(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("anabasis-b",[{"sp": "HDR", "t": "Βιβλίον αʹ", "st": "1.1.1"}, {"sp": "N", "t": "Δαρείου καὶ Παρυσάτιδος γίγνονται παῖδες δύο, πρεσβύτερος μὲν Ἀρταξέρξης, νεώτερος δὲ Κῦρος· ἐπεὶ δὲ ἠσθένει Δαρεῖος καὶ ὑπώπτευε τελευτὴν τοῦ βίου, ἐβούλετο τὼ παῖδε ἀμφοτέρω παρεῖναι.", "st": "1.1.1"}, {"sp": "N", "t": "ὁ μὲν οὖν πρεσβύτερος παρὼν ἐτύγχανε· Κῦρον δὲ μεταπέμπεται ἀπὸ τῆς ἀρχῆς ἧς αὐτὸν σατράπην ἐποίησε, καὶ στρατηγὸν δὲ αὐτὸν ἀπέδειξε πάντων ὅσοι ἐς Καστωλοῦ πεδίον ἁθροίζονται. ἀναβαίνει οὖν ὁ Κῦρος λαβὼν Τισσαφέρνην ὡς φίλον, καὶ τῶν Ἑλλήνων ἔχων ὁπλίτας ἀνέβη τριακοσίους, ἄρχοντα δὲ αὐτῶν Ξενίαν Παρράσιον.", "st": "1.1.2"}, {"sp": "N", "t": "ἐπεὶ δὲ ἐτελεύτησε Δαρεῖος καὶ κατέστη εἰς τὴν βασιλείαν Ἀρταξέρξης, Τισσαφέρνης διαβάλλει τὸν Κῦρον πρὸς τὸν ἀδελφὸν ὡς ἐπιβουλεύοι αὐτῶι. ὁ δὲ πείθεται καὶ συλλαμβάνει Κῦρον ὡς ἀποκτενῶν· ἡ δὲ μήτηρ ἐξαιτησαμένη αὐτὸν ἀποπέμπει πάλιν ἐπὶ τὴν ἀρχήν.", "st": "1.1.3"}, {"sp": "N", "t": "ὁ δ᾽ ὡς ἀπῆλθε κινδυνεύσας καὶ ἀτιμασθείς, βουλεύεται ὅπως μήποτε ἔτι ἔσται ἐπὶ τῶι ἀδελφῶι, ἀλλά, ἢν δύνηται, βασιλεύσει ἀντ᾽ ἐκείνου. Παρύσατις μὲν δὴ ἡ μήτηρ ὑπῆρχε τῶι Κύρωι, φιλοῦσα αὐτὸν μᾶλλον ἢ τὸν βασιλεύοντα Ἀρταξέρξην.", "st": "1.1.4"}, {"sp": "N", "t": "ὅστις δ᾽ ἀφικνεῖτο τῶν παρὰ βασιλέως πρὸς αὐτὸν πάντας οὕτω διατιθεὶς ἀπεπέμπετο ὥστε αὐτῶι μᾶλλον φίλους εἶναι ἢ βασιλεῖ. καὶ τῶν παρ᾽ ἑαυτῶι δὲ βαρβάρων ἐπεμελεῖτο ὡς πολεμεῖν τε ἱκανοὶ εἴησαν καὶ εὐνοϊκῶς ἔχοιεν αὐτῶι.", "st": "1.1.5"}, {"sp": "N", "t": "τὴν δὲ Ἑλληνικὴν δύναμιν ἥθροιζεν ὡς μάλιστα ἐδύνατο ἐπικρυπτόμενος, ὅπως ὅτι ἀπαρασκευότατον λάβοι βασιλέα. ὧδε οὖν ἐποιεῖτο τὴν συλλογήν. ὁπόσας εἶχε φυλακὰς ἐν ταῖς πόλεσι παρήγγειλε τοῖς φρουράρχοις ἑκάστοις λαμβάνειν ἄνδρας Πελοποννησίους ὅτι πλείστους καὶ βελτίστους, ὡς ἐπιβουλεύοντος Τισσαφέρνους ταῖς πόλεσι. καὶ γὰρ ἦσαν αἱ Ἰωνικαὶ πόλεις Τισσαφέρνους τὸ ἀρχαῖον ἐκ βασιλέως δεδομέναι, τότε δὲ ἀφειστήκεσαν πρὸς Κῦρον πᾶσαι πλὴν Μιλήτου·", "st": "1.1.6"}, {"sp": "N", "t": "ἐν Μιλήτωι δὲ Τισσαφέρνης προαισθόμενος τὰ αὐτὰ ταῦτα βουλευομένους ἀποστῆναι πρὸς Κῦρον, τοὺς μὲν αὐτῶν ἀπέκτεινε τοὺς δ᾽ ἐξέβαλεν. ὁ δὲ Κῦρος ὑπολαβὼν τοὺς φεύγοντας συλλέξας στράτευμα ἐπολιόρκει Μίλητον καὶ κατὰ γῆν καὶ κατὰ θάλατταν καὶ ἐπειρᾶτο κατάγειν τοὺς ἐκπεπτωκότας. καὶ αὕτη αὖ ἄλλη πρόφασις ἦν αὐτῶι τοῦ ἁθροίζειν στράτευμα.", "st": "1.1.7"}, {"sp": "N", "t": "πρὸς δὲ βασιλέα πέμπων ἠξίου ἀδελφὸς ὢν αὐτοῦ δοθῆναι οἷ ταύτας τὰς πόλεις μᾶλλον ἢ Τισσαφέρνην ἄρχειν αὐτῶν, καὶ ἡ μήτηρ συνέπραττεν αὐτῶι ταῦτα· ὥστε βασιλεὺς τὴν μὲν πρὸς ἑαυτὸν ἐπιβουλὴν οὐκ ἠισθάνετο, Τισσαφέρνει δ᾽ ἐνόμιζε πολεμοῦντα αὐτὸν ἀμφὶ τὰ στρατεύματα δαπανᾶν· ὥστε οὐδὲν ἤχθετο αὐτῶν πολεμούντων. καὶ γὰρ ὁ Κῦρος ἀπέπεμπε τοὺς γιγνομένους δασμοὺς βασιλεῖ ἐκ τῶν πόλεων ὧν Τισσαφέρνους ἐτύγχανεν ἔχων.", "st": "1.1.8"}, {"sp": "N", "t": "ἄλλο δὲ στράτευμα αὐτῶι συνελέγετο ἐν Χερρονήσωι τῆι κατ᾽ ἀντιπέρας Ἀβύδου τόνδε τὸν τρόπον. Κλέαρχος Λακεδαιμόνιος φυγὰς ἦν· τούτωι συγγενόμενος ὁ Κῦρος ἠγάσθη τε αὐτὸν καὶ δίδωσιν αὐτῶι μυρίους δαρεικούς. ὁ δὲ λαβὼν τὸ χρυσίον στράτευμα συνέλεξεν ἀπὸ τούτων τῶν χρημάτων καὶ ἐπολέμει ἐκ Χερρονήσου ὁρμώμενος τοῖς Θραιξὶ τοῖς ὑπὲρ Ἑλλήσποντον οἰκοῦσι καὶ ὠφέλει τοὺς Ἕλληνας· ὥστε καὶ χρήματα συνεβάλλοντο αὐτῶι εἰς τὴν τροφὴν τῶν στρατιωτῶν αἱ Ἑλλησποντιακαὶ πόλεις ἑκοῦσαι. τοῦτο δ᾽ αὖ οὕτω τρεφόμενον ἐλάνθανεν αὐτῶι τὸ στράτευμα.", "st": "1.1.9"}, {"sp": "N", "t": "Ἀρίστιππος δὲ ὁ Θετταλὸς ξένος ὢν ἐτύγχανεν αὐτῶι, καὶ πιεζόμενος ὑπὸ τῶν οἴκοι ἀντιστασιωτῶν ἔρχεται πρὸς τὸν Κῦρον καὶ αἰτεῖ αὐτὸν εἰς δισχιλίους ξένους καὶ τριῶν μηνῶν μισθόν, ὡς οὕτως περιγενόμενος ἂν τῶν ἀντιστασιωτῶν. ὁ δὲ Κῦρος δίδωσιν αὐτῶι εἰς τετρακισχιλίους καὶ ἓξ μηνῶν μισθόν, καὶ δεῖται αὐτοῦ μὴ πρόσθεν καταλῦσαι πρὸς τοὺς ἀντιστασιώτας πρὶν ἂν αὐτῶι συμβουλεύσηται. οὕτω δὲ αὖ τὸ ἐν Θετταλίαι ἐλάνθανεν αὐτῶι τρεφόμενον στράτευμα.", "st": "1.1.10"}, {"sp": "N", "t": "Πρόξενον δὲ τὸν Βοιώτιον ξένον ὄντα ἐκέλευσε λαβόντα ἄνδρας ὅτι πλείστους παραγενέσθαι, ὡς ἐς Πισίδας βουλόμενος στρατεύεσθαι, ὡς πράγματα παρεχόντων τῶν Πισιδῶν τῆι ἑαυτοῦ χώραι. Σοφαίνετον δὲ τὸν Στυμφάλιον καὶ Σωκράτην τὸν Ἀχαιόν, ξένους ὄντας καὶ τούτους, ἐκέλευσεν ἄνδρας λαβόντας ἐλθεῖν ὅτι πλείστους, ὡς πολεμήσων Τισσαφέρνει σὺν τοῖς φυγάσι τοῖς Μιλησίων. καὶ ἐποίουν οὕτως οὗτοι.", "st": "1.1.11"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἐδόκει ἤδη πορεύεσθαι αὐτῶι ἄνω, τὴν μὲν πρόφασιν ἐποιεῖτο ὡς Πισίδας βουλόμενος ἐκβαλεῖν παντάπασιν ἐκ τῆς χώρας· καὶ ἁθροίζει ὡς ἐπὶ τούτους τό τε βαρβαρικὸν καὶ τὸ Ἑλληνικόν. ἐνταῦθα καὶ παραγγέλλει τῶι τε Κλεάρχωι λαβόντι ἥκειν ὅσον ἦν αὐτῶι στράτευμα καὶ τῶι Ἀριστίππωι συναλλαγέντι πρὸς τοὺς οἴκοι ἀποπέμψαι πρὸς ἑαυτὸν ὃ εἶχε στράτευμα· καὶ Ξενίαι τῶι Ἀρκάδι, ὃς αὐτῶι προειστήκει τοῦ ἐν ταῖς πόλεσι ξενικοῦ, ἥκειν παραγγέλλει λαβόντα τοὺς ἄλλους πλὴν ὁπόσοι ἱκανοὶ ἦσαν τὰς ἀκροπόλεις φυλάττειν.", "st": "1.2.1"}, {"sp": "N", "t": "ἐκάλεσε δὲ καὶ τοὺς Μίλητον πολιορκοῦντας, καὶ τοὺς φυγάδας ἐκέλευσε σὺν αὐτῶι στρατεύεσθαι, ὑποσχόμενος αὐτοῖς, εἰ καλῶς καταπράξειεν ἐφ᾽ ἃ ἐστρατεύετο, μὴ πρόσθεν παύσεσθαι πρὶν αὐτοὺς καταγάγοι οἴκαδε. οἱ δὲ ἡδέως ἐπείθοντο· ἐπίστευον γὰρ αὐτῶι· καὶ λαβόντες τὰ ὅπλα παρῆσαν εἰς Σάρδεις.", "st": "1.2.2"}, {"sp": "N", "t": "Ξενίας μὲν δὴ τοὺς ἐκ τῶν πόλεων λαβὼν παρεγένετο εἰς Σάρδεις ὁπλίτας εἰς τετρακισχιλίους, Πρόξενος δὲ παρῆν ἔχων ὁπλίτας μὲν εἰς πεντακοσίους καὶ χιλίους, γυμνῆτας δὲ πεντακοσίους, Σοφαίνετος δὲ ὁ Στυμφάλιος ὁπλίτας ἔχων χιλίους, Σωκράτης δὲ ὁ Ἀχαιὸς ὁπλίτας ἔχων ὡς πεντακοσίους, Πασίων δὲ ὁ Μεγαρεὺς τριακοσίους μὲν ὁπλίτας, τριακοσίους δὲ πελταστὰς ἔχων παρεγένετο· ἦν δὲ καὶ οὗτος καὶ ὁ Σωκράτης τῶν ἀμφὶ Μίλητον στρατευομένων.", "st": "1.2.3"}, {"sp": "N", "t": "οὗτοι μὲν εἰς Σάρδεις αὐτῶι ἀφίκοντο. Τισσαφέρνης δὲ κατανοήσας ταῦτα, καὶ μείζονα ἡγησάμενος εἶναι ἢ ὡς ἐπὶ Πισίδας τὴν παρασκευήν, πορεύεται ὡς βασιλέα ἧι ἐδύνατο τάχιστα ἱππέας ἔχων ὡς πεντακοσίους.", "st": "1.2.4"}, {"sp": "N", "t": "καὶ βασιλεὺς μὲν δὴ ἐπεὶ ἤκουσε Τισσαφέρνους τὸν Κύρου στόλον, ἀντιπαρεσκευάζετο. Κῦρος δὲ ἔχων οὓς εἴρηκα ὡρμᾶτο ἀπὸ Σάρδεων· καὶ ἐξελαύνει διὰ τῆς Λυδίας σταθμοὺς τρεῖς παρασάγγας εἴκοσι καὶ δύο ἐπὶ τὸν Μαίανδρον ποταμόν. τούτου τὸ εὖρος δύο πλέθρα· γέφυρα δὲ ἐπῆν ἐζευγμένη πλοίοις.", "st": "1.2.5"}, {"sp": "N", "t": "τοῦτον διαβὰς ἐξελαύνει διὰ Φρυγίας σταθμὸν ἕνα παρασάγγας ὀκτὼ εἰς Κολοσσάς, πόλιν οἰκουμένην καὶ εὐδαίμονα καὶ μεγάλην. ἐνταῦθα ἔμεινεν ἡμέρας ἑπτά· καὶ ἧκε Μένων ὁ Θετταλὸς ὁπλίτας ἔχων χιλίους καὶ πελταστὰς πεντακοσίους, Δόλοπας καὶ Αἰνιᾶνας καὶ Ὀλυνθίους.", "st": "1.2.6"}, {"sp": "N", "t": "ἐντεῦθεν ἐξελαύνει σταθμοὺς τρεῖς παρασάγγας εἴκοσιν εἰς Κελαινάς, τῆς Φρυγίας πόλιν οἰκουμένην, μεγάλην καὶ εὐδαίμονα. ἐνταῦθα Κύρωι βασίλεια ἦν καὶ παράδεισος μέγας ἀγρίων θηρίων πλήρης, ἃ ἐκεῖνος ἐθήρευεν ἀπὸ ἵππου, ὁπότε γυμνάσαι βούλοιτο ἑαυτόν τε καὶ τοὺς ἵππους. διὰ μέσου δὲ τοῦ παραδείσου ῥεῖ ὁ Μαίανδρος ποταμός· αἱ δὲ πηγαὶ αὐτοῦ εἰσιν ἐκ τῶν βασιλείων· ῥεῖ δὲ καὶ διὰ τῆς Κελαινῶν πόλεως.", "st": "1.2.7"}, {"sp": "N", "t": "ἔστι δὲ καὶ μεγάλου βασιλέως βασίλεια ἐν Κελαιναῖς ἐρυμνὰ ἐπὶ ταῖς πηγαῖς τοῦ Μαρσύου ποταμοῦ ὑπὸ τῆι ἀκροπόλει· ῥεῖ δὲ καὶ οὗτος διὰ τῆς πόλεως καὶ ἐμβάλλει εἰς τὸν Μαίανδρον· τοῦ δὲ Μαρσύου τὸ εὖρός ἐστιν εἴκοσι καὶ πέντε ποδῶν. ἐνταῦθα λέγεται Ἀπόλλων ἐκδεῖραι Μαρσύαν νικήσας ἐρίζοντά οἱ περὶ σοφίας, καὶ τὸ δέρμα κρεμάσαι ἐν τῶι ἄντρωι ὅθεν αἱ πηγαί· διὰ δὲ τοῦτο ὁ ποταμὸς καλεῖται Μαρσύας.", "st": "1.2.8"}, {"sp": "N", "t": "ἐνταῦθα Ξέρξης, ὅτε ἐκ τῆς Ἑλλάδος ἡττηθεὶς τῆι μάχηι ἀπεχώρει, λέγεται οἰκοδομῆσαι ταῦτά τε τὰ βασίλεια καὶ τὴν Κελαινῶν ἀκρόπολιν. ἐνταῦθα ἔμεινε Κῦρος ἡμέρας τριάκοντα· καὶ ἧκε Κλέαρχος ὁ Λακεδαιμόνιος φυγὰς ἔχων ὁπλίτας χιλίους καὶ πελταστὰς Θρᾶικας ὀκτακοσίους καὶ τοξότας Κρῆτας διακοσίους. ἅμα δὲ καὶ Σῶσις παρῆν ὁ Συρακόσιος ἔχων ὁπλίτας τριακοσίους, καὶ Σοφαίνετος Ἀρκάδας ἔχων ὁπλίτας χιλίους. καὶ ἐνταῦθα Κῦρος ἐξέτασιν καὶ ἀριθμὸν τῶν Ἑλλήνων ἐποίησεν ἐν τῶι παραδείσωι, καὶ ἐγένοντο οἱ σύμπαντες ὁπλῖται μὲν μύριοι χίλιοι, πελτασταὶ δὲ ἀμφὶ τοὺς δισχιλίους.", "st": "1.2.9"}, {"sp": "N", "t": "ἐντεῦθεν ἐξελαύνει σταθμοὺς δύο παρασάγγας δέκα εἰς Πέλτας, πόλιν οἰκουμένην. ἐνταῦθ᾽ ἔμεινεν ἡμέρας τρεῖς· ἐν αἷς Ξενίας ὁ Ἀρκὰς τὰ Λύκαια ἔθυσε καὶ ἀγῶνα ἔθηκε· τὰ δὲ ἆθλα ἦσαν στλεγγίδες χρυσαῖ· ἐθεώρει δὲ τὸν ἀγῶνα καὶ Κῦρος.", "st": "1.2.10"}, {"sp": "N", "t": "ἐντεῦθεν ἐξελαύνει σταθμοὺς δύο παρασάγγας δώδεκα ἐς Κεράμων ἀγοράν, πόλιν οἰκουμένην, ἐσχάτην πρὸς τῆι Μυσίαι χώραι. ἐντεῦθεν ἐξελαύνει σταθμοὺς τρεῖς παρασάγγας τριάκοντα εἰς Καΰστρου πεδίον, πόλιν οἰκουμένην. ἐνταῦθ᾽ ἔμεινεν ἡμέρας πέντε· καὶ τοῖς στρατιώταις ὠφείλετο μισθὸς πλέον ἢ τριῶν μηνῶν, καὶ πολλάκις ἰόντες ἐπὶ τὰς θύρας ἀπήιτουν. ὁ δὲ ἐλπίδας λέγων διῆγε καὶ δῆλος ἦν ἀνιώμενος· οὐ γὰρ ἦν πρὸς τοῦ Κύρου τρόπου ἔχοντα μὴ ἀποδιδόναι.", "st": "1.2.11"}, {"sp": "N", "t": "ἐνταῦθα ἀφικνεῖται Ἐπύαξα ἡ Συεννέσιος γυνὴ τοῦ Κιλίκων βασιλέως παρὰ Κῦρον· καὶ ἐλέγετο Κύρωι δοῦναι χρήματα πολλά. τῆι δ᾽ οὖν στρατιᾶι τότε ἀπέδωκε Κῦρος μισθὸν τεττάρων μηνῶν. εἶχε δὲ ἡ Κίλισσα φυλακὴν [καὶ φύλακας] περὶ αὑτὴν Κίλικας καὶ Ἀσπενδίους· ἐλέγετο δὲ καὶ συγγενέσθαι Κῦρον τῆι Κιλίσσηι.", "st": "1.2.12"}, {"sp": "N", "t": "ἐντεῦθεν δὲ ἐλαύνει σταθμοὺς δύο παρασάγγας δέκα εἰς Θύμβριον, πόλιν οἰκουμένην. ἐνταῦθα ἦν παρὰ τὴν ὁδὸν κρήνη ἡ Μίδου καλουμένη τοῦ Φρυγῶν βασιλέως, ἐφ᾽ ἧι λέγεται Μίδας τὸν Σάτυρον θηρεῦσαι οἴνωι κεράσας αὐτήν.", "st": "1.2.13"}, {"sp": "N", "t": "ἐντεῦθεν ἐξελαύνει σταθμοὺς δύο παρασάγγας δέκα εἰς Τυριάειον, πόλιν οἰκουμένην. ἐνταῦθα ἔμεινεν ἡμέρας τρεῖς. καὶ λέγεται δεηθῆναι ἡ Κίλισσα Κύρου ἐπιδεῖξαι τὸ στράτευμα αὐτῆι· βουλόμενος οὖν ἐπιδεῖξαι ἐξέτασιν ποιεῖται ἐν τῶι πεδίωι τῶν Ἑλλήνων καὶ τῶν βαρβάρων.", "st": "1.2.14"}, {"sp": "N", "t": "ἐκέλευσε δὲ τοὺς Ἕλληνας ὡς νόμος αὐτοῖς εἰς μάχην οὕτω ταχθῆναι καὶ στῆναι, συντάξαι δ᾽ ἕκαστον τοὺς ἑαυτοῦ. ἐτάχθησαν οὖν ἐπὶ τεττάρων· εἶχε δὲ τὸ μὲν δεξιὸν Μένων καὶ οἱ σὺν αὐτῶι, τὸ δὲ εὐώνυμον Κλέαρχος καὶ οἱ ἐκείνου, τὸ δὲ μέσον οἱ ἄλλοι στρατηγοί.", "st": "1.2.15"}, {"sp": "N", "t": "ἐθεώρει οὖν ὁ Κῦρος πρῶτον μὲν τοὺς βαρβάρους· οἱ δὲ παρήλαυνον τεταγμένοι κατὰ ἴλας καὶ κατὰ τάξεις· εἶτα δὲ τοὺς Ἕλληνας, παρελαύνων ἐφ᾽ ἅρματος καὶ ἡ Κίλισσα ἐφ᾽ ἁρμαμάξης. εἶχον δὲ πάντες κράνη χαλκᾶ καὶ χιτῶνας φοινικοῦς καὶ κνημῖδας καὶ τὰς ἀσπίδας ἐκκεκαλυμμένας.", "st": "1.2.16"}, {"sp": "N", "t": "ἐπειδὴ δὲ πάντας παρήλασε, στήσας τὸ ἅρμα πρὸ τῆς φάλαγγος μέσης, πέμψας Πίγρητα τὸν ἑρμηνέα παρὰ τοὺς στρατηγοὺς τῶν Ἑλλήνων ἐκέλευσε προβαλέσθαι τὰ ὅπλα καὶ ἐπιχωρῆσαι ὅλην τὴν φάλαγγα. οἱ δὲ ταῦτα προεῖπον τοῖς στρατιώταις· καὶ ἐπεὶ ἐσάλπιγξε, προβαλόμενοι τὰ ὅπλα ἐπῆισαν. ἐκ δὲ τούτου θᾶττον προϊόντων σὺν κραυγῆι ἀπὸ τοῦ αὐτομάτου δρόμος ἐγένετο τοῖς στρατιώταις ἐπὶ τὰς σκηνάς,", "st": "1.2.17"}, {"sp": "N", "t": "τῶν δὲ βαρβάρων φόβος πολύς, καὶ ἥ τε Κίλισσα ἔφυγεν ἐπὶ τῆς ἁρμαμάξης καὶ οἱ ἐκ τῆς ἀγορᾶς καταλιπόντες τὰ ὤνια ἔφυγον. οἱ δὲ Ἕλληνες σὺν γέλωτι ἐπὶ τὰς σκηνὰς ἦλθον. ἡ δὲ Κίλισσα ἰδοῦσα τὴν λαμπρότητα καὶ τὴν τάξιν τοῦ στρατεύματος ἐθαύμασε. Κῦρος δὲ ἥσθη τὸν ἐκ τῶν Ἑλλήνων εἰς τοὺς βαρβάρους φόβον ἰδών.", "st": "1.2.18"}, {"sp": "N", "t": "ἐντεῦθεν ἐξελαύνει σταθμοὺς τρεῖς παρασάγγας εἴκοσιν εἰς Ἰκόνιον, τῆς Φρυγίας πόλιν ἐσχάτην. ἐνταῦθα ἔμεινε τρεῖς ἡμέρας. ἐντεῦθεν ἐξελαύνει διὰ τῆς Λυκαονίας σταθμοὺς πέντε παρασάγγας τριάκοντα. ταύτην τὴν χώραν ἐπέτρεψε διαρπάσαι τοῖς Ἕλλησιν ὡς πολεμίαν οὖσαν.", "st": "1.2.19"}, {"sp": "N", "t": "ἐντεῦθεν Κῦρος τὴν Κίλισσαν εἰς τὴν Κιλικίαν ἀποπέμπει τὴν ταχίστην ὁδόν· καὶ συνέπεμψεν αὐτῆι στρατιώτας οὓς Μένων εἶχε καὶ αὐτόν. Κῦρος δὲ μετὰ τῶν ἄλλων ἐξελαύνει διὰ Καππαδοκίας σταθμοὺς τέτταρας παρασάγγας εἴκοσι καὶ πέντε πρὸς Δάναν, πόλιν οἰκουμένην, μεγάλην καὶ εὐδαίμονα. ἐνταῦθα ἔμειναν ἡμέρας τρεῖς· ἐν ὧι Κῦρος ἀπέκτεινεν ἄνδρα Πέρσην Μεγαφέρνην, φοινικιστὴν βασίλειον, καὶ ἕτερόν τινα τῶν ὑπάρχων δυνάστην, αἰτιασάμενος ἐπιβουλεύειν αὐτῶι.", "st": "1.2.20"}, {"sp": "N", "t": "ἐντεῦθεν ἐπειρῶντο εἰσβάλλειν εἰς τὴν Κιλικίαν· ἡ δὲ εἰσβολὴ ἦν ὁδὸς ἁμαξιτὸς ὀρθία ἰσχυρῶς καὶ ἀμήχανος εἰσελθεῖν στρατεύματι, εἴ τις ἐκώλυεν. ἐλέγετο δὲ καὶ Συέννεσις εἶναι ἐπὶ τῶν ἄκρων φυλάττων τὴν εἰσβολήν· διὸ ἔμεινεν ἡμέραν ἐν τῶι πεδίωι. τῆι δ᾽ ὑστεραίαι ἧκεν ἄγγελος λέγων ὅτι λελοιπὼς εἴη Συέννεσις τὰ ἄκρα, ἐπεὶ ἤισθετο ὅτι τὸ Μένωνος στράτευμα ἤδη ἐν Κιλικίαι ἦν εἴσω τῶν ὀρέων, καὶ ὅτι τριήρεις ἤκουε περιπλεούσας ἀπ᾽ Ἰωνίας εἰς Κιλικίαν Ταμὼν ἔχοντα τὰς Λακεδαιμονίων καὶ αὐτοῦ Κύρου.", "st": "1.2.21"}, {"sp": "N", "t": "Κῦρος δ᾽ οὖν ἀνέβη ἐπὶ τὰ ὄρη οὐδενὸς κωλύοντος, καὶ εἶδε τὰς σκηνὰς οὗ οἱ Κίλικες ἐφύλαττον. ἐντεῦθεν δὲ κατέβαινεν εἰς πεδίον μέγα καὶ καλόν, ἐπίρρυτον, καὶ δένδρων παντοδαπῶν σύμπλεων καὶ ἀμπέλων· πολὺ δὲ καὶ σήσαμον καὶ μελίνην καὶ κέγχρον καὶ πυροὺς καὶ κριθὰς φέρει. ὄρος δ᾽ αὐτὸ περιεῖχεν ὀχυρὸν καὶ ὑψηλὸν πάντηι ἐκ θαλάττης εἰς θάλατταν.", "st": "1.2.22"}, {"sp": "N", "t": "καταβὰς δὲ διὰ τούτου τοῦ πεδίου ἤλασε σταθμοὺς τέτταρας παρασάγγας πέντε καὶ εἴκοσιν εἰς Ταρσούς, τῆς Κιλικίας πόλιν μεγάλην καὶ εὐδαίμονα, οὗ ἦν τὰ Συεννέσιος βασίλεια τοῦ Κιλίκων βασιλέως· διὰ μέσου δὲ τῆς πόλεως ῥεῖ ποταμὸς Κύδνος ὄνομα, εὖρος δύο πλέθρων.", "st": "1.2.23"}, {"sp": "N", "t": "ταύτην τὴν πόλιν ἐξέλιπον οἱ ἐνοικοῦντες μετὰ Συεννέσιος εἰς χωρίον ὀχυρὸν ἐπὶ τὰ ὄρη πλὴν οἱ τὰ καπηλεῖα ἔχοντες· ἔμειναν δὲ καὶ οἱ παρὰ τὴν θάλατταν οἰκοῦντες ἐν Σόλοις καὶ ἐν Ἰσσοῖς.", "st": "1.2.24"}, {"sp": "N", "t": "Ἐπύαξα δὲ ἡ Συεννέσιος γυνὴ προτέρα Κύρου πέντε ἡμέραις εἰς Ταρσοὺς ἀφίκετο· ἐν δὲ τῆι ὑπερβολῆι τῶν ὀρέων τῆι εἰς τὸ πεδίον δύο λόχοι τοῦ Μένωνος στρατεύματος ἀπώλοντο· οἱ μὲν ἔφασαν ἁρπάζοντάς τι κατακοπῆναι ὑπὸ τῶν Κιλίκων, οἱ δὲ ὑπολειφθέντας καὶ οὐ δυναμένους εὑρεῖν τὸ ἄλλο στράτευμα οὐδὲ τὰς ὁδοὺς εἶτα πλανωμένους ἀπολέσθαι· ἦσαν δ᾽ οὖν οὗτοι ἑκατὸν ὁπλῖται.", "st": "1.2.25"}, {"sp": "N", "t": "οἱ δ᾽ ἄλλοι ἐπεὶ ἧκον, τήν τε πόλιν τοὺς Ταρσοὺς διήρπασαν, διὰ τὸν ὄλεθρον τῶν συστρατιωτῶν ὀργιζόμενοι, καὶ τὰ βασίλεια τὰ ἐν αὐτῆι. Κῦρος δ᾽ ἐπεὶ εἰσήλασεν εἰς τὴν πόλιν, μετεπέμπετο τὸν Συέννεσιν πρὸς ἑαυτόν· ὁ δ᾽ οὔτε πρότερον οὐδενί πω κρείττονι ἑαυτοῦ εἰς χεῖρας ἐλθεῖν ἔφη οὔτε τότε Κύρωι ἰέναι ἤθελε, πρὶν ἡ γυνὴ αὐτὸν ἔπεισε καὶ πίστεις ἔλαβε.", "st": "1.2.26"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα ἐπεὶ συνεγένοντο ἀλλήλοις, Συέννεσις μὲν ἔδωκε Κύρωι χρήματα πολλὰ εἰς τὴν στρατιάν, Κῦρος δὲ ἐκείνωι δῶρα ἃ νομίζεται παρὰ βασιλεῖ τίμια, ἵππον χρυσοχάλινον καὶ στρεπτὸν χρυσοῦν καὶ ψέλια καὶ ἀκινάκην χρυσοῦν καὶ στολὴν Περσικήν, καὶ τὴν χώραν μηκέτι διαρπάζεσθαι· τὰ δὲ ἡρπασμένα ἀνδράποδα, ἤν που ἐντυγχάνωσιν, ἀπολαμβάνειν.", "st": "1.2.27"}, {"sp": "N", "t": "ἐνταῦθα ἔμεινεν ὁ Κῦρος καὶ ἡ στρατιὰ ἡμέρας εἴκοσιν· οἱ γὰρ στρατιῶται οὐκ ἔφασαν ἰέναι τοῦ πρόσω· ὑπώπτευον γὰρ ἤδη ἐπὶ βασιλέα ἰέναι· μισθωθῆναι δὲ οὐκ ἐπὶ τούτωι ἔφασαν. πρῶτος δὲ Κλέαρχος τοὺς αὑτοῦ στρατιώτας ἐβιάζετο ἰέναι· οἱ δ᾽ αὐτόν τε ἔβαλλον καὶ τὰ ὑποζύγια τὰ ἐκείνου, ἐπεὶ ἄρξαιντο προϊέναι.", "st": "1.3.1"}, {"sp": "N", "t": "Κλέαρχος δὲ τότε μὲν μικρὸν ἐξέφυγε μὴ καταπετρωθῆναι, ὕστερον δ᾽ ἐπεὶ ἔγνω ὅτι οὐ δυνήσεται βιάσασθαι, συνήγαγεν ἐκκλησίαν τῶν αὑτοῦ στρατιωτῶν. καὶ πρῶτον μὲν ἐδάκρυε πολὺν χρόνον ἑστώς· οἱ δὲ ὁρῶντες ἐθαύμαζον καὶ ἐσιώπων· εἶτα δὲ ἔλεξε τοιάδε.", "st": "1.3.2"}, {"sp": "N", "t": "«ἄνδρες στρατιῶται, μὴ θαυμάζετε ὅτι χαλεπῶς φέρω τοῖς παροῦσι πράγμασιν. ἐμοὶ γὰρ ξένος Κῦρος ἐγένετο καί με φεύγοντα ἐκ τῆς πατρίδος τά τε ἄλλα ἐτίμησε καὶ μυρίους ἔδωκε δαρεικούς· οὓς ἐγὼ λαβὼν οὐκ εἰς τὸ ἴδιον κατεθέμην ἐμοὶ οὐδὲ καθηδυπάθησα, ἀλλ᾽ εἰς ὑμᾶς ἐδαπάνων.", "st": "1.3.3"}, {"sp": "N", "t": "καὶ πρῶτον μὲν πρὸς τοὺς Θρᾶικας ἐπολέμησα, καὶ ὑπὲρ τῆς Ἑλλάδος ἐτιμωρούμην μεθ᾽ ὑμῶν, ἐκ τῆς Χερρονήσου αὐτοὺς ἐξελαύνων βουλομένους ἀφαιρεῖσθαι τοὺς ἐνοικοῦντας Ἕλληνας τὴν γῆν. ἐπειδὴ δὲ Κῦρος ἐκάλει, λαβὼν ὑμᾶς ἐπορευόμην, ἵνα εἴ τι δέοιτο ὠφελοίην αὐτὸν ἀνθ᾽ ὧν εὖ ἔπαθον ὑπ᾽ ἐκείνου.", "st": "1.3.4"}, {"sp": "N", "t": "ἐπεὶ δὲ ὑμεῖς οὐ βούλεσθε συμπορεύεσθαι, ἀνάγκη δή μοι ἢ ὑμᾶς προδόντα τῆι Κύρου φιλίαι χρῆσθαι ἢ πρὸς ἐκεῖνον ψευσάμενον μεθ᾽ ὑμῶν εἶναι. εἰ μὲν δὴ δίκαια ποιήσω οὐκ οἶδα, αἱρήσομαι δ᾽ οὖν ὑμᾶς καὶ σὺν ὑμῖν ὅ τι ἂν δέηι πείσομαι. καὶ οὔποτε ἐρεῖ οὐδεὶς ὡς ἐγὼ Ἕλληνας ἀγαγὼν εἰς τοὺς βαρβάρους, προδοὺς τοὺς Ἕλληνας τὴν τῶν βαρβάρων φιλίαν εἱλόμην,", "st": "1.3.5"}, {"sp": "N", "t": "ἀλλ᾽ ἐπεὶ ὑμεῖς ἐμοὶ οὐ θέλετε πείθεσθαι, ἐγὼ σὺν ὑμῖν ἕψομαι καὶ ὅ τι ἂν δέηι πείσομαι. νομίζω γὰρ ὑμᾶς ἐμοὶ εἶναι καὶ πατρίδα καὶ φίλους καὶ συμμάχους, καὶ σὺν ὑμῖν μὲν ἂν οἶμαι εἶναι τίμιος ὅπου ἂν ὦ, ὑμῶν δὲ ἔρημος ὢν οὐκ ἂν ἱκανὸς οἶμαι εἶναι οὔτ᾽ ἂν φίλον ὠφελῆσαι οὔτ᾽ ἂν ἐχθρὸν ἀλέξασθαι. ὡς ἐμοῦ οὖν ἰόντος ὅπηι ἂν καὶ ὑμεῖς οὕτω τὴν γνώμην ἔχετε.»", "st": "1.3.6"}, {"sp": "N", "t": "ταῦτα εἶπεν· οἱ δὲ στρατιῶται οἵ τε αὐτοῦ ἐκείνου καὶ οἱ ἄλλοι ταῦτα ἀκούσαντες ὅτι οὐ φαίη παρὰ βασιλέα πορεύεσθαι ἐπήινεσαν· παρὰ δὲ Ξενίου καὶ Πασίωνος πλείους ἢ δισχίλιοι λαβόντες τὰ ὅπλα καὶ τὰ σκευοφόρα ἐστρατοπεδεύσαντο παρὰ Κλεάρχωι.", "st": "1.3.7"}, {"sp": "N", "t": "Κῦρος δὲ τούτοις ἀπορῶν τε καὶ λυπούμενος μετεπέμπετο τὸν Κλέαρχον· ὁ δὲ ἰέναι μὲν οὐκ ἤθελε, λάθραι δὲ τῶν στρατιωτῶν πέμπων αὐτῶι ἄγγελον ἔλεγε θαρρεῖν ὡς καταστησομένων τούτων εἰς τὸ δέον. μεταπέμπεσθαι δ᾽ ἐκέλευεν αὐτόν· αὐτὸς δ᾽ οὐκ ἔφη ἰέναι.", "st": "1.3.8"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα συναγαγὼν τούς θ᾽ ἑαυτοῦ στρατιώτας καὶ τοὺς προσελθόντας αὐτῶι καὶ τῶν ἄλλων τὸν βουλόμενον, ἔλεξε τοιάδε. «ἄνδρες στρατιῶται, τὰ μὲν δὴ Κύρου δῆλον ὅτι οὕτως ἔχει πρὸς ἡμᾶς ὥσπερ τὰ ἡμέτερα πρὸς ἐκεῖνον· οὔτε γὰρ ἡμεῖς ἐκείνου ἔτι στρατιῶται, ἐπεί γε οὐ συνεπόμεθα αὐτῶι, οὔτε ἐκεῖνος ἔτι ἡμῖν μισθοδότης.", "st": "1.3.9"}, {"sp": "N", "t": "ὅτι μέντοι ἀδικεῖσθαι νομίζει ὑφ᾽ ἡμῶν οἶδα· ὥστε καὶ μεταπεμπομένου αὐτοῦ οὐκ ἐθέλω ἐλθεῖν, τὸ μὲν μέγιστον αἰσχυνόμενος ὅτι σύνοιδα ἐμαυτῶι πάντα ἐψευσμένος αὐτόν, ἔπειτα καὶ δεδιὼς μὴ λαβών με δίκην ἐπιθῆι ὧν νομίζει ὑπ᾽ ἐμοῦ ἠδικῆσθαι.", "st": "1.3.10"}, {"sp": "N", "t": "ἐμοὶ οὖν δοκεῖ οὐχ ὥρα εἶναι ἡμῖν καθεύδειν οὐδ᾽ ἀμελεῖν ἡμῶν αὐτῶν, ἀλλὰ βουλεύεσθαι ὅ τι χρὴ ποιεῖν ἐκ τούτων. καὶ ἕως γε μένομεν αὐτοῦ σκεπτέον μοι δοκεῖ εἶναι ὅπως ἀσφαλέστατα μενοῦμεν, εἴ τε ἤδη δοκεῖ ἀπιέναι, ὅπως ἀσφαλέστατα ἄπιμεν, καὶ ὅπως τὰ ἐπιτήδεια ἕξομεν· ἄνευ γὰρ τούτων οὔτε στρατηγοῦ οὔτε ἰδιώτου ὄφελος οὐδέν.", "st": "1.3.11"}, {"sp": "N", "t": "ὁ δ᾽ ἀνὴρ πολλοῦ μὲν ἄξιος ὧι ἂν φίλος ἦι, χαλεπώτατος δ᾽ ἐχθρὸς ὧι ἂν πολέμιος ἦι, ἔχει δὲ δύναμιν καὶ πεζὴν καὶ ἱππικὴν καὶ ναυτικὴν ἣν πάντες ὁμοίως ὁρῶμέν τε καὶ ἐπιστάμεθα· καὶ γὰρ οὐδὲ πόρρω δοκοῦμέν μοι αὐτοῦ καθῆσθαι. ὥστε ὥρα λέγειν ὅ τι τις γιγνώσκει ἄριστον εἶναι.» ταῦτα εἰπὼν ἐπαύσατο.", "st": "1.3.12"}, {"sp": "N", "t": "ἐκ δὲ τούτου ἀνίσταντο οἱ μὲν ἐκ τοῦ αὐτομάτου, λέξοντες ἃ ἐγίγνωσκον, οἱ δὲ καὶ ὑπ᾽ ἐκείνου ἐγκέλευστοι, ἐπιδεικνύντες οἵα εἴη ἡ ἀπορία ἄνευ τῆς Κύρου γνώμης καὶ μένειν καὶ ἀπιέναι.", "st": "1.3.13"}, {"sp": "N", "t": "εἷς δὲ δὴ εἶπε προσποιούμενος σπεύδειν ὡς τάχιστα πορεύεσθαι εἰς τὴν Ἑλλάδα στρατηγοὺς μὲν ἑλέσθαι ἄλλους ὡς τάχιστα, εἰ μὴ βούλεται Κλέαρχος ἀπάγειν· τὰ δ᾽ ἐπιτήδει᾽ ἀγοράζεσθαι (ἡ δ᾽ ἀγορὰ ἦν ἐν τῶι βαρβαρικῶι στρατεύματι) καὶ συσκευάζεσθαι· ἐλθόντας δὲ Κῦρον αἰτεῖν πλοῖα, ὡς ἀποπλέοιεν· ἐὰν δὲ μὴ διδῶι ταῦτα, ἡγεμόνα αἰτεῖν Κῦρον ὅστις διὰ φιλίας τῆς χώρας ἀπάξει. ἐὰν δὲ μηδὲ ἡγεμόνα διδῶι, συντάττεσθαι τὴν ταχίστην, πέμψαι δὲ καὶ προκαταληψομένους τὰ ἄκρα, ὅπως μὴ φθάσωσι μήτε Κῦρος μήτε οἱ Κίλικες καταλαβόντες, ὧν πολλοὺς καὶ πολλὰ χρήματα ἔχομεν ἀνηρπακότες. οὗτος μὲν τοιαῦτα εἶπε· μετὰ δὲ τοῦτον Κλέαρχος εἶπε τοσοῦτον.", "st": "1.3.14"}, {"sp": "N", "t": "«ὡς μὲν στρατηγήσοντα ἐμὲ ταύτην τὴν στρατηγίαν μηδεὶς ὑμῶν λεγέτω· πολλὰ γὰρ ἐνορῶ δι᾽ ἃ ἐμοὶ τοῦτο οὐ ποιητέον· ὡς δὲ τῶι ἀνδρὶ ὃν ἂν ἕλησθε πείσομαι ἧι δυνατὸν μάλιστα, ἵνα εἰδῆτε ὅτι καὶ ἄρχεσθαι ἐπίσταμαι ὥς τις καὶ ἄλλος μάλιστα ἀνθρώπων.", "st": "1.3.15"}, {"sp": "N", "t": "μετὰ τοῦτον ἄλλος ἀνέστη, ἐπιδεικνὺς μὲν τὴν εὐήθειαν τοῦ τὰ πλοῖα αἰτεῖν κελεύοντος, ὥσπερ πάλιν τὸν στόλον Κύρου ποιουμένου, ἐπιδεικνὺς δὲ ὡς εὔηθες εἴη ἡγεμόνα αἰτεῖν παρὰ τούτου ὧι λυμαινόμεθα τὴν πρᾶξιν. εἰ δὲ καὶ τῶι ἡγεμόνι πιστεύσομεν ὃν ἂν Κῦρος διδῶι, τί κωλύει καὶ τὰ ἄκρα ἡμῖν κελεύειν Κῦρον προκαταλαβεῖν;", "st": "1.3.16"}, {"sp": "N", "t": "ἐγὼ γὰρ ὀκνοίην μὲν ἂν εἰς τὰ πλοῖα ἐμβαίνειν ἃ ἡμῖν δοίη, μὴ ἡμᾶς ταῖς τριήρεσι καταδύσηι, φοβοίμην δ᾽ ἂν τῶι ἡγεμόνι ὃν δοίη ἕπεσθαι, μὴ ἡμᾶς ἀγάγηι ὅθεν οὐκ ἔσται ἐξελθεῖν· βουλοίμην δ᾽ ἂν ἄκοντος ἀπιὼν Κύρου λαθεῖν αὐτὸν ἀπελθών· ὃ οὐ δυνατόν ἐστιν.", "st": "1.3.17"}, {"sp": "N", "t": "ἀλλ᾽ ἐγώ φημι ταῦτα μὲν φλυαρίας εἶναι· δοκεῖ δέ μοι ἄνδρας ἐλθόντας πρὸς Κῦρον οἵτινες ἐπιτήδειοι σὺν Κλεάρχωι ἐρωτᾶν ἐκεῖνον τί βούλεται ἡμῖν χρῆσθαι· καὶ ἐὰν μὲν ἡ πρᾶξις ἦι παραπλησία οἵαιπερ καὶ πρόσθεν ἐχρῆτο τοῖς ξένοις, ἕπεσθαι καὶ ἡμᾶς καὶ μὴ κακίους εἶναι τῶν πρόσθεν τούτωι συναναβάντων·", "st": "1.3.18"}, {"sp": "N", "t": "ἐὰν δὲ μείζων ἡ πρᾶξις τῆς πρόσθεν φαίνηται καὶ ἐπιπονωτέρα καὶ ἐπικινδυνοτέρα, ἀξιοῦν ἢ πείσαντα ἡμᾶς ἄγειν ἢ πεισθέντα πρὸς φιλίαν ἀφιέναι· οὕτω γὰρ καὶ ἑπόμενοι ἂν φίλοι αὐτῶι καὶ πρόθυμοι ἑποίμεθα καὶ ἀπιόντες ἀσφαλῶς ἂν ἀπίοιμεν· ὅ τι δ᾽ ἂν πρὸς ταῦτα λέγηι ἀπαγγεῖλαι δεῦρο· ἡμᾶς δ᾽ ἀκούσαντας πρὸς ταῦτα βουλεύεσθαι.»", "st": "1.3.19"}, {"sp": "N", "t": "ἔδοξε ταῦτα, καὶ ἄνδρας ἑλόμενοι σὺν Κλεάρχωι πέμπουσιν οἳ ἠρώτων Κῦρον τὰ δόξαντα τῆι στρατιᾶι. ὁ δ᾽ ἀπεκρίνατο ὅτι ἀκούει Ἀβροκόμαν ἐχθρὸν ἄνδρα ἐπὶ τῶι Εὐφράτηι ποταμῶι εἶναι, ἀπέχοντα δώδεκα σταθμούς· πρὸς τοῦτον οὖν ἔφη βούλεσθαι ἐλθεῖν· κἂν μὲν ἦι ἐκεῖ, τὴν δίκην ἔφη χρήιζειν ἐπιθεῖναι αὐτῶι, «ἦν δὲ φύγηι, ἡμεῖς ἐκεῖ πρὸς ταῦτα βουλευσόμεθα.»", "st": "1.3.20"}, {"sp": "N", "t": "ἀκούσαντες δὲ ταῦτα οἱ αἱρετοὶ ἀγγέλλουσι τοῖς στρατιώταις· τοῖς δὲ ὑποψία μὲν ἦν ὅτι ἄγει πρὸς βασιλέα, ὅμως δὲ ἐδόκει ἕπεσθαι. προσαιτοῦσι δὲ μισθόν· ὁ δὲ Κῦρος ὑπισχνεῖται ἡμιόλιον πᾶσι δώσειν οὗ πρότερον ἔφερον, ἀντὶ δαρεικοῦ τρία ἡμιδαρεικὰ τοῦ μηνὸς τῶι στρατιώτηι· ὅτι δὲ ἐπὶ βασιλέα ἄγοι οὐδὲ ἐνταῦθα ἤκουσεν οὐδεὶς ἐν τῶι γε φανερῶι.", "st": "1.3.21"}, {"sp": "N", "t": "ἐντεῦθεν ἐξελαύνει σταθμοὺς δύο παρασάγγας δέκα ἐπὶ τὸν Ψάρον ποταμόν, οὗ ἦν τὸ εὖρος τρία πλέθρα. ἐντεῦθεν ἐξελαύνει σταθμὸν ἕνα παρασάγγας πέντε ἐπὶ τὸν Πύραμον ποταμόν, οὗ ἦν τὸ εὖρος στάδιον. ἐντεῦθεν ἐξελαύνει σταθμοὺς δύο παρασάγγας πεντεκαίδεκα εἰς Ἰσσούς, τῆς Κιλικίας ἐσχάτην πόλιν ἐπὶ τῆι θαλάττηι οἰκουμένην, μεγάλην καὶ εὐδαίμονα.", "st": "1.4.1"}, {"sp": "N", "t": "ἐνταῦθα ἔμειναν ἡμέρας τρεῖς· καὶ Κύρωι παρῆσαν αἱ ἐκ Πελοποννήσου νῆες τριάκοντα καὶ πέντε καὶ ἐπ᾽ αὐταῖς ναύαρχος Πυθαγόρας Λακεδαιμόνιος. ἡγεῖτο δ᾽ αὐταῖς Ταμὼς Αἰγύπτιος ἐξ Ἐφέσου, ἔχων ναῦς ἑτέρας Κύρου πέντε καὶ εἴκοσιν, αἷς ἐπολιόρκει Μίλητον, ὅτε Τισσαφέρνει φίλη ἦν, καὶ συνεπολέμει Κύρωι πρὸς αὐτόν.", "st": "1.4.2"}, {"sp": "N", "t": "παρῆν δὲ καὶ Χειρίσοφος Λακεδαιμόνιος ἐπὶ τῶν νεῶν, μετάπεμπτος ὑπὸ Κύρου, ἑπτακοσίους ἔχων ὁπλίτας, ὧν ἐστρατήγει παρὰ Κύρωι. αἱ δὲ νῆες ὥρμουν παρὰ τὴν Κύρου σκηνήν. ἐνταῦθα καὶ οἱ παρὰ Ἀβροκόμα μισθοφόροι Ἕλληνες ἀποστάντες ἦλθον παρὰ Κῦρον τετρακόσιοι ὁπλῖται καὶ συνεστρατεύοντο ἐπὶ βασιλέα.", "st": "1.4.3"}, {"sp": "N", "t": "ἐντεῦθεν ἐξελαύνει σταθμὸν ἕνα παρασάγγας πέντε ἐπὶ πύλας τῆς Κιλικίας καὶ τῆς Συρίας. ἦσαν δὲ ταῦτα δύο τείχη, καὶ τὸ μὲν ἔσωθεν ⟨τὸ⟩ πρὸ τῆς Κιλικίας Συέννεσις εἶχε καὶ Κιλίκων φυλακή, τὸ δὲ ἔξω τὸ πρὸ τῆς Συρίας βασιλέως ἐλέγετο φυλακὴ φυλάττειν. διὰ μέσου δὲ ῥεῖ τούτων ποταμὸς Κάρσος ὄνομα, εὖρος πλέθρου. ἅπαν δὲ τὸ μέσον τῶν τειχῶν ἦσαν στάδιοι τρεῖς· καὶ παρελθεῖν οὐκ ἦν βίαι· ἦν γὰρ ἡ πάροδος στενὴ καὶ τὰ τείχη εἰς τὴν θάλατταν καθήκοντα, ὕπερθεν δ᾽ ἦσαν πέτραι ἠλίβατοι· ἐπὶ δὲ τοῖς τείχεσιν ἀμφοτέροις ἐφειστήκεσαν πύλαι.", "st": "1.4.4"}, {"sp": "N", "t": "ταύτης ἕνεκα τῆς παρόδου Κῦρος τὰς ναῦς μετεπέμψατο, ὅπως ὁπλίτας ἀποβιβάσειεν εἴσω καὶ ἔξω τῶν πυλῶν, καὶ βιασόμενος τοὺς πολεμίους εἰ φυλάττοιεν ἐπὶ ταῖς Συρίαις πύλαις, ὅπερ ὤιετο ποιήσειν ὁ Κῦρος τὸν Ἀβροκόμαν, ἔχοντα πολὺ στράτευμα. Ἀβροκόμας δὲ οὐ τοῦτ᾽ ἐποίησεν, ἀλλ᾽ ἐπεὶ ἤκουσε Κῦρον ἐν Κιλικίαι ὄντα, ἀναστρέψας ἐκ Φοινίκης παρὰ βασιλέα ἀπήλαυνεν, ἔχων, ὡς ἐλέγετο, τριάκοντα μυριάδας στρατιᾶς.", "st": "1.4.5"}, {"sp": "N", "t": "ἐντεῦθεν ἐξελαύνει διὰ Συρίας σταθμὸν ἕνα παρασάγγας πέντε εἰς Μυρίανδον, πόλιν οἰκουμένην ὑπὸ Φοινίκων ἐπὶ τῆι θαλάττηι· ἐμπόριον δ᾽ ἦν τὸ χωρίον καὶ ὥρμουν αὐτόθι ὁλκάδες πολλαί. ἐνταῦθ᾽ ἔμεινεν ἡμέρας ἑπτά·", "st": "1.4.6"}, {"sp": "N", "t": "καὶ Ξενίας ὁ Ἀρκὰς [στρατηγὸς] καὶ Πασίων ὁ Μεγαρεὺς ἐμβάντες εἰς πλοῖον καὶ τὰ πλείστου ἄξια ἐνθέμενοι ἀπέπλευσαν, ὡς μὲν τοῖς πλείστοις ἐδόκουν φιλοτιμηθέντες ὅτι τοὺς στρατιώτας αὐτῶν τοὺς παρὰ Κλέαρχον ἀπελθόντας ὡς ἀπιόντας εἰς τὴν Ἑλλάδα πάλιν καὶ οὐ πρὸς βασιλέα εἴα Κῦρος τὸν Κλέαρχον ἔχειν. ἐπεὶ δ᾽ ἦσαν ἀφανεῖς, διῆλθε λόγος ὅτι διώκει αὐτοὺς Κῦρος τριήρεσι· καὶ οἱ μὲν ηὔχοντο ὡς δειλοὺς ὄντας αὐτοὺς ληφθῆναι, οἱ δ᾽ ὤικτιρον εἰ ἁλώσοιντο.", "st": "1.4.7"}, {"sp": "N", "t": "Κῦρος δὲ συγκαλέσας τοὺς στρατηγοὺς εἶπεν· «ἀπολελοίπασιν ἡμᾶς Ξενίας καὶ Πασίων. ἀλλ᾽ εὖ γε μέντοι ἐπιστάσθων ὅτι οὔτε ἀποδεδράκασιν· οἶδα γὰρ ὅπηι οἴχονται· οὔτε ἀποπεφεύγασιν· ἔχω γὰρ τριήρεις ὥστε ἑλεῖν τὸ ἐκείνων πλοῖον· ἀλλὰ μὰ τοὺς θεοὺς οὐκ ἔγωγε αὐτοὺς διώξω, οὐδ᾽ ἐρεῖ οὐδεὶς ὡς ἐγὼ ἕως μὲν ἂν παρῆι τις χρῶμαι, ἐπειδὰν δὲ ἀπιέναι βούληται, συλλαβὼν καὶ αὐτοὺς κακῶς ποιῶ καὶ τὰ χρήματα ἀποσυλῶ. ἀλλὰ ἴτωσαν, εἰδότες ὅτι κακίους εἰσὶ περὶ ἡμᾶς ἢ ἡμεῖς περὶ ἐκείνους. καίτοι ἔχω γε αὐτῶν καὶ τέκνα καὶ γυναῖκας ἐν Τράλλεσι φρουρούμενα· ἀλλ᾽ οὐδὲ τούτων στερήσονται, ἀλλ᾽ ἀπολήψονται τῆς πρόσθεν ἕνεκα περὶ ἐμὲ ἀρετῆς.»", "st": "1.4.8"}, {"sp": "N", "t": "καὶ ὁ μὲν ταῦτα εἶπεν· οἱ δὲ Ἕλληνες, εἴ τις καὶ ἀθυμότερος ἦν πρὸς τὴν ἀνάβασιν, ἀκούοντες τὴν Κύρου ἀρετὴν ἥδιον καὶ προθυμότερον συνεπορεύοντο. μετὰ ταῦτα Κῦρος ἐξελαύνει σταθμοὺς τέτταρας παρασάγγας εἴκοσιν ἐπὶ τὸν Χάλον ποταμόν, ὄντα τὸ εὖρος πλέθρου, πλήρη δ᾽ ἰχθύων μεγάλων καὶ πραέων, οὓς οἱ Σύροι θεοὺς ἐνόμιζον καὶ ἀδικεῖν οὐκ εἴων, οὐδὲ τὰς περιστεράς. αἱ δὲ κῶμαι ἐν αἷς ἐσκήνουν Παρυσάτιδος ἦσαν εἰς ζώνην δεδομέναι.", "st": "1.4.9"}, {"sp": "N", "t": "ἐντεῦθεν ἐξελαύνει σταθμοὺς πέντε παρασάγγας τριάκοντα ἐπὶ τὰς πηγὰς τοῦ Δάρδατος ποταμοῦ, οὗ τὸ εὖρος πλέθρου. ἐνταῦθα ἦσαν τὰ Βελέσυος βασίλεια τοῦ Συρίας ἄρξαντος, καὶ παράδεισος πάνυ μέγας καὶ καλός, ἔχων πάντα ὅσα ὧραι φύουσι. Κῦρος δ᾽ αὐτὸν ἐξέκοψε καὶ τὰ βασίλεια κατέκαυσεν.", "st": "1.4.10"}, {"sp": "N", "t": "ἐντεῦθεν ἐξελαύνει σταθμοὺς τρεῖς παρασάγγας πεντεκαίδεκα ἐπὶ τὸν Εὐφράτην ποταμόν, ὄντα τὸ εὖρος τεττάρων σταδίων· καὶ πόλις αὐτόθι ὠικεῖτο μεγάλη καὶ εὐδαίμων Θάψακος ὄνομα. ἐνταῦθα ἔμεινεν ἡμέρας πέντε. καὶ Κῦρος μεταπεμψάμενος τοὺς στρατηγοὺς τῶν Ἑλλήνων ἔλεγεν ὅτι ἡ ὁδὸς ἔσοιτο πρὸς βασιλέα μέγαν εἰς Βαβυλῶνα· καὶ κελεύει αὐτοὺς λέγειν ταῦτα τοῖς στρατιώταις καὶ ἀναπείθειν ἕπεσθαι.", "st": "1.4.11"}, {"sp": "N", "t": "οἱ δὲ ποιήσαντες ἐκκλησίαν ἀπήγγελλον ταῦτα· οἱ δὲ στρατιῶται ἐχαλέπαινον τοῖς στρατηγοῖς, καὶ ἔφασαν αὐτοὺς πάλαι ταῦτ᾽ εἰδότας κρύπτειν, καὶ οὐκ ἔφασαν ἰέναι, ἐὰν μή τις αὐτοῖς χρήματα διδῶι, ὥσπερ τοῖς προτέροις μετὰ Κύρου ἀναβᾶσι παρὰ τὸν πατέρα τοῦ Κύρου, καὶ ταῦτα οὐκ ἐπὶ μάχην ἰόντων, ἀλλὰ καλοῦντος τοῦ πατρὸς Κῦρον.", "st": "1.4.12"}, {"sp": "N", "t": "ταῦτα οἱ στρατηγοὶ Κύρωι ἀπήγγελλον· ὁ δ᾽ ὑπέσχετο ἀνδρὶ ἑκάστωι δώσειν πέντε ἀργυρίου μνᾶς, ἐπὰν εἰς Βαβυλῶνα ἥκωσι, καὶ τὸν μισθὸν ἐντελῆ μέχρι ἂν καταστήσηι τοὺς Ἕλληνας εἰς Ἰωνίαν πάλιν. τὸ μὲν δὴ πολὺ τοῦ Ἑλληνικοῦ οὕτως ἐπείσθη. Μένων δὲ πρὶν δῆλον εἶναι τί ποιήσουσιν οἱ ἄλλοι στρατιῶται, πότερον ἕψονται Κύρωι ἢ οὔ, συνέλεξε τὸ αὑτοῦ στράτευμα χωρὶς τῶν ἄλλων καὶ ἔλεξε τάδε.", "st": "1.4.13"}, {"sp": "N", "t": "«ἄνδρες, ἐάν μοι πεισθῆτε, οὔτε κινδυνεύσαντες οὔτε πονήσαντες τῶν ἄλλων πλέον προτιμήσεσθε στρατιωτῶν ὑπὸ Κύρου. τί οὖν κελεύω ποιῆσαι; νῦν δεῖται Κῦρος ἕπεσθαι τοὺς Ἕλληνας ἐπὶ βασιλέα· ἐγὼ οὖν φημι ὑμᾶς χρῆναι διαβῆναι τὸν Εὐφράτην ποταμὸν πρὶν δῆλον εἶναι ὅ τι οἱ ἄλλοι Ἕλληνες ἀποκρινοῦνται Κύρωι.", "st": "1.4.14"}, {"sp": "N", "t": "ἢν μὲν γὰρ ψηφίσωνται ἕπεσθαι, ὑμεῖς δόξετε αἴτιοι εἶναι ἄρξαντες τοῦ διαβαίνειν, καὶ ὡς προθυμοτάτοις οὖσιν ὑμῖν χάριν εἴσεται Κῦρος καὶ ἀποδώσει· ἐπίσταται δ᾽ εἴ τις καὶ ἄλλος· ἢν δὲ ἀποψηφίσωνται οἱ ἄλλοι, ἄπιμεν μὲν ἅπαντες τοὔμπαλιν, ὑμῖν δὲ ὡς μόνοις πειθομένοις πιστοτάτοις χρήσεται καὶ εἰς φρούρια καὶ εἰς λοχαγίας, καὶ ἄλλου οὗτινος ἂν δέησθε οἶδα ὅτι ὡς φίλοι τεύξεσθε Κύρου.»", "st": "1.4.15"}, {"sp": "N", "t": "ἀκούσαντες ταῦτα ἐπείθοντο καὶ διέβησαν πρὶν τοὺς ἄλλους ἀποκρίνασθαι. Κῦρος δ᾽ ἐπεὶ ἤισθετο διαβεβηκότας, ἥσθη τε καὶ τῶι στρατεύματι πέμψας Γλοῦν εἶπεν· «ἐγὼ μέν, ὦ ἄνδρες, ἤδη ὑμᾶς ἐπαινῶ· ὅπως δὲ καὶ ὑμεῖς ἐμὲ ἐπαινέσετε ἐμοὶ μελήσει, ἢ μηκέτι με Κῦρον νομίζετε.»", "st": "1.4.16"}, {"sp": "N", "t": "οἱ μὲν δὴ στρατιῶται ἐν ἐλπίσι μεγάλαις ὄντες ηὔχοντο αὐτὸν εὐτυχῆσαι, Μένωνι δὲ καὶ δῶρα ἐλέγετο πέμψαι μεγαλοπρεπῶς. ταῦτα δὲ ποιήσας διέβαινε· συνείπετο δὲ καὶ τὸ ἄλλο στράτευμα αὐτῶι ἅπαν. καὶ τῶν διαβαινόντων τὸν ποταμὸν οὐδεὶς ἐβρέχθη ἀνωτέρω τῶν μαστῶν ὑπὸ τοῦ ποταμοῦ.", "st": "1.4.17"}, {"sp": "N", "t": "οἱ δὲ Θαψακηνοὶ ἔλεγον ὅτι οὐπώποθ᾽ οὗτος ὁ ποταμὸς διαβατὸς γένοιτο πεζῆι εἰ μὴ τότε, ἀλλὰ πλοίοις, ἃ τότε Ἀβροκόμας προϊὼν κατέκαυσεν, ἵνα μὴ Κῦρος διαβῆι. ἐδόκει δὴ θεῖον εἶναι καὶ σαφῶς ὑποχωρῆσαι τὸν ποταμὸν Κύρωι ὡς βασιλεύσοντι.", "st": "1.4.18"}, {"sp": "N", "t": "ἐντεῦθεν ἐξελαύνει διὰ τῆς Συρίας σταθμοὺς ἐννέα παρασάγγας πεντήκοντα· καὶ ἀφικνοῦνται πρὸς τὸν Ἀράξην ποταμόν. ἐνταῦθα ἦσαν κῶμαι πολλαὶ μεσταὶ σίτου καὶ οἴνου. ἐνταῦθα ἔμειναν ἡμέρας τρεῖς καὶ ἐπεσιτίσαντο.", "st": "1.4.19"}, {"sp": "N", "t": "ἐντεῦθεν ἐξελαύνει διὰ τῆς Ἀραβίας τὸν Εὐφράτην ποταμὸν ἐν δεξιᾶι ἔχων σταθμοὺς ἐρήμους πέντε παρασάγγας τριάκοντα καὶ πέντε. ἐν τούτωι δὲ τῶι τόπωι ἦν μὲν ἡ γῆ πεδίον ἅπαν ὁμαλὲς ὥσπερ θάλαττα, ἀψινθίου δὲ πλῆρες· εἰ δέ τι καὶ ἄλλο ἐνῆν ὕλης ἢ καλάμου, ἅπαντα ἦσαν εὐώδη ὥσπερ ἀρώματα·", "st": "1.5.1"}, {"sp": "N", "t": "δένδρον δ᾽ οὐδὲν ἐνῆν, θηρία δὲ παντοῖα, πλεῖστοι ὄνοι ἄγριοι, πολλαὶ δὲ στρουθοὶ αἱ μεγάλαι· ἐνῆσαν δὲ καὶ ὠτίδες καὶ δορκάδες· ταῦτα δὲ τὰ θηρία οἱ ἱππεῖς ἐνίοτε ἐδίωκον. καὶ οἱ μὲν ὄνοι, ἐπεί τις διώκοι, προδραμόντες ἕστασαν· πολὺ γὰρ τῶν ἵππων ἔτρεχον θᾶττον· καὶ πάλιν, ἐπεὶ πλησιάζοιεν οἱ ἵπποι, ταὐτὸν ἐποίουν, καὶ οὐκ ἦν λαβεῖν, εἰ μὴ διαστάντες οἱ ἱππεῖς θηρῶιεν διαδεχόμενοι. τὰ δὲ κρέα τῶν ἁλισκομένων ἦν παραπλήσια τοῖς ἐλαφείοις, ἁπαλώτερα δέ.", "st": "1.5.2"}, {"sp": "N", "t": "στρουθὸν δὲ οὐδεὶς ἔλαβεν· οἱ δὲ διώξαντες τῶν ἱππέων ταχὺ ἐπαύοντο· πολὺ γὰρ ἀπέσπα φεύγουσα, τοῖς μὲν ποσὶ δρόμωι, ταῖς δὲ πτέρυξιν αἴρουσα, ὥσπερ ἱστίωι χρωμένη. τὰς δὲ ὠτίδας ἄν τις ταχὺ ἀνιστῆι ἔστι λαμβάνειν· πέτονται γὰρ βραχὺ ὥσπερ πέρδικες καὶ ταχὺ ἀπαγορεύουσι.", "st": "1.5.3"}, {"sp": "N", "t": "τὰ δὲ κρέα αὐτῶν ἥδιστα ἦν. πορευόμενοι δὲ διὰ ταύτης τῆς χώρας ἀφικνοῦνται ἐπὶ τὸν Μάσκαν ποταμόν, τὸ εὖρος πλεθριαῖον. ἐνταῦθα ἦν πόλις ἐρήμη, μεγάλη, ὄνομα δ᾽ αὐτῆι Κορσωτή· περιερρεῖτο δ᾽ αὕτη ὑπὸ τοῦ Μάσκα κύκλωι.", "st": "1.5.4"}, {"sp": "N", "t": "ἐνταῦθ᾽ ἔμειναν ἡμέρας τρεῖς καὶ ἐπεσιτίσαντο. ἐντεῦθεν ἐξελαύνει σταθμοὺς ἐρήμους τρισκαίδεκα παρασάγγας ἐνενήκοντα τὸν Εὐφράτην ποταμὸν ἐν δεξιᾶι ἔχων, καὶ ἀφικνεῖται ἐπὶ Πύλας. ἐν τούτοις τοῖς σταθμοῖς πολλὰ τῶν ὑποζυγίων ἀπώλετο ὑπὸ λιμοῦ· οὐ γὰρ ἦν χόρτος οὐδὲ ἄλλο οὐδὲν δένδρον, ἀλλὰ ψιλὴ ἦν ἅπασα ἡ χώρα· οἱ δὲ ἐνοικοῦντες ὄνους ἀλέτας παρὰ τὸν ποταμὸν ὀρύττοντες καὶ ποιοῦντες εἰς Βαβυλῶνα ἦγον καὶ ἐπώλουν καὶ ἀνταγοράζοντες σῖτον ἔζων.", "st": "1.5.5"}, {"sp": "N", "t": "τὸ δὲ στράτευμα ὁ σῖτος ἐπέλιπε, καὶ πρίασθαι οὐκ ἦν εἰ μὴ ἐν τῆι Λυδίαι ἀγορᾶι ἐν τῶι Κύρου βαρβαρικῶι, τὴν καπίθην ἀλεύρων ἢ ἀλφίτων τεττάρων σίγλων. ὁ δὲ σίγλος δύναται ἑπτὰ ὀβολοὺς καὶ ἡμιωβέλιον Ἀττικούς· ἡ δὲ καπίθη δύο χοίνικας Ἀττικὰς ἐχώρει. κρέα οὖν ἐσθίοντες οἱ στρατιῶται διεγίγνοντο.", "st": "1.5.6"}, {"sp": "N", "t": "ἦν δὲ τούτων τῶν σταθμῶν οὓς πάνυ μακροὺς ἤλαυνεν, ὁπότε ἢ πρὸς ὕδωρ βούλοιτο διατελέσαι ἢ πρὸς χιλόν. καὶ δή ποτε στενοχωρίας καὶ πηλοῦ φανέντος ταῖς ἁμάξαις δυσπορεύτου ἐπέστη ὁ Κῦρος σὺν τοῖς περὶ αὐτὸν ἀρίστοις καὶ εὐδαιμονεστάτοις καὶ ἔταξε Γλοῦν καὶ Πίγρητα λαβόντας τοῦ βαρβαρικοῦ στρατοῦ συνεκβιβάζειν τὰς ἁμάξας.", "st": "1.5.7"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἐδόκουν αὐτῶι σχολαίως ποιεῖν, ὥσπερ ὀργῆι ἐκέλευσε τοὺς περὶ αὐτὸν Πέρσας τοὺς κρατίστους συνεπισπεῦσαι τὰς ἁμάξας. ἔνθα δὴ μέρος τι τῆς εὐταξίας ἦν θεάσασθαι. ῥίψαντες γὰρ τοὺς πορφυροῦς κάνδυς ὅπου ἔτυχεν ἕκαστος ἑστηκώς, ἵεντο ὥσπερ ἂν δράμοι τις ἐπὶ νίκηι καὶ μάλα κατὰ πρανοῦς γηλόφου, ἔχοντες τούτους τε τοὺς πολυτελεῖς χιτῶνας καὶ τὰς ποικίλας ἀναξυρίδας, ἔνιοι δὲ καὶ στρεπτοὺς περὶ τοῖς τραχήλοις καὶ ψέλια περὶ ταῖς χερσίν· εὐθὺς δὲ σὺν τούτοις εἰσπηδήσαντες εἰς τὸν πηλὸν θᾶττον ἢ ὥς τις ἂν ὤιετο μετεώρους ἐξεκόμισαν τὰς ἁμάξας.", "st": "1.5.8"}, {"sp": "N", "t": "τὸ δὲ σύμπαν δῆλος ἦν Κῦρος ὡς σπεύδων πᾶσαν τὴν ὁδὸν καὶ οὐ διατρίβων ὅπου μὴ ἐπισιτισμοῦ ἕνεκα ἤ τινος ἄλλου ἀναγκαίου ἐκαθέζετο, νομίζων, ὅσωι θᾶττον ἔλθοι, τοσούτωι ἀπαρασκευαστοτέρωι βασιλεῖ μαχεῖσθαι, ὅσωι δὲ σχολαίτερον, τοσούτωι πλέον συναγείρεσθαι βασιλεῖ στράτευμα. καὶ συνιδεῖν δ᾽ ἦν τῶι προσέχοντι τὸν νοῦν τῆι βασιλέως ἀρχῆι πλήθει μὲν χώρας καὶ ἀνθρώπων ἰσχυρὰ οὖσα, τοῖς δὲ μήκεσι τῶν ὁδῶν καὶ τῶι διεσπάσθαι τὰς δυνάμεις ἀσθενής, εἴ τις διὰ ταχέων τὸν πόλεμον ποιοῖτο.", "st": "1.5.9"}, {"sp": "N", "t": "πέραν δὲ τοῦ Εὐφράτου ποταμοῦ κατὰ τοὺς ἐρήμους σταθμοὺς ἦν πόλις εὐδαίμων καὶ μεγάλη, ὄνομα δὲ Χαρμάνδη· ἐκ ταύτης οἱ στρατιῶται ἠγόραζον τὰ ἐπιτήδεια, σχεδίαις διαβαίνοντες ὧδε. διφθέρας ἃς εἶχον στεγάσματα ἐπίμπλασαν χόρτου κούφου, εἶτα συνῆγον καὶ συνέσπων, ὡς μὴ ἅπτεσθαι τῆς κάρφης τὸ ὕδωρ· ἐπὶ τούτων διέβαινον καὶ ἐλάμβανον τὰ ἐπιτήδεια, οἶνόν τε ἐκ τῆς βαλάνου πεποιημένον τῆς ἀπὸ τοῦ φοίνικος καὶ σῖτον μελίνης· τοῦτο γὰρ ἦν ἐν τῆι χώραι πλεῖστον.", "st": "1.5.10"}, {"sp": "N", "t": "ἀμφιλεξάντων δέ τι ἐνταῦθα τῶν τε τοῦ Μένωνος στρατιωτῶν καὶ τῶν τοῦ Κλεάρχου ὁ Κλέαρχος κρίνας ἀδικεῖν τὸν τοῦ Μένωνος πληγὰς ἐνέβαλεν· ὁ δὲ ἐλθὼν πρὸς τὸ ἑαυτοῦ στράτευμα ἔλεγεν· ἀκούσαντες δὲ οἱ στρατιῶται ἐχαλέπαινον καὶ ὠργίζοντο ἰσχυρῶς τῶι Κλεάρχωι.", "st": "1.5.11"}, {"sp": "N", "t": "τῆι δὲ αὐτῆι ἡμέραι Κλέαρχος ἐλθὼν ἐπὶ τὴν διάβασιν τοῦ ποταμοῦ καὶ ἐκεῖ κατασκεψάμενος τὴν ἀγορὰν ἀφιππεύει ἐπὶ τὴν ἑαυτοῦ σκηνὴν διὰ τοῦ Μένωνος στρατεύματος σὺν ὀλίγοις τοῖς περὶ αὐτόν· Κῦρος δὲ οὔπω ἧκεν, ἀλλ᾽ ἔτι προσήλαυνε· τῶν δὲ Μένωνος στρατιωτῶν ξύλα σχίζων τις ὡς εἶδε Κλέαρχον διελαύνοντα, ἵησι τῆι ἀξίνηι· καὶ οὗτος μὲν αὐτοῦ ἥμαρτεν· ἄλλος δὲ λίθωι καὶ ἄλλος, εἶτα πολλοί, κραυγῆς γενομένης.", "st": "1.5.12"}, {"sp": "N", "t": "ὁ δὲ καταφεύγει εἰς τὸ ἑαυτοῦ στράτευμα, καὶ εὐθὺς παραγγέλλει εἰς τὰ ὅπλα· καὶ τοὺς μὲν ὁπλίτας αὐτοῦ ἐκέλευσε μεῖναι τὰς ἀσπίδας πρὸς τὰ γόνατα θέντας, αὐτὸς δὲ λαβὼν τοὺς Θρᾶικας καὶ τοὺς ἱππέας οἳ ἦσαν αὐτῶι ἐν τῶι στρατεύματι πλείους ἢ τετταράκοντα, τούτων δὲ οἱ πλεῖστοι Θρᾶικες, ἤλαυνεν ἐπὶ τοὺς Μένωνος, ὥστ᾽ ἐκείνους ἐκπεπλῆχθαι καὶ αὐτὸν Μένωνα, καὶ τρέχειν ἐπὶ τὰ ὅπλα· οἱ δὲ καὶ ἕστασαν ἀποροῦντες τῶι πράγματι.", "st": "1.5.13"}, {"sp": "N", "t": "ὁ δὲ Πρόξενος (ἔτυχε γὰρ ὕστερος προσιὼν καὶ τάξις αὐτῶι ἑπομένη τῶν ὁπλιτῶν) εὐθὺς οὖν εἰς τὸ μέσον ἀμφοτέρων ἄγων ἔθετο τὰ ὅπλα καὶ ἐδεῖτο τοῦ Κλεάρχου μὴ ποιεῖν ταῦτα. ὁ δ᾽ ἐχαλέπαινεν ὅτι αὐτοῦ ὀλίγου δεήσαντος καταλευσθῆναι πράως λέγοι τὸ αὑτοῦ πάθος, ἐκέλευσέ τε αὐτὸν ἐκ τοῦ μέσου ἐξίστασθαι.", "st": "1.5.14"}, {"sp": "N", "t": "ἐν τούτωι δ᾽ ἐπήιει καὶ Κῦρος καὶ ἐπύθετο τὸ πρᾶγμα· εὐθὺς δ᾽ ἔλαβε τὰ παλτὰ εἰς τὰς χεῖρας καὶ σὺν τοῖς παροῦσι τῶν πιστῶν ἧκεν ἐλαύνων εἰς τὸ μέσον, καὶ λέγει τάδε.", "st": "1.5.15"}, {"sp": "N", "t": "Κλέαρχε καὶ Πρόξενε καὶ οἱ ἄλλοι οἱ παρόντες Ἕλληνες, οὐκ ἴστε ὅ τι ποιεῖτε. εἰ γάρ τινα ἀλλήλοις μάχην συνάψετε, νομίζετε ἐν τῆιδε τῆι ἡμέραι ἐμέ τε κατακεκόψεσθαι καὶ ὑμᾶς οὐ πολὺ ἐμοῦ ὕστερον· κακῶς γὰρ τῶν ἡμετέρων ἐχόντων πάντες οὗτοι οὓς ὁρᾶτε βάρβαροι πολεμιώτεροι ἡμῖν ἔσονται τῶν παρὰ βασιλεῖ ὄντων.", "st": "1.5.16"}, {"sp": "N", "t": "ἀκούσας ταῦτα ὁ Κλέαρχος ἐν ἑαυτῶι ἐγένετο· καὶ παυσάμενοι ἀμφότεροι κατὰ χώραν ἔθεντο τὰ ὅπλα.", "st": "1.5.17"}, {"sp": "N", "t": "ἐντεῦθεν προϊόντων ἐφαίνετο ἴχνια ἵππων καὶ κόπρος· εἰκάζετο δ᾽ εἶναι ὁ στίβος ὡς δισχιλίων ἵππων. οὗτοι προϊόντες ἔκαιον καὶ χιλὸν καὶ εἴ τι ἄλλο χρήσιμον ἦν. Ὀρόντας δέ, Πέρσης ἀνήρ, γένει τε προσήκων βασιλεῖ καὶ τὰ πολέμια λεγόμενος ἐν τοῖς ἀρίστοις Περσῶν ἐπιβουλεύει Κύρωι καὶ πρόσθεν πολεμήσας, καταλλαγεὶς δέ.", "st": "1.6.1"}, {"sp": "N", "t": "οὗτος Κύρωι εἶπεν, εἰ αὐτῶι δοίη ἱππέας χιλίους, ὅτι τοὺς προκατακαίοντας ἱππέας ἢ κατακαίνοι ἂν ἐνεδρεύσας ἢ ζῶντας πολλοὺς αὐτῶν ἂν ἕλοι καὶ κωλύσειε τοῦ καίειν ἐπιόντας, καὶ ποιήσειεν ὥστε μήποτε δύνασθαι αὐτοὺς ἰδόντας τὸ Κύρου στράτευμα βασιλεῖ διαγγεῖλαι. τῶι δὲ Κύρωι ἀκούσαντι ταῦτα ἐδόκει ὠφέλιμα εἶναι, καὶ ἐκέλευεν αὐτὸν λαμβάνειν μέρος παρ᾽ ἑκάστου τῶν ἡγεμόνων.", "st": "1.6.2"}, {"sp": "N", "t": "ὁ δ᾽ Ὀρόντας νομίσας ἑτοίμους εἶναι αὑτῶι τοὺς ἱππέας γράφει ἐπιστολὴν παρὰ βασιλέα ὅτι ἥξοι ἔχων ἱππέας ὡς ἂν δύνηται πλείστους· ἀλλὰ φράσαι τοῖς αὑτοῦ ἱππεῦσιν ἐκέλευεν ὡς φίλιον αὐτὸν ὑποδέχεσθαι. ἐνῆν δὲ ἐν τῆι ἐπιστολῆι καὶ τῆς πρόσθεν φιλίας ὑπομνήματα καὶ πίστεως. ταύτην τὴν ἐπιστολὴν δίδωσι πιστῶι ἀνδρί, ὡς ὤιετο· ὁ δὲ λαβὼν Κύρωι δίδωσιν.", "st": "1.6.3"}, {"sp": "N", "t": "ἀναγνοὺς δὲ αὐτὴν ὁ Κῦρος συλλαμβάνει Ὀρόνταν, καὶ συγκαλεῖ εἰς τὴν ἑαυτοῦ σκηνὴν Πέρσας τοὺς ἀρίστους τῶν περὶ αὐτὸν ἑπτά, καὶ τοὺς τῶν Ἑλλήνων στρατηγοὺς ἐκέλευσεν ὁπλίτας ἀγαγεῖν, τούτους δὲ θέσθαι τὰ ὅπλα περὶ τὴν αὑτοῦ σκηνήν. οἱ δὲ ταῦτα ἐποίησαν, ἀγαγόντες ὡς τρισχιλίους ὁπλίτας.", "st": "1.6.4"}, {"sp": "N", "t": "Κλέαρχον δὲ καὶ εἴσω παρεκάλεσε σύμβουλον, ὅς γε καὶ αὐτῶι καὶ τοῖς ἄλλοις ἐδόκει προτιμηθῆναι μάλιστα τῶν Ἑλλήνων. ἐπεὶ δ᾽ ἐξῆλθεν, ἀπήγγειλε τοῖς φίλοις τὴν κρίσιν τοῦ Ὀρόντα ὡς ἐγένετο· οὐ γὰρ ἀπόρρητον ἦν.", "st": "1.6.5"}, {"sp": "N", "t": "ἔφη δὲ Κῦρον ἄρχειν τοῦ λόγου ὧδε. «παρεκάλεσα ὑμᾶς, ἄνδρες φίλοι, ὅπως σὺν ὑμῖν βουλευόμενος ὅ τι δίκαιόν ἐστι καὶ πρὸς θεῶν καὶ πρὸς ἀνθρώπων, τοῦτο πράξω περὶ Ὀρόντα τουτουί. τοῦτον γὰρ πρῶτον μὲν ὁ ἐμὸς πατὴρ ἔδωκεν ὑπήκοον εἶναι ἐμοί· ἐπεὶ δὲ ταχθείς, ὡς ἔφη αὐτός, ὑπὸ τοῦ ἐμοῦ ἀδελφοῦ οὗτος ἐπολέμησεν ἐμοὶ ἔχων τὴν ἐν Σάρδεσιν ἀκρόπολιν, καὶ ἐγὼ αὐτὸν προσπολεμῶν ἐποίησα ὥστε δόξαι τούτωι τοῦ πρὸς ἐμὲ πολέμου παύσασθαι, καὶ δεξιὰν ἔλαβον καὶ ἔδωκα, μετὰ ταῦτα, ἔφη, Ὀρόντα, ἔστιν ὅ τι σε ἠδίκησα;»", "st": "1.6.6"}, {"sp": "N", "t": "ἀπεκρίνατο ὅτι οὔ. πάλιν δὲ ὁ Κῦρος ἠρώτα· «οὐκοῦν ὕστερον, ὡς αὐτὸς σὺ ὁμολογεῖς, οὐδὲν ὑπ᾽ ἐμοῦ ἀδικούμενος ἀποστὰς εἰς Μυσοὺς κακῶς ἐποίεις τὴν ἐμὴν χώραν ὅ τι ἐδύνω;» ἔφη Ὀρόντας. «οὐκοῦν, ἔφη ὁ Κῦρος, ὁπότ᾽ αὖ ἔγνως τὴν σαυτοῦ δύναμιν, ἐλθὼν ἐπὶ τὸν τῆς Ἀρτέμιδος βωμὸν μεταμέλειν τέ σοι ἔφησθα καὶ πείσας ἐμὲ πιστὰ πάλιν ἔδωκάς μοι καὶ ἔλαβες παρ᾽ ἐμοῦ;» καὶ ταῦθ᾽ ὡμολόγει Ὀρόντας.", "st": "1.6.7"}, {"sp": "N", "t": "«τί οὖν, ἔφη ὁ Κῦρος, ἀδικηθεὶς ὑπ᾽ ἐμοῦ νῦν τὸ τρίτον ἐπιβουλεύων μοι φανερὸς γέγονας;» εἰπόντος δὲ τοῦ Ὀρόντα ὅτι οὐδὲν ἀδικηθείς, ἠρώτησεν ὁ Κῦρος αὐτόν· «ὁμολογεῖς οὖν περὶ ἐμὲ ἄδικος γεγενῆσθαι;» «ἦ γὰρ ἀνάγκη,» ἔφη Ὀρόντας. ἐκ τούτου πάλιν ἠρώτησεν ὁ Κῦρος· «ἔτι οὖν ἂν γένοιο τῶι ἐμῶι ἀδελφῶι πολέμιος, ἐμοὶ δὲ φίλος καὶ πιστός;» ὁ δὲ ἀπεκρίνατο ὅτι οὐδ᾽ εἰ γενοίμην, ὦ Κῦρε, σοί γ᾽ ἄν ποτε ἔτι δόξαιμι.", "st": "1.6.8"}, {"sp": "N", "t": "πρὸς ταῦτα Κῦρος εἶπε τοῖς παροῦσιν· «ὁ μὲν ἀνὴρ τοιαῦτα μὲν πεποίηκε, τοιαῦτα δὲ λέγει· ὑμῶν δὲ σὺ πρῶτος, ὦ Κλέαρχε, ἀπόφηναι γνώμην ὅ τι σοι δοκεῖ.» Κλέαρχος δὲ εἶπε τάδε. «συμβουλεύω ἐγὼ τὸν ἄνδρα τοῦτον ἐκποδὼν ποιεῖσθαι ὡς τάχιστα, ὡς μηκέτι δέηι τοῦτον φυλάττεσθαι, ἀλλὰ σχολὴ ἦι ἡμῖν, τὸ κατὰ τοῦτον εἶναι, τοὺς ἐθελοντὰς τούτους εὖ ποιεῖν.»", "st": "1.6.9"}, {"sp": "N", "t": "ταύτηι δὲ τῆι γνώμηι ἔφη καὶ τοὺς ἄλλους προσθέσθαι. μετὰ ταῦτα, ἔφη, κελεύοντος Κύρου ἔλαβον τῆς ζώνης τὸν Ὀρόνταν ἐπὶ θανάτωι ἅπαντες ἀναστάντες καὶ οἱ συγγενεῖς· εἶτα δ᾽ ἐξῆγον αὐτὸν οἷς προσετάχθη. ἐπεὶ δὲ εἶδον αὐτὸν οἵπερ πρόσθεν προσεκύνουν, καὶ τότε προσεκύνησαν, καίπερ εἰδότες ὅτι ἐπὶ θάνατον ἄγοιτο.", "st": "1.6.10"}, {"sp": "N", "t": "ἐπεὶ δὲ εἰς τὴν Ἀρταπάτου σκηνὴν εἰσήχθη, τοῦ πιστοτάτου τῶν Κύρου σκηπτούχων, μετὰ ταῦτα οὔτε ζῶντα Ὀρόνταν οὔτε τεθνηκότα οὐδεὶς εἶδε πώποτε, οὐδὲ ὅπως ἀπέθανεν οὐδεὶς εἰδὼς ἔλεγεν· εἴκαζον δὲ ἄλλοι ἄλλως· τάφος δὲ οὐδεὶς πώποτε αὐτοῦ ἐφάνη.", "st": "1.6.11"}, {"sp": "N", "t": "ἐντεῦθεν ἐξελαύνει διὰ τῆς Βαβυλωνίας σταθμοὺς τρεῖς παρασάγγας δώδεκα. ἐν δὲ τῶι τρίτωι σταθμῶι Κῦρος ἐξέτασιν ποιεῖται τῶν Ἑλλήνων καὶ τῶν βαρβάρων ἐν τῶι πεδίωι περὶ μέσας νύκτας· ἐδόκει γὰρ εἰς τὴν ἐπιοῦσαν ἕω ἥξειν βασιλέα σὺν τῶι στρατεύματι μαχούμενον· καὶ ἐκέλευε Κλέαρχον μὲν τοῦ δεξιοῦ κέρως ἡγεῖσθαι, Μένωνα δὲ τὸν Θετταλὸν τοῦ εὐωνύμου, αὐτὸς δὲ τοὺς ἑαυτοῦ διέταξε.", "st": "1.7.1"}, {"sp": "N", "t": "μετὰ δὲ τὴν ἐξέτασιν ἅμα τῆι ἐπιούσηι ἡμέραι ἥκοντες αὐτόμολοι παρὰ μεγάλου βασιλέως ἀπήγγελλον Κύρωι περὶ τῆς βασιλέως στρατιᾶς. Κῦρος δὲ συγκαλέσας τοὺς στρατηγοὺς καὶ λοχαγοὺς τῶν Ἑλλήνων συνεβουλεύετό τε πῶς ἂν τὴν μάχην ποιοῖτο καὶ αὐτὸς παρήινει θαρρύνων τοιάδε.", "st": "1.7.2"}, {"sp": "N", "t": "«ὦ ἄνδρες Ἕλληνες, οὐκ ἀνθρώπων ἀπορῶν βαρβάρων συμμάχους ὑμᾶς ἄγω, ἀλλὰ νομίζων ἀμείνονας καὶ κρείττους πολλῶν βαρβάρων ὑμᾶς εἶναι, διὰ τοῦτο προσέλαβον. ὅπως οὖν ἔσεσθε ἄνδρες ἄξιοι τῆς ἐλευθερίας ἧς κέκτησθε καὶ ἧς ὑμᾶς ἐγὼ εὐδαιμονίζω. εὖ γὰρ ἴστε ὅτι τὴν ἐλευθερίαν ἑλοίμην ἂν ἀντὶ ὧν ἔχω πάντων καὶ ἄλλων πολλαπλασίων.", "st": "1.7.3"}, {"sp": "N", "t": "ὅπως δὲ καὶ εἰδῆτε εἰς οἷον ἔρχεσθε ἀγῶνα, ὑμᾶς εἰδὼς διδάξω. τὸ μὲν γὰρ πλῆθος πολὺ καὶ κραυγῆι πολλῆι ἐπίασιν· ἂν δὲ ταῦτα ἀνάσχησθε, τὰ ἄλλα καὶ αἰσχύνεσθαί μοι δοκῶ οἵους ἡμῖν γνώσεσθε τοὺς ἐν τῆι χώραι ὄντας ἀνθρώπους. ὑμῶν δὲ ἀνδρῶν ὄντων καὶ εὖ τῶν ἐμῶν γενομένων, ἐγὼ ὑμῶν τὸν μὲν οἴκαδε βουλόμενον ἀπιέναι τοῖς οἴκοι ζηλωτὸν ποιήσω ἀπελθεῖν, πολλοὺς δὲ οἶμαι ποιήσειν τὰ παρ᾽ ἐμοὶ ἑλέσθαι ἀντὶ τῶν οἴκοι.»", "st": "1.7.4"}, {"sp": "N", "t": "ἐνταῦθα Γαυλίτης παρών, φυγὰς Σάμιος, πιστὸς δὲ Κύρωι, εἶπεν· «καὶ μήν, ὦ Κῦρε, λέγουσί τινες ὅτι πολλὰ ὑπισχνῆι νῦν διὰ τὸ ἐν τοιούτωι εἶναι τοῦ κινδύνου προσιόντος, ἂν δὲ εὖ γένηταί τι, οὐ μεμνήσεσθαί σέ φασιν· ἔνιοι δὲ οὐδ᾽ εἰ μεμνῆιό τε καὶ βούλοιο δύνασθαι ἂν ἀποδοῦναι ὅσα ὑπισχνῆι.»", "st": "1.7.5"}, {"sp": "N", "t": "ἀκούσας ταῦτα ἔλεξεν ὁ Κῦρος· «ἀλλ᾽ ἔστι μὲν ἡμῖν, ὦ ἄνδρες, ἀρχὴ πατρώια πρὸς μὲν μεσημβρίαν μέχρι οὗ διὰ καῦμα οὐ δύνανται οἰκεῖν ἄνθρωποι, πρὸς δὲ ἄρκτον μέχρι οὗ διὰ χειμῶνα· τὰ δ᾽ ἐν μέσωι τούτων πάντα σατραπεύουσιν οἱ τοῦ ἐμοῦ ἀδελφοῦ φίλοι.", "st": "1.7.6"}, {"sp": "N", "t": "ἢν δ᾽ ἡμεῖς νικήσωμεν, ἡμᾶς δεῖ τοὺς ἡμετέρους φίλους τούτων ἐγκρατεῖς ποιῆσαι. ὥστε οὐ τοῦτο δέδοικα, μὴ οὐκ ἔχω ὅ τι δῶ ἑκάστωι τῶν φίλων, ἂν εὖ γένηται, ἀλλὰ μὴ οὐκ ἔχω ἱκανοὺς οἷς δῶ. ὑμῶν δὲ τῶν Ἑλλήνων καὶ στέφανον ἑκάστωι χρυσοῦν δώσω.»", "st": "1.7.7"}, {"sp": "N", "t": "οἱ δὲ ταῦτα ἀκούσαντες αὐτοί τε ἦσαν πολὺ προθυμότεροι καὶ τοῖς ἄλλοις ἐξήγγελλον. εἰσῆισαν δὲ παρ᾽ αὐτὸν οἵ τε στρατηγοὶ καὶ τῶν ἄλλων Ἑλλήνων τινὲς ἀξιοῦντες εἰδέναι τί σφίσιν ἔσται, ἐὰν κρατήσωσιν. ὁ δὲ ἐμπιμπλὰς ἁπάντων τὴν γνώμην ἀπέπεμπε.", "st": "1.7.8"}, {"sp": "N", "t": "παρεκελεύοντο δὲ αὐτῶι πάντες ὅσοιπερ διελέγοντο μὴ μάχεσθαι, ἀλλ᾽ ὄπισθεν ἑαυτῶν τάττεσθαι. ἐν δὲ τῶι καιρῶι τούτωι Κλέαρχος ὧδέ πως ἤρετο τὸν Κῦρον· «οἴει γάρ σοι μαχεῖσθαι, ὦ Κῦρε, τὸν ἀδελφόν;» «νὴ Δί᾽, ἔφη ὁ Κῦρος, εἴπερ γε Δαρείου καὶ Παρυσάτιδός ἐστι παῖς, ἐμὸς δὲ ἀδελφός, οὐκ ἀμαχεὶ ταῦτ᾽ ἐγὼ λήψομαι.»", "st": "1.7.9"}, {"sp": "N", "t": "ἐνταῦθα δὴ ἐν τῆι ἐξοπλισίαι ἀριθμὸς ἐγένετο τῶν μὲν Ἑλλήνων ἀσπὶς μυρία καὶ τετρακοσία, πελτασταὶ δὲ δισχίλιοι καὶ πεντακόσιοι, τῶν δὲ μετὰ Κύρου βαρβάρων δέκα μυριάδες καὶ ἅρματα δρεπανηφόρα ἀμφὶ τὰ εἴκοσι.", "st": "1.7.10"}, {"sp": "N", "t": "τῶν δὲ πολεμίων ἐλέγοντο εἶναι ἑκατὸν καὶ εἴκοσι μυριάδες καὶ ἅρματα δρεπανηφόρα διακόσια. ἄλλοι δὲ ἦσαν ἑξακισχίλιοι ἱππεῖς, ὧν Ἀρταγέρσης ἦρχεν· οὗτοι δ᾽ αὖ πρὸ αὐτοῦ βασιλέως τεταγμένοι ἦσαν.", "st": "1.7.11"}, {"sp": "N", "t": "τοῦ δὲ βασιλέως στρατεύματος ἦσαν ἄρχοντες καὶ στρατηγοὶ καὶ ἡγεμόνες τέτταρες, τριάκοντα μυριάδων ἕκαστος, Ἀβροκόμας, Τισσαφέρνης, Γωβρύας, Ἀρβάκης. τούτων δὲ παρεγένοντο ἐν τῆι μάχηι ἐνενήκοντα μυριάδες καὶ ἅρματα δρεπανηφόρα ἑκατὸν καὶ πεντήκοντα· Ἀβροκόμας δὲ ὑστέρησε τῆς μάχης ἡμέραις πέντε, ἐκ Φοινίκης ἐλαύνων.", "st": "1.7.12"}, {"sp": "N", "t": "ταῦτα δὲ ἤγγελλον πρὸς Κῦρον οἱ αὐτομολήσαντες [ἐκ τῶν πολεμίων] παρὰ μεγάλου βασιλέως πρὸ τῆς μάχης, καὶ μετὰ τὴν μάχην οἳ ὕστερον ἐλήφθησαν τῶν πολεμίων ταὐτὰ ἤγγελλον.", "st": "1.7.13"}, {"sp": "N", "t": "ἐντεῦθεν δὲ Κῦρος ἐξελαύνει σταθμὸν ἕνα παρασάγγας τρεῖς συντεταγμένωι τῶι στρατεύματι παντὶ καὶ τῶι Ἑλληνικῶι καὶ τῶι βαρβαρικῶι· ὤιετο γὰρ ταύτηι τῆι ἡμέραι μαχεῖσθαι βασιλέα· κατὰ γὰρ μέσον τὸν σταθμὸν τοῦτον τάφρος ἦν ὀρυκτὴ βαθεῖα, τὸ μὲν εὖρος ὀργυιαὶ πέντε, τὸ δὲ βάθος ὀργυιαὶ τρεῖς.", "st": "1.7.14"}, {"sp": "N", "t": "παρετέτατο δὲ ἡ τάφρος ἄνω διὰ τοῦ πεδίου ἐπὶ δώδεκα παρασάγγας μέχρι τοῦ Μηδίας τείχους. [ἔνθα αἱ διώρυχες, ἀπὸ τοῦ Τίγρητος ποταμοῦ ῥέουσαι· εἰσὶ δὲ τέτταρες, τὸ μὲν εὖρος πλεθριαῖαι, βαθεῖαι δὲ ἰσχυρῶς, καὶ πλοῖα πλεῖ ἐν αὐταῖς σιταγωγά· εἰσβάλλουσι δὲ εἰς τὸν Εὐφράτην, διαλείπουσι δ᾽ ἑκάστη παρασάγγην, γέφυραι, δ᾽ ἔπεισιν.] ἦν δὲ παρὰ τὸν Εὐφράτην πάροδος στενὴ μεταξὺ τοῦ ποταμοῦ καὶ τῆς τάφρου ὡς εἴκοσι ποδῶν τὸ εὖρος·", "st": "1.7.15"}, {"sp": "N", "t": "ταύτην δὲ τὴν τάφρον βασιλεὺς ποιεῖ μέγας ἀντὶ ἐρύματος, ἐπειδὴ πυνθάνεται Κῦρον προσελαύνοντα. ταύτην δὴ τὴν πάροδον Κῦρός τε καὶ ἡ στρατιὰ παρῆλθε καὶ ἐγένοντο εἴσω τῆς τάφρου.", "st": "1.7.16"}, {"sp": "N", "t": "ταύτηι μὲν οὖν τῆι ἡμέραι οὐκ ἐμαχέσατο βασιλεύς, ἀλλ᾽ ὑποχωρούντων φανερὰ ἦσαν καὶ ἵππων καὶ ἀνθρώπων ἴχνη πολλά.", "st": "1.7.17"}, {"sp": "N", "t": "ἐνταῦθα Κῦρος Σιλανὸν καλέσας τὸν Ἀμπρακιώτην μάντιν ἔδωκεν αὐτῶι δαρεικοὺς τρισχιλίους, ὅτι τῆι ἑνδεκάτηι ἀπ᾽ ἐκείνης ἡμέραι πρότερον θυόμενος εἶπεν αὐτῶι ὅτι βασιλεὺς οὐ μαχεῖται δέκα ἡμερῶν, Κῦρος δ᾽ εἶπεν· «οὐκ ἄρα ἔτι μαχεῖται, εἰ ἐν ταύταις οὐ μαχεῖται ταῖς ἡμέραις· ἐὰν δ᾽ ἀληθεύσηις, ὑπισχνοῦμαί σοι δέκα τάλαντα.» τοῦτο τὸ χρυσίον τότε ἀπέδωκεν, ἐπεὶ παρῆλθον αἱ δέκα ἡμέραι.", "st": "1.7.18"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἐπὶ τῆι τάφρωι οὐκ ἐκώλυε βασιλεὺς τὸ Κύρου στράτευμα διαβαίνειν, ἔδοξε καὶ Κύρωι καὶ τοῖς ἄλλοις ἀπεγνωκέναι τοῦ μάχεσθαι· ὥστε τῆι ὑστεραίαι Κῦρος ἐπορεύετο ἠμελημένως μᾶλλον.", "st": "1.7.19"}, {"sp": "N", "t": "τῆι δὲ τρίτηι ἐπί τε τοῦ ἅρματος καθήμενος τὴν πορείαν ἐποιεῖτο καὶ ὀλίγους ἐν τάξει ἔχων πρὸ αὑτοῦ, τὸ δὲ πολὺ αὐτῶι ἀνατεταραγμένον ἐπορεύετο καὶ τῶν ὅπλων τοῖς στρατιώταις πολλὰ ἐπὶ ἁμαξῶν ἤγοντο καὶ ὑποζυγίων.", "st": "1.7.20"}, {"sp": "N", "t": "καὶ ἤδη τε ἦν ἀμφὶ ἀγορὰν πλήθουσαν καὶ πλησίον ἦν ὁ σταθμὸς ἔνθα ἔμελλε καταλύειν, ἡνίκα Πατηγύας, ἀνὴρ Πέρσης τῶν ἀμφὶ Κῦρον χρηστός, προφαίνεται ἐλαύνων ἀνὰ κράτος ἱδροῦντι τῶι ἵππωι, καὶ εὐθὺς πᾶσιν οἷς ἐνετύγχανεν ἐβόα καὶ βαρβαρικῶς καὶ ἑλληνικῶς ὅτι βασιλεὺς σὺν στρατεύματι πολλῶι προσέρχεται ὡς εἰς μάχην παρεσκευασμένος.", "st": "1.8.1"}, {"sp": "N", "t": "ἔνθα δὴ πολὺς τάραχος ἐγένετο· αὐτίκα γὰρ ἐδόκουν οἱ Ἕλληνες καὶ πάντες δὲ ἀτάκτοις σφίσιν ἐπιπεσεῖσθαι·", "st": "1.8.2"}, {"sp": "N", "t": "Κῦρός τε καταπηδήσας ἀπὸ τοῦ ἅρματος τὸν θώρακα ἐνεδύετο καὶ ἀναβὰς ἐπὶ τὸν ἵππον τὰ παλτὰ εἰς τὰς χεῖρας ἔλαβε, τοῖς τε ἄλλοις πᾶσι παρήγγελλεν ἐξοπλίζεσθαι καὶ καθίστασθαι εἰς τὴν ἑαυτοῦ τάξιν ἕκαστον.", "st": "1.8.3"}, {"sp": "N", "t": "ἔνθα δὴ σὺν πολλῆι σπουδῆι καθίσταντο, Κλέαρχος μὲν τὰ δεξιὰ τοῦ κέρατος ἔχων πρὸς τῶι Εὐφράτηι ποταμῶι, Πρόξενος δὲ ἐχόμενος, οἱ δ᾽ ἄλλοι μετὰ τοῦτον, Μένων δὲ καὶ τὸ στράτευμα τὸ εὐώνυμον κέρας ἔσχε τοῦ Ἑλληνικοῦ.", "st": "1.8.4"}, {"sp": "N", "t": "τοῦ δὲ βαρβαρικοῦ ἱππεῖς μὲν Παφλαγόνες εἰς χιλίους παρὰ Κλέαρχον ἔστησαν ἐν τῶι δεξιῶι καὶ τὸ Ἑλληνικὸν πελταστικόν, ἐν δὲ τῶι εὐωνύμωι Ἀριαῖός τε ὁ Κύρου ὕπαρχος καὶ τὸ ἄλλο βαρβαρικόν,", "st": "1.8.5"}, {"sp": "N", "t": "Κῦρος δὲ καὶ ἱππεῖς τούτου ὅσον ἑξακόσιοι ⟨κατὰ τὸ μέσον⟩, ὡπλισμένοι θώραξι μὲν αὐτοὶ καὶ παραμηριδίοις καὶ κράνεσι πάντες πλὴν Κύρου· Κῦρος δὲ ψιλὴν ἔχων τὴν κεφαλὴν εἰς τὴν μάχην καθίστατο [λέγεται δὲ καὶ τοὺς ἄλλους Πέρσας ψιλαῖς ταῖς κεφαλαῖς ἐν τῶι πολέμωι διακινδυνεύειν].", "st": "1.8.6"}, {"sp": "N", "t": "οἱ δ᾽ ἵπποι πάντες [οἱ μετὰ Κύρου] εἶχον καὶ προμετωπίδια καὶ προστερνίδια· εἶχον δὲ καὶ μαχαίρας οἱ ἱππεῖς Ἑλληνικάς.", "st": "1.8.7"}, {"sp": "N", "t": "καὶ ἤδη τε ἦν μέσον ἡμέρας καὶ οὔπω καταφανεῖς ἦσαν οἱ πολέμιοι· ἡνίκα δὲ δείλη ἐγίγνετο, ἐφάνη κονιορτὸς ὥσπερ νεφέλη λευκή, χρόνωι δὲ συχνῶι ὕστερον ὥσπερ μελανία τις ἐν τῶι πεδίωι ἐπὶ πολύ. ὅτε δὲ ἐγγύτερον ἐγίγνοντο, τάχα δὴ καὶ χαλκός τις ἤστραπτε καὶ λόγχαι καὶ αἱ τάξεις καταφανεῖς ἐγίγνοντο.", "st": "1.8.8"}, {"sp": "N", "t": "καὶ ἦσαν ἱππεῖς μὲν λευκοθώρακες ἐπὶ τοῦ εὐωνύμου τῶν πολεμίων· Τισσαφέρνης ἐλέγετο τούτων ἄρχειν· ἐχόμενοι δὲ γερροφόροι, ἐχόμενοι δὲ ὁπλῖται σὺν ποδήρεσι ξυλίναις ἀσπίσιν. Αἰγύπτιοι δ᾽ οὗτοι ἐλέγοντο εἶναι· ἄλλοι δ᾽ ἱππεῖς, ἄλλοι τοξόται. πάντες δ᾽ οὗτοι κατὰ ἔθνη ἐν πλαισίωι πλήρει ἀνθρώπων ἕκαστον τὸ ἔθνος ἐπορεύετο.", "st": "1.8.9"}, {"sp": "N", "t": "πρὸ δὲ αὐτῶν ἅρματα διαλείποντα συχνὸν ἀπ᾽ ἀλλήλων τὰ δὴ δρεπανηφόρα καλούμενα· εἶχον δὲ τὰ δρέπανα ἐκ τῶν ἀξόνων εἰς πλάγιον ἀποτεταμένα καὶ ὑπὸ τοῖς δίφροις εἰς γῆν βλέποντα, ὡς διακόπτειν ὅτωι ἐντυγχάνοιεν. ἡ δὲ γνώμη ἦν ὡς εἰς τὰς τάξεις τῶν Ἑλλήνων ἐλῶντα καὶ διακόψοντα.", "st": "1.8.10"}, {"sp": "N", "t": "ὃ μέντοι Κῦρος εἶπεν ὅτε καλέσας παρεκελεύετο τοῖς Ἕλλησι τὴν κραυγὴν τῶν βαρβάρων ἀνέχεσθαι, ἐψεύσθη τοῦτο· οὐ γὰρ κραυγῆι ἀλλὰ σιγῆι ὡς ἁνυστὸν καὶ ἡσυχῆι ἐν ἴσωι καὶ βραδέως προσῆισαν.", "st": "1.8.11"}, {"sp": "N", "t": "καὶ ἐν τούτωι Κῦρος παρελαύνων αὐτὸς σὺν Πίγρητι τῶι ἑρμηνεῖ καὶ ἄλλοις τρισὶν ἢ τέτταρσι τῶι Κλεάρχωι ἐβόα ἄγειν τὸ στράτευμα κατὰ μέσον τὸ τῶν πολεμίων, ὅτι ἐκεῖ βασιλεὺς εἴη· κἂν τοῦτ᾽, ἔφη, νικῶμεν, πάνθ᾽ ἡμῖν πεποίηται.", "st": "1.8.12"}, {"sp": "N", "t": "ὁρῶν δὲ ὁ Κλέαρχος τὸ μέσον στῖφος καὶ ἀκούων Κύρου ἔξω ὄντα τοῦ Ἑλληνικοῦ εὐωνύμου βασιλέα (τοσοῦτον γὰρ πλήθει περιῆν βασιλεὺς ὥστε μέσον τῶν ἑαυτοῦ ἔχων τοῦ Κύρου εὐωνύμου ἔξω ἦν) ἀλλ᾽ ὅμως ὁ Κλέαρχος οὐκ ἤθελεν ἀποσπάσαι ἀπὸ τοῦ ποταμοῦ τὸ δεξιὸν κέρας, φοβούμενος μὴ κυκλωθείη ἑκατέρωθεν, τῶι δὲ Κύρωι ἀπεκρίνατο ὅτι αὐτῶι μέλει ὅπως καλῶς ἔχοι.", "st": "1.8.13"}, {"sp": "N", "t": "καὶ ἐν τούτωι τῶι καιρῶι τὸ μὲν βαρβαρικὸν στράτευμα ὁμαλῶς προήιει, τὸ δὲ Ἑλληνικὸν ἔτι ἐν τῶι αὐτῶι μένον συνετάττετο ἐκ τῶν ἔτι προσιόντων. καὶ ὁ Κῦρος παρελαύνων οὐ πάνυ πρὸς αὐτῶι στρατεύματι κατεθεᾶτο ἑκατέρωσε ἀποβλέπων εἴς τε τοὺς πολεμίους καὶ τοὺς φίλους.", "st": "1.8.14"}, {"sp": "N", "t": "ἰδὼν δὲ αὐτὸν ἀπὸ τοῦ Ἑλληνικοῦ Ξενοφῶν Ἀθηναῖος, πελάσας ὡς συναντῆσαι ἤρετο εἴ τι παραγγέλλοι· ὁ δ᾽ ἐπιστήσας εἶπε καὶ λέγειν ἐκέλευε πᾶσιν ὅτι καὶ τὰ ἱερὰ καλὰ καὶ τὰ σφάγια καλά.", "st": "1.8.15"}, {"sp": "N", "t": "ταῦτα δὲ λέγων θορύβου ἤκουσε διὰ τῶν τάξεων ἰόντος, καὶ ἤρετο τίς ὁ θόρυβος εἴη. ὁ δὲ [Κλέαρχος] εἶπεν ὅτι σύνθημα παρέρχεται δεύτερον ἤδη. καὶ ὃς ἐθαύμασε τίς παραγγέλλει καὶ ἤρετο ὅ τι εἴη τὸ σύνθημα. ὁ δ᾽ ἀπεκρίνατο· Ζεὺς σωτὴρ καὶ νίκη.", "st": "1.8.16"}, {"sp": "N", "t": "ὁ δὲ Κῦρος ἀκούσας, «ἀλλὰ δέχομαί τε, ἔφη, καὶ τοῦτο ἔστω.» ταῦτα δ᾽ εἰπὼν εἰς τὴν αὑτοῦ χώραν ἀπήλαυνε. καὶ οὐκέτι τρία ἢ τέτταρα στάδια διειχέτην τὼ φάλαγγε ἀπ᾽ ἀλλήλων ἡνίκα ἐπαιάνιζόν τε οἱ Ἕλληνες καὶ ἤρχοντο ἀντίοι ἰέναι τοῖς πολεμίοις.", "st": "1.8.17"}, {"sp": "N", "t": "ὡς δὲ πορευομένων ἐξεκύμαινέ τι τῆς φάλαγγος, τὸ ὑπολειπόμενον ἤρξατο δρόμωι θεῖν· καὶ ἅμα ἐφθέγξαντο πάντες οἷον τῶι Ἐνυαλίωι ἐλελίζουσι, καὶ πάντες δὲ ἔθεον. λέγουσι δέ τινες ὡς καὶ ταῖς ἀσπίσι πρὸς τὰ δόρατα ἐδούπησαν φόβον ποιοῦντες τοῖς ἵπποις.", "st": "1.8.18"}, {"sp": "N", "t": "πρὶν δὲ τόξευμα ἐξικνεῖσθαι ἐκκλίνουσιν οἱ βάρβαροι καὶ φεύγουσι. καὶ ἐνταῦθα δὴ ἐδίωκον μὲν κατὰ κράτος οἱ Ἕλληνες, ἐβόων δὲ ἀλλήλοις μὴ θεῖν δρόμωι, ἀλλ᾽ ἐν τάξει ἕπεσθαι.", "st": "1.8.19"}, {"sp": "N", "t": "τὰ δ᾽ ἅρματα ἐφέροντο τὰ μὲν δι᾽ αὐτῶν τῶν πολεμίων, τὰ δὲ καὶ διὰ τῶν Ἑλλήνων κενὰ ἡνιόχων. οἱ δ᾽ ἐπεὶ προΐδοιεν, διίσταντο· ἔστι δ᾽ ὅστις καὶ κατελήφθη ὥσπερ ἐν ἱπποδρόμωι ἐκπλαγείς· καὶ οὐδὲν μέντοι οὐδὲ τοῦτον παθεῖν ἔφασαν, οὐδ᾽ ἄλλος δὲ τῶν Ἑλλήνων ἐν ταύτηι τῆι μάχηι ἔπαθεν οὐδεὶς οὐδέν, πλὴν ἐπὶ τῶι εὐωνύμωι τοξευθῆναί τις ἐλέγετο.", "st": "1.8.20"}, {"sp": "N", "t": "Κῦρος δ᾽ ὁρῶν τοὺς Ἕλληνας νικῶντας τὸ καθ᾽ αὑτοὺς καὶ διώκοντας, ἡδόμενος καὶ προσκυνούμενος ἤδη ὡς βασιλεὺς ὑπὸ τῶν ἀμφ᾽ αὐτόν, οὐδ᾽ ὣς ἐξήχθη διώκειν, ἀλλὰ συνεσπειραμένην ἔχων τὴν τῶν σὺν ἑαυτῶι ἑξακοσίων ἱππέων τάξιν ἐπεμελεῖτο ὅ τι ποιήσει βασιλεύς. καὶ γὰρ ἤιδει αὐτὸν ὅτι μέσον ἔχοι τοῦ Περσικοῦ στρατεύματος.", "st": "1.8.21"}, {"sp": "N", "t": "καὶ πάντες δ᾽ οἱ τῶν βαρβάρων ἄρχοντες μέσον ἔχοντες τὸ αὑτῶν ἡγοῦνται, νομίζοντες οὕτω καὶ ἐν ἀσφαλεστάτωι εἶναι, ἢν ἦι ἡ ἰσχὺς αὐτῶν ἑκατέρωθεν, καὶ εἴ τι παραγγεῖλαι χρήιζοιεν, ἡμίσει ἂν χρόνωι αἰσθάνεσθαι τὸ στράτευμα.", "st": "1.8.22"}, {"sp": "N", "t": "καὶ βασιλεὺς δὴ τότε μέσον ἔχων τῆς αὑτοῦ στρατιᾶς ὅμως ἔξω ἐγένετο τοῦ Κύρου εὐωνύμου κέρατος. ἐπεὶ δ᾽ οὐδεὶς αὐτῶι ἐμάχετο ἐκ τοῦ ἀντίου οὐδὲ τοῖς αὐτοῦ τεταγμένοις ἔμπροσθεν, ἐπέκαμπτεν ὡς εἰς κύκλωσιν.", "st": "1.8.23"}, {"sp": "N", "t": "ἔνθα δὴ Κῦρος δείσας μὴ ὄπισθεν γενόμενος κατακόψηι τὸ Ἑλληνικὸν ἐλαύνει ἀντίος· καὶ ἐμβαλὼν σὺν τοῖς ἑξακοσίοις νικᾶι τοὺς πρὸ βασιλέως τεταγμένους καὶ εἰς φυγὴν ἔτρεψε τοὺς ἑξακισχιλίους, καὶ ἀποκτεῖναι λέγεται αὐτὸς τῆι ἑαυτοῦ χειρὶ Ἀρταγέρσην τὸν ἄρχοντα αὐτῶν.", "st": "1.8.24"}, {"sp": "N", "t": "ὡς δ᾽ ἡ τροπὴ ἐγένετο, διασπείρονται καὶ οἱ Κύρου ἑξακόσιοι εἰς τὸ διώκειν ὁρμήσαντες, πλὴν πάνυ ὀλίγοι ἀμφ᾽ αὐτὸν κατελείφθησαν, σχεδὸν οἱ ὁμοτράπεζοι καλούμενοι.", "st": "1.8.25"}, {"sp": "N", "t": "σὺν τούτοις δὲ ὢν καθορᾶι βασιλέα καὶ τὸ ἀμφ᾽ ἐκεῖνον στῖφος· καὶ εὐθὺς οὐκ ἠνέσχετο, ἀλλ᾽ εἰπὼν «τὸν ἄνδρα ὁρῶ» ἵετο ἐπ᾽ αὐτὸν καὶ παίει κατὰ τὸ στέρνον καὶ τιτρώσκει διὰ τοῦ θώρακος, ὥς φησι Κτησίας ὁ ἰατρός, καὶ ἰᾶσθαι αὐτὸς τὸ τραῦμά φησι.", "st": "1.8.26"}, {"sp": "N", "t": "παίοντα δ᾽ αὐτὸν ἀκοντίζει τις παλτῶι ὑπὸ τὸν ὀφθαλμὸν βιαίως· καὶ ἐνταῦθα μαχόμενοι καὶ βασιλεὺς καὶ Κῦρος καὶ οἱ ἀμφ᾽ αὐτοὺς ὑπὲρ ἑκατέρου, ὁπόσοι μὲν τῶν ἀμφὶ βασιλέα ἀπέθνηισκον Κτησίας λέγει· παρ᾽ ἐκείνωι γὰρ ἦν· Κῦρος δὲ αὐτός τε ἀπέθανε καὶ ὀκτὼ οἱ ἄριστοι τῶν περὶ αὐτὸν ἔκειντο ἐπ᾽ αὐτῶι.", "st": "1.8.27"}, {"sp": "N", "t": "Ἀρταπάτης δ᾽ ὁ πιστότατος αὐτῶι τῶν σκηπτούχων θεράπων λέγεται, ἐπειδὴ πεπτωκότα εἶδε Κῦρον, καταπηδήσας ἀπὸ τοῦ ἵππου περιπεσεῖν αὐτῶι.", "st": "1.8.28"}, {"sp": "N", "t": "καὶ οἱ μέν φασι βασιλέα κελεῦσαί τινα ἐπισφάξαι αὐτὸν Κύρωι, οἱ δ᾽ ἑαυτὸν ἐπισφάξασθαι σπασάμενον τὸν ἀκινάκην· εἶχε γὰρ χρυσοῦν· καὶ στρεπτὸν δ᾽ ἐφόρει καὶ ψέλια καὶ τἆλλα ὥσπερ οἱ ἄριστοι Περσῶν· ἐτετίμητο γὰρ ὑπὸ Κύρου δι᾽ εὔνοιάν τε καὶ πιστότητα.", "st": "1.8.29"}, {"sp": "N", "t": "Κῦρος μὲν οὖν οὕτως ἐτελεύτησεν, ἀνὴρ ὢν Περσῶν τῶν μετὰ Κῦρον τὸν ἀρχαῖον γενομένων βασιλικώτατός τε καὶ ἄρχειν ἀξιώτατος, ὡς παρὰ πάντων ὁμολογεῖται τῶν Κύρου δοκούντων ἐν πείραι γενέσθαι.", "st": "1.9.1"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ ἔτι παῖς ὤν, ὅτ᾽ ἐπαιδεύετο καὶ σὺν τῶι ἀδελφῶι καὶ σὺν τοῖς ἄλλοις παισί, πάντων πάντα κράτιστος ἐνομίζετο.", "st": "1.9.2"}, {"sp": "N", "t": "πάντες γὰρ οἱ τῶν ἀρίστων Περσῶν παῖδες ἐπὶ ταῖς βασιλέως θύραις παιδεύονται· ἔνθα πολλὴν μὲν σωφροσύνην καταμάθοι ἄν τις, αἰσχρὸν δ᾽ οὐδὲν οὔτ᾽ ἀκοῦσαι οὔτ᾽ ἰδεῖν ἔστι.", "st": "1.9.3"}, {"sp": "N", "t": "θεῶνται δ᾽ οἱ παῖδες καὶ τιμωμένους ὑπὸ βασιλέως καὶ ἀκούουσι, καὶ ἄλλους ἀτιμαζομένους· ὥστε εὐθὺς παῖδες ὄντες μανθάνουσιν ἄρχειν τε καὶ ἄρχεσθαι.", "st": "1.9.4"}, {"sp": "N", "t": "ἔνθα Κῦρος αἰδημονέστατος μὲν πρῶτον τῶν ἡλικιωτῶν ἐδόκει εἶναι, τοῖς τε πρεσβυτέροις καὶ τῶν ἑαυτοῦ ὑποδεεστέρων μᾶλλον πείθεσθαι, ἔπειτα δὲ φιλιππότατος καὶ τοῖς ἵπποις ἄριστα χρῆσθαι· ἔκρινον δ᾽ αὐτὸν καὶ τῶν εἰς τὸν πόλεμον ἔργων, τοξικῆς τε καὶ ἀκοντίσεως, φιλομαθέστατον εἶναι καὶ μελετηρότατον.", "st": "1.9.5"}, {"sp": "N", "t": "ἐπεὶ δὲ τῆι ἡλικίαι ἔπρεπε, καὶ φιλοθηρότατος ἦν καὶ πρὸς τὰ θηρία μέντοι φιλοκινδυνότατος. καὶ ἄρκτον ποτὲ ἐπιφερομένην οὐκ ἔτρεσεν, ἀλλὰ συμπεσὼν κατεσπάσθη ἀπὸ τοῦ ἵππου, καὶ τὰ μὲν ἔπαθεν, ὧν καὶ τὰς ὠτειλὰς εἶχεν, τέλος δὲ κατέκανε· καὶ τὸν πρῶτον μέντοι βοηθήσαντα πολλοῖς μακαριστὸν ἐποίησεν.", "st": "1.9.6"}, {"sp": "N", "t": "ἐπεὶ δὲ κατεπέμφθη ὑπὸ τοῦ πατρὸς σατράπης Λυδίας τε καὶ Φρυγίας τῆς μεγάλης καὶ Καππαδοκίας, στρατηγὸς δὲ καὶ πάντων ἀπεδείχθη οἷς καθήκει εἰς Καστωλοῦ πεδίον ἁθροίζεσθαι, πρῶτον μὲν ἐπέδειξεν αὑτόν, ὅτι περὶ πλείστου ποιοῖτο, εἴ τωι σπείσαιτο καὶ εἴ τωι συνθοῖτο καὶ εἴ τωι ὑπόσχοιτό τι, μηδὲν ψεύδεσθαι.", "st": "1.9.7"}, {"sp": "N", "t": "καὶ γὰρ οὖν ἐπίστευον μὲν αὐτῶι αἱ πόλεις ἐπιτρεπόμεναι, ἐπίστευον δ᾽ οἱ ἄνδρες· καὶ εἴ τις πολέμιος ἐγένετο, σπεισαμένου Κύρου ἐπίστευε μηδὲν ἂν παρὰ τὰς σπονδὰς παθεῖν.", "st": "1.9.8"}, {"sp": "N", "t": "τοιγαροῦν ἐπεὶ Τισσαφέρνει ἐπολέμησε, πᾶσαι αἱ πόλεις ἑκοῦσαι Κῦρον εἵλοντο ἀντὶ Τισσαφέρνους πλὴν Μιλησίων· οὗτοι δὲ ὅτι οὐκ ἤθελε τοὺς φεύγοντας προέσθαι ἐφοβοῦντο αὐτόν.", "st": "1.9.9"}, {"sp": "N", "t": "καὶ γὰρ ἔργωι ἐπεδείκνυτο καὶ ἔλεγεν ὅτι οὐκ ἄν ποτε προοῖτο, ἐπεὶ ἅπαξ φίλος αὐτοῖς ἐγένετο, οὐδ᾽ εἰ ἔτι μὲν μείους γένοιντο, ἔτι δὲ κάκιον πράξειαν.", "st": "1.9.10"}, {"sp": "N", "t": "φανερὸς δ᾽ ἦν καὶ εἴ τίς τι ἀγαθὸν ἢ κακὸν ποιήσειεν αὐτόν, νικᾶν πειρώμενος· καὶ εὐχὴν δέ τινες αὐτοῦ ἐξέφερον ὡς εὔχοιτο τοσοῦτον χρόνον ζῆν ἔστε νικώιη καὶ τοὺς εὖ καὶ κακῶς ποιοῦντας ἀλεξόμενος.", "st": "1.9.11"}, {"sp": "N", "t": "καὶ γὰρ οὖν πλεῖστοι δὴ αὐτῶι ἑνί γε ἀνδρὶ τῶν ἐφ᾽ ἡμῶν ἐπεθύμησαν καὶ χρήματα καὶ πόλεις καὶ τὰ ἑαυτῶν σώματα προέσθαι.", "st": "1.9.12"}, {"sp": "N", "t": "οὐ μὲν δὴ οὐδὲ τοῦτ᾽ ἄν τις εἴποι, ὡς τοὺς κακούργους καὶ ἀδίκους εἴα καταγελᾶν, ἀλλὰ ἀφειδέστατα πάντων ἐτιμωρεῖτο· πολλάκις δ᾽ ἦν ἰδεῖν παρὰ τὰς στειβομένας ὁδοὺς καὶ ποδῶν καὶ χειρῶν καὶ ὀφθαλμῶν στερομένους ἀνθρώπους· ὥστ᾽ ἐν τῆι Κύρου ἀρχῆι ἐγένετο καὶ Ἕλληνι καὶ βαρβάρωι μηδὲν ἀδικοῦντι ἀδεῶς πορεύεσθαι ὅπηι τις ἤθελεν, ἔχοντι ὅ τι προχωροίη.", "st": "1.9.13"}, {"sp": "N", "t": "τούς γε μέντοι ἀγαθοὺς εἰς πόλεμον ὡμολόγητο διαφερόντως τιμᾶν. καὶ πρῶτον μὲν ἦν αὐτῶι πόλεμος πρὸς Πισίδας καὶ Μυσούς· στρατευόμενος οὖν καὶ αὐτὸς εἰς ταύτας τὰς χώρας, οὓς ἑώρα ἐθέλοντας κινδυνεύειν, τούτους καὶ ἄρχοντας ἐποίει ἧς κατεστρέφετο χώρας, ἔπειτα δὲ καὶ ἄλλοις δώροις ἐτίμα·", "st": "1.9.14"}, {"sp": "N", "t": "ὥστε φαίνεσθαι τοὺς μὲν ἀγαθοὺς εὐδαιμονεστάτους, τοὺς δὲ κακοὺς δούλους τούτων ἀξιοῦσθαι εἶναι. τοιγαροῦν πολλὴ ἦν ἀφθονία αὐτῶι τῶν ἐθελόντων κινδυνεύειν, ὅπου τις οἴοιτο Κῦρον αἰσθήσεσθαι.", "st": "1.9.15"}, {"sp": "N", "t": "εἴς γε μὴν δικαιοσύνην εἴ τις φανερὸς γένοιτο ἐπιδείκνυσθαι βουλόμενος, περὶ παντὸς ἐποιεῖτο τούτους πλουσιωτέρους ποιεῖν τῶν ἐκ τοῦ ἀδίκου φιλοκερδούντων.", "st": "1.9.16"}, {"sp": "N", "t": "καὶ γὰρ οὖν ἄλλα τε πολλὰ δικαίως αὐτῶι διεχειρίζετο καὶ στρατεύματι ἀληθινῶι ἐχρήσατο. καὶ γὰρ στρατηγοὶ καὶ λοχαγοί, οἳ χρημάτων ἕνεκα πρὸς ἐκεῖνον ἔπλευσαν, ἔγνωσαν κερδαλεώτερον εἶναι Κύρωι καλῶς πειθαρχεῖν ἢ τὸ κατὰ μῆνα κέρδος.", "st": "1.9.17"}, {"sp": "N", "t": "ἀλλὰ μὴν εἴ τίς γέ τι αὐτῶι προστάξαντι καλῶς ὑπηρετήσειεν, οὐδενὶ πώποτε ἀχάριστον εἴασε τὴν προθυμίαν. τοιγαροῦν δὴ κράτιστοι ὑπηρέται παντὸς ἔργου Κύρωι ἐλέχθησαν γενέσθαι.", "st": "1.9.18"}, {"sp": "N", "t": "εἰ δέ τινα ὁρώιη δεινὸν ὄντα οἰκονόμον ἐκ τοῦ δικαίου καὶ κατασκευάζοντά τε ἧς ἄρχοι χώρας καὶ προσόδους ποιοῦντα, οὐδένα ἂν πώποτε ἀφείλετο, ἀλλ᾽ ἀεὶ πλείω προσεδίδου· ὥστε καὶ ἡδέως ἐπόνουν καὶ θαρραλέως ἐκτῶντο καὶ ὃ ἐπέπατο αὖ τις ἥκιστα Κῦρον ἔκρυπτεν· οὐ γὰρ φθονῶν τοῖς φανερῶς πλουτοῦσιν ἐφαίνετο, ἀλλὰ πειρώμενος χρῆσθαι τοῖς τῶν ἀποκρυπτομένων χρήμασι.", "st": "1.9.19"}, {"sp": "N", "t": "φίλους γε μήν, ὅσους ποιήσαιτο καὶ εὔνους γνοίη ὄντας καὶ ἱκανοὺς κρίνειε συνεργοὺς εἶναι ὅ τι τυγχάνει βουλόμενος κατεργάζεσθαι, ὁμολογεῖται πρὸς πάντων κράτιστος δὴ γενέσθαι θεραπεύειν.", "st": "1.9.20"}, {"sp": "N", "t": "καὶ γὰρ αὐτὸ τοῦτο οὗπερ αὐτὸς ἕνεκα φίλων ὤιετο δεῖσθαι, ὡς συνεργοὺς ἔχοι, καὶ αὐτὸς ἐπειρᾶτο συνεργὸς τοῖς φίλοις κράτιστος εἶναι τούτου ὅτου αἰσθάνοιτο ἕκαστον ἐπιθυμοῦντα.", "st": "1.9.21"}, {"sp": "N", "t": "δῶρα δὲ πλεῖστα μὲν οἶμαι εἷς γε ἀνὴρ ἐλάμβανε διὰ πολλά· ταῦτα δὲ πάντων δὴ μάλιστα τοῖς φίλοις διεδίδου, πρὸς τοὺς τρόπους ἑκάστου σκοπῶν καὶ ὅτου μάλιστα ὁρώιη ἕκαστον δεόμενον.", "st": "1.9.22"}, {"sp": "N", "t": "καὶ ὅσα τῶι σώματι αὐτοῦ πέμποι τις ἢ ὡς εἰς πόλεμον ἢ ὡς εἰς καλλωπισμόν, καὶ περὶ τούτων λέγειν αὐτὸν ἔφασαν ὅτι τὸ μὲν ἑαυτοῦ σῶμα οὐκ ἂν δύναιτο τούτοις πᾶσι κοσμηθῆναι, φίλους δὲ καλῶς κεκοσμημένους μέγιστον κόσμον ἀνδρὶ νομίζοι.", "st": "1.9.23"}, {"sp": "N", "t": "καὶ τὸ μὲν τὰ μεγάλα νικᾶν τοὺς φίλους εὖ ποιοῦντα οὐδὲν θαυμαστόν, ἐπειδή γε καὶ δυνατώτερος ἦν· τὸ δὲ τῆι ἐπιμελείαι περιεῖναι τῶν φίλων καὶ τῶι προθυμεῖσθαι χαρίζεσθαι, ταῦτα ἔμοιγε μᾶλλον δοκεῖ ἀγαστὰ εἶναι.", "st": "1.9.24"}, {"sp": "N", "t": "Κῦρος γὰρ ἔπεμπε βίκους οἴνου ἡμιδεεῖς πολλάκις ὁπότε πάνυ ἡδὺν λάβοι, λέγων ὅτι οὔπω δὴ πολλοῦ χρόνου τούτου ἡδίονι οἴνωι ἐπιτύχοι· «τοῦτον οὖν σοὶ ἔπεμψε καὶ δεῖταί σου τήμερον τοῦτον ἐκπιεῖν σὺν οἷς μάλιστα φιλεῖς.»", "st": "1.9.25"}, {"sp": "N", "t": "πολλάκις δὲ χῆνας ἡμιβρώτους ἔπεμπε καὶ ἄρτων ἡμίσεα καὶ ἄλλα τοιαῦτα, ἐπιλέγειν κελεύων τὸν φέροντα· «τούτοις ἥσθη Κῦρος· βούλεται οὖν καὶ σὲ τούτων γεύσασθαι.»", "st": "1.9.26"}, {"sp": "N", "t": "ὅπου δὲ χιλὸς σπάνιος πάνυ εἴη, αὐτὸς δὲ δύναιτο παρασκευάσασθαι διὰ τὸ πολλοὺς ἔχειν ὑπηρέτας καὶ διὰ τὴν ἐπιμέλειαν, διαπέμπων ἐκέλευε τοὺς φίλους τοῖς τὰ ἑαυτῶν σώματα ἄγουσιν ἵπποις ἐμβάλλειν τοῦτον τὸν χιλόν, ὡς μὴ πεινῶντες τοὺς ἑαυτοῦ φίλους ἄγωσιν.", "st": "1.9.27"}, {"sp": "N", "t": "εἰ δὲ δή ποτε πορεύοιτο καὶ πλεῖστοι μέλλοιεν ὄψεσθαι, προσκαλῶν τοὺς φίλους ἐσπουδαιολογεῖτο, ὡς δηλοίη οὓς τιμᾶι. ὥστε ἐγὼ μέν γε, ἐξ ὧν ἀκούω, οὐδένα κρίνω ὑπὸ πλειόνων πεφιλῆσθαι οὔτε Ἑλλήνων οὔτε βαρβάρων.", "st": "1.9.28"}, {"sp": "N", "t": "τεκμήριον δὲ τούτου καὶ τόδε. παρὰ μὲν Κύρου δούλου ὄντος οὐδεὶς ἀπήιει πρὸς βασιλέα, πλὴν Ὀρόντας ἐπεχείρησε· καὶ οὗτος δὴ ὃν ὤιετο πιστόν οἱ εἶναι ταχὺ αὐτὸν ηὗρε Κύρωι φίλτερον ἢ ἑαυτῶι· παρὰ δὲ βασιλέως πολλοὶ πρὸς Κῦρον ἀπῆλθον, ἐπειδὴ πολέμιοι ἀλλήλοις ἐγένοντο, καὶ οὗτοι μέντοι οἱ μάλιστα ὑπ᾽ αὐτοῦ ἀγαπώμενοι, νομίζοντες παρὰ Κύρωι ὄντες ἀγαθοὶ ἀξιωτέρας ἂν τιμῆς τυγχάνειν ἢ παρὰ βασιλεῖ.", "st": "1.9.29"}, {"sp": "N", "t": "μέγα δὲ τεκμήριον καὶ τὸ ἐν τῆι τελευτῆι τοῦ βίου αὐτῶι γενόμενον ὅτι καὶ αὐτὸς ἦν ἀγαθὸς καὶ κρίνειν ὀρθῶς ἐδύνατο τοὺς πιστοὺς καὶ εὔνους καὶ βεβαίους.", "st": "1.9.30"}, {"sp": "N", "t": "ἀποθνήισκοντος γὰρ αὐτοῦ πάντες οἱ περὶ αὐτὸν φίλοι καὶ συντράπεζοι ἀπέθανον μαχόμενοι ὑπὲρ Κύρου πλὴν Ἀριαίου· οὗτος δὲ τεταγμένος ἐτύγχανεν ἐπὶ τῶι εὐωνύμωι τοῦ ἱππικοῦ ἄρχων· ὡς δ᾽ ἤισθετο Κῦρον πεπτωκότα, ἔφυγεν ἔχων καὶ τὸ στράτευμα πᾶν οὗ ἡγεῖτο.", "st": "1.9.31"}, {"sp": "N", "t": "ἐνταῦθα δὴ Κύρου ἀποτέμνεται ἡ κεφαλὴ καὶ ἡ χεὶρ ἡ δεξιά. βασιλεὺς δὲ [καὶ οἱ σὺν αὐτῶι] διώκων εἰσπίπτει εἰς τὸ Κύρειον στρατόπεδον· καὶ οἱ μὲν μετὰ Ἀριαίου οὐκέτι ἵστανται, ἀλλὰ φεύγουσι διὰ τοῦ αὑτῶν στρατοπέδου εἰς τὸν σταθμὸν ἔνθεν ὡρμῶντο· τέτταρες δ᾽ ἐλέγοντο παρασάγγαι εἶναι τῆς ὁδοῦ.", "st": "1.10.1"}, {"sp": "N", "t": "βασιλεὺς δὲ καὶ οἱ σὺν αὐτῶι τά τε ἄλλα πολλὰ διαρπάζουσι καὶ τὴν Φωκαΐδα τὴν Κύρου παλλακίδα τὴν σοφὴν καὶ καλὴν λεγομένην εἶναι λαμβάνει.", "st": "1.10.2"}, {"sp": "N", "t": "ἡ δὲ Μιλησία ἡ νεωτέρα ληφθεῖσα ὑπὸ τῶν ἀμφὶ βασιλέα ἐκφεύγει γυμνὴ πρὸς τῶν Ἑλλήνων οἳ ἔτυχον ἐν τοῖς σκευοφόροις ὅπλα ἔχοντες καὶ ἀντιταχθέντες πολλοὺς μὲν τῶν ἁρπαζόντων ἀπέκτειναν, οἱ δὲ καὶ αὐτῶν ἀπέθανον· οὐ μὴν ἔφυγόν γε, ἀλλὰ καὶ ταύτην ἔσωσαν καὶ τἆλλα, ὁπόσα ἐντὸς αὐτῶν καὶ χρήματα καὶ ἄνθρωποι ἐγένοντο, πάντα ἔσωσαν.", "st": "1.10.3"}, {"sp": "N", "t": "ἐνταῦθα διέσχον ἀλλήλων βασιλεύς τε καὶ οἱ Ἕλληνες ὡς τριάκοντα στάδια, οἱ μὲν διώκοντες τοὺς καθ᾽ αὑτοὺς ὡς πάντας νικῶντες, οἱ δ᾽ ἁρπάζοντες ὡς ἤδη πάντες νικῶντες.", "st": "1.10.4"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἤισθοντο οἱ μὲν Ἕλληνες ὅτι βασιλεὺς σὺν τῶι στρατεύματι ἐν τοῖς σκευοφόροις εἴη, βασιλεὺς δ᾽ αὖ ἤκουσε Τισσαφέρνους ὅτι οἱ Ἕλληνες νικῶιεν τὸ καθ᾽ αὑτοὺς καὶ εἰς τὸ πρόσθεν οἴχονται διώκοντες, ἔνθα δὴ βασιλεὺς μὲν ἁθροίζει τε τοὺς ἑαυτοῦ καὶ συντάττεται, ὁ δὲ Κλέαρχος ἐβουλεύετο Πρόξενον καλέσας (πλησιαίτατος γὰρ ἦν), εἰ πέμποιέν τινας ἢ πάντες ἴοιεν ἐπὶ τὸ στρατόπεδον ἀρήξοντες.", "st": "1.10.5"}, {"sp": "N", "t": "ἐν τούτωι καὶ βασιλεὺς δῆλος ἦν προσιὼν πάλιν, ὡς ἐδόκει, ὄπισθεν. καὶ οἱ μὲν Ἕλληνες στραφέντες παρεσκευάζοντο ὡς ταύτηι προσιόντος καὶ δεξόμενοι, ὁ δὲ βασιλεὺς ταύτηι μὲν οὐκ ἦγεν, ἧι δὲ παρῆλθεν ἔξω τοῦ εὐωνύμου κέρατος ταύτηι καὶ ἀπῆγεν, ἀναλαβὼν καὶ τοὺς ἐν τῆι μάχηι πρὸς τοὺς Ἕλληνας αὐτομολήσαντας καὶ Τισσαφέρνην καὶ τοὺς σὺν αὐτῶι.", "st": "1.10.6"}, {"sp": "N", "t": "ὁ γὰρ Τισσαφέρνης ἐν τῆι πρώτηι συνόδωι οὐκ ἔφυγεν, ἀλλὰ διήλασε παρὰ τὸν ποταμὸν κατὰ τοὺς Ἕλληνας πελταστάς· διελαύνων δὲ κατέκανε μὲν οὐδένα, διαστάντες δ᾽ οἱ Ἕλληνες ἔπαιον καὶ ἠκόντιζον αὐτούς· Ἐπισθένης δὲ Ἀμφιπολίτης ἦρχε τῶν πελταστῶν καὶ ἐλέγετο φρόνιμος γενέσθαι.", "st": "1.10.7"}, {"sp": "N", "t": "ὁ δ᾽ οὖν Τισσαφέρνης ὡς μεῖον ἔχων ἀπηλλάγη, πάλιν μὲν οὐκ ἀναστρέφει, εἰς δὲ τὸ στρατόπεδον ἀφικόμενος τὸ τῶν Ἑλλήνων ἐκεῖ συντυγχάνει βασιλεῖ, καὶ ὁμοῦ δὴ πάλιν συνταξάμενοι ἐπορεύοντο.", "st": "1.10.8"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἦσαν κατὰ τὸ εὐώνυμον τῶν Ἑλλήνων κέρας, ἔδεισαν οἱ Ἕλληνες μὴ προσάγοιεν πρὸς τὸ κέρας καὶ περιπτύξαντες ἀμφοτέρωθεν αὐτοὺς κατακόψειαν· καὶ ἐδόκει αὐτοῖς ἀναπτύσσειν τὸ κέρας καὶ ποιήσασθαι ὄπισθεν τὸν ποταμόν.", "st": "1.10.9"}, {"sp": "N", "t": "ἐν ὧι δὲ ταῦτα ἐβουλεύοντο, καὶ δὴ βασιλεὺς παραμειψάμενος εἰς τὸ αὐτὸ σχῆμα κατέστησεν ἀντίαν τὴν φάλαγγα ὥσπερ τὸ πρῶτον μαχούμενος συνήιει. ὡς δὲ εἶδον οἱ Ἕλληνες ἐγγύς τε ὄντας καὶ παρατεταγμένους, αὖθις παιανίσαντες ἐπῆισαν πολὺ ἔτι προθυμότερον ἢ τὸ πρόσθεν.", "st": "1.10.10"}, {"sp": "N", "t": "οἱ δ᾽ αὖ βάρβαροι οὐκ ἐδέχοντο, ἀλλὰ ἐκ πλέονος ἢ τὸ πρόσθεν ἔφευγον·", "st": "1.10.11"}, {"sp": "N", "t": "οἱ δ᾽ ἐπεδίωκον μέχρι κώμης τινός· ἐνταῦθα δ᾽ ἔστησαν οἱ Ἕλληνες· ὑπὲρ γὰρ τῆς κώμης γήλοφος ἦν, ἐφ᾽ οὗ ἀνεστράφησαν οἱ ἀμφὶ βασιλέα, πεζοὶ μὲν οὐκέτι, τῶν δὲ ἱππέων ὁ λόφος ἐνεπλήσθη, ὥστε τὸ ποιούμενον μὴ γιγνώσκειν. καὶ τὸ βασίλειον σημεῖον ὁρᾶν ἔφασαν αἰετόν τινα χρυσοῦν ἐπὶ πέλτηι ἐπὶ ξύλου ἀνατεταμένον.", "st": "1.10.12"}, {"sp": "N", "t": "ἐπεὶ δὲ καὶ ἐνταῦθ᾽ ἐχώρουν οἱ Ἕλληνες, λείπουσι δὴ καὶ τὸν λόφον οἱ ἱππεῖς· οὐ μὴν ἔτι ἁθρόοι ἀλλ᾽ ἄλλοι ἄλλοθεν· ἐψιλοῦτο δ᾽ ὁ λόφος τῶν ἱππέων· τέλος δὲ καὶ πάντες ἀπεχώρησαν.", "st": "1.10.13"}, {"sp": "N", "t": "ὁ οὖν Κλέαρχος οὐκ ἀνεβίβαζεν ἐπὶ τὸν λόφον, ἀλλ᾽ ὑπ᾽ αὐτὸν στήσας τὸ στράτευμα πέμπει Λύκιον τὸν Συρακόσιον καὶ ἄλλον ἐπὶ τὸν λόφον καὶ κελεύει κατιδόντας τὰ ὑπὲρ τοῦ λόφου τί ἐστιν ἀπαγγεῖλαι.", "st": "1.10.14"}, {"sp": "N", "t": "καὶ ὁ Λύκιος ἤλασέ τε καὶ ἰδὼν ἀπαγγέλλει ὅτι φεύγουσιν ἀνὰ κράτος.", "st": "1.10.15"}, {"sp": "N", "t": "σχεδὸν δ᾽ ὅτε ταῦτα ἦν καὶ ἥλιος ἐδύετο. ἐνταῦθα δ᾽ ἔστησαν οἱ Ἕλληνες καὶ θέμενοι τὰ ὅπλα ἀνεπαύοντο· καὶ ἅμα μὲν ἐθαύμαζον ὅτι οὐδαμοῦ Κῦρος φαίνοιτο οὐδ᾽ ἄλλος ἀπ᾽ αὐτοῦ οὐδεὶς παρήιει· οὐ γὰρ ἤιδεσαν αὐτὸν τεθνηκότα, ἀλλ᾽ εἴκαζον ἢ διώκοντα οἴχεσθαι ἢ καταληψόμενόν τι προεληλακέναι·", "st": "1.10.16"}, {"sp": "N", "t": "καὶ αὐτοὶ ἐβουλεύοντο εἰ αὐτοῦ μείναντες τὰ σκευοφόρα ἐνταῦθα ἄγοιντο ἢ ἀπίοιεν ἐπὶ τὸ στρατόπεδον. ἔδοξεν αὐτοῖς ἀπιέναι· καὶ ἀφικνοῦνται ἀμφὶ δορπηστὸν ἐπὶ τὰς σκηνάς.", "st": "1.10.17"}, {"sp": "N", "t": "ταύτης μὲν τῆς ἡμέρας τοῦτο τὸ τέλος ἐγένετο. καταλαμβάνουσι δὲ τῶν τε ἄλλων χρημάτων τὰ πλεῖστα διηρπασμένα καὶ εἴ τι σιτίον ἢ ποτὸν ἦν, καὶ τὰς ἁμάξας μεστὰς ἀλεύρων καὶ οἴνου, ἃς παρεσκευάσατο Κῦρος, ἵνα εἴ ποτε σφόδρα τὸ στράτευμα λάβοι ἔνδεια, διαδιδοίη τοῖς Ἕλλησιν (ἦσαν δ᾽ αὗται τετρακόσιαι, ὡς ἐλέγοντο, ἅμαξαι), καὶ ταύτας τότε οἱ σὺν βασιλεῖ διήρπασαν.", "st": "1.10.18"}, {"sp": "N", "t": "ὥστε ἄδειπνοι ἦσαν οἱ πλεῖστοι τῶν Ἑλλήνων· ἦσαν δὲ καὶ ἀνάριστοι· πρὶν γὰρ δὴ καταλῦσαι τὸ στράτευμα πρὸς ἄριστον βασιλεὺς ἐφάνη. ταύτην μὲν οὖν τὴν νύκτα οὕτω διεγένοντο.", "st": "1.10.19"}, {"sp": "HDR", "t": "Βιβλίον βʹ", "st": "2.1.1"}, {"sp": "N", "t": "[Ὡς μὲν οὖν ἡθροίσθη Κύρωι τὸ Ἑλληνικὸν ὅτε ἐπὶ τὸν ἀδελφὸν Ἀρταξέρξην ἐστρατεύετο, καὶ ὅσα ἐν τῆι ἀνόδωι ἐπράχθη καὶ ὡς ἡ μάχη ἐγένετο καὶ ὡς Κῦρος ἐτελεύτησε καὶ ὡς ἐπὶ τὸ στρατόπεδον ἐλθόντες οἱ Ἕλληνες ἐκοιμήθησαν οἰόμενοι τὰ πάντα νικᾶν καὶ Κῦρον ζῆν, ἐν τῶι πρόσθεν λόγωι δεδήλωται.]", "st": "2.1.1"}, {"sp": "N", "t": "Ἅμα δὲ τῆι ἡμέραι συνελθόντες οἱ στρατηγοὶ ἐθαύμαζον ὅτι Κῦρος οὔτε ἄλλον πέμπει σημανοῦντα ὅ τι χρὴ ποιεῖν οὔτε αὐτὸς φαίνοιτο. ἔδοξεν οὖν αὐτοῖς συσκευασαμένοις ἃ εἶχον καὶ ἐξοπλισαμένοις προϊέναι εἰς τὸ πρόσθεν, ἕως Κύρωι συμμείξειαν.", "st": "2.1.2"}, {"sp": "N", "t": "ἤδη δὲ ἐν ὁρμῆι ὄντων ἅμα ἡλίωι ἀνέχοντι ἦλθε Προκλῆς ὁ Τευθρανίας ἄρχων, γεγονὼς ἀπὸ Δαμαράτου τοῦ Λάκωνος, καὶ Γλοῦς ὁ Ταμώ. οὗτοι ἔλεγον ὅτι Κῦρος μὲν τέθνηκεν, Ἀριαῖος δὲ πεφευγὼς ἐν τῶι σταθμῶι εἴη μετὰ τῶν ἄλλων βαρβάρων ὅθεν τῆι προτεραίαι ὡρμῶντο, καὶ λέγει ὅτι ταύτην μὲν τὴν ἡμέραν περιμένοιεν αὐτούς, εἰ μέλλοιεν ἥκειν, τῆι δὲ ἄλληι ἀπιέναι φαίη ἐπὶ Ἰωνίας, ὅθενπερ ἦλθε.", "st": "2.1.3"}, {"sp": "N", "t": "ταῦτα ἀκούσαντες οἱ στρατηγοὶ καὶ οἱ ἄλλοι Ἕλληνες πυνθανόμενοι βαρέως ἔφερον. Κλέαρχος δὲ τάδε εἶπεν· «ἀλλ᾽ ὤφελε μὲν Κῦρος ζῆν· ἐπεὶ δὲ τετελεύτηκεν, ἀπαγγέλλετε Ἀριαίωι ὅτι ἡμεῖς νικῶμέν τε βασιλέα καί, ὡς ὁρᾶτε, οὐδεὶς ἔτι ἡμῖν μάχεται, καί, εἰ μὴ ὑμεῖς ἤλθετε, ἐπορευόμεθα ἂν ἐπὶ βασιλέα. ἐπαγγελλόμεθα δὲ Ἀριαίωι, ἐὰν ἐνθάδε ἔλθηι, εἰς τὸν θρόνον τὸν βασίλειον καθιεῖν αὐτόν· τῶν γὰρ μάχην νικώντων καὶ τὸ ἄρχειν ἐστί.»", "st": "2.1.4"}, {"sp": "N", "t": "ταῦτα εἰπὼν ἀποστέλλει τοὺς ἀγγέλους καὶ σὺν αὐτοῖς Χειρίσοφον τὸν Λάκωνα καὶ Μένωνα τὸν Θετταλόν· καὶ γὰρ αὐτὸς Μένων ἐβούλετο· ἦν γὰρ φίλος καὶ ξένος Ἀριαίου.", "st": "2.1.5"}, {"sp": "N", "t": "οἱ μὲν ὤιχοντο, Κλέαρχος δὲ περιέμενε· τὸ δὲ στράτευμα ἐπορίζετο σῖτον, ὅπως ἐδύνατο, ἐκ τῶν ὑποζυγίων κόπτοντες τοὺς βοῦς καὶ ὄνους· ξύλοις δὲ ἐχρῶντο μικρὸν προϊόντες ἀπὸ τῆς φάλαγγος, οὗ ἡ μάχη ἐγένετο, τοῖς τε οἰστοῖς πολλοῖς οὖσιν, οὓς ἠνάγκαζον οἱ Ἕλληνες ἐκβάλλειν τοὺς αὐτομολοῦντας παρὰ βασιλέως, καὶ τοῖς γέρροις καὶ ταῖς ἀσπίσι ταῖς ξυλίναις ταῖς Αἰγυπτίαις· πολλαὶ δὲ καὶ πέλται καὶ ἅμαξαι ἦσαν φέρεσθαι ἔρημοι· οἷς πᾶσι χρώμενοι κρέα ἕψοντες ἤσθιον ἐκείνην τὴν ἡμέραν.", "st": "2.1.6"}, {"sp": "N", "t": "καὶ ἤδη τε ἦν περὶ πλήθουσαν ἀγορὰν καὶ ἔρχονται παρὰ βασιλέως καὶ Τισσαφέρνους κήρυκες οἱ μὲν ἄλλοι βάρβαροι, ἦν δ᾽ αὐτῶν Φαλῖνος εἷς Ἕλλην, ὃς ἐτύγχανε παρὰ Τισσαφέρνει ὢν καὶ ἐντίμως ἔχων· καὶ γὰρ προσεποιεῖτο ἐπιστήμων εἶναι τῶν ἀμφὶ τάξεις τε καὶ ὁπλομαχίαν.", "st": "2.1.7"}, {"sp": "N", "t": "οὗτοι δὲ προσελθόντες καὶ καλέσαντες τοὺς τῶν Ἑλλήνων ἄρχοντας λέγουσιν ὅτι βασιλεὺς κελεύει τοὺς Ἕλληνας, ἐπεὶ νικῶν τυγχάνει καὶ Κῦρον ἀπέκτονε, παραδόντας τὰ ὅπλα ἰόντας ἐπὶ βασιλέως θύρας εὑρίσκεσθαι ἄν τι δύνωνται ἀγαθόν.", "st": "2.1.8"}, {"sp": "N", "t": "ταῦτα μὲν εἶπον οἱ βασιλέως κήρυκες· οἱ δὲ Ἕλληνες βαρέως μὲν ἤκουσαν, ὅμως δὲ Κλέαρχος τοσοῦτον εἶπεν, ὅτι οὐ τῶν νικώντων εἴη τὰ ὅπλα παραδιδόναι· ἀλλ᾽, ἔφη, ὑμεῖς μέν, ὦ ἄνδρες στρατηγοί, τούτοις ἀποκρίνασθε ὅ τι κάλλιστόν τε καὶ ἄριστον ἔχετε· ἐγὼ δὲ αὐτίκα ἥξω. ἐκάλεσε γάρ τις αὐτὸν τῶν ὑπηρετῶν, ὅπως ἴδοι τὰ ἱερὰ ἐξηιρημένα· ἔτυχε γὰρ θυόμενος.", "st": "2.1.9"}, {"sp": "N", "t": "ἔνθα δὴ ἀπεκρίνατο Κλεάνωρ ὁ Ἀρκάς, πρεσβύτατος ὤν, ὅτι πρόσθεν ἂν ἀποθάνοιεν ἢ τὰ ὅπλα παραδοίησαν· Πρόξενος δὲ ὁ Θηβαῖος, «ἀλλ᾽ ἐγώ, ἔφη, ὦ Φαλῖνε, θαυμάζω πότερα ὡς κρατῶν βασιλεὺς αἰτεῖ τὰ ὅπλα ἢ ὡς διὰ φιλίαν δῶρα. εἰ μὲν γὰρ ὡς κρατῶν, τί δεῖ αὐτὸν αἰτεῖν καὶ οὐ λαβεῖν ἐλθόντα; εἰ δὲ πείσας βούλεται λαβεῖν, λεγέτω τί ἔσται τοῖς στρατιώταις, ἐὰν αὐτῶι ταῦτα χαρίσωνται.»", "st": "2.1.10"}, {"sp": "N", "t": "πρὸς ταῦτα Φαλῖνος εἶπε· «βασιλεὺς νικᾶν ἡγεῖται, ἐπεὶ Κῦρον ἀπέκτεινε. τίς γὰρ αὐτῶι ἔστιν ὅστις τῆς ἀρχῆς ἀντιποιεῖται; νομίζει δὲ καὶ ὑμᾶς ἑαυτοῦ εἶναι, ἔχων ἐν μέσηι τῆι ἑαυτοῦ χώραι καὶ ποταμῶν ἐντὸς ἀδιαβάτων καὶ πλῆθος ἀνθρώπων ἐφ᾽ ὑμᾶς δυνάμενος ἀγαγεῖν, ὅσον οὐδ᾽ εἰ παρέχοι ὑμῖν δύναισθε ἂν ἀποκτεῖναι.»", "st": "2.1.11"}, {"sp": "N", "t": "μετὰ τοῦτον Θεόπομπος Ἀθηναῖος εἶπεν· «ὦ Φαλῖνε, νῦν, ὡς σὺ ὁρᾶις, ἡμῖν οὐδὲν ἔστιν ἀγαθὸν ἄλλο εἰ μὴ ὅπλα καὶ ἀρετή. ὅπλα μὲν οὖν ἔχοντες οἰόμεθα ἂν καὶ τῆι ἀρετῆι χρῆσθαι, παραδόντες δ᾽ ἂν ταῦτα καὶ τῶν σωμάτων στερηθῆναι. μὴ οὖν οἴου τὰ μόνα ἀγαθὰ ἡμῖν ὄντα ὑμῖν παραδώσειν, ἀλλὰ σὺν τούτοις καὶ περὶ τῶν ὑμετέρων ἀγαθῶν μαχούμεθα.»", "st": "2.1.12"}, {"sp": "N", "t": "ἀκούσας δὲ ταῦτα ὁ Φαλῖνος ἐγέλασε καὶ εἶπεν· «ἀλλὰ φιλοσόφωι μὲν ἔοικας, ὦ νεανίσκε, καὶ λέγεις οὐκ ἀχάριστα· ἴσθι μέντοι ἀνόητος ὤν, εἰ οἴει τὴν ὑμετέραν ἀρετὴν περιγενέσθαι ἂν τῆς βασιλέως δυνάμεως.»", "st": "2.1.13"}, {"sp": "N", "t": "ἄλλους δέ τινας ἔφασαν λέγειν ὑπομαλακιζομένους, ὡς καὶ Κύρωι πιστοὶ ἐγένοντο καὶ βασιλεῖ ἂν πολλοῦ ἄξιοι γένοιντο, εἰ βούλοιτο φίλος γενέσθαι· καὶ εἴτε ἄλλο τι θέλοι χρῆσθαι εἴτ᾽ ἐπ᾽ Αἴγυπτον στρατεύειν, συγκαταστρέψαιντ᾽ ἂν αὐτῶι.", "st": "2.1.14"}, {"sp": "N", "t": "ἐν τούτωι Κλέαρχος ἧκε, καὶ ἠρώτησεν εἰ ἤδη ἀποκεκριμένοι εἶεν. Φαλῖνος δὲ ὑπολαβὼν εἶπεν· «οὗτοι μέν, ὦ Κλέαρχε, ἄλλος ἄλλα λέγει· σὺ δ᾽ ἡμῖν εἰπὲ τί λέγεις.»", "st": "2.1.15"}, {"sp": "N", "t": "ὁ δ᾽ εἶπεν· «ἐγώ σε, ὦ Φαλῖνε, ἄσμενος ἑόρακα, οἶμαι δὲ καὶ οἱ ἄλλοι πάντες· σύ τε γὰρ Ἕλλην εἶ καὶ ἡμεῖς τοσοῦτοι ὄντες ὅσους σὺ ὁρᾶις· ἐν τοιούτοις δὲ ὄντες πράγμασι συμβουλευόμεθά σοι τί χρὴ ποιεῖν περὶ ὧν λέγεις.", "st": "2.1.16"}, {"sp": "N", "t": "σὺ οὖν πρὸς θεῶν συμβούλευσον ἡμῖν ὅ τι σοι δοκεῖ κάλλιστον καὶ ἄριστον εἶναι, καὶ ὅ σοι τιμὴν οἴσει εἰς τὸν ἔπειτα χρόνον [ἀνα]λεγόμενον, ὅτι Φαλῖνός ποτε πεμφθεὶς παρὰ βασιλέως κελεύσων τοὺς Ἕλληνας τὰ ὅπλα παραδοῦναι συμβουλευομένοις συνεβούλευσεν αὐτοῖς τάδε. οἶσθα δὲ ὅτι ἀνάγκη λέγεσθαι ἐν τῆι Ἑλλάδι ἃ ἂν συμβουλεύσηις.»", "st": "2.1.17"}, {"sp": "N", "t": "ὁ δὲ Κλέαρχος ταῦτα ὑπήγετο βουλόμενος καὶ αὐτὸν τὸν παρὰ βασιλέως πρεσβεύοντα συμβουλεῦσαι μὴ παραδοῦναι τὰ ὅπλα, ὅπως εὐέλπιδες μᾶλλον εἶεν οἱ Ἕλληνες. Φαλῖνος δὲ ὑποστρέψας παρὰ τὴν δόξαν αὐτοῦ εἶπεν·", "st": "2.1.18"}, {"sp": "N", "t": "«ἐγώ, εἰ μὲν τῶν μυρίων ἐλπίδων μία τις ὑμῖν ἐστι σωθῆναι πολεμοῦντας βασιλεῖ, συμβουλεύω μὴ παραδιδόναι τὰ ὅπλα· εἰ δέ τοι μηδεμία σωτηρίας ἐστὶν ἐλπὶς ἄκοντος βασιλέως, συμβουλεύω σώιζεσθαι ὑμῖν ὅπηι δυνατόν.»", "st": "2.1.19"}, {"sp": "N", "t": "Κλέαρχος δὲ πρὸς ταῦτα εἶπεν· «ἀλλὰ ταῦτα μὲν δὴ σὺ λέγεις· παρ᾽ ἡμῶν δὲ ἀπάγγελλε τάδε, ὅτι ἡμεῖς οἰόμεθα, εἰ μὲν δέοι βασιλεῖ φίλους εἶναι, πλείονος ἂν ἄξιοι εἶναι φίλοι ἔχοντες τὰ ὅπλα ἢ παραδόντες ἄλλωι, εἰ δὲ δέοι πολεμεῖν, ἄμεινον ἂν πολεμεῖν ἔχοντες τὰ ὅπλα ἢ ἄλλωι παραδόντες.»", "st": "2.1.20"}, {"sp": "N", "t": "ὁ δὲ Φαλῖνος εἶπε· «ταῦτα μὲν δὴ ἀπαγγελοῦμεν· ἀλλὰ καὶ τάδε ὑμῖν εἰπεῖν ἐκέλευσε βασιλεύς, ὅτι μένουσι μὲν ὑμῖν αὐτοῦ σπονδαὶ εἴησαν, προϊοῦσι δὲ καὶ ἀπιοῦσι πόλεμος. εἴπατε οὖν καὶ περὶ τούτου πότερα μενεῖτε καὶ σπονδαί εἰσιν ἢ ὡς πολέμου ὄντος παρ᾽ ὑμῶν ἀπαγγελῶ.»", "st": "2.1.21"}, {"sp": "N", "t": "Κλέαρχος δ᾽ ἔλεξεν· «ἀπάγγελλε τοίνυν καὶ περὶ τούτου ὅτι καὶ ἡμῖν ταὐτὰ δοκεῖ ἅπερ καὶ βασιλεῖ.» «τί οὖν ταῦτά ἐστιν;» ἔφη ὁ Φαλῖνος. ἀπεκρίνατο Κλέαρχος· «ἢν μὲν μένωμεν, σπονδαί, ἀπιοῦσι δὲ καὶ προϊοῦσι πόλεμος.»", "st": "2.1.22"}, {"sp": "N", "t": "ὁ δὲ πάλιν ἠρώτησε· «σπονδὰς ἢ πόλεμον ἀπαγγελῶ;» Κλέαρχος δὲ ταὐτὰ πάλιν ἀπεκρίνατο· «σπονδαὶ μὲν μένουσιν, ἀπιοῦσι δὲ καὶ προϊοῦσι πόλεμος.» ὅ τι δὲ ποιήσοι οὐ διεσήμηνε.", "st": "2.1.23"}, {"sp": "N", "t": "Φαλῖνος μὲν δὴ ὤιχετο καὶ οἱ σὺν αὐτῶι. οἱ δὲ παρὰ Ἀριαίου ἧκον Προκλῆς καὶ Χειρίσοφος· Μένων δὲ αὐτοῦ ἔμενε παρὰ Ἀριαίωι· οὗτοι δὲ ἔλεγον ὅτι πολλοὺς φαίη Ἀριαῖος εἶναι Πέρσας ἑαυτοῦ βελτίους, οὓς οὐκ ἂν ἀνασχέσθαι αὐτοῦ βασιλεύοντος· «ἀλλ᾽ εἰ βούλεσθε συναπιέναι, ἥκειν ἤδη κελεύει τῆς νυκτός. εἰ δὲ μή, αὔριον πρὼι ἀπιέναι φησίν.»", "st": "2.2.1"}, {"sp": "N", "t": "ὁ δὲ Κλέαρχος εἶπεν· «ἀλλ᾽ οὕτω χρὴ ποιεῖν· ἐὰν μὲν ἥκωμεν, ὥσπερ λέγετε· εἰ δὲ μή, πράττετε ὁποῖον ἄν τι ὑμῖν οἴησθε μάλιστα συμφέρειν. ὅ τι δὲ ποιήσοι οὐδὲ τούτοις εἶπε.", "st": "2.2.2"}, {"sp": "N", "t": "μετὰ ταῦτα ἤδη ἡλίου δύνοντος συγκαλέσας στρατηγοὺς καὶ λοχαγοὺς ἔλεξε τοιάδε. «ἐμοί, ὦ ἄνδρες, θυομένωι ἰέναι ἐπὶ βασιλέα οὐκ ἐγίγνετο τὰ ἱερά. καὶ εἰκότως ἄρα οὐκ ἐγίγνετο· ὡς γὰρ ἐγὼ νῦν πυνθάνομαι, ἐν μέσωι ἡμῶν καὶ βασιλέως ὁ Τίγρης ποταμός ἐστι ναυσίπορος, ὃν οὐκ ἂν δυναίμεθα ἄνευ πλοίων διαβῆναι· πλοῖα δὲ ἡμεῖς οὐκ ἔχομεν. οὐ μὲν δὴ αὐτοῦ γε μένειν οἷόν τε· τὰ γὰρ ἐπιτήδεια οὐκ ἔστιν ἔχειν· ἰέναι δὲ παρὰ τοὺς Κύρου φίλους πάνυ καλὰ ἡμῖν τὰ ἱερὰ ἦν.", "st": "2.2.3"}, {"sp": "N", "t": "ὧδε οὖν χρὴ ποιεῖν· ἀπιόντας δειπνεῖν ὅ τι τις ἔχει· ἐπειδὰν δὲ σημήνηι τῶι κέρατι ὡς ἀναπαύεσθαι, συσκευάζεσθε· ἐπειδὰν δὲ τὸ δεύτερον, ἀνατίθεσθε ἐπὶ τὰ ὑποζύγια· ἐπὶ δὲ τῶι τρίτωι ἕπεσθε τῶι ἡγουμένωι, τὰ μὲν ὑποζύγια ἔχοντες πρὸς τοῦ ποταμοῦ, τὰ δὲ ὅπλα ἔξω.»", "st": "2.2.4"}, {"sp": "N", "t": "ταῦτ᾽ ἀκούσαντες οἱ στρατηγοὶ καὶ λοχαγοὶ ἀπῆλθον καὶ ἐποίουν οὕτω. καὶ τὸ λοιπὸν ὁ μὲν ἦρχεν, οἱ δὲ ἐπείθοντο, οὐχ ἑλόμενοι, ἀλλὰ ὁρῶντες ὅτι μόνος ἐφρόνει οἷα δεῖ τὸν ἄρχοντα, οἱ δ᾽ ἄλλοι ἄπειροι ἦσαν.", "st": "2.2.5"}, {"sp": "N", "t": "[ἀριθμὸς τῆς ὁδοῦ ἣν ἦλθον ἐξ Ἐφέσου τῆς Ἰωνίας μέχρι τῆς μάχης σταθμοὶ τρεῖς καὶ ἐνενήκοντα, παρασάγγαι πέντε καὶ τριάκοντα καὶ πεντακόσιοι, στάδιοι πεντήκοντα καὶ ἑξακισχίλιοι καὶ μύριοι· ἀπὸ δὲ τῆς μάχης ἐλέγοντο εἶναι εἰς Βαβυλῶνα στάδιοι ἑξήκοντα καὶ τριακόσιοι.]", "st": "2.2.6"}, {"sp": "N", "t": "ἐντεῦθεν ἐπεὶ σκότος ἐγένετο Μιλτοκύθης μὲν ὁ Θρᾶιξ ἔχων τούς τε ἱππέας τοὺς μεθ᾽ ἑαυτοῦ εἰς τετταράκοντα καὶ τῶν πεζῶν Θραικῶν ὡς τριακοσίους ηὐτομόλησε πρὸς βασιλέα.", "st": "2.2.7"}, {"sp": "N", "t": "Κλέαρχος δὲ τοῖς ἄλλοις ἡγεῖτο κατὰ τὰ παρηγγελμένα, οἱ δ᾽ εἵποντο· καὶ ἀφικνοῦνται εἰς τὸν πρῶτον σταθμὸν παρ᾽ Ἀριαῖον καὶ τὴν ἐκείνου στρατιὰν ἀμφὶ μέσας νύκτας· καὶ ἐν τάξει θέμενοι τὰ ὅπλα συνῆλθον οἱ στρατηγοὶ καὶ λοχαγοὶ τῶν Ἑλλήνων παρ᾽ Ἀριαῖον· καὶ ὤμοσαν οἵ τε Ἕλληνες καὶ ὁ Ἀριαῖος καὶ τῶν σὺν αὐτῶι οἱ κράτιστοι μήτε προδώσειν ἀλλήλους σύμμαχοί τε ἔσεσθαι· οἱ δὲ βάρβαροι προσώμοσαν καὶ ἡγήσεσθαι ἀδόλως.", "st": "2.2.8"}, {"sp": "N", "t": "ταῦτα δ᾽ ὤμοσαν, σφάξαντες ταῦρον καὶ κάπρον καὶ κριὸν εἰς ἀσπίδα, οἱ μὲν Ἕλληνες βάπτοντες ξίφος, οἱ δὲ βάρβαροι λόγχην.", "st": "2.2.9"}, {"sp": "N", "t": "ἐπεὶ δὲ τὰ πιστὰ ἐγένετο, εἶπεν ὁ Κλέαρχος· «ἄγε δή, ὦ Ἀριαῖε, ἐπείπερ ὁ αὐτὸς ὑμῖν στόλος ἐστὶ καὶ ἡμῖν, εἰπὲ τίνα γνώμην ἔχεις περὶ τῆς πορείας, πότερον ἄπιμεν ἥνπερ ἤλθομεν ἢ ἄλλην τινὰ ἐννενοηκέναι δοκεῖς ὁδὸν κρείττω.»", "st": "2.2.10"}, {"sp": "N", "t": "ὁ δ᾽ εἶπεν· «ἣν μὲν ἤλθομεν ἀπιόντες παντελῶς ἂν ὑπὸ λιμοῦ ἀπολοίμεθα· ὑπάρχει γὰρ νῦν ἡμῖν οὐδὲν τῶν ἐπιτηδείων. ἑπτακαίδεκα γὰρ σταθμῶν τῶν ἐγγυτάτω οὐδὲ δεῦρο ἰόντες ἐκ τῆς χώρας οὐδὲν εἴχομεν λαμβάνειν· ἔνθα δέ τι ἦν, ἡμεῖς διαπορευόμενοι κατεδαπανήσαμεν. νῦν δ᾽ ἐπινοοῦμεν πορεύεσθαι μακροτέραν μέν, τῶν δ᾽ ἐπιτηδείων οὐκ ἀπορήσομεν.", "st": "2.2.11"}, {"sp": "N", "t": "πορευτέον δ᾽ ἡμῖν τοὺς πρώτους σταθμοὺς ὡς ἂν δυνώμεθα μακροτάτους, ἵνα ὡς πλεῖστον ἀποσπάσωμεν τοῦ βασιλικοῦ στρατεύματος· ἢν γὰρ ἅπαξ δύο ἢ τριῶν ἡμερῶν ὁδὸν ἀπόσχωμεν, οὐκέτι μὴ δύνηται βασιλεὺς ἡμᾶς καταλαβεῖν. ὀλίγωι μὲν γὰρ στρατεύματι οὐ τολμήσει ἐφέπεσθαι· πολὺν δ᾽ ἔχων στόλον οὐ δυνήσεται ταχέως πορεύεσθαι· ἴσως δὲ καὶ τῶν ἐπιτηδείων σπανιεῖ. ταύτην, ἔφη, τὴν γνώμην ἔχω ἔγωγε.»", "st": "2.2.12"}, {"sp": "N", "t": "ἦν δὲ αὕτη ἡ στρατηγία οὐδὲν ἄλλο δυναμένη ἢ ἀποδρᾶναι ἢ ἀποφυγεῖν· ἡ δὲ τύχη ἐστρατήγησε κάλλιον. ἐπεὶ γὰρ ἡμέρα ἐγένετο, ἐπορεύοντο ἐν δεξιᾶι ἔχοντες τὸν ἥλιον, λογιζόμενοι ἥξειν ἅμα ἡλίωι δύνοντι εἰς κώμας τῆς Βαβυλωνίας χώρας· καὶ τοῦτο μὲν οὐκ ἐψεύσθησαν.", "st": "2.2.13"}, {"sp": "N", "t": "ἔτι δὲ ἀμφὶ δείλην ἔδοξαν πολεμίους ὁρᾶν ἱππέας· καὶ τῶν τε Ἑλλήνων οἳ μὴ ἔτυχον ἐν ταῖς τάξεσιν ὄντες εἰς τὰς τάξεις ἔθεον, καὶ Ἀριαῖος (ἐτύγχανε γὰρ ἐφ᾽ ἁμάξης πορευόμενος διότι ἐτέτρωτο) καταβὰς ἐθωρακίζετο καὶ οἱ σὺν αὐτῶι.", "st": "2.2.14"}, {"sp": "N", "t": "ἐν ὧι δὲ ὡπλίζοντο ἧκον λέγοντες οἱ προπεμφθέντες σκοποὶ ὅτι οὐχ ἱππεῖς εἰσιν, ἀλλ᾽ ὑποζύγια νέμοιντο. καὶ εὐθὺς ἔγνωσαν πάντες ὅτι ἐγγύς που ἐστρατοπεδεύετο βασιλεύς· καὶ γὰρ καπνὸς ἐφαίνετο ἐν κώμαις οὐ πρόσω.", "st": "2.2.15"}, {"sp": "N", "t": "Κλέαρχος δὲ ἐπὶ μὲν τοὺς πολεμίους οὐκ ἦγεν· ἤιδει γὰρ καὶ ἀπειρηκότας τοὺς στρατιώτας καὶ ἀσίτους ὄντας· ἤδη δὲ καὶ ὀψὲ ἦν· οὐ μέντοι οὐδὲ ἀπέκλινε, φυλαττόμενος μὴ δοκοίη φεύγειν, ἀλλ᾽ εὐθύωρον ἄγων ἅμα τῶι ἡλίωι δυομένωι εἰς τὰς ἐγγυτάτω κώμας τοὺς πρώτους ἄγων κατεσκήνωσεν, ἐξ ὧν διήρπαστο ὑπὸ τοῦ βασιλικοῦ στρατεύματος καὶ αὐτὰ τὰ ἀπὸ τῶν οἰκιῶν ξύλα.", "st": "2.2.16"}, {"sp": "N", "t": "οἱ μὲν οὖν πρῶτοι ὅμως τρόπωι τινὶ ἐστρατοπεδεύσαντο, οἱ δὲ ὕστεροι σκοταῖοι προσιόντες ὡς ἐτύγχανον ἕκαστοι ηὐλίζοντο, καὶ κραυγὴν πολλὴν ἐποίουν καλοῦντες ἀλλήλους, ὥστε καὶ τοὺς πολεμίους ἀκούειν· ὥστε οἱ μὲν ἐγγύτατα τῶν πολεμίων καὶ ἔφυγον ἐκ τῶν σκηνωμάτων.", "st": "2.2.17"}, {"sp": "N", "t": "δῆλον δὲ τοῦτο τῆι ὑστεραίαι ἐγένετο· οὔτε γὰρ ὑποζύγιον ἔτ᾽ οὐδὲν ἐφάνη οὔτε στρατόπεδον οὔτε καπνὸς οὐδαμοῦ πλησίον. ἐξεπλάγη δέ, ὡς ἔοικε, καὶ βασιλεὺς τῆι ἐφόδωι τοῦ στρατεύματος. ἐδήλωσε δὲ τοῦτο οἷς τῆι ὑστεραίαι ἔπραττε.", "st": "2.2.18"}, {"sp": "N", "t": "προϊούσης μέντοι τῆς νυκτὸς ταύτης καὶ τοῖς Ἕλλησι φόβος ἐμπίπτει, καὶ θόρυβος καὶ δοῦπος ἦν οἷον εἰκὸς φόβου ἐμπεσόντος γενέσθαι.", "st": "2.2.19"}, {"sp": "N", "t": "Κλέαρχος δὲ Τολμίδην Ἠλεῖον, ὃν ἐτύγχανεν ἔχων παρ᾽ ἑαυτῶι κήρυκα ἄριστον τῶν τότε, ἀνειπεῖν ἐκέλευσε σιγὴν κηρύξαντα ὅτι προαγορεύουσιν οἱ ἄρχοντες, ὃς ἂν τὸν ἀφέντα τὸν ὄνον εἰς τὰ ὅπλα μηνύσηι, ὅτι λήψεται μισθὸν τάλαντον.", "st": "2.2.20"}, {"sp": "N", "t": "ἐπεὶ δὲ ταῦτα ἐκηρύχθη, ἔγνωσαν οἱ στρατιῶται ὅτι κενὸς ὁ φόβος εἴη καὶ οἱ ἄρχοντες σῶιοι. ἅμα δὲ ὄρθρωι παρήγγειλεν ὁ Κλέαρχος εἰς τάξιν τὰ ὅπλα τίθεσθαι τοὺς Ἕλληνας ἧιπερ εἶχον ὅτε ἦν ἡ μάχη.", "st": "2.2.21"}, {"sp": "N", "t": "ὃ δὲ δὴ ἔγραψα ὅτι βασιλεὺς ἐξεπλάγη τῆι ἐφόδωι, τῶιδε δῆλον ἦν. τῆι μὲν γὰρ πρόσθεν ἡμέραι πέμπων τὰ ὅπλα παραδιδόναι ἐκέλευε, τότε δὲ ἅμα ἡλίωι ἀνατέλλοντι κήρυκας ἔπεμψε περὶ σπονδῶν.", "st": "2.3.1"}, {"sp": "N", "t": "οἱ δ᾽ ἐπεὶ ἦλθον πρὸς τοὺς προφύλακας, ἐζήτουν τοὺς ἄρχοντας. ἐπειδὴ δὲ ἀπήγγελλον οἱ προφύλακες, Κλέαρχος τυχὼν τότε τὰς τάξεις ἐπισκοπῶν εἶπε τοῖς προφύλαξι κελεύειν τοὺς κήρυκας περιμένειν ἄχρι ἂν σχολάσηι.", "st": "2.3.2"}, {"sp": "N", "t": "ἐπεὶ δὲ κατέστησε τὸ στράτευμα ὡς καλῶς ἔχειν ὁρᾶσθαι πάντηι φάλαγγα πυκνήν, ἐκ τῶν ὅπλων δὲ μηδένα καταφανῆ εἶναι, ἐκάλεσε τοὺς ἀγγέλους, καὶ αὐτός τε προῆλθε τούς τε εὐοπλοτάτους ἔχων καὶ εὐειδεστάτους τῶν αὑτοῦ στρατιωτῶν καὶ τοῖς ἄλλοις στρατηγοῖς ταὐτὰ ἔφρασεν.", "st": "2.3.3"}, {"sp": "N", "t": "ἐπεὶ δὲ ἦν πρὸς τοῖς ἀγγέλοις, ἀνηρώτα [πρῶτα] τί βούλοιντο. οἱ δ᾽ ἔλεγον ὅτι περὶ σπονδῶν ἥκοιεν ἄνδρες οἵτινες ἱκανοὶ ἔσονται τά τε παρὰ βασιλέως τοῖς Ἕλλησιν ἀπαγγεῖλαι καὶ τὰ παρὰ τῶν Ἑλλήνων βασιλεῖ.", "st": "2.3.4"}, {"sp": "N", "t": "ὁ δὲ ἀπεκρίνατο· «ἀπαγγέλλετε τοίνυν αὐτῶι ὅτι μάχης δεῖ πρῶτον· ἄριστον γὰρ οὐκ ἔστιν οὐδ᾽ ὁ τολμήσων περὶ σπονδῶν λέγειν τοῖς Ἕλλησι μὴ πορίσας ἄριστον.»", "st": "2.3.5"}, {"sp": "N", "t": "ταῦτα ἀκούσαντες οἱ ἄγγελοι ἀπήλαυνον, καὶ ἧκον ταχύ· ὧι καὶ δῆλον ἦν ὅτι ἐγγύς που βασιλεὺς ἦν ἢ ἄλλος τις ὧι ἐπετέτακτο ταῦτα πράττειν· ἔλεγον δὲ ὅτι εἰκότα δοκοῖεν λέγειν βασιλεῖ, καὶ ἥκοιεν ἡγεμόνας ἔχοντες οἳ αὐτούς, ἐὰν σπονδαὶ γένωνται, ἄξουσιν ἔνθεν ἕξουσι τὰ ἐπιτήδεια.", "st": "2.3.6"}, {"sp": "N", "t": "ὁ δὲ ἠρώτα εἰ αὐτοῖς τοῖς ἀνδράσι σπένδοιτο τοῖς ἰοῦσι καὶ ἀπιοῦσιν, ἢ καὶ τοῖς ἄλλοις ἔσοιντο σπονδαί. οἱ δέ, «ἅπασιν, ἔφασαν, μέχρι ἂν βασιλεῖ τὰ παρ᾽ ὑμῶν διαγγελθῆι.»", "st": "2.3.7"}, {"sp": "N", "t": "ἐπεὶ δὲ ταῦτα εἶπον, μεταστησάμενος αὐτοὺς ὁ Κλέαρχος ἐβουλεύετο· καὶ ἐδόκει ταχὺ τὰς σπονδὰς ποιεῖσθαι καὶ καθ᾽ ἡσυχίαν ἐλθεῖν τε ἐπὶ τὰ ἐπιτήδεια καὶ λαβεῖν.", "st": "2.3.8"}, {"sp": "N", "t": "ὁ δὲ Κλέαρχος εἶπε· «δοκεῖ μὲν κἀμοὶ ταῦτα· οὐ μέντοι ταχύ γε ἀπαγγελῶ, ἀλλὰ διατρίψω ἔστ᾽ ἂν ὀκνήσωσιν οἱ ἄγγελοι μὴ ἀποδόξηι ἡμῖν τὰς σπονδὰς ποιήσασθαι· οἶμαί γε μέντοι, ἔφη, καὶ τοῖς ἡμετέροις στρατιώταις τὸν αὐτὸν φόβον παρέσεσθαι.» ἐπεὶ δὲ ἐδόκει καιρὸς εἶναι, ἀπήγγελλεν ὅτι σπένδοιτο, καὶ εὐθὺς ἡγεῖσθαι ἐκέλευε πρὸς τἀπιτήδεια.", "st": "2.3.9"}, {"sp": "N", "t": "καὶ οἱ μὲν ἡγοῦντο, Κλέαρχος μέντοι ἐπορεύετο τὰς μὲν σπονδὰς ποιησάμενος, τὸ δὲ στράτευμα ἔχων ἐν τάξει, καὶ αὐτὸς ὠπισθοφυλάκει. καὶ ἐνετύγχανον τάφροις καὶ αὐλῶσιν ὕδατος πλήρεσιν, ὡς μὴ δύνασθαι διαβαίνειν ἄνευ γεφυρῶν· ἀλλ᾽ ἐποιοῦντο διαβάσεις ἐκ τῶν φοινίκων οἳ ἦσαν ἐκπεπτωκότες, τοὺς δὲ καὶ ἐξέκοπτον.", "st": "2.3.10"}, {"sp": "N", "t": "καὶ ἐνταῦθα ἦν Κλέαρχον καταμαθεῖν ὡς ἐπεστάτει, ἐν μὲν τῆι ἀριστερᾶι χειρὶ τὸ δόρυ ἔχων, ἐν δὲ τῆι δεξιᾶι βακτηρίαν· καὶ εἴ τις αὐτῶι δοκοίη τῶν πρὸς τοῦτο τεταγμένων βλακεύειν, ἐκλεγόμενος τὸν ἐπιτήδειον ἔπαισεν ἄν, καὶ ἅμα αὐτὸς προσελάμβανεν εἰς τὸν πηλὸν ἐμβαίνων· ὥστε πᾶσιν αἰσχύνην εἶναι μὴ οὐ συσπουδάζειν.", "st": "2.3.11"}, {"sp": "N", "t": "καὶ ἐτάχθησαν πρὸς αὐτὸ οἱ ⟨εἰς⟩ τριάκοντα ἔτη γεγονότες· ἐπεὶ δὲ Κλέαρχον ἑώρων σπουδάζοντα, προσελάμβανον καὶ οἱ πρεσβύτεροι.", "st": "2.3.12"}, {"sp": "N", "t": "πολὺ δὲ μᾶλλον ὁ Κλέαρχος ἔσπευδεν, ὑποπτεύων μὴ αἰεὶ οὕτω πλήρεις εἶναι τὰς τάφρους ὕδατος (οὐ γὰρ ἦν ὥρα οἵα τὸ πεδίον ἄρδειν), ἀλλ᾽ ἵνα ἤδη πολλὰ προφαίνοιτο τοῖς Ἕλλησι δεινὰ εἰς τὴν πορείαν, τούτου ἕνεκα βασιλέα ὑπώπτευεν ἐπὶ τὸ πεδίον τὸ ὕδωρ ἀφεικέναι.", "st": "2.3.13"}, {"sp": "N", "t": "πορευόμενοι δὲ ἀφίκοντο εἰς κώμας ὅθεν ἀπέδειξαν οἱ ἡγεμόνες λαμβάνειν τὰ ἐπιτήδεια. ἐνῆν δὲ σῖτος πολὺς καὶ οἶνος φοινίκων καὶ ὄξος ἑψητὸν ἀπὸ τῶν αὐτῶν.", "st": "2.3.14"}, {"sp": "N", "t": "αὐταὶ δὲ αἱ βάλανοι τῶν φοινίκων οἵας μὲν ἐν τοῖς Ἕλλησιν ἔστιν ἰδεῖν τοῖς οἰκέταις ἀπέκειντο, αἱ δὲ τοῖς δεσπόταις ἀποκείμεναι ἦσαν ἀπόλεκτοι, θαυμάσιαι τοῦ κάλλους καὶ μεγέθους, ἡ δὲ ὄψις ἠλέκτρου οὐδὲν διέφερεν· τὰς δέ τινας ξηραίνοντες τραγήματα ἀπετίθεσαν. καὶ ἦν καὶ παρὰ πότον ἡδὺ μέν, κεφαλαλγὲς δέ.", "st": "2.3.15"}, {"sp": "N", "t": "ἐνταῦθα καὶ τὸν ἐγκέφαλον τοῦ φοίνικος πρῶτον ἔφαγον οἱ στρατιῶται, καὶ οἱ πολλοὶ ἐθαύμασαν τό τε εἶδος καὶ τὴν ἰδιότητα τῆς ἡδονῆς. ἦν δὲ σφόδρα καὶ τοῦτο κεφαλαλγές. ὁ δὲ φοῖνιξ ὅθεν ἐξαιρεθείη ὁ ἐγκέφαλος ὅλος ηὐαίνετο.", "st": "2.3.16"}, {"sp": "N", "t": "ἐνταῦθα ἔμειναν ἡμέρας τρεῖς· καὶ παρὰ μεγάλου βασιλέως ἧκε Τισσαφέρνης καὶ ὁ τῆς βασιλέως γυναικὸς ἀδελφὸς καὶ ἄλλοι Πέρσαι τρεῖς· δοῦλοι δὲ πολλοὶ εἵποντο. ἐπεὶ δὲ ἀπήντησαν αὐτοῖς οἱ τῶν Ἑλλήνων στρατηγοί, ἔλεγε πρῶτος Τισσαφέρνης δι᾽ ἑρμηνέως τοιάδε.", "st": "2.3.17"}, {"sp": "N", "t": "«ἐγώ, ὦ ἄνδρες Ἕλληνες, γείτων οἰκῶ τῆι Ἑλλάδι, καὶ ἐπεὶ ὑμᾶς εἶδον εἰς πολλὰ καὶ ἀμήχανα πεπτωκότας, εὕρημα ἐποιησάμην εἴ πως δυναίμην παρὰ βασιλέως αἰτήσασθαι δοῦναι ἐμοὶ ἀποσῶσαι ὑμᾶς εἰς τὴν Ἑλλάδα. οἶμαι γὰρ ἂν οὐκ ἀχαρίστως μοι ἔχειν οὔτε πρὸς ὑμῶν οὔτε πρὸς τῆς πάσης Ἑλλάδος.", "st": "2.3.18"}, {"sp": "N", "t": "ταῦτα δὲ γνοὺς ἠιτούμην βασιλέα, λέγων αὐτῶι ὅτι δικαίως ἄν μοι χαρίζοιτο, ὅτι αὐτῶι Κῦρόν τε ἐπιστρατεύοντα πρῶτος ἤγγειλα καὶ βοήθειαν ἔχων ἅμα τῆι ἀγγελίαι ἀφικόμην, καὶ μόνος τῶν κατὰ τοὺς Ἕλληνας τεταγμένων οὐκ ἔφυγον, ἀλλὰ διήλασα καὶ συνέμειξα βασιλεῖ ἐν τῶι ὑμετέρωι στρατοπέδωι ἔνθα βασιλεὺς ἀφίκετο, ἐπεὶ Κῦρον ἀπέκτεινε καὶ τοὺς ξὺν Κύρωι βαρβάρους ἐδίωξε σὺν τοῖσδε τοῖς παροῦσι νῦν μετ᾽ ἐμοῦ, οἵπερ αὐτῶι εἰσι πιστότατοι. καὶ περὶ μὲν τούτων ὑπέσχετό μοι βουλεύσεσθαι·", "st": "2.3.19"}, {"sp": "N", "t": "ἐρέσθαι δέ με ὑμᾶς ἐκέλευεν ἐλθόντα τίνος ἕνεκεν ἐστρατεύσατε ἐπ᾽ αὐτόν. καὶ συμβουλεύω ὑμῖν μετρίως ἀποκρίνασθαι, ἵνα μοι εὐπρακτότερον ἦι ἐάν τι δύνωμαι ἀγαθὸν ὑμῖν παρ᾽ αὐτοῦ διαπράξασθαι.»", "st": "2.3.20"}, {"sp": "N", "t": "πρὸς ταῦτα μεταστάντες οἱ Ἕλληνες ἐβουλεύοντο· καὶ ἀπεκρίναντο, Κλέαρχος δ᾽ ἔλεγεν· «ἡμεῖς οὔτε συνήλθομεν ὡς βασιλεῖ πολεμήσοντες οὔτε ἐπορευόμεθα ἐπὶ βασιλέα, ἀλλὰ πολλὰς προφάσεις Κῦρος ηὕρισκεν, ὡς καὶ σὺ εὖ οἶσθα, ἵνα ὑμᾶς τε ἀπαρασκεύους λάβοι καὶ ἡμᾶς ἐνθάδε ἀγάγοι.", "st": "2.3.21"}, {"sp": "N", "t": "ἐπεὶ μέντοι ἤδη αὐτὸν ἑωρῶμεν ἐν δεινῶι ὄντα, ἠισχύνθημεν καὶ θεοὺς καὶ ἀνθρώπους προδοῦναι αὐτόν, ἐν τῶι πρόσθεν χρόνωι παρέχοντες ἡμᾶς αὐτοὺς εὖ ποιεῖν.", "st": "2.3.22"}, {"sp": "N", "t": "ἐπεὶ δὲ Κῦρος τέθνηκεν, οὔτε βασιλεῖ ἀντιποιούμεθα τῆς ἀρχῆς οὔτ᾽ ἔστιν ὅτου ἕνεκα βουλοίμεθα ἂν τὴν βασιλέως χώραν κακῶς ποιεῖν, οὐδ᾽ αὐτὸν ἀποκτεῖναι ἂν ἐθέλοιμεν, πορευοίμεθα δ᾽ ἂν οἴκαδε, εἴ τις ἡμᾶς μὴ λυποίη· ἀδικοῦντα μέντοι πειρασόμεθα σὺν τοῖς θεοῖς ἀμύνασθαι· ἐὰν μέντοι τις ἡμᾶς καὶ εὖ ποιῶν ὑπάρχηι, καὶ τούτου εἴς γε δύναμιν οὐχ ἡττησόμεθα εὖ ποιοῦντες.»", "st": "2.3.23"}, {"sp": "N", "t": "ὁ μὲν οὕτως εἶπεν· ἀκούσας δὲ ὁ Τισσαφέρνης, «ταῦτα, ἔφη, ἐγὼ ἀπαγγελῶ βασιλεῖ καὶ ὑμῖν πάλιν τὰ παρ᾽ ἐκείνου· μέχρι δ᾽ ἂν ἐγὼ ἥκω αἱ σπονδαὶ μενόντων· ἀγορὰν δὲ ἡμεῖς παρέξομεν.»", "st": "2.3.24"}, {"sp": "N", "t": "καὶ εἰς μὲν τὴν ὑστεραίαν οὐχ ἧκεν· ὥσθ᾽ οἱ Ἕλληνες ἐφρόντιζον· τῆι δὲ τρίτηι ἥκων ἔλεγεν ὅτι διαπεπραγμένος ἥκοι παρὰ βασιλέως δοθῆναι αὐτῶι σώιζειν τοὺς Ἕλληνας, καίπερ πάνυ πολλῶν ἀντιλεγόντων ὡς οὐκ ἄξιον εἴη βασιλεῖ ἀφεῖναι τοὺς ἐφ᾽ ἑαυτὸν στρατευσαμένους.", "st": "2.3.25"}, {"sp": "N", "t": "τέλος δὲ εἶπε· «καὶ νῦν ἔξεστιν ὑμῖν πιστὰ λαβεῖν παρ᾽ ἡμῶν ἦ μὴν φιλίαν παρέξειν ὑμῖν τὴν χώραν καὶ ἀδόλως ἀπάξειν εἰς τὴν Ἑλλάδα ἀγορὰν παρέχοντας· ὅπου δ᾽ ἂν μὴ ἦι πρίασθαι, λαμβάνειν ὑμᾶς ἐκ τῆς χώρας ἐάσομεν τὰ ἐπιτήδεια.", "st": "2.3.26"}, {"sp": "N", "t": "ὑμᾶς δὲ αὖ ἡμῖν δεήσει ὀμόσαι ἦ μὴν πορεύσεσθαι ὡς διὰ φιλίας ἀσινῶς σῖτα καὶ ποτὰ λαμβάνοντας ὁπόταν μὴ ἀγορὰν παρέχωμεν, ἐὰν δὲ παρέχωμεν ἀγοράν, ὠνουμένους ἕξειν τὰ ἐπιτήδεια.»", "st": "2.3.27"}, {"sp": "N", "t": "ταῦτα ἔδοξε, καὶ ὤμοσαν καὶ δεξιὰς ἔδοσαν Τισσαφέρνης καὶ ὁ τῆς βασιλέως γυναικὸς ἀδελφὸς τοῖς τῶν Ἑλλήνων στρατηγοῖς καὶ λοχαγοῖς καὶ ἔλαβον παρὰ τῶν Ἑλλήνων.", "st": "2.3.28"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα Τισσαφέρνης εἶπε· «νῦν μὲν δὴ ἄπειμι ὡς βασιλέα· ἐπειδὰν δὲ διαπράξωμαι ἃ δέομαι, ἥξω συσκευασάμενος ὡς ἀπάξων ὑμᾶς εἰς τὴν Ἑλλάδα καὶ αὐτὸς ἀπιὼν ἐπὶ τὴν ἐμαυτοῦ ἀρχήν.»", "st": "2.3.29"}, {"sp": "N", "t": "μετὰ ταῦτα περιέμενον Τισσαφέρνην οἵ τε Ἕλληνες καὶ ὁ Ἀριαῖος ἐγγὺς ἀλλήλων ἐστρατοπεδευμένοι ἡμέρας πλείους ἢ εἴκοσιν. ἐν δὲ ταύταις ἀφικνοῦνται πρὸς Ἀριαῖον καὶ οἱ ἀδελφοὶ καὶ οἱ ἄλλοι ἀναγκαῖοι καὶ πρὸς τοὺς σὺν ἐκείνωι Περσῶν τινες, ⟨οἳ⟩ παρεθάρρυνόν τε καὶ δεξιὰς ἐνίοις παρὰ βασιλέως ἔφερον μὴ μνησικακήσειν βασιλέα αὐτοῖς τῆς σὺν Κύρωι ἐπιστρατείας μηδὲ ἄλλου μηδενὸς τῶν παροιχομένων.", "st": "2.4.1"}, {"sp": "N", "t": "τούτων δὲ γιγνομένων ἔνδηλοι ἦσαν οἱ περὶ Ἀριαῖον ἧττον προσέχοντες τοῖς Ἕλλησι τὸν νοῦν· ὥστε καὶ διὰ τοῦτο τοῖς μὲν πολλοῖς τῶν Ἑλλήνων οὐκ ἤρεσκον, ἀλλὰ προσιόντες τῶι Κλεάρχωι ἔλεγον καὶ τοῖς ἄλλοις στρατηγοῖς·", "st": "2.4.2"}, {"sp": "N", "t": "«τί μένομεν; ἢ οὐκ ἐπιστάμεθα ὅτι βασιλεὺς ἡμᾶς ἀπολέσαι ἂν περὶ παντὸς ποιήσαιτο, ἵνα καὶ τοῖς ἄλλοις Ἕλλησι φόβος εἴη ἐπὶ βασιλέα μέγαν στρατεύειν; καὶ νῦν μὲν ἡμᾶς ὑπάγεται μένειν διὰ τὸ διεσπάρθαι αὐτοῦ τὸ στράτευμα· ἐπὰν δὲ πάλιν ἁλισθῆι αὐτῶι ἡ στρατιά, οὐκ ἔστιν ὅπως οὐκ ἐπιθήσεται ἡμῖν.", "st": "2.4.3"}, {"sp": "N", "t": "ἴσως δέ που ἢ ἀποσκάπτει τι ἢ ἀποτειχίζει, ὡς ἄπορος εἴη ἡ ὁδός. οὐ γάρ ποτε ἑκών γε βουλήσεται ἡμᾶς ἐλθόντας εἰς τὴν Ἑλλάδα ἀπαγγεῖλαι ὡς ἡμεῖς τοσοίδε ὄντες ἐνικῶμεν τὸν βασιλέα ἐπὶ ταῖς θύραις αὐτοῦ καὶ καταγελάσαντες ἀπήλθομεν.»", "st": "2.4.4"}, {"sp": "N", "t": "Κλέαρχος δὲ ἀπεκρίνατο τοῖς ταῦτα λέγουσιν· «ἐγὼ ἐνθυμοῦμαι μὲν καὶ ταῦτα πάντα· ἐννοῶ δ᾽ ὅτι εἰ νῦν ἄπιμεν, δόξομεν ἐπὶ πολέμωι ἀπιέναι καὶ παρὰ τὰς σπονδὰς ποιεῖν. ἔπειτα πρῶτον μὲν ἀγορὰν οὐδεὶς παρέξει ἡμῖν οὐδὲ ὅθεν ἐπισιτιούμεθα· αὖθις δὲ ὁ ἡγησόμενος οὐδεὶς ἔσται· καὶ ἅμα ταῦτα ποιούντων ἡμῶν εὐθὺς Ἀριαῖος ἀφεστήξει· ὥστε φίλος ἡμῖν οὐδεὶς λελείψεται, ἀλλὰ καὶ οἱ πρόσθεν ὄντες πολέμιοι ἡμῖν ἔσονται.", "st": "2.4.5"}, {"sp": "N", "t": "ποταμὸς δ᾽ εἰ μέν τις καὶ ἄλλος ἄρα ἡμῖν ἐστι διαβατέος οὐκ οἶδα· τὸν δ᾽ οὖν Εὐφράτην ἴσμεν ὅτι ἀδύνατον διαβῆναι κωλυόντων πολεμίων. οὐ μὲν δὴ ἂν μάχεσθαί γε δέηι, ἱππεῖς εἰσιν ἡμῖν ξύμμαχοι, τῶν δὲ πολεμίων ἱππεῖς εἰσιν οἱ πλεῖστοι καὶ πλείστου ἄξιοι· ὥστε νικῶντες μὲν τίνα ἂν ἀποκτείναιμεν; ἡττωμένων δὲ οὐδένα οἷόν τε σωθῆναι.", "st": "2.4.6"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν βασιλέα, ὧι οὕτω πολλά ἐστι τὰ σύμμαχα, εἴπερ προθυμεῖται ἡμᾶς ἀπολέσαι, οὐκ οἶδα ὅ τι δεῖ αὐτὸν ὀμόσαι καὶ δεξιὰν δοῦναι καὶ θεοὺς ἐπιορκῆσαι καὶ τὰ ἑαυτοῦ πιστὰ ἄπιστα ποιῆσαι Ἕλλησί τε καὶ βαρβάροις.» τοιαῦτα πολλὰ ἔλεγεν.", "st": "2.4.7"}, {"sp": "N", "t": "ἐν δὲ τούτωι ἧκε Τισσαφέρνης ἔχων τὴν ἑαυτοῦ δύναμιν ὡς εἰς οἶκον ἀπιὼν καὶ Ὀρόντας τὴν ἑαυτοῦ δύναμιν· ἦγε δὲ καὶ τὴν θυγατέρα τὴν βασιλέως ἐπὶ γάμωι.", "st": "2.4.8"}, {"sp": "N", "t": "ἐντεῦθεν δὲ ἤδη Τισσαφέρνους ἡγουμένου καὶ ἀγορὰν παρέχοντος ἐπορεύοντο· ἐπορεύετο δὲ καὶ Ἀριαῖος τὸ Κύρου βαρβαρικὸν ἔχων στράτευμα ἅμα Τισσαφέρνει καὶ Ὀρόνται καὶ ξυνεστρατοπεδεύετο σὺν ἐκείνοις.", "st": "2.4.9"}, {"sp": "N", "t": "οἱ δὲ Ἕλληνες ὑφορῶντες τούτους αὐτοὶ ἐφ᾽ ἑαυτῶν ἐχώρουν ἡγεμόνας ἔχοντες. ἐστρατοπεδεύοντο δὲ ἑκάστοτε ἀπέχοντες ἀλλήλων παρασάγγην καὶ πλέον· ἐφυλάττοντο δὲ ἀμφότεροι ὥσπερ πολεμίους ἀλλήλους, καὶ εὐθὺς τοῦτο ὑποψίαν παρεῖχεν.", "st": "2.4.10"}, {"sp": "N", "t": "ἐνίοτε δὲ καὶ ξυλιζόμενοι ἐκ τοῦ αὐτοῦ καὶ χόρτον καὶ ἄλλα τοιαῦτα ξυλλέγοντες πληγὰς ἐνέτεινον ἀλλήλοις· ὥστε καὶ τοῦτο ἔχθραν παρεῖχε.", "st": "2.4.11"}, {"sp": "N", "t": "διελθόντες δὲ τρεῖς σταθμοὺς ἀφίκοντο πρὸς τὸ Μηδίας καλούμενον τεῖχος, καὶ παρῆλθον εἴσω αὐτοῦ. ἦν δὲ ὠικοδομημένον πλίνθοις ὀπταῖς ἐν ἀσφάλτωι κειμέναις, εὖρος εἴκοσι ποδῶν, ὕψος δὲ ἑκατόν· μῆκος δ᾽ ἐλέγετο εἶναι εἴκοσι παρασάγγαι· ἀπέχει δὲ Βαβυλῶνος οὐ πολύ.", "st": "2.4.12"}, {"sp": "N", "t": "ἐντεῦθεν δ᾽ ἐπορεύθησαν σταθμοὺς δύο παρασάγγας ὀκτώ· καὶ διέβησαν διώρυχας δύο, τὴν μὲν ἐπὶ γεφύρας, τὴν δὲ ἐζευγμένην πλοίοις ἑπτά· αὗται δ᾽ ἦσαν ἀπὸ τοῦ Τίγρητος ποταμοῦ· κατετέτμηντο δὲ ἐξ αὐτῶν καὶ τάφροι ἐπὶ τὴν χώραν, αἱ μὲν πρῶται μεγάλαι, ἔπειτα δὲ ἐλάττους· τέλος δὲ καὶ μικροὶ ὀχετοί, ὥσπερ ἐν τῆι Ἑλλάδι ἐπὶ τὰς μελίνας· καὶ ἀφικνοῦνται ἐπὶ τὸν Τίγρητα ποταμόν· πρὸς ὧι πόλις ἦν μεγάλη καὶ πολυάνθρωπος ἧι ὄνομα Σιττάκη, ἀπέχουσα τοῦ ποταμοῦ σταδίους πεντεκαίδεκα.", "st": "2.4.13"}, {"sp": "N", "t": "οἱ μὲν οὖν Ἕλληνες παρ᾽ αὐτὴν ἐσκήνησαν ἐγγὺς παραδείσου μεγάλου καὶ καλοῦ καὶ δασέος παντοίων δένδρων, οἱ δὲ βάρβαροι διαβεβηκότες τὸν Τίγρητα· οὐ μέντοι καταφανεῖς ἦσαν.", "st": "2.4.14"}, {"sp": "N", "t": "μετὰ δὲ τὸ δεῖπνον ἔτυχον ἐν περιπάτωι ὄντες πρὸ τῶν ὅπλων Πρόξενος καὶ Ξενοφῶν· καὶ προσελθὼν ἄνθρωπός τις ἠρώτησε τοὺς προφύλακας ποῦ ἂν ἴδοι Πρόξενον ἢ Κλέαρχον· Μένωνα δὲ οὐκ ἐζήτει, καὶ ταῦτα παρ᾽ Ἀριαίου ὢν τοῦ Μένωνος ξένου.", "st": "2.4.15"}, {"sp": "N", "t": "ἐπεὶ δὲ Πρόξενος εἶπεν «ὅτι αὐτός εἰμι ὃν ζητεῖς», εἶπεν ὁ ἄνθρωπος τάδε. «ἔπεμψέ με Ἀριαῖος καὶ Ἀρτάοζος, πιστοὶ ὄντες Κύρωι καὶ ὑμῖν εὖνοι, καὶ κελεύουσι φυλάττεσθαι μὴ ὑμῖν ἐπιθῶνται τῆς νυκτὸς οἱ βάρβαροι· ἔστι δὲ στράτευμα πολὺ ἐν τῶι πλησίον παραδείσωι.", "st": "2.4.16"}, {"sp": "N", "t": "καὶ παρὰ τὴν γέφυραν τοῦ Τίγρητος ποταμοῦ πέμψαι κελεύουσι φυλακήν, ὡς διανοεῖται αὐτὴν λῦσαι Τισσαφέρνης τῆς νυκτός, ἐὰν δύνηται, ὡς μὴ διαβῆτε ἀλλ᾽ ἐν μέσωι ἀποληφθῆτε τοῦ ποταμοῦ καὶ τῆς διώρυχος.»", "st": "2.4.17"}, {"sp": "N", "t": "ἀκούσαντες ταῦτα ἄγουσιν αὐτὸν παρὰ τὸν Κλέαρχον καὶ φράζουσιν ἃ λέγει. ὁ δὲ Κλέαρχος ἀκούσας ἐταράχθη σφόδρα καὶ ἐφοβεῖτο.", "st": "2.4.18"}, {"sp": "N", "t": "νεανίσκος δέ τις τῶν παρόντων ἐννοήσας εἶπεν ὡς οὐκ ἀκόλουθα εἴη τό τε ἐπιθήσεσθαι καὶ λύσειν τὴν γέφυραν. δῆλον γὰρ ὅτι ἐπιτιθεμένους ἢ νικᾶν δεήσει ἢ ἡττᾶσθαι. ἐὰν μὲν οὖν νικῶσι, τί δεῖ λύειν αὐτοὺς τὴν γέφυραν; οὐδὲ γὰρ ἂν πολλαὶ γέφυραι ὦσιν ἔχοιμεν ἂν ὅποι φυγόντες ἡμεῖς σωθῶμεν.", "st": "2.4.19"}, {"sp": "N", "t": "ἐὰν δὲ ἡμεῖς νικῶμεν, λελυμένης τῆς γεφύρας οὐχ ἕξουσιν ἐκεῖνοι ὅποι φύγωσιν· οὐδὲ μὴν βοηθῆσαι πολλῶν ὄντων πέραν οὐδεὶς αὐτοῖς δυνήσεται λελυμένης τῆς γεφύρας.", "st": "2.4.20"}, {"sp": "N", "t": "ἀκούσας δὲ ὁ Κλέαρχος ταῦτα ἤρετο τὸν ἄγγελον πόση τις εἴη χώρα ἡ ἐν μέσωι τοῦ Τίγρητος καὶ τῆς διώρυχος. ὁ δὲ εἶπεν ὅτι πολλὴ καὶ κῶμαι ἔνεισι καὶ πόλεις πολλαὶ καὶ μεγάλαι.", "st": "2.4.21"}, {"sp": "N", "t": "τότε δὴ καὶ ἐγνώσθη ὅτι οἱ βάρβαροι τὸν ἄνθρωπον ὑποπέμψειαν, ὀκνοῦντες μὴ οἱ Ἕλληνες διελόντες τὴν γέφυραν μείναιεν ἐν τῆι νήσωι ἐρύματα ἔχοντες ἔνθεν μὲν τὸν Τίγρητα, ἔνθεν δὲ τὴν διώρυχα· τὰ δ᾽ ἐπιτήδεια ἔχοιεν ἐκ τῆς ἐν μέσωι χώρας πολλῆς καὶ ἀγαθῆς οὔσης καὶ τῶν ἐργασομένων ἐνόντων· εἶτα δὲ καὶ ἀποστροφὴ γένοιτο εἴ τις βούλοιτο βασιλέα κακῶς ποιεῖν.", "st": "2.4.22"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα ἀνεπαύοντο· ἐπὶ μέντοι τὴν γέφυραν ὅμως φυλακὴν ἔπεμψαν· καὶ οὔτε ἐπέθετο οὐδεὶς οὐδαμόθεν οὔτε πρὸς τὴν γέφυραν οὐδεὶς ἦλθε τῶν πολεμίων, ὡς οἱ φυλάττοντες ἀπήγγελλον.", "st": "2.4.23"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἕως ἐγένετο, διέβαινον τὴν γέφυραν ἐζευγμένην πλοίοις τριάκοντα καὶ ἑπτὰ ὡς οἷόν τε μάλιστα πεφυλαγμένως· ἐξήγγελλον γάρ τινες τῶν παρὰ Τισσαφέρνους Ἑλλήνων ὡς διαβαινόντων μέλλοιεν ἐπιθήσεσθαι. ἀλλὰ ταῦτα μὲν ψευδῆ ἦν· διαβαινόντων μέντοι ὁ Γλοῦς [αὐτῶν] ἐπεφάνη μετ᾽ ἄλλων σκοπῶν εἰ διαβαίνοιεν τὸν ποταμόν· ἐπειδὴ δὲ εἶδεν, ὤιχετο ἀπελαύνων.", "st": "2.4.24"}, {"sp": "N", "t": "ἀπὸ δὲ τοῦ Τίγρητος ἐπορεύθησαν σταθμοὺς τέτταρας παρασάγγας εἴκοσιν ἐπὶ τὸν Φύσκον ποταμόν, τὸ εὖρος πλέθρου· ἐπῆν δὲ γέφυρα. καὶ ἐνταῦθα ὠικεῖτο πόλις μεγάλη ὄνομα Ὦπις· πρὸς ἣν ἀπήντησε τοῖς Ἕλλησιν ὁ Κύρου καὶ Ἀρταξέρξου νόθος ἀδελφὸς ἀπὸ Σούσων καὶ Ἐκβατάνων στρατιὰν πολλὴν ἄγων ὡς βοηθήσων βασιλεῖ· καὶ ἐπιστήσας τὸ ἑαυτοῦ στράτευμα παρερχομένους τοὺς Ἕλληνας ἐθεώρει.", "st": "2.4.25"}, {"sp": "N", "t": "ὁ δὲ Κλέαρχος ἡγεῖτο μὲν εἰς δύο, ἐπορεύετο δὲ ἄλλοτε καὶ ἄλλοτε ἐφιστάμενος· ὅσον δὲ [ἂν] χρόνον τὸ ἡγούμενον τοῦ στρατεύματος ἐπιστήσειε, τοσοῦτον ἦν ἀνάγκη χρόνον δι᾽ ὅλου τοῦ στρατεύματος γίγνεσθαι τὴν ἐπίστασιν· ὥστε τὸ στράτευμα καὶ αὐτοῖς τοῖς Ἕλλησι δόξαι πάμπολυ εἶναι, καὶ τὸν Πέρσην ἐκπεπλῆχθαι θεωροῦντα.", "st": "2.4.26"}, {"sp": "N", "t": "ἐντεῦθεν δ᾽ ἐπορεύθησαν διὰ τῆς Μηδίας σταθμοὺς ἐρήμους ἓξ παρασάγγας τριάκοντα εἰς τὰς Παρυσάτιδος κώμας τῆς Κύρου καὶ βασιλέως μητρός. ταύτας Τισσαφέρνης Κύρωι ἐπεγγελῶν διαρπάσαι τοῖς Ἕλλησιν ἐπέτρεψε πλὴν ἀνδραπόδων. ἐνῆν δὲ σῖτος πολὺς καὶ πρόβατα καὶ ἄλλα χρήματα.", "st": "2.4.27"}, {"sp": "N", "t": "ἐντεῦθεν δ᾽ ἐπορεύθησαν σταθμοὺς ἐρήμους τέτταρας παρασάγγας εἴκοσι τὸν Τίγρητα ποταμὸν ἐν ἀριστερᾶι ἔχοντες. ἐν δὲ τῶι πρώτωι σταθμῶι πέραν τοῦ ποταμοῦ πόλις ὠικεῖτο μεγάλη καὶ εὐδαίμων ὄνομα Καιναί, ἐξ ἧς οἱ βάρβαροι διῆγον ἐπὶ σχεδίαις διφθερίναις ἄρτους, τυρούς, οἶνον.", "st": "2.4.28"}, {"sp": "N", "t": "μετὰ ταῦτα ἀφικνοῦνται ἐπὶ τὸν Ζαπάταν ποταμόν, τὸ εὖρος τεττάρων πλέθρων. καὶ ἐνταῦθα ἔμειναν ἡμέρας τρεῖς· ἐν δὲ ταύταις ὑποψίαι μὲν ἦσαν, φανερὰ δὲ οὐδεμία ἐφαίνετο ἐπιβουλή.", "st": "2.5.1"}, {"sp": "N", "t": "ἔδοξεν οὖν τῶι Κλεάρχωι ξυγγενέσθαι τῶι Τισσαφέρνει καὶ εἴ πως δύναιτο παῦσαι τὰς ὑποψίας πρὶν ἐξ αὐτῶν πόλεμον γενέσθαι. καὶ ἔπεμψέν τινα ἐροῦντα ὅτι ξυγγενέσθαι αὐτῶι χρήιζει.", "st": "2.5.2"}, {"sp": "N", "t": "ὁ δὲ ἑτοίμως ἐκέλευεν ἥκειν. ἐπειδὴ δὲ ξυνῆλθον, λέγει ὁ Κλέαρχος τάδε. «ἐγώ, ὦ Τισσαφέρνη, οἶδα μὲν ἡμῖν ὅρκους γεγενημένους καὶ δεξιὰς δεδομένας μὴ ἀδικήσειν ἀλλήλους· φυλαττόμενον δὲ σέ τε ὁρῶ ὡς πολεμίους ἡμᾶς καὶ ἡμεῖς ὁρῶντες ταῦτα ἀντιφυλαττόμεθα.", "st": "2.5.3"}, {"sp": "N", "t": "ἐπεὶ δὲ σκοπῶν οὐ δύναμαι οὔτε σὲ αἰσθέσθαι πειρώμενον ἡμᾶς κακῶς ποιεῖν ἐγώ τε σαφῶς οἶδα ὅτι ἡμεῖς γε οὐδὲ ἐπινοοῦμεν τοιοῦτον οὐδέν, ἔδοξέ μοι εἰς λόγους σοι ἐλθεῖν, ὅπως εἰ δυναίμεθα ἐξέλοιμεν ἀλλήλων τὴν ἀπιστίαν.", "st": "2.5.4"}, {"sp": "N", "t": "καὶ γὰρ οἶδα ἀνθρώπους ἤδη τοὺς μὲν ἐκ διαβολῆς τοὺς δὲ καὶ ἐξ ὑποψίας οἳ φοβηθέντες ἀλλήλους φθάσαι βουλόμενοι πρὶν παθεῖν ἐποίησαν ἀνήκεστα κακὰ τοὺς οὔτε μέλλοντας οὔτ᾽ αὖ βουλομένους τοιοῦτον οὐδέν.", "st": "2.5.5"}, {"sp": "N", "t": "τὰς οὖν τοιαύτας ἀγνωμοσύνας νομίζων συνουσίαις μάλιστα παύεσθαι ἥκω καὶ διδάσκειν σε βούλομαι ὡς σὺ ἡμῖν οὐκ ὀρθῶς ἀπιστεῖς.", "st": "2.5.6"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ καὶ μέγιστον οἱ θεῶν ἡμᾶς ὅρκοι κωλύουσι πολεμίους εἶναι ἀλλήλοις· ὅστις δὲ τούτων σύνοιδεν αὑτῶι παρημεληκώς, τοῦτον ἐγὼ οὔποτ᾽ ἂν εὐδαιμονίσαιμι. τὸν γὰρ θεῶν πόλεμον οὐκ οἶδα οὔτ᾽ ἀπὸ ποίου ἂν τάχους οὔτε ὅποι ἄν τις φεύγων ἀποφύγοι οὔτ᾽ εἰς ποῖον ἂν σκότος ἀποδραίη οὔθ᾽ ὅπως ἂν εἰς ἐχυρὸν χωρίον ἀποσταίη. πάντηι γὰρ πάντα τοῖς θεοῖς ὕποχα καὶ πάντων ἴσον οἱ θεοὶ κρατοῦσι.", "st": "2.5.7"}, {"sp": "N", "t": "περὶ μὲν δὴ τῶν θεῶν τε καὶ τῶν ὅρκων οὕτω γιγνώσκω, παρ᾽ οὓς ἡμεῖς τὴν φιλίαν συνθέμενοι κατεθέμεθα· τῶν δ᾽ ἀνθρωπίνων σὲ ἐγὼ ἐν τῶι παρόντι νομίζω μέγιστον εἶναι ἡμῖν ἀγαθόν.", "st": "2.5.8"}, {"sp": "N", "t": "σὺν μὲν γὰρ σοὶ πᾶσα μὲν ὁδὸς εὔπορος, πᾶς δὲ ποταμὸς διαβατός, τῶν τε ἐπιτηδείων οὐκ ἀπορία· ἄνευ δὲ σοῦ πᾶσα μὲν διὰ σκότους ἡ ὁδός· οὐδὲν γὰρ αὐτῆς ἐπιστάμεθα· πᾶς δὲ ποταμὸς δύσπορος, πᾶς δὲ ὄχλος φοβερός, φοβερώτατον δ᾽ ἐρημία· μεστὴ γὰρ πολλῆς ἀπορίας ἐστίν.", "st": "2.5.9"}, {"sp": "N", "t": "εἰ δὲ δὴ καὶ μανέντες σε κατακτείναιμεν, ἄλλο τι ἂν ἢ τὸν εὐεργέτην κατακτείναντες πρὸς βασιλέα τὸν μέγιστον ἔφεδρον ἀγωνιζοίμεθα; ὅσων δὲ δὴ καὶ οἵων ἂν ἐλπίδων ἐμαυτὸν στερήσαιμι, εἰ σέ τι κακὸν ἐπιχειρήσαιμι ποιεῖν, ταῦτα λέξω.", "st": "2.5.10"}, {"sp": "N", "t": "ἐγὼ γὰρ Κῦρον ἐπεθύμησά μοι φίλον γενέσθαι, νομίζων τῶν τότε ἱκανώτατον εἶναι εὖ ποιεῖν ὃν βούλοιτο· σὲ δὲ νῦν ὁρῶ τήν τε Κύρου δύναμιν καὶ χώραν ἔχοντα καὶ τὴν σαυτοῦ [χώραν] σώιζοντα, τὴν δὲ βασιλέως δύναμιν, ἧι Κῦρος πολεμίαι ἐχρῆτο, σοὶ ταύτην ξύμμαχον οὖσαν.", "st": "2.5.11"}, {"sp": "N", "t": "τούτων δὲ τοιούτων ὄντων τίς οὕτω μαίνεται ὅστις οὐ βούλεται σοὶ φίλος εἶναι; ἀλλὰ μὴν ἐρῶ γὰρ καὶ ταῦτα ἐξ ὧν ἔχω ἐλπίδας καὶ σὲ βουλήσεσθαι φίλον ἡμῖν εἶναι.", "st": "2.5.12"}, {"sp": "N", "t": "οἶδα μὲν γὰρ ὑμῖν Μυσοὺς λυπηροὺς ὄντας, οὓς νομίζω ἂν σὺν τῆι παρούσηι δυνάμει ταπεινοὺς ὑμῖν παρασχεῖν· οἶδα δὲ καὶ Πισίδας· ἀκούω δὲ καὶ ἄλλα ἔθνη πολλὰ τοιαῦτα εἶναι, ἃ οἶμαι ἂν παῦσαι ἐνοχλοῦντα ἀεὶ τῆι ὑμετέραι εὐδαιμονίαι. Αἰγυπτίους δέ, οἷς μάλιστα ὑμᾶς γιγνώσκω τεθυμωμένους, οὐχ ὁρῶ ποίαι δυνάμει συμμάχωι χρησάμενοι μᾶλλον ἂν κολάσαισθε τῆς νῦν σὺν ἐμοὶ οὔσης.", "st": "2.5.13"}, {"sp": "N", "t": "ἀλλὰ μὴν ἔν γε τοῖς πέριξ οἰκοῦσι σὺ εἰ μὲν βούλοιο φίλος ὡς μέγιστος ἂν εἴης, εἰ δέ τίς σε λυποίη, ὡς δεσπότης ⟨ἂν⟩ ἀναστρέφοιο ἔχων ἡμᾶς ὑπηρέτας, οἵ σοι οὐκ ἂν μισθοῦ ἕνεκα ὑπηρετοῖμεν ἀλλὰ καὶ τῆς χάριτος ἣν σωθέντες ὑπὸ σοῦ σοὶ ἂν ἔχοιμεν δικαίως.", "st": "2.5.14"}, {"sp": "N", "t": "ἐμοὶ μὲν ταῦτα πάντα ἐνθυμουμένωι οὕτω δοκεῖ θαυμαστὸν εἶναι τὸ σὲ ἡμῖν ἀπιστεῖν ὥστε καὶ ἥδιστ᾽ ἂν ἀκούσαιμι τὸ ὄνομα τίς οὕτως ἐστὶ δεινὸς λέγειν ὥστε σε πεῖσαι λέγων ὡς ἡμεῖς σοι ἐπιβουλεύομεν.» Κλέαρχος μὲν οὖν τοσαῦτα εἶπε· Τισσαφέρνης δὲ ὧδε ἀπημείφθη.", "st": "2.5.15"}, {"sp": "N", "t": "«ἀλλ᾽ ἥδομαι μέν, ὦ Κλέαρχε, ἀκούων σου φρονίμους λόγους· ταῦτα γὰρ γιγνώσκων εἴ τι ἐμοὶ κακὸν βουλεύοις, ἅμα ἄν μοι δοκεῖς καὶ σαυτῶι κακόνους εἶναι. ὡς δ᾽ ἂν μάθηις ὅτι οὐδ᾽ ἂν ὑμεῖς δικαίως οὔτε βασιλεῖ οὔτ᾽ ἐμοὶ ἀπιστοίητε, ἀντάκουσον.", "st": "2.5.16"}, {"sp": "N", "t": "εἰ γὰρ ὑμᾶς ἐβουλόμεθα ἀπολέσαι, πότερά σοι δοκοῦμεν ἱππέων πλήθους ἀπορεῖν ἢ πεζῶν ἢ ὁπλίσεως ἐν ἧι ὑμᾶς μὲν βλάπτειν ἱκανοὶ εἴημεν ἄν, ἀντιπάσχειν δὲ οὐδεὶς κίνδυνος;", "st": "2.5.17"}, {"sp": "N", "t": "ἀλλὰ χωρίων ἐπιτηδείων ὑμῖν ἐπιτίθεσθαι ἀπορεῖν ἄν σοι δοκοῦμεν; οὐ τοσαῦτα μὲν πεδία ἃ ὑμεῖς φίλια ὄντα σὺν πολλῶι πόνωι διαπορεύεσθε, τοσαῦτα δὲ ὄρη ὁρᾶτε ὑμῖν ὄντα πορευτέα, ἃ ἡμῖν ἔξεστι προκαταλαβοῦσιν ἄπορα ὑμῖν παρέχειν, τοσοῦτοι δ᾽ εἰσὶ ποταμοὶ ἐφ᾽ ὧν ἔξεστιν ἡμῖν ταμιεύεσθαι ὁπόσοις ἂν ὑμῶν βουλώμεθα μάχεσθαι; εἰσὶ δ᾽ αὐτῶν οὓς οὐδ᾽ ἂν παντάπασι διαβαίητε, εἰ μὴ ἡμεῖς ὑμᾶς διαπορεύοιμεν.", "st": "2.5.18"}, {"sp": "N", "t": "εἰ δ᾽ ἐν πᾶσι τούτοις ἡττώιμεθα, ἀλλὰ τό γέ τοι πῦρ κρεῖττον τοῦ καρποῦ ἐστιν· ὃν ἡμεῖς δυναίμεθ᾽ ἂν κατακαύσαντες λιμὸν ὑμῖν ἀντιτάξαι, ὧι ὑμεῖς οὐδ᾽ εἰ πάνυ ἀγαθοὶ εἴητε μάχεσθαι ἂν δύναισθε.", "st": "2.5.19"}, {"sp": "N", "t": "πῶς ἂν οὖν ἔχοντες τοσούτους πόρους πρὸς τὸ ὑμῖν πολεμεῖν, καὶ τούτων μηδένα ἡμῖν ἐπικίνδυνον, ἔπειτα ἐκ τούτων πάντων τοῦτον ἂν τὸν τρόπον ἐξελοίμεθα ὃς μόνος μὲν πρὸς θεῶν ἀσεβής, μόνος δὲ πρὸς ἀνθρώπων αἰσχρός;", "st": "2.5.20"}, {"sp": "N", "t": "παντάπασι δὲ ἀπόρων ἐστὶ καὶ ἀμηχάνων καὶ ἐν ἀνάγκηι ἐχομένων, καὶ τούτων πονηρῶν, οἵτινες ἐθέλουσι δι᾽ ἐπιορκίας τε πρὸς θεοὺς καὶ ἀπιστίας πρὸς ἀνθρώπους πράττειν τι. οὐχ οὕτως ἡμεῖς, ὦ Κλέαρχε, οὔτε ἀλόγιστοι οὔτε ἠλίθιοί ἐσμεν.", "st": "2.5.21"}, {"sp": "N", "t": "ἀλλὰ τί δὴ ὑμᾶς ἐξὸν ἀπολέσαι οὐκ ἐπὶ τοῦτο ἤλθομεν; εὖ ἴσθι ὅτι ὁ ἐμὸς ἔρως τούτου αἴτιος τὸ τοῖς Ἕλλησιν ἐμὲ πιστὸν γενέσθαι, καὶ ὧι Κῦρος ἀνέβη ξενικῶι διὰ μισθοδοσίας πιστεύων τούτωι ἐμὲ καταβῆναι δι᾽ εὐεργεσίαν ἰσχυρόν.", "st": "2.5.22"}, {"sp": "N", "t": "ὅσα δ᾽ ἐμοὶ χρήσιμοι ὑμεῖς ἐστε τὰ μὲν καὶ σὺ εἶπας, τὸ δὲ μέγιστον ἐγὼ οἶδα· τὴν μὲν γὰρ ἐπὶ τῆι κεφαλῆι τιάραν βασιλεῖ μόνωι ἔξεστιν ὀρθὴν ἔχειν, τὴν δ᾽ ἐπὶ τῆι καρδίαι ἴσως ἂν ὑμῶν παρόντων καὶ ἕτερος εὐπετῶς ἔχοι.»", "st": "2.5.23"}, {"sp": "N", "t": "ταῦτα εἰπὼν ἔδοξε τῶι Κλεάρχωι ἀληθῆ λέγειν· καὶ εἶπεν· «οὐκοῦν, ἔφη, οἵτινες τοιούτων ἡμῖν εἰς φιλίαν ὑπαρχόντων πειρῶνται διαβάλλοντες ποιῆσαι πολεμίους ἡμᾶς ἄξιοί εἰσι τὰ ἔσχατα παθεῖν;»", "st": "2.5.24"}, {"sp": "N", "t": "«καὶ ἐγὼ μέν γε, ἔφη ὁ Τισσαφέρνης, εἰ βούλεσθέ μοι οἵ τε στρατηγοὶ καὶ οἱ λοχαγοὶ ἐλθεῖν, ἐν τῶι ἐμφανεῖ λέξω τοὺς πρὸς ἐμὲ λέγοντας ὡς σὺ ἐμοὶ ἐπιβουλεύεις καὶ τῆι σὺν ἐμοὶ στρατιᾶι.»", "st": "2.5.25"}, {"sp": "N", "t": "«ἐγὼ δέ, ἔφη ὁ Κλέαρχος, ἄξω πάντας, καὶ σοὶ αὖ δηλώσω ὅθεν ἐγὼ περὶ σοῦ ἀκούω.»", "st": "2.5.26"}, {"sp": "N", "t": "ἐκ τούτων δὴ τῶν λόγων ὁ Τισσαφέρνης φιλοφρονούμενος τότε μὲν μένειν τε αὐτὸν ἐκέλευε καὶ σύνδειπνον ἐποιήσατο. τῆι δὲ ὑστεραίαι ὁ Κλέαρχος ἐλθὼν ἐπὶ τὸ στρατόπεδον δῆλός τ᾽ ἦν πάνυ φιλικῶς οἰόμενος διακεῖσθαι τῶι Τισσαφέρνει καὶ ἃ ἔλεγεν ἐκεῖνος ἀπήγγελλεν, ἔφη τε χρῆναι ἰέναι παρὰ Τισσαφέρνην οὓς ἐκέλευεν, καὶ οἳ ἂν ἐλεγχθῶσι διαβάλλοντες τῶν Ἑλλήνων, ὡς προδότας αὐτοὺς καὶ κακόνους τοῖς Ἕλλησιν ὄντας τιμωρηθῆναι.", "st": "2.5.27"}, {"sp": "N", "t": "ὑπώπτευε δὲ εἶναι τὸν διαβάλλοντα Μένωνα, εἰδὼς αὐτὸν καὶ συγγεγενημένον Τισσαφέρνει μετ᾽ Ἀριαίου καὶ στασιάζοντα αὐτῶι καὶ ἐπιβουλεύοντα, ὅπως τὸ στράτευμα ἅπαν πρὸς αὑτὸν λαβὼν φίλος ἦι Τισσαφέρνει.", "st": "2.5.28"}, {"sp": "N", "t": "ἐβούλετο δὲ καὶ Κλέαρχος ἅπαν τὸ στράτευμα πρὸς ἑαυτὸν ἔχειν τὴν γνώμην καὶ τοὺς παραλυποῦντας ἐκποδὼν εἶναι. τῶν δὲ στρατιωτῶν ἀντέλεγόν τινες αὐτῶι μὴ ἰέναι πάντας τοὺς λοχαγοὺς καὶ στρατηγοὺς μηδὲ πιστεύειν Τισσαφέρνει.", "st": "2.5.29"}, {"sp": "N", "t": "ὁ δὲ Κλέαρχος ἰσχυρῶς κατέτεινεν, ἔστε διεπράξατο πέντε μὲν στρατηγοὺς ἰέναι, εἴκοσι δὲ λοχαγούς· συνηκολούθησαν δὲ ὡς εἰς ἀγορὰν καὶ τῶν ἄλλων στρατιωτῶν ὡς διακόσιοι.", "st": "2.5.30"}, {"sp": "N", "t": "ἐπεὶ δὲ ἦσαν ἐπὶ θύραις ταῖς Τισσαφέρνους, οἱ μὲν στρατηγοὶ παρεκλήθησαν εἴσω, Πρόξενος Βοιώτιος, Μένων Θετταλός, Ἀγίας Ἀρκάς, Κλέαρχος Λάκων, Σωκράτης Ἀχαιός· οἱ δὲ λοχαγοὶ ἐπὶ ταῖς θύραις ἔμενον.", "st": "2.5.31"}, {"sp": "N", "t": "οὐ πολλῶι δὲ ὕστερον ἀπὸ τοῦ αὐτοῦ σημείου οἵ τ᾽ ἔνδον ξυνελαμβάνοντο καὶ οἱ ἔξω κατεκόπησαν. μετὰ δὲ ταῦτα τῶν βαρβάρων τινὲς ἱππέων διὰ τοῦ πεδίου ἐλαύνοντες ὧιτινι ἐντυγχάνοιεν Ἕλληνι ἢ δούλωι ἢ ἐλευθέρωι πάντας ἔκτεινον.", "st": "2.5.32"}, {"sp": "N", "t": "οἱ δὲ Ἕλληνες τήν τε ἱππασίαν ἐθαύμαζον ἐκ τοῦ στρατοπέδου ὁρῶντες καὶ ὅ τι ἐποίουν ἠμφεγνόουν, πρὶν Νίκαρχος Ἀρκὰς ἧκε φεύγων τετρωμένος εἰς τὴν γαστέρα καὶ τὰ ἔντερα ἐν ταῖς χερσὶν ἔχων, καὶ εἶπε πάντα τὰ γεγενημένα.", "st": "2.5.33"}, {"sp": "N", "t": "ἐκ τούτου δὴ οἱ Ἕλληνες ἔθεον ἐπὶ τὰ ὅπλα πάντες ἐκπεπληγμένοι καὶ νομίζοντες αὐτίκα ἥξειν αὐτοὺς ἐπὶ τὸ στρατόπεδον.", "st": "2.5.34"}, {"sp": "N", "t": "οἱ δὲ πάντες μὲν οὐκ ἦλθον, Ἀριαῖος δὲ καὶ Ἀρτάοζος καὶ Μιθραδάτης, οἳ ἦσαν Κύρωι πιστότατοι· ὁ δὲ τῶν Ἑλλήνων ἑρμηνεὺς ἔφη καὶ τὸν Τισσαφέρνους ἀδελφὸν σὺν αὐτοῖς ὁρᾶν καὶ γιγνώσκειν· ξυνηκολούθουν δὲ καὶ ἄλλοι Περσῶν τεθωρακισμένοι εἰς τριακοσίους.", "st": "2.5.35"}, {"sp": "N", "t": "οὗτοι ἐπεὶ ἐγγὺς ἦσαν, προσελθεῖν ἐκέλευον εἴ τις εἴη τῶν Ἑλλήνων στρατηγὸς ἢ λοχαγός, ἵνα ἀπαγγείλωσι τὰ παρὰ βασιλέως.", "st": "2.5.36"}, {"sp": "N", "t": "μετὰ ταῦτα ἐξῆλθον φυλαττόμενοι τῶν Ἑλλήνων στρατηγοὶ μὲν Κλεάνωρ Ὀρχομένιος καὶ Σοφαίνετος Στυμφάλιος, ξὺν αὐτοῖς δὲ Ξενοφῶν Ἀθηναῖος, ὅπως μάθοι τὰ περὶ Προξένου· Χειρίσοφος δὲ ἐτύγχανεν ἀπὼν ἐν κώμηι τινὶ ξὺν ἄλλοις ἐπισιτιζομένοις.", "st": "2.5.37"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἔστησαν εἰς ἐπήκοον, εἶπεν Ἀριαῖος τάδε. Κλέαρχος μέν, ὦ ἄνδρες Ἕλληνες, ἐπεὶ ἐπιορκῶν τε ἐφάνη καὶ τὰς σπονδὰς λύων, ἔχει τὴν δίκην καὶ τέθνηκε, Πρόξενος δὲ καὶ Μένων, ὅτι κατήγγειλαν αὐτοῦ τὴν ἐπιβουλήν, ἐν μεγάληι τιμῆι εἰσιν. ὑμᾶς δὲ βασιλεὺς τὰ ὅπλα ἀπαιτεῖ· αὑτοῦ γὰρ εἶναί φησιν, ἐπείπερ Κύρου ἦσαν τοῦ ἐκείνου δούλου.", "st": "2.5.38"}, {"sp": "N", "t": "πρὸς ταῦτα ἀπεκρίναντο οἱ Ἕλληνες, ἔλεγε δὲ Κλεάνωρ ὁ Ὀρχομένιος· «ὦ κάκιστε ἀνθρώπων Ἀριαῖε καὶ οἱ ἄλλοι ὅσοι ἦτε Κύρου φίλοι, οὐκ αἰσχύνεσθε οὔτε θεοὺς οὔτ᾽ ἀνθρώπους, οἵτινες ὀμόσαντες ἡμῖν τοὺς αὐτοὺς φίλους καὶ ἐχθροὺς νομιεῖν, προδόντες ἡμᾶς σὺν Τισσαφέρνει τῶι ἀθεωτάτωι τε καὶ πανουργοτάτωι τούς τε ἄνδρας αὐτοὺς οἷς ὤμνυτε ἀπολωλέκατε καὶ τοὺς ἄλλους ἡμᾶς προδεδωκότες ξὺν τοῖς πολεμίοις ἐφ᾽ ἡμᾶς ἔρχεσθε;»", "st": "2.5.39"}, {"sp": "N", "t": "ὁ δὲ Ἀριαῖος εἶπε· «Κλέαρχος γὰρ πρόσθεν ἐπιβουλεύων φανερὸς ἐγένετο Τισσαφέρνει τε καὶ Ὀρόνται, καὶ πᾶσιν ἡμῖν τοῖς ξὺν τούτοις.» ἐπὶ τούτοις Ξενοφῶν τάδε εἶπε.", "st": "2.5.40"}, {"sp": "N", "t": "»Κλέαρχος μὲν τοίνυν εἰ παρὰ τοὺς ὅρκους ἔλυε τὰς σπονδάς, τὴν δίκην ἔχει· δίκαιον γὰρ ἀπόλλυσθαι τοὺς ἐπιορκοῦντας· Πρόξενος δὲ καὶ Μένων ἐπείπερ εἰσὶν ὑμέτεροι μὲν εὐεργέται, ἡμέτεροι δὲ στρατηγοί, πέμψατε αὐτοὺς δεῦρο· δῆλον γὰρ ὅτι φίλοι γε ὄντες ἀμφοτέροις πειράσονται καὶ ὑμῖν καὶ ἡμῖν τὰ βέλτιστα ξυμβουλεῦσαι.»", "st": "2.5.41"}, {"sp": "N", "t": "πρὸς ταῦτα οἱ βάρβαροι πολὺν χρόνον διαλεχθέντες ἀλλήλοις ἀπῆλθον οὐδὲν ἀποκρινάμενοι.", "st": "2.5.42"}, {"sp": "N", "t": "οἱ μὲν δὴ στρατηγοὶ οὕτω ληφθέντες ἀνήχθησαν ὡς βασιλέα καὶ ἀποτμηθέντες τὰς κεφαλὰς ἐτελεύτησαν, εἷς μὲν αὐτῶν Κλέαρχος ὁμολογουμένως ἐκ πάντων τῶν ἐμπείρως αὐτοῦ ἐχόντων δόξας γενέσθαι ἀνὴρ καὶ πολεμικὸς καὶ φιλοπόλεμος ἐσχάτως.", "st": "2.6.1"}, {"sp": "N", "t": "καὶ γὰρ δὴ ἕως μὲν πόλεμος ἦν τοῖς Λακεδαιμονίοις πρὸς τοὺς Ἀθηναίους παρέμενεν, ἐπειδὴ δὲ εἰρήνη ἐγένετο, πείσας τὴν αὑτοῦ πόλιν ὡς οἱ Θρᾶικες ἀδικοῦσι τοὺς Ἕλληνας καὶ διαπραξάμενος ὡς ἐδύνατο παρὰ τῶν ἐφόρων ἐξέπλει ὡς πολεμήσων τοῖς ὑπὲρ Χερρονήσου καὶ Περίνθου Θραιξίν.", "st": "2.6.2"}, {"sp": "N", "t": "ἐπεὶ δὲ μεταγνόντες πως οἱ ἔφοροι ἤδη ἔξω ὄντος ἀποστρέφειν αὐτὸν ἐπειρῶντο ἐξ Ἰσθμοῦ, ἐνταῦθα οὐκέτι πείθεται, ἀλλ᾽ ὤιχετο πλέων εἰς Ἑλλήσποντον.", "st": "2.6.3"}, {"sp": "N", "t": "ἐκ τούτου καὶ ἐθανατώθη ὑπὸ τῶν ἐν Σπάρτηι τελῶν ὡς ἀπειθῶν. ἤδη δὲ φυγὰς ὢν ἔρχεται πρὸς Κῦρον, καὶ ὁποίοις μὲν λόγοις ἔπεισε Κῦρον ἄλληι γέγραπται, δίδωσι δὲ αὐτῶι Κῦρος μυρίους δαρεικούς·", "st": "2.6.4"}, {"sp": "N", "t": "ὁ δὲ λαβὼν οὐκ ἐπὶ ῥαιθυμίαν ἐτράπετο, ἀλλ᾽ ἀπὸ τούτων τῶν χρημάτων συλλέξας στράτευμα ἐπολέμει τοῖς Θραιξί, καὶ μάχηι τε ἐνίκησε καὶ ἀπὸ τούτου δὴ ἔφερε καὶ ἦγε τούτους καὶ πολεμῶν διεγένετο μέχρι Κῦρος ἐδεήθη τοῦ στρατεύματος· τότε δὲ ἀπῆλθεν ὡς ξὺν ἐκείνωι αὖ πολεμήσων.", "st": "2.6.5"}, {"sp": "N", "t": "ταῦτα οὖν φιλοπολέμου μοι δοκεῖ ἀνδρὸς ἔργα εἶναι, ὅστις ἐξὸν μὲν εἰρήνην ἄγειν ἄνευ αἰσχύνης καὶ βλάβης αἱρεῖται πολεμεῖν, ἐξὸν δὲ ῥαιθυμεῖν βούλεται πονεῖν ὥστε πολεμεῖν, ἐξὸν δὲ χρήματα ἔχειν ἀκινδύνως αἱρεῖται πολεμῶν μείονα ταῦτα ποιεῖν· ἐκεῖνος δὲ ὥσπερ εἰς παιδικὰ ἢ εἰς ἄλλην τινὰ ἡδονὴν ἤθελε δαπανᾶν εἰς πόλεμον.", "st": "2.6.6"}, {"sp": "N", "t": "οὕτω μὲν φιλοπόλεμος ἦν· πολεμικὸς δὲ αὖ ταύτηι ἐδόκει εἶναι ὅτι φιλοκίνδυνός τε ἦν καὶ ἡμέρας καὶ νυκτὸς ἄγων ἐπὶ τοὺς πολεμίους καὶ ἐν τοῖς δεινοῖς φρόνιμος, ὡς οἱ παρόντες πανταχοῦ πάντες ὡμολόγουν.", "st": "2.6.7"}, {"sp": "N", "t": "καὶ ἀρχικὸς δ᾽ ἐλέγετο εἶναι ὡς δυνατὸν ἐκ τοῦ τοιούτου τρόπου οἷον κἀκεῖνος εἶχεν. ἱκανὸς μὲν γὰρ ὥς τις καὶ ἄλλος φροντίζειν ἦν ὅπως ἔχοι ἡ στρατιὰ αὐτῶι τὰ ἐπιτήδεια καὶ παρασκευάζειν ταῦτα, ἱκανὸς δὲ καὶ ἐμποιῆσαι τοῖς παροῦσιν ὡς πειστέον εἴη Κλεάρχωι.", "st": "2.6.8"}, {"sp": "N", "t": "τοῦτο δ᾽ ἐποίει ἐκ τοῦ χαλεπὸς εἶναι· καὶ γὰρ ὁρᾶν στυγνὸς ἦν καὶ τῆι φωνῆι τραχύς, ἐκόλαζέ τε ἰσχυρῶς, καὶ ὀργῆι ἐνίοτε, ὡς καὶ αὐτῶι μεταμέλειν ἔσθ᾽ ὅτε.", "st": "2.6.9"}, {"sp": "N", "t": "καὶ γνώμηι δ᾽ ἐκόλαζεν· ἀκολάστου γὰρ στρατεύματος οὐδὲν ἡγεῖτο ὄφελος εἶναι, ἀλλὰ καὶ λέγειν αὐτὸν ἔφασαν ὡς δέοι τὸν στρατιώτην φοβεῖσθαι μᾶλλον τὸν ἄρχοντα ἢ τοὺς πολεμίους, εἰ μέλλοι ἢ φυλακὰς φυλάξειν ἢ φίλων ἀφέξεσθαι ἢ ἀπροφασίστως ἰέναι πρὸς τοὺς πολεμίους.", "st": "2.6.10"}, {"sp": "N", "t": "ἐν μὲν οὖν τοῖς δεινοῖς ἤθελον αὐτοῦ ἀκούειν σφόδρα καὶ οὐκ ἄλλον ἡιροῦντο οἱ στρατιῶται· καὶ γὰρ τὸ στυγνὸν τότε φαιδρὸν αὐτοῦ ἐν τοῖς ἄλλοις προσώποις ἔφασαν φαίνεσθαι καὶ τὸ χαλεπὸν ἐρρωμένον πρὸς τοὺς πολεμίους ἐδόκει εἶναι, ὥστε σωτήριον, οὐκέτι χαλεπὸν ἐφαίνετο·", "st": "2.6.11"}, {"sp": "N", "t": "ὅτε δ᾽ ἔξω τοῦ δεινοῦ γένοιντο καὶ ἐξείη πρὸς ἄλλον ἀρξομένους ἀπιέναι, πολλοὶ αὐτὸν ἀπέλειπον· τὸ γὰρ ἐπίχαρι οὐκ εἶχεν, ἀλλ᾽ ἀεὶ χαλεπὸς ἦν καὶ ὠμός· ὥστε διέκειντο πρὸς αὐτὸν οἱ στρατιῶται ὥσπερ παῖδες πρὸς διδάσκαλον.", "st": "2.6.12"}, {"sp": "N", "t": "καὶ γὰρ οὖν φιλίαι μὲν καὶ εὐνοίαι ἑπομένους οὐδέποτε εἶχεν· οἵτινες δὲ ἢ ὑπὸ πόλεως τεταγμένοι ἢ ὑπὸ τοῦ δεῖσθαι ἢ ἄλληι τινὶ ἀνάγκηι κατεχόμενοι παρείησαν αὐτῶι, σφόδρα πειθομένοις ἐχρῆτο.", "st": "2.6.13"}, {"sp": "N", "t": "ἐπεὶ δὲ ἄρξαιντο νικᾶν ξὺν αὐτῶι τοὺς πολεμίους, ἤδη μεγάλα ἦν τὰ χρησίμους ποιοῦντα εἶναι τοὺς ξὺν αὐτῶι στρατιώτας· τό τε γὰρ πρὸς τοὺς πολεμίους θαρραλέως ἔχειν παρῆν καὶ τὸ τὴν παρ᾽ ἐκείνου τιμωρίαν φοβεῖσθαι εὐτάκτους ἐποίει.", "st": "2.6.14"}, {"sp": "N", "t": "τοιοῦτος μὲν δὴ ἄρχων ἦν· ἄρχεσθαι δὲ ὑπὸ ἄλλων οὐ μάλα ἐθέλειν ἐλέγετο. ἦν δὲ ὅτε ἐτελεύτα ἀμφὶ τὰ πεντήκοντα ἔτη.", "st": "2.6.15"}, {"sp": "N", "t": "Πρόξενος δὲ ὁ Βοιώτιος εὐθὺς μὲν μειράκιον ὢν ἐπεθύμει γενέσθαι ἀνὴρ τὰ μεγάλα πράττειν ἱκανός· καὶ διὰ ταύτην τὴν ἐπιθυμίαν ἔδωκε Γοργίαι ἀργύριον τῶι Λεοντίνωι.", "st": "2.6.16"}, {"sp": "N", "t": "ἐπεὶ δὲ συνεγένετο ἐκείνωι, ἱκανὸς νομίσας ἤδη εἶναι καὶ ἄρχειν καὶ φίλος ὢν τοῖς πρώτοις μὴ ἡττᾶσθαι εὐεργετῶν, ἦλθεν εἰς ταύτας τὰς σὺν Κύρωι πράξεις· καὶ ὤιετο κτήσεσθαι ἐκ τούτων ὄνομα μέγα καὶ δύναμιν μεγάλην καὶ χρήματα πολλά·", "st": "2.6.17"}, {"sp": "N", "t": "τοσούτων δ᾽ ἐπιθυμῶν σφόδρα ἔνδηλον αὖ καὶ τοῦτο εἶχεν, ὅτι τούτων οὐδὲν ἂν θέλοι κτᾶσθαι μετὰ ἀδικίας, ἀλλὰ σὺν τῶι δικαίωι καὶ καλῶι ὤιετο δεῖν τούτων τυγχάνειν, ἄνευ δὲ τούτων μή.", "st": "2.6.18"}, {"sp": "N", "t": "ἄρχειν δὲ καλῶν μὲν καὶ ἀγαθῶν δυνατὸς ἦν· οὐ μέντοι οὔτ᾽ αἰδῶ τοῖς στρατιώταις ἑαυτοῦ οὔτε φόβον ἱκανὸς ἐμποιῆσαι, ἀλλὰ καὶ ἠισχύνετο μᾶλλον τοὺς στρατιώτας ἢ οἱ ἀρχόμενοι ἐκεῖνον· καὶ φοβούμενος μᾶλλον ἦν φανερὸς τὸ ἀπεχθάνεσθαι τοῖς στρατιώταις ἢ οἱ στρατιῶται τὸ ἀπιστεῖν ἐκείνωι.", "st": "2.6.19"}, {"sp": "N", "t": "ὤιετο δὲ ἀρκεῖν πρὸς τὸ ἀρχικὸν εἶναι καὶ δοκεῖν τὸν μὲν καλῶς ποιοῦντα ἐπαινεῖν, τὸν δὲ ἀδικοῦντα μὴ ἐπαινεῖν. τοιγαροῦν αὐτῶι οἱ μὲν καλοί τε καὶ ἀγαθοὶ τῶν συνόντων εὖνοι ἦσαν, οἱ δὲ ἄδικοι ἐπεβούλευον ὡς εὐμεταχειρίστωι ὄντι. ὅτε δὲ ἀπέθνηισκεν ἦν ἐτῶν ὡς τριάκοντα.", "st": "2.6.20"}, {"sp": "N", "t": "Μένων δὲ ὁ Θετταλὸς δῆλος ἦν ἐπιθυμῶν μὲν πλουτεῖν ἰσχυρῶς, ἐπιθυμῶν δὲ ἄρχειν, ὅπως πλείω λαμβάνοι, ἐπιθυμῶν δὲ τιμᾶσθαι, ἵνα πλείω κερδαίνοι· φίλος τε ἐβούλετο εἶναι τοῖς μέγιστα δυναμένοις, ἵνα ἀδικῶν μὴ διδοίη δίκην.", "st": "2.6.21"}, {"sp": "N", "t": "ἐπὶ δὲ τὸ κατεργάζεσθαι ὧν ἐπιθυμοίη συντομωτάτην ὤιετο ὁδὸν εἶναι διὰ τοῦ ἐπιορκεῖν τε καὶ ψεύδεσθαι καὶ ἐξαπατᾶν, τὸ δ᾽ ἁπλοῦν καὶ ἀληθὲς τὸ αὐτὸ τῶι ἠλιθίωι εἶναι.", "st": "2.6.22"}, {"sp": "N", "t": "στέργων δὲ φανερὸς μὲν ἦν οὐδένα, ὅτωι δὲ φαίη φίλος εἶναι, τούτωι ἔνδηλος ἐγίγνετο ἐπιβουλεύων. καὶ πολεμίου μὲν οὐδενὸς κατεγέλα, τῶν δὲ συνόντων πάντων ὡς καταγελῶν ἀεὶ διελέγετο.", "st": "2.6.23"}, {"sp": "N", "t": "καὶ τοῖς μὲν τῶν πολεμίων κτήμασιν οὐκ ἐπεβούλευε· χαλεπὸν γὰρ ὤιετο εἶναι τὰ τῶν φυλαττομένων λαμβάνειν· τὰ δὲ τῶν φίλων μόνος ὤιετο εἰδέναι ῥᾶιστον ὂν ἀφύλακτα λαμβάνειν.", "st": "2.6.24"}, {"sp": "N", "t": "καὶ ὅσους μὲν αἰσθάνοιτο ἐπιόρκους καὶ ἀδίκους ὡς εὖ ὡπλισμένους ἐφοβεῖτο, τοῖς δὲ ὁσίοις καὶ ἀλήθειαν ἀσκοῦσιν ὡς ἀνάνδροις ἐπειρᾶτο χρῆσθαι.", "st": "2.6.25"}, {"sp": "N", "t": "ὥσπερ δέ τις ἀγάλλεται ἐπὶ θεοσεβείαι καὶ ἀληθείαι καὶ δικαιότητι, οὕτω Μένων ἠγάλλετο τῶι ἐξαπατᾶν δύνασθαι, τῶι πλάσασθαι ψεύδη, τῶι φίλους διαγελᾶν· τὸν δὲ μὴ πανοῦργον τῶν ἀπαιδεύτων ἀεὶ ἐνόμιζεν εἶναι. καὶ παρ᾽ οἷς μὲν ἐπεχείρει πρωτεύειν φιλίαι, διαβάλλων τοὺς πρώτους τοῦτο ὤιετο δεῖν κτήσασθαι.", "st": "2.6.26"}, {"sp": "N", "t": "τὸ δὲ πειθομένους τοὺς στρατιώτας παρέχεσθαι ἐκ τοῦ συναδικεῖν αὐτοῖς ἐμηχανᾶτο. τιμᾶσθαι δὲ καὶ θεραπεύεσθαι ἠξίου ἐπιδεικνύμενος ὅτι πλεῖστα δύναιτο καὶ ἐθέλοι ἂν ἀδικεῖν. εὐεργεσίαν δὲ κατέλεγεν, ὁπότε τις αὐτοῦ ἀφίσταιτο, ὅτι χρώμενος αὐτῶι οὐκ ἀπώλεσεν αὐτόν.", "st": "2.6.27"}, {"sp": "N", "t": "καὶ τὰ μὲν δὴ ἀφανῆ ἔξεστι περὶ αὐτοῦ ψεύδεσθαι, ἃ δὲ πάντες ἴσασι τάδ᾽ ἐστί. παρὰ Ἀριστίππου μὲν ἔτι ὡραῖος ὢν στρατηγεῖν διεπράξατο τῶν ξένων, Ἀριαίωι δὲ βαρβάρωι ὄντι, ὅτι μειρακίοις καλοῖς ἥδετο, οἰκειότατος [ἔτι ὡραῖος ὢν] ἐγένετο, αὐτὸς δὲ παιδικὰ εἶχε Θαρύπαν ἀγένειος ὢν γενειῶντα.", "st": "2.6.28"}, {"sp": "N", "t": "ἀποθνηισκόντων δὲ τῶν συστρατήγων ὅτι ἐστράτευσαν ἐπὶ βασιλέα ξὺν Κύρωι, ταὐτὰ πεποιηκὼς οὐκ ἀπέθανε, μετὰ δὲ τὸν τῶν ἄλλων θάνατον στρατηγῶν τιμωρηθεὶς ὑπὸ βασιλέως ἀπέθανεν, οὐχ ὥσπερ Κλέαρχος καὶ οἱ ἄλλοι στρατηγοὶ ἀποτμηθέντες τὰς κεφαλάς, ὅσπερ τάχιστος θάνατος δοκεῖ εἶναι, ἀλλὰ ζῶν αἰκισθεὶς ἐνιαυτὸν ὡς πονηρὸς λέγεται τῆς τελευτῆς τυχεῖν.", "st": "2.6.29"}, {"sp": "N", "t": "Ἀγίας δὲ ὁ Ἀρκὰς καὶ Σωκράτης ὁ Ἀχαιὸς καὶ τούτω ἀπεθανέτην. τούτων δὲ οὔθ᾽ ὡς ἐν πολέμωι κακῶν οὐδεὶς κατεγέλα οὔτ᾽ εἰς φιλίαν αὐτοὺς ἐμέμφετο. ἤστην δὲ ἄμφω ἀμφὶ τὰ πέντε καὶ τριάκοντα ἔτη ἀπὸ γενεᾶς.", "st": "2.6.30"}, {"sp": "HDR", "t": "Βιβλίον γʹ", "st": "3.1.1"}, {"sp": "N", "t": "[ Ὅσα μὲν δὴ ἐν τῆι Κύρου ἀναβάσει οἱ Ἕλληνες ἔπραξαν μέχρι τῆς μάχης, καὶ ὅσα ἐπεὶ Κῦρος ἐτελεύτησεν ἐγένετο ἀπιόντων τῶν Ἑλλήνων σὺν Τισσαφέρνει ἐν ταῖς σπονδαῖς, ἐν τῶι πρόσθεν λόγωι δεδήλωται.]", "st": "3.1.1"}, {"sp": "N", "t": "Ἐπεὶ δὲ οἱ στρατηγοὶ συνειλημμένοι ἦσαν καὶ τῶν λοχαγῶν καὶ τῶν στρατιωτῶν οἱ συνεπόμενοι ἀπωλώλεσαν, ἐν πολλῆι δὴ ἀπορίαι ἦσαν οἱ Ἕλληνες, ἐννοούμενοι ὅτι ἐπὶ ταῖς βασιλέως θύραις ἦσαν, κύκλωι δὲ αὐτοῖς πάντηι πολλὰ καὶ ἔθνη καὶ πόλεις πολέμιαι ἦσαν, ἀγορὰν δὲ οὐδεὶς ἔτι παρέξειν ἔμελλεν, ἀπεῖχον δὲ τῆς Ἑλλάδος οὐ μεῖον ἢ μύρια στάδια, ἡγεμὼν δ᾽ οὐδεὶς τῆς ὁδοῦ ἦν, ποταμοὶ δὲ διεῖργον ἀδιάβατοι ἐν μέσωι τῆς οἴκαδε ὁδοῦ, προυδεδώκεσαν δὲ αὐτοὺς καὶ οἱ σὺν Κύρωι ἀναβάντες βάρβαροι, μόνοι δὲ καταλελειμμένοι ἦσαν οὐδὲ ἱππέα οὐδένα σύμμαχον ἔχοντες, ὥστε εὔδηλον ἦν ὅτι νικῶντες μὲν οὐδένα ἂν κατακάνοιεν, ἡττηθέντων δὲ αὐτῶν οὐδεὶς ἂν λειφθείη·", "st": "3.1.2"}, {"sp": "N", "t": "ταῦτ᾽ ἐννοούμενοι καὶ ἀθύμως ἔχοντες ὀλίγοι μὲν αὐτῶν εἰς τὴν ἑσπέραν σίτου ἐγεύσαντο, ὀλίγοι δὲ πῦρ ἀνέκαυσαν, ἐπὶ δὲ τὰ ὅπλα πολλοὶ οὐκ ἦλθον ταύτην τὴν νύκτα, ἀνεπαύοντο δὲ ὅπου ἐτύγχανον ἕκαστος, οὐ δυνάμενοι καθεύδειν ὑπὸ λύπης καὶ πόθου πατρίδων, γονέων, γυναικῶν, παίδων, οὓς οὔποτ᾽ ἐνόμιζον ἔτι ὄψεσθαι. οὕτω μὲν δὴ διακείμενοι πάντες ἀνεπαύοντο.", "st": "3.1.3"}, {"sp": "N", "t": "ἦν δέ τις ἐν τῆι στρατιᾶι Ξενοφῶν Ἀθηναῖος, ὃς οὔτε στρατηγὸς οὔτε λοχαγὸς οὔτε στρατιώτης ὢν συνηκολούθει, ἀλλὰ Πρόξενος αὐτὸν μετεπέμψατο οἴκοθεν ξένος ὢν ἀρχαῖος· ὑπισχνεῖτο δὲ αὐτῶι, εἰ ἔλθοι, φίλον αὐτὸν Κύρωι ποιήσειν, ὃν αὐτὸς ἔφη κρείττω ἑαυτῶι νομίζειν τῆς πατρίδος.", "st": "3.1.4"}, {"sp": "N", "t": "ὁ μέντοι Ξενοφῶν ἀναγνοὺς τὴν ἐπιστολὴν ἀνακοινοῦται Σωκράτει τῶι Ἀθηναίωι περὶ τῆς πορείας. καὶ ὁ Σωκράτης ὑποπτεύσας μή τι πρὸς τῆς πόλεως ὑπαίτιον εἴη Κύρωι φίλον γενέσθαι, ὅτι ἐδόκει ὁ Κῦρος προθύμως τοῖς Λακεδαιμονίοις ἐπὶ τὰς Ἀθήνας συμπολεμῆσαι, συμβουλεύει τῶι Ξενοφῶντι ἐλθόντα εἰς Δελφοὺς ἀνακοινῶσαι τῶι θεῶι περὶ τῆς πορείας.", "st": "3.1.5"}, {"sp": "N", "t": "ἐλθὼν δ᾽ ὁ Ξενοφῶν ἐπήρετο τὸν Ἀπόλλω τίνι ἂν θεῶν θύων καὶ εὐχόμενος κάλλιστα καὶ ἄριστα ἔλθοι τὴν ὁδὸν ἣν ἐπινοεῖ καὶ καλῶς πράξας σωθείη. καὶ ἀνεῖλεν αὐτῶι ὁ Ἀπόλλων θεοῖς οἷς ἔδει θύειν.", "st": "3.1.6"}, {"sp": "N", "t": "ἐπεὶ δὲ πάλιν ἦλθε, λέγει τὴν μαντείαν τῶι Σωκράτει. ὁ δ᾽ ἀκούσας ἠιτιᾶτο αὐτὸν ὅτι οὐ τοῦτο πρῶτον ἠρώτα πότερον λῶιον εἴη αὐτῶι πορεύεσθαι ἢ μένειν, ἀλλ᾽ αὐτὸς κρίνας ἰτέον εἶναι τοῦτ᾽ ἐπυνθάνετο ὅπως ἂν κάλλιστα πορευθείη. ἐπεὶ μέντοι οὕτως ἤρου, ταῦτ᾽, ἔφη, χρὴ ποιεῖν ὅσα ὁ θεὸς ἐκέλευσεν.", "st": "3.1.7"}, {"sp": "N", "t": "ὁ μὲν δὴ Ξενοφῶν οὕτω θυσάμενος οἷς ἀνεῖλεν ὁ θεὸς ἐξέπλει, καὶ καταλαμβάνει ἐν Σάρδεσι Πρόξενον καὶ Κῦρον μέλλοντας ἤδη ὁρμᾶν τὴν ἄνω ὁδόν, καὶ συνεστάθη Κύρωι.", "st": "3.1.8"}, {"sp": "N", "t": "προθυμουμένου δὲ τοῦ Προξένου καὶ ὁ Κῦρος συμπρουθυμεῖτο μεῖναι αὐτόν, εἶπε δὲ ὅτι ἐπειδὰν τάχιστα ἡ στρατεία λήξηι, εὐθὺς ἀποπέμψει αὐτόν. ἐλέγετο δὲ ὁ στόλος εἶναι εἰς Πισίδας.", "st": "3.1.9"}, {"sp": "N", "t": "ἐστρατεύετο μὲν δὴ οὕτως ἐξαπατηθείς – οὐχ ὑπὸ Προξένου· οὐ γὰρ ἤιδει τὴν ἐπὶ βασιλέα ὁρμὴν οὐδὲ ἄλλος οὐδεὶς τῶν Ἑλλήνων πλὴν Κλεάρχου· ἐπεὶ μέντοι εἰς Κιλικίαν ἦλθον, σαφὲς πᾶσιν ἤδη ἐδόκει εἶναι ὅτι ὁ στόλος εἴη ἐπὶ βασιλέα. φοβούμενοι δὲ τὴν ὁδὸν καὶ ἄκοντες ὅμως οἱ πολλοὶ δι᾽ αἰσχύνην καὶ ἀλλήλων καὶ Κύρου συνηκολούθησαν· ὧν εἷς καὶ Ξενοφῶν ἦν.", "st": "3.1.10"}, {"sp": "N", "t": "ἐπεὶ δὲ ἀπορία ἦν, ἐλυπεῖτο μὲν σὺν τοῖς ἄλλοις καὶ οὐκ ἐδύνατο καθεύδειν· μικρὸν δ᾽ ὕπνου λαχὼν εἶδεν ὄναρ. ἔδοξεν αὐτῶι βροντῆς γενομένης σκηπτὸς πεσεῖν εἰς τὴν πατρώιαν οἰκίαν, καὶ ἐκ τούτου λάμπεσθαι πᾶσα.", "st": "3.1.11"}, {"sp": "N", "t": "περίφοβος δ᾽ εὐθὺς ἀνηγέρθη, καὶ τὸ ὄναρ τῆι μὲν ἔκρινεν ἀγαθόν, ὅτι ἐν πόνοις ὢν καὶ κινδύνοις φῶς μέγα ἐκ Διὸς ἰδεῖν ἔδοξε· τῆι δὲ καὶ ἐφοβεῖτο, ὅτι ἀπὸ Διὸς μὲν βασιλέως τὸ ὄναρ ἐδόκει αὐτῶι εἶναι, κύκλωι δὲ ἐδόκει λάμπεσθαι τὸ πῦρ, μὴ οὐ δύναιτο ἐκ τῆς χώρας ἐξελθεῖν τῆς βασιλέως, ἀλλ᾽ εἴργοιτο πάντοθεν ὑπό τινων ἀποριῶν.", "st": "3.1.12"}, {"sp": "N", "t": "ὁποῖόν τι μὲν δὴ ἐστὶ τὸ τοιοῦτον ὄναρ ἰδεῖν ἔξεστι σκοπεῖν ἐκ τῶν συμβάντων μετὰ τὸ ὄναρ. γίγνεται γὰρ τάδε. εὐθὺς ἐπειδὴ ἀνηγέρθη πρῶτον μὲν ἔννοια αὐτῶι ἐμπίπτει· τί κατάκειμαι; ἡ δὲ νὺξ προβαίνει· ἅμα δὲ τῆι ἡμέραι εἰκὸς τοὺς πολεμίους ἥξειν. εἰ δὲ γενησόμεθα ἐπὶ βασιλεῖ, τί ἐμποδὼν μὴ οὐχὶ πάντα μὲν τὰ χαλεπώτατα ἐπιδόντας, πάντα δὲ τὰ δεινότατα παθόντας ὑβριζομένους ἀποθανεῖν;", "st": "3.1.13"}, {"sp": "N", "t": "ὅπως δ᾽ ἀμυνούμεθα οὐδεὶς παρασκευάζεται οὐδὲ ἐπιμελεῖται, ἀλλὰ κατακείμεθα ὥσπερ ἐξὸν ἡσυχίαν ἄγειν. ἐγὼ οὖν τὸν ἐκ ποίας πόλεως στρατηγὸν προσδοκῶ ταῦτα πράξειν; ποίαν δ᾽ ἡλικίαν ἐμαυτῶι ἐλθεῖν ἀναμείνω; οὐ γὰρ ἔγωγ᾽ ἔτι πρεσβύτερος ἔσομαι, ἐὰν τήμερον προδῶ ἐμαυτὸν τοῖς πολεμίοις.", "st": "3.1.14"}, {"sp": "N", "t": "ἐκ τούτου ἀνίσταται καὶ συγκαλεῖ τοὺς Προξένου πρῶτον λοχαγούς. ἐπεὶ δὲ συνῆλθον, ἔλεξεν· «ἐγώ, ὦ ἄνδρες λοχαγοί, οὔτε καθεύδειν δύναμαι, ὥσπερ οἶμαι οὐδ᾽ ὑμεῖς, οὔτε κατακεῖσθαι ἔτι, ὁρῶν ἐν οἵοις ἐσμέν.", "st": "3.1.15"}, {"sp": "N", "t": "οἱ μὲν γὰρ πολέμιοι δῆλον ὅτι οὐ πρότερον πρὸς ἡμᾶς τὸν πόλεμον ἐξέφηναν πρὶν ἐνόμισαν καλῶς τὰ ἑαυτῶν παρασκευάσασθαι, ἡμῶν δ᾽ οὐδεὶς οὐδὲν ἀντεπιμελεῖται ὅπως ὡς κάλλιστα ἀγωνιούμεθα.", "st": "3.1.16"}, {"sp": "N", "t": "καὶ μὴν εἰ ὑφησόμεθα καὶ ἐπὶ βασιλεῖ γενησόμεθα, τί οἰόμεθα πείσεσθαι; ὃς καὶ τοῦ ὁμομητρίου ἀδελφοῦ καὶ τεθνηκότος ἤδη ἀποτεμὼν τὴν κεφαλὴν καὶ τὴν χεῖρα ἀνεσταύρωσεν· ἡμᾶς δέ, οἷς κηδεμὼν μὲν οὐδεὶς πάρεστιν, ἐστρατεύσαμεν δὲ ἐπ᾽ αὐτὸν ὡς δοῦλον ἀντὶ βασιλέως ποιήσοντες καὶ ἀποκτενοῦντες εἰ δυναίμεθα, τί ἂν οἰόμεθα παθεῖν;", "st": "3.1.17"}, {"sp": "N", "t": "ἆρ᾽ οὐκ ἂν ἐπὶ πᾶν ἔλθοι ὡς ἡμᾶς τὰ ἔσχατα αἰκισάμενος πᾶσιν ἀνθρώποις φόβον παράσχοι τοῦ στρατεῦσαί ποτε ἐπ᾽ αὐτόν; ἀλλ᾽ ὅπως τοι μὴ ἐπ᾽ ἐκείνωι γενησόμεθα πάντα ποιητέον.", "st": "3.1.18"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν ἔστε μὲν αἱ σπονδαὶ ἦσαν οὔποτε ἐπαυόμην ἡμᾶς μὲν οἰκτίρων, βασιλέα δὲ καὶ τοὺς σὺν αὐτῶι μακαρίζων, διαθεώμενος αὐτῶν ὅσην μὲν χώραν καὶ οἵαν ἔχοιεν, ὡς δὲ ἄφθονα τὰ ἐπιτήδεια, ὅσους δὲ θεράποντας, ὅσα δὲ κτήνη, χρυσὸν δέ, ἐσθῆτα δέ·", "st": "3.1.19"}, {"sp": "N", "t": "τὰ δ᾽ αὖ τῶν στρατιωτῶν ὁπότε ἐνθυμοίμην, ὅτι τῶν μὲν ἀγαθῶν τούτων οὐδενὸς ἡμῖν μετείη, εἰ μὴ πριαίμεθα, ὅτου δ᾽ ὠνησόμεθα ἤιδειν ἔτι ὀλίγους ἔχοντας, ἄλλως δέ πως πορίζεσθαι τὰ ἐπιτήδεια ἢ ὠνουμένους ὅρκους ἤδη κατέχοντας ἡμᾶς· ταῦτ᾽ οὖν λογιζόμενος ἐνίοτε τὰς σπονδὰς μᾶλλον ἐφοβούμην ἢ νῦν τὸν πόλεμον.", "st": "3.1.20"}, {"sp": "N", "t": "ἐπεὶ μέντοι ἐκεῖνοι ἔλυσαν τὰς σπονδάς, λελύσθαι μοι δοκεῖ καὶ ἡ ἐκείνων ὕβρις καὶ ἡ ἡμετέρα ὑποψία. ἐν μέσωι γὰρ ἤδη κεῖται ταῦτα τὰ ἀγαθὰ ἆθλα ὁπότεροι ἂν ἡμῶν ἄνδρες ἀμείνονες ὦσιν, ἀγωνοθέται δ᾽ οἱ θεοί εἰσιν, οἳ σὺν ἡμῖν, ὡς τὸ εἰκός, ἔσονται.", "st": "3.1.21"}, {"sp": "N", "t": "οὗτοι μὲν γὰρ αὐτοὺς ἐπιωρκήκασιν· ἡμεῖς δὲ πολλὰ ὁρῶντες ἀγαθὰ στερρῶς αὐτῶν ἀπειχόμεθα διὰ τοὺς τῶν θεῶν ὅρκους· ὥστε ἐξεῖναί μοι δοκεῖ ἰέναι ἐπὶ τὸν ἀγῶνα πολὺ σὺν φρονήματι μείζονι ἢ τούτοις.", "st": "3.1.22"}, {"sp": "N", "t": "ἔτι δ᾽ ἔχομεν σώματα ἱκανώτερα τούτων καὶ ψύχη καὶ θάλπη καὶ πόνους φέρειν· ἔχομεν δὲ καὶ ψυχὰς σὺν τοῖς θεοῖς ἀμείνονας· οἱ δὲ ἄνδρες καὶ τρωτοὶ καὶ θνητοὶ μᾶλλον ἡμῶν, ἢν οἱ θεοὶ ὥσπερ τὸ πρόσθεν νίκην ἡμῖν διδῶσιν.", "st": "3.1.23"}, {"sp": "N", "t": "ἀλλ᾽ ἴσως γὰρ καὶ ἄλλοι ταὐτὰ ἐνθυμοῦνται, πρὸς τῶν θεῶν μὴ ἀναμένωμεν ἄλλους ἐφ᾽ ἡμᾶς ἐλθεῖν παρακαλοῦντας ἐπὶ τὰ κάλλιστα ἔργα, ἀλλ᾽ ἡμεῖς ἄρξωμεν τοῦ ἐξορμῆσαι καὶ τοὺς ἄλλους ἐπὶ τὴν ἀρετήν· φάνητε τῶν λοχαγῶν ἄριστοι καὶ τῶν στρατηγῶν ἀξιοστρατηγότεροι.", "st": "3.1.24"}, {"sp": "N", "t": "κἀγὼ δέ, εἰ μὲν ὑμεῖς ἐθέλετε ἐξορμᾶν ἐπὶ ταῦτα, ἕπεσθαι ὑμῖν βούλομαι, εἰ δ᾽ ὑμεῖς τάττετ᾽ ἐμὲ ἡγεῖσθαι, οὐδὲν προφασίζομαι τὴν ἡλικίαν, ἀλλὰ καὶ ἀκμάζειν ἡγοῦμαι ἐρύκειν ἀπ᾽ ἐμαυτοῦ τὰ κακά.»", "st": "3.1.25"}, {"sp": "N", "t": "ὁ μὲν ταῦτ᾽ ἔλεξεν, οἱ δὲ ἀρχηγοὶ ἀκούσαντες ἡγεῖσθαι ἐκέλευον πάντες, πλὴν Ἀπολλωνίδης τις ἦν βοιωτιάζων τῆι φωνῆι· οὗτος δ᾽ εἶπεν ὅτι φλυαροίη ὅστις λέγει ἄλλως πως σωτηρίας ἂν τυχεῖν ἢ βασιλέα πείσας, εἰ δύναιτο, καὶ ἅμα ἤρχετο λέγειν τὰς ἀπορίας. ὁ μέντοι Ξενοφῶν μεταξὺ ὑπολαβὼν ἔλεξεν ὧδε.", "st": "3.1.26"}, {"sp": "N", "t": "«ὦ θαυμασιώτατε ἄνθρωπε, σύγε οὐδὲ ὁρῶν γιγνώσκεις οὐδὲ ἀκούων μέμνησαι. ἐν ταὐτῶι γε μέντοι ἦσθα τούτοις ὅτε βασιλεύς, ἐπεὶ Κῦρος ἀπέθανε, μέγα φρονήσας ἐπὶ τούτωι πέμπων ἐκέλευε παραδιδόναι τὰ ὅπλα.", "st": "3.1.27"}, {"sp": "N", "t": "ἐπεὶ δὲ ἡμεῖς οὐ παραδόντες, ἀλλ᾽ ἐξοπλισάμενοι ἐλθόντες παρεσκηνήσαμεν αὐτῶι, τί οὐκ ἐποίησε πρέσβεις πέμπων καὶ σπονδὰς αἰτῶν καὶ παρέχων τὰ ἐπιτήδεια, ἔστε σπονδῶν ἔτυχεν;", "st": "3.1.28"}, {"sp": "N", "t": "ἐπεὶ δ᾽ αὖ οἱ στρατηγοὶ καὶ λοχαγοί, ὥσπερ δὴ σὺ κελεύεις, εἰς λόγους αὐτοῖς ἄνευ ὅπλων ἦλθον πιστεύσαντες ταῖς σπονδαῖς, οὐ νῦν ἐκεῖνοι παιόμενοι, κεντούμενοι, ὑβριζόμενοι οὐδὲ ἀποθανεῖν οἱ τλήμονες δύνανται, καὶ μάλ᾽ οἶμαι ἐρῶντες τούτου; ἃ σὺ πάντα εἰδὼς τοὺς μὲν ἀμύνασθαι κελεύοντας φλυαρεῖν φήις, πείθειν δὲ πάλιν κελεύεις ἰόντας;", "st": "3.1.29"}, {"sp": "N", "t": "ἐμοί, ὦ ἄνδρες, δοκεῖ τὸν ἄνθρωπον τοῦτον μήτε προσίεσθαι εἰς ταὐτὸ ἡμῖν αὐτοῖς ἀφελομένους τε τὴν λοχαγίαν σκεύη ἀναθέντας ὡς τοιούτωι χρῆσθαι. οὗτος γὰρ καὶ τὴν πατρίδα καταισχύνει καὶ πᾶσαν τὴν Ἑλλάδα, ὅτι Ἕλλην ὢν τοιοῦτός ἐστιν.»", "st": "3.1.30"}, {"sp": "N", "t": "ἐντεῦθεν ὑπολαβὼν Ἀγασίας Στυμφάλιος εἶπεν· «ἀλλὰ τούτωι γε οὔτε τῆς Βοιωτίας προσήκει οὐδὲν οὔτε τῆς Ἑλλάδος παντάπασιν, ἐπεὶ ἐγὼ αὐτὸν εἶδον ὥσπερ Λυδὸν ἀμφότερα τὰ ὦτα τετρυπημένον.»", "st": "3.1.31"}, {"sp": "N", "t": "καὶ εἶχεν οὕτως. τοῦτον μὲν οὖν ἀπήλασαν· οἱ δὲ ἄλλοι παρὰ τὰς τάξεις ἰόντες, ὅπου μὲν στρατηγὸς σῶιος εἴη, τὸν στρατηγὸν παρεκάλουν, ὁπόθεν δὲ οἴχοιτο, τὸν ὑποστράτηγον, ὅπου δ᾽ αὖ λοχαγὸς σῶιος εἴη, τὸν λοχαγόν.", "st": "3.1.32"}, {"sp": "N", "t": "ἐπεὶ δὲ πάντες συνῆλθον, εἰς τὸ πρόσθεν τῶν ὅπλων ἐκαθέζοντο· καὶ ἐγένοντο οἱ συνελθόντες στρατηγοὶ καὶ λοχαγοὶ ἀμφὶ τοὺς ἑκατόν. ὅτε δὲ ταῦτα ἦν σχεδὸν μέσαι ἦσαν νύκτες.", "st": "3.1.33"}, {"sp": "N", "t": "ἐνταῦθα Ἱερώνυμος Ἠλεῖος πρεσβύτατος ὢν τῶν Προξένου λοχαγῶν ἤρχετο λέγειν ὧδε. «ἡμῖν, ὦ ἄνδρες στρατηγοὶ καὶ λοχαγοί, ὁρῶσι τὰ παρόντα ἔδοξε καὶ αὐτοῖς συνελθεῖν καὶ ὑμᾶς παρακαλέσαι, ὅπως βουλευσαίμεθα εἴ τι δυναίμεθα ἀγαθόν. λέξον δ᾽, ἔφη, καὶ σύ, ὦ Ξενοφῶν, ἅπερ καὶ πρὸς ἡμᾶς.»", "st": "3.1.34"}, {"sp": "N", "t": "ἐκ τούτου λέγει τάδε Ξενοφῶν. «ἀλλὰ ταῦτα μὲν δὴ πάντες ἐπιστάμεθα, ὅτι βασιλεὺς καὶ Τισσαφέρνης οὓς μὲν ἐδυνήθησαν συνειλήφασιν ἡμῶν, τοῖς δ᾽ ἄλλοις δῆλον ὅτι ἐπιβουλεύουσιν, ὡς, ἢν δύνωνται, ἀπολέσωσιν. ἡμῖν δέ γε οἶμαι πάντα ποιητέα ὡς μήποτε ἐπὶ τοῖς βαρβάροις γενώμεθα, ἀλλὰ μᾶλλον ἐκεῖνοι ἐφ᾽ ἡμῖν.", "st": "3.1.35"}, {"sp": "N", "t": "εὖ τοίνυν ἐπίστασθε ὅτι ὑμεῖς τοσοῦτοι ὄντες ὅσοι νῦν συνεληλύθατε μέγιστον ἔχετε καιρόν. οἱ γὰρ στρατιῶται οὗτοι πάντες πρὸς ὑμᾶς βλέπουσι, κἂν μὲν ὑμᾶς ὁρῶσιν ἀθύμους, πάντες κακοὶ ἔσονται, ἢν δὲ ὑμεῖς αὐτοί τε παρασκευαζόμενοι φανεροὶ ἦτε ἐπὶ τοὺς πολεμίους καὶ τοὺς ἄλλους παρακαλῆτε, εὖ ἴστε ὅτι ἕψονται ὑμῖν καὶ πειράσονται μιμεῖσθαι.", "st": "3.1.36"}, {"sp": "N", "t": "ἴσως δέ τοι καὶ δίκαιόν ἐστιν ὑμᾶς διαφέρειν τι τούτων. ὑμεῖς γάρ ἐστε στρατηγοί, ὑμεῖς ταξίαρχοι καὶ λοχαγοί· καὶ ὅτε εἰρήνη ἦν, ὑμεῖς καὶ χρήμασι καὶ τιμαῖς τούτων ἐπλεονεκτεῖτε· καὶ νῦν τοίνυν ἐπεὶ πόλεμός ἐστιν, ἀξιοῦν δεῖ ὑμᾶς αὐτοὺς ἀμείνους τε τοῦ πλήθους εἶναι καὶ προβουλεύειν τούτων καὶ προπονεῖν, ἤν που δέηι.", "st": "3.1.37"}, {"sp": "N", "t": "καὶ νῦν πρῶτον μὲν οἴομαι ἂν ὑμᾶς μέγα ὠφελῆσαι τὸ στράτευμα, εἰ ἐπιμεληθείητε ὅπως ἀντὶ τῶν ἀπολωλότων ὡς τάχιστα στρατηγοὶ καὶ λοχαγοὶ ἀντικατασταθῶσιν. ἄνευ γὰρ ἀρχόντων οὐδὲν ἂν οὔτε καλὸν οὔτε ἀγαθὸν γένοιτο ὡς μὲν συνελόντι εἰπεῖν οὐδαμοῦ, ἐν δὲ δὴ τοῖς πολεμικοῖς παντάπασιν. ἡ μὲν γὰρ εὐταξία σώιζειν δοκεῖ, ἡ δὲ ἀταξία πολλοὺς ἤδη ἀπολώλεκεν.", "st": "3.1.38"}, {"sp": "N", "t": "ἐπειδὰν δὲ καταστήσησθε τοὺς ἄρχοντας ὅσους δεῖ, ἢν καὶ τοὺς ἄλλους στρατιώτας συλλέγητε καὶ παραθαρρύνητε, οἶμαι ἂν ὑμᾶς πάνυ ἐν καιρῶι ποιῆσαι.", "st": "3.1.39"}, {"sp": "N", "t": "νῦν γὰρ ἴσως καὶ ὑμεῖς αἰσθάνεσθε ὡς ἀθύμως μὲν ἦλθον ἐπὶ τὰ ὅπλα, ἀθύμως δὲ πρὸς τὰς φυλακάς· ὥστε οὕτω γ᾽ ἐχόντων οὐκ οἶδα ὅ τι ἄν τις χρήσαιτο αὐτοῖς, εἴτε νυκτὸς δέοι εἴτε καὶ ἡμέρας.", "st": "3.1.40"}, {"sp": "N", "t": "ἢν δέ τις αὐτῶν τρέψηι τὰς γνώμας, ὡς μὴ τοῦτο μόνον ἐννοῶνται, τί πείσονται, ἀλλὰ καὶ τί ποιήσουσι, πολὺ εὐθυμότεροι ἔσονται.", "st": "3.1.41"}, {"sp": "N", "t": "ἐπίστασθε γὰρ δὴ ὅτι οὔτε πλῆθός ἐστιν οὔτε ἰσχὺς ἡ ἐν τῶι πολέμωι τὰς νίκας ποιοῦσα, ἀλλ᾽ ὁπότεροι ἂν σὺν τοῖς θεοῖς ταῖς ψυχαῖς ἐρρωμενέστεροι ἴωσιν ἐπὶ τοὺς πολεμίους, τούτους ὡς ἐπὶ τὸ πολὺ οἱ ἀντίοι οὐ δέχονται.", "st": "3.1.42"}, {"sp": "N", "t": "ἐντεθύμημαι δ᾽ ἔγωγε, ὦ ἄνδρες, καὶ τοῦτο, ὅτι ὁπόσοι μὲν μαστεύουσι ζῆν ἐκ παντὸς τρόπου ἐν τοῖς πολεμικοῖς, οὗτοι μὲν κακῶς τε καὶ αἰσχρῶς ὡς ἐπὶ τὸ πολὺ ἀποθνήισκουσιν, ὁπόσοι δὲ τὸν μὲν θάνατον ἐγνώκασι πᾶσι κοινὸν εἶναι καὶ ἀναγκαῖον ἀνθρώποις, περὶ δὲ τοῦ καλῶς ἀποθνήισκειν ἀγωνίζονται, τούτους ὁρῶ μᾶλλόν πως εἰς τὸ γῆρας ἀφικνουμένους καὶ ἕως ἂν ζῶσιν εὐδαιμονέστερον διάγοντας.", "st": "3.1.43"}, {"sp": "N", "t": "ἃ καὶ ὑμᾶς δεῖ νῦν καταμαθόντας (ἐν τοιούτωι γὰρ καιρῶι ἐσμεν) αὐτούς τε ἄνδρας ἀγαθοὺς εἶναι καὶ τοὺς ἄλλους παρακαλεῖν.»", "st": "3.1.44"}, {"sp": "N", "t": "ὁ μὲν ταῦτα εἰπὼν ἐπαύσατο. μετὰ δὲ τοῦτον εἶπε Χειρίσοφος· «ἀλλὰ πρόσθεν μέν, ὦ Ξενοφῶν, τοσοῦτον μόνον σε ἐγίγνωσκον ὅσον ἤκουον Ἀθηναῖον εἶναι, νῦν δὲ καὶ ἐπαινῶ σε ἐφ᾽ οἷς λέγεις τε καὶ πράττεις καὶ βουλοίμην ἂν ὅτι πλείστους εἶναι τοιούτους· κοινὸν γὰρ ἂν εἴη τὸ ἀγαθόν.", "st": "3.1.45"}, {"sp": "N", "t": "καὶ νῦν, ἔφη, μὴ μέλλωμεν, ὦ ἄνδρες, ἀλλ᾽ ἀπελθόντες ἤδη αἱρεῖσθε οἱ δεόμενοι ἄρχοντας, καὶ ἑλόμενοι ἥκετε εἰς τὸ μέσον τοῦ στρατοπέδου καὶ τοὺς αἱρεθέντας ἄγετε· ἔπειτ᾽ ἐκεῖ συγκαλοῦμεν τοὺς ἄλλους στρατιώτας. παρέστω δ᾽ ἡμῖν, ἔφη, καὶ Τολμίδης ὁ κῆρυξ.»", "st": "3.1.46"}, {"sp": "N", "t": "καὶ ἅμα ταῦτ᾽ εἰπὼν ἀνέστη, ὡς μὴ μέλλοιτο ἀλλὰ περαίνοιτο τὰ δέοντα. ἐκ τούτου ἡιρέθησαν ἄρχοντες ἀντὶ μὲν Κλεάρχου Τιμασίων Δαρδανεύς, ἀντὶ δὲ Σωκράτους Ξανθικλῆς Ἀχαιός, ἀντὶ δὲ Ἀγίου Κλεάνωρ Ἀρκάς, ἀντὶ δὲ Μένωνος Φιλήσιος Ἀχαιός, ἀντὶ δὲ Προξένου Ξενοφῶν Ἀθηναῖος.", "st": "3.1.47"}, {"sp": "N", "t": "ἐπεὶ δὲ ἥιρηντο, ἡμέρα τε σχεδὸν ὑπέφαινε καὶ εἰς τὸ μέσον ἧκον οἱ ἄρχοντες, καὶ ἔδοξεν αὐτοῖς προφυλακὰς καταστήσαντας συγκαλεῖν τοὺς στρατιώτας. ἐπεὶ δὲ καὶ οἱ ἄλλοι στρατιῶται συνῆλθον, ἀνέστη πρῶτος μὲν Χειρίσοφος ὁ Λακεδαιμόνιος καὶ ἔλεξεν ὧδε.", "st": "3.2.1"}, {"sp": "N", "t": "«ἄνδρες στρατιῶται, χαλεπὰ μὲν τὰ παρόντα, ὁπότε ἀνδρῶν στρατηγῶν τοιούτων στερόμεθα καὶ λοχαγῶν καὶ στρατιωτῶν, πρὸς δ᾽ ἔτι καὶ οἱ ἀμφὶ Ἀριαῖον οἱ πρόσθεν σύμμαχοι ὄντες προδεδώκασιν ἡμᾶς·", "st": "3.2.2"}, {"sp": "N", "t": "ὅμως δὲ δεῖ ἐκ τῶν παρόντων ἄνδρας ἀγαθοὺς τελέθειν καὶ μὴ ὑφίεσθαι, ἀλλὰ πειρᾶσθαι ὅπως, ἢν μὲν δυνώμεθα, καλῶς νικῶντες σωιζώμεθα· εἰ δὲ μή, ἀλλὰ καλῶς γε ἀποθνήισκωμεν, ὑποχείριοι δὲ μηδέποτε γενώμεθα ζῶντες τοῖς πολεμίοις. οἴομαι γὰρ ἂν ἡμᾶς τοιαῦτα παθεῖν οἷα τοὺς ἐχθροὺς οἱ θεοὶ ποιήσειαν.»", "st": "3.2.3"}, {"sp": "N", "t": "ἐπὶ τούτωι Κλεάνωρ ὁ Ὀρχομένιος ἀνέστη καὶ ἔλεξεν ὧδε. «ἀλλ᾽ ὁρᾶτε μέν, ὦ ἄνδρες, τὴν βασιλέως ἐπιορκίαν καὶ ἀσέβειαν, ὁρᾶτε δὲ τὴν Τισσαφέρνους ἀπιστίαν, ὅστις λέγων ὡς γείτων τε εἴη τῆς Ἑλλάδος καὶ περὶ πλείστου ἂν ποιήσαιτο σῶσαι ἡμᾶς, καὶ ἐπὶ τούτοις αὐτὸς ὀμόσας ἡμῖν, αὐτὸς δεξιὰς δούς, αὐτὸς ἐξαπατήσας συνέλαβε τοὺς στρατηγούς, καὶ οὐδὲ Δία ξένιον ἠιδέσθη, ἀλλὰ Κλεάρχωι καὶ ὁμοτράπεζος γενόμενος αὐτοῖς τούτοις ἐξαπατήσας τοὺς ἄνδρας ἀπολώλεκεν.", "st": "3.2.4"}, {"sp": "N", "t": "Ἀριαῖος δέ, ὃν ἡμεῖς ἠθέλομεν βασιλέα καθιστάναι, καὶ ἐδώκαμεν καὶ ἐλάβομεν πιστὰ μὴ προδώσειν ἀλλήλους, καὶ οὗτος οὔτε τοὺς θεοὺς δείσας οὔτε Κῦρον τεθνηκότα αἰδεσθείς, τιμώμενος μάλιστα ὑπὸ Κύρου ζῶντος νῦν πρὸς τοὺς ἐκείνου ἐχθίστους ἀποστὰς ἡμᾶς τοὺς Κύρου φίλους κακῶς ποιεῖν πειρᾶται.", "st": "3.2.5"}, {"sp": "N", "t": "ἀλλὰ τούτους μὲν οἱ θεοὶ ἀποτείσαιντο· ἡμᾶς δὲ δεῖ ταῦτα ὁρῶντας μήποτε ἐξαπατηθῆναι ἔτι ὑπὸ τούτων, ἀλλὰ μαχομένους ὡς ἂν δυνώμεθα κράτιστα τοῦτο ὅ τι ἂν δοκῆι τοῖς θεοῖς πάσχειν.»", "st": "3.2.6"}, {"sp": "N", "t": "ἐκ τούτου Ξενοφῶν ἀνίσταται ἐσταλμένος ἐπὶ πόλεμον ὡς ἐδύνατο κάλλιστα, νομίζων, εἴτε νίκην διδοῖεν οἱ θεοί, τὸν κάλλιστον κόσμον τῶι νικᾶν πρέπειν, εἴτε τελευτᾶν δέοι, ὀρθῶς ἔχειν τῶν καλλίστων ἑαυτὸν ἀξιώσαντα ἐν τούτοις τῆς τελευτῆς τυγχάνειν· τοῦ λόγου δὲ ἤρχετο ὧδε.", "st": "3.2.7"}, {"sp": "N", "t": "«τὴν μὲν τῶν βαρβάρων ἐπιορκίαν τε καὶ ἀπιστίαν λέγει μὲν Κλεάνωρ, ἐπίστασθε δὲ καὶ ὑμεῖς οἶμαι. εἰ μὲν οὖν βουλόμεθα πάλιν αὐτοῖς διὰ φιλίας ἰέναι, ἀνάγκη ἡμᾶς πολλὴν ἀθυμίαν ἔχειν, ὁρῶντας καὶ τοὺς στρατηγούς, οἳ διὰ πίστεως αὐτοῖς ἑαυτοὺς ἐνεχείρισαν, οἷα πεπόνθασιν· εἰ μέντοι διανοούμεθα σὺν τοῖς ὅπλοις ὧν τε πεποιήκασι δίκην ἐπιθεῖναι αὐτοῖς καὶ τὸ λοιπὸν διὰ παντὸς πολέμου αὐτοῖς ἰέναι, σὺν τοῖς θεοῖς πολλαὶ ἡμῖν καὶ καλαὶ ἐλπίδες εἰσὶ σωτηρίας.»", "st": "3.2.8"}, {"sp": "N", "t": "τοῦτο δὲ λέγοντος αὐτοῦ πτάρνυταί τις· ἀκούσαντες δ᾽ οἱ στρατιῶται πάντες μιᾶι ὁρμῆι προσεκύνησαν τὸν θεόν, καὶ ὁ Ξενοφῶν εἶπε· «δοκεῖ μοι, ὦ ἄνδρες, ἐπεὶ περὶ σωτηρίας ἡμῶν λεγόντων οἰωνὸς τοῦ Διὸς τοῦ σωτῆρος ἐφάνη, εὔξασθαι τῶι θεῶι τούτωι θύσειν σωτήρια ὅπου ἂν πρῶτον εἰς φιλίαν χώραν ἀφικώμεθα, συνεπεύξασθαι δὲ καὶ τοῖς ἄλλοις θεοῖς θύσειν κατὰ δύναμιν. καὶ ὅτωι δοκεῖ ταῦτ᾽, ἔφη, ἀνατεινάτω τὴν χεῖρα.» καὶ ἀνέτειναν ἅπαντες. ἐκ τούτου ηὔξαντο καὶ ἐπαιάνισαν. ἐπεὶ δὲ τὰ τῶν θεῶν καλῶς εἶχεν, ἤρχετο πάλιν ὧδε.", "st": "3.2.9"}, {"sp": "N", "t": "«ἐτύγχανον λέγων ὅτι πολλαὶ καὶ καλαὶ ἐλπίδες ἡμῖν εἶεν σωτηρίας. πρῶτον μὲν γὰρ ἡμεῖς μὲν ἐμπεδοῦμεν τοὺς τῶν θεῶν ὅρκους, οἱ δὲ πολέμιοι ἐπιωρκήκασί τε καὶ τὰς σπονδὰς παρὰ τοὺς ὅρκους λελύκασιν. οὕτω δ᾽ ἐχόντων εἰκὸς τοῖς μὲν πολεμίοις ἐναντίους εἶναι τοὺς θεούς, ἡμῖν δὲ συμμάχους, οἵπερ ἱκανοί εἰσι καὶ τοὺς μεγάλους ταχὺ μικροὺς ποιεῖν καὶ τοὺς μικροὺς κἂν ἐν δεινοῖς ὦσι σώιζειν εὐπετῶς, ὅταν βούλωνται.", "st": "3.2.10"}, {"sp": "N", "t": "ἔπειτα δὲ ἀναμνήσω γὰρ ὑμᾶς καὶ τοὺς τῶν προγόνων τῶν ἡμετέρων κινδύνους, ἵνα εἰδῆτε ὡς ἀγαθοῖς τε ὑμῖν προσήκει εἶναι σώιζονταί τε σὺν τοῖς θεοῖς καὶ ἐκ πάνυ δεινῶν οἱ ἀγαθοί. ἐλθόντων μὲν γὰρ Περσῶν καὶ τῶν σὺν αὐτοῖς παμπληθεῖ στόλωι ὡς ἀφανιούντων τὰς Ἀθήνας, ὑποστῆναι αὐτοὶ Ἀθηναῖοι τολμήσαντες ἐνίκησαν αὐτούς.", "st": "3.2.11"}, {"sp": "N", "t": "καὶ εὐξάμενοι τῆι Ἀρτέμιδι ὁπόσους κατακάνοιεν τῶν πολεμίων τοσαύτας χιμαίρας καταθύσειν τῆι θεῶι, ἐπεὶ οὐκ εἶχον ἱκανὰς εὑρεῖν, ἔδοξεν αὐτοῖς κατ᾽ ἐνιαυτὸν πεντακοσίας θύειν, καὶ ἔτι νῦν ἀποθύουσιν.", "st": "3.2.12"}, {"sp": "N", "t": "ἔπειτα ὅτε Ξέρξης ὕστερον ἀγείρας τὴν ἀναρίθμητον στρατιὰν ἦλθεν ἐπὶ τὴν Ἑλλάδα, καὶ τότε ἐνίκων οἱ ἡμέτεροι πρόγονοι τοὺς τούτων προγόνους καὶ κατὰ γῆν καὶ κατὰ θάλατταν. ὧν ἔστι μὲν τεκμήρια ὁρᾶν τὰ τρόπαια, μέγιστον δὲ μαρτύριον ἡ ἐλευθερία τῶν πόλεων ἐν αἷς ὑμεῖς ἐγένεσθε καὶ ἐτράφητε· οὐδένα γὰρ ἄνθρωπον δεσπότην ἀλλὰ τοὺς θεοὺς προσκυνεῖτε.", "st": "3.2.13"}, {"sp": "N", "t": "τοιούτων μέν ἐστε προγόνων. οὐ μὲν δὴ τοῦτό γε ἐρῶ ὡς ὑμεῖς καταισχύνετε αὐτούς· ἀλλ᾽ οὐ πολλαὶ ἡμέραι ἀφ᾽ οὗ ἀντιταξάμενοι τούτοις τοῖς ἐκείνων ἐκγόνοις πολλαπλασίους ὑμῶν αὐτῶν ἐνικᾶτε σὺν τοῖς θεοῖς.", "st": "3.2.14"}, {"sp": "N", "t": "καὶ τότε μὲν δὴ περὶ τῆς Κύρου βασιλείας ἄνδρες ἦτε ἀγαθοί· νῦν δ᾽ ὁπότε περὶ τῆς ὑμετέρας σωτηρίας ὁ ἀγών ἐστι, πολὺ δήπου ὑμᾶς προσήκει καὶ ἀμείνονας καὶ προθυμοτέρους εἶναι.", "st": "3.2.15"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ θαρραλεωτέρους νῦν πρέπει εἶναι πρὸς τοὺς πολεμίους. τότε μὲν γὰρ ἄπειροι ὄντες αὐτῶν τὸ δὲ πλῆθος ἄμετρον ὁρῶντες, ὅμως ἐτολμήσατε σὺν τῶι πατρώιωι φρονήματι ἰέναι εἰς αὐτούς· νῦν δὲ ὁπότε καὶ πεῖραν ἤδη ἔχετε αὐτῶν ὅτι οὐ θέλουσι καὶ πολλαπλάσιοι ὄντες [μὴ] δέχεσθαι ὑμᾶς, τί ἔτι ὑμῖν προσήκει τούτους φοβεῖσθαι;", "st": "3.2.16"}, {"sp": "N", "t": "μηδὲ μέντοι τοῦτο μεῖον δόξητε ἔχειν ὅτι οἱ Κύρειοι πρόσθεν σὺν ἡμῖν ταττόμενοι νῦν ἀφεστήκασιν. ἔτι γὰρ οὗτοι κακίονές εἰσι τῶν ὑφ᾽ ἡμῶν ἡττημένων· ἔφυγον γοῦν πρὸς ἐκείνους καταλιπόντες ἡμᾶς. τοὺς δ᾽ ἐθέλοντας φυγῆς ἄρχειν πολὺ κρεῖττον σὺν τοῖς πολεμίοις ταττομένους ἢ ἐν τῆι ἡμετέραι τάξει ὁρᾶν.", "st": "3.2.17"}, {"sp": "N", "t": "εἰ δέ τις ὑμῶν ἀθυμεῖ ὅτι ἡμῖν μὲν οὐκ εἰσὶν ἱππεῖς, τοῖς δὲ πολεμίοις πολλοὶ πάρεισιν, ἐνθυμήθητε ὅτι οἱ μύριοι ἱππεῖς οὐδὲν ἄλλο ἢ μύριοί εἰσιν ἄνθρωποι· ὑπὸ μὲν γὰρ ἵππου ἐν μάχηι οὐδεὶς πώποτε οὔτε δηχθεὶς οὔτε λακτισθεὶς ἀπέθανεν, οἱ δὲ ἄνδρες εἰσὶν οἱ ποιοῦντες ὅ τι ἂν ἐν ταῖς μάχαις γίγνηται.", "st": "3.2.18"}, {"sp": "N", "t": "οὐκοῦν τῶν ἱππέων πολὺ ἡμεῖς ἐπ᾽ ἀσφαλεστέρου ὀχήματός ἐσμεν· οἱ μὲν γὰρ ἐφ᾽ ἵππων κρέμανται φοβούμενοι οὐχ ἡμᾶς μόνον ἀλλὰ καὶ τὸ καταπεσεῖν· ἡμεῖς δ᾽ ἐπὶ γῆς βεβηκότες πολὺ μὲν ἰσχυρότερον παίσομεν, ἤν τις προσίηι, πολὺ δὲ μᾶλλον ὅτου ἂν βουλώμεθα τευξόμεθα. ἑνὶ δὲ μόνωι προέχουσιν οἱ ἱππεῖς [ἡμᾶς]· φεύγειν αὐτοῖς ἀσφαλέστερόν ἐστιν ἢ ἡμῖν.", "st": "3.2.19"}, {"sp": "N", "t": "εἰ δὲ δὴ τὰς μὲν μάχας θαρρεῖτε, ὅτι δὲ οὐκέτι ὑμῖν Τισσαφέρνης ἡγήσεται οὐδὲ βασιλεὺς ἀγορὰν παρέξει, τοῦτο ἄχθεσθε, σκέψασθε πότερον κρεῖττον Τισσαφέρνην ἡγεμόνα ἔχειν, ὃς ἐπιβουλεύων ἡμῖν φανερός ἐστιν, ἢ οὓς ἂν ἡμεῖς ἄνδρας λαβόντες ἡγεῖσθαι κελεύωμεν, οἳ εἴσονται ὅτι, ἤν τι περὶ ἡμᾶς ἁμαρτάνωσι, περὶ τὰς ἑαυτῶν ψυχὰς καὶ σώματα ἁμαρτήσονται.", "st": "3.2.20"}, {"sp": "N", "t": "τὰ δὲ ἐπιτήδεια πότερον ὠνεῖσθαι κρεῖττον ἐκ τῆς ἀγορᾶς ἧς οὗτοι παρεῖχον μικρὰ μέτρα πολλοῦ ἀργυρίου, μηδὲ τοῦτο ἔτι ἔχοντας, ἢ αὐτοὺς λαμβάνειν ἤνπερ κρατῶμεν, μέτρωι χρωμένους ὁπόσωι ἂν ἕκαστος βούληται.", "st": "3.2.21"}, {"sp": "N", "t": "εἰ δὲ ταῦτα μὲν γιγνώσκετε ὅτι κρείττονα, τοὺς δὲ ποταμοὺς ἄπορον νομίζετε εἶναι καὶ μεγάλως ἡγεῖσθε ἐξαπατηθῆναι διαβάντες, σκέψασθε εἰ ἄρα τοῦτο καὶ μωρότατον πεποιήκασιν οἱ βάρβαροι. πάντες γὰρ ποταμοί, ἢν καὶ πρόσω τῶν πηγῶν ἄποροι ὦσι, προσιοῦσι πρὸς τὰς πηγὰς διαβατοὶ γίγνονται οὐδὲ τὸ γόνυ βρέχοντες.", "st": "3.2.22"}, {"sp": "N", "t": "εἰ δὲ μήθ᾽ οἱ ποταμοὶ διήσουσιν ἡγεμών τε μηδεὶς ἡμῖν φανεῖται, οὐδ᾽ ὣς ἡμῖν γε ἀθυμητέον. ἐπιστάμεθα γὰρ Μυσούς, οὓς οὐκ ἂν ἡμῶν φαίημεν βελτίους εἶναι, ὅτι βασιλέως ἄκοντος ἐν βασιλέως χώραι πολλάς τε καὶ εὐδαίμονας καὶ μεγάλας πόλεις οἰκοῦσιν, ἐπιστάμεθα δὲ Πισίδας ὡσαύτως, Λυκάονας δὲ καὶ αὐτοὶ εἴδομεν ὅτι ἐν τοῖς πεδίοις τὰ ἐρυμνὰ καταλαβόντες τὴν τούτων χώραν καρποῦνται·", "st": "3.2.23"}, {"sp": "N", "t": "καὶ ἡμᾶς δ᾽ ἂν ἔφην ἔγωγε χρῆναι μήπω φανεροὺς εἶναι οἴκαδε ὡρμημένους, ἀλλὰ κατασκευάζεσθαι ὡς αὐτοῦ οἰκήσοντας. οἶδα γὰρ ὅτι καὶ Μυσοῖς βασιλεὺς πολλοὺς μὲν ἡγεμόνας ἂν δοίη, πολλοὺς δ᾽ ἂν ὁμήρους τοῦ ἀδόλως ἐκπέμψειν, καὶ ὁδοποιήσειέ γ᾽ ἂν αὐτοῖς καὶ εἰ σὺν τεθρίπποις βούλοιντο ἀπιέναι. καὶ ἡμῖν γ᾽ ἂν οἶδ᾽ ὅτι τρισάσμενος ταῦτ᾽ ἐποίει, εἰ ἑώρα ἡμᾶς μένειν κατασκευαζομένους.", "st": "3.2.24"}, {"sp": "N", "t": "ἀλλὰ γὰρ δέδοικα μή, ἂν ἅπαξ μάθωμεν ἀργοὶ ζῆν καὶ ἐν ἀφθόνοις βιοτεύειν, καὶ Μήδων δὲ καὶ Περσῶν καλαῖς καὶ μεγάλαις γυναιξὶ καὶ παρθένοις ὁμιλεῖν, μὴ ὥσπερ οἱ λωτοφάγοι ἐπιλαθώμεθα τῆς οἴκαδε ὁδοῦ.", "st": "3.2.25"}, {"sp": "N", "t": "δοκεῖ οὖν μοι εἰκὸς καὶ δίκαιον εἶναι πρῶτον εἰς τὴν Ἑλλάδα καὶ πρὸς τοὺς οἰκείους πειρᾶσθαι ἀφικνεῖσθαι καὶ ἐπιδεῖξαι τοῖς Ἕλλησιν ὅτι ἑκόντες πένονται, ἐξὸν αὐτοῖς τοὺς νῦν [οἴκοι] σκληρῶς ἐκεῖ πολιτεύοντας ἐνθάδε κομισαμένους πλουσίους ὁρᾶν. ἀλλὰ γάρ, ὦ ἄνδρες, πάντα ταῦτα τἀγαθὰ δῆλον ὅτι τῶν κρατούντων ἐστί·", "st": "3.2.26"}, {"sp": "N", "t": "τοῦτο δὴ δεῖ λέγειν, ὅπως ἂν πορευοίμεθά τε ὡς ἀσφαλέστατα καὶ εἰ μάχεσθαι δέοι ὡς κράτιστα μαχοίμεθα. πρῶτον μὲν τοίνυν, ἔφη, δοκεῖ μοι κατακαῦσαι τὰς ἁμάξας ἃς ἔχομεν, ἵνα μὴ τὰ ζεύγη ἡμῶν στρατηγῆι, ἀλλὰ πορευώμεθα ὅπηι ἂν τῆι στρατιᾶι συμφέρηι· ἔπειτα καὶ τὰς σκηνὰς συγκατακαῦσαι. αὗται γὰρ αὖ ὄχλον μὲν παρέχουσιν ἄγειν, συνωφελοῦσι δ᾽ οὐδὲν οὔτε εἰς τὸ μάχεσθαι οὔτ᾽ εἰς τὸ τὰ ἐπιτήδεια ἔχειν.", "st": "3.2.27"}, {"sp": "N", "t": "ἔτι δὲ καὶ τῶν ἄλλων σκευῶν τὰ περιττὰ ἀπαλλάξωμεν πλὴν ὅσα πολέμου ἕνεκεν ἢ σίτων ἢ ποτῶν ἔχομεν, ἵνα ὡς πλεῖστοι μὲν ἡμῶν ἐν τοῖς ὅπλοις ὦσιν, ὡς ἐλάχιστοι δὲ σκευοφορῶσι. κρατουμένων μὲν γὰρ ἐπίστασθε ὅτι πάντα ἀλλότρια· ἢν δὲ κρατῶμεν, καὶ τοὺς πολεμίους δεῖ σκευοφόρους ἡμετέρους νομίζειν.", "st": "3.2.28"}, {"sp": "N", "t": "λοιπόν μοι εἰπεῖν ὅπερ καὶ μέγιστον νομίζω εἶναι. ὁρᾶτε γὰρ καὶ τοὺς πολεμίους ὅτι οὐ πρόσθεν ἐξενεγκεῖν ἐτόλμησαν πρὸς ἡμᾶς πόλεμον πρὶν τοὺς στρατηγοὺς ἡμῶν συνέλαβον, νομίζοντες ὄντων μὲν τῶν ἀρχόντων καὶ ἡμῶν πειθομένων ἱκανοὺς εἶναι ἡμᾶς περιγενέσθαι τῶι πολέμωι, λαβόντες δὲ τοὺς ἄρχοντας ἀναρχίαι ἂν καὶ ἀταξίαι ἐνόμιζον ἡμᾶς ἀπολέσθαι.", "st": "3.2.29"}, {"sp": "N", "t": "δεῖ οὖν πολὺ μὲν τοὺς ἄρχοντας ἐπιμελεστέρους γενέσθαι τοὺς νῦν τῶν πρόσθεν, πολὺ δὲ τοὺς ἀρχομένους εὐτακτοτέρους καὶ πειθομένους μᾶλλον τοῖς ἄρχουσι νῦν ἢ πρόσθεν·", "st": "3.2.30"}, {"sp": "N", "t": "ἢν δέ τις ἀπειθῆι, [ἢν] ψηφίσασθαι τὸν ἀεὶ ὑμῶν ἐντυγχάνοντα σὺν τῶι ἄρχοντι κολάζειν· οὕτως οἱ πολέμιοι πλεῖστον ἐψευσμένοι ἔσονται· τῆιδε γὰρ τῆι ἡμέραι μυρίους ὄψονται ἀνθ᾽ ἑνὸς Κλεάρχους τοὺς οὐδενὶ ἐπιτρέψοντας κακῶι εἶναι.", "st": "3.2.31"}, {"sp": "N", "t": "ἀλλὰ γὰρ καὶ περαίνειν ἤδη ὥρα· ἴσως γὰρ οἱ πολέμιοι αὐτίκα παρέσονται. ὅτωι οὖν ταῦτα δοκεῖ καλῶς ἔχειν, ἐπικυρωσάτω ὡς τάχιστα, ἵνα ἔργωι περαίνηται. εἰ δέ τι ἄλλο βέλτιον ἢ ταύτηι, τολμάτω καὶ ὁ ἰδιώτης διδάσκειν· πάντες γὰρ κοινῆς σωτηρίας δεόμεθα.»", "st": "3.2.32"}, {"sp": "N", "t": "μετὰ ταῦτα Χειρίσοφος εἶπεν· «ἀλλ᾽ εἰ μέν τινος ἄλλου δεῖ πρὸς τούτοις οἷς λέγει Ξενοφῶν, καὶ αὐτίκα ἐξέσται ποιεῖν· ἃ δὲ νῦν εἴρηκε δοκεῖ μοι ὡς τάχιστα ψηφίσασθαι ἄριστον εἶναι· καὶ ὅτωι δοκεῖ ταῦτα, ἀνατεινάτω τὴν χεῖρα.»", "st": "3.2.33"}, {"sp": "N", "t": "ἀνέτειναν πάντες. ἀναστὰς δὲ πάλιν εἶπε Ξενοφῶν· «ὦ ἄνδρες, ἀκούσατε ὧν προσδοκεῖ μοι. δῆλον ὅτι πορεύεσθαι ἡμᾶς δεῖ ὅπου ἕξομεν τὰ ἐπιτήδεια· ἀκούω δὲ κώμας εἶναι καλὰς οὐ πλέον εἴκοσι σταδίων ἀπεχούσας·", "st": "3.2.34"}, {"sp": "N", "t": "οὐκ ἂν οὖν θαυμάζοιμεν εἰ οἱ πολέμιοι, ὥσπερ οἱ δειλοὶ κύνες τοὺς μὲν παριόντας διώκουσί τε καὶ δάκνουσιν, ἢν δύνωνται, τοὺς δὲ διώκοντας φεύγουσιν, εἰ καὶ αὐτοὶ ἡμῖν ἀπιοῦσιν ἐπακολουθοῖεν.", "st": "3.2.35"}, {"sp": "N", "t": "ἴσως οὖν ἀσφαλέστερον ἡμῖν πορεύεσθαι πλαίσιον ποιησαμένους τῶν ὅπλων, ἵνα τὰ σκευοφόρα καὶ ὁ πολὺς ὄχλος ἐν ἀσφαλεστέρωι εἴη. εἰ οὖν νῦν ἀποδειχθείη τίνας χρὴ ἡγεῖσθαι τοῦ πλαισίου καὶ τὰ πρόσθεν κοσμεῖν καὶ τίνας ἐπὶ τῶν πλευρῶν ἑκατέρων εἶναι, τίνας δ᾽ ὀπισθοφυλακεῖν, οὐκ ἂν ὁπότε οἱ πολέμιοι ἔλθοιεν βουλεύεσθαι ἡμᾶς δέοι, ἀλλὰ χρώιμεθα ἂν εὐθὺς τοῖς τεταγμένοις.", "st": "3.2.36"}, {"sp": "N", "t": "εἰ μὲν οὖν ἄλλο τις βέλτιον ὁρᾶι, ἄλλως ἐχέτω· εἰ δὲ μή, Χειρίσοφος μὲν ἡγοῖτο, ἐπειδὴ καὶ Λακεδαιμόνιός ἐστι· τῶν δὲ πλευρῶν ἑκατέρων δύο τὼ πρεσβυτάτω στρατηγὼ ἐπιμελοίσθην· ὀπισθοφυλακοῖμεν δ᾽ ἡμεῖς οἱ νεώτατοι ἐγὼ καὶ Τιμασίων τὸ νῦν εἶναι.", "st": "3.2.37"}, {"sp": "N", "t": "τὸ δὲ λοιπὸν πειρώμενοι ταύτης τῆς τάξεως βουλευσόμεθα ὅ τι ἂν ἀεὶ κράτιστον δοκῆι εἶναι. εἰ δέ τις ἄλλο ὁρᾶι βέλτιον, λεξάτω.» ἐπεὶ δ᾽ οὐδεὶς ἀντέλεγεν, εἶπεν· «ὅτωι δοκεῖ ταῦτα, ἀνατεινάτω τὴν χεῖρα. ἔδοξε ταῦτα.", "st": "3.2.38"}, {"sp": "N", "t": "«νῦν τοίνυν, ἔφη, ἀπιόντας ποιεῖν δεῖ τὰ δεδογμένα. καὶ ὅστις τε ὑμῶν τοὺς οἰκείους ἐπιθυμεῖ ἰδεῖν, μεμνήσθω ἀνὴρ ἀγαθὸς εἶναι· οὐ γὰρ ἔστιν ἄλλως τούτου τυχεῖν· ὅστις τε ζῆν ἐπιθυμεῖ, πειράσθω νικᾶν· τῶν μὲν γὰρ νικώντων τὸ καίνειν, τῶν δὲ ἡττωμένων τὸ ἀποθνήισκειν ἐστί· καὶ εἴ τις δὲ χρημάτων ἐπιθυμεῖ, κρατεῖν πειράσθω· τῶν γὰρ νικώντων ἐστὶ καὶ τὰ ἑαυτῶν σώιζειν καὶ τὰ τῶν ἡττωμένων λαμβάνειν.»", "st": "3.2.39"}, {"sp": "N", "t": "τούτων λεχθέντων ἀνέστησαν καὶ ἀπελθόντες κατέκαιον τὰς ἁμάξας καὶ τὰς σκηνάς, τῶν δὲ περιττῶν ὅτου μὲν δέοιτό τις μετεδίδοσαν ἀλλήλοις, τὰ δὲ ἄλλα εἰς τὸ πῦρ ἐρρίπτουν. ταῦτα ποιήσαντες ἠριστοποιοῦντο. ἀριστοποιουμένων δὲ αὐτῶν ἔρχεται Μιθραδάτης σὺν ἱππεῦσιν ὡς τριάκοντα, καὶ καλεσάμενος τοὺς στρατηγοὺς εἰς ἐπήκοον λέγει ὧδε.", "st": "3.3.1"}, {"sp": "N", "t": "«ἐγώ, ὦ ἄνδρες Ἕλληνες, καὶ Κύρωι πιστὸς ἦν, ὡς ὑμεῖς ἐπίστασθε, καὶ νῦν ὑμῖν εὔνους· καὶ ἐνθάδε δ᾽ εἰμὶ σὺν πολλῶι φόβωι διάγων. εἰ οὖν ὁρώιην ὑμᾶς σωτήριόν τι βουλευομένους, ἔλθοιμι ἂν πρὸς ὑμᾶς καὶ τοὺς θεράποντας πάντας ἔχων. λέξατε οὖν πρός με τί ἐν νῶι ἔχετε ὡς φίλον τε καὶ εὔνουν καὶ βουλόμενον κοινῆι σὺν ὑμῖν τὸν στόλον ποιεῖσθαι.»", "st": "3.3.2"}, {"sp": "N", "t": "βουλευομένοις τοῖς στρατηγοῖς ἔδοξεν ἀποκρίνασθαι τάδε· καὶ ἔλεγε Χειρίσοφος· «ἡμῖν δοκεῖ, εἰ μέν τις ἐᾶι ἡμᾶς ἀπιέναι οἴκαδε, διαπορεύεσθαι τὴν χώραν ὡς ἂν δυνώμεθα ἀσινέστατα· ἢν δέ τις ἡμᾶς τῆς ὁδοῦ ἀποκωλύηι, διαπολεμεῖν τούτωι ὡς ἂν δυνώμεθα κράτιστα.»", "st": "3.3.3"}, {"sp": "N", "t": "ἐκ τούτου ἐπειρᾶτο Μιθραδάτης διδάσκειν ὡς ἄπορον εἴη βασιλέως ἄκοντος σωθῆναι. ἔνθα δὴ ἐγιγνώσκετο ὅτι ὑπόπεμπτος εἴη· καὶ γὰρ τῶν Τισσαφέρνους τις οἰκείων παρηκολουθήκει πίστεως ἕνεκα.", "st": "3.3.4"}, {"sp": "N", "t": "καὶ ἐκ τούτου ἐδόκει τοῖς στρατηγοῖς βέλτιον εἶναι δόγμα ποιήσασθαι τὸν πόλεμον ἀκήρυκτον εἶναι ἔστ᾽ ἐν τῆι πολεμίαι εἶεν· διέφθειρον γὰρ προσιόντες τοὺς στρατιώτας, καὶ ἕνα γε λοχαγὸν διέφθειραν Νίκαρχον Ἀρκάδα, καὶ ὤιχετο ἀπιὼν νυκτὸς σὺν ἀνθρώποις ὡς εἴκοσι.", "st": "3.3.5"}, {"sp": "N", "t": "μετὰ ταῦτα ἀριστήσαντες καὶ διαβάντες τὸν Ζαπάταν ποταμὸν ἐπορεύοντο τεταγμένοι τὰ ὑποζύγια καὶ τὸν ὄχλον ἐν μέσωι ἔχοντες. οὐ πολὺ δὲ προεληλυθότων αὐτῶν ἐπιφαίνεται πάλιν ὁ Μιθραδάτης, ἱππέας ἔχων ὡς διακοσίους καὶ τοξότας καὶ σφενδονήτας εἰς τετρακοσίους μάλα ἐλαφροὺς καὶ εὐζώνους.", "st": "3.3.6"}, {"sp": "N", "t": "καὶ προσήιει μὲν ὡς φίλος ὢν πρὸς τοὺς Ἕλληνας· ἐπεὶ δ᾽ ἐγγὺς ἐγένοντο, ἐξαπίνης οἱ μὲν αὐτῶν ἐτόξευον καὶ ἱππεῖς καὶ πεζοί, οἱ δ᾽ ἐσφενδόνων καὶ ἐτίτρωσκον. οἱ δὲ ὀπισθοφύλακες τῶν Ἑλλήνων ἔπασχον μὲν κακῶς, ἀντεποίουν δ᾽ οὐδέν· οἵ τε γὰρ Κρῆτες βραχύτερα τῶν Περσῶν ἐτόξευον καὶ ἅμα ψιλοὶ ὄντες εἴσω τῶν ὅπλων κατεκέκλειντο, οἱ δὲ ἀκοντισταὶ βραχύτερα ἠκόντιζον ἢ ὡς ἐξικνεῖσθαι τῶν σφενδονητῶν.", "st": "3.3.7"}, {"sp": "N", "t": "ἐκ τούτου Ξενοφῶντι ἐδόκει διωκτέον εἶναι· καὶ ἐδίωκον τῶν ὁπλιτῶν καὶ τῶν πελταστῶν οἳ ἔτυχον σὺν αὐτῶι ὀπισθοφυλακοῦντες· διώκοντες δὲ οὐδένα κατελάμβανον τῶν πολεμίων.", "st": "3.3.8"}, {"sp": "N", "t": "οὔτε γὰρ ἱππεῖς ἦσαν τοῖς Ἕλλησιν οὔτε οἱ πεζοὶ τοὺς πεζοὺς ἐκ πολλοῦ φεύγοντας ἐδύναντο καταλαμβάνειν ἐν ὀλίγωι χωρίωι· πολὺ γὰρ οὐχ οἷόν τε ἦν ἀπὸ τοῦ ἄλλου στρατεύματος διώκειν·", "st": "3.3.9"}, {"sp": "N", "t": "οἱ δὲ βάρβαροι ἱππεῖς καὶ φεύγοντες ἅμα ἐτίτρωσκον εἰς τοὔπισθεν τοξεύοντες ἀπὸ τῶν ἵππων, ὁπόσον δὲ διώξειαν οἱ Ἕλληνες, τοσοῦτον πάλιν ἐπαναχωρεῖν μαχομένους ἔδει.", "st": "3.3.10"}, {"sp": "N", "t": "ὥστε τῆς ἡμέρας ὅλης διῆλθον οὐ πλέον πέντε καὶ εἴκοσι σταδίων, ἀλλὰ δείλης ἀφίκοντο εἰς τὰς κώμας. ἔνθα δὴ πάλιν ἀθυμία ἦν. καὶ Χειρίσοφος καὶ οἱ πρεσβύτατοι τῶν στρατηγῶν Ξενοφῶντα ἠιτιῶντο ὅτι ἐδίωκεν ἀπὸ τῆς φάλαγγος καὶ αὐτός τε ἐκινδύνευε καὶ τοὺς πολεμίους οὐδὲν μᾶλλον ἐδύνατο βλάπτειν.", "st": "3.3.11"}, {"sp": "N", "t": "ἀκούσας δὲ Ξενοφῶν ἔλεγεν ὅτι ὀρθῶς αἰτιῶιντο καὶ αὐτὸ τὸ ἔργον αὐτοῖς μαρτυροίη. ἀλλ᾽ ἐγώ, ἔφη, ἠναγκάσθην διώκειν, ἐπειδὴ ἑώρων ἡμᾶς ἐν τῶι μένειν κακῶς μὲν πάσχοντας, ἀντιποιεῖν δὲ οὐ δυναμένους.", "st": "3.3.12"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἐδιώκομεν, ἀληθῆ, ἔφη, ὑμεῖς λέγετε· κακῶς μὲν γὰρ ποιεῖν οὐδὲν μᾶλλον ἐδυνάμεθα τοὺς πολεμίους, ἀνεχωροῦμεν δὲ παγχαλέπως.", "st": "3.3.13"}, {"sp": "N", "t": "τοῖς οὖν θεοῖς χάρις ὅτι οὐ σὺν πολλῆι ῥώμηι ἀλλὰ σὺν ὀλίγοις ἦλθον, ὥστε βλάψαι μὲν μὴ μεγάλα, δηλῶσαι δὲ ὧν δεόμεθα.", "st": "3.3.14"}, {"sp": "N", "t": "νῦν γὰρ οἱ πολέμιοι τοξεύουσι καὶ σφενδονῶσιν ὅσον οὔτε οἱ Κρῆτες ἀντιτοξεύειν δύνανται οὔτε οἱ ἐκ χειρὸς βάλλοντες ἐξικνεῖσθαι· ὅταν δὲ αὐτοὺς διώκωμεν, πολὺ μὲν οὐχ οἷόν τε χωρίον ἀπὸ τοῦ στρατεύματος διώκειν, ἐν ὀλίγωι δὲ οὐδ᾽ εἰ ταχὺς εἴη πεζὸς πεζὸν ἂν διώκων καταλαμβάνοι ἐκ τόξου ῥύματος.", "st": "3.3.15"}, {"sp": "N", "t": "ἡμεῖς οὖν εἰ μέλλοιμεν τούτους εἴργειν ὥστε μὴ δύνασθαι βλάπτειν ἡμᾶς πορευομένους, σφενδονητῶν τὴν ταχίστην δεῖ καὶ ἱππέων. ἀκούω δ᾽ εἶναι ἐν τῶι στρατεύματι ἡμῶν ῾Ροδίους, ὧν τοὺς πολλούς φασιν ἐπίστασθαι σφενδονᾶν, καὶ τὸ βέλος αὐτῶν καὶ διπλάσιον φέρεσθαι τῶν Περσικῶν σφενδονῶν.", "st": "3.3.16"}, {"sp": "N", "t": "ἐκεῖναι γὰρ διὰ τὸ χειροπληθέσι τοῖς λίθοις σφενδονᾶν ἐπὶ βραχὺ ἐξικνοῦνται, οἱ δὲ ῾Ρόδιοι καὶ ταῖς μολυβδίσιν ἐπίστανται χρῆσθαι.", "st": "3.3.17"}, {"sp": "N", "t": "ἢν οὖν αὐτῶν ἐπισκεψώμεθα τίνες πέπανται σφενδόνας, καὶ τούτωι μὲν δῶμεν αὐτῶν ἀργύριον, τῶι δὲ ἄλλας πλέκειν ἐθέλοντι ἄλλο ἀργύριον τελῶμεν, καὶ τῶι σφενδονᾶν ἐν τῶι τεταγμένωι ἐθέλοντι ἄλλην τινὰ ἀτέλειαν εὑρίσκωμεν, ἴσως τινὲς φανοῦνται ἱκανοὶ ἡμᾶς ὠφελεῖν.", "st": "3.3.18"}, {"sp": "N", "t": "ὁρῶ δὲ ἵππους ὄντας ἐν τῶι στρατεύματι, τοὺς μέν τινας παρ᾽ ἐμοί, τοὺς δὲ τῶν Κλεάρχου καταλελειμμένους, πολλοὺς δὲ καὶ ἄλλους αἰχμαλώτους σκευοφοροῦντας. ἂν οὖν τούτους πάντας ἐκλέξαντες σκευοφόρα μὲν ἀντιδῶμεν, τοὺς δὲ ἵππους εἰς ἱππέας κατασκευάσωμεν, ἴσως καὶ οὗτοί τι τοὺς φεύγοντας ἀνιάσουσιν.", "st": "3.3.19"}, {"sp": "N", "t": "ἔδοξε καὶ ταῦτα. καὶ ταύτης τῆς νυκτὸς σφενδονῆται μὲν εἰς διακοσίους ἐγένοντο, ἵπποι δὲ καὶ ἱππεῖς ἐδοκιμάσθησαν τῆι ὑστεραίαι εἰς πεντήκοντα, καὶ σπολάδες καὶ θώρακες αὐτοῖς ἐπορίσθησαν, καὶ ἵππαρχος ἐπεστάθη Λύκιος ὁ Πολυστράτου Ἀθηναῖος.", "st": "3.3.20"}, {"sp": "N", "t": "μείναντες δὲ ταύτην τὴν ἡμέραν τῆι ἄλληι ἐπορεύοντο πρωιαίτερον ἀναστάντες· χαράδραν γὰρ ἔδει αὐτοὺς διαβῆναι ἐφ᾽ ἧι ἐφοβοῦντο μὴ ἐπιθοῖντο αὐτοῖς διαβαίνουσιν οἱ πολέμιοι.", "st": "3.4.1"}, {"sp": "N", "t": "διαβεβηκόσι δὲ αὐτοῖς πάλιν φαίνεται Μιθραδάτης, ἔχων ἱππέας χιλίους, τοξότας δὲ καὶ σφενδονήτας εἰς τετρακισχιλίους· τοσούτους γὰρ ἤιτησε Τισσαφέρνην, καὶ ἔλαβεν ὑποσχόμενος, ἂν τούτους λάβηι, παραδώσειν αὐτῶι τοὺς Ἕλληνας, καταφρονήσας, ὅτι ἐν τῆι πρόσθεν προσβολῆι ὀλίγους ἔχων ἔπαθε μὲν οὐδέν, πολλὰ δὲ κακὰ ἐνόμιζε ποιῆσαι.", "st": "3.4.2"}, {"sp": "N", "t": "ἐπεὶ δὲ οἱ Ἕλληνες διαβεβηκότες ἀπεῖχον τῆς χαράδρας ὅσον ὀκτὼ σταδίους, διέβαινε καὶ ὁ Μιθραδάτης ἔχων τὴν δύναμιν. παρήγγελτο δὲ τῶν τε πελταστῶν οὓς ἔδει διώκειν καὶ τῶν ὁπλιτῶν, καὶ τοῖς ἱππεῦσιν εἴρητο θαρροῦσι διώκειν ὡς ἐφεψομένης ἱκανῆς δυνάμεως.", "st": "3.4.3"}, {"sp": "N", "t": "ἐπεὶ δὲ ὁ Μιθραδάτης κατειλήφει, καὶ ἤδη σφενδόναι καὶ τοξεύματα ἐξικνοῦντο, ἐσήμηνε τοῖς Ἕλλησι τῆι σάλπιγγι, καὶ εὐθὺς ἔθεον ὁμόσε οἷς εἴρητο καὶ οἱ ἱππεῖς ἤλαυνον· οἱ δὲ οὐκ ἐδέξαντο, ἀλλ᾽ ἔφευγον ἐπὶ τὴν χαράδραν.", "st": "3.4.4"}, {"sp": "N", "t": "ἐν ταύτηι τῆι διώξει τοῖς βαρβάροις τῶν τε πεζῶν ἀπέθανον πολλοὶ καὶ τῶν ἱππέων ἐν τῆι χαράδραι ζωοὶ ἐλήφθησαν εἰς ὀκτωκαίδεκα. τοὺς δὲ ἀποθανόντας αὐτοκέλευστοι οἱ Ἕλληνες ἠικίσαντο, ὡς ὅτι φοβερώτατον τοῖς πολεμίοις εἴη ὁρᾶν.", "st": "3.4.5"}, {"sp": "N", "t": "καὶ οἱ μὲν πολέμιοι οὕτω πράξαντες ἀπῆλθον, οἱ δὲ Ἕλληνες ἀσφαλῶς πορευόμενοι τὸ λοιπὸν τῆς ἡμέρας ἀφίκοντο ἐπὶ τὸν Τίγρητα ποταμόν.", "st": "3.4.6"}, {"sp": "N", "t": "ἐνταῦθα πόλις ἦν ἐρήμη μεγάλη, ὄνομα δ᾽ αὐτῆι ἦν Λάρισα· ὤικουν δ᾽ αὐτὴν τὸ παλαιὸν Μῆδοι. τοῦ δὲ τείχους αὐτῆς ἦν τὸ εὖρος πέντε καὶ εἴκοσι πόδες, ὕψος δ᾽ ἑκατόν· τοῦ δὲ κύκλου ἡ περίοδος δύο παρασάγγαι· ὠικοδόμητο δὲ πλίνθοις κεραμεαῖς· κρηπὶς δ᾽ ὑπῆν λιθίνη τὸ ὕψος εἴκοσι ποδῶν.", "st": "3.4.7"}, {"sp": "N", "t": "ταύτην βασιλεὺς Περσῶν ὅτε παρὰ Μήδων τὴν ἀρχὴν ἐλάμβανον Πέρσαι πολιορκῶν οὐδενὶ τρόπωι ἐδύνατο ἑλεῖν· ἥλιον δὲ νεφέλη προκαλύψασα ἠφάνισε μέχρι ἐξέλιπον οἱ ἄνθρωποι, καὶ οὕτως ἑάλω.", "st": "3.4.8"}, {"sp": "N", "t": "παρὰ ταύτην τὴν πόλιν ἦν πυραμὶς λιθίνη, τὸ μὲν εὖρος ἑνὸς πλέθρου, τὸ δὲ ὕψος δύο πλέθρων. ἐπὶ ταύτης πολλοὶ τῶν βαρβάρων ἦσαν ἐκ τῶν πλησίον κωμῶν ἀποπεφευγότες.", "st": "3.4.9"}, {"sp": "N", "t": "ἐντεῦθεν δ᾽ ἐπορεύθησαν σταθμὸν ἕνα παρασάγγας ἓξ πρὸς τεῖχος ἔρημον μέγα πρὸς τῆι πόλει κείμενον· ὄνομα δὲ ἦν τῆι πόλει Μέσπιλα· Μῆδοι δ᾽ αὐτήν ποτε ὤικουν. ἦν δὲ ἡ μὲν κρηπὶς λίθου ξεστοῦ κογχυλιάτου, τὸ εὖρος πεντήκοντα ποδῶν καὶ τὸ ὕψος πεντήκοντα.", "st": "3.4.10"}, {"sp": "N", "t": "ἐπὶ δὲ ταύτηι ἐπωικοδόμητο πλίνθινον τεῖχος, τὸ μὲν εὖρος πεντήκοντα ποδῶν, τὸ δὲ ὕψος ἑκατόν· τοῦ δὲ τείχους ἡ περίοδος ἓξ παρασάγγαι. ἐνταῦθα λέγεται Μήδεια γυνὴ βασιλέως καταφυγεῖν ὅτε ἀπώλλυσαν τὴν ἀρχὴν ὑπὸ Περσῶν Μῆδοι.", "st": "3.4.11"}, {"sp": "N", "t": "ταύτην δὲ τὴν πόλιν πολιορκῶν ὁ Περσῶν βασιλεὺς οὐκ ἐδύνατο οὔτε χρόνωι ἑλεῖν οὔτε βίαι· Ζεὺς δὲ βροντῆι κατέπληξε τοὺς ἐνοικοῦντας, καὶ οὕτως ἑάλω.", "st": "3.4.12"}, {"sp": "N", "t": "ἐντεῦθεν δ᾽ ἐπορεύθησαν σταθμὸν ἕνα παρασάγγας τέτταρας. εἰς τοῦτον δὲ τὸν σταθμὸν Τισσαφέρνης ἐπεφάνη, οὕς τε αὐτὸς ἱππέας ἦλθεν ἔχων καὶ τὴν Ὀρόντα δύναμιν τοῦ τὴν βασιλέως θυγατέρα ἔχοντος καὶ οὓς Κῦρος ἔχων ἀνέβη βαρβάρους καὶ οὓς ὁ βασιλέως ἀδελφὸς ἔχων βασιλεῖ ἐβοήθει, καὶ πρὸς τούτοις ὅσους βασιλεὺς ἔδωκεν αὐτῶι, ὥστε τὸ στράτευμα πάμπολυ ἐφάνη.", "st": "3.4.13"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἐγγὺς ἐγένετο, τὰς μὲν τῶν τάξεων ὄπισθεν καταστήσας, τὰς δὲ εἰς τὰ πλάγια παραγαγὼν ἐμβαλεῖν μὲν οὐκ ἐτόλμησεν οὐδ᾽ ἐβούλετο διακινδυνεύειν, σφενδονᾶν δὲ παρήγγειλε καὶ τοξεύειν.", "st": "3.4.14"}, {"sp": "N", "t": "ἐπεὶ δὲ διαταχθέντες οἱ ῾Ρόδιοι ἐσφενδόνησαν καὶ οἱ [Σκύθαι] τοξόται ἐτόξευσαν καὶ οὐδεὶς ἡμάρτανεν ἀνδρός (οὐδὲ γὰρ εἰ πάνυ προυθυμεῖτο ῥάιδιον ἦν), καὶ ὁ Τισσαφέρνης μάλα ταχέως ἔξω βελῶν ἀπεχώρει καὶ ⟨αἱ⟩ ἄλλαι τάξεις ἀπεχώρησαν.", "st": "3.4.15"}, {"sp": "N", "t": "καὶ τὸ λοιπὸν τῆς ἡμέρας οἱ μὲν ἐπορεύοντο, οἱ δ᾽ εἵποντο· καὶ οὐκέτι ἐσίνοντο οἱ βάρβαροι τῆι τότε ἀκροβολίσει· μακρότερον γὰρ οἵ τε ῾Ρόδιοι τῶν Περσῶν ἐσφενδόνων καὶ τῶν τοξοτῶν·", "st": "3.4.16"}, {"sp": "N", "t": "μεγάλα δὲ καὶ τόξα τὰ Περσικά ἐστιν· ὥστε χρήσιμα ἦν ὁπόσα ἁλίσκοιτο τῶν τοξευμάτων τοῖς Κρησί, καὶ διετέλουν χρώμενοι τοῖς τῶν πολεμίων τοξεύμασι, καὶ ἐμελέτων τοξεύειν ἄνω ἱέντες μακράν. ηὑρίσκετο δὲ καὶ νεῦρα πολλὰ ἐν ταῖς κώμαις καὶ μόλυβδος, ὥστε χρῆσθαι εἰς τὰς σφενδόνας.", "st": "3.4.17"}, {"sp": "N", "t": "καὶ ταύτηι μὲν τῆι ἡμέραι, ἐπεὶ κατεστρατοπεδεύοντο οἱ Ἕλληνες κώμαις ἐπιτυχόντες, ἀπῆλθον οἱ βάρβαροι μεῖον ἔχοντες τῆι ἀκροβολίσει· τὴν δ᾽ ἐπιοῦσαν ἡμέραν ἔμειναν οἱ Ἕλληνες καὶ ἐπεσιτίσαντο· ἦν γὰρ πολὺς σῖτος ἐν ταῖς κώμαις. τῆι δὲ ὑστεραίαι ἐπορεύοντο διὰ τοῦ πεδίου, καὶ Τισσαφέρνης εἵπετο ἀκροβολιζόμενος.", "st": "3.4.18"}, {"sp": "N", "t": "ἔνθα δὲ οἱ Ἕλληνες ἔγνωσαν πλαίσιον ἰσόπλευρον ὅτι πονηρὰ τάξις εἴη πολεμίων ἑπομένων. ἀνάγκη γάρ ἐστιν, ἢν συγκύπτηι τὰ κέρατα τοῦ πλαισίου ἢ ὁδοῦ στενοτέρας οὔσης ἢ ὀρέων ἀναγκαζόντων ἢ γεφύρας, ἐκθλίβεσθαι τοὺς ὁπλίτας καὶ πορεύεσθαι πονήρως ἅμα μὲν πιεζομένους, ἅμα δὲ καὶ ταραττομένους, ὥστε δυσχρήστους εἶναι [ἀνάγκη] ἀτάκτους ὄντας·", "st": "3.4.19"}, {"sp": "N", "t": "ὅταν δ᾽ αὖ διάσχηι τὰ κέρατα, ἀνάγκη διασπᾶσθαι τοὺς τότε ἐκθλιβομένους καὶ κενὸν γίγνεσθαι τὸ μέσον τῶν κεράτων, καὶ ἀθυμεῖν τοὺς ταῦτα πάσχοντας πολεμίων ἑπομένων. καὶ ὁπότε δέοι γέφυραν διαβαίνειν ἢ ἄλλην τινὰ διάβασιν, ἔσπευδεν ἕκαστος βουλόμενος φθάσαι πρῶτος· καὶ εὐεπίθετον ἦν ἐνταῦθα τοῖς πολεμίοις.", "st": "3.4.20"}, {"sp": "N", "t": "ἐπεὶ δὲ ταῦτ᾽ ἔγνωσαν οἱ στρατηγοί, ἐποίησαν ἓξ λόχους ἀνὰ ἑκατὸν ἄνδρας, καὶ λοχαγοὺς ἐπέστησαν καὶ ἄλλους πεντηκοντῆρας καὶ ἄλλους ἐνωμοτάρχους. οὗτοι δὲ πορευόμενοι, ὁπότε μὲν συγκύπτοι τὰ κέρατα, ὑπέμενον ὕστεροι [οἱ λοχαγοί], ὥστε μὴ ἐνοχλεῖν τοῖς κέρασι, τότε δὲ παρῆγον ἔξωθεν τῶν κεράτων.", "st": "3.4.21"}, {"sp": "N", "t": "ὁπότε δὲ διάσχοιεν αἱ πλευραὶ τοῦ πλαισίου, τὸ μέσον ἂν ἐξεπίμπλασαν, εἰ μὲν στενότερον εἴη τὸ διέχον, κατὰ λόχους, εἰ δὲ πλατύτερον, κατὰ πεντηκοστῦς, εἰ δὲ πάνυ πλατύ, κατ᾽ ἐνωμοτίας· ὥστε ἀεὶ ἔκπλεων εἶναι τὸ μέσον.", "st": "3.4.22"}, {"sp": "N", "t": "εἰ δὲ καὶ διαβαίνειν τινὰ δέοι διάβασιν ἢ γέφυραν, οὐκ ἐταράττοντο, ἀλλ᾽ ἐν τῶι μέρει οἱ λοχαγοὶ διέβαινον· καὶ εἴ που δέοι τι τῆς φάλαγγος, ἐπιπαρῆισαν οὗτοι. τούτωι τῶι τρόπωι ἐπορεύθησαν σταθμοὺς τέτταρας.", "st": "3.4.23"}, {"sp": "N", "t": "ἡνίκα δὲ τὸν πέμπτον ἐπορεύοντο, εἶδον βασίλειόν τι καὶ περὶ αὐτὸ κώμας πολλάς, τὴν δὲ ὁδὸν πρὸς τὸ χωρίον τοῦτο διὰ γηλόφων ὑψηλῶν γιγνομένην, οἳ καθῆκον ἀπὸ τοῦ ὄρους ὑφ᾽ ὧι ἦν ἡ κώμη. καὶ εἶδον μὲν τοὺς λόφους ἄσμενοι οἱ Ἕλληνες, ὡς εἰκὸς τῶν πολεμίων ὄντων ἱππέων·", "st": "3.4.24"}, {"sp": "N", "t": "ἐπεὶ δὲ πορευόμενοι ἐκ τοῦ πεδίου ἀνέβησαν ἐπὶ τὸν πρῶτον γήλοφον ⟨καὶ⟩ κατέβαινον, ὡς ἐπὶ τὸν ἕτερον ἀναβαίνειν, ἐνταῦθα ἐπιγίγνονται οἱ βάρβαροι καὶ ἀπὸ τοῦ ὑψηλοῦ εἰς τὸ πρανὲς ἔβαλλον, ἐσφενδόνων, ἐτόξευον ὑπὸ μαστίγων,", "st": "3.4.25"}, {"sp": "N", "t": "καὶ πολλοὺς ἐτίτρωσκον καὶ ἐκράτησαν τῶν Ἑλλήνων γυμνήτων καὶ κατέκλεισαν αὐτοὺς εἴσω τῶν ὅπλων· ὥστε παντάπασι ταύτην τὴν ἡμέραν ἄχρηστοι ἦσαν ἐν τῶι ὄχλωι ὄντες καὶ οἱ σφενδονῆται καὶ οἱ τοξόται.", "st": "3.4.26"}, {"sp": "N", "t": "ἐπεὶ δὲ πιεζόμενοι οἱ Ἕλληνες ἐπεχείρησαν διώκειν, σχολῆι μὲν ἐπὶ τὸ ἄκρον ἀφικνοῦνται ὁπλῖται ὄντες, οἱ δὲ πολέμιοι ταχὺ ἀπεπήδων.", "st": "3.4.27"}, {"sp": "N", "t": "πάλιν δὲ ὁπότε ἀπίοιεν πρὸς τὸ ἄλλο στράτευμα ταὐτὰ ἔπασχον, καὶ ἐπὶ τοῦ δευτέρου γηλόφου ταὐτὰ ἐγίγνετο, ὥστε ἀπὸ τοῦ τρίτου γηλόφου ἔδοξεν αὐτοῖς μὴ κινεῖν τοὺς στρατιώτας πρὶν ἀπὸ τῆς δεξιᾶς πλευρᾶς τοῦ πλαισίου ἀνήγαγον πελταστὰς πρὸς τὸ ὄρος.", "st": "3.4.28"}, {"sp": "N", "t": "ἐπεὶ δ᾽ οὗτοι ἐγένοντο ὑπὲρ τῶν ἑπομένων πολεμίων, οὐκέτι ἐπετίθεντο οἱ πολέμιοι τοῖς καταβαίνουσι, δεδοικότες μὴ ἀποτμηθείησαν καὶ ἀμφοτέρωθεν αὐτῶν γένοιντο οἱ πολέμιοι.", "st": "3.4.29"}, {"sp": "N", "t": "οὕτω τὸ λοιπὸν τῆς ἡμέρας πορευόμενοι, οἱ μὲν ⟨ἐν⟩ τῆι ὁδῶι κατὰ τοὺς γηλόφους, οἱ δὲ κατὰ τὸ ὄρος ἐπιπαριόντες, ἀφίκοντο εἰς τὰς κώμας· καὶ ἰατροὺς κατέστησαν ὀκτώ· πολλοὶ γὰρ ἦσαν οἱ τετρωμένοι.", "st": "3.4.30"}, {"sp": "N", "t": "ἐνταῦθα ἔμειναν ἡμέρας τρεῖς καὶ τῶν τετρωμένων ἕνεκα καὶ ἅμα ἐπιτήδεια πολλὰ εἶχον, ἄλευρα, οἶνον, κριθὰς ἵπποις συμβεβλημένας πολλάς. ταῦτα δὲ συνενηνεγμένα ἦν τῶι σατραπεύοντι τῆς χώρας.", "st": "3.4.31"}, {"sp": "N", "t": "τετάρτηι δ᾽ ἡμέραι καταβαίνουσιν εἰς τὸ πεδίον. ἐπεὶ δὲ κατέλαβεν αὐτοὺς Τισσαφέρνης σὺν τῆι δυνάμει, ἐδίδαξεν αὐτοὺς ἡ ἀνάγκη κατασκηνῆσαι οὗ πρῶτον εἶδον κώμην καὶ μὴ πορεύεσθαι ἔτι μαχομένους· πολλοὶ γὰρ ἦσαν οἱ ἀπόμαχοι, ⟨οἵ τε⟩ τετρωμένοι καὶ οἱ ἐκείνους φέροντες καὶ οἱ τῶν φερόντων τὰ ὅπλα δεξάμενοι.", "st": "3.4.32"}, {"sp": "N", "t": "ἐπεὶ δὲ κατεσκήνησαν καὶ ἐπεχείρησαν αὐτοῖς ἀκροβολίζεσθαι οἱ βάρβαροι πρὸς τὴν κώμην προσιόντες, πολὺ περιῆσαν οἱ Ἕλληνες· πολὺ γὰρ διέφερεν ἐκ χώρας ὁρμῶντας ἀλέξασθαι ἢ πορευομένους ἐπιοῦσι τοῖς πολεμίοις μάχεσθαι.", "st": "3.4.33"}, {"sp": "N", "t": "ἡνίκα δ᾽ ἦν ἤδη δείλη, ὥρα ἦν ἀπιέναι τοῖς πολεμίοις· οὔποτε γὰρ μεῖον ἀπεστρατοπεδεύοντο οἱ βάρβαροι τοῦ Ἑλληνικοῦ ἑξήκοντα σταδίων, φοβούμενοι μὴ τῆς νυκτὸς οἱ Ἕλληνες ἐπιθῶνται αὐτοῖς.", "st": "3.4.34"}, {"sp": "N", "t": "πονηρὸν γὰρ νυκτός ἐστι στράτευμα Περσικόν. οἵ τε γὰρ ἵπποι αὐτοῖς δέδενται καὶ ὡς ἐπὶ τὸ πολὺ πεποδισμένοι εἰσὶ τοῦ μὴ φεύγειν ἕνεκα εἰ λυθείησαν, ἐάν τέ τις θόρυβος γίγνηται, δεῖ ἐπισάξαι τὸν ἵππον Πέρσηι ἀνδρὶ καὶ χαλινῶσαι, δεῖ καὶ θωρακισθέντα ἀναβῆναι ἐπὶ τὸν ἵππον. ταῦτα δὲ πάντα χαλεπὰ νύκτωρ καὶ θορύβου ὄντος. τούτου ἕνεκα πόρρω ἀπεσκήνουν τῶν Ἑλλήνων.", "st": "3.4.35"}, {"sp": "N", "t": "ἐπεὶ δὲ ἐγίγνωσκον αὐτοὺς οἱ Ἕλληνες βουλομένους ἀπιέναι καὶ διαγγελλομένους, ἐκήρυξε τοῖς Ἕλλησι συσκευάζεσθαι ἀκουόντων τῶν πολεμίων. καὶ χρόνον μέν τινα ἐπέσχον τῆς πορείας οἱ βάρβαροι, ἐπειδὴ δὲ ὀψὲ ἐγίγνετο, ἀπῆισαν· οὐ γὰρ ἐδόκει λύειν αὐτοὺς νυκτὸς πορεύεσθαι καὶ κατάγεσθαι ἐπὶ τὸ στρατόπεδον.", "st": "3.4.36"}, {"sp": "N", "t": "ἐπειδὴ δὲ σαφῶς ἀπιόντας ἤδη ἑώρων οἱ Ἕλληνες, ἐπορεύοντο καὶ αὐτοὶ ἀναζεύξαντες καὶ διῆλθον ὅσον ἑξήκοντα σταδίους. καὶ γίγνεται τοσοῦτον μεταξὺ τῶν στρατευμάτων ὥστε τῆι ὑστεραίαι οὐκ ἐφάνησαν οἱ πολέμιοι οὐδὲ τῆι τρίτηι, τῆι δὲ τετάρτηι νυκτὸς προελθόντες καταλαμβάνουσι χωρίον ὑπερδέξιον οἱ βάρβαροι, ἧι ἔμελλον οἱ Ἕλληνες παριέναι, ἀκρωνυχίαν ὄρους, ὑφ᾽ ἣν ἡ κατάβασις ἦν εἰς τὸ πεδίον.", "st": "3.4.37"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἑώρα Χειρίσοφος προκατειλημμένην τὴν ἀκρωνυχίαν, καλεῖ Ξενοφῶντα ἀπὸ τῆς οὐρᾶς καὶ κελεύει λαβόντα τοὺς πελταστὰς παραγενέσθαι εἰς τὸ πρόσθεν.", "st": "3.4.38"}, {"sp": "N", "t": "ὁ δὲ Ξενοφῶν τοὺς μὲν πελταστὰς οὐκ ἦγεν· ἐπιφαινόμενον γὰρ ἑώρα Τισσαφέρνην καὶ τὸ στράτευμα πᾶν· αὐτὸς δὲ προσελάσας ἠρώτα «τί καλεῖς;» ὁ δὲ λέγει αὐτῶι· «ἔξεστιν ὁρᾶν· κατείληπται γὰρ ἡμῖν ὁ ὑπὲρ τῆς καταβάσεως λόφος, καὶ οὐκ ἔστι παρελθεῖν, εἰ μὴ τούτους ἀποκόψομεν.", "st": "3.4.39"}, {"sp": "N", "t": "ἀλλὰ τί οὐκ ἦγες τοὺς πελταστάς;» ὁ δὲ λέγει ὅτι οὐκ ἐδόκει αὐτῶι ἔρημα καταλιπεῖν τὰ ὄπισθεν πολεμίων ἐπιφαινομένων. «ἀλλὰ μὴν ὥρα γ᾽, ἔφη, βουλεύεσθαι πῶς τις τοὺς ἄνδρας ἀπελᾶι ἀπὸ τοῦ λόφου.»", "st": "3.4.40"}, {"sp": "N", "t": "ἐνταῦθα Ξενοφῶν ὁρᾶι τοῦ ὄρους τὴν κορυφὴν ὑπὲρ αὐτοῦ τοῦ ἑαυτῶν στρατεύματος οὖσαν, καὶ ἀπὸ ταύτης ἔφοδον ἐπὶ τὸν λόφον ἔνθα ἦσαν οἱ πολέμιοι, καὶ λέγει· «κράτιστον, ὦ Χειρίσοφε, ἡμῖν ἵεσθαι ὡς τάχιστα ἐπὶ τὸ ἄκρον· ἢν γὰρ τοῦτο λάβωμεν, οὐ δυνήσονται μένειν οἱ ὑπὲρ τῆς ὁδοῦ. ἀλλά, εἰ βούλει, μένε ἐπὶ τῶι στρατεύματι, ἐγὼ δ᾽ ἐθέλω πορεύεσθαι· εἰ δὲ χρήιζεις, πορεύου ἐπὶ τὸ ὄρος, ἐγὼ δὲ μενῶ αὐτοῦ.", "st": "3.4.41"}, {"sp": "N", "t": "«ἀλλὰ δίδωμί σοι, ἔφη ὁ Χειρίσοφος, ὁπότερον βούλει ἑλέσθαι.» εἰπὼν ὁ Ξενοφῶν ὅτι νεώτερός ἐστιν αἱρεῖται πορεύεσθαι, κελεύει δέ οἱ συμπέμψαι ἀπὸ τοῦ στόματος ἄνδρας· μακρὸν γὰρ ἦν ἀπὸ τῆς οὐρᾶς λαβεῖν.", "st": "3.4.42"}, {"sp": "N", "t": "καὶ ὁ Χειρίσοφος συμπέμπει τοὺς ἀπὸ τοῦ στόματος πελταστάς, ἔλαβε δὲ τοὺς κατὰ μέσον πλαισίου. συνέπεσθαι δ᾽ ἐκέλευσεν αὐτῶι καὶ τοὺς τριακοσίους οὓς αὐτὸς εἶχε τῶν ἐπιλέκτων ἐπὶ τῶι στόματι τοῦ πλαισίου.", "st": "3.4.43"}, {"sp": "N", "t": "ἐντεῦθεν ἐπορεύοντο ὡς ἐδύναντο τάχιστα. οἱ δ᾽ ἐπὶ τοῦ λόφου πολέμιοι ὡς ἐνόησαν αὐτῶν τὴν πορείαν ἐπὶ τὸ ἄκρον, εὐθὺς καὶ αὐτοὶ ὥρμησαν ἁμιλλᾶσθαι ἐπὶ τὸ ἄκρον.", "st": "3.4.44"}, {"sp": "N", "t": "καὶ ἐνταῦθα πολλὴ μὲν κραυγὴ ἦν τοῦ Ἑλληνικοῦ στρατεύματος διακελευομένων τοῖς ἑαυτῶν, πολλὴ δὲ κραυγὴ τῶν ἀμφὶ Τισσαφέρνην τοῖς ἑαυτῶν διακελευομένων.", "st": "3.4.45"}, {"sp": "N", "t": "Ξενοφῶν δὲ παρελαύνων ἐπὶ τοῦ ἵππου παρεκελεύετο· «ἄνδρες, νῦν ἐπὶ τὴν Ἑλλάδα νομίζετε ἁμιλλᾶσθαι, νῦν πρὸς τοὺς παῖδας καὶ τὰς γυναῖκας, νῦν ὀλίγον πονήσαντες ἀμαχεὶ τὴν λοιπὴν πορευσόμεθα.»", "st": "3.4.46"}, {"sp": "N", "t": "Σωτηρίδας δὲ ὁ Σικυώνιος εἶπεν· «οὐκ ἐξ ἴσου, ὦ Ξενοφῶν, ἐσμέν· σὺ μὲν γὰρ ἐφ᾽ ἵππου ὀχῆι, ἐγὼ δὲ χαλεπῶς κάμνω τὴν ἀσπίδα φέρων.»", "st": "3.4.47"}, {"sp": "N", "t": "καὶ ὃς ἀκούσας ταῦτα καταπηδήσας ἀπὸ τοῦ ἵππου ὠθεῖται αὐτὸν ἐκ τῆς τάξεως καὶ τὴν ἀσπίδα ἀφελόμενος ὡς ἐδύνατο τάχιστα ἔχων ἐπορεύετο· ἐτύγχανε δὲ καὶ θώρακα ἔχων τὸν ἱππικόν· ὥστ᾽ ἐπιέζετο. καὶ τοῖς μὲν ἔμπροσθεν ὑπάγειν παρεκελεύετο, τοῖς δὲ ὄπισθεν παριέναι μόλις ἑπόμενος.", "st": "3.4.48"}, {"sp": "N", "t": "οἱ δ᾽ ἄλλοι στρατιῶται παίουσι καὶ βάλλουσι καὶ λοιδοροῦσι τὸν Σωτηρίδαν, ἔστε ἠνάγκασαν λαβόντα τὴν ἀσπίδα πορεύεσθαι. ὁ δὲ ἀναβάς, ἕως μὲν βάσιμα ἦν, ἐπὶ τοῦ ἵππου ἦγεν, ἐπεὶ δὲ ἄβατα ἦν, καταλιπὼν τὸν ἵππον ἔσπευδε πεζῆι. καὶ φθάνουσιν ἐπὶ τῶι ἄκρωι γενόμενοι τοὺς πολεμίους.", "st": "3.4.49"}, {"sp": "N", "t": "ἔνθα δὴ οἱ μὲν βάρβαροι στραφέντες ἔφευγον ἧι ἕκαστος ἐδύνατο, οἱ δὲ Ἕλληνες εἶχον τὸ ἄκρον. οἱ δὲ ἀμφὶ Τισσαφέρνην καὶ Ἀριαῖον ἀποτραπόμενοι ἄλλην ὁδὸν ὤιχοντο. οἱ δὲ ἀμφὶ Χειρίσοφον καταβάντες ἐστρατοπεδεύοντο ἐν κώμηι μεστῆι πολλῶν ἀγαθῶν. ἦσαν δὲ καὶ ἄλλαι κῶμαι πολλαὶ πλήρεις πολλῶν ἀγαθῶν ἐν τούτωι τῶι πεδίωι παρὰ τὸν Τίγρητα ποταμόν.", "st": "3.5.1"}, {"sp": "N", "t": "ἡνίκα δ᾽ ἦν δείλη ἐξαπίνης οἱ πολέμιοι ἐπιφαίνονται ἐν τῶι πεδίωι, καὶ τῶν Ἑλλήνων κατέκοψάν τινας τῶν ἐσκεδασμένων ἐν τῶι πεδίωι καθ᾽ ἁρπαγήν· καὶ γὰρ νομαὶ πολλαὶ βοσκημάτων διαβιβαζόμεναι εἰς τὸ πέραν τοῦ ποταμοῦ κατελήφθησαν.", "st": "3.5.2"}, {"sp": "N", "t": "ἐνταῦθα Τισσαφέρνης καὶ οἱ σὺν αὐτῶι καίειν ἐπεχείρησαν τὰς κώμας. καὶ τῶν Ἑλλήνων μάλα ἠθύμησάν τινες, ἐννοούμενοι μὴ τὰ ἐπιτήδεια, εἰ καίοιεν, οὐκ ἔχοιεν ὁπόθεν λαμβάνοιεν.", "st": "3.5.3"}, {"sp": "N", "t": "καὶ οἱ μὲν ἀμφὶ Χειρίσοφον ἀπῆισαν ἐκ τῆς βοηθείας· ὁ δὲ Ξενοφῶν ἐπεὶ κατέβη, παρελαύνων τὰς τάξεις ἡνίκα ἀπὸ τῆς βοηθείας ἀπήντησαν οἱ Ἕλληνες ἔλεγεν·", "st": "3.5.4"}, {"sp": "N", "t": "«ὁρᾶτε, ὦ ἄνδρες Ἕλληνες, ὑφιέντας τὴν χώραν ἤδη ἡμετέραν εἶναι; ἃ γὰρ ὅτε ἐσπένδοντο διεπράττοντο, μὴ καίειν τὴν βασιλέως χώραν, νῦν αὐτοὶ καίουσιν ὡς ἀλλοτρίαν. ἀλλ᾽ ἐάν που καταλείπωσί γε αὑτοῖς ἐπιτήδεια, ὄψονται καὶ ἡμᾶς ἐνταῦθα πορευομένους.", "st": "3.5.5"}, {"sp": "N", "t": "ἀλλ᾽, ὦ Χειρίσοφε, ἔφη, δοκεῖ μοι βοηθεῖν ἐπὶ τοὺς καίοντας ὡς ὑπὲρ τῆς ἡμετέρας.» ὁ δὲ Χειρίσοφος εἶπεν· «οὔκουν ἔμοιγε δοκεῖ· ἀλλὰ καὶ ἡμεῖς, ἔφη, καίωμεν, καὶ οὕτω θᾶττον παύσονται.»", "st": "3.5.6"}, {"sp": "N", "t": "ἐπεὶ δὲ ἐπὶ τὰς σκηνὰς ἦλθον, οἱ μὲν ἄλλοι περὶ τὰ ἐπιτήδεια ἦσαν, στρατηγοὶ δὲ καὶ λοχαγοὶ συνῆισαν. καὶ ἐνταῦθα πολλὴ ἀπορία ἦν. ἔνθεν μὲν γὰρ ὄρη ἦν ὑπερύψηλα, ἔνθεν δὲ ὁ ποταμὸς τοσοῦτος βάθος ὡς μηδὲ τὰ δόρατα ὑπερέχειν πειρωμένοις τοῦ βάθους.", "st": "3.5.7"}, {"sp": "N", "t": "ἀπορουμένοις δ᾽ αὐτοῖς προσελθών τις ἀνὴρ ῾Ρόδιος εἶπεν· «ἐγὼ θέλω, ὦ ἄνδρες, διαβιβάσαι ὑμᾶς κατὰ τετρακισχιλίους ὁπλίτας, ἂν ἐμοὶ ὧν δέομαι ὑπηρετήσητε καὶ τάλαντον μισθὸν πορίσητε.»", "st": "3.5.8"}, {"sp": "N", "t": "ἐρωτώμενος δὲ ὅτου δέοιτο, «ἀσκῶν, ἔφη, δισχιλίων δεήσομαι· πολλὰ δ᾽ ὁρῶ πρόβατα καὶ αἶγας καὶ βοῦς καὶ ὄνους, ἃ ἀποδαρέντα καὶ φυσηθέντα ῥαιδίως ἂν παρέχοι τὴν διάβασιν.", "st": "3.5.9"}, {"sp": "N", "t": "δεήσομαι δὲ καὶ τῶν δεσμῶν οἷς χρῆσθε περὶ τὰ ὑποζύγια· τούτοις ζεύξας τοὺς ἀσκοὺς πρὸς ἀλλήλους, ὁρμίσας ἕκαστον ἀσκὸν λίθους ἀρτήσας καὶ ἀφεὶς ὥσπερ ἀγκύρας εἰς τὸ ὕδωρ, διαγαγὼν καὶ ἀμφοτέρωθεν δήσας ἐπιβαλῶ ὕλην καὶ γῆν ἐπιφορήσω·", "st": "3.5.10"}, {"sp": "N", "t": "ὅτι μὲν οὖν οὐ καταδύσεσθε αὐτίκα μάλα εἴσεσθε· πᾶς γὰρ ἀσκὸς δύ᾽ ἄνδρας ἕξει τοῦ μὴ καταδῦναι. ὥστε δὲ μὴ ὀλισθάνειν ἡ ὕλη καὶ ἡ γῆ σχήσει.»", "st": "3.5.11"}, {"sp": "N", "t": "ἀκούσασι ταῦτα τοῖς στρατηγοῖς τὸ μὲν ἐνθύμημα χαρίεν ἐδόκει εἶναι, τὸ δ᾽ ἔργον ἀδύνατον· ἦσαν γὰρ οἱ κωλύσοντες πέραν πολλοὶ ἱππεῖς, οἳ εὐθὺς τοῖς πρώτοις οὐδὲν ἂν ἐπέτρεπον τούτων ποιεῖν.", "st": "3.5.12"}, {"sp": "N", "t": "ἐνταῦθα τὴν μὲν ὑστεραίαν ὑπανεχώρουν εἰς τοὔμπαλιν [ἢ πρὸς Βαβυλῶνα] εἰς τὰς ἀκαύστους κώμας, κατακαύσαντες ἔνθεν ἐξῆισαν· ὥστε οἱ πολέμιοι οὐ προσήλαυνον, ἀλλὰ ἐθεῶντο καὶ ὅμοιοι ἦσαν θαυμάζειν ὅποι ποτὲ τρέψονται οἱ Ἕλληνες καὶ τί ἐν νῶι ἔχοιεν.", "st": "3.5.13"}, {"sp": "N", "t": "ἐνταῦθα οἱ μὲν ἄλλοι στρατιῶται ἐπὶ τὰ ἐπιτήδεια ἦισαν· οἱ δὲ στρατηγοὶ πάλιν συνῆλθον, καὶ συναγαγόντες τοὺς ἑαλωκότας ἤλεγχον τὴν κύκλωι πᾶσαν χώραν τίς ἑκάστη εἴη.", "st": "3.5.14"}, {"sp": "N", "t": "οἱ δὲ ἔλεγον ὅτι τὰ πρὸς μεσημβρίαν τῆς ἐπὶ Βαβυλῶνα εἴη καὶ Μηδίαν, δι᾽ ἧσπερ ἥκοιεν, ἡ δὲ πρὸς ἕω ἐπὶ Σοῦσά τε καὶ Ἐκβάτανα φέροι, ἔνθα θερίζειν λέγεται βασιλεύς, ἡ δὲ διαβάντι τὸν ποταμὸν πρὸς ἑσπέραν ἐπὶ Λυδίαν καὶ Ἰωνίαν φέροι, ἡ δὲ διὰ τῶν ὀρέων καὶ πρὸς ἄρκτον τετραμμένη ὅτι εἰς Καρδούχους ἄγοι.", "st": "3.5.15"}, {"sp": "N", "t": "τούτους δὲ ἔφασαν οἰκεῖν ἀνὰ τὰ ὄρη καὶ πολεμικοὺς εἶναι, καὶ βασιλέως οὐκ ἀκούειν, ἀλλὰ καὶ ἐμβαλεῖν ποτε εἰς αὐτοὺς βασιλικὴν στρατιὰν δώδεκα μυριάδας· τούτων δ᾽ οὐδέν᾽ ἀπονοστῆσαι διὰ τὴν δυσχωρίαν. ὁπότε μέντοι πρὸς τὸν σατράπην τὸν ἐν τῶι πεδίωι σπείσαιντο, καὶ ἐπιμιγνύναι σφῶν τε πρὸς ἐκείνους καὶ ἐκείνων πρὸς ἑαυτούς.", "st": "3.5.16"}, {"sp": "N", "t": "ἀκούσαντες ταῦτα οἱ στρατηγοὶ ἐκάθισαν χωρὶς τοὺς ἑκασταχόσε φάσκοντας εἰδέναι, οὐδὲν δῆλον ποιήσαντες ὅποι πορεύεσθαι ἔμελλον. ἐδόκει δὲ τοῖς στρατηγοῖς ἀναγκαῖον εἶναι διὰ τῶν ὀρέων εἰς Καρδούχους ἐμβαλεῖν· τούτους γὰρ διελθόντας ἔφασαν εἰς Ἀρμενίαν ἥξειν, ἧς Ὀρόντας ἦρχε πολλῆς καὶ εὐδαίμονος. ἐντεῦθεν δ᾽ εὔπορον ἔφασαν εἶναι ὅποι τις ἐθέλοι πορεύεσθαι.", "st": "3.5.17"}, {"sp": "N", "t": "ἐπὶ τούτοις ἐθύσαντο, ὅπως ἡνίκα καὶ δοκοίη τῆς ὥρας τὴν πορείαν ποιοῖντο· τὴν γὰρ ὑπερβολὴν τῶν ὀρέων ἐδεδοίκεσαν μὴ προκαταληφθείη· καὶ παρήγγειλαν, ἐπειδὴ δειπνήσαιεν, συσκευασαμένους πάντας ἀναπαύεσθαι, καὶ ἕπεσθαι ἡνίκ᾽ ἄν τις παραγγέλληι.", "st": "3.5.18"}, {"sp": "HDR", "t": "Βιβλίον δʹ", "st": "4.1.1"}, {"sp": "N", "t": "[ Ὅσα μὲν δὴ ἐν τῆι ἀναβάσει ἐγένετο μέχρι τῆς μάχης, καὶ ὅσα μετὰ τὴν μάχην ἐν ταῖς σπονδαῖς ἃς βασιλεὺς καὶ οἱ σὺν Κύρωι ἀναβάντες Ἕλληνες ἐποιήσαντο, καὶ ὅσα παραβάντος τὰς σπονδὰς βασιλέως καὶ Τισσαφέρνους ἐπολεμήθη πρὸς τοὺς Ἕλληνας ἐπακολουθοῦντος τοῦ Περσικοῦ στρατεύματος, ἐν τῶι πρόσθεν λόγωι δεδήλωται.", "st": "4.1.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ἀφίκοντο ἔνθα ὁ μὲν Τίγρης ποταμὸς παντάπασιν ἄπορος ἦν διὰ τὸ βάθος καὶ μέγεθος, πάροδος δὲ οὐκ ἦν, ἀλλὰ τὰ Καρδούχεια ὄρη ἀπότομα ὑπὲρ αὐτοῦ τοῦ ποταμοῦ ἐκρέματο, ἐδόκει δὴ τοῖς στρατηγοῖς διὰ τῶν ὀρέων πορευτέον εἶναι.", "st": "4.1.2"}, {"sp": "N", "t": "ἤκουον γὰρ τῶν ἁλισκομένων ὅτι εἰ διέλθοιεν τὰ Καρδούχεια ὄρη, ἐν τῆι Ἀρμενίαι τὰς πηγὰς τοῦ Τίγρητος ποταμοῦ, ἢν μὲν βούλωνται, διαβήσονται, ἢν δὲ μὴ βούλωνται, περιίασι. καὶ τοῦ Εὐφράτου δὲ τὰς πηγὰς ἐλέγετο οὐ πρόσω τοῦ Τίγρητος εἶναι, καὶ ἔστιν οὕτως ἔχον.", "st": "4.1.3"}, {"sp": "N", "t": "τὴν δ᾽ εἰς τοὺς Καρδούχους ἐμβολὴν ὧδε ποιοῦνται, ἅμα μὲν λαθεῖν πειρώμενοι, ἅμα δὲ φθάσαι πρὶν τοὺς πολεμίους καταλαβεῖν τὰ ἄκρα.]", "st": "4.1.4"}, {"sp": "N", "t": "Ἡνίκα δ᾽ ἦν ἀμφὶ τὴν τελευταίαν φυλακὴν καὶ ἐλείπετο τῆς νυκτὸς ὅσον σκοταίους διελθεῖν τὸ πεδίον, τηνικαῦτα ἀναστάντες ἀπὸ παραγγέλσεως πορευόμενοι ἀφικνοῦνται ἅμα τῆι ἡμέραι πρὸς τὸ ὄρος.", "st": "4.1.5"}, {"sp": "N", "t": "ἔνθα δὴ Χειρίσοφος μὲν ἡγεῖτο τοῦ στρατεύματος λαβὼν τὸ ἀμφ᾽ αὑτὸν καὶ τοὺς γυμνῆτας πάντας, Ξενοφῶν δὲ σὺν τοῖς ὀπισθοφύλαξιν ὁπλίταις εἵπετο οὐδένα ἔχων γυμνῆτα· οὐδεὶς γὰρ κίνδυνος ἐδόκει εἶναι μή τις ἄνω πορευομένων ἐκ τοῦ ὄπισθεν ἐπίσποιτο.", "st": "4.1.6"}, {"sp": "N", "t": "καὶ ἐπὶ μὲν τὸ ἄκρον ἀναβαίνει Χειρίσοφος πρίν τινας αἰσθέσθαι τῶν πολεμίων· ἔπειτα δ᾽ ὑφηγεῖτο· ἐφείπετο δὲ ἀεὶ τὸ ὑπερβάλλον τοῦ στρατεύματος εἰς τὰς κώμας τὰς ἐν τοῖς ἄγκεσί τε καὶ μυχοῖς τῶν ὀρέων.", "st": "4.1.7"}, {"sp": "N", "t": "ἔνθα δὴ οἱ μὲν Καρδοῦχοι ἐκλιπόντες τὰς οἰκίας ἔχοντες καὶ γυναῖκας καὶ παῖδας ἔφευγον ἐπὶ τὰ ὄρη. τὰ δὲ ἐπιτήδεια πολλὰ ἦν λαμβάνειν, ἦσαν δὲ καὶ χαλκώμασι παμπόλλοις κατεσκευασμέναι αἱ οἰκίαι, ὧν οὐδὲν ἔφερον οἱ Ἕλληνες, οὐδὲ τοὺς ἀνθρώπους ἐδίωκον, ὑποφειδόμενοι, εἴ πως ἐθελήσειαν οἱ Καρδοῦχοι διιέναι αὐτοὺς ὡς διὰ φιλίας τῆς χώρας, ἐπείπερ βασιλεῖ πολέμιοι ἦσαν·", "st": "4.1.8"}, {"sp": "N", "t": "τὰ μέντοι ἐπιτήδεια ὅτωι τις ἐπιτυγχάνοι ἐλάμβανεν· ἀνάγκη γὰρ ἦν. οἱ δὲ Καρδοῦχοι οὔτε καλούντων ὑπήκουον οὔτε ἄλλο φιλικὸν οὐδὲν ἐποίουν.", "st": "4.1.9"}, {"sp": "N", "t": "ἐπεὶ δὲ οἱ τελευταῖοι τῶν Ἑλλήνων κατέβαινον εἰς τὰς κώμας ἀπὸ τοῦ ἄκρου ἤδη σκοταῖοι (διὰ γὰρ τὸ στενὴν εἶναι τὴν ὁδὸν ὅλην τὴν ἡμέραν ἡ ἀνάβασις αὐτοῖς ἐγένετο καὶ κατάβασις), τότε δὴ συλλεγέντες τινὲς τῶν Καρδούχων τοῖς τελευταίοις ἐπετίθεντο, καὶ ἀπέκτεινάν τινας καὶ λίθοις καὶ τοξεύμασι κατέτρωσαν, ὀλίγοι ὄντες· ἐξ ἀπροσδοκήτου γὰρ αὐτοῖς ἐπέπεσε τὸ Ἑλληνικόν.", "st": "4.1.10"}, {"sp": "N", "t": "εἰ μέντοι τότε πλείους συνελέγησαν, ἐκινδύνευσεν ἂν διαφθαρῆναι πολὺ τοῦ στρατεύματος. καὶ ταύτην μὲν τὴν νύκτα οὕτως ἐν ταῖς κώμαις ηὐλίσθησαν· οἱ δὲ Καρδοῦχοι πυρὰ πολλὰ ἔκαιον κύκλωι ἐπὶ τῶν ὀρέων καὶ συνεώρων ἀλλήλους.", "st": "4.1.11"}, {"sp": "N", "t": "ἅμα δὲ τῆι ἡμέραι συνελθοῦσι τοῖς στρατηγοῖς καὶ λοχαγοῖς τῶν Ἑλλήνων ἔδοξε τῶν τε ὑποζυγίων τὰ ἀναγκαῖα καὶ δυνατώτατα ἔχοντας πορεύεσθαι, καταλιπόντας τἆλλα, καὶ ὅσα ἦν νεωστὶ αἰχμάλωτα ἀνδράποδα ἐν τῆι στρατιᾶι πάντα ἀφεῖναι.", "st": "4.1.12"}, {"sp": "N", "t": "σχολαίαν γὰρ ἐποίουν τὴν πορείαν πολλὰ ὄντα τὰ ὑποζύγια καὶ τὰ αἰχμάλωτα, πολλοὶ δὲ οἱ ἐπὶ τούτοις ὄντες ἀπόμαχοι ἦσαν, διπλάσιά τε ἐπιτήδεια ἔδει πορίζεσθαι καὶ φέρεσθαι πολλῶν τῶν ἀνθρώπων ὄντων. δόξαν δὲ ταῦτα ἐκήρυξαν οὕτω ποιεῖν.", "st": "4.1.13"}, {"sp": "N", "t": "ἐπεὶ δὲ ἀριστήσαντες ἐπορεύοντο, ὑποστήσαντες ἐν τῶι στενῶι οἱ στρατηγοί, εἴ τι εὑρίσκοιεν τῶν εἰρημένων μὴ ἀφειμένον, ἀφηιροῦντο, οἱ δ᾽ ἐπείθοντο, πλὴν εἴ τις ἔκλεψεν, οἷον ἢ παιδὸς ἐπιθυμήσας ἢ γυναικὸς τῶν εὐπρεπῶν. καὶ ταύτην μὲν τὴν ἡμέραν οὕτως ἐπορεύθησαν, τὰ μέν τι μαχόμενοι τὰ δὲ καὶ ἀναπαυόμενοι.", "st": "4.1.14"}, {"sp": "N", "t": "εἰς δὲ τὴν ὑστεραίαν γίγνεται χειμὼν πολύς, ἀναγκαῖον δ᾽ ἦν πορεύεσθαι· οὐ γὰρ ἦν ἱκανὰ τἀπιτήδεια. καὶ ἡγεῖτο μὲν Χειρίσοφος, ὠπισθοφυλάκει δὲ Ξενοφῶν.", "st": "4.1.15"}, {"sp": "N", "t": "καὶ οἱ πολέμιοι ἰσχυρῶς ἐπετίθεντο, καὶ στενῶν ὄντων τῶν χωρίων ἐγγὺς προσιόντες ἐτόξευον καὶ ἐσφενδόνων· ὥστε ἠναγκάζοντο οἱ Ἕλληνες ἐπιδιώκοντες καὶ πάλιν ἀναχάζοντες σχολῆι πορεύεσθαι· καὶ θαμινὰ παρήγγελλεν ὁ Ξενοφῶν ὑπομένειν, ὅτε οἱ πολέμιοι ἰσχυρῶς ἐπικέοιντο.", "st": "4.1.16"}, {"sp": "N", "t": "ἐνταῦθα ὁ Χειρίσοφος ἄλλοτε μὲν ὅτε παρεγγυῶιτο ὑπέμενε, τότε δὲ οὐχ ὑπέμενεν, ἀλλ᾽ ἦγε ταχέως καὶ παρηγγύα ἕπεσθαι, ὥστε δῆλον ἦν ὅτι πρᾶγμά τι εἴη· σχολὴ δ᾽ οὐκ ἦν ἰδεῖν παρελθόντι τὸ αἴτιον τῆς σπουδῆς· ὥστε ἡ πορεία ὁμοία φυγῆι ἐγίγνετο τοῖς ὀπισθοφύλαξι.", "st": "4.1.17"}, {"sp": "N", "t": "καὶ ἐνταῦθα ἀποθνήισκει ἀνὴρ ἀγαθὸς Λακωνικὸς Λεώνυμος τοξευθεὶς διὰ τῆς ἀσπίδος καὶ τῆς σπολάδος εἰς τὰς πλευράς, καὶ Βασίας Ἀρκὰς διαμπερὲς τὴν κεφαλήν.", "st": "4.1.18"}, {"sp": "N", "t": "ἐπεὶ δὲ ἀφίκοντο ἐπὶ σταθμόν, εὐθὺς ὥσπερ εἶχεν ὁ Ξενοφῶν ἐλθὼν πρὸς τὸν Χειρίσοφον ἠιτιᾶτο αὐτὸν ὅτι οὐχ ὑπέμενεν, ἀλλ᾽ ἠναγκάζοντο φεύγοντες ἅμα μάχεσθαι. «καὶ νῦν δύο καλώ τε καὶ ἀγαθὼ ἄνδρε τέθνατον καὶ οὔτε ἀνελέσθαι οὔτε θάψαι ἐδυνάμεθα.»", "st": "4.1.19"}, {"sp": "N", "t": "ἀποκρίνεται ὁ Χειρίσοφος· «βλέψον, ἔφη, πρὸς τὰ ὄρη καὶ ἰδὲ ὡς ἄβατα πάντα ἐστί· μία δ᾽ αὕτη ὁδὸς ἣν ὁρᾶις ὀρθία, καὶ ἐπὶ ταύτηι ἀνθρώπων ὁρᾶν ἔξεστί σοι ὄχλον τοσοῦτον, οἳ κατειληφότες φυλάττουσι τὴν ἔκβασιν.", "st": "4.1.20"}, {"sp": "N", "t": "ταῦτ᾽ ἐγὼ ἔσπευδον καὶ διὰ τοῦτό σε οὐχ ὑπέμενον, εἴ πως δυναίμην φθάσαι πρὶν κατειλῆφθαι τὴν ὑπερβολήν· οἱ δ᾽ ἡγεμόνες οὓς ἔχομεν οὔ φασιν εἶναι ἄλλην ὁδόν.»", "st": "4.1.21"}, {"sp": "N", "t": "ὁ δὲ Ξενοφῶν λέγει· «ἀλλ᾽ ἐγὼ ἔχω δύο ἄνδρας. ἐπεὶ γὰρ ἡμῖν πράγματα παρεῖχον, ἐνηδρεύσαμεν, ὅπερ ἡμᾶς καὶ ἀναπνεῦσαι ἐποίησε, καὶ ἀπεκτείναμέν τινας αὐτῶν, καὶ ζῶντας προυθυμήθημεν λαβεῖν αὐτοῦ τούτου ἕνεκα ὅπως ἡγεμόσιν εἰδόσι τὴν χώραν χρησαίμεθα.»", "st": "4.1.22"}, {"sp": "N", "t": "καὶ εὐθὺς ἀγαγόντες τοὺς ἀνθρώπους ἤλεγχον διαλαβόντες εἴ τινα εἰδεῖεν ἄλλην ὁδὸν ἢ τὴν φανεράν. ὁ μὲν οὖν ἕτερος οὐκ ἔφη μάλα πολλῶν φόβων προσαγομένων· ἐπεὶ δὲ οὐδὲν ὠφέλιμον ἔλεγεν, ὁρῶντος τοῦ ἑτέρου κατεσφάγη.", "st": "4.1.23"}, {"sp": "N", "t": "ὁ δὲ λοιπὸς ἔλεξεν ὅτι οὗτος μὲν οὐ φαίη διὰ ταῦτα εἰδέναι, ὅτι αὐτῶι ἐτύγχανε θυγάτηρ ἐκεῖ παρ᾽ ἀνδρὶ ἐκδεδομένη· αὐτὸς δ᾽ ἔφη ἡγήσεσθαι δυνατὴν καὶ ὑποζυγίοις πορεύεσθαι ὁδόν.", "st": "4.1.24"}, {"sp": "N", "t": "ἐρωτώμενος δ᾽ εἰ εἴη τι ἐν αὐτῆι δυσπάριτον χωρίον, ἔφη εἶναι ἄκρον ὃ εἰ μή τις προκαταλήψοιτο, ἀδύνατον ἔσεσθαι παρελθεῖν.", "st": "4.1.25"}, {"sp": "N", "t": "ἐνταῦθα δ᾽ ἐδόκει συγκαλέσαντας λοχαγοὺς καὶ πελταστὰς καὶ τῶν ὁπλιτῶν λέγειν τε τὰ παρόντα καὶ ἐρωτᾶν εἴ τις αὐτῶν ἔστιν ὅστις ἀνὴρ ἀγαθὸς ἐθέλοι ἂν γενέσθαι καὶ ὑποστὰς ἐθελοντὴς πορεύεσθαι.", "st": "4.1.26"}, {"sp": "N", "t": "ὑφίσταται τῶν μὲν ὁπλιτῶν Ἀριστώνυμος Μεθυδριεὺς [Ἀρκὰς] καὶ Ἀγασίας Στυμφάλιος [Ἀρκάς], ἀντιστασιάζων δὲ αὐτοῖς Καλλίμαχος Παρράσιος [Ἀρκὰς καὶ οὗτος] ἔφη ἐθέλειν πορεύεσθαι προσλαβὼν ἐθελοντὰς ἐκ παντὸς τοῦ στρατεύματος· ἐγὼ γάρ, ἔφη, οἶδα ὅτι ἕψονται πολλοὶ τῶν νέων ἐμοῦ ἡγουμένου.", "st": "4.1.27"}, {"sp": "N", "t": "ἐκ τούτου ἐρωτῶσιν εἴ τις καὶ τῶν γυμνήτων ταξιάρχων ἐθέλοι συμπορεύεσθαι. ὑφίσταται Ἀριστέας Χῖος, ὃς πολλαχοῦ πολλοῦ ἄξιος τῆι στρατιᾶι εἰς τὰ τοιαῦτα ἐγένετο.", "st": "4.1.28"}, {"sp": "N", "t": "καὶ ἦν μὲν δείλη, οἱ δ᾽ ἐκέλευον αὐτοὺς ἐμφαγόντας πορεύεσθαι. καὶ τὸν ἡγεμόνα δήσαντες παραδιδόασιν αὐτοῖς, καὶ συντίθενται τὴν μὲν νύκτα, ἢν λάβωσι τὸ ἄκρον, τὸ χωρίον φυλάττειν, ἅμα δὲ τῆι ἡμέραι τῆι σάλπιγγι σημαίνειν· καὶ τοὺς μὲν ἄνω ὄντας ἰέναι ἐπὶ τοὺς κατέχοντας τὴν φανερὰν ἔκβασιν, αὐτοὶ δὲ συμβοηθήσειν ἐκβαίνοντες ὡς ἂν δύνωνται τάχιστα.", "st": "4.2.1"}, {"sp": "N", "t": "ταῦτα συνθέμενοι οἱ μὲν ἐπορεύοντο πλῆθος ὡς δισχίλιοι· καὶ ὕδωρ πολὺ ἦν ἐξ οὐρανοῦ· Ξενοφῶν δὲ ἔχων τοὺς ὀπισθοφύλακας ἡγεῖτο πρὸς τὴν φανερὰν ἔκβασιν, ὅπως ταύτηι τῆι ὁδῶι οἱ πολέμιοι προσέχοιεν τὸν νοῦν καὶ ὡς μάλιστα λάθοιεν οἱ περιιόντες.", "st": "4.2.2"}, {"sp": "N", "t": "ἐπεὶ δὲ ἦσαν ἐπὶ χαράδραι οἱ ὀπισθοφύλακες ἣν ἔδει διαβάντας πρὸς τὸ ὄρθιον ἐκβαίνειν, τηνικαῦτα ἐκύλινδον οἱ βάρβαροι ὁλοιτρόχους ἁμαξιαίους καὶ μείζους καὶ ἐλάττους, οἳ φερόμενοι πρὸς τὰς πέτρας παίοντες διεσφενδονῶντο· καὶ παντάπασιν οὐδὲ πελάσαι οἷόν τ᾽ ἦν τῆι εἰσόδωι.", "st": "4.2.3"}, {"sp": "N", "t": "ἔνιοι δὲ τῶν λοχαγῶν, εἰ μὴ ταύτηι δύναιντο, ἄλληι ἐπειρῶντο· καὶ ταῦτα ἐποίουν μέχρι σκότος ἐγένετο· ἐπεὶ δὲ ὤιοντο ἀφανεῖς εἶναι ἀπιόντες, τότε ἀπῆλθον ἐπὶ τὸ δεῖπνον· ἐτύγχανον δὲ καὶ ἀνάριστοι ὄντες αὐτῶν οἱ ὀπισθοφυλακήσαντες. οἱ μέντοι πολέμιοι οὐδὲν ἐπαύσαντο δι᾽ ὅλης τῆς νυκτὸς κυλίνδοντες τοὺς λίθους· τεκμαίρεσθαι δ᾽ ἦν τῶι ψόφωι.", "st": "4.2.4"}, {"sp": "N", "t": "οἱ δ᾽ ἔχοντες τὸν ἡγεμόνα κύκλωι περιιόντες καταλαμβάνουσι τοὺς φύλακας ἀμφὶ πῦρ καθημένους· καὶ τοὺς μὲν κατακαίνοντες τοὺς δὲ καταδιώξαντες αὐτοὶ ἐνταῦθ᾽ ἔμενον ὡς τὸ ἄκρον κατέχοντες.", "st": "4.2.5"}, {"sp": "N", "t": "οἱ δ᾽ οὐ κατεῖχον, ἀλλὰ μαστὸς ἦν ὑπὲρ αὐτῶν παρ᾽ ὃν ἦν ἡ στενὴ αὕτη ὁδὸς ἐφ᾽ ἧι ἐκάθηντο οἱ φύλακες. ἔφοδος μέντοι αὐτόθεν ἐπὶ τοὺς πολεμίους ἦν οἳ ἐπὶ τῆι φανερᾶι ὁδῶι ἐκάθηντο.", "st": "4.2.6"}, {"sp": "N", "t": "καὶ τὴν μὲν νύκτα ἐνταῦθα διήγαγον· ἐπεὶ δ᾽ ἡμέρα ὑπέφαινεν, ἐπορεύοντο σιγῆι συντεταγμένοι ἐπὶ τοὺς πολεμίους· καὶ γὰρ ὁμίχλη ἐγένετο, ὥστ᾽ ἔλαθον ἐγγὺς προσελθόντες. ἐπεὶ δὲ εἶδον ἀλλήλους, ἥ τε σάλπιγξ ἐφθέγξατο καὶ ἀλαλάξαντες ἵεντο ἐπὶ τοὺς ἀνθρώπους· οἱ δὲ οὐκ ἐδέξαντο, ἀλλὰ λιπόντες τὴν ὁδὸν φεύγοντες ὀλίγοι ἀπέθνηισκον· εὔζωνοι γὰρ ἦσαν.", "st": "4.2.7"}, {"sp": "N", "t": "οἱ δὲ ἀμφὶ Χειρίσοφον ἀκούσαντες τῆς σάλπιγγος εὐθὺς ἵεντο ἄνω κατὰ τὴν φανερὰν ὁδόν· ἄλλοι δὲ τῶν στρατηγῶν κατὰ ἀτριβεῖς ὁδοὺς ἐπορεύοντο ἧι ἔτυχον ἕκαστοι ὄντες, καὶ ἀναβάντες ὡς ἐδύναντο ἀνίμων ἀλλήλους τοῖς δόρασι.", "st": "4.2.8"}, {"sp": "N", "t": "καὶ οὗτοι πρῶτοι συνέμειξαν τοῖς προκαταλαβοῦσι τὸ χωρίον. Ξενοφῶν δὲ ἔχων τῶν ὀπισθοφυλάκων τοὺς ἡμίσεις ἐπορεύετο ἧιπερ οἱ τὸν ἡγεμόνα ἔχοντες· εὐοδωτάτη γὰρ ἦν τοῖς ὑποζυγίοις· τοὺς δὲ ἡμίσεις ὄπισθεν τῶν ὑποζυγίων ἔταξε.", "st": "4.2.9"}, {"sp": "N", "t": "πορευόμενοι δ᾽ ἐντυγχάνουσι λόφωι ὑπὲρ τῆς ὁδοῦ κατειλημμένωι ὑπὸ τῶν πολεμίων, οὓς ἢ ἀποκόψαι ἦν ἀνάγκη ἢ διεζεῦχθαι ἀπὸ τῶν ἄλλων Ἑλλήνων. καὶ αὐτοὶ μὲν ἂν ἐπορεύθησαν ἧιπερ οἱ ἄλλοι, τὰ δὲ ὑποζύγια οὐκ ἦν ἄλληι ἢ ταύτηι ἐκβῆναι.", "st": "4.2.10"}, {"sp": "N", "t": "ἔνθα δὴ παρακελευσάμενοι ἀλλήλοις προσβάλλουσι πρὸς τὸν λόφον ὀρθίοις τοῖς λόχοις, οὐ κύκλωι ἀλλὰ καταλιπόντες ἄφοδον τοῖς πολεμίοις, εἰ βούλοιντο φεύγειν.", "st": "4.2.11"}, {"sp": "N", "t": "καὶ τέως μὲν αὐτοὺς ἀναβαίνοντας ὅπηι ἐδύναντο ἕκαστος οἱ βάρβαροι ἐτόξευον καὶ ἔβαλλον, ἐγγὺς δ᾽ οὐ προσίεντο, ἀλλὰ φυγῆι λείπουσι τὸ χωρίον. καὶ τοῦτόν τε παρεληλύθεσαν οἱ Ἕλληνες καὶ ἕτερον ὁρῶσιν ἔμπροσθεν λόφον κατεχόμενον ἐπὶ τοῦτον αὖθις ἐδόκει πορεύεσθαι.", "st": "4.2.12"}, {"sp": "N", "t": "ἐννοήσας δ᾽ ὁ Ξενοφῶν μή, εἰ ἔρημον καταλίποι τὸν ἡλωκότα λόφον, [καὶ] πάλιν λαβόντες οἱ πολέμιοι ἐπιθοῖντο τοῖς ὑποζυγίοις παριοῦσιν (ἐπὶ πολὺ δ᾽ ἦν τὰ ὑποζύγια ἅτε διὰ στενῆς τῆς ὁδοῦ πορευόμενα), καταλείπει ἐπὶ τοῦ λόφου λοχαγοὺς Κηφισόδωρον Κηφισοφῶντος Ἀθηναῖον καὶ Ἀμφικράτην Ἀμφιδήμου Ἀθηναῖον καὶ Ἀρχαγόραν Ἀργεῖον φυγάδα, αὐτὸς δὲ σὺν τοῖς λοιποῖς ἐπορεύετο ἐπὶ τὸν δεύτερον λόφον, καὶ τῶι αὐτῶι τρόπωι καὶ τοῦτον αἱροῦσιν.", "st": "4.2.13"}, {"sp": "N", "t": "ἔτι δ᾽ αὐτοῖς τρίτος μαστὸς λοιπὸς ἦν πολὺ ὀρθιώτατος ὁ ὑπὲρ τῆς ἐπὶ τῶι πυρὶ καταληφθείσης φυλακῆς τῆς νυκτὸς ὑπὸ τῶν ἐθελοντῶν.", "st": "4.2.14"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἐγγὺς ἐγένοντο οἱ Ἕλληνες, λείπουσιν οἱ βάρβαροι ἀμαχητὶ τὸν μαστόν, ὥστε θαυμαστὸν πᾶσι γενέσθαι καὶ ὑπώπτευον δείσαντας αὐτοὺς μὴ κυκλωθέντες πολιορκοῖντο ἀπολιπεῖν. οἱ δ᾽ ἄρα ἀπὸ τοῦ ἄκρου καθορῶντες τὰ ὄπισθεν γιγνόμενα πάντες ἐπὶ τοὺς ὀπισθοφύλακας ἐχώρουν.", "st": "4.2.15"}, {"sp": "N", "t": "καὶ Ξενοφῶν μὲν σὺν τοῖς νεωτάτοις ἀνέβαινεν ἐπὶ τὸ ἄκρον, τοὺς δὲ ἄλλους ἐκέλευσεν ὑπάγειν, ὅπως οἱ τελευταῖοι λόχοι προσμείξειαν, καὶ προελθόντας κατὰ τὴν ὁδὸν ἐν τῶι ὁμαλῶι θέσθαι τὰ ὅπλα εἶπε.", "st": "4.2.16"}, {"sp": "N", "t": "καὶ ἐν τούτωι τῶι χρόνωι ἦλθεν Ἀρχαγόρας ὁ Ἀργεῖος πεφευγὼς καὶ λέγει ὡς ἀπεκόπησαν ἀπὸ τοῦ λόφου καὶ ὅτι τεθνᾶσι Κηφισόδωρος καὶ Ἀμφικράτης καὶ ἄλλοι ὅσοι μὴ ἁλόμενοι κατὰ τῆς πέτρας πρὸς τοὺς ὀπισθοφύλακας ἀφίκοντο.", "st": "4.2.17"}, {"sp": "N", "t": "ταῦτα δὲ διαπραξάμενοι οἱ βάρβαροι ἧκον ἐπ᾽ ἀντίπορον λόφον τῶι μαστῶι· καὶ ὁ Ξενοφῶν διελέγετο αὐτοῖς δι᾽ ἑρμηνέως περὶ σπονδῶν καὶ τοὺς νεκροὺς ἀπήιτει.", "st": "4.2.18"}, {"sp": "N", "t": "οἱ δὲ ἔφασαν ἀποδώσειν ἐφ᾽ ὧι μὴ καίειν τὰς οἰκίας. συνωμολόγει ταῦτα ὁ Ξενοφῶν. ἐν ὧι δὲ τὸ μὲν ἄλλο στράτευμα παρήιει, οἱ δὲ ταῦτα διελέγοντο, πάντες οἱ ἐκ τούτου τοῦ τόπου συνερρύησαν· ἐνταῦθα ἵσταντο οἱ πολέμιοι.", "st": "4.2.19"}, {"sp": "N", "t": "καὶ ἐπεὶ ἤρξαντο καταβαίνειν ἀπὸ τοῦ μαστοῦ πρὸς τοὺς ἄλλους ἔνθα τὰ ὅπλα ἔκειντο, ἵεντο δὴ οἱ πολέμιοι πολλῶι πλήθει καὶ θορύβωι· καὶ ἐπεὶ ἐγένοντο ἐπὶ τῆς κορυφῆς τοῦ μαστοῦ ἀφ᾽ οὗ Ξενοφῶν κατέβαινεν, ἐκυλίνδουν πέτρους· καὶ ἑνὸς μὲν κατέαξαν τὸ σκέλος, Ξενοφῶντα δὲ ὁ ὑπασπιστὴς ἔχων τὴν ἀσπίδα ἀπέλιπεν·", "st": "4.2.20"}, {"sp": "N", "t": "Εὐρύλοχος δὲ Λουσιεὺς [Ἀρκὰς] προσέδραμεν αὐτῶι ὁπλίτης, καὶ πρὸ ἀμφοῖν προβεβλημένος ἀπεχώρει, καὶ οἱ ἄλλοι πρὸς τοὺς συντεταγμένους ἀπῆλθον.", "st": "4.2.21"}, {"sp": "N", "t": "ἐκ δὲ τούτου πᾶν ὁμοῦ ἐγένετο τὸ Ἑλληνικόν, καὶ ἐσκήνησαν αὐτοῦ ἐν πολλαῖς καὶ καλαῖς οἰκίαις καὶ ἐπιτηδείοις δαψιλέσι· καὶ γὰρ οἶνος πολὺς ἦν, ὥστε ἐν λάκκοις κονιατοῖς εἶχον.", "st": "4.2.22"}, {"sp": "N", "t": "Ξενοφῶν δὲ καὶ Χειρίσοφος διεπράξαντο ὥστε λαβόντες τοὺς νεκροὺς ἀπέδοσαν τὸν ἡγεμόνα· καὶ πάντα ἐποίησαν τοῖς ἀποθανοῦσιν ἐκ τῶν δυνατῶν ὥσπερ νομίζεται ἀνδράσιν ἀγαθοῖς.", "st": "4.2.23"}, {"sp": "N", "t": "τῆι δὲ ὑστεραίαι ἄνευ ἡγεμόνος ἐπορεύοντο· μαχόμενοι δ᾽ οἱ πολέμιοι καὶ ὅπηι εἴη στενὸν χωρίον προκαταλαμβάνοντες ἐκώλυον τὰς παρόδους.", "st": "4.2.24"}, {"sp": "N", "t": "ὁπότε μὲν οὖν τοὺς πρώτους κωλύοιεν, Ξενοφῶν ὄπισθεν ἐκβαίνων πρὸς τὰ ὄρη ἔλυε τὴν ἀπόφραξιν τῆς ὁδοῦ τοῖς πρώτοις ἀνωτέρω πειρώμενος γίγνεσθαι τῶν κωλυόντων,", "st": "4.2.25"}, {"sp": "N", "t": "ὁπότε δὲ τοῖς ὄπισθεν ἐπιθοῖντο, Χειρίσοφος ἐκβαίνων καὶ πειρώμενος ἀνωτέρω γίγνεσθαι τῶν κωλυόντων ἔλυε τὴν ἀπόφραξιν τῆς παρόδου τοῖς ὄπισθεν· καὶ ἀεὶ οὕτως ἐβοήθουν ἀλλήλοις καὶ ἰσχυρῶς ἀλλήλων ἐπεμέλοντο.", "st": "4.2.26"}, {"sp": "N", "t": "ἦν δὲ καὶ ὁπότε αὐτοῖς τοῖς ἀναβᾶσι πολλὰ πράγματα παρεῖχον οἱ βάρβαροι πάλιν καταβαίνουσιν· ἐλαφροὶ γὰρ ἦσαν ὥστε καὶ ἐγγύθεν φεύγοντες ἀποφεύγειν· οὐδὲν γὰρ εἶχον ἄλλο ἢ τόξα καὶ σφενδόνας.", "st": "4.2.27"}, {"sp": "N", "t": "ἄριστοι δὲ καὶ τοξόται ἦσαν· εἶχον δὲ τόξα ἐγγὺς τριπήχη, τὰ δὲ τοξεύματα πλέον ἢ διπήχη· εἷλκον δὲ τὰς νευρὰς ὁπότε τοξεύοιεν πρὸς τὸ κάτω τοῦ τόξου τῶι ἀριστερῶι ποδὶ προσβαίνοντες. τὰ δὲ τοξεύματα ἐχώρει διὰ τῶν ἀσπίδων καὶ διὰ τῶν θωράκων. ἐχρῶντο δὲ αὐτοῖς οἱ Ἕλληνες, ἐπεὶ λάβοιεν, ἀκοντίοις ἐναγκυλῶντες. ἐν τούτοις τοῖς χωρίοις οἱ Κρῆτες χρησιμώτατοι ἐγένοντο. ἦρχε δὲ αὐτῶν Στρατοκλῆς Κρής.", "st": "4.2.28"}, {"sp": "N", "t": "ταύτην δ᾽ αὖ τὴν ἡμέραν ηὐλίσθησαν ἐν ταῖς κώμαις ταῖς ὑπὲρ τοῦ πεδίου παρὰ τὸν Κεντρίτην ποταμόν, εὖρος ὡς δίπλεθρον, ὃς ὁρίζει τὴν Ἀρμενίαν καὶ τὴν τῶν Καρδούχων χώραν. καὶ οἱ Ἕλληνες ἐνταῦθα ἀνέπνευσαν ἄσμενοι ἰδόντες πεδίον· ἀπεῖχε δὲ τῶν ὀρέων ὁ ποταμὸς ἓξ ἢ ἑπτὰ στάδια τῶν Καρδούχων.", "st": "4.3.1"}, {"sp": "N", "t": "τότε μὲν οὖν ηὐλίσθησαν μάλα ἡδέως καὶ τἀπιτήδεια ἔχοντες καὶ πολλὰ τῶν παρεληλυθότων πόνων μνημονεύοντες. ἑπτὰ γὰρ ἡμέρας ὅσασπερ ἐπορεύθησαν διὰ τῶν Καρδούχων πάσας μαχόμενοι διετέλεσαν, καὶ ἔπαθον κακὰ ὅσα οὐδὲ τὰ σύμπαντα ὑπὸ βασιλέως καὶ Τισσαφέρνους. ὡς οὖν ἀπηλλαγμένοι τούτων ἡδέως ἐκοιμήθησαν.", "st": "4.3.2"}, {"sp": "N", "t": "ἅμα δὲ τῆι ἡμέραι ὁρῶσιν ἱππέας που πέραν τοῦ ποταμοῦ ἐξωπλισμένους ὡς κωλύσοντας διαβαίνειν, πεζοὺς δ᾽ ἐπὶ ταῖς ὄχθαις παρατεταγμένους ἄνω τῶν ἱππέων ὡς κωλύσοντας εἰς τὴν Ἀρμενίαν ἐκβαίνειν.", "st": "4.3.3"}, {"sp": "N", "t": "ἦσαν δ᾽ οὗτοι Ὀρόντα καὶ Ἀρτούχα Ἀρμένιοι καὶ Μάρδοι καὶ Χαλδαῖοι μισθοφόροι. ἐλέγοντο δὲ οἱ Χαλδαῖοι ἐλεύθεροί τε καὶ ἄλκιμοι εἶναι· ὅπλα δ᾽ εἶχον γέρρα μακρὰ καὶ λόγχας.", "st": "4.3.4"}, {"sp": "N", "t": "αἱ δὲ ὄχθαι αὗται ἐφ᾽ ὧν παρατεταγμένοι οὗτοι ἦσαν τρία ἢ τέτταρα πλέθρα ἀπὸ τοῦ ποταμοῦ ἀπεῖχον· ὁδὸς δὲ μία ὁρωμένη ἦν ἄγουσα ἄνω ὥσπερ χειροποίητος· ταύτηι ἐπειρῶντο διαβαίνειν οἱ Ἕλληνες.", "st": "4.3.5"}, {"sp": "N", "t": "ἐπεὶ δὲ πειρωμένοις τό τε ὕδωρ ὑπὲρ τῶν μαστῶν ἐφαίνετο, καὶ τραχὺς ἦν ὁ ποταμὸς μεγάλοις λίθοις καὶ ὀλισθηροῖς, καὶ οὔτ᾽ ἐν τῶι ὕδατι τὰ ὅπλα ἦν ἔχειν· εἰ δὲ μή, ἥρπαζεν ὁ ποταμός· ἐπί τε τῆς κεφαλῆς τὰ ὅπλα εἴ τις φέροι, γυμνοὶ ἐγίγνοντο πρὸς τὰ τοξεύματα καὶ τἆλλα βέλη, ἀνεχώρησαν καὶ αὐτοῦ ἐστρατοπεδεύσαντο παρὰ τὸν ποταμόν.", "st": "4.3.6"}, {"sp": "N", "t": "ἔνθα δὲ αὐτοὶ τὴν πρόσθεν νύκτα ἦσαν ἐπὶ τοῦ ὄρους ἑώρων τοὺς Καρδούχους πολλοὺς συνειλεγμένους ἐν τοῖς ὅπλοις. ἐνταῦθα δὴ πολλὴ ἀθυμία ἦν τοῖς Ἕλλησιν, ὁρῶσι μὲν τοῦ ποταμοῦ τὴν δυσπορίαν, ὁρῶσι δὲ τοὺς διαβαίνειν κωλύσοντας, ὁρῶσι δὲ τοῖς διαβαίνουσιν ἐπικεισομένους τοὺς Καρδούχους ὄπισθεν.", "st": "4.3.7"}, {"sp": "N", "t": "ταύτην μὲν οὖν τὴν ἡμέραν καὶ νύκτα ἔμειναν ἐν πολλῆι ἀπορίαι ὄντες. Ξενοφῶν δὲ ὄναρ εἶδεν· ἔδοξεν ἐν πέδαις δεδέσθαι, αὗται δὲ αὐτῶι αὐτόμαται περιρρυῆναι, ὥστε λυθῆναι καὶ διαβαίνειν ὁπόσον ἐβούλετο. ἐπεὶ δὲ ὄρθρος ἦν, ἔρχεται πρὸς τὸν Χειρίσοφον καὶ λέγει ὅτι ἐλπίδας ἔχει καλῶς ἔσεσθαι, καὶ διηγεῖται αὐτῶι τὸ ὄναρ.", "st": "4.3.8"}, {"sp": "N", "t": "ὁ δὲ ἥδετό τε καὶ ὡς τάχιστα ἕως ὑπέφαινεν ἐθύοντο πάντες παρόντες οἱ στρατηγοί· καὶ τὰ ἱερὰ καλὰ ἦν εὐθὺς ἐπὶ τοῦ πρώτου. καὶ ἀπιόντες ἀπὸ τῶν ἱερῶν οἱ στρατηγοὶ καὶ λοχαγοὶ παρήγγελλον τῆι στρατιᾶι ἀριστοποιεῖσθαι.", "st": "4.3.9"}, {"sp": "N", "t": "καὶ ἀριστῶντι τῶι Ξενοφῶντι προσέτρεχον δύο νεανίσκω· ἤιδεσαν γὰρ πάντες ὅτι ἐξείη αὐτῶι καὶ ἀριστῶντι καὶ δειπνοῦντι προσελθεῖν καὶ εἰ καθεύδοι ἐπεγείραντα εἰπεῖν, εἴ τίς τι ἔχοι τῶν πρὸς τὸν πόλεμον.", "st": "4.3.10"}, {"sp": "N", "t": "καὶ τότε ἔλεγον ὅτι τυγχάνοιεν φρύγανα συλλέγοντες ὡς ἐπὶ πῦρ, κἄπειτα κατίδοιεν ἐν τῶι πέραν ἐν πέτραις καθηκούσαις ἐπ᾽ αὐτὸν τὸν ποταμὸν γέροντά τε καὶ γυναῖκα καὶ παιδίσκας ὥσπερ μαρσίπους ἱματίων κατατιθεμένους ἐν πέτραι ἀντρώδει.", "st": "4.3.11"}, {"sp": "N", "t": "ἰδοῦσι δὲ σφίσι δόξαι ἀσφαλὲς εἶναι διαβῆναι· οὐδὲ γὰρ τοῖς πολεμίοις ἱππεῦσι προσβατὸν εἶναι κατὰ τοῦτο. ἐκδύντες δ᾽ ἔφασαν ἔχοντες τὰ ἐγχειρίδια γυμνοὶ ὡς νευσόμενοι διαβαίνειν· πορευόμενοι δὲ πρόσθεν διαβῆναι πρὶν βρέξαι τὰ αἰδοῖα·", "st": "4.3.12"}, {"sp": "N", "t": "καὶ διαβάντες, λαβόντες τὰ ἱμάτια πάλιν ἥκειν. εὐθὺς οὖν Ξενοφῶν αὐτός τε ἔσπενδε καὶ τοῖς νεανίσκοις ἐγχεῖν ἐκέλευε καὶ εὔχεσθαι τοῖς φήνασι θεοῖς τά τε ὀνείρατα καὶ τὸν πόρον καὶ τὰ λοιπὰ ἀγαθὰ ἐπιτελέσαι. σπείσας δ᾽ εὐθὺς ἦγε τοὺς νεανίσκους παρὰ τὸν Χειρίσοφον, καὶ διηγοῦνται ταὐτά.", "st": "4.3.13"}, {"sp": "N", "t": "ἀκούσας δὲ καὶ ὁ Χειρίσοφος σπονδὰς ἐποίει. σπείσαντες δὲ τοῖς μὲν ἄλλοις παρήγγελλον συσκευάζεσθαι, αὐτοὶ δὲ συγκαλέσαντες τοὺς στρατηγοὺς ἐβουλεύοντο ὅπως ἂν κάλλιστα διαβαῖεν καὶ τούς τε ἔμπροσθεν νικῶιεν καὶ ὑπὸ τῶν ὄπισθεν μηδὲν πάσχοιεν κακόν.", "st": "4.3.14"}, {"sp": "N", "t": "καὶ ἔδοξεν αὐτοῖς Χειρίσοφον μὲν ἡγεῖσθαι καὶ διαβαίνειν ἔχοντα τὸ ἥμισυ τοῦ στρατεύματος, τὸ δ᾽ ἥμισυ ἔτι ὑπομένειν σὺν Ξενοφῶντι, τὰ δὲ ὑποζύγια καὶ τὸν ὄχλον ἐν μέσωι τούτων διαβαίνειν.", "st": "4.3.15"}, {"sp": "N", "t": "ἐπεὶ δὲ ταῦτα καλῶς εἶχεν ἐπορεύοντο· ἡγοῦντο δ᾽ οἱ νεανίσκοι ἐν ἀριστερᾶι ἔχοντες τὸν ποταμόν· ὁδὸς δὲ ἦν ἐπὶ τὴν διάβασιν ὡς τέτταρες στάδιοι.", "st": "4.3.16"}, {"sp": "N", "t": "πορευομένων δ᾽ αὐτῶν ἀντιπαρῆισαν αἱ τάξεις τῶν ἱππέων. ἐπειδὴ δὲ ἦσαν κατὰ τὴν διάβασιν καὶ τὰς ὄχθας τοῦ ποταμοῦ, ἔθεντο τὰ ὅπλα, καὶ αὐτὸς πρῶτος Χειρίσοφος στεφανωσάμενος καὶ ἀποδὺς ἐλάμβανε τὰ ὅπλα καὶ τοῖς ἄλλοις πᾶσι παρήγγελλε, καὶ τοὺς λοχαγοὺς ἐκέλευεν ἄγειν τοὺς λόχους ὀρθίους, τοὺς μὲν ἐν ἀριστερᾶι τοὺς δ᾽ ἐν δεξιᾶι ἑαυτοῦ. καὶ οἱ μὲν μάντεις ἐσφαγιάζοντο εἰς τὸν ποταμόν·", "st": "4.3.17"}, {"sp": "N", "t": "οἱ δὲ πολέμιοι ἐτόξευον καὶ ἐσφενδόνων·", "st": "4.3.18"}, {"sp": "N", "t": "ἀλλ᾽ οὔπω ἐξικνοῦντο· ἐπεὶ δὲ καλὰ ἦν τὰ σφάγια, ἐπαιάνιζον πάντες οἱ στρατιῶται καὶ ἀνηλάλαζον, συνωλόλυζον δὲ καὶ αἱ γυναῖκες ἅπασαι. πολλαὶ γὰρ ἦσαν ἑταῖραι ἐν τῶι στρατεύματι.", "st": "4.3.19"}, {"sp": "N", "t": "καὶ Χειρίσοφος μὲν ἐνέβαινε καὶ οἱ σὺν ἐκείνωι· ὁ δὲ Ξενοφῶν τῶν ὀπισθοφυλάκων λαβὼν τοὺς εὐζωνοτάτους ἔθει ἀνὰ κράτος πάλιν ἐπὶ τὸν πόρον τὸν κατὰ τὴν ἔκβασιν τὴν εἰς τὰ τῶν Ἀρμενίων ὄρη, προσποιούμενος ταύτηι διαβὰς ἀποκλείσειν τοὺς παρὰ τὸν ποταμὸν ἱππέας.", "st": "4.3.20"}, {"sp": "N", "t": "οἱ δὲ πολέμιοι ὁρῶντες μὲν τοὺς ἀμφὶ Χειρίσοφον εὐπετῶς τὸ ὕδωρ περῶντας, ὁρῶντες δὲ τοὺς ἀμφὶ Ξενοφῶντα θέοντας εἰς τοὔμπαλιν, δείσαντες μὴ ἀποληφθείησαν φεύγουσιν ἀνὰ κράτος ὡς πρὸς τὴν τοῦ ποταμοῦ ἄνω ἔκβασιν. ἐπεὶ δὲ κατὰ τὴν ὁδὸν ἐγένοντο, ἔτεινον ἄνω πρὸς τὸ ὄρος.", "st": "4.3.21"}, {"sp": "N", "t": "Λύκιος δ᾽ ὁ τὴν τάξιν ἔχων τῶν ἱππέων καὶ Αἰσχίνης ὁ τὴν τάξιν τῶν πελταστῶν τῶν ἀμφὶ Χειρίσοφον ἐπεὶ ἑώρων ἀνὰ κράτος φεύγοντας, εἵποντο· οἱ δὲ στρατιῶται ἐβόων μὴ ἀπολείπεσθαι, ἀλλὰ συνεκβαίνειν ἐπὶ τὸ ὄρος.", "st": "4.3.22"}, {"sp": "N", "t": "Χειρίσοφος δ᾽ αὖ ἐπεὶ διέβη, τοὺς ἱππέας οὐκ ἐδίωκεν, εὐθὺς δὲ κατὰ τὰς προσηκούσας ὄχθας ἐπὶ τὸν ποταμὸν ἐξέβαινεν ἐπὶ τοὺς ἄνω πολεμίους. οἱ δὲ ἄνω, ὁρῶντες μὲν τοὺς ἑαυτῶν ἱππέας φεύγοντας, ὁρῶντες δ᾽ ὁπλίτας σφίσιν ἐπιόντας, ἐκλείπουσι τὰ ὑπὲρ τοῦ ποταμοῦ ἄκρα.", "st": "4.3.23"}, {"sp": "N", "t": "Ξενοφῶν δ᾽ ἐπεὶ τὰ πέραν ἑώρα καλῶς γιγνόμενα, ἀπεχώρει τὴν ταχίστην πρὸς τὸ διαβαῖνον στράτευμα· καὶ γὰρ οἱ Καρδοῦχοι φανεροὶ ἤδη ἦσαν εἰς τὸ πεδίον καταβαίνοντες ὡς ἐπιθησόμενοι τοῖς τελευταίοις.", "st": "4.3.24"}, {"sp": "N", "t": "καὶ Χειρίσοφος μὲν τὰ ἄνω κατεῖχε, Λύκιος δὲ σὺν ὀλίγοις ἐπιχειρήσας ἐπιδιῶξαι ἔλαβε τῶν σκευοφόρων τὰ ὑπολειπόμενα καὶ μετὰ τούτων ἐσθῆτά τε καλὴν καὶ ἐκπώματα.", "st": "4.3.25"}, {"sp": "N", "t": "καὶ τὰ σκευοφόρα τῶν Ἑλλήνων καὶ ὁ ὄχλος ἀκμὴν διέβαινε, Ξενοφῶν δὲ στρέψας πρὸς τοὺς Καρδούχους ἀντία τὰ ὅπλα ἔθετο, καὶ παρήγγειλε τοῖς λοχαγοῖς κατ᾽ ἐνωμοτίας ποιήσασθαι ἕκαστον τὸν ἑαυτοῦ λόχον, παρ᾽ ἀσπίδα παραγαγόντας τὴν ἐνωμοτίαν ἐπὶ φάλαγγος· καὶ τοὺς μὲν λοχαγοὺς καὶ τοὺς ἐνωμοτάρχους πρὸς τῶν Καρδούχων ἰέναι, οὐραγοὺς δὲ καταστήσασθαι πρὸς τοῦ ποταμοῦ.", "st": "4.3.26"}, {"sp": "N", "t": "οἱ δὲ Καρδοῦχοι ὡς ἑώρων τοὺς ὀπισθοφύλακας τοῦ ὄχλου ψιλουμένους καὶ ὀλίγους ἤδη φαινομένους, θᾶττον δὴ ἐπῆισαν ὠιδάς τινας ἄιδοντες. ὁ δὲ Χειρίσοφος, ἐπεὶ τὰ παρ᾽ αὐτῶι ἀσφαλῶς εἶχε, πέμπει παρὰ Ξενοφῶντα τοὺς πελταστὰς καὶ σφενδονήτας καὶ τοξότας καὶ κελεύει ποιεῖν ὅ τι ἂν παραγγέλληι.", "st": "4.3.27"}, {"sp": "N", "t": "ἰδὼν δ᾽ αὐτοὺς διαβαίνοντας Ξενοφῶν πέμψας ἄγγελον κελεύει αὐτοῦ μεῖναι ἐπὶ τοῦ ποταμοῦ μὴ διαβάντας· ὅταν δ᾽ ἄρξωνται αὐτοὶ διαβαίνειν, ἐναντίους ἔνθεν καὶ ἔνθεν σφῶν ἐμβαίνειν ὡς διαβησομένους, διηγκυλωμένους τοὺς ἀκοντιστὰς καὶ ἐπιβεβλημένους τοὺς τοξότας· μὴ πρόσω δὲ τοῦ ποταμοῦ προβαίνειν.", "st": "4.3.28"}, {"sp": "N", "t": "τοῖς δὲ παρ᾽ ἑαυτῶι παρήγγειλεν, ἐπειδὰν σφενδόνη ἐξικνῆται καὶ ἀσπὶς ψοφῆι, παιανίσαντας θεῖν εἰς τοὺς πολεμίους, ἐπειδὰν δ᾽ ἀναστρέψωσιν οἱ πολέμιοι καὶ ἐκ τοῦ ποταμοῦ ὁ σαλπικτὴς σημήνηι τὸ πολεμικόν, ἀναστρέψαντας ἐπὶ δόρυ ἡγεῖσθαι μὲν τοὺς οὐραγούς, θεῖν δὲ πάντας καὶ διαβαίνειν ὅτι τάχιστα ἧι ἕκαστος τὴν τάξιν εἶχεν, ὡς μὴ ἐμποδίζειν ἀλλήλους· ὅτι οὗτος ἄριστος ἔσοιτο ὃς ἂν πρῶτος ἐν τῶι πέραν γένηται.", "st": "4.3.29"}, {"sp": "N", "t": "οἱ δὲ Καρδοῦχοι ὁρῶντες ὀλίγους ἤδη τοὺς λοιπούς (πολλοὶ γὰρ καὶ τῶν μένειν τεταγμένων ὤιχοντο ἐπιμελόμενοι οἱ μὲν ὑποζυγίων, οἱ δὲ σκευῶν, οἱ δ᾽ ἑταιρῶν), ἐνταῦθα δὴ ἐπέκειντο θρασέως καὶ ἤρχοντο σφενδονᾶν καὶ τοξεύειν.", "st": "4.3.30"}, {"sp": "N", "t": "οἱ δὲ Ἕλληνες παιανίσαντες ὥρμησαν δρόμωι ἐπ᾽ αὐτούς· οἱ δὲ οὐκ ἐδέξαντο· καὶ γὰρ ἦσαν ὡπλισμένοι ὡς μὲν ἐν τοῖς ὄρεσιν ἱκανῶς πρὸς τὸ ἐπιδραμεῖν καὶ φεύγειν, πρὸς δὲ τὸ εἰς χεῖρας δέχεσθαι οὐχ ἱκανῶς.", "st": "4.3.31"}, {"sp": "N", "t": "ἐν τούτωι σημαίνει ὁ σαλπικτής· καὶ οἱ μὲν πολέμιοι ἔφευγον πολὺ ἔτι θᾶττον, οἱ δὲ Ἕλληνες τἀναντία στρέψαντες ἔφευγον διὰ τοῦ ποταμοῦ ὅτι τάχιστα.", "st": "4.3.32"}, {"sp": "N", "t": "τῶν δὲ πολεμίων οἱ μέν τινες αἰσθόμενοι πάλιν ἔδραμον ἐπὶ τὸν ποταμὸν καὶ τοξεύοντες ὀλίγους ἔτρωσαν, οἱ δὲ πολλοὶ καὶ πέραν ὄντων τῶν Ἑλλήνων ἔτι φανεροὶ ἦσαν φεύγοντες.", "st": "4.3.33"}, {"sp": "N", "t": "οἱ δὲ ὑπαντήσαντες ἀνδριζόμενοι καὶ προσωτέρω τοῦ καιροῦ προϊόντες ὕστερον τῶν μετὰ Ξενοφῶντος διέβησαν πάλιν· καὶ ἐτρώθησάν τινες καὶ τούτων.", "st": "4.3.34"}, {"sp": "N", "t": "ἐπεὶ δὲ διέβησαν, συνταξάμενοι ἀμφὶ μέσον ἡμέρας ἐπορεύθησαν διὰ τῆς Ἀρμενίας πεδίον ἅπαν καὶ λείους γηλόφους οὐ μεῖον ἢ πέντε παρασάγγας· οὐ γὰρ ἦσαν ἐγγὺς τοῦ ποταμοῦ κῶμαι διὰ τοὺς πολέμους τοὺς πρὸς τοὺς Καρδούχους.", "st": "4.4.1"}, {"sp": "N", "t": "εἰς δὲ ἣν ἀφίκοντο κώμην μεγάλη τε ἦν καὶ βασίλειον εἶχε τῶι σατράπηι καὶ ἐπὶ ταῖς πλείσταις οἰκίαις τύρσεις ἐπῆσαν· ἐπιτήδεια δ᾽ ἦν δαψιλῆ.", "st": "4.4.2"}, {"sp": "N", "t": "ἐντεῦθεν δ᾽ ἐπορεύθησαν σταθμοὺς δύο παρασάγγας δέκα μέχρι ὑπερῆλθον τὰς πηγὰς τοῦ Τίγρητος ποταμοῦ. ἐντεῦθεν δ᾽ ἐπορεύθησαν σταθμοὺς τρεῖς παρασάγγας πεντεκαίδεκα ἐπὶ τὸν Τηλεβόαν ποταμόν. οὗτος δ᾽ ἦν καλὸς μέν, μέγας δ᾽ οὔ· κῶμαι δὲ πολλαὶ περὶ τὸν ποταμὸν ἦσαν.", "st": "4.4.3"}, {"sp": "N", "t": "ὁ δὲ τόπος οὗτος Ἀρμενία ἐκαλεῖτο ἡ πρὸς ἑσπέραν. ὕπαρχος δ᾽ ἦν αὐτῆς Τιρίβαζος, ὁ καὶ βασιλεῖ φίλος γενόμενος, καὶ ὁπότε παρείη, οὐδεὶς ἄλλος βασιλέα ἐπὶ τὸν ἵππον ἀνέβαλλεν.", "st": "4.4.4"}, {"sp": "N", "t": "οὗτος προσήλασεν ἱππέας ἔχων, καὶ προπέμψας ἑρμηνέα εἶπεν ὅτι βούλοιτο διαλεχθῆναι τοῖς ἄρχουσι. τοῖς δὲ στρατηγοῖς ἔδοξεν ἀκοῦσαι· καὶ προσελθόντες εἰς ἐπήκοον ἠρώτων τί θέλει.", "st": "4.4.5"}, {"sp": "N", "t": "ὁ δὲ εἶπεν ὅτι σπείσασθαι βούλοιτο ἐφ᾽ ὧι μήτε αὐτὸς τοὺς Ἕλληνας ἀδικεῖν μήτε ἐκείνους καίειν τὰς οἰκίας λαμβάνειν τε τἀπιτήδεια ὅσων δέοιντο. ἔδοξε ταῦτα τοῖς στρατηγοῖς καὶ ἐσπείσαντο ἐπὶ τούτοις.", "st": "4.4.6"}, {"sp": "N", "t": "ἐντεῦθεν δ᾽ ἐπορεύθησαν σταθμοὺς τρεῖς διὰ πεδίου παρασάγγας πεντεκαίδεκα· καὶ Τιρίβαζος παρηκολούθει ἔχων τὴν ἑαυτοῦ δύναμιν ἀπέχων ὡς δέκα σταδίους· καὶ ἀφίκοντο εἰς βασίλεια καὶ κώμας πέριξ πολλὰς πολλῶν τῶν ἐπιτηδείων μεστάς.", "st": "4.4.7"}, {"sp": "N", "t": "στρατοπεδευομένων δ᾽ αὐτῶν γίγνεται τῆς νυκτὸς χιὼν πολλή· καὶ ἕωθεν ἔδοξε διασκηνῆσαι τὰς τάξεις καὶ τοὺς στρατηγοὺς κατὰ τὰς κώμας· οὐ γὰρ ἑώρων πολέμιον οὐδένα καὶ ἀσφαλὲς ἐδόκει εἶναι διὰ τὸ πλῆθος τῆς χιόνος.", "st": "4.4.8"}, {"sp": "N", "t": "ἐνταῦθα εἶχον τὰ ἐπιτήδεια ὅσα ἐστὶν ἀγαθά, ἱερεῖα, σῖτον, οἴνους παλαιοὺς εὐώδεις, ἀσταφίδας, ὄσπρια παντοδαπά. τῶν δὲ ἀποσκεδαννυμένων τινὲς ἀπὸ τοῦ στρατοπέδου ἔλεγον ὅτι κατίδοιεν νύκτωρ πολλὰ πυρὰ φαίνοντα.", "st": "4.4.9"}, {"sp": "N", "t": "ἐδόκει δὴ τοῖς στρατηγοῖς οὐκ ἀσφαλὲς εἶναι διασκηνοῦν, ἀλλὰ συναγαγεῖν τὸ στράτευμα πάλιν. ἐντεῦθεν συνῆλθον· καὶ γὰρ ἐδόκει διαιθριάζειν.", "st": "4.4.10"}, {"sp": "N", "t": "νυκτερευόντων δ᾽ αὐτῶν ἐνταῦθα ἐπιπίπτει χιὼν ἄπλετος, ὥστε ἀπέκρυψε καὶ τὰ ὅπλα καὶ τοὺς ἀνθρώπους κατακειμένους· καὶ τὰ ὑποζύγια συνεπόδισεν ἡ χιών· καὶ πολὺς ὄκνος ἦν ἀνίστασθαι· κατακειμένων γὰρ ἀλεεινὸν ἦν ἡ χιὼν ἐπιπεπτωκυῖα ὅτωι μὴ παραρρυείη.", "st": "4.4.11"}, {"sp": "N", "t": "ἐπεὶ δὲ Ξενοφῶν ἐτόλμησε γυμνὸς ἀναστὰς σχίζειν ξύλα, τάχ᾽ ἀναστάς τις καὶ ἄλλος ἐκείνου ἀφελόμενος ἔσχιζεν. ἐκ δὲ τούτου καὶ ἄλλοι ἀναστάντες πῦρ ἔκαιον καὶ ἐχρίοντο·", "st": "4.4.12"}, {"sp": "N", "t": "πολὺ γὰρ ἐνταῦθα ηὑρίσκετο χρῖμα, ὧι ἐχρῶντο ἀντ᾽ ἐλαίου, σύειον καὶ σησάμινον καὶ ἀμυγδάλινον ἐκ τῶν πικρῶν καὶ τερμίνθινον. ἐκ δὲ τῶν αὐτῶν τούτων καὶ μύρον ηὑρίσκετο.", "st": "4.4.13"}, {"sp": "N", "t": "μετὰ ταῦτα ἐδόκει πάλιν διασκηνητέον εἶναι [τὰς κώμας] εἰς στέγας. ἔνθα δὴ οἱ στρατιῶται σὺν πολλῆι κραυγῆι καὶ ἡδονῆι ἦισαν ἐπὶ τὰς στέγας καὶ τὰ ἐπιτήδεια· ὅσοι δὲ ὅτε τὸ πρότερον ἀπῆισαν τὰς οἰκίας ἐνέπρησαν ὑπὸ ἀτασθαλίας, δίκην ἐδίδοσαν κακῶς σκηνοῦντες.", "st": "4.4.14"}, {"sp": "N", "t": "ἐντεῦθεν ἔπεμψαν νυκτὸς Δημοκράτην Τημνίτην ἄνδρας δόντες ἐπὶ τὰ ὄρη ἔνθα ἔφασαν οἱ ἀποσκεδαννύμενοι καθορᾶν τὰ πυρά· οὗτος γὰρ ἐδόκει καὶ πρότερον πολλὰ ἤδη ἀληθεῦσαι τοιαῦτα, τὰ ὄντα τε ὡς ὄντα καὶ τὰ μὴ ὄντα ὡς οὐκ ὄντα.", "st": "4.4.15"}, {"sp": "N", "t": "πορευθεὶς δὲ τὰ μὲν πυρὰ οὐκ ἔφη ἰδεῖν, ἄνδρα δὲ συλλαβὼν ἧκεν ἄγων ἔχοντα τόξον Περσικὸν καὶ φαρέτραν καὶ σάγαριν οἵανπερ καὶ ⟨αἱ⟩ Ἀμαζόνες ἔχουσιν.", "st": "4.4.16"}, {"sp": "N", "t": "ἐρωτώμενος δὲ ποδαπὸς εἴη Πέρσης μὲν ἔφη εἶναι, πορεύεσθαι δ᾽ ἀπὸ τοῦ Τιριβάζου στρατοπέδου, ὅπως ἐπιτήδεια λάβοι. οἱ δὲ ἠρώτων αὐτὸν τὸ στράτευμα ὁπόσον τε εἴη καὶ ἐπὶ τίνι συνειλεγμένον.", "st": "4.4.17"}, {"sp": "N", "t": "ὁ δὲ εἶπεν ὅτι Τιρίβαζος εἴη ἔχων τήν τε ἑαυτοῦ δύναμιν καὶ μισθοφόρους Χάλυβας καὶ Ταόχους· παρεσκευάσθαι δὲ αὐτὸν ἔφη ὡς ἐπὶ τῆι ὑπερβολῆι τοῦ ὄρους ἐν τοῖς στενοῖς ἧιπερ μοναχῆι εἴη πορεία, ἐνταῦθα ἐπιθησόμενον τοῖς Ἕλλησιν.", "st": "4.4.18"}, {"sp": "N", "t": "ἀκούσασι τοῖς στρατηγοῖς ταῦτα ἔδοξε τὸ στράτευμα συναγαγεῖν· καὶ εὐθὺς φύλακας καταλιπόντες καὶ στρατηγὸν ἐπὶ τοῖς μένουσι Σοφαίνετον Στυμφάλιον ἐπορεύοντο ἔχοντες ἡγεμόνα τὸν ἁλόντα ἄνθρωπον.", "st": "4.4.19"}, {"sp": "N", "t": "ἐπειδὴ δὲ ὑπερέβαλλον τὰ ὄρη, οἱ πελτασταὶ προϊόντες καὶ κατιδόντες τὸ στρατόπεδον οὐκ ἔμειναν τοὺς ὁπλίτας, ἀλλ᾽ ἀνακραγόντες ἔθεον ἐπὶ τὸ στρατόπεδον.", "st": "4.4.20"}, {"sp": "N", "t": "οἱ δὲ βάρβαροι ἀκούσαντες τὸν θόρυβον οὐχ ὑπέμειναν, ἀλλ᾽ ἔφευγον· ὅμως δὲ καὶ ἀπέθανόν τινες τῶν βαρβάρων καὶ ἵπποι ἥλωσαν εἰς εἴκοσι καὶ ἡ σκηνὴ ἡ Τιριβάζου ἑάλω καὶ ἐν αὐτῆι κλῖναι ἀργυρόποδες καὶ ἐκπώματα καὶ οἱ ἀρτοκόποι καὶ οἱ οἰνοχόοι φάσκοντες εἶναι.", "st": "4.4.21"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἐπύθοντο ταῦτα οἱ τῶν ὁπλιτῶν στρατηγοί, ἐδόκει αὐτοῖς ἀπιέναι τὴν ταχίστην ἐπὶ τὸ στρατόπεδον, μή τις ἐπίθεσις γένοιτο τοῖς καταλελειμμένοις. καὶ εὐθὺς ἀνακαλεσάμενοι τῆι σάλπιγγι ἀπῆισαν, καὶ ἀφίκοντο αὐθημερὸν ἐπὶ τὸ στρατόπεδον.", "st": "4.4.22"}, {"sp": "N", "t": "τῆι δ᾽ ὑστεραίαι ἐδόκει πορευτέον εἶναι ὅπηι δύναιντο τάχιστα πρὶν ἢ συλλεγῆναι τὸ στράτευμα πάλιν καὶ καταλαβεῖν τὰ στενά. συσκευασάμενοι δ᾽ εὐθὺς ἐπορεύοντο διὰ χιόνος πολλῆς ἡγεμόνας ἔχοντες πολλούς· καὶ αὐθημερὸν ὑπερβαλόντες τὸ ἄκρον ἐφ᾽ ὧι ἔμελλεν ἐπιτίθεσθαι Τιρίβαζος κατεστρατοπεδεύσαντο.", "st": "4.5.1"}, {"sp": "N", "t": "ἐντεῦθεν δ᾽ ἐπορεύθησαν σταθμοὺς ἐρήμους τρεῖς παρασάγγας πεντεκαίδεκα ἐπὶ τὸν Εὐφράτην ποταμόν, καὶ διέβαινον αὐτὸν βρεχόμενοι πρὸς τὸν ὀμφαλόν.", "st": "4.5.2"}, {"sp": "N", "t": "ἐλέγοντο δ᾽ οὐδὲ πηγαὶ πρόσω εἶναι. ἐντεῦθεν ἐπορεύοντο διὰ χιόνος πολλῆς καὶ πεδίου σταθμοὺς τρεῖς παρασάγγας πεντεκαίδεκα. ὁ δὲ τρίτος ἐγένετο χαλεπὸς καὶ ἄνεμος βορρᾶς ἐναντίος ἔπνει παντάπασιν ἀποκαίων πάντα καὶ πηγνὺς τοὺς ἀνθρώπους.", "st": "4.5.3"}, {"sp": "N", "t": "ἔνθα δὴ τῶν μάντεών τις εἶπε σφαγιάσασθαι τῶι ἀνέμωι, καὶ σφαγιάζεται· καὶ πᾶσι δὴ περιφανῶς ἔδοξεν λῆξαι τὸ χαλεπὸν τοῦ πνεύματος. ἦν δὲ τῆς χιόνος τὸ βάθος ὀργυιά· ὥστε καὶ τῶν ὑποζυγίων καὶ τῶν ἀνδραπόδων πολλὰ ἀπώλετο καὶ τῶν στρατιωτῶν ὡς τριάκοντα.", "st": "4.5.4"}, {"sp": "N", "t": "διεγένοντο δὲ τὴν νύκτα πῦρ καίοντες· ξύλα δ᾽ ἦν ἐν τῶι σταθμῶι πολλά· οἱ δὲ ὀψὲ προσιόντες ξύλα οὐκ εἶχον. οἱ οὖν πάλαι ἥκοντες καὶ τὸ πῦρ καίοντες οὐ προσίεσαν πρὸς τὸ πῦρ τοὺς ὀψίζοντας, εἰ μὴ μεταδοῖεν αὐτοῖς πυροὺς ἢ ἄλλο [τι] εἴ τι ἔχοιεν βρωτόν.", "st": "4.5.5"}, {"sp": "N", "t": "ἔνθα δὴ μετεδίδοσαν ἀλλήλοις ὧν εἶχον ἕκαστοι. ἔνθα δὲ τὸ πῦρ ἐκαίετο, διατηκομένης τῆς χιόνος βόθροι ἐγένοντο μεγάλοι ἔστε ἐπὶ τὸ δάπεδον· οὗ δὴ παρῆν μετρεῖν τὸ βάθος τῆς χιόνος.", "st": "4.5.6"}, {"sp": "N", "t": "ἐντεῦθεν δὲ τὴν ἐπιοῦσαν ἡμέραν ὅλην ἐπορεύοντο διὰ χιόνος, καὶ πολλοὶ τῶν ἀνθρώπων ἐβουλιμίασαν. Ξενοφῶν δ᾽ ὀπισθοφυλακῶν καὶ καταλαμβάνων τοὺς πίπτοντας τῶν ἀνθρώπων ἠγνόει ὅ τι τὸ πάθος εἴη.", "st": "4.5.7"}, {"sp": "N", "t": "ἐπειδὴ δὲ εἶπέ τις αὐτῶι τῶν ἐμπείρων ὅτι σαφῶς βουλιμιῶσι κἄν τι φάγωσιν ἀναστήσονται, περιιὼν περὶ τὰ ὑποζύγια, εἴ πού τι ὁρώιη βρωτόν, διεδίδου καὶ διέπεμπε διδόντας τοὺς δυναμένους περιτρέχειν τοῖς βουλιμιῶσιν.", "st": "4.5.8"}, {"sp": "N", "t": "ἐπειδὴ δέ τι ἐμφάγοιεν, ἀνίσταντο καὶ ἐπορεύοντο. πορευομένων δὲ Χειρίσοφος μὲν ἀμφὶ κνέφας πρὸς κώμην ἀφικνεῖται, καὶ ὑδροφορούσας ἐκ τῆς κώμης πρὸς τῆι κρήνηι γυναῖκας καὶ κόρας καταλαμβάνει ἔμπροσθεν τοῦ ἐρύματος.", "st": "4.5.9"}, {"sp": "N", "t": "αὗται ἠρώτων αὐτοὺς τίνες εἶεν. ὁ δ᾽ ἑρμηνεὺς εἶπε περσιστὶ ὅτι παρὰ βασιλέως πορεύονται πρὸς τὸν σατράπην. αἱ δὲ ἀπεκρίναντο ὅτι οὐκ ἐνταῦθα εἴη, ἀλλ᾽ ἀπέχει ὅσον παρασάγγην. οἱ δ᾽, ἐπεὶ ὀψὲ ἦν, πρὸς τὸν κώμαρχον συνεισέρχονται εἰς τὸ ἔρυμα σὺν ταῖς ὑδροφόροις.", "st": "4.5.10"}, {"sp": "N", "t": "Χειρίσοφος μὲν οὖν καὶ ὅσοι ἐδυνήθησαν τοῦ στρατεύματος ἐνταῦθα ἐστρατοπεδεύσαντο, τῶν δ᾽ ἄλλων στρατιωτῶν οἱ μὴ δυνάμενοι διατελέσαι τὴν ὁδὸν ἐνυκτέρευσαν ἄσιτοι καὶ ἄνευ πυρός· καὶ ἐνταῦθά τινες ἀπώλοντο τῶν στρατιωτῶν.", "st": "4.5.11"}, {"sp": "N", "t": "ἐφείποντο δὲ τῶν πολεμίων συνειλεγμένοι τινὲς καὶ τὰ μὴ δυνάμενα τῶν ὑποζυγίων ἥρπαζον καὶ ἀλλήλοις ἐμάχοντο περὶ αὐτῶν. ἐλείποντο δὲ τῶν στρατιωτῶν οἵ τε διεφθαρμένοι ὑπὸ τῆς χιόνος τοὺς ὀφθαλμοὺς οἵ τε ὑπὸ τοῦ ψύχους τοὺς δακτύλους τῶν ποδῶν ἀποσεσηπότες.", "st": "4.5.12"}, {"sp": "N", "t": "ἦν δὲ τοῖς μὲν ὀφθαλμοῖς ἐπικούρημα τῆς χιόνος εἴ τις μέλαν τι ἔχων πρὸ τῶν ὀφθαλμῶν ἐπορεύετο, τῶν δὲ ποδῶν εἴ τις κινοῖτο καὶ μηδέποτε ἡσυχίαν ἔχοι καὶ εἰς τὴν νύκτα ὑπολύοιτο·", "st": "4.5.13"}, {"sp": "N", "t": "ὅσοι δὲ ὑποδεδεμένοι ἐκοιμῶντο, εἰσεδύοντο εἰς τοὺς πόδας οἱ ἱμάντες καὶ τὰ ὑποδήματα περιεπήγνυντο· καὶ γὰρ ἦσαν, ἐπειδὴ ἐπέλιπε τὰ ἀρχαῖα ὑποδήματα, καρβάτιναι πεποιημέναι ἐκ τῶν νεοδάρτων βοῶν.", "st": "4.5.14"}, {"sp": "N", "t": "διὰ τὰς τοιαύτας οὖν ἀνάγκας ὑπελείποντό τινες τῶν στρατιωτῶν· καὶ ἰδόντες μέλαν τι χωρίον διὰ τὸ ἐκλελοιπέναι αὐτόθι τὴν χιόνα εἴκαζον τετηκέναι· καὶ ἐτετήκει διὰ κρήνην τινὰ ἣ πλησίον ἦν ἀτμίζουσα ἐν νάπηι. ἐνταῦθ᾽ ἐκτραπόμενοι ἐκάθηντο καὶ οὐκ ἔφασαν πορεύεσθαι.", "st": "4.5.15"}, {"sp": "N", "t": "ὁ δὲ Ξενοφῶν ἔχων ὀπισθοφύλακας ὡς ἤισθετο, ἐδεῖτο αὐτῶν πάσηι τέχνηι καὶ μηχανῆι μὴ ἀπολείπεσθαι, λέγων ὅτι ἕπονται πολλοὶ πολέμιοι συνειλεγμένοι, καὶ τελευτῶν ἐχαλέπαινεν. οἱ δὲ σφάττειν ἐκέλευον· οὐ γὰρ ἂν δύνασθαι πορευθῆναι.", "st": "4.5.16"}, {"sp": "N", "t": "ἐνταῦθα ἔδοξε κράτιστον εἶναι τοὺς ἑπομένους πολεμίους φοβῆσαι, εἴ τις δύναιτο, μὴ ἐπίοιεν τοῖς κάμνουσι. καὶ ἦν μὲν σκότος ἤδη, οἱ δὲ προσῆισαν πολλῶι θορύβωι ἀμφὶ ὧν εἶχον διαφερόμενοι.", "st": "4.5.17"}, {"sp": "N", "t": "ἔνθα δὴ οἱ ὀπισθοφύλακες, ἅτε ὑγιαίνοντες, ἐξαναστάντες ἔδραμον εἰς τοὺς πολεμίους· οἱ δὲ κάμνοντες ἀνακραγόντες ὅσον ἐδύναντο μέγιστον τὰς ἀσπίδας πρὸς τὰ δόρατα ἔκρουσαν. οἱ δὲ πολέμιοι δείσαντες ἧκαν ἑαυτοὺς κατὰ τῆς χιόνος εἰς τὴν νάπην, καὶ οὐδεὶς ἔτι οὐδαμοῦ ἐφθέγξατο.", "st": "4.5.18"}, {"sp": "N", "t": "καὶ Ξενοφῶν μὲν καὶ οἱ σὺν αὐτῶι εἰπόντες τοῖς ἀσθενοῦσιν ὅτι τῆι ὑστεραίαι ἥξουσί τινες ἐπ᾽ αὐτούς, πορευόμενοι πρὶν τέτταρα στάδια διελθεῖν ἐντυγχάνουσιν ἐν τῆι ὁδῶι ἀναπαυομένοις ἐπὶ τῆς χιόνος τοῖς στρατιώταις ἐγκεκαλυμμένοις, καὶ οὐδὲ φυλακὴ οὐδεμία καθειστήκει· καὶ ἀνίστασαν αὐτούς. οἱ δ᾽ ἔλεγον ὅτι οἱ ἔμπροσθεν οὐχ ὑποχωροῖεν.", "st": "4.5.19"}, {"sp": "N", "t": "ὁ δὲ παριὼν καὶ παραπέμπων τῶν πελταστῶν τοὺς ἰσχυροτάτους ἐκέλευε σκέψασθαι τί εἴη τὸ κωλῦον. οἱ δὲ ἀπήγγελλον ὅτι ὅλον οὕτως ἀναπαύοιτο τὸ στράτευμα.", "st": "4.5.20"}, {"sp": "N", "t": "ἐνταῦθα καὶ οἱ περὶ Ξενοφῶντα ηὐλίσθησαν αὐτοῦ ἄνευ πυρὸς καὶ ἄδειπνοι, φυλακὰς οἵας ἐδύναντο καταστησάμενοι. ἐπεὶ δὲ πρὸς ἡμέραν ἦν, ὁ μὲν Ξενοφῶν πέμψας πρὸς τοὺς ἀσθενοῦντας τοὺς νεωτάτους ἀναστήσαντας ἐκέλευεν ἀναγκάζειν προϊέναι.", "st": "4.5.21"}, {"sp": "N", "t": "ἐν δὲ τούτωι Χειρίσοφος πέμπει τῶν ἐκ τῆς κώμης σκεψομένους πῶς ἔχοιεν οἱ τελευταῖοι. οἱ δὲ ἄσμενοι ἰδόντες τοὺς μὲν ἀσθενοῦντας τούτοις παρέδοσαν κομίζειν ἐπὶ τὸ στρατόπεδον, αὐτοὶ δὲ ἐπορεύοντο, καὶ πρὶν εἴκοσι στάδια διεληλυθέναι ἦσαν πρὸς τῆι κώμηι ἔνθα Χειρίσοφος ηὐλίζετο.", "st": "4.5.22"}, {"sp": "N", "t": "ἐπεὶ δὲ συνεγένοντο ἀλλήλοις, ἔδοξε κατὰ τὰς κώμας ἀσφαλὲς εἶναι τὰς τάξεις σκηνοῦν. καὶ Χειρίσοφος μὲν αὐτοῦ ἔμενεν, οἱ δὲ ἄλλοι διαλαχόντες ἃς ἑώρων κώμας ἐπορεύοντο ἕκαστοι τοὺς ἑαυτῶν ἔχοντες.", "st": "4.5.23"}, {"sp": "N", "t": "ἔνθα δὴ Πολυκράτης Ἀθηναῖος λοχαγὸς ἐκέλευσεν ἀφιέναι ἑαυτόν· καὶ λαβὼν τοὺς εὐζώνους, θέων ἐπὶ τὴν κώμην ἣν εἰλήχει Ξενοφῶν καταλαμβάνει πάντας ἔνδον τοὺς κωμήτας καὶ τὸν κώμαρχον, καὶ πώλους εἰς δασμὸν βασιλεῖ τρεφομένους ἑπτακαίδεκα, καὶ τὴν θυγατέρα τοῦ κωμάρχου ἐνάτην ἡμέραν γεγαμημένην· ὁ δ᾽ ἀνὴρ αὐτῆς λαγῶς ὤιχετο θηράσων καὶ οὐχ ἥλω ἐν τῆι κώμηι.", "st": "4.5.24"}, {"sp": "N", "t": "αἱ δ᾽ οἰκίαι ἦσαν κατάγειοι, τὸ μὲν στόμα ὥσπερ φρέατος, κάτω δ᾽ εὐρεῖαι· αἱ δὲ εἴσοδοι τοῖς μὲν ὑποζυγίοις ὀρυκταί, οἱ δὲ ἄνθρωποι κατέβαινον ἐπὶ κλίμακος. ἐν δὲ ταῖς οἰκίαις ἦσαν αἶγες, οἶες, βόες, ὄρνιθες, καὶ τὰ ἔκγονα τούτων· τὰ δὲ κτήνη πάντα χιλῶι ἔνδον ἐτρέφοντο.", "st": "4.5.25"}, {"sp": "N", "t": "ἦσαν δὲ καὶ πυροὶ καὶ κριθαὶ καὶ ὄσπρια καὶ οἶνος κρίθινος ἐν κρατῆρσιν. ἐνῆσαν δὲ καὶ αὐταὶ αἱ κριθαὶ ἰσοχειλεῖς, καὶ κάλαμοι ἐνέκειντο, οἱ μὲν μείζους οἱ δὲ ἐλάττους, γόνατα οὐκ ἔχοντες·", "st": "4.5.26"}, {"sp": "N", "t": "τούτους ἔδει ὁπότε τις διψώιη λαβόντα εἰς τὸ στόμα μύζειν. καὶ πάνυ ἄκρατος ἦν, εἰ μή τις ὕδωρ ἐπιχέοι· καὶ πάνυ ἡδὺ συμμαθόντι τὸ πῶμα ἦν.", "st": "4.5.27"}, {"sp": "N", "t": "ὁ δὲ Ξενοφῶν τὸν ἄρχοντα τῆς κώμης ταύτης σύνδειπνον ἐποιήσατο καὶ θαρρεῖν αὐτὸν ἐκέλευε λέγων ὅτι οὔτε τῶν τέκνων στερήσοιτο τήν τε οἰκίαν αὐτοῦ ἀντεμπλήσαντες τῶν ἐπιτηδείων ἀπίασιν, ἢν ἀγαθόν τι τῶι στρατεύματι ἐξηγησάμενος φαίνηται ἔστ᾽ ἂν ἐν ἄλλωι ἔθνει γένωνται.", "st": "4.5.28"}, {"sp": "N", "t": "ὁ δὲ ταῦτα ὑπισχνεῖτο, καὶ φιλοφρονούμενος οἶνον ἔφρασεν ἔνθα ἦν κατορωρυγμένος. ταύτην μὲν τὴν νύκτα διασκηνήσαντες οὕτως ἐκοιμήθησαν ἐν πᾶσιν ἀφθόνοις πάντες οἱ στρατιῶται, ἐν φυλακῆι ἔχοντες τὸν κώμαρχον καὶ τὰ τέκνα αὐτοῦ ὁμοῦ ἐν ὀφθαλμοῖς.", "st": "4.5.29"}, {"sp": "N", "t": "τῆι δ᾽ ἐπιούσηι ἡμέραι Ξενοφῶν λαβὼν τὸν κώμαρχον πρὸς Χειρίσοφον ἐπορεύετο· ὅπου δὲ παρίοι κώμην, ἐτρέπετο πρὸς τοὺς ἐν ταῖς κώμαις καὶ κατελάμβανε πανταχοῦ εὐωχουμένους καὶ εὐθυμουμένους, καὶ οὐδαμόθεν ἀφίεσαν πρὶν παραθεῖναι αὐτοῖς ἄριστον·", "st": "4.5.30"}, {"sp": "N", "t": "οὐκ ἦν δ᾽ ὅπου οὐ παρετίθεσαν ἐπὶ τὴν αὐτὴν τράπεζαν κρέα ἄρνεια, ἐρίφεια, χοίρεια, μόσχεια, ὀρνίθεια, σὺν πολλοῖς ἄρτοις τοῖς μὲν πυρίνοις τοῖς δὲ κριθίνοις.", "st": "4.5.31"}, {"sp": "N", "t": "ὁπότε δέ τις φιλοφρονούμενός τωι βούλοιτο προπιεῖν, εἷλκεν ἐπὶ τὸν κρατῆρα, ἔνθεν ἐπικύψαντα ἔδει ῥοφοῦντα πίνειν ὥσπερ βοῦν. καὶ τῶι κωμάρχωι ἐδίδοσαν λαμβάνειν ὅ τι βούλοιτο. ὁ δὲ ἄλλο μὲν οὐδὲν ἐδέχετο, ὅπου δέ τινα τῶν συγγενῶν ἴδοι, πρὸς ἑαυτὸν ἀεὶ ἐλάμβανεν.", "st": "4.5.32"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἦλθον πρὸς Χειρίσοφον, κατελάμβανον κἀκείνους σκηνοῦντας ἐστεφανωμένους τοῦ ξηροῦ χιλοῦ στεφάνοις, καὶ διακονοῦντας Ἀρμενίους παῖδας σὺν ταῖς βαρβαρικαῖς στολαῖς· τοῖς παισὶν ἐδείκνυσαν ὥσπερ ἐνεοῖς ὅ τι δέοι ποιεῖν.", "st": "4.5.33"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἀλλήλους ἐφιλοφρονήσαντο Χειρίσοφος καὶ Ξενοφῶν, κοινῆι δὴ ἀνηρώτων τὸν κώμαρχον διὰ τοῦ περσίζοντος ἑρμηνέως τίς εἴη ἡ χώρα. ὁ δ᾽ ἔλεγεν ὅτι Ἀρμενία. καὶ πάλιν ἠρώτων τίνι οἱ ἵπποι τρέφονται. ὁ δ᾽ ἔλεγεν ὅτι βασιλεῖ δασμός· τὴν δὲ πλησίον χώραν ἔφη εἶναι Χάλυβας, καὶ τὴν ὁδὸν ἔφραζεν ἧι εἴη.", "st": "4.5.34"}, {"sp": "N", "t": "καὶ αὐτὸν τότε μὲν ὤιχετο ἄγων ὁ Ξενοφῶν πρὸς τοὺς ἑαυτοῦ οἰκέτας, καὶ ἵππον ὃν εἰλήφει παλαίτερον δίδωσι τῶι κωμάρχωι ἀναθρέψαντι καταθῦσαι, ὅτι ἤκουεν αὐτὸν ἱερὸν εἶναι τοῦ Ἡλίου, δεδιὼς μὴ ἀποθάνηι· ἐκεκάκωτο γὰρ ὑπὸ τῆς πορείας· αὐτὸς δὲ τῶν πώλων λαμβάνει, καὶ τῶν ἄλλων στρατηγῶν καὶ λοχαγῶν ἔδωκεν ἑκάστωι πῶλον.", "st": "4.5.35"}, {"sp": "N", "t": "ἦσαν δ᾽ οἱ ταύτηι ἵπποι μείονες μὲν τῶν Περσικῶν, θυμοειδέστεροι δὲ πολύ. ἐνταῦθα δὴ καὶ διδάσκει ὁ κώμαρχος περὶ τοὺς πόδας τῶν ἵππων καὶ τῶν ὑποζυγίων σακία περιειλεῖν, ὅταν διὰ τῆς χιόνος ἄγωσιν· ἄνευ γὰρ τῶν σακίων κατεδύοντο μέχρι τῆς γαστρός.", "st": "4.5.36"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἡμέρα ἦν ὀγδόη, τὸν μὲν ἡγεμόνα παραδίδωσι Χειρισόφωι, τοὺς δὲ οἰκέτας καταλείπει τῶι κωμάρχωι, πλὴν τοῦ υἱοῦ τοῦ ἄρτι ἡβάσκοντος· τοῦτον δὲ Πλεισθένει Ἀμφιπολίτηι δίδωσι φυλάττειν, ὅπως εἰ καλῶς ἡγήσοιτο, ἔχων καὶ τοῦτον ἀπίοι. καὶ εἰς τὴν οἰκίαν αὐτοῦ εἰσεφόρησαν ὡς ἐδύναντο πλεῖστα, καὶ ἀναζεύξαντες ἐπορεύοντο.", "st": "4.6.1"}, {"sp": "N", "t": "ἡγεῖτο δ᾽ αὐτοῖς ὁ κώμαρχος λελυμένος διὰ χιόνος· καὶ ἤδη τε ἦν ἐν τῶι τρίτωι σταθμῶι, καὶ Χειρίσοφος αὐτῶι ἐχαλεπάνθη ὅτι οὐκ εἰς κώμας ἤγαγεν. ὁ δ᾽ ἔλεγεν ὅτι οὐκ εἶεν ἐν τῶι τόπωι τούτωι.", "st": "4.6.2"}, {"sp": "N", "t": "ὁ δὲ Χειρίσοφος αὐτὸν ἔπαισεν, ἔδησε δ᾽ οὔ. ἐκ δὲ τούτου ἐκεῖνος τῆς νυκτὸς ἀποδρὰς ὤιχετο καταλιπὼν τὸν υἱόν. τοῦτό γε δὴ Χειρισόφωι καὶ Ξενοφῶντι μόνον διάφορον ἐν τῆι πορείαι ἐγένετο, ἡ τοῦ ἡγεμόνος κάκωσις καὶ ἀμέλεια. Πλεισθένης δὲ ἠράσθη τοῦ παιδὸς καὶ οἴκαδε κομίσας πιστοτάτωι ἐχρῆτο.", "st": "4.6.3"}, {"sp": "N", "t": "μετὰ τοῦτο ἐπορεύθησαν ἑπτὰ σταθμοὺς ἀνὰ πέντε παρασάγγας τῆς ἡμέρας παρὰ τὸν Φᾶσιν ποταμόν, εὖρος πλεθριαῖον.", "st": "4.6.4"}, {"sp": "N", "t": "ἐντεῦθεν ἐπορεύθησαν σταθμοὺς δύο παρασάγγας δέκα· ἐπὶ δὲ τῆι εἰς τὸ πεδίον ὑπερβολῆι ἀπήντησαν αὐτοῖς Χάλυβες καὶ Τάοχοι καὶ Φασιανοί.", "st": "4.6.5"}, {"sp": "N", "t": "Χειρίσοφος δ᾽ ἐπεὶ κατεῖδε τοὺς πολεμίους ἐπὶ τῆι ὑπερβολῆι, ἐπαύσατο πορευόμενος, ἀπέχων εἰς τριάκοντα σταδίους, ἵνα μὴ κατὰ κέρας ἄγων πλησιάσηι τοῖς πολεμίοις· παρήγγειλε δὲ καὶ τοῖς ἄλλοις παράγειν τοὺς λόχους, ὅπως ἐπὶ φάλαγγος γένοιτο τὸ στράτευμα.", "st": "4.6.6"}, {"sp": "N", "t": "ἐπεὶ δὲ ἦλθον οἱ ὀπισθοφύλακες, συνεκάλεσε στρατηγοὺς καὶ λοχαγούς, καὶ ἔλεξεν ὧδε. «οἱ μὲν πολέμιοι, ὡς ὁρᾶτε, κατέχουσι τὰς ὑπερβολὰς τοῦ ὄρους· ὥρα δὲ βουλεύεσθαι ὅπως ὡς κάλλιστα ἀγωνιούμεθα.", "st": "4.6.7"}, {"sp": "N", "t": "ἐμοὶ μὲν οὖν δοκεῖ παραγγεῖλαι μὲν ἀριστοποιεῖσθαι τοῖς στρατιώταις, ἡμᾶς δὲ βουλεύεσθαι εἴτε τήμερον εἴτε αὔριον δοκεῖ ὑπερβάλλειν τὸ ὄρος.»", "st": "4.6.8"}, {"sp": "N", "t": "«ἐμοὶ δέ γε, ἔφη ὁ Κλεάνωρ, δοκεῖ, ἐπὰν τάχιστα ἀριστήσωμεν, ἐξοπλισαμένους ὡς κράτιστα ἰέναι ἐπὶ τοὺς ἄνδρας. εἰ γὰρ διατρίψομεν τὴν τήμερον ἡμέραν, οἵ τε νῦν ἡμᾶς ὁρῶντες πολέμιοι θαρραλεώτεροι ἔσονται καὶ ἄλλους εἰκὸς τούτων θαρρούντων πλείους προσγενέσθαι.»", "st": "4.6.9"}, {"sp": "N", "t": "μετὰ τοῦτον Ξενοφῶν εἶπεν· «ἐγὼ δ᾽ οὕτω γιγνώσκω. εἰ μὲν ἀνάγκη ἐστὶ μάχεσθαι, τοῦτο δεῖ παρασκευάσασθαι, ὅπως ὡς κράτιστα μαχούμεθα· εἰ δὲ βουλόμεθα ὡς ῥᾶιστα ὑπερβάλλειν, τοῦτό μοι δοκεῖ σκεπτέον εἶναι, ὅπως ⟨ὡς⟩ ἐλάχιστα μὲν τραύματα λάβωμεν, ὡς ἐλάχιστα δὲ σώματα ἀνδρῶν ἀποβάλωμεν.", "st": "4.6.10"}, {"sp": "N", "t": "τὸ μὲν οὖν ὄρος ἐστὶ τὸ ὁρώμενον πλέον ἢ ἐφ᾽ ἑξήκοντα στάδια, ἄνδρες δ᾽ οὐδαμοῦ φυλάττοντες ἡμᾶς φανεροί εἰσιν ἀλλ᾽ ἢ κατ᾽ αὐτὴν τὴν ὁδόν· πολὺ οὖν κρεῖττον τοῦ ἐρήμου ὄρους καὶ κλέψαι τι πειρᾶσθαι λαθόντας καὶ ἁρπάσαι φθάσαντας, εἰ δυναίμεθα, μᾶλλον ἢ πρὸς ἰσχυρὰ χωρία καὶ ἀνθρώπους παρεσκευασμένους μάχεσθαι.", "st": "4.6.11"}, {"sp": "N", "t": "πολὺ γὰρ ῥᾶιον ὄρθιον ἀμαχεὶ ἰέναι ἢ ὁμαλὲς ἔνθεν καὶ ἔνθεν πολεμίων ὄντων, καὶ νύκτωρ ἀμαχεὶ μᾶλλον ἂν τὰ πρὸ ποδῶν ὁρώιη τις ἢ μεθ᾽ ἡμέραν μαχόμενος, καὶ ἡ τραχεῖα τοῖς ποσὶν ἀμαχεὶ ἰοῦσιν εὐμενεστέρα ἢ ἡ ὁμαλὴ τὰς κεφαλὰς βαλλομένοις.", "st": "4.6.12"}, {"sp": "N", "t": "καὶ κλέψαι δ᾽ οὐκ ἀδύνατόν μοι δοκεῖ εἶναι, ἐξὸν μὲν νυκτὸς ἰέναι, ὡς μὴ ὁρᾶσθαι, ἐξὸν δ᾽ ἀπελθεῖν τοσοῦτον ὡς μὴ αἴσθησιν παρέχειν. δοκοῦμεν δ᾽ ἄν μοι ταύτηι προσποιούμενοι προσβάλλειν ἐρημοτέρωι ἂν τῶι ὄρει χρῆσθαι· μένοιεν γὰρ ⟨ἂν⟩ αὐτοῦ μᾶλλον ἁθρόοι οἱ πολέμιοι.", "st": "4.6.13"}, {"sp": "N", "t": "ἀτὰρ τί ἐγὼ περὶ κλοπῆς συμβάλλομαι; ὑμᾶς γὰρ ἔγωγε, ὦ Χειρίσοφε, ἀκούω τοὺς Λακεδαιμονίους ὅσοι ἐστὲ τῶν ὁμοίων εὐθὺς ἐκ παίδων κλέπτειν μελετᾶν, καὶ οὐκ αἰσχρὸν εἶναι ἀλλὰ καλὸν κλέπτειν ὅσα μὴ κωλύει νόμος.", "st": "4.6.14"}, {"sp": "N", "t": "ὅπως δὲ ὡς κράτιστα κλέπτητε καὶ πειρᾶσθε λανθάνειν, νόμιμον ἄρα ὑμῖν ἐστιν, ἐὰν ληφθῆτε κλέπτοντες, μαστιγοῦσθαι. νῦν οὖν μάλα σοι καιρός ἐστιν ἐπιδείξασθαι τὴν παιδείαν, καὶ φυλάξασθαι μὴ ληφθῶμεν κλέπτοντες τοῦ ὄρους, ὡς μὴ πληγὰς λάβωμεν.»", "st": "4.6.15"}, {"sp": "N", "t": "«ἀλλὰ μέντοι, ἔφη ὁ Χειρίσοφος, κἀγὼ ὑμᾶς τοὺς Ἀθηναίους ἀκούω δεινοὺς εἶναι κλέπτειν τὰ δημόσια, καὶ μάλα ὄντος δεινοῦ κινδύνου τῶι κλέπτοντι, καὶ τοὺς κρατίστους μέντοι μάλιστα, εἴπερ ὑμῖν οἱ κράτιστοι ἄρχειν ἀξιοῦνται· ὥστε ὥρα καὶ σοὶ ἐπιδείκνυσθαι τὴν παιδείαν.»", "st": "4.6.16"}, {"sp": "N", "t": "«ἐγὼ μὲν τοίνυν, ἔφη ὁ Ξενοφῶν, ἕτοιμός εἰμι τοὺς ὀπισθοφύλακας ἔχων, ἐπειδὰν δειπνήσωμεν, ἰέναι καταληψόμενος τὸ ὄρος. ἔχω δὲ καὶ ἡγεμόνας· οἱ γὰρ γυμνῆτες τῶν ἑπομένων ἡμῖν κλωπῶν ἔλαβόν τινας ἐνεδρεύσαντες· τούτων καὶ πυνθάνομαι ὅτι οὐκ ἄβατόν ἐστι τὸ ὄρος, ἀλλὰ νέμεται αἰξὶ καὶ βουσίν· ὥστε ἐάνπερ ἅπαξ λάβωμέν τι τοῦ ὄρους, βατὰ καὶ τοῖς ὑποζυγίοις ἔσται.", "st": "4.6.17"}, {"sp": "N", "t": "ἐλπίζω δὲ οὐδὲ τοὺς πολεμίους μενεῖν ἔτι, ἐπειδὰν ἴδωσιν ἡμᾶς ἐν τῶι ὁμοίωι ἐπὶ τῶν ἄκρων· οὐδὲ γὰρ νῦν ἐθέλουσι καταβαίνειν εἰς τὸ ἴσον ἡμῖν.»", "st": "4.6.18"}, {"sp": "N", "t": "ὁ δὲ Χειρίσοφος εἶπε· «καὶ τί δεῖ σὲ ἰέναι καὶ λιπεῖν τὴν ὀπισθοφυλακίαν; ἀλλὰ ἄλλους πέμψον, ἂν μή τινες ἐθέλοντες ἀγαθοὶ φαίνωνται.»", "st": "4.6.19"}, {"sp": "N", "t": "ἐκ τούτου Ἀριστώνυμος Μεθυδριεὺς ἔρχεται ὁπλίτας ἔχων καὶ Ἀριστέας ὁ Χῖος γυμνῆτας καὶ Νικόμαχος Οἰταῖος γυμνῆτας· καὶ σύνθημα ἐποιήσαντο, ὁπότε ἔχοιεν τὰ ἄκρα, πυρὰ καίειν πολλά.", "st": "4.6.20"}, {"sp": "N", "t": "ταῦτα συνθέμενοι ἠρίστων· ἐκ δὲ τοῦ ἀρίστου προήγαγεν ὁ Χειρίσοφος τὸ στράτευμα πᾶν ὡς δέκα σταδίους πρὸς τοὺς πολεμίους, ὅπως ὡς μάλιστα δοκοίη ταύτηι προσάξειν.", "st": "4.6.21"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἐδείπνησαν καὶ νὺξ ἐγένετο, οἱ μὲν ταχθέντες ὤιχοντο, καὶ καταλαμβάνουσι τὸ ὄρος, οἱ δὲ ἄλλοι αὐτοῦ ἀνεπαύοντο. οἱ δὲ πολέμιοι ἐπεὶ ἤισθοντο τὸ ὄρος ἐχόμενον, ἐγρηγόρεσαν καὶ ἔκαιον πυρὰ πολλὰ διὰ νυκτός.", "st": "4.6.22"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἡμέρα ἐγένετο Χειρίσοφος μὲν θυσάμενος ἦγε κατὰ τὴν ὁδόν, οἱ δὲ τὸ ὄρος καταλαβόντες κατὰ τὰ ἄκρα ἐπῆισαν.", "st": "4.6.23"}, {"sp": "N", "t": "τῶν δὲ πολεμίων τὸ μὲν πολὺ ἔμενεν ἐπὶ τῆι ὑπερβολῆι τοῦ ὄρους, μέρος δ᾽ αὐτῶν ἀπήντα τοῖς κατὰ τὰ ἄκρα. πρὶν δὲ ὁμοῦ εἶναι τοὺς πολλοὺς ἀλλήλοις, συμμιγνύασιν οἱ κατὰ τὰ ἄκρα, καὶ νικῶσιν οἱ Ἕλληνες καὶ διώκουσιν.", "st": "4.6.24"}, {"sp": "N", "t": "ἐν τούτωι δὲ καὶ οἱ ἐκ τοῦ πεδίου οἱ μὲν πελτασταὶ τῶν Ἑλλήνων δρόμωι ἔθεον πρὸς τοὺς παρατεταγμένους, Χειρίσοφος δὲ βάδην ταχὺ ἐφείπετο σὺν τοῖς ὁπλίταις.", "st": "4.6.25"}, {"sp": "N", "t": "οἱ δὲ πολέμιοι οἱ ἐπὶ τῆι ὁδῶι ἐπειδὴ τὸ ἄνω ἑώρων ἡττώμενον, φεύγουσι· καὶ ἀπέθανον μὲν οὐ πολλοὶ αὐτῶν, γέρρα δὲ πάμπολλα ἐλήφθη· ἃ οἱ Ἕλληνες ταῖς μαχαίραις κόπτοντες ἀχρεῖα ἐποίουν.", "st": "4.6.26"}, {"sp": "N", "t": "ὡς δ᾽ ἀνέβησαν, θύσαντες καὶ τρόπαιον στησάμενοι κατέβησαν εἰς τὸ πεδίον, καὶ εἰς κώμας πολλῶν καὶ ἀγαθῶν γεμούσας ἦλθον.", "st": "4.6.27"}, {"sp": "N", "t": "ἐκ δὲ τούτων ἐπορεύθησαν εἰς Ταόχους σταθμοὺς πέντε παρασάγγας τριάκοντα· καὶ τὰ ἐπιτήδεια ἐπέλειπε· χωρία γὰρ ὤικουν ἰσχυρὰ οἱ Τάοχοι, ἐν οἷς καὶ τὰ ἐπιτήδεια ἅπαντα εἶχον ἀνακεκομισμένοι.", "st": "4.7.1"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἀφίκοντο πρὸς χωρίον ὃ πόλιν μὲν οὐκ εἶχεν οὐδ᾽ οἰκίας, συνεληλυθότες δ᾽ ἦσαν αὐτόσε καὶ ἄνδρες καὶ γυναῖκες καὶ κτήνη πολλά, Χειρίσοφος μὲν οὖν πρὸς τοῦτο προσέβαλλεν εὐθὺς ἥκων· ἐπειδὴ δὲ ἡ πρώτη τάξις ἀπέκαμνεν, ἄλλη προσήιει καὶ αὖθις ἄλλη· οὐ γὰρ ἦν ἁθρόοις περιστῆναι, ἀλλ᾽ ἀπότομον ἦν κύκλωι.", "st": "4.7.2"}, {"sp": "N", "t": "ἐπειδὴ δὲ Ξενοφῶν ἦλθε σὺν τοῖς ὀπισθοφύλαξι καὶ πελτασταῖς καὶ ὁπλίταις, ἐνταῦθα δὴ λέγει Χειρίσοφος· «εἰς καλὸν ἥκετε· τὸ γὰρ χωρίον αἱρετέον· τῆι γὰρ στρατιᾶι οὐκ ἔστι τὰ ἐπιτήδεια, εἰ μὴ ληψόμεθα τὸ χωρίον.»", "st": "4.7.3"}, {"sp": "N", "t": "ἐνταῦθα δὴ κοινῆι ἐβουλεύοντο· καὶ τοῦ Ξενοφῶντος ἐρωτῶντος τί τὸ κωλῦον εἴη εἰσελθεῖν, εἶπεν ὁ Χειρίσοφος· «μία αὕτη πάροδός ἐστιν ἣν ὁρᾶις· ὅταν δέ τις ταύτηι πειρᾶται παριέναι, κυλίνδουσι λίθους ὑπὲρ ταύτης τῆς ὑπερεχούσης πέτρας· ὃς δ᾽ ἂν καταληφθῆι, οὕτω διατίθεται.» ἅμα δ᾽ ἔδειξε συντετριμμένους ἀνθρώπους καὶ σκέλη καὶ πλευράς.", "st": "4.7.4"}, {"sp": "N", "t": "«ἢν δὲ τοὺς λίθους ἀναλώσωσιν, ἔφη ὁ Ξενοφῶν, ἄλλο τι ἢ οὐδὲν κωλύει παριέναι; οὐ γὰρ δὴ ἐκ τοῦ ἐναντίου ὁρῶμεν εἰ μὴ ὀλίγους τούτους ἀνθρώπους, καὶ τούτων δύο ἢ τρεῖς ὡπλισμένους.", "st": "4.7.5"}, {"sp": "N", "t": "τὸ δὲ χωρίον, ὡς καὶ σὺ ὁρᾶις, σχεδὸν τρία ἡμίπλεθρά ἐστιν ὃ δεῖ βαλλομένους διελθεῖν· τούτου δὲ ὅσον πλέθρον δασὺ πίτυσι διαλειπούσαις μεγάλαις, ἀνθ᾽ ὧν ἑστηκότες ἄνδρες τί ἂν πάσχοιεν ἢ ὑπὸ τῶν φερομένων λίθων ἢ ὑπὸ τῶν κυλινδομένων; τὸ λοιπὸν οὖν γίγνεται ὡς ἡμίπλεθρον, ὃ δεῖ ὅταν λωφήσωσιν οἱ λίθοι παραδραμεῖν.»", "st": "4.7.6"}, {"sp": "N", "t": "«ἀλλὰ εὐθύς, ἔφη ὁ Χειρίσοφος, ἐπειδὰν ἀρξώμεθα εἰς τὸ δασὺ προσιέναι, φέρονται οἱ λίθοι πολλοί.» «αὐτὸ ἄν, ἔφη, τὸ δέον εἴη· θᾶττον γὰρ ἀναλώσουσι τοὺς λίθους. ἀλλὰ πορευώμεθα ἔνθεν ἡμῖν μικρόν τι παραδραμεῖν ἔσται, ἢν δυνώμεθα, καὶ ἀπελθεῖν ῥάιδιον, ἢν βουλώμεθα.»", "st": "4.7.7"}, {"sp": "N", "t": "ἐντεῦθεν ἐπορεύοντο Χειρίσοφος καὶ Ξενοφῶν καὶ Καλλίμαχος Παρράσιος λοχαγός· τούτου γὰρ ἡ ἡγεμονία ἦν τῶν ὀπισθοφυλάκων λοχαγῶν ἐκείνηι τῆι ἡμέραι· οἱ δὲ ἄλλοι λοχαγοὶ ἔμενον ἐν τῶι ἀσφαλεῖ. μετὰ τοῦτο οὖν ἀπῆλθον ὑπὸ τὰ δένδρα ἄνθρωποι ὡς ἑβδομήκοντα, οὐχ ἁθρόοι ἀλλὰ καθ᾽ ἕνα, ἕκαστος φυλαττόμενος ὡς ἐδύνατο.", "st": "4.7.8"}, {"sp": "N", "t": "Ἀγασίας δὲ ὁ Στυμφάλιος καὶ Ἀριστώνυμος Μεθυδριεὺς καὶ οὗτοι τῶν ὀπισθοφυλάκων λοχαγοὶ ὄντες, καὶ ἄλλοι δέ, ἐφέστασαν ἔξω τῶν δένδρων· οὐ γὰρ ἦν ἀσφαλῶς ἐν τοῖς δένδροις ἑστάναι πλέον ἢ τὸν ἕνα λόχον.", "st": "4.7.9"}, {"sp": "N", "t": "ἔνθα δὴ Καλλίμαχος μηχανᾶταί τι· προύτρεχεν ἀπὸ τοῦ δένδρου ὑφ᾽ ὧι ἦν αὐτὸς δύο ἢ τρία βήματα· ἐπειδὴ δὲ οἱ λίθοι φέροιντο, ἀνέχαζεν εὐπετῶς· ἐφ᾽ ἑκάστης δὲ τῆς προδρομῆς πλέον ἢ δέκα ἅμαξαι πετρῶν ἀνηλίσκοντο.", "st": "4.7.10"}, {"sp": "N", "t": "ὁ δὲ Ἀγασίας ὡς ὁρᾶι τὸν Καλλίμαχον ἃ ἐποίει τὸ στράτευμα πᾶν θεώμενον, δείσας μὴ οὐ πρῶτος παραδράμηι εἰς τὸ χωρίον, οὐδὲ τὸν Ἀριστώνυμον πλησίον ὄντα παρακαλέσας οὐδὲ Εὐρύλοχον τὸν Λουσιέα, ἑταίρους ὄντας, οὐδὲ ἄλλον οὐδένα χωρεῖ αὐτός, καὶ παρέρχεται πάντας.", "st": "4.7.11"}, {"sp": "N", "t": "ὁ δὲ Καλλίμαχος ὡς ὁρᾶι αὐτὸν παριόντα, ἐπιλαμβάνεται αὐτοῦ τῆς ἴτυος· ἐν δὲ τούτωι παραθεῖ αὐτοὺς Ἀριστώνυμος Μεθυδριεύς, καὶ μετὰ τοῦτον Εὐρύλοχος Λουσιεύς· πάντες γὰρ οὗτοι ἀντεποιοῦντο ἀρετῆς καὶ διηγωνίζοντο πρὸς ἀλλήλους· καὶ οὕτως ἐρίζοντες αἱροῦσι τὸ χωρίον. ὡς γὰρ ἅπαξ εἰσέδραμον, οὐδεὶς πέτρος ἄνωθεν ἠνέχθη.", "st": "4.7.12"}, {"sp": "N", "t": "ἐνταῦθα δὴ δεινὸν ἦν θέαμα. αἱ γὰρ γυναῖκες ῥίπτουσαι τὰ παιδία εἶτα ἑαυτὰς ἐπικατερρίπτουν, καὶ οἱ ἄνδρες ὡσαύτως. ἐνταῦθα δὴ καὶ Αἰνείας Στυμφάλιος λοχαγὸς ἰδών τινα θέοντα ὡς ῥίψοντα ἑαυτὸν στολὴν ἔχοντα καλὴν ἐπιλαμβάνεται ὡς κωλύσων·", "st": "4.7.13"}, {"sp": "N", "t": "ὁ δὲ αὐτὸν ἐπισπᾶται, καὶ ἀμφότεροι ὤιχοντο κατὰ τῶν πετρῶν φερόμενοι καὶ ἀπέθανον. ἐντεῦθεν ἄνθρωποι μὲν πάνυ ὀλίγοι ἐλήφθησαν, βόες δὲ καὶ ὄνοι πολλοὶ καὶ πρόβατα.", "st": "4.7.14"}, {"sp": "N", "t": "ἐντεῦθεν ἐπορεύθησαν διὰ Χαλύβων σταθμοὺς ἑπτὰ παρασάγγας πεντήκοντα. οὗτοι ἦσαν ὧν διῆλθον ἀλκιμώτατοι, καὶ εἰς χεῖρας ἦισαν. εἶχον δὲ θώρακας λινοῦς μέχρι τοῦ ἤτρου, ἀντὶ δὲ τῶν πτερύγων σπάρτα πυκνὰ ἐστραμμένα.", "st": "4.7.15"}, {"sp": "N", "t": "εἶχον δὲ καὶ κνημῖδας καὶ κράνη καὶ παρὰ τὴν ζώνην μαχαίριον ὅσον ξυήλην Λακωνικήν, ὧι ἔσφαττον ὧν κρατεῖν δύναιντο, καὶ ἀποτεμόντες ἂν τὰς κεφαλὰς ἔχοντες ἐπορεύοντο, καὶ ἦιδον καὶ ἐχόρευον ὁπότε οἱ πολέμιοι αὐτοὺς ὄψεσθαι ἔμελλον. εἶχον δὲ καὶ δόρυ ὡς πεντεκαίδεκα πήχεων μίαν λόγχην ἔχον.", "st": "4.7.16"}, {"sp": "N", "t": "οὗτοι ἐνέμενον ἐν τοῖς πολίσμασιν· ἐπεὶ δὲ παρέλθοιεν οἱ Ἕλληνες, εἵποντο ἀεὶ μαχούμενοι. ὤικουν δὲ ἐν τοῖς ὀχυροῖς, καὶ τὰ ἐπιτήδεια ἐν τούτοις ἀνακεκομισμένοι ἦσαν· ὥστε μηδὲν λαμβάνειν αὐτόθεν τοὺς Ἕλληνας, ἀλλὰ διετράφησαν τοῖς κτήνεσιν ἃ ἐκ τῶν Ταόχων ἔλαβον.", "st": "4.7.17"}, {"sp": "N", "t": "ἐκ τούτων οἱ Ἕλληνες ἀφίκοντο ἐπὶ Ἅρπασον ποταμόν, εὖρος τεττάρων πλέθρων. ἐντεῦθεν ἐπορεύθησαν διὰ Σκυθηνῶν σταθμοὺς τέτταρας παρασάγγας εἴκοσι διὰ πεδίου εἰς κώμας· ἐν αἷς ἔμειναν ἡμέρας τρεῖς καὶ ἐπεσιτίσαντο.", "st": "4.7.18"}, {"sp": "N", "t": "ἐντεῦθεν διῆλθον σταθμοὺς τέτταρας παρασάγγας εἴκοσι πρὸς πόλιν μεγάλην καὶ εὐδαίμονα καὶ οἰκουμένην ἣ ἐκαλεῖτο Γυμνιάς. ἐκ ταύτης τῆς χώρας ὁ ἄρχων τοῖς Ἕλλησιν ἡγεμόνα πέμπει, ὅπως διὰ τῆς ἑαυτῶν πολεμίας χώρας ἄγοι αὐτούς.", "st": "4.7.19"}, {"sp": "N", "t": "ἐλθὼν δ᾽ ἐκεῖνος λέγει ὅτι ἄξει αὐτοὺς πέντε ἡμερῶν εἰς χωρίον ὅθεν ὄψονται θάλατταν· εἰ δὲ μή, τεθνάναι ἐπηγγείλατο. καὶ ἡγούμενος ἐπειδὴ ἐνέβαλλεν εἰς τὴν [ἑαυτοῦ] πολεμίαν, παρεκελεύετο αἴθειν καὶ φθείρειν τὴν χώραν· ὧι καὶ δῆλον ἐγένετο ὅτι τούτου ἕνεκα ἔλθοι, οὐ τῆς τῶν Ἑλλήνων εὐνοίας.", "st": "4.7.20"}, {"sp": "N", "t": "καὶ ἀφικνοῦνται ἐπὶ τὸ ὄρος τῆι πέμπτηι ἡμέραι· ὄνομα δὲ τῶι ὄρει ἦν Θήχης. ἐπεὶ δὲ οἱ πρῶτοι ἐγένοντο ἐπὶ τοῦ ὄρους καὶ κατεῖδον τὴν θάλατταν, κραυγὴ πολλὴ ἐγένετο.", "st": "4.7.21"}, {"sp": "N", "t": "ἀκούσας δὲ ὁ Ξενοφῶν καὶ οἱ ὀπισθοφύλακες ὠιήθησαν ἔμπροσθεν ἄλλους ἐπιτίθεσθαι πολεμίους· εἵποντο γὰρ ὄπισθεν ἐκ τῆς καιομένης χώρας, καὶ αὐτῶν οἱ ὀπισθοφύλακες ἀπέκτεινάν τέ τινας καὶ ἐζώγρησαν ἐνέδραν ποιησάμενοι, καὶ γέρρα ἔλαβον δασειῶν βοῶν ὠμοβόεια ἀμφὶ τὰ εἴκοσιν.", "st": "4.7.22"}, {"sp": "N", "t": "ἐπειδὴ δὲ βοὴ πλείων τε ἐγίγνετο καὶ ἐγγύτερον καὶ οἱ ἀεὶ ἐπιόντες ἔθεον δρόμωι ἐπὶ τοὺς ἀεὶ βοῶντας καὶ πολλῶι μείζων ἐγίγνετο ἡ βοὴ ὅσωι δὴ πλείους ἐγίγνοντο,", "st": "4.7.23"}, {"sp": "N", "t": "ἐδόκει δὴ μεῖζόν τι εἶναι τῶι Ξενοφῶντι, καὶ ἀναβὰς ἐφ᾽ ἵππον καὶ Λύκιον καὶ τοὺς ἱππέας ἀναλαβὼν παρεβοήθει· καὶ τάχα δὴ ἀκούουσι βοώντων τῶν στρατιωτῶν «θάλαττα θάλαττα» καὶ παρεγγυώντων. ἔνθα δὴ ἔθεον πάντες καὶ οἱ ὀπισθοφύλακες, καὶ τὰ ὑποζύγια ἠλαύνετο καὶ οἱ ἵπποι.", "st": "4.7.24"}, {"sp": "N", "t": "ἐπεὶ δὲ ἀφίκοντο πάντες ἐπὶ τὸ ἄκρον, ἐνταῦθα δὴ περιέβαλλον ἀλλήλους καὶ στρατηγοὺς καὶ λοχαγοὺς δακρύοντες. καὶ ἐξαπίνης ὅτου δὴ παρεγγυήσαντος οἱ στρατιῶται φέρουσι λίθους καὶ ποιοῦσι κολωνὸν μέγαν.", "st": "4.7.25"}, {"sp": "N", "t": "ἐνταῦθα ἀνετίθεσαν δερμάτων πλῆθος ὠμοβοείων καὶ βακτηρίας καὶ τὰ αἰχμάλωτα γέρρα, καὶ ὁ ἡγεμὼν αὐτός τε κατέτεμνε τὰ γέρρα καὶ τοῖς ἄλλοις διεκελεύετο.", "st": "4.7.26"}, {"sp": "N", "t": "μετὰ ταῦτα τὸν ἡγεμόνα οἱ Ἕλληνες ἀποπέμπουσι δῶρα δόντες ἀπὸ κοινοῦ ἵππον καὶ φιάλην ἀργυρᾶν καὶ σκευὴν Περσικὴν καὶ δαρεικοὺς δέκα· ἤιτει δὲ μάλιστα τοὺς δακτυλίους, καὶ ἔλαβε πολλοὺς παρὰ τῶν στρατιωτῶν. κώμην δὲ δείξας αὐτοῖς οὗ σκηνήσουσι καὶ τὴν ὁδὸν ἣν πορεύσονται εἰς Μάκρωνας, ἐπεὶ ἑσπέρα ἐγένετο, ὤιχετο τῆς νυκτὸς ἀπιών.", "st": "4.7.27"}, {"sp": "N", "t": "ἐντεῦθεν δ᾽ ἐπορεύθησαν οἱ Ἕλληνες διὰ Μακρώνων σταθμοὺς τρεῖς παρασάγγας δέκα. τῆι πρώτηι δὲ ἡμέραι ἀφίκοντο ἐπὶ τὸν ποταμὸν ὃς ὥριζε τὴν τῶν Μακρώνων καὶ τὴν τῶν Σκυθηνῶν.", "st": "4.8.1"}, {"sp": "N", "t": "εἶχον δ᾽ ὑπὲρ δεξιῶν χωρίον οἷον χαλεπώτατον καὶ ἐξ ἀριστερᾶς ἄλλον ποταμόν, εἰς ὃν ἐνέβαλλεν ὁ ὁρίζων, δι᾽ οὗ ἔδει διαβῆναι. ἦν δὲ οὗτος δασὺς δένδρεσι παχέσι μὲν οὔ, πυκνοῖς δέ. ταῦτ᾽ ἐπεὶ προσῆλθον οἱ Ἕλληνες ἔκοπτον, σπεύδοντες ἐκ τοῦ χωρίου ὡς τάχιστα ἐξελθεῖν.", "st": "4.8.2"}, {"sp": "N", "t": "οἱ δὲ Μάκρωνες ἔχοντες γέρρα καὶ λόγχας καὶ τριχίνους χιτῶνας κατ᾽ ἀντιπέραν τῆς διαβάσεως παρατεταγμένοι ἦσαν καὶ ἀλλήλοις διεκελεύοντο καὶ λίθους εἰς τὸν ποταμὸν ἔρριπτον· ἐξικνοῦντο γὰρ οὒ οὐδ᾽ ἔβλαπτον οὐδέν.", "st": "4.8.3"}, {"sp": "N", "t": "ἔνθα δὴ προσέρχεται Ξενοφῶντι τῶν πελταστῶν ἀνὴρ Ἀθήνησι φάσκων δεδουλευκέναι, λέγων ὅτι γιγνώσκοι τὴν φωνὴν τῶν ἀνθρώπων. «καὶ οἶμαι, ἔφη, ἐμὴν ταύτην πατρίδα εἶναι· καὶ εἰ μή τι κωλύει, ἐθέλω αὐτοῖς διαλεχθῆναι.»", "st": "4.8.4"}, {"sp": "N", "t": "«ἀλλ᾽ οὐδὲν κωλύει, ἔφη, ἀλλὰ διαλέγου καὶ μάθε πρῶτον τίνες εἰσίν.» οἱ δ᾽ εἶπον ἐρωτήσαντος ὅτι Μάκρωνες. «ἐρώτα τοίνυν, ἔφη, αὐτοὺς τί ἀντιτετάχαται καὶ χρήιζουσιν ἡμῖν πολέμιοι εἶναι.»", "st": "4.8.5"}, {"sp": "N", "t": "οἱ δ᾽ ἀπεκρίναντο «ὅτι καὶ ὑμεῖς ἐπὶ τὴν ἡμετέραν χώραν ἔρχεσθε.» λέγειν ἐκέλευον οἱ στρατηγοὶ ὅτι «οὐ κακῶς γε ποιήσοντες, ἀλλὰ βασιλεῖ πολεμήσαντες ἀπερχόμεθα εἰς τὴν Ἑλλάδα, καὶ ἐπὶ θάλατταν βουλόμεθα ἀφικέσθαι.»", "st": "4.8.6"}, {"sp": "N", "t": "ἠρώτων ἐκεῖνοι εἰ δοῖεν ἂν τούτων τὰ πιστά. οἱ δ᾽ ἔφασαν καὶ δοῦναι καὶ λαβεῖν ἐθέλειν. ἐντεῦθεν διδόασιν οἱ Μάκρωνες βαρβαρικὴν λόγχην τοῖς Ἕλλησιν, οἱ δὲ Ἕλληνες ἐκείνοις Ἑλληνικήν· ταῦτα γὰρ ἔφασαν πιστὰ εἶναι· θεοὺς δ᾽ ἐπεμαρτύραντο ἀμφότεροι.", "st": "4.8.7"}, {"sp": "N", "t": "μετὰ δὲ τὰ πιστὰ εὐθὺς οἱ Μάκρωνες τὰ δένδρα συνεξέκοπτον τήν τε ὁδὸν ὡδοποίουν ὡς διαβιβάσοντες ἐν μέσοις ἀναμεμιγμένοι τοῖς Ἕλλησι, καὶ ἀγορὰν οἵαν ἐδύναντο παρεῖχον, καὶ παρήγαγον ἐν τρισὶν ἡμέραις ἕως ἐπὶ τὰ Κόλχων ὅρια κατέστησαν τοὺς Ἕλληνας.", "st": "4.8.8"}, {"sp": "N", "t": "ἐνταῦθα ἦν ὄρος μέγα, προσβατὸν δέ· καὶ ἐπὶ τούτου οἱ Κόλχοι παρατεταγμένοι ἦσαν. καὶ τὸ μὲν πρῶτον οἱ Ἕλληνες ἀντιπαρετάξαντο φάλαγγα, ὡς οὕτως ἄξοντες πρὸς τὸ ὄρος· ἔπειτα δὲ ἔδοξε τοῖς στρατηγοῖς βουλεύσασθαι συλλεγεῖσιν ὅπως ὡς κάλλιστα ἀγωνιοῦνται.", "st": "4.8.9"}, {"sp": "N", "t": "ἔλεξεν οὖν Ξενοφῶν ὅτι δοκοίη παύσαντας τὴν φάλαγγα λόχους ὀρθίους ποιῆσαι· ἡ μὲν γὰρ φάλαγξ διασπασθήσεται εὐθύς· τῆι μὲν γὰρ ἄνοδον τῆι δὲ εὔοδον εὑρήσομεν τὸ ὄρος· καὶ εὐθὺς τοῦτο ἀθυμίαν ποιήσει ὅταν τεταγμένοι εἰς φάλαγγα ταύτην διεσπασμένην ὁρῶσιν.", "st": "4.8.10"}, {"sp": "N", "t": "ἔπειτα ἢν μὲν ἐπὶ πολλῶν τεταγμένοι προσάγωμεν, περιττεύσουσιν ἡμῶν οἱ πολέμιοι καὶ τοῖς περιττοῖς χρήσονται ὅ τι ἂν βούλωνται· ἐὰν δὲ ἐπ᾽ ὀλίγων τεταγμένοι ὦμεν, οὐδὲν ἂν εἴη θαυμαστὸν εἰ διακοπείη ἡμῶν ἡ φάλαγξ ὑπὸ ἁθρόων καὶ βελῶν καὶ ἀνθρώπων πολλῶν ἐμπεσόντων· εἰ δέ πηι τοῦτο ἔσται, τῆι ὅληι φάλαγγι κακὸν ἔσται.", "st": "4.8.11"}, {"sp": "N", "t": "ἀλλά μοι δοκεῖ ὀρθίους τοὺς λόχους ποιησαμένους τοσοῦτον χωρίον κατασχεῖν διαλιπόντας τοῖς λόχοις ὅσον ἔξω τοὺς ἐσχάτους λόχους γενέσθαι τῶν πολεμίων κεράτων· καὶ οὕτως ἐσόμεθα τῆς τε τῶν πολεμίων φάλαγγος ἔξω [οἱ ἔσχατοι λόχοι], καὶ ὀρθίους ἄγοντες οἱ κράτιστοι ἡμῶν πρῶτοι προσίασιν, ἧι τε ἂν εὔοδον ἦι, ταύτηι ἕκαστος ἄξει [ὁ λόχος].", "st": "4.8.12"}, {"sp": "N", "t": "καὶ εἴς τε τὸ διαλεῖπον οὐ ῥάιδιον ἔσται τοῖς πολεμίοις εἰσελθεῖν ἔνθεν καὶ ἔνθεν λόχων ὄντων, διακόψαι τε οὐ ῥάιδιον ἔσται λόχον ὄρθιον προσιόντα. ἄν τέ τις πιέζηται τῶν λόχων, ὁ πλησίον βοηθήσει. ἤν τε εἷς πηι δυνηθῆι τῶν λόχων ἐπὶ τὸ ἄκρον ἀναβῆναι, οὐδεὶς μηκέτι μείνηι τῶν πολεμίων.", "st": "4.8.13"}, {"sp": "N", "t": "ταῦτα ἔδοξε, καὶ ἐποίουν ὀρθίους τοὺς λόχους. Ξενοφῶν δὲ ἀπιὼν ἐπὶ τὸ εὐώνυμον ἀπὸ τοῦ δεξιοῦ ἔλεγε τοῖς στρατιώταις· «ἄνδρες, οὗτοί εἰσιν οὓς ὁρᾶτε μόνοι ἔτι ἡμῖν ἐμποδὼν τὸ μὴ ἤδη εἶναι ἔνθα πάλαι σπεύδομεν· τούτους, ἤν πως δυνώμεθα, καὶ ὠμοὺς δεῖ καταφαγεῖν.»", "st": "4.8.14"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἐν ταῖς χώραις ἕκαστοι ἐγένοντο καὶ τοὺς λόχους ὀρθίους ἐποιήσαντο, ἐγένοντο μὲν λόχοι τῶν ὁπλιτῶν ἀμφὶ τοὺς ὀγδοήκοντα, ὁ δὲ λόχος ἕκαστος σχεδὸν εἰς τοὺς ἑκατόν· τοὺς δὲ πελταστὰς καὶ τοὺς τοξότας τριχῆι ἐποιήσαντο, τοὺς μὲν τοῦ εὐωνύμου ἔξω, τοὺς δὲ τοῦ δεξιοῦ, τοὺς δὲ κατὰ μέσον, σχεδὸν ἑξακοσίους ἑκάστους.", "st": "4.8.15"}, {"sp": "N", "t": "ἐκ τούτου παρηγγύησαν οἱ στρατηγοὶ εὔχεσθαι· εὐξάμενοι δὲ καὶ παιανίσαντες ἐπορεύοντο. καὶ Χειρίσοφος μὲν καὶ Ξενοφῶν καὶ οἱ σὺν αὐτοῖς πελτασταὶ τῆς τῶν πολεμίων φάλαγγος ἔξω γενόμενοι ἐπορεύοντο·", "st": "4.8.16"}, {"sp": "N", "t": "οἱ δὲ πολέμιοι ὡς εἶδον αὐτούς, ἀντιπαραθέοντες οἱ μὲν ἐπὶ τὸ δεξιὸν οἱ δὲ ἐπὶ τὸ εὐώνυμον διεσπάσθησαν, καὶ πολὺ τῆς αὑτῶν φάλαγγος ἐν τῶι μέσωι κενὸν ἐποίησαν.", "st": "4.8.17"}, {"sp": "N", "t": "οἱ δὲ κατὰ τὸ Ἀρκαδικὸν πελτασταί, ὧν ἦρχεν Αἰσχίνης ὁ Ἀκαρνάν, νομίσαντες φεύγειν ἀνακραγόντες ἔθεον· καὶ οὗτοι πρῶτοι ἐπὶ τὸ ὄρος ἀναβαίνουσι· συνεφείπετο δὲ αὐτοῖς καὶ τὸ Ἀρκαδικὸν ὁπλιτικόν, ὧν ἦρχε Κλεάνωρ ὁ Ὀρχομένιος.", "st": "4.8.18"}, {"sp": "N", "t": "οἱ δὲ πολέμιοι, ὡς ἤρξαντο θεῖν, οὐκέτι ἔστησαν, ἀλλὰ φυγῆι ἄλλος ἄλληι ἐτράπετο. οἱ δὲ Ἕλληνες ἀναβάντες ἐστρατοπεδεύοντο ἐν πολλαῖς κώμαις καὶ τἀπιτήδεια πολλὰ ἐχούσαις.", "st": "4.8.19"}, {"sp": "N", "t": "καὶ τὰ μὲν ἄλλα οὐδὲν ὅ τι καὶ ἐθαύμασαν· τὰ δὲ σμήνη πολλὰ ἦν αὐτόθι, καὶ τῶν κηρίων ὅσοι ἔφαγον τῶν στρατιωτῶν πάντες ἄφρονές τε ἐγίγνοντο καὶ ἤμουν καὶ κάτω διεχώρει αὐτοῖς καὶ ὀρθὸς οὐδεὶς ἐδύνατο ἵστασθαι, ἀλλ᾽ οἱ μὲν ὀλίγον ἐδηδοκότες σφόδρα μεθύουσιν ἐώικεσαν, οἱ δὲ πολὺ μαινομένοις, οἱ δὲ καὶ ἀποθνήισκουσιν.", "st": "4.8.20"}, {"sp": "N", "t": "ἔκειντο δὲ οὕτω πολλοὶ ὥσπερ τροπῆς γεγενημένης, καὶ πολλὴ ἦν ἀθυμία. τῆι δ᾽ ὑστεραίαι ἀπέθανε μὲν οὐδείς, ἀμφὶ δὲ τὴν αὐτήν πως ὥραν ἀνεφρόνουν· τρίτηι δὲ καὶ τετάρτηι ἀνίσταντο ὥσπερ ἐκ φαρμακοποσίας.", "st": "4.8.21"}, {"sp": "N", "t": "ἐντεῦθεν δ᾽ ἐπορεύθησαν δύο σταθμοὺς παρασάγγας ἑπτά, καὶ ἦλθον ἐπὶ θάλατταν εἰς Τραπεζοῦντα πόλιν Ἑλληνίδα οἰκουμένην ἐν τῶι Εὐξείνωι Πόντωι, Σινωπέων ἀποικίαν, ἐν τῆι Κόλχων χώραι. ἐνταῦθα ἔμειναν ἡμέρας ἀμφὶ τὰς τριάκοντα ἐν ταῖς τῶν Κόλχων κώμαις·", "st": "4.8.22"}, {"sp": "N", "t": "κἀντεῦθεν ὁρμώμενοι ἐλήιζοντο τὴν Κολχίδα. ἀγορὰν δὲ παρεῖχον τῶι στρατοπέδωι Τραπεζούντιοι, καὶ ἐδέξαντό τε τοὺς Ἕλληνας καὶ ξένια ἔδοσαν βοῦς καὶ ἄλφιτα καὶ οἶνον.", "st": "4.8.23"}, {"sp": "N", "t": "συνδιεπράττοντο δὲ καὶ ὑπὲρ τῶν πλησίον Κόλχων τῶν ἐν τῶι πεδίωι μάλιστα οἰκούντων, καὶ ξένια καὶ παρ᾽ ἐκείνων ἦλθον βόες.", "st": "4.8.24"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο τὴν θυσίαν ἣν ηὔξαντο παρεσκευάζοντο· ἦλθον δ᾽ αὐτοῖς ἱκανοὶ βόες ἀποθῦσαι τῶι Διὶ τῶι σωτῆρι καὶ τῶι Ἡρακλεῖ ἡγεμόσυνα καὶ τοῖς ἄλλοις θεοῖς ἃ ηὔξαντο. ἐποίησαν δὲ καὶ ἀγῶνα γυμνικὸν ἐν τῶι ὄρει ἔνθαπερ ἐσκήνουν. εἵλοντο δὲ Δρακόντιον Σπαρτιάτην, ὃς ἔφυγε παῖς ὢν οἴκοθεν, παῖδα ἄκων κατακανὼν ξυήληι πατάξας, δρόμου τ᾽ ἐπιμεληθῆναι καὶ τοῦ ἀγῶνος προστατῆσαι.", "st": "4.8.25"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἡ θυσία ἐγένετο, τὰ δέρματα παρέδοσαν τῶι Δρακοντίωι, καὶ ἡγεῖσθαι ἐκέλευον ὅπου τὸν δρόμον πεποιηκὼς εἴη. ὁ δὲ δείξας οὗπερ ἑστηκότες ἐτύγχανον «οὗτος ὁ λόφος, ἔφη, κάλλιστος τρέχειν ὅπου ἄν τις βούληται.» «πῶς οὖν, ἔφασαν, δυνήσονται παλαίειν ἐν σκληρῶι καὶ δασεῖ οὕτως;» ὁ δ᾽ εἶπε· «μᾶλλόν τι ἀνιάσεται ὁ καταπεσών.»", "st": "4.8.26"}, {"sp": "N", "t": "ἠγωνίζοντο δὲ παῖδες μὲν στάδιον τῶν αἰχμαλώτων οἱ πλεῖστοι, δόλιχον δὲ Κρῆτες πλείους ἢ ἑξήκοντα ἔθεον, πάλην δὲ καὶ πυγμὴν καὶ παγκράτιον ἕτεροι, καὶ καλὴ θέα ἐγένετο· πολλοὶ γὰρ κατέβησαν καὶ ἅτε θεωμένων τῶν ἑταίρων πολλὴ φιλονικία ἐγίγνετο.", "st": "4.8.27"}, {"sp": "N", "t": "ἔθεον δὲ καὶ ἵπποι καὶ ἔδει αὐτοὺς κατὰ τοῦ πρανοῦς ἐλάσαντας ἐν τῆι θαλάττηι ἀποστρέψαντας πάλιν πρὸς τὸν βωμὸν ἄγειν. καὶ κάτω μὲν οἱ πολλοὶ ἐκαλινδοῦντο· ἄνω δὲ πρὸς τὸ ἰσχυρῶς ὄρθιον μόλις βάδην ἐπορεύοντο οἱ ἵπποι· ἔνθα πολλὴ κραυγὴ καὶ γέλως καὶ παρακέλευσις ἐγίγνετο.", "st": "4.8.28"}, {"sp": "HDR", "t": "Βιβλίον εʹ", "st": "5.1.1"}, {"sp": "N", "t": "[ Ὅσα μὲν δὴ ἐν τῆι ἀναβάσει τῆι μετὰ Κύρου ἔπραξαν οἱ Ἕλληνες, καὶ ἐν τῆι πορείαι τῆι μέχρι ἐπὶ θάλατταν τὴν ἐν τῶι Εὐξείνωι Πόντωι, καὶ ὡς εἰς Τραπεζοῦντα Ἑλληνίδα πόλιν ἀφίκοντο, καὶ ὡς ἀπέθυσαν ἃ εὔξαντο σωτήρια θύειν ἔνθα πρῶτον εἰς φιλίαν γῆν ἀφίκοντο, ἐν τῶι πρόσθεν λόγωι δεδήλωται.]", "st": "5.1.1"}, {"sp": "N", "t": "Ἐκ δὲ τούτου ξυνελθόντες ἐβουλεύοντο περὶ τῆς λοιπῆς πορείας· ἀνέστη δὲ πρῶτος Λέων Θούριος καὶ ἔλεξεν ὧδε. «ἐγὼ μὲν τοίνυν, ἔφη, ὦ ἄνδρες, ἀπείρηκα ἤδη ξυσκευαζόμενος καὶ βαδίζων καὶ τρέχων καὶ τὰ ὅπλα φέρων καὶ ἐν τάξει ὢν καὶ φυλακὰς φυλάττων καὶ μαχόμενος, ἐπιθυμῶ δὲ ἤδη παυσάμενος τούτων τῶν πόνων, ἐπεὶ θάλατταν ἔχομεν, πλεῖν τὸ λοιπὸν καὶ ἐκταθεὶς ὥσπερ Ὀδυσσεὺς ἀφικέσθαι εἰς τὴν Ἑλλάδα.»", "st": "5.1.2"}, {"sp": "N", "t": "ταῦτα ἀκούσαντες οἱ στρατιῶται ἀνεθορύβησαν ὡς εὖ λέγει· καὶ ἄλλος ταὔτ᾽ ἔλεγε, καὶ πάντες οἱ παριόντες. ἔπειτα δὲ Χειρίσοφος ἀνέστη καὶ εἶπεν ὧδε.", "st": "5.1.3"}, {"sp": "N", "t": "«φίλος μοί ἐστιν, ὦ ἄνδρες, Ἀναξίβιος, ναυαρχῶν δὲ καὶ τυγχάνει. ἢν οὖν πέμψητέ με, οἴομαι ἂν ἐλθεῖν καὶ τριήρεις ἔχων καὶ πλοῖα τὰ ἡμᾶς ἄξοντα· ὑμεῖς δὲ εἴπερ πλεῖν βούλεσθε, περιμένετε ἔστ᾽ ἂν ἐγὼ ἔλθω· ἥξω δὲ ταχέως.» ἀκούσαντες ταῦτα οἱ στρατιῶται ἥσθησάν τε καὶ ἐψηφίσαντο πλεῖν αὐτὸν ὡς τάχιστα.", "st": "5.1.4"}, {"sp": "N", "t": "μετὰ τοῦτον Ξενοφῶν ἀνέστη καὶ ἔλεξεν ὧδε. Χειρίσοφος μὲν δὴ ἐπὶ πλοῖα στέλλεται, ἡμεῖς δὲ ἀναμενοῦμεν. ὅσα μοι οὖν δοκεῖ καιρὸς εἶναι ποιεῖν ἐν τῆι μονῆι, ταῦτα ἐρῶ.", "st": "5.1.5"}, {"sp": "N", "t": "πρῶτον μὲν τὰ ἐπιτήδεια δεῖ πορίζεσθαι ἐκ τῆς πολεμίας· οὔτε γὰρ ἀγορὰ ἔστιν ἱκανὴ οὔτε ὅτου ὠνησόμεθα εὐπορία εἰ μὴ ὀλίγοις τισίν· ἡ δὲ χώρα πολεμία· κίνδυνος οὖν πολλοὺς ἀπόλλυσθαι, ἢν ἀμελῶς τε καὶ ἀφυλάκτως πορεύησθε ἐπὶ τὰ ἐπιτήδεια.", "st": "5.1.6"}, {"sp": "N", "t": "ἀλλά μοι δοκεῖ σὺν προνομαῖς λαμβάνειν τὰ ἐπιτήδεια, ἄλλως δὲ μὴ πλανᾶσθαι, ὡς σώιζησθε, ἡμᾶς δὲ τούτων ἐπιμελεῖσθαι.", "st": "5.1.7"}, {"sp": "N", "t": "ἔδοξε ταῦτα. «ἔτι τοίνυν ἀκούσατε καὶ τάδε. ἐπὶ λείαν γὰρ ὑμῶν ἐκπορεύσονταί τινες. οἴομαι οὖν βέλτιστον εἶναι ἡμῖν εἰπεῖν τὸν μέλλοντα ἐξιέναι, φράζειν δὲ καὶ ὅποι, ἵνα καὶ τὸ πλῆθος εἰδῶμεν τῶν ἐξιόντων καὶ τῶν μενόντων καὶ ξυμπαρασκευάζωμεν, ἐάν τι δέηι, κἂν βοηθῆσαί τισι καιρὸς ἦι, εἰδῶμεν ὅποι δεήσει βοηθεῖν, καὶ ἐάν τις τῶν ἀπειροτέρων ἐγχειρῆι ποι, ξυμβουλεύωμεν πειρώμενοι εἰδέναι τὴν δύναμιν ἐφ᾽ οὓς ἂν ἴωσιν.»", "st": "5.1.8"}, {"sp": "N", "t": "ἔδοξε καὶ ταῦτα. «ἐννοεῖτε δὴ καὶ τόδε, ἔφη. σχολὴ τοῖς πολεμίοις λήιζεσθαι, καὶ δικαίως ἡμῖν ἐπιβουλεύουσιν· ἔχομεν γὰρ τὰ ἐκείνων· ὑπερκάθηνται δὲ ἡμῶν. φυλακὰς δή μοι δοκεῖ δεῖν περὶ τὸ στρατόπεδον εἶναι· ἐὰν οὖν κατὰ μέρος [μερισθέντες] φυλάττωμεν καὶ σκοπῶμεν, ἧττον ἂν δύναιντο ἡμᾶς θηρᾶν οἱ πολέμιοι. ἔτι τοίνυν τάδε ὁρᾶτε.", "st": "5.1.9"}, {"sp": "N", "t": "εἰ μὲν ἠπιστάμεθα σαφῶς ὅτι ἥξει πλοῖα Χειρίσοφος ἄγων ἱκανά, οὐδὲν ἂν ἔδει ὧν μέλλω λέγειν· νῦν δ᾽ ἐπεὶ τοῦτο ἄδηλον, δοκεῖ μοι πειρᾶσθαι πλοῖα συμπαρασκευάζειν καὶ αὐτόθεν. ἢν μὲν γὰρ ἔλθηι, ὑπαρχόντων ἐνθάδε ἐν ἀφθονωτέροις πλευσόμεθα· ἢν δὲ μὴ ἄγηι, τοῖς ἐνθάδε χρησόμεθα.", "st": "5.1.10"}, {"sp": "N", "t": "ὁρῶ δὲ ἐγὼ πλοῖα πολλάκις παραπλέοντα· εἰ οὖν αἰτησάμενοι παρὰ Τραπεζουντίων μακρὰ πλοῖα κατάγοιμεν καὶ φυλάττοιμεν αὐτά, τὰ πηδάλια παραλυόμενοι, ἕως ἂν ἱκανὰ τὰ ἄξοντα γένηται, ἴσως ἂν οὐκ ἀπορήσαιμεν κομιδῆς οἵας δεόμεθα.» ἔδοξε καὶ ταῦτα.", "st": "5.1.11"}, {"sp": "N", "t": "«ἐννοήσατε δ᾽, ἔφη, εἰ εἰκὸς καὶ τρέφειν ἀπὸ κοινοῦ οὓς ἂν καταγάγωμεν ὅσον ἂν χρόνον ἡμῶν ἕνεκεν μένωσι, καὶ ναῦλον ξυνθέσθαι, ὅπως ὠφελοῦντες καὶ ὠφελῶνται.» ἔδοξε καὶ ταῦτα.", "st": "5.1.12"}, {"sp": "N", "t": "«δοκεῖ τοίνυν μοι, ἔφη, ἢν ἄρα καὶ ταῦτα ἡμῖν μὴ ἐκπεραίνηται ὥστε ἀρκεῖν πλοῖα, τὰς ὁδοὺς ἃς δυσπόρους ἀκούομεν εἶναι ταῖς παρὰ θάλατταν οἰκούσαις πόλεσιν ἐντείλασθαι ὁδοποιεῖν· πείσονται γὰρ καὶ διὰ τὸ φοβεῖσθαι καὶ διὰ τὸ βούλεσθαι ἡμῶν ἀπαλλαγῆναι.»", "st": "5.1.13"}, {"sp": "N", "t": "ἐνταῦθα δὲ ἀνέκραγον ὡς οὐ δέοι ὁδοιπορεῖν. ὁ δὲ ὡς ἔγνω τὴν ἀφροσύνην αὐτῶν, ἐπεψήφισε μὲν οὐδέν, τὰς δὲ πόλεις ἑκούσας ἔπεισεν ὁδοποιεῖν, λέγων ὅτι θᾶττον ἀπαλλάξονται, ἢν εὔποροι γένωνται αἱ ὁδοί.", "st": "5.1.14"}, {"sp": "N", "t": "ἔλαβον δὲ καὶ πεντηκόντορον παρὰ τῶν Τραπεζουντίων, ἧι ἐπέστησαν Δέξιππον Λάκωνα περίοικον. οὗτος ἀμελήσας τοῦ ξυλλέγειν πλοῖα ἀποδρὰς ὤιχετο ἔξω τοῦ Πόντου, ἔχων τὴν ναῦν. οὗτος μὲν οὖν δίκαια ἔπαθεν ὕστερον· ἐν Θράικηι γὰρ παρὰ Σεύθηι πολυπραγμονῶν τι ἀπέθανεν ὑπὸ Νικάνδρου τοῦ Λάκωνος.", "st": "5.1.15"}, {"sp": "N", "t": "ἔλαβον δὲ καὶ τριακόντορον, ἧι ἐπεστάθη Πολυκράτης Ἀθηναῖος, ὃς ὁπόσα λαμβάνοι πλοῖα κατῆγεν ἐπὶ τὸ στρατόπεδον. καὶ τὰ μὲν ἀγώγιμα εἴ τι ἦγον ἐξαιρούμενοι φύλακας καθίστασαν, ὅπως σῶια εἴη, τοῖς δὲ πλοίοις ἐχρήσαντο εἰς παραγωγήν.", "st": "5.1.16"}, {"sp": "N", "t": "ἐν ὧι δὲ ταῦτα ἦν ἐπὶ λείαν ἐξῆισαν οἱ Ἕλληνες, καὶ οἱ μὲν ἐλάμβανον οἱ δὲ καὶ οὔ. Κλεαίνετος δ᾽ ἐξαγαγὼν καὶ τὸν ἑαυτοῦ καὶ ἄλλον λόχον πρὸς χωρίον χαλεπὸν αὐτός τε ἀπέθανε καὶ ἄλλοι πολλοὶ τῶν σὺν αὐτῶι.", "st": "5.1.17"}, {"sp": "N", "t": "ἐπεὶ δὲ τὰ ἐπιτήδεια οὐκέτι ἦν λαμβάνειν ὥστε ἀπαυθημερίζειν ἐπὶ τὸ στρατόπεδον, ἐκ τούτου λαβὼν Ξενοφῶν ἡγεμόνας τῶν Τραπεζουντίων ἐξάγει εἰς Δρίλας τὸ ἥμισυ τοῦ στρατεύματος, τὸ δὲ ἥμισυ κατέλιπε φυλάττειν τὸ στρατόπεδον· οἱ γὰρ Κόλχοι, ἅτε ἐκπεπτωκότες τῶν οἰκιῶν, πολλοὶ ἦσαν ἁθρόοι καὶ ὑπερεκάθηντο ἐπὶ τῶν ἄκρων.", "st": "5.2.1"}, {"sp": "N", "t": "οἱ δὲ Τραπεζούντιοι ὁπόθεν μὲν τὰ ἐπιτήδεια ῥάιδιον ἦν λαβεῖν οὐκ ἦγον· φίλοι γὰρ αὐτοῖς ἦσαν· εἰς δὲ τοὺς Δρίλας προθύμως ἦγον, ὑφ᾽ ὧν κακῶς ἔπασχον, εἰς χωρία τε ὀρεινὰ καὶ δύσβατα καὶ ἀνθρώπους πολεμικωτάτους τῶν ἐν τῶι Πόντωι.", "st": "5.2.2"}, {"sp": "N", "t": "ἐπεὶ δὲ ἦσαν ἐν τῆι ἄνω χώραι οἱ Ἕλληνες, ὁποῖα τῶν χωρίων τοῖς Δρίλαις ἁλώσιμα εἶναι ἐδόκει ἐμπιμπράντες ἀπῆισαν· καὶ οὐδὲν ἦν λαμβάνειν εἰ μὴ ὗς ἢ βοῦς ἢ ἄλλο τι κτῆνος τὸ πῦρ διαπεφευγός. ἓν δὲ ἦν χωρίον μητρόπολις αὐτῶν· εἰς τοῦτο πάντες ξυνερρυήκεσαν. περὶ δὲ τοῦτο ἦν χαράδρα ἰσχυρῶς βαθεῖα, καὶ πρόσοδοι χαλεπαὶ πρὸς τὸ χωρίον.", "st": "5.2.3"}, {"sp": "N", "t": "οἱ δὲ πελτασταὶ προδραμόντες στάδια πέντε ἢ ἓξ τῶν ὁπλιτῶν, διαβάντες τὴν χαράδραν, ὁρῶντες πρόβατα πολλὰ καὶ ἄλλα χρήματα προσέβαλλον πρὸς τὸ χωρίον· ξυνείποντο δὲ καὶ δορυφόροι πολλοὶ οἱ ἐπὶ τὰ ἐπιτήδεια ἐξωρμημένοι· ὥστε ἐγένοντο οἱ διαβάντες πλείους ἢ δισχίλιοι ἄνθρωποι.", "st": "5.2.4"}, {"sp": "N", "t": "ἐπεὶ δὲ μαχόμενοι οὐκ ἐδύναντο λαβεῖν τὸ χωρίον (καὶ γὰρ τάφρος ἦν περὶ αὐτὸ εὐρεῖα ἀναβεβλημένη καὶ σκόλοπες ἐπὶ τῆς ἀναβολῆς καὶ τύρσεις πυκναὶ ξύλιναι πεποιημέναι), ἀπιέναι δὴ ἐπεχείρουν· οἱ δὲ ἐπέκειντο αὐτοῖς.", "st": "5.2.5"}, {"sp": "N", "t": "ὡς δὲ οὐκ ἐδύναντο ἀποτρέχειν (ἦν γὰρ ἐφ᾽ ἑνὸς ἡ κατάβασις ἐκ τοῦ χωρίου εἰς τὴν χαράδραν), πέμπουσι πρὸς Ξενοφῶντα· ὁ δὲ ἡγεῖτο τοῖς ὁπλίταις.", "st": "5.2.6"}, {"sp": "N", "t": "ὁ δὲ ἐλθὼν λέγει ὅτι ἔστι χωρίον χρημάτων πολλῶν μεστόν· τοῦτο οὔτε λαβεῖν δυνάμεθα· ἰσχυρὸν γάρ ἐστιν· οὔτε ἀπελθεῖν ῥάιδιον· μάχονται γὰρ ἐπεξεληλυθότες καὶ ἡ ἄφοδος χαλεπή.", "st": "5.2.7"}, {"sp": "N", "t": "ἀκούσας ταῦτα ὁ Ξενοφῶν προσαγαγὼν πρὸς τὴν χαράδραν τοὺς μὲν ὁπλίτας θέσθαι ἐκέλευσε τὰ ὅπλα, αὐτὸς δὲ διαβὰς σὺν τοῖς λοχαγοῖς ἐσκοπεῖτο πότερον εἴη κρεῖττον ἀπαγαγεῖν καὶ τοὺς διαβεβηκότας ἢ καὶ τοὺς ὁπλίτας διαβιβάζειν, ὡς ἁλόντος ἂν τοῦ χωρίου.", "st": "5.2.8"}, {"sp": "N", "t": "ἐδόκει γὰρ τὸ μὲν ἀπαγαγεῖν οὐκ εἶναι ἄνευ πολλῶν νεκρῶν, ἑλεῖν δ᾽ ἂν ὤιοντο καὶ οἱ λοχαγοὶ τὸ χωρίον, καὶ ὁ Ξενοφῶν ξυνεχώρησε τοῖς ἱεροῖς πιστεύσας· οἱ γὰρ μάντεις ἀποδεδειγμένοι ἦσαν ὅτι μάχη μὲν ἔσται, τὸ δὲ τέλος καλὸν τῆς ἐξόδου.", "st": "5.2.9"}, {"sp": "N", "t": "καὶ τοὺς μὲν λοχαγοὺς ἔπεμπε διαβιβάσοντας τοὺς ὁπλίτας, αὐτὸς δ᾽ ἔμενεν ἀναχωρίσας ἅπαντας τοὺς πελταστάς, καὶ οὐδένα εἴα ἀκροβολίζεσθαι.", "st": "5.2.10"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἧκον οἱ ὁπλῖται, ἐκέλευσε τὸν λόχον ἕκαστον ποιῆσαι τῶν λοχαγῶν ὡς ἂν κράτιστα οἴηται ἀγωνιεῖσθαι· ἦσαν γὰρ οἱ λοχαγοὶ πλησίον ἀλλήλων οἳ πάντα τὸν χρόνον ἀλλήλοις περὶ ἀνδραγαθίας ἀντεποιοῦντο.", "st": "5.2.11"}, {"sp": "N", "t": "καὶ οἱ μὲν ταῦτ᾽ ἐποίουν· ὁ δὲ τοῖς πελτασταῖς πᾶσι παρήγγειλε διηγκυλωμένους ἰέναι, ὡς, ὁπόταν σημήνηι, ἀκοντίζειν, καὶ τοὺς τοξότας ἐπιβεβλῆσθαι ἐπὶ ταῖς νευραῖς, ὡς, ὁπόταν σημήνηι, τοξεύειν δεῆσον, καὶ τοὺς γυμνῆτας λίθων ἔχειν μεστὰς τὰς διφθέρας· καὶ τοὺς ἐπιτηδείους ἔπεμψε τούτων ἐπιμεληθῆναι.", "st": "5.2.12"}, {"sp": "N", "t": "ἐπεὶ δὲ πάντα παρεσκεύαστο καὶ οἱ λοχαγοὶ καὶ οἱ ὑπολόχαγοι καὶ οἱ ἀξιοῦντες τούτων μὴ χείρους εἶναι πάντες παρατεταγμένοι ἦσαν, καὶ ἀλλήλους μὲν δὴ ξυνεώρων (μηνοειδὴς γὰρ διὰ τὸ χωρίον ἡ τάξις ἦν)·", "st": "5.2.13"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἐπαιάνισαν καὶ ἡ σάλπιγξ ἐφθέγξατο, ἅμα τε τῶι Ἐνυαλίωι ἠλέλιξαν καὶ ἔθεον δρόμωι οἱ ὁπλῖται, καὶ τὰ βέλη ὁμοῦ ἐφέρετο, λόγχαι, τοξεύματα, σφενδόναι, πλεῖστοι δ᾽ ἐκ τῶν χειρῶν λίθοι, ἦσαν δὲ οἳ καὶ πῦρ προσέφερον.", "st": "5.2.14"}, {"sp": "N", "t": "ὑπὸ δὲ τοῦ πλήθους τῶν βελῶν ἔλιπον οἱ πολέμιοι τά τε σταυρώματα καὶ τὰς τύρσεις· ὥστε Ἀγασίας Στυμφάλιος καταθέμενος τὰ ὅπλα ἐν χιτῶνι μόνον ἀνέβη, καὶ ἄλλος ἄλλον εἷλκε, καὶ ἄλλος ἀνεβεβήκει, καὶ ἡλώκει τὸ χωρίον, ὡς ἐδόκει.", "st": "5.2.15"}, {"sp": "N", "t": "καὶ οἱ μὲν πελτασταὶ καὶ οἱ ψιλοὶ ἐσδραμόντες ἥρπαζον ὅ τι ἕκαστος ἐδύνατο· ὁ δὲ Ξενοφῶν στὰς κατὰ τὰς πύλας ὁπόσους ἐδύνατο κατεκώλυε τῶν ὁπλιτῶν ἔξω· πολέμιοι γὰρ ἄλλοι ἐφαίνοντο ἐπ᾽ ἄκροις τισὶν ἰσχυροῖς.", "st": "5.2.16"}, {"sp": "N", "t": "οὐ πολλοῦ δὲ χρόνου μεταξὺ γενομένου κραυγή τε ἐγένετο ἔνδον καὶ ἔφευγον οἱ μὲν καὶ ἔχοντες ἃ ἔλαβον, τάχα δέ τις καὶ τετρωμένος· καὶ πολὺς ἦν ὠθισμὸς ἀμφὶ τὰ θύρετρα. καὶ ἐρωτώμενοι οἱ ἐκπίπτοντες ἔλεγον ὅτι ἄκρα τέ ἐστιν ἔνδον καὶ οἱ πολέμιοι πολλοί, οἳ παίουσιν ἐκδεδραμηκότες τοὺς ἔνδον ἀνθρώπους.", "st": "5.2.17"}, {"sp": "N", "t": "ἐνταῦθα ἀνειπεῖν ἐκέλευσε Τολμίδην τὸν κήρυκα ἰέναι εἴσω τὸν βουλόμενόν τι λαμβάνειν. καὶ ἵενται πολλοὶ εἴσω, καὶ νικῶσι τοὺς ἐκπίπτοντας οἱ εἰσωθούμενοι καὶ κατακλείουσι τοὺς πολεμίους πάλιν εἰς τὴν ἄκραν.", "st": "5.2.18"}, {"sp": "N", "t": "καὶ τὰ μὲν ἔξω τῆς ἄκρας πάντα διηρπάσθη, καὶ ἐξεκομίσαντο οἱ Ἕλληνες· οἱ δὲ ὁπλῖται ἔθεντο τὰ ὅπλα, οἱ μὲν περὶ τὰ σταυρώματα, οἱ δὲ κατὰ τὴν ὁδὸν τὴν ἐπὶ τὴν ἄκραν φέρουσαν.", "st": "5.2.19"}, {"sp": "N", "t": "ὁ δὲ Ξενοφῶν καὶ οἱ λοχαγοὶ ἐσκόπουν εἰ οἷόν τε εἴη τὴν ἄκραν λαβεῖν· ἦν γὰρ οὕτως σωτηρία ἀσφαλής, ἄλλως δὲ πάνυ χαλεπὸν ἐδόκει εἶναι ἀπελθεῖν· σκοπουμένοις δὲ αὐτοῖς ἔδοξε παντάπασιν ἀνάλωτον εἶναι τὸ χωρίον.", "st": "5.2.20"}, {"sp": "N", "t": "ἐνταῦθα παρεσκευάζοντο τὴν ἄφοδον, καὶ τοὺς μὲν σταυροὺς ἕκαστοι τοὺς καθ᾽ αὑτοὺς διήιρουν, καὶ τοὺς ἀχρείους καὶ φορτία ἔχοντάς τε ἐξεπέμποντο καὶ τῶν ὁπλιτῶν τὸ πλῆθος, καταλιπόντες οἱ λοχαγοὶ οἷς ἕκαστος ἐπίστευεν.", "st": "5.2.21"}, {"sp": "N", "t": "ἐπεὶ δὲ ἤρξαντο ἀποχωρεῖν, ἐπεξέθεον ἔνδοθεν πολλοὶ γέρρα καὶ λόγχας ἔχοντες καὶ κνημῖδας καὶ κράνη Παφλαγονικά, καὶ ἄλλοι ἐπὶ τὰς οἰκίας ἀνέβαινον τὰς ἔνθεν καὶ ἔνθεν τῆς εἰς τὴν ἄκραν φερούσης ὁδοῦ·", "st": "5.2.22"}, {"sp": "N", "t": "ὥστε οὐδὲ διώκειν ἀσφαλὲς ἦν κατὰ τὰς πύλας τὰς εἰς τὴν ἄκραν φερούσας. καὶ γὰρ ξύλα μεγάλα ἐπερρίπτουν ἄνωθεν, ὥστε χαλεπὸν ἦν καὶ μένειν καὶ ἀπιέναι· καὶ ἡ νὺξ φοβερὰ ἦν ἡ ἐπιοῦσα.", "st": "5.2.23"}, {"sp": "N", "t": "μαχομένων δὲ αὐτῶν καὶ ἀπορουμένων θεῶν τις αὐτοῖς μηχανὴν σωτηρίας δίδωσιν. ἐξαπίνης γὰρ ἀνέλαμψεν οἰκία τῶν ἐν δεξιᾶι ὅτου δὴ ἐνάψαντος. ὡς δ᾽ αὕτη ξυνέπιπτεν, ἔφευγον οἱ ἀπὸ τῶν ἐν δεξιᾶι οἰκιῶν.", "st": "5.2.24"}, {"sp": "N", "t": "ὡς δὲ ἔμαθεν ὁ Ξενοφῶν τοῦτο παρὰ τῆς τύχης, ἐνάπτειν ἐκέλευε καὶ τὰς ἐν ἀριστερᾶι οἰκίας, αἳ ξύλιναι ἦσαν, ὥστε καὶ ταχὺ ἐκαίοντο.", "st": "5.2.25"}, {"sp": "N", "t": "ἔφευγον οὖν καὶ οἱ ἀπὸ τούτων τῶν οἰκιῶν. οἱ δὲ κατὰ στόμα δὴ ἔτι μόνοι ἐλύπουν καὶ δῆλοι ἦσαν ὅτι ἐπικείσονται ἐν τῆι ἐξόδωι τε καὶ καταβάσει. ἐνταῦθα παραγγέλλει φέρειν ξύλα ὅσοι ἐτύγχανον ἔξω ὄντες τῶν βελῶν εἰς τὸ μέσον ἑαυτῶν καὶ τῶν πολεμίων. ἐπεὶ δὲ ἱκανὰ ἤδη ἦν, ἐνῆψαν· ἐνῆπτον δὲ καὶ τὰς παρ᾽ αὐτὸ τὸ χαράκωμα οἰκίας, ὅπως οἱ πολέμιοι ἀμφὶ ταῦτα ἔχοιεν.", "st": "5.2.26"}, {"sp": "N", "t": "οὕτω μόλις ἀπῆλθον ἀπὸ τοῦ χωρίου, πῦρ ἐν μέσωι ἑαυτῶν καὶ τῶν πολεμίων ποιησάμενοι. καὶ κατεκαύθη πᾶσα ἡ πόλις καὶ αἱ οἰκίαι καὶ αἱ τύρσεις καὶ τὰ σταυρώματα καὶ τἆλλα πάντα πλὴν τῆς ἄκρας.", "st": "5.2.27"}, {"sp": "N", "t": "τῆι δὲ ὑστεραίαι ἀπῆισαν οἱ Ἕλληνες ἔχοντες τὰ ἐπιτήδεια. ἐπεὶ δὲ τὴν κατάβασιν ἐφοβοῦντο τὴν εἰς Τραπεζοῦντα (πρανὴς γὰρ ἦν καὶ στενή), ψευδενέδραν ἐποιήσαντο·", "st": "5.2.28"}, {"sp": "N", "t": "καὶ ἀνὴρ Μυσὸς καὶ τοὔνομα τοῦτο ἔχων τῶν Κρητῶν λαβὼν δέκα ἔμενεν ἐν λασίωι χωρίωι καὶ προσεποιεῖτο τοὺς πολεμίους πειρᾶσθαι λανθάνειν· αἱ δὲ πέλται αὐτῶν ἄλλοτε καὶ ἄλλοτε διεφαίνοντο χαλκαῖ οὖσαι.", "st": "5.2.29"}, {"sp": "N", "t": "οἱ μὲν οὖν πολέμιοι ταῦτα διορῶντες ἐφοβοῦντο ὡς ἐνέδραν οὖσαν· ἡ δὲ στρατιὰ ἐν τούτωι κατέβαινεν. ἐπεὶ δὲ ἐδόκει ἤδη ἱκανὸν ὑπεληλυθέναι, τῶι Μυσῶι ἐσήμηνε φεύγειν ἀνὰ κράτος· καὶ ὃς ἐξαναστὰς φεύγει καὶ οἱ σὺν αὐτῶι.", "st": "5.2.30"}, {"sp": "N", "t": "καὶ οἱ μὲν ἄλλοι Κρῆτες (ἁλίσκεσθαι γὰρ ἔφασαν τῶι δρόμωι), ἐκπεσόντες ἐκ τῆς ὁδοῦ εἰς ὕλην κατὰ τὰς νάπας καλινδούμενοι ἐσώθησαν, ὁ Μυσὸς δὲ κατὰ τὴν ὁδὸν φεύγων ἐβόα βοηθεῖν·", "st": "5.2.31"}, {"sp": "N", "t": "καὶ ἐβοήθησαν αὐτῶι, καὶ ἀνέλαβον τετρωμένον. καὶ αὐτοὶ ἐπὶ πόδα ἀνεχώρουν βαλλόμενοι οἱ βοηθήσαντες καὶ ἀντιτοξεύοντές τινες τῶν Κρητῶν. οὕτως ἀφίκοντο ἐπὶ τὸ στρατόπεδον πάντες σῶιοι ὄντες.", "st": "5.2.32"}, {"sp": "N", "t": "ἐπεὶ δὲ οὔτε Χειρίσοφος ἧκεν οὔτε πλοῖα ἱκανὰ ἦν οὔτε τὰ ἐπιτήδεια ἦν λαμβάνειν ἔτι, ἐδόκει ἀπιτέον εἶναι. καὶ εἰς μὲν τὰ πλοῖα τούς τε ἀσθενοῦντας ἐνεβίβασαν καὶ τοὺς ὑπὲρ τετταράκοντα ἔτη καὶ παῖδας καὶ γυναῖκας καὶ τῶν σκευῶν ὅσα μὴ ἀνάγκη ἦν ἔχειν. καὶ Φιλήσιον καὶ Σοφαίνετον τοὺς πρεσβυτάτους τῶν στρατηγῶν εἰσβιβάσαντες τούτων ἐκέλευον ἐπιμελεῖσθαι· οἱ δὲ ἄλλοι ἐπορεύοντο· ἡ δὲ ὁδὸς ὡδοποιημένη ἦν.", "st": "5.3.1"}, {"sp": "N", "t": "καὶ ἀφικνοῦνται πορευόμενοι εἰς Κερασοῦντα τριταῖοι πόλιν Ἑλληνίδα ἐπὶ θαλάττηι Σινωπέων ἄποικον ἐν τῆι Κολχίδι χώραι.", "st": "5.3.2"}, {"sp": "N", "t": "ἐνταῦθα ἔμειναν ἡμέρας δέκα· καὶ ἐξέτασις σὺν τοῖς ὅπλοις ἐγίγνετο καὶ ἀριθμός, καὶ ἐγένοντο ὀκτακισχίλιοι καὶ ἑξακόσιοι. οὗτοι ἐσώθησαν. οἱ δὲ ἄλλοι ἀπώλοντο ὑπό τε τῶν πολεμίων καὶ χιόνος καὶ εἴ τις νόσωι.", "st": "5.3.3"}, {"sp": "N", "t": "ἐνταῦθα καὶ διαλαμβάνουσι τὸ ἀπὸ τῶν αἰχμαλώτων ἀργύριον γενόμενον. καὶ τὴν δεκάτην, ἣν τῶι Ἀπόλλωνι ἐξεῖλον καὶ τῆι Ἐφεσίαι Ἀρτέμιδι, διέλαβον οἱ στρατηγοὶ τὸ μέρος ἕκαστος φυλάττειν τοῖς θεοῖς· ἀντὶ δὲ Χειρισόφου Νέων ὁ Ἀσιναῖος ἔλαβε.", "st": "5.3.4"}, {"sp": "N", "t": "Ξενοφῶν οὖν τὸ μὲν τοῦ Ἀπόλλωνος ἀνάθημα ποιησάμενος ἀνατίθησιν εἰς τὸν ἐν Δελφοῖς τῶν Ἀθηναίων θησαυρὸν καὶ ἐπέγραψε τό τε αὑτοῦ ὄνομα καὶ τὸ Προξένου, ὃς σὺν Κλεάρχωι ἀπέθανεν· ξένος γὰρ ἦν αὐτοῦ.", "st": "5.3.5"}, {"sp": "N", "t": "τὸ δὲ τῆς Ἀρτέμιδος τῆς Ἐφεσίας, ὅτ᾽ ἀπήιει σὺν Ἀγησιλάωι ἐκ τῆς Ἀσίας τὴν εἰς Βοιωτοὺς ὁδόν, καταλείπει παρὰ Μεγαβύζωι τῶι τῆς Ἀρτέμιδος νεωκόρωι, ὅτι αὐτὸς κινδυνεύσων ἐδόκει ἰέναι, καὶ ἐπέστειλεν, ἢν μὲν αὐτὸς σωθῆι, αὑτῶι ἀποδοῦναι· ἢν δέ τι πάθηι, ἀναθεῖναι ποιησάμενον τῆι Ἀρτέμιδι ὅ τι οἴοιτο χαριεῖσθαι τῆι θεῶι.", "st": "5.3.6"}, {"sp": "N", "t": "ἐπειδὴ δ᾽ ἔφευγεν ὁ Ξενοφῶν, κατοικοῦντος ἤδη αὐτοῦ ἐν Σκιλλοῦντι ὑπὸ τῶν Λακεδαιμονίων οἰκισθέντος παρὰ τὴν Ὀλυμπίαν ἀφικνεῖται Μεγάβυζος εἰς Ὀλυμπίαν θεωρήσων καὶ ἀποδίδωσι τὴν παρακαταθήκην αὐτῶι. Ξενοφῶν δὲ λαβὼν χωρίον ὠνεῖται τῆι θεῶι ὅπου ἀνεῖλεν ὁ θεός.", "st": "5.3.7"}, {"sp": "N", "t": "ἔτυχε δὲ διαρρέων διὰ τοῦ χωρίου ποταμὸς Σελινοῦς. καὶ ἐν Ἐφέσωι δὲ παρὰ τὸν τῆς Ἀρτέμιδος νεὼν Σελινοῦς ποταμὸς παραρρεῖ. καὶ ἰχθύες τε ἐν ἀμφοτέροις ἔνεισι καὶ κόγχαι· ἐν δὲ τῶι ἐν Σκιλλοῦντι χωρίωι καὶ θῆραι πάντων ὁπόσα ἐστὶν ἀγρευόμενα θηρία.", "st": "5.3.8"}, {"sp": "N", "t": "ἐποίησε δὲ καὶ βωμὸν καὶ ναὸν ἀπὸ τοῦ ἱεροῦ ἀργυρίου, καὶ τὸ λοιπὸν δὲ ἀεὶ δεκατεύων τὰ ἐκ τοῦ ἀγροῦ ὡραῖα θυσίαν ἐποίει τῆι θεῶι, καὶ πάντες οἱ πολῖται καὶ οἱ πρόσχωροι ἄνδρες καὶ γυναῖκες μετεῖχον τῆς ἑορτῆς. παρεῖχε δὲ ἡ θεὸς τοῖς σκηνοῦσιν ἄλφιτα, ἄρτους, οἶνον, τραγήματα, καὶ τῶν θυομένων ἀπὸ τῆς ἱερᾶς νομῆς λάχος, καὶ τῶν θηρευομένων δέ.", "st": "5.3.9"}, {"sp": "N", "t": "καὶ γὰρ θήραν ἐποιοῦντο εἰς τὴν ἑορτὴν οἵ τε Ξενοφῶντος παῖδες καὶ οἱ τῶν ἄλλων πολιτῶν, οἱ δὲ βουλόμενοι καὶ ἄνδρες ξυνεθήρων· καὶ ἡλίσκετο τὰ μὲν ἐξ αὐτοῦ τοῦ ἱεροῦ χώρου, τὰ δὲ καὶ ἐκ τῆς Φολόης, σύες καὶ δορκάδες καὶ ἔλαφοι.", "st": "5.3.10"}, {"sp": "N", "t": "ἔστι δὲ ἡ χώρα ἧι ἐκ Λακεδαίμονος εἰς Ὀλυμπίαν πορεύονται ὡς εἴκοσι στάδιοι ἀπὸ τοῦ ἐν Ὀλυμπίαι Διὸς ἱεροῦ. ἔνι δ᾽ ἐν τῶι ἱερῶι χώρωι καὶ λειμὼν καὶ ὄρη δένδρων μεστά, ἱκανὰ σῦς καὶ αἶγας καὶ βοῦς τρέφειν καὶ ἵππους, ὥστε καὶ τὰ τῶν εἰς τὴν ἑορτὴν ἰόντων ὑποζύγια εὐωχεῖσθαι.", "st": "5.3.11"}, {"sp": "N", "t": "περὶ δὲ αὐτὸν τὸν ναὸν ἄλσος ἡμέρων δένδρων ἐφυτεύθη ὅσα ἐστὶ τρωκτὰ ὡραῖα. ὁ δὲ ναὸς ὡς μικρὸς μεγάλωι τῶι ἐν Ἐφέσωι εἴκασται, καὶ τὸ ξόανον ἔοικεν ὡς κυπαρίττινον χρυσῶι ὄντι τῶι ἐν Ἐφέσωι.", "st": "5.3.12"}, {"sp": "N", "t": "καὶ στήλη ἕστηκε παρὰ τὸν ναὸν γράμματα ἔχουσα· Ἱερὸς ὁ χῶρος τῆς Ἀρτέμιδος. τὸν ἔχοντα καὶ καρπούμενον τὴν μὲν δεκάτην καταθύειν ἑκάστου ἔτους. ἐκ δὲ τοῦ περιττοῦ τὸν ναὸν ἐπισκευάζειν. ἂν δὲ τις μὴ ποιῆι ταῦτα τῆι θεῶι μελήσει.", "st": "5.3.13"}, {"sp": "N", "t": "ἐκ Κερασοῦντος δὲ κατὰ θάλατταν μὲν ἐκομίζοντο οἵπερ καὶ πρόσθεν, οἱ δὲ ἄλλοι κατὰ γῆν ἐπορεύοντο.", "st": "5.4.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ἦσαν ἐπὶ τοῖς Μοσσυνοίκων ὁρίοις, πέμπουσιν εἰς αὐτοὺς Τιμησίθεον τὸν Τραπεζούντιον πρόξενον ὄντα τῶν Μοσσυνοίκων, ἐρωτῶντες πότερον ὡς διὰ φιλίας ἢ διὰ πολεμίας πορεύσονται τῆς χώρας. οἱ δὲ εἶπον ὅτι οὐ διήσοιεν· ἐπίστευον γὰρ τοῖς χωρίοις.", "st": "5.4.2"}, {"sp": "N", "t": "ἐντεῦθεν λέγει ὁ Τιμησίθεος ὅτι πολέμιοί εἰσιν αὐτοῖς οἱ ἐκ τοῦ ἐπέκεινα. καὶ ἐδόκει καλέσαι ἐκείνους, εἰ βούλοιντο ξυμμαχίαν ποιήσασθαι· καὶ πεμφθεὶς ὁ Τιμησίθεος ἧκεν ἄγων τοὺς ἄρχοντας.", "st": "5.4.3"}, {"sp": "N", "t": "ἐπεὶ δὲ ἀφίκοντο, συνῆλθον οἵ τε τῶν Μοσσυνοίκων ἄρχοντες καὶ οἱ στρατηγοὶ τῶν Ἑλλήνων·", "st": "5.4.4"}, {"sp": "N", "t": "καὶ ἔλεξε Ξενοφῶν, ἡρμήνευε δὲ Τιμησίθεος· «ὦ ἄνδρες Μοσσύνοικοι, ἡμεῖς βουλόμεθα διασωθῆναι πρὸς τὴν Ἑλλάδα πεζῆι· πλοῖα γὰρ οὐκ ἔχομεν· κωλύουσι δὲ οὗτοι ἡμᾶς οὓς ἀκούομεν ὑμῖν πολεμίους εἶναι.", "st": "5.4.5"}, {"sp": "N", "t": "εἰ οὖν βούλεσθε, ἔξεστιν ὑμῖν ἡμᾶς λαβεῖν ξυμμάχους καὶ τιμωρήσασθαι εἴ τί ποτε ὑμᾶς οὗτοι ἠδίκησαν, καὶ τὸ λοιπὸν ὑμῶν ὑπηκόους εἶναι τούτους.", "st": "5.4.6"}, {"sp": "N", "t": "εἰ δὲ ἡμᾶς ἀφήσετε, σκέψασθε πόθεν αὖθις ἂν τοσαύτην δύναμιν λάβοιτε ξύμμαχον.»", "st": "5.4.7"}, {"sp": "N", "t": "πρὸς ταῦτα ἀπεκρίνατο ὁ ἄρχων τῶν Μοσσυνοίκων ὅτι καὶ βούλοιντο ταῦτα καὶ δέχοιντο τὴν ξυμμαχίαν.", "st": "5.4.8"}, {"sp": "N", "t": "«ἄγετε δή, ἔφη ὁ Ξενοφῶν, τί ἡμῶν δεήσεσθε χρήσασθαι, ἂν ξύμμαχοι ὑμῶν γενώμεθα, καὶ ὑμεῖς τί οἷοί τε ἔσεσθε ἡμῖν ξυμπρᾶξαι περὶ τῆς διόδου;»", "st": "5.4.9"}, {"sp": "N", "t": "οἱ δὲ εἶπον ὅτι ἱκανοί ἐσμεν εἰς τὴν χώραν εἰσβάλλειν ἐκ τοῦ ἐπὶ θάτερα τὴν τῶν ὑμῖν τε καὶ ἡμῖν πολεμίων, καὶ δεῦρο ὑμῖν πέμψαι ναῦς τε καὶ ἄνδρας οἵτινες ὑμῖν ξυμμαχοῦνταί τε καὶ τὴν ὁδὸν ἡγήσονται.", "st": "5.4.10"}, {"sp": "N", "t": "ἐπὶ τούτοις πιστὰ δόντες καὶ λαβόντες ὤιχοντο. καὶ ἧκον τῆι ὑστεραίαι ἄγοντες τριακόσια πλοῖα μονόξυλα καὶ ἐν ἑκάστωι τρεῖς ἄνδρας, ὧν οἱ μὲν δύο ἐκβάντες εἰς τάξιν ἔθεντο τὰ ὅπλα, ὁ δὲ εἷς ἔμενε.", "st": "5.4.11"}, {"sp": "N", "t": "καὶ οἱ μὲν λαβόντες τὰ πλοῖα ἀπέπλευσαν, οἱ δὲ μένοντες ἐξετάξαντο ὧδε. ἔστησαν [ὥσπερ] ἀνὰ ἑκατὸν μάλιστα οἷον χοροὶ ἀντιστοιχοῦντες ἀλλήλοις, ἔχοντες γέρρα πάντες λευκῶν βοῶν δασέα, ἠικασμένα κιττοῦ πετάλωι, ἐν δὲ τῆι δεξιᾶι παλτὸν ὡς ἕξπηχυ, ἔμπροσθεν μὲν λόγχην ἔχον, ὄπισθεν δὲ τοῦ ξύλου σφαιροειδές.", "st": "5.4.12"}, {"sp": "N", "t": "χιτωνίσκους δὲ ἐνεδεδύκεσαν ὑπὲρ γονάτων, πάχος ὡς λινοῦ στρωματοδέσμου, ἐπὶ τῆι κεφαλῆι δὲ κράνη σκύτινα οἷάπερ τὰ Παφλαγονικά, κρωβύλον ἔχοντα κατὰ μέσον, ἐγγύτατα τιαροειδῆ· εἶχον δὲ καὶ σαγάρεις σιδηρᾶς.", "st": "5.4.13"}, {"sp": "N", "t": "ἐντεῦθεν ἐξῆρχε μὲν αὐτῶν εἷς, οἱ δὲ ἄλλοι ἅπαντες ἐπορεύοντο ἄιδοντες ἐν ῥυθμῶι, καὶ διελθόντες διὰ τῶν τάξεων καὶ διὰ τῶν ὅπλων τῶν Ἑλλήνων ἐπορεύοντο εὐθὺς πρὸς τοὺς πολεμίους ἐπὶ χωρίον ὃ ἐδόκει ἐπιμαχώτατον εἶναι.", "st": "5.4.14"}, {"sp": "N", "t": "ὠικεῖτο δὲ τοῦτο πρὸ τῆς πόλεως τῆς Μητροπόλεως καλουμένης αὐτοῖς καὶ ἐχούσης τὸ ἀκρότατον τῶν Μοσσυνοίκων. καὶ περὶ τούτου ὁ πόλεμος ἦν· οἱ γὰρ ἀεὶ τοῦτ᾽ ἔχοντες ἐδόκουν ἐγκρατεῖς εἶναι καὶ πάντων Μοσσυνοίκων, καὶ ἔφασαν τούτους οὐ δικαίως ἔχειν τοῦτο, ἀλλὰ κοινὸν ὂν καταλαβόντας πλεονεκτεῖν.", "st": "5.4.15"}, {"sp": "N", "t": "εἵποντο δ᾽ αὐτοῖς καὶ τῶν Ἑλλήνων τινές, οὐ ταχθέντες ὑπὸ τῶν στρατηγῶν, ἀλλὰ ἁρπαγῆς ἕνεκεν. οἱ δὲ πολέμιοι προσιόντων τέως μὲν ἡσύχαζον· ἐπεὶ δ᾽ ἐγγὺς ἐγένοντο τοῦ χωρίου, ἐκδραμόντες τρέπονται αὐτούς, καὶ ἀπέκτειναν συχνοὺς τῶν βαρβάρων καὶ τῶν ξυναναβάντων Ἑλλήνων τινάς, καὶ ἐδίωκον μέχρι οὗ εἶδον τοὺς Ἕλληνας βοηθοῦντας·", "st": "5.4.16"}, {"sp": "N", "t": "εἶτα δὲ ἀποτραπόμενοι ὤιχοντο, καὶ ἀποτεμόντες τὰς κεφαλὰς τῶν νεκρῶν ἐπεδείκνυσαν τοῖς Ἕλλησι καὶ τοῖς ἑαυτῶν πολεμίοις, καὶ ἅμα ἐχόρευον νόμωι τινὶ ἄιδοντες.", "st": "5.4.17"}, {"sp": "N", "t": "οἱ δὲ Ἕλληνες μάλα ἤχθοντο ὅτι τούς τε πολεμίους ἐπεποιήκεσαν θρασυτέρους καὶ ὅτι οἱ ἐξελθόντες Ἕλληνες σὺν αὐτοῖς ἐπεφεύγεσαν μάλα ὄντες συχνοί· ὃ οὔπω πρόσθεν ἐπεποιήκεσαν ἐν τῆι στρατείαι.", "st": "5.4.18"}, {"sp": "N", "t": "Ξενοφῶν δὲ ξυγκαλέσας τοὺς Ἕλληνας εἶπεν· «ἄνδρες στρατιῶται, μηδὲν ἀθυμήσητε ἕνεκα τῶν γεγενημένων· ἴστε γὰρ ὅτι καὶ ἀγαθὸν οὐ μεῖον τοῦ κακοῦ γεγένηται.", "st": "5.4.19"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ ἐπίστασθε ὅτι οἱ μέλλοντες ἡμῖν ἡγεῖσθαι τῶι ὄντι πολέμιοί εἰσιν οἷσπερ καὶ ἡμᾶς ἀνάγκη· ἔπειτα δὲ καὶ τῶν Ἑλλήνων οἱ ἀμελήσαντες τῆς ξὺν ἡμῖν τάξεως καὶ ἱκανοὶ ἡγησάμενοι εἶναι ξὺν τοῖς βαρβάροις ταὐτὰ πράττειν ἅπερ σὺν ἡμῖν δίκην δεδώκασιν· ὥστε αὖθις ἧττον τῆς ἡμετέρας τάξεως ἀπολείψονται.", "st": "5.4.20"}, {"sp": "N", "t": "ἀλλ᾽ ὑμᾶς δεῖ παρασκευάζεσθαι ὅπως καὶ τοῖς φίλοις οὖσι τῶν βαρβάρων δόξητε κρείττους αὐτῶν εἶναι καὶ τοῖς πολεμίοις δηλώσητε ὅτι οὐχ ὁμοίοις ἀνδράσι μαχοῦνται νῦν τε καὶ ὅτε τοῖς ἀτάκτοις ἐμάχοντο.»", "st": "5.4.21"}, {"sp": "N", "t": "ταύτην μὲν οὖν τὴν ἡμέραν οὕτως ἔμειναν· τῆι δὲ ὑστεραίαι θύσαντες ἐπεὶ ἐκαλλιερήσαντο, ἀριστήσαντες, ὀρθίους τοὺς λόχους ποιησάμενοι, καὶ τοὺς βαρβάρους ἐπὶ τὸ εὐώνυμον κατὰ ταὐτὰ ταξάμενοι ἐπορεύοντο τοὺς τοξότας μεταξὺ τῶν λόχων [ὀρθίων] ἔχοντες, ὑπολειπομένου δὲ μικρὸν τοῦ στόματος τῶν ὁπλιτῶν.", "st": "5.4.22"}, {"sp": "N", "t": "ἦσαν γὰρ τῶν πολεμίων οἳ εὔζωνοι κατατρέχοντες τοῖς λίθοις ἔβαλλον. τούτους ἀνέστελλον οἱ τοξόται καὶ πελτασταί. οἱ δ᾽ ἄλλοι βάδην ἐπορεύοντο πρῶτον μὲν ἐπὶ τὸ χωρίον ἀφ᾽ οὗ τῆι προτεραίαι οἱ βάρβαροι ἐτρέφθησαν καὶ οἱ ξὺν αὐτοῖς· ἐνταῦθα γὰρ οἱ πολέμιοι ἦσαν ἀντιτεταγμένοι.", "st": "5.4.23"}, {"sp": "N", "t": "τοὺς μὲν οὖν πελταστὰς ἐδέξαντο οἱ βάρβαροι καὶ ἐμάχοντο, ἐπειδὴ δὲ ἐγγὺς ἦσαν οἱ ὁπλῖται, ἐτρέποντο. καὶ οἱ μὲν πελτασταὶ εὐθὺς εἵποντο διώκοντες ἄνω πρὸς τὴν πόλιν, οἱ δὲ ὁπλῖται ἐν τάξει εἵποντο.", "st": "5.4.24"}, {"sp": "N", "t": "ἐπεὶ δὲ ἄνω ἦσαν πρὸς ταῖς Μητροπόλεως οἰκίαις, ἐνταῦθα οἱ πολέμιοι ὁμοῦ δὴ πάντες γενόμενοι ἐμάχοντο καὶ ἐξηκόντιζον τοῖς παλτοῖς, καὶ ἄλλα δόρατα ἔχοντες παχέα μακρά, ὅσα ἀνὴρ ἂν φέροι μόλις, τούτοις ἐπειρῶντο ἀμύνασθαι ἐκ χειρός.", "st": "5.4.25"}, {"sp": "N", "t": "ἐπεὶ δὲ οὐχ ὑφίεντο οἱ Ἕλληνες, ἀλλὰ ὁμόσε ἐχώρουν, ἔφευγον οἱ βάρβαροι καὶ ἐντεῦθεν, λιπόντες ἅπαντες τὸ χωρίον. ὁ δὲ βασιλεὺς αὐτῶν ὁ ἐν τῶι μόσσυνι τῶι ἐπ᾽ ἄκρου ὠικοδομημένωι, ὃν τρέφουσι πάντες κοινῆι αὐτοῦ μένοντα καὶ φυλάττουσιν, οὐκ ἤθελεν ἐξελθεῖν, οὐδὲ ὁ ἐν τῶι πρότερον αἱρεθέντι χωρίωι, ἀλλ᾽ αὐτοῦ σὺν τοῖς μοσσύνοις κατεκαύθησαν.", "st": "5.4.26"}, {"sp": "N", "t": "οἱ δὲ Ἕλληνες διαρπάζοντες τὰ χωρία ηὕρισκον θησαυροὺς ἐν ταῖς οἰκίαις ἄρτων νενημένων περυσινῶν, ὡς ἔφασαν οἱ Μοσσύνοικοι, τὸν δὲ νέον σῖτον ξὺν τῆι καλάμηι ἀποκείμενον· ἦσαν δὲ ζειαὶ αἱ πλεῖσται.", "st": "5.4.27"}, {"sp": "N", "t": "καὶ δελφίνων τεμάχη ἐν ἀμφορεῦσιν ηὑρίσκετο τεταριχευμένα καὶ στέαρ ἐν τεύχεσι τῶν δελφίνων, ὧι ἐχρῶντο οἱ Μοσσύνοικοι καθάπερ οἱ Ἕλληνες τῶι ἐλαίωι·", "st": "5.4.28"}, {"sp": "N", "t": "κάρυα δὲ ἐπὶ τῶν ἀνώγεων ἦν πολλὰ τὰ πλατέα οὐκ ἔχοντα διαφυὴν οὐδεμίαν. τούτων καὶ πλείστωι σίτωι ἐχρῶντο ἕψοντες καὶ ἄρτους ὀπτῶντες. οἶνος δὲ ηὑρίσκετο ὃς ἄκρατος μὲν ὀξὺς ἐφαίνετο εἶναι ὑπὸ τῆς αὐστηρότητος, κερασθεὶς δὲ εὐώδης τε καὶ ἡδύς.", "st": "5.4.29"}, {"sp": "N", "t": "οἱ μὲν δὴ Ἕλληνες ἀριστήσαντες ἐνταῦθα ἐπορεύοντο εἰς τὸ πρόσω, παραδόντες τὸ χωρίον τοῖς ξυμμαχήσασι τῶν Μοσσυνοίκων. ὁπόσα δὲ καὶ ἄλλα παρῆισαν χωρία τῶν ξὺν τοῖς πολεμίοις ὄντων, τὰ εὐπροσοδώτατα οἱ μὲν ἔλειπον, οἱ δὲ ἑκόντες προσεχώρουν.", "st": "5.4.30"}, {"sp": "N", "t": "τὰ δὲ πλεῖστα τοιάδε ἦν τῶν χωρίων. ἀπεῖχον αἱ πόλεις ἀπ᾽ ἀλλήλων στάδια ὀγδοήκοντα, αἱ δὲ πλέον αἱ δὲ μεῖον· ἀναβοώντων δὲ ἀλλήλων ξυνήκουον εἰς τὴν ἑτέραν ἐκ τῆς ἑτέρας πόλεως· οὕτως ὑψηλή τε καὶ κοίλη ἡ χώρα ἦν.", "st": "5.4.31"}, {"sp": "N", "t": "ἐπεὶ δὲ πορευόμενοι ἐν τοῖς φίλοις ἦσαν, ἐπεδείκνυσαν αὐτοῖς παῖδας τῶν εὐδαιμόνων σιτευτούς, τεθραμμένους καρύοις ἑφθοῖς, ἁπαλοὺς καὶ λευκοὺς σφόδρα καὶ οὐ πολλοῦ δέοντας ἴσους τὸ μῆκος καὶ τὸ πλάτος εἶναι, ποικίλους δὲ τὰ νῶτα καὶ τὰ ἔμπροσθεν πάντα, ἐστιγμένους ἀνθέμια.", "st": "5.4.32"}, {"sp": "N", "t": "ἐζήτουν δὲ καὶ ταῖς ἑταίραις ἃς ἦγον οἱ Ἕλληνες ἐμφανῶς ξυγγίγνεσθαι· νόμος γὰρ ἦν οὗτός σφισι. λευκοὶ δὲ πάντες οἱ ἄνδρες καὶ αἱ γυναῖκες.", "st": "5.4.33"}, {"sp": "N", "t": "τούτους ἔλεγον οἱ στρατευσάμενοι βαρβαρωτάτους διελθεῖν καὶ πλεῖστον τῶν Ἑλληνικῶν νόμων κεχωρισμένους. ἔν τε γὰρ ὄχλωι ὄντες ἐποίουν ἅπερ ⟨ἂν⟩ ἄνθρωποι ἐν ἐρημίαι ποιήσειαν, μόνοι τε ὄντες ὅμοια ἔπραττον ἅπερ ἂν μετ᾽ ἄλλων ὄντες, διελέγοντό τε αὑτοῖς καὶ ἐγέλων ἐφ᾽ ἑαυτοῖς καὶ ὠρχοῦντο ἐφιστάμενοι ὅπου τύχοιεν, ὥσπερ ἄλλοις ἐπιδεικνύμενοι.", "st": "5.4.34"}, {"sp": "N", "t": "διὰ ταύτης τῆς χώρας οἱ Ἕλληνες, διά τε τῆς πολεμίας καὶ τῆς φιλίας, ἐπορεύθησαν ὀκτὼ σταθμούς, καὶ ἀφικνοῦνται εἰς Χάλυβας. οὗτοι ὀλίγοι τε ἦσαν καὶ ὑπήκοοι τῶν Μοσσυνοίκων, καὶ ὁ βίος ἦν τοῖς πλείστοις αὐτῶν ἀπὸ σιδηρείας.", "st": "5.5.1"}, {"sp": "N", "t": "ἐντεῦθεν ἀφικνοῦνται εἰς Τιβαρηνούς. ἡ δὲ τῶν Τιβαρηνῶν χώρα πολὺ ἦν πεδινωτέρα καὶ χωρία εἶχεν ἐπὶ θαλάττηι ἧττον ἐρυμνά. καὶ οἱ στρατηγοὶ ἔχρηιζον πρὸς τὰ χωρία προσβάλλειν καὶ τὴν στρατιὰν ὀνηθῆναί τι, καὶ τὰ ξένια ἃ ἧκε παρὰ Τιβαρηνῶν οὐκ ἐδέχοντο, ἀλλ᾽ ἐπιμεῖναι κελεύσαντες ἔστε βουλεύσαιντο ἐθύοντο.", "st": "5.5.2"}, {"sp": "N", "t": "καὶ πολλὰ καταθυσάντων τέλος ἀπεδείξαντο οἱ μάντεις πάντες γνώμην ὅτι οὐδαμῆι προσίοιντο οἱ θεοὶ τὸν πόλεμον. ἐντεῦθεν δὴ τὰ ξένια ἐδέξαντο, καὶ ὡς διὰ φιλίας πορευόμενοι δύο ἡμέρας ἀφίκοντο εἰς Κοτύωρα πόλιν Ἑλληνίδα, Σινωπέων ἄποικον, οὖσαν δ᾽ ἐν τῆι Τιβαρηνῶν χώραι.", "st": "5.5.3"}, {"sp": "N", "t": "[μέχρι ἐνταῦθα ἐπέζευσεν ἡ στρατιά. πλῆθος τῆς καταβάσεως τῆς ὁδοῦ ἀπὸ τῆς ἐν Βαβυλῶνι μάχης ἄχρι εἰς Κοτύωρα σταθμοὶ ἑκατὸν εἴκοσι δύο, παρασάγγαι ἑξακόσιοι καὶ εἴκοσι, στάδιοι μύριοι καὶ ὀκτακισχίλιοι καὶ ἑξακόσιοι, χρόνου πλῆθος ὀκτὼ μῆνες.]", "st": "5.5.4"}, {"sp": "N", "t": "ἐνταῦθα ἔμειναν ἡμέρας τετταράκοντα πέντε. ἐν δὲ ταύταις πρῶτον μὲν τοῖς θεοῖς ἔθυσαν, καὶ πομπὰς ἐποίησαν κατὰ ἔθνος ἕκαστοι τῶν Ἑλλήνων καὶ ἀγῶνας γυμνικούς.", "st": "5.5.5"}, {"sp": "N", "t": "τὰ δ᾽ ἐπιτήδει᾽ ἐλάμβανον τὰ μὲν ἐκ τῆς Παφλαγονίας, τὰ δ᾽ ἐκ τῶν χωρίων τῶν Κοτυωριτῶν· οὐ γὰρ παρεῖχον ἀγοράν, οὐδ᾽ εἰς τὸ τεῖχος τοὺς ἀσθενοῦντας ἐδέχοντο.", "st": "5.5.6"}, {"sp": "N", "t": "ἐν τούτωι ἔρχονται ἐκ Σινώπης πρέσβεις, φοβούμενοι περὶ τῶν Κοτυωριτῶν τῆς τε πόλεως (ἦν γὰρ ἐκείνων καὶ φόρον ἐκείνοις ἔφερον) καὶ περὶ τῆς χώρας, ὅτι ἤκουον δηιουμένην. καὶ ἐλθόντες εἰς τὸ στρατόπεδον ἔλεγον· προηγόρει δὲ Ἑκατώνυμος δεινὸς νομιζόμενος εἶναι λέγειν·", "st": "5.5.7"}, {"sp": "N", "t": "«ἔπεμψεν ἡμᾶς, ὦ ἄνδρες στρατιῶται, ἡ τῶν Σινωπέων πόλις ἐπαινέσοντάς τε ὑμᾶς ὅτι νικᾶτε Ἕλληνες ὄντες βαρβάρους, ἔπειτα δὲ καὶ ξυνησθησομένους ὅτι διὰ πολλῶν τε καὶ δεινῶν, ὡς ἡμεῖς ἠκούσαμεν, πραγμάτων σεσωσμένοι πάρεστε.", "st": "5.5.8"}, {"sp": "N", "t": "ἀξιοῦμεν δὲ Ἕλληνες ὄντες καὶ αὐτοὶ ὑφ᾽ ὑμῶν ὄντων Ἑλλήνων ἀγαθὸν μέν τι πάσχειν, κακὸν δὲ μηδέν· οὐδὲ γὰρ ἡμεῖς ὑμᾶς οὐδὲν πώποτε ὑπήρξαμεν κακῶς ποιοῦντες.", "st": "5.5.9"}, {"sp": "N", "t": "Κοτυωρῖται δὲ οὗτοι εἰσὶ μὲν ἡμέτεροι ἄποικοι, καὶ τὴν χώραν ἡμεῖς αὐτοῖς ταύτην παραδεδώκαμεν βαρβάρους ἀφελόμενοι· διὸ καὶ δασμὸν ἡμῖν φέρουσιν οὗτοι τεταγμένον καὶ Κερασούντιοι καὶ Τραπεζούντιοι· ὥστε ὅ τι ἂν τούτους κακὸν ποιήσητε ἡ Σινωπέων πόλις νομίζει πάσχειν.", "st": "5.5.10"}, {"sp": "N", "t": "νῦν δὲ ἀκούομεν ὑμᾶς εἴς τε τὴν πόλιν βίαι παρεληλυθότας ἐνίους σκηνοῦν ἐν ταῖς οἰκίαις καὶ ἐκ τῶν χωρίων βίαι λαμβάνειν ὧν ἂν δέησθε οὐ πείθοντας.", "st": "5.5.11"}, {"sp": "N", "t": "ταῦτ᾽ οὖν οὐκ ἀξιοῦμεν· εἰ δὲ ταῦτα ποιήσετε, ἀνάγκη ἡμῖν καὶ Κορύλαν καὶ Παφλαγόνας καὶ ἄλλον ὅντινα ἂν δυνώμεθα φίλον ποιεῖσθαι.»", "st": "5.5.12"}, {"sp": "N", "t": "πρὸς ταῦτα ἀναστὰς Ξενοφῶν ὑπὲρ τῶν στρατιωτῶν εἶπεν· «ἡμεῖς δέ, ὦ ἄνδρες Σινωπεῖς, ἥκομεν ἀγαπῶντες ὅτι τὰ σώματα διεσωσάμεθα καὶ τὰ ὅπλα· οὐ γὰρ ἦν δυνατὸν ἅμα τε χρήματα ἄγειν καὶ φέρειν καὶ τοῖς πολεμίοις μάχεσθαι.", "st": "5.5.13"}, {"sp": "N", "t": "καὶ νῦν ἐπεὶ εἰς τὰς Ἑλληνίδας πόλεις ἤλθομεν, ἐν Τραπεζοῦντι μὲν (παρεῖχον γὰρ ἡμῖν ἀγοράν) ὠνούμενοι εἴχομεν τὰ ἐπιτήδεια, καὶ ἀνθ᾽ ὧν ἐτίμησαν ἡμᾶς καὶ ξένια ἔδωκαν τῆι στρατιᾶι, ἀντετιμῶμεν αὐτούς, καὶ εἴ τις αὐτοῖς φίλος ἦν τῶν βαρβάρων, τούτων ἀπειχόμεθα· τοὺς δὲ πολεμίους αὐτῶν ἐφ᾽ οὓς αὐτοὶ ἡγοῖντο κακῶς ἐποιοῦμεν ὅσον ἐδυνάμεθα.", "st": "5.5.14"}, {"sp": "N", "t": "ἐρωτᾶτε δὲ αὐτοὺς ὁποίων τινῶν ἡμῶν ἔτυχον· πάρεισι γὰρ ἐνθάδε οὓς ἡμῖν ἡγεμόνας διὰ φιλίαν ἡ πόλις ξυνέπεμψεν.", "st": "5.5.15"}, {"sp": "N", "t": "ὅποι δ᾽ ἂν ἐλθόντες ἀγορὰν μὴ ἔχωμεν, ἄν τε εἰς βάρβαρον γῆν ἄν τε εἰς Ἑλληνίδα, οὐχ ὕβρει ἀλλὰ ἀνάγκηι λαμβάνομεν τὰ ἐπιτήδεια.", "st": "5.5.16"}, {"sp": "N", "t": "καὶ Καρδούχους καὶ Ταόχους καὶ Χαλδαίους καίπερ βασιλέως οὐχ ὑπηκόους ὄντας ὅμως καὶ μάλα φοβεροὺς ὄντας πολεμίους ἐκτησάμεθα διὰ τὸ ἀνάγκην εἶναι λαμβάνειν τὰ ἐπιτήδεια, ἐπεὶ ἀγορὰν οὐ παρεῖχον.", "st": "5.5.17"}, {"sp": "N", "t": "Μάκρωνας δὲ καίπερ βαρβάρους ὄντας, ἐπεὶ ἀγορὰν οἵαν ἐδύναντο παρεῖχον, φίλους τε ἐνομίζομεν εἶναι καὶ βίαι οὐδὲν ἐλαμβάνομεν τῶν ἐκείνων.", "st": "5.5.18"}, {"sp": "N", "t": "Κοτυωρίτας δέ, οὓς ὑμετέρους φατὲ εἶναι, εἴ τι αὐτῶν εἰλήφαμεν, αὐτοὶ αἴτιοί εἰσιν· οὐ γὰρ ὡς φίλοι προσεφέροντο ἡμῖν, ἀλλὰ κλείσαντες τὰς πύλας οὔτε εἴσω ἐδέχοντο οὔτε ἔξω ἀγορὰν ἔπεμπον· ἠιτιῶντο δὲ τὸν παρ᾽ ὑμῶν ἁρμοστὴν τούτων αἴτιον εἶναι.", "st": "5.5.19"}, {"sp": "N", "t": "ὃ δὲ λέγεις βίαι παρελθόντας σκηνοῦν, ἡμεῖς ἠξιοῦμεν τοὺς κάμνοντας εἰς τὰς στέγας δέξασθαι· ἐπεὶ δὲ οὐκ ἀνέωιγον τὰς πύλας, ἧι ἡμᾶς ἐδέχετο αὐτὸ τὸ χωρίον ταύτηι εἰσελθόντες ἄλλο μὲν οὐδὲν βίαιον ἐποιήσαμεν, σκηνοῦσι δ᾽ ἐν ταῖς στέγαις οἱ κάμνοντες τὰ αὑτῶν δαπανῶντες, καὶ τὰς πύλας φρουροῦμεν, ὅπως μὴ ἐπὶ τῶι ὑμετέρωι ἁρμοστῆι ὦσιν οἱ κάμνοντες ἡμῶν, ἀλλ᾽ ἐφ᾽ ἡμῖν ἦι κομίσασθαι ὅταν βουλώμεθα.", "st": "5.5.20"}, {"sp": "N", "t": "οἱ δὲ ἄλλοι, ὡς ὁρᾶτε, σκηνοῦμεν ὑπαίθριοι ἐν τῆι τάξει, παρεσκευασμένοι, ἂν μέν τις εὖ ποιῆι, ἀντ᾽ εὖ ποιεῖν, ἂν δὲ κακῶς, ἀλέξασθαι.", "st": "5.5.21"}, {"sp": "N", "t": "ἃ δὲ ἠπείλησας ὡς, ἢν ὑμῖν δοκῆι, Κορύλαν καὶ Παφλαγόνας ξυμμάχους ποιήσεσθε ἐφ᾽ ἡμᾶς, ἡμεῖς δέ, ἢν μὲν ἀνάγκη ἦι, πολεμήσομεν καὶ ἀμφοτέροις· ἤδη γὰρ καὶ ἄλλοις πολλαπλασίοις ὑμῶν ἐπολεμήσαμεν· ἂν δὲ δοκῆι ἡμῖν καὶ φίλον ποιεῖσθαι τὸν Παφλαγόνα", "st": "5.5.22"}, {"sp": "N", "t": "(ἀκούομεν δὲ αὐτὸν καὶ ἐπιθυμεῖν τῆς ὑμετέρας πόλεως καὶ χωρίων τῶν ἐπιθαλαττίων), πειρασόμεθα ξυμπράττοντες αὐτῶι ὧν ἐπιθυμεῖ φίλοι γίγνεσθαι.»", "st": "5.5.23"}, {"sp": "N", "t": "ἐκ τούτου μάλα μὲν δῆλοι ἦσαν οἱ ξυμπρέσβεις τῶι Ἑκατωνύμωι χαλεπαίνοντες τοῖς εἰρημένοις, παρελθὼν δ᾽ αὐτῶν ἄλλος εἶπεν ὅτι οὐ πόλεμον ποιησόμενοι ἥκοιεν ἀλλὰ ἐπιδείξοντες ὅτι φίλοι εἰσί. καὶ ξενίοις, ἢν μὲν ἔλθητε πρὸς τὴν Σινωπέων πόλιν, ἐκεῖ δεξόμεθα, νῦν δὲ τοὺς ἐνθάδε κελεύσομεν διδόναι ἃ δύνανται· ὁρῶμεν γὰρ πάντα ἀληθῆ ὄντα ἃ λέγετε.", "st": "5.5.24"}, {"sp": "N", "t": "ἐκ τούτου ξένιά τε ἔπεμπον οἱ Κοτυωρῖται καὶ οἱ στρατηγοὶ τῶν Ἑλλήνων ἐξένιζον τοὺς τῶν Σινωπέων πρέσβεις, καὶ πρὸς ἀλλήλους πολλά τε καὶ φιλικὰ διελέγοντο τά τε ἄλλα καὶ περὶ τῆς λοιπῆς πορείας ἀνεπυνθάνοντο ὧν ἑκάτεροι ἐδέοντο.", "st": "5.5.25"}, {"sp": "N", "t": "ταύτηι μὲν τῆι ἡμέραι τοῦτο τὸ τέλος ἐγένετο. τῆι δὲ ὑστεραίαι ξυνέλεξαν οἱ στρατηγοὶ τοὺς στρατιώτας. καὶ ἐδόκει αὐτοῖς περὶ τῆς λοιπῆς πορείας παρακαλέσαντας τοὺς Σινωπέας βουλεύεσθαι. εἴτε γὰρ πεζῆι δέοι πορεύεσθαι, χρήσιμοι ἂν ἐδόκουν εἶναι οἱ Σινωπεῖς· ἔμπειροι γὰρ ἦσαν τῆς Παφλαγονίας· εἴτε κατὰ θάλατταν, προσδεῖν ἐδόκει Σινωπέων· μόνοι γὰρ ἂν ἐδόκουν ἱκανοὶ εἶναι πλοῖα παρασχεῖν ἀρκοῦντα τῆι στρατιᾶι.", "st": "5.6.1"}, {"sp": "N", "t": "καλέσαντες οὖν τοὺς πρέσβεις ξυνεβουλεύοντο, καὶ ἠξίουν Ἕλληνας ὄντας Ἕλλησι τούτωι πρῶτον καλῶς δέχεσθαι τῶι εὔνους τε εἶναι καὶ τὰ κάλλιστα ξυμβουλεύειν.", "st": "5.6.2"}, {"sp": "N", "t": "ἀναστὰς δὲ Ἑκατώνυμος πρῶτον μὲν ἀπελογήσατο περὶ οὗ εἶπεν ὡς τὸν Παφλαγόνα φίλον ποιήσοιντο, ὅτι οὐχ ὡς τοῖς Ἕλλησι πολεμησόντων σφῶν εἴποι, ἀλλ᾽ ὅτι ἐξὸν τοῖς βαρβάροις φίλους εἶναι τοὺς Ἕλληνας αἱρήσονται. ἐπεὶ δὲ ξυμβουλεύειν ἐκέλευον, ἐπευξάμενος εἶπεν ὧδε.", "st": "5.6.3"}, {"sp": "N", "t": "«εἰ μὲν ξυμβουλεύοιμι ἃ βέλτιστά μοι [εἶναι] δοκεῖ, πολλά μοι καὶ ἀγαθὰ γένοιτο· εἰ δὲ μή, τἀναντία. αὐτὴ γὰρ ἡ ἱερὰ ξυμβουλὴ λεγομένη εἶναι δοκεῖ μοι παρεῖναι· νῦν γὰρ δὴ ἂν μὲν εὖ ξυμβουλεύσας φανῶ, πολλοὶ ἔσονται οἱ ἐπαινοῦντές με, ἂν δὲ κακῶς, πολλοὶ ἔσεσθε οἱ καταρώμενοι.", "st": "5.6.4"}, {"sp": "N", "t": "πράγματα μὲν οὖν οἶδ᾽ ὅτι πολὺ πλείω ἕξομεν, ἐὰν κατὰ θάλατταν κομίζησθε· ἡμᾶς γὰρ δεήσει τὰ πλοῖα πορίζειν· ἢν δὲ κατὰ γῆν στέλλησθε, ὑμᾶς δεήσει τοὺς μαχομένους εἶναι. ὅμως δὲ λεκτέα ἃ γιγνώσκω·", "st": "5.6.5"}, {"sp": "N", "t": "ἔμπειρος γάρ εἰμι καὶ τῆς χώρας τῆς Παφλαγόνων καὶ τῆς δυνάμεως. ἔχει γὰρ ἀμφότερα, καὶ πεδία κάλλιστα καὶ ὄρη ὑψηλότατα.", "st": "5.6.6"}, {"sp": "N", "t": "καὶ πρῶτον μὲν οἶδα εὐθὺς ἧι τὴν εἰσβολὴν ἀνάγκη ποιεῖσθαι· οὐ γὰρ ἔστιν ἄλληι ἢ ἧι τὰ κέρατα τοῦ ὄρους τῆς ὁδοῦ καθ᾽ ἑκάτερά ἐστιν ὑψηλά, ἃ κρατεῖν κατέχοντες καὶ πάνυ ὀλίγοι δύναιντ᾽ ἄν· τούτων δὲ κατεχομένων οὐδ᾽ ἂν οἱ πάντες ἄνθρωποι δύναιντ᾽ ἂν διελθεῖν. ταῦτα δὲ καὶ δείξαιμι ἄν, εἴ μοί τινα βούλοισθε ξυμπέμψαι.", "st": "5.6.7"}, {"sp": "N", "t": "ἔπειτα δὲ οἶδα καὶ πεδία ὄντα καὶ ἱππείαν ἣν αὐτοὶ οἱ βάρβαροι νομίζουσι κρείττω εἶναι ἁπάσης τῆς βασιλέως ἱππείας. καὶ νῦν οὗτοι οὐ παρεγένοντο βασιλεῖ καλοῦντι, ἀλλὰ μεῖζον φρονεῖ ὁ ἄρχων αὐτῶν.", "st": "5.6.8"}, {"sp": "N", "t": "ἢν δὲ καὶ δυνηθῆτε τά τε ὄρη κλέψαι ἢ φθάσαι λαβόντες καὶ ἐν τῶι πεδίωι κρατῆσαι μαχόμενοι τούς τε ἱππέας τούτων καὶ πεζῶν μυριάδας πλέον ἢ δώδεκα, ἥξετε ἐπὶ τοὺς ποταμούς, πρῶτον μὲν τὸν Θερμώδοντα, εὖρος τριῶν πλέθρων, ὃν χαλεπὸν οἶμαι διαβαίνειν ἄλλως τε καὶ πολεμίων πολλῶν ἔμπροσθεν ὄντων, πολλῶν δὲ ὄπισθεν ἑπομένων· δεύτερον δὲ Ἶριν, τρίπλεθρον ὡσαύτως· τρίτον δὲ Ἅλυν, οὐ μεῖον δυοῖν σταδίοιν, ὃν οὐκ ἂν δύναισθε ἄνευ πλοίων διαβῆναι· πλοῖα δὲ τίς ἔσται ὁ παρέχων; ὡς δ᾽ αὔτως καὶ ὁ Παρθένιος ἄβατος·", "st": "5.6.9"}, {"sp": "N", "t": "ἐφ᾽ ὃν ἔλθοιτε ἄν, εἰ τὸν Ἅλυν διαβαίητε. ἐγὼ μὲν οὖν οὐ χαλεπὴν ὑμῖν εἶναι νομίζω τὴν πορείαν ἀλλὰ παντάπασιν ἀδύνατον. ἂν δὲ πλέητε, ἔστιν ἐνθένδε μὲν εἰς Σινώπην παραπλεῦσαι, ἐκ Σινώπης δὲ εἰς Ἡράκλειαν· ἐξ Ἡρακλείας δὲ οὔτε πεζῆι οὔτε κατὰ θάλατταν ἀπορία· πολλὰ γὰρ καὶ πλοῖά ἐστιν ἐν Ἡρακλείαι.»", "st": "5.6.10"}, {"sp": "N", "t": "ἐπεὶ δὲ ταῦτ᾽ ἔλεξεν, οἱ μὲν ὑπώπτευον φιλίας ἕνεκα τῆς Κορύλα λέγειν· καὶ γὰρ ἦν πρόξενος αὐτῶι· οἱ δὲ καὶ ὡς δῶρα ληψόμενον διὰ τὴν ξυμβουλὴν ταύτην· οἱ δὲ ὑπώπτευον καὶ τούτου ἕνεκα λέγειν ὡς μὴ πεζῆι ἰόντες τὴν Σινωπέων τι χώραν κακὸν ἐργάζοιντο. οἱ δ᾽ οὖν Ἕλληνες ἐψηφίσαντο κατὰ θάλατταν τὴν πορείαν ποιεῖσθαι.", "st": "5.6.11"}, {"sp": "N", "t": "μετὰ ταῦτα Ξενοφῶν εἶπεν· «ὦ Σινωπεῖς, οἱ μὲν ἄνδρες ἥιρηνται πορείαν ἣν ὑμεῖς ξυμβουλεύετε· οὕτω δὲ ἔχει· εἰ μὲν μέλλει πλοῖα ἔσεσθαι ἱκανὰ ὡς ἀριθμῶι ἕνα μὴ καταλείπεσθαι ἐνθάδε, ἡμεῖς ἂν πλέοιμεν· εἰ δὲ μέλλοιμεν οἱ μὲν καταλείψεσθαι οἱ δὲ πλεύσεσθαι, οὐκ ἂν ἐμβαίημεν εἰς τὰ πλοῖα.", "st": "5.6.12"}, {"sp": "N", "t": "γιγνώσκομεν γὰρ ὅτι ὅπου μὲν ἂν κρατῶμεν, δυναίμεθ᾽ ἂν καὶ σώιζεσθαι καὶ τὰ ἐπιτήδεια ἔχειν· εἰ δέ που ἥττους τῶν πολεμίων ληφθησόμεθα, εὔδηλον δὴ ὅτι ἐν ἀνδραπόδων χώραι ἐσόμεθα.» ἀκούσαντες ταῦτα οἱ πρέσβεις ἐκέλευον πέμπειν πρέσβεις.", "st": "5.6.13"}, {"sp": "N", "t": "καὶ πέμπουσι Καλλίμαχον Ἀρκάδα καὶ Ἀρίστωνα Ἀθηναῖον καὶ Σαμόλαν Ἀχαιόν. καὶ οἱ μὲν ὤιχοντο.", "st": "5.6.14"}, {"sp": "N", "t": "ἐν δὲ τούτωι τῶι χρόνωι Ξενοφῶντι, ὁρῶντι μὲν ὁπλίτας πολλοὺς τῶν Ἑλλήνων, ὁρῶντι δὲ πελταστὰς πολλοὺς καὶ τοξότας καὶ σφενδονήτας καὶ ἱππέας δὲ καὶ μάλα ἤδη διὰ τὴν τριβὴν ἱκανούς, ὄντας δ᾽ ἐν τῶι Πόντωι, ἔνθα οὐκ ἂν ἀπ᾽ ὀλίγων χρημάτων τοσαύτη δύναμις παρεσκευάσθη, καλὸν αὐτῶι ἐδόκει εἶναι χώραν καὶ δύναμιν τῆι Ἑλλάδι προσκτήσασθαι πόλιν κατοικίσαντας.", "st": "5.6.15"}, {"sp": "N", "t": "καὶ γενέσθαι ἂν αὐτῶι ἐδόκει μεγάλη, καταλογιζομένωι τό τε αὑτῶν πλῆθος καὶ τοὺς περιοικοῦντας τὸν Πόντον. καὶ ἐπὶ τούτοις ἐθύετο πρίν τινι εἰπεῖν τῶν στρατιωτῶν Σιλανὸν παρακαλέσας τὸν Κύρου μάντιν γενόμενον τὸν Ἀμπρακιώτην.", "st": "5.6.16"}, {"sp": "N", "t": "ὁ δὲ Σιλανὸς δεδιὼς μὴ γένηται ταῦτα καὶ καταμείνηι που ἡ στρατιά, ἐκφέρει εἰς τὸ στράτευμα λόγον ὅτι Ξενοφῶν βούλεται καταμεῖναι τὴν στρατιὰν καὶ πόλιν οἰκίσαι καὶ ἑαυτῶι ὄνομα καὶ δύναμιν περιποιήσασθαι.", "st": "5.6.17"}, {"sp": "N", "t": "αὐτὸς δ᾽ ὁ Σιλανὸς ἐβούλετο ὅτι τάχιστα εἰς τὴν Ἑλλάδα ἀφικέσθαι· οὓς γὰρ παρὰ Κύρου ἔλαβε τρισχιλίους δαρεικοὺς ὅτε τὰς δέκα ἡμέρας ἠλήθευσε θυόμενος Κύρωι, διεσεσώκει.", "st": "5.6.18"}, {"sp": "N", "t": "τῶν δὲ στρατιωτῶν, ἐπεὶ ἤκουσαν, τοῖς μὲν ἐδόκει βέλτιστον εἶναι καταμεῖναι, τοῖς δὲ πολλοῖς οὔ. Τιμασίων δὲ ὁ Δαρδανεὺς καὶ Θώραξ ὁ Βοιώτιος πρὸς ἐμπόρους τινὰς παρόντας τῶν Ἡρακλεωτῶν καὶ Σινωπέων λέγουσιν ὅτι εἰ μὴ ἐκποριοῦσι τῆι στρατιᾶι μισθὸν ὥστε ἔχειν τὰ ἐπιτήδεια ἐκπλέοντας, ὅτι κινδυνεύσει μεῖναι τοσαύτη δύναμις ἐν τῶι Πόντωι· βούλεται γὰρ Ξενοφῶν καὶ ἡμᾶς παρακαλεῖ, ἐπειδὰν ἔλθηι τὰ πλοῖα, τότε εἰπεῖν ἐξαίφνης τῆι στρατιᾶι·", "st": "5.6.19"}, {"sp": "N", "t": "«ἄνδρες, νῦν μὲν ὁρῶμεν ὑμᾶς ἀπόρους ὄντας καὶ ἐν τῶι ἀπόπλωι ἔχειν τὰ ἐπιτήδεια καὶ ὡς οἴκαδε ἀπελθόντας ὀνῆσαί τι τοὺς οἴκοι· εἰ δὲ βούλεσθε τῆς κύκλωι χώρας περὶ τὸν Πόντον οἰκουμένης ἐκλεξάμενοι ὅποι ἂν βούλησθε κατασχεῖν, καὶ τὸν μὲν ἐθέλοντα ἀπιέναι οἴκαδε, τὸν δ᾽ ἐθέλοντα μένειν αὐτοῦ, πλοῖα δ᾽ ὑμῖν πάρεστιν, ὥστε ὅπηι ἂν βούλησθε ἐξαίφνης ἂν ἐπιπέσοιτε.»", "st": "5.6.20"}, {"sp": "N", "t": "ἀκούσαντες ταῦτα οἱ ἔμποροι ἀπήγγελλον ταῖς πόλεσι· ξυνέπεμψε δ᾽ αὐτοῖς Τιμασίων Δαρδανεὺς Εὐρύμαχόν τε τὸν Δαρδανέα καὶ Θώρακα τὸν Βοιώτιον ταὐτὰ ἐροῦντας. Σινωπεῖς δὲ καὶ Ἡρακλεῶται ταῦτα ἀκούσαντες πέμπουσι πρὸς τὸν Τιμασίωνα καὶ κελεύουσι προστατεῦσαι λαβόντα χρήματα ὅπως ἐκπλεύσηι ἡ στρατιά.", "st": "5.6.21"}, {"sp": "N", "t": "ὁ δὲ ἄσμενος ἀκούσας ἐν ξυλλόγωι τῶν στρατιωτῶν ὄντων λέγει τάδε. «οὐ δεῖ προσέχειν μονῆι, ὦ ἄνδρες, οὐδὲ τῆς Ἑλλάδος οὐδὲν περὶ πλείονος ποιεῖσθαι. ἀκούω δέ τινας θύεσθαι ἐπὶ τούτωι οὐδ᾽ ὑμῖν λέγοντας.", "st": "5.6.22"}, {"sp": "N", "t": "ὑπισχνοῦμαι δὲ ὑμῖν, ἂν ἐκπλέητε, ἀπὸ νουμηνίας μισθοφορὰν παρέξειν κυζικηνὸν ἑκάστωι τοῦ μηνός· καὶ ἄξω ὑμᾶς εἰς τὴν Τρωιάδα, ἔνθεν καί εἰμι φυγάς, καὶ ὑπάρξει ὑμῖν ἡ ἐμὴ πόλις· ἑκόντες γάρ με δέξονται.", "st": "5.6.23"}, {"sp": "N", "t": "ἡγήσομαι δὲ αὐτὸς ἐγὼ ἔνθεν πολλὰ χρήματα λήψεσθε. ἔμπειρος δέ εἰμι τῆς Αἰολίδος καὶ τῆς Φρυγίας καὶ τῆς Τρωιάδος καὶ τῆς Φαρναβάζου ἀρχῆς πάσης, τὰ μὲν διὰ τὸ ἐκεῖθεν εἶναι, τὰ δὲ διὰ τὸ ξυνεστρατεῦσθαι ἐν αὐτῆι σὺν Κλεάρχωι τε καὶ Δερκυλίδαι.»", "st": "5.6.24"}, {"sp": "N", "t": "ἀναστὰς αὖθις Θώραξ ὁ Βοιώτιος, ὃς περὶ στρατηγίας Ξενοφῶντι ἐμάχετο, ἔφη, εἰ ἐξέλθοιεν ἐκ τοῦ Πόντου, ἔσεσθαι αὐτοῖς Χερρόνησον χώραν καλὴν καὶ εὐδαίμονα ὥστε τῶι βουλομένωι ἐνοικεῖν, τῶι δὲ μὴ βουλομένωι ἀπιέναι οἴκαδε. γελοῖον δὲ εἶναι ἐν τῆι Ἑλλάδι οὔσης χώρας πολλῆς καὶ ἀφθόνου ἐν τῆι βαρβάρων μαστεύειν.", "st": "5.6.25"}, {"sp": "N", "t": "ἔστε δ᾽ ἄν, ἔφη, ἐκεῖ γένησθε, κἀγὼ καθάπερ Τιμασίων ὑπισχνοῦμαι ὑμῖν τὴν μισθοφοράν. ταῦτα δὲ ἔλεγεν εἰδὼς ἃ Τιμασίωνι οἱ Ἡρακλεῶται καὶ οἱ Σινωπεῖς ὑπισχνοῦντο ὥστε ἐκπλεῖν.", "st": "5.6.26"}, {"sp": "N", "t": "ὁ δὲ Ξενοφῶν ἐν τούτωι ἐσίγα. ἀναστὰς δὲ Φιλήσιος καὶ Λύκων οἱ Ἀχαιοὶ ἔλεγον ὡς δεινὸν εἴη ἰδίαι μὲν Ξενοφῶντα πείθειν τε καταμένειν καὶ θύεσθαι ὑπὲρ τῆς μονῆς [μὴ κοινούμενον τῆι στρατιᾶι], εἰς δὲ τὸ κοινὸν μηδὲν ἀγορεύειν περὶ τούτων. ὥστε ἠναγκάσθη ὁ Ξενοφῶν ἀναστῆναι καὶ εἰπεῖν τάδε.", "st": "5.6.27"}, {"sp": "N", "t": "«ἐγώ, ὦ ἄνδρες, θύομαι μὲν ὡς ὁρᾶτε ὁπόσα δύναμαι καὶ ὑπὲρ ὑμῶν καὶ ὑπὲρ ἐμαυτοῦ ὅπως ταῦτα τυγχάνω καὶ λέγων καὶ νοῶν καὶ πράττων ὁποῖα μέλλει ὑμῖν τε κάλλιστα καὶ ἄριστα ἔσεσθαι καὶ ἐμοί. καὶ νῦν ἐθυόμην περὶ αὐτοῦ τούτου, εἰ ἄμεινον εἴη ἄρχεσθαι λέγειν εἰς ὑμᾶς καὶ πράττειν περὶ τούτων ἢ παντάπασι μηδὲ ἅπτεσθαι τοῦ πράγματος.", "st": "5.6.28"}, {"sp": "N", "t": "Σιλανὸς δέ μοι ὁ μάντις ἀπεκρίνατο τὸ μὲν μέγιστον, τὰ ἱερὰ καλὰ εἶναι· ἤιδει γὰρ καὶ ἐμὲ οὐκ ἄπειρον ὄντα διὰ τὸ ἀεὶ παρεῖναι τοῖς ἱεροῖς· ἔλεξε δὲ ὅτι ἐν τοῖς ἱεροῖς φαίνοιτό τις δόλος καὶ ἐπιβουλὴ ἐμοί, ὡς ἄρα γιγνώσκων ὅτι αὐτὸς ἐπεβούλευε διαβάλλειν με πρὸς ὑμᾶς. ἐξήνεγκε γὰρ τὸν λόγον ὡς ἐγὼ πράττειν ταῦτα διανοοίμην ἤδη οὐ πείσας ὑμᾶς.", "st": "5.6.29"}, {"sp": "N", "t": "ἐγὼ δὲ εἰ μὲν ἑώρων ἀποροῦντας ὑμᾶς, τοῦτ᾽ ἂν ἐσκόπουν ἀφ᾽ οὗ ἂν γένοιτο ὥστε λαβόντας ὑμᾶς πόλιν τὸν μὲν βουλόμενον ἀποπλεῖν ἤδη, τὸν δὲ μὴ βουλόμενον, ἐπεὶ κτήσαιτο ἱκανὰ ὥστε καὶ τοὺς ἑαυτοῦ οἰκείους ὠφελῆσαί τι.", "st": "5.6.30"}, {"sp": "N", "t": "ἐπεὶ δὲ ὁρῶ ὑμῖν καὶ τὰ πλοῖα πέμποντας Ἡρακλεώτας καὶ Σινωπέας ὥστε ἐκπλεῖν, καὶ μισθὸν ὑπισχνουμένους ὑμῖν ἄνδρας ἀπὸ νουμηνίας, καλόν μοι δοκεῖ εἶναι σωιζομένους ἔνθα βουλόμεθα μισθὸν τῆς σωτηρίας λαμβάνειν, καὶ αὐτός τε παύομαι ἐκείνης τῆς διανοίας, καὶ ὁπόσοι πρὸς ἐμὲ προσῆισαν λέγοντες ὡς χρὴ ταῦτα πράττειν, ἀναπαύεσθαί φημι χρῆναι.", "st": "5.6.31"}, {"sp": "N", "t": "οὕτω γὰρ γιγνώσκω· ὁμοῦ μὲν ὄντες πολλοὶ ὥσπερ νυνὶ δοκεῖτε ἄν μοι καὶ ἔντιμοι εἶναι καὶ ἔχειν τὰ ἐπιτήδεια· ἐν γὰρ τῶι κρατεῖν ἐστι καὶ τὸ λαμβάνειν τὰ τῶν ἡττόνων· διασπασθέντες δ᾽ ἂν καὶ κατὰ μικρὰ γενομένης τῆς δυνάμεως οὔτ᾽ ἂν τροφὴν δύναισθε λαμβάνειν οὔτε χαίροντες ἂν ἀπαλλάξαιτε.", "st": "5.6.32"}, {"sp": "N", "t": "δοκεῖ οὖν μοι ἅπερ ὑμῖν, ἐκπορεύεσθαι εἰς τὴν Ἑλλάδα, καὶ ἐάν τις μέντοι ἀπολιπὼν ληφθῆι πρὶν ἐν ἀσφαλεῖ εἶναι πᾶν τὸ στράτευμα, κρίνεσθαι αὐτὸν ὡς ἀδικοῦντα. καὶ ὅτωι δοκεῖ, ἔφη, ταῦτα, ἀράτω τὴν χεῖρα.»", "st": "5.6.33"}, {"sp": "N", "t": "ἀνέτειναν ἅπαντες. ὁ δὲ Σιλανὸς ἐβόα, καὶ ἐπεχείρει λέγειν ὡς δίκαιον εἴη ἀπιέναι τὸν βουλόμενον. οἱ δὲ στρατιῶται οὐκ ἠνείχοντο, ἀλλ᾽ ἠπείλουν αὐτῶι ὅτι εἰ λήψονται ἀποδιδράσκοντα, τὴν δίκην ἐπιθήσοιεν.", "st": "5.6.34"}, {"sp": "N", "t": "ἐντεῦθεν ἐπεὶ ἔγνωσαν οἱ Ἡρακλεῶται ὅτι ἐκπλεῖν δεδογμένον εἴη καὶ Ξενοφῶν αὐτὸς ἐπεψηφικὼς εἴη, τὰ μὲν πλοῖα πέμπουσι, τὰ δὲ χρήματα ἃ ὑπέσχοντο Τιμασίωνι καὶ Θώρακι ἐψευσμένοι ἦσαν [τῆς μισθοφορᾶς].", "st": "5.6.35"}, {"sp": "N", "t": "ἐνταῦθα δὲ ἐκπεπληγμένοι ἦσαν καὶ ἐδεδίεσαν τὴν στρατιὰν οἱ τὴν μισθοφορὰν ὑπεσχημένοι. παραλαβόντες οὖν οὗτοι καὶ τοὺς ἄλλους στρατηγοὺς οἷς ἀνεκεκοίνωντο ἃ πρόσθεν ἔπραττον, πάντες δ᾽ ἦσαν πλὴν Νέωνος τοῦ Ἀσιναίου, ὃς Χειρισόφωι ὑπεστρατήγει, Χειρίσοφος δὲ οὔπω παρῆν, ἔρχονται πρὸς Ξενοφῶντα, καὶ λέγουσιν ὅτι μεταμέλοι αὐτοῖς, καὶ δοκοίη κράτιστον εἶναι πλεῖν εἰς Φᾶσιν, ἐπεὶ πλοῖα ἔστι, καὶ κατασχεῖν τὴν Φασιανῶν χώραν.", "st": "5.6.36"}, {"sp": "N", "t": "αἰήτου δὲ ὑιδοῦς ἐτύγχανε βασιλεύων αὐτῶν. Ξενοφῶν δὲ ἀπεκρίνατο ὅτι οὐδὲν ἂν τούτων εἴποι εἰς τὴν στρατιάν· «ὑμεῖς δὲ ξυλλέξαντες, ἔφη, εἰ βούλεσθε, λέγετε.» ἐνταῦθα ἀποδείκνυται Τιμασίων ὁ Δαρδανεὺς γνώμην οὐκ ἐκκλησιάζειν ἀλλὰ τοὺς αὑτοῦ ἕκαστον λοχαγοὺς πρῶτον πειρᾶσθαι πείθειν. καὶ ἀπελθόντες ταῦτ᾽ ἐποίουν.", "st": "5.6.37"}, {"sp": "N", "t": "ταῦτα οὖν οἱ στρατιῶται ἀνεπύθοντο ταραττόμενα. καὶ ὁ Νέων λέγει ὡς Ξενοφῶν ἀναπεπεικὼς τοὺς ἄλλους στρατηγοὺς διανοεῖται ἄγειν τοὺς στρατιώτας ἐξαπατήσας πάλιν εἰς Φᾶσιν.", "st": "5.7.1"}, {"sp": "N", "t": "ἀκούσαντες δ᾽ οἱ στρατιῶται χαλεπῶς ἔφερον, καὶ ξύλλογοι ἐγίγνοντο καὶ κύκλοι ξυνίσταντο καὶ μάλα φοβεροὶ ἦσαν μὴ ποιήσειαν οἷα καὶ τοὺς τῶν Κόλχων κήρυκας ἐποίησαν καὶ τοὺς ἀγορανόμους· [ὅσοι μὴ εἰς τὴν θάλατταν κατέφυγον κατελεύσθησαν.]", "st": "5.7.2"}, {"sp": "N", "t": "ἐπεὶ δὲ ἠισθάνετο Ξενοφῶν, ἔδοξεν αὐτῶι ὡς τάχιστα ξυναγαγεῖν αὐτῶν ἀγοράν, καὶ μὴ ἐᾶσαι ξυλλεγῆναι αὐτομάτους· καὶ ἐκέλευσε τὸν κήρυκα ξυλλέξαι ἀγοράν.", "st": "5.7.3"}, {"sp": "N", "t": "οἱ δ᾽ ἐπεὶ τοῦ κήρυκος ἤκουσαν, ξυνέδραμον καὶ μάλα ἑτοίμως. ἐνταῦθα Ξενοφῶν τῶν μὲν στρατηγῶν οὐ κατηγόρει, ὅτι ἦλθον πρὸς αὐτόν, λέγει δὲ ὧδε.", "st": "5.7.4"}, {"sp": "N", "t": "«ἀκούω τινὰ διαβάλλειν, ὦ ἄνδρες, ἐμὲ ὡς ἐγὼ ἄρα ἐξαπατήσας ὑμᾶς μέλλω ἄγειν εἰς Φᾶσιν. ἀκούσατε οὖν μου πρὸς θεῶν, καὶ ἐὰν μὲν ἐγὼ φαίνωμαι ἀδικεῖν, οὐ χρή με ἐνθένδε ἀπελθεῖν πρὶν ἂν δῶ δίκην· ἂν δ᾽ ὑμῖν φαίνωνται ἀδικεῖν οἱ ἐμὲ διαβάλλοντες, οὕτως αὐτοῖς χρῆσθε ὥσπερ ἄξιον.", "st": "5.7.5"}, {"sp": "N", "t": "ὑμεῖς δέ, ἔφη, ἴστε δήπου ὅθεν ἥλιος ἀνίσχει καὶ ὅπου δύεται, καὶ ὅτι ἐὰν μέν τις εἰς τὴν Ἑλλάδα μέλληι ἰέναι, πρὸς ἑσπέραν δεῖ πορεύεσθαι· ἢν δέ τις βούληται εἰς τοὺς βαρβάρους, τοὔμπαλιν πρὸς ἕω. ἔστιν οὖν ὅστις τοῦτο ἂν δύναιτο ὑμᾶς ἐξαπατῆσαι ὡς ἥλιος ἔνθεν μὲν ἀνίσχει, δύεται δὲ ἐνταῦθα, ἔνθα δὲ δύεται, ἀνίσχει δ᾽ ἐντεῦθεν;", "st": "5.7.6"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ τοῦτό γε ἐπίστασθε ὅτι βορέας μὲν ἔξω τοῦ Πόντου εἰς τὴν Ἑλλάδα φέρει, νότος δὲ εἴσω εἰς Φᾶσιν, καὶ λέγεται, ὅταν βορρᾶς πνέηι, ὡς καλοὶ πλοῖ εἰσιν εἰς τὴν Ἑλλάδα. τοῦτ᾽ οὖν ἔστιν ὅπως τις ἂν ὑμᾶς ἐξαπατήσαι ὥστε ἐμβαίνειν ὁπόταν νότος πνέηι;", "st": "5.7.7"}, {"sp": "N", "t": "ἀλλὰ γὰρ ὁπόταν γαλήνη ἦι ἐμβιβῶ. οὐκοῦν ἐγὼ μὲν ἐν ἑνὶ πλοίωι πλεύσομαι, ὑμεῖς δὲ τοὐλάχιστον ἐν ἑκατόν. πῶς ἂν οὖν ἐγὼ ἢ βιασαίμην ὑμᾶς ξὺν ἐμοὶ πλεῖν μὴ βουλομένους ἢ ἐξαπατήσας ἄγοιμι;", "st": "5.7.8"}, {"sp": "N", "t": "ποιῶ δ᾽ ὑμᾶς ἐξαπατηθέντας καὶ γοητευθέντας ὑπ᾽ ἐμοῦ ἥκειν εἰς Φᾶσιν· καὶ δὴ ἀποβαίνομεν εἰς τὴν χώραν· γνώσεσθε δήπου ὅτι οὐκ ἐν τῆι Ἑλλάδι ἐστέ· καὶ ἐγὼ μὲν ἔσομαι ὁ ἐξηπατηκὼς εἷς, ὑμεῖς δὲ οἱ ἐξηπατημένοι ἐγγὺς μυρίων ἔχοντες ὅπλα. πῶς ἂν οὖν ἀνὴρ μᾶλλον δοίη δίκην ἢ οὕτω περὶ αὑτοῦ τε καὶ ὑμῶν βουλευόμενος;", "st": "5.7.9"}, {"sp": "N", "t": "ἀλλ᾽ οὗτοί εἰσιν οἱ λόγοι ἀνδρῶν καὶ ἠλιθίων κἀμοὶ φθονούντων, ὅτι ἐγὼ ὑφ᾽ ὑμῶν τιμῶμαι. καίτοι οὐ δικαίως γ᾽ ἄν μοι φθονοῖεν· τίνα γὰρ αὐτῶν ἐγὼ κωλύω ἢ λέγειν εἴ τίς τι ἀγαθὸν δύναται ἐν ὑμῖν, ἢ μάχεσθαι εἴ τις ἐθέλει ὑπὲρ ὑμῶν τε καὶ ἑαυτοῦ, ἢ ἐγρηγορέναι περὶ τῆς ὑμετέρας ἀσφαλείας ἐπιμελούμενον; τί γάρ, ἄρχοντας αἱρουμένων ὑμῶν ἐγώ τινι ἐμποδών εἰμι; παρίημι, ἀρχέτω· μόνον ἀγαθόν τι ποιῶν ὑμᾶς φαινέσθω.", "st": "5.7.10"}, {"sp": "N", "t": "ἀλλὰ γὰρ ἐμοὶ μὲν ἀρκεῖ περὶ τούτων τὰ εἰρημένα· εἰ δέ τις ὑμῶν ἢ αὐτὸς ἐξαπατηθῆναι ἂν οἴεται ταῦτα ἢ ἄλλον ἐξαπατῆσαι ταῦτα, λέγων διδασκέτω.", "st": "5.7.11"}, {"sp": "N", "t": "ὅταν δὲ τούτων ἅλις ἔχητε, μὴ ἀπέλθητε πρὶν ἂν ἀκούσητε οἷον ὁρῶ ἐν τῆι στρατιᾶι ἀρχόμενον πρᾶγμα· ὃ εἰ ἔπεισι καὶ ἔσται οἷον ὑποδείκνυσιν, ὥρα ἡμῖν βουλεύεσθαι ὑπὲρ ἡμῶν αὐτῶν μὴ κάκιστοί τε καὶ αἴσχιστοι ἄνδρες ἀποφαινώμεθα καὶ πρὸς θεῶν καὶ πρὸς ἀνθρώπων καὶ φίλων καὶ πολεμίων.»", "st": "5.7.12"}, {"sp": "N", "t": "ἀκούσαντες δὲ ταῦτα οἱ στρατιῶται ἐθαύμασάν τε ὅ τι εἴη καὶ λέγειν ἐκέλευον. ἐκ τούτου ἄρχεται πάλιν· «ἐπίστασθέ που ὅτι χωρία ἦν ἐν τοῖς ὄρεσι βαρβαρικά, φίλια τοῖς Κερασουντίοις, ὅθεν κατιόντες τινὲς καὶ ἱερεῖα ἐπώλουν ἡμῖν καὶ ἄλλα ὧν εἶχον, δοκοῦσι δέ μοι καὶ ὑμῶν τινες εἰς τὸ ἐγγυτάτω χωρίον τούτων ἐλθόντες ἀγοράσαντές τι πάλιν ἀπελθεῖν.", "st": "5.7.13"}, {"sp": "N", "t": "τοῦτο καταμαθὼν Κλεάρετος ὁ λοχαγὸς ὅτι καὶ μικρὸν εἴη καὶ ἀφύλακτον διὰ τὸ φίλιον νομίζειν εἶναι, ἔρχεται ἐπ᾽ αὐτοὺς τῆς νυκτὸς ὡς πορθήσων, οὐδενὶ ἡμῶν εἰπών.", "st": "5.7.14"}, {"sp": "N", "t": "διενενόητο δέ, εἰ λάβοι τόδε τὸ χωρίον, εἰς μὲν τὸ στράτευμα μηκέτι ἐλθεῖν, εἰσβὰς δὲ εἰς πλοῖον ἐν ὧι ἐτύγχανον οἱ ξύσκηνοι αὐτοῦ παραπλέοντες, καὶ ἐνθέμενος εἴ τι λάβοι, ἀποπλέων οἴχεσθαι ἔξω τοῦ Πόντου. καὶ ταῦτα ξυνωμολόγησαν αὐτῶι οἱ ἐκ τοῦ πλοίου σύσκηνοι, ὡς ἐγὼ νῦν αἰσθάνομαι.", "st": "5.7.15"}, {"sp": "N", "t": "παρακαλέσας οὖν ὁπόσους ἔπειθεν ἦγεν ἐπὶ τὸ χωρίον. πορευόμενον δ᾽ αὐτὸν φθάνει ἡμέρα γενομένη, καὶ ξυστάντες οἱ ἄνθρωποι ἀπὸ ἰσχυρῶν τόπων βάλλοντες καὶ παίοντες τόν τε Κλεάρετον ἀποκτείνουσι καὶ τῶν ἄλλων συχνούς, οἱ δέ τινες καὶ εἰς Κερασοῦντα αὐτῶν ἀποχωροῦσι.", "st": "5.7.16"}, {"sp": "N", "t": "ταῦτα δ᾽ ἦν ἐν τῆι ἡμέραι ἧι ἡμεῖς δεῦρο ἐξωρμῶμεν πεζῆι· τῶν δὲ πλεόντων ἔτι τινὲς ἦσαν ἐν Κερασοῦντι, οὔπω ἀνηγμένοι. μετὰ τοῦτο, ὡς οἱ Κερασούντιοι λέγουσιν, ἀφικνοῦνται τῶν ἐκ τοῦ χωρίου τρεῖς ἄνδρες τῶν γεραιτέρων πρὸς τὸ κοινὸν τὸ ἡμέτερον χρήιζοντες ἐλθεῖν.", "st": "5.7.17"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἡμᾶς οὐ κατέλαβον, πρὸς τοὺς Κερασουντίους ἔλεγον ὅτι θαυμάζοιεν τί ἡμῖν δόξειεν ἐλθεῖν ἐπ᾽ αὐτούς. ἐπεὶ μέντοι σφεῖς λέγειν, ἔφασαν, ὅτι οὐκ ἀπὸ κοινοῦ γένοιτο τὸ πρᾶγμα, ἥδεσθαί τε αὐτοὺς καὶ μέλλειν ἐνθάδε πλεῖν, ὡς ἡμῖν λέξαι τὰ γενόμενα καὶ τοὺς νεκροὺς κελεύειν αὐτοὺς θάπτειν λαβόντας.", "st": "5.7.18"}, {"sp": "N", "t": "τῶν δ᾽ ἀποφυγόντων τινὰς Ἑλλήνων τυχεῖν ἔτι ὄντας ἐν Κερασοῦντι· αἰσθόμενοι δὲ τοὺς βαρβάρους ὅποι ἴοιεν αὐτοί τε ἐτόλμησαν βάλλειν τοῖς λίθοις καὶ τοῖς ἄλλοις παρεκελεύοντο. καὶ οἱ ἄνδρες ἀποθνήισκουσι τρεῖς ὄντες οἱ πρέσβεις καταλευσθέντες.", "st": "5.7.19"}, {"sp": "N", "t": "ἐπεὶ δὲ τοῦτο ἐγένετο, ἔρχονται πρὸς ἡμᾶς οἱ Κερασούντιοι καὶ λέγουσι τὸ πρᾶγμα· καὶ ἡμεῖς οἱ στρατηγοὶ ἀκούσαντες ἠχθόμεθά τε τοῖς γεγενημένοις καὶ ἐβουλευόμεθα ξὺν τοῖς Κερασουντίοις ὅπως ἂν ταφείησαν οἱ τῶν Ἑλλήνων νεκροί.", "st": "5.7.20"}, {"sp": "N", "t": "συγκαθήμενοι δ᾽ ἔξωθεν τῶν ὅπλων ἐξαίφνης ἀκούομεν θορύβου πολλοῦ «παῖε παῖε, βάλλε βάλλε», καὶ τάχα δὴ ὁρῶμεν πολλοὺς προσθέοντας λίθους ἔχοντας ἐν ταῖς χερσί, τοὺς δὲ καὶ ἀναιρουμένους.", "st": "5.7.21"}, {"sp": "N", "t": "καὶ οἱ μὲν Κερασούντιοι, ὡς [ἂν] καὶ ἑορακότες τὸ παρ᾽ ἑαυτοῖς πρᾶγμα, δείσαντες ἀποχωροῦσι πρὸς τὰ πλοῖα. ἦσαν δὲ νὴ Δία καὶ ἡμῶν οἳ ἔδεισαν.", "st": "5.7.22"}, {"sp": "N", "t": "ἐγώ γε μὴν ἦλθον πρὸς αὐτοὺς καὶ ἠρώτων ὅ τι ἐστὶ τὸ πρᾶγμα. τῶν δὲ ἦσαν μὲν οἳ οὐδὲν ἤιδεσαν, ὅμως δὲ λίθους εἶχον ἐν ταῖς χερσίν. ἐπεὶ δὲ εἰδότι τινὶ ἐπέτυχον, λέγει μοι ὅτι οἱ ἀγορανόμοι δεινότατα ποιοῦσι τὸ στράτευμα.", "st": "5.7.23"}, {"sp": "N", "t": "ἐν τούτωι τις ὁρᾶι τὸν ἀγορανόμον Ζήλαρχον πρὸς τὴν θάλατταν ἀποχωροῦντα, καὶ ἀνέκραγεν· οἱ δὲ ὡς ἤκουσαν, ὥσπερ ἢ συὸς ἀγρίου ἢ ἐλάφου φανέντος ἵενται ἐπ᾽ αὐτόν.", "st": "5.7.24"}, {"sp": "N", "t": "οἱ δ᾽ αὖ Κερασούντιοι ὡς εἶδον ὁρμῶντας καθ᾽ αὑτούς, σαφῶς νομίζοντες ἐπὶ σφᾶς ἵεσθαι, φεύγουσι δρόμωι καὶ ἐμπίπτουσιν εἰς τὴν θάλατταν. ξυνεισέπεσον δὲ καὶ ἡμῶν αὐτῶν τινες, καὶ ἐπνίγετο ὅστις νεῖν μὴ ἐτύγχανεν ἐπιστάμενος.", "st": "5.7.25"}, {"sp": "N", "t": "καὶ τούτους τί δοκεῖτε; ἠδίκουν μὲν οὐδέν, ἔδεισαν δὲ μὴ λύττα τις ὥσπερ κυσὶν ἡμῖν ἐμπεπτώκοι. εἰ οὖν ταῦτα τοιαῦτα ἔσται, θεάσασθε οἵα ἡ κατάστασις ἡμῖν ἔσται τῆς στρατιᾶς.", "st": "5.7.26"}, {"sp": "N", "t": "ὑμεῖς μὲν οἱ πάντες οὐκ ἔσεσθε κύριοι οὔτε ἀνελέσθαι πόλεμον ὧι ἂν βούλησθε οὔτε καταλῦσαι, ἰδίαι δὲ ὁ βουλόμενος ἄξει στράτευμα ἐφ᾽ ὅ τι ἂν θέληι. κἄν τινες πρὸς ὑμᾶς ἴωσι πρέσβεις εἰρήνης δεόμενοι ἢ ἄλλου τινός, κατακτείναντες τούτους οἱ βουλόμενοι ποιήσουσιν ὑμᾶς τῶν λόγων μὴ ἀκοῦσαι τῶν πρὸς ὑμᾶς ἰόντων.", "st": "5.7.27"}, {"sp": "N", "t": "ἔπειτα δὲ οὓς μὲν ἂν ὑμεῖς πάντες ἕλησθε ἄρχοντας, ἐν οὐδεμιᾶι χώραι ἔσονται, ὅστις δὲ ἂν ἑαυτὸν ἕληται στρατηγὸν καὶ ἐθέληι λέγειν «βάλλε βάλλε», οὗτος ἔσται ἱκανὸς καὶ ἄρχοντα κατακανεῖν καὶ ἰδιώτην ὃν ἂν ὑμῶν ἐθέληι ἄκριτον, ἢν ὦσιν οἱ πεισόμενοι αὐτῶι, ὥσπερ καὶ νῦν ἐγένετο.", "st": "5.7.28"}, {"sp": "N", "t": "οἷα δὲ ὑμῖν καὶ διαπεπράχασιν οἱ αὐθαίρετοι οὗτοι στρατηγοὶ σκέψασθε. Ζήλαρχος μὲν ὁ ἀγορανόμος εἰ μὲν ἀδικεῖ ὑμᾶς, οἴχεται ἀποπλέων οὐ δοὺς ὑμῖν δίκην· εἰ δὲ μὴ ἀδικεῖ, φεύγει ἐκ τοῦ στρατεύματος δείσας μὴ ἀδίκως ἄκριτος ἀποθάνηι.", "st": "5.7.29"}, {"sp": "N", "t": "οἱ δὲ καταλεύσαντες τοὺς πρέσβεις διεπράξαντο ὑμῖν μόνοις μὲν τῶν Ἑλλήνων εἰς Κερασοῦντα μὴ ἀσφαλὲς εἶναι, ἂν μὴ σὺν ἰσχύι ἀφικνῆσθε· τοὺς δὲ νεκροὺς οὓς πρόσθεν αὐτοὶ οἱ κατακανόντες ἐκέλευον θάπτειν, τούτους διεπράξαντο μηδὲ ξὺν κηρυκείωι ἔτι ἀσφαλὲς εἶναι ἀνελέσθαι. τίς γὰρ ἐθελήσει κῆρυξ ἰέναι κήρυκας ἀπεκτονώς; ἀλλ᾽ ἡμεῖς Κερασουντίων θάψαι αὐτοὺς ἐδεήθημεν.", "st": "5.7.30"}, {"sp": "N", "t": "εἰ μὲν οὖν ταῦτα καλῶς ἔχει, δοξάτω ὑμῖν, ἵνα ὡς τοιούτων ἐσομένων καὶ φυλακὴν ἰδίαι ποιήσηι τις καὶ τὰ ἐρυμνὰ ὑπερδέξια πειρᾶται ἔχων σκηνοῦν.", "st": "5.7.31"}, {"sp": "N", "t": "εἰ μέντοι ὑμῖν δοκεῖ θηρίων ἀλλὰ μὴ ἀνθρώπων εἶναι τὰ τοιαῦτα ἔργα, σκοπεῖτε παῦλάν τινα αὐτῶν· εἰ δὲ μή, πρὸς Διὸς πῶς ἢ θεοῖς θύσομεν ἡδέως ποιοῦντες ἔργα ἀσεβῆ, ἢ πολεμίοις πῶς μαχούμεθα, ἢν ἀλλήλους κατακαίνωμεν;", "st": "5.7.32"}, {"sp": "N", "t": "πόλις δὲ φιλία τίς ἡμᾶς δέξεται, ἥτις ἂν ὁρᾶι τοσαύτην ἀνομίαν ἐν ἡμῖν; ἀγορὰν δὲ τίς ἄξει θαρρῶν, ἢν περὶ τὰ μέγιστα τοιαῦτα ἐξαμαρτάνοντες φαινώμεθα; οὗ δὲ δὴ πάντων οἰόμεθα τεύξεσθαι ἐπαίνου, τίς ἂν ἡμᾶς τοιούτους ὄντας ἐπαινέσειεν; ἡμεῖς μὲν γὰρ οἶδ᾽ ὅτι πονηροὺς ἂν φαίημεν εἶναι τοὺς τὰ τοιαῦτα ποιοῦντας.»", "st": "5.7.33"}, {"sp": "N", "t": "ἐκ τούτου ἀνιστάμενοι πάντες ἔλεγον τοὺς μὲν τούτων ἄρξαντας δοῦναι δίκην, τοῦ δὲ λοιποῦ μηκέτι ἐξεῖναι ἀνομίας ἄρξαι· ἐὰν δέ τις ἄρξηι, ἄγεσθαι αὐτοὺς ἐπὶ θανάτωι· τοὺς δὲ στρατηγοὺς εἰς δίκας πάντας καταστῆσαι· εἶναι δὲ δίκας καὶ εἴ τι ἄλλο τις ἠδίκητο ἐξ οὗ Κῦρος ἀπέθανε· δικαστὰς δὲ τοὺς λοχαγοὺς ἐποιήσαντο.", "st": "5.7.34"}, {"sp": "N", "t": "παραινοῦντος δὲ Ξενοφῶντος καὶ τῶν μάντεων συμβουλευόντων ἔδοξε καθῆραι τὸ στράτευμα. καὶ ἐγένετο καθαρμός.", "st": "5.7.35"}, {"sp": "N", "t": "ἔδοξε δὲ καὶ τοὺς στρατηγοὺς δίκην ὑποσχεῖν τοῦ παρεληλυθότος χρόνου. καὶ διδόντων Φιλήσιος μὲν ὦφλε καὶ Ξανθικλῆς τῆς φυλακῆς τῶν γαυλικῶν χρημάτων τὸ μείωμα εἴκοσι μνᾶς, Σοφαίνετος δέ, ὅτι αἱρεθεὶς ... κατημέλει, δέκα μνᾶς. Ξενοφῶντος δὲ κατηγόρησάν τινες φάσκοντες παίεσθαι ὑπ᾽ αὐτοῦ καὶ ὡς ὑβρίζοντος τὴν κατηγορίαν ἐποιοῦντο.", "st": "5.8.1"}, {"sp": "N", "t": "καὶ ὁ Ξενοφῶν ἐκέλευσεν εἰπεῖν τὸν πρῶτον λέξαντα ποῦ καὶ ἐπλήγη. ὁ δὲ ἀπεκρίνατο· «ὅπου καὶ ῥίγει ἀπωλλύμεθα καὶ χιὼν πλείστη ἦν.»", "st": "5.8.2"}, {"sp": "N", "t": "ὁ δὲ εἶπεν· «ἀλλὰ μὴν χειμῶνός γε ὄντος οἵου λέγεις, σίτου δὲ ἐπιλελοιπότος, οἴνου δὲ μηδ᾽ ὀσφραίνεσθαι παρόν, ὑπὸ δὲ πόνων πολλῶν ἀπαγορευόντων, πολεμίων δὲ ἑπομένων, εἰ ἐν τοιούτωι καιρῶι ὕβριζον, ὁμολογῶ καὶ τῶν ὄνων ὑβριστότερος εἶναι, οἷς φασιν ὑπὸ τῆς ὕβρεως κόπον οὐκ ἐγγίγνεσθαι. ὅμως δὲ καὶ λέξον, ἔφη, ἐκ τίνος ἐπλήγης.", "st": "5.8.3"}, {"sp": "N", "t": "πότερον ἤιτουν τί σε καὶ ἐπεί μοι οὐκ ἐδίδους ἔπαιον; ἀλλ᾽ ἀπήιτουν; ἀλλὰ περὶ παιδικῶν μαχόμενος;", "st": "5.8.4"}, {"sp": "N", "t": "ἀλλὰ μεθύων ἐπαρώινησα;» ἐπεὶ δὲ τούτων οὐδὲν ἔφησεν, ἐπήρετο αὐτὸν εἰ ὁπλιτεύοι. οὐκ ἔφη· πάλιν εἰ πελτάζοι. οὐδὲ τοῦτ᾽ ἔφη, ἀλλ᾽ ἡμίονον ἐλαύνειν ταχθεὶς ὑπὸ τῶν συσκήνων ἐλεύθερος ὤν.", "st": "5.8.5"}, {"sp": "N", "t": "ἐνταῦθα δὴ ἀναγιγνώσκει αὐτὸν καὶ ἤρετο· «ἦ σὺ εἶ ὁ τὸν κάμνοντα ἀγαγών;» «ναὶ μὰ Δί᾽, ἔφη· σὺ γὰρ ἠνάγκαζες· τὰ δὲ τῶν ἐμῶν συσκήνων σκεύη διέρριψας.»", "st": "5.8.6"}, {"sp": "N", "t": "«ἀλλ᾽ ἡ μὲν διάρριψις, ἔφη ὁ Ξενοφῶν, τοιαύτη τις ἐγένετο. διέδωκα ἄλλοις ἄγειν καὶ ἐκέλευσα πρὸς ἐμὲ ἀπαγαγεῖν, καὶ ἀπολαβὼν ἅπαντα σῶια ἀπέδωκά σοι, ἐπεὶ καὶ σὺ ἐμοὶ ἀπέδειξας τὸν ἄνδρα. οἷον δὲ τὸ πρᾶγμα ἐγένετο ἀκούσατε, ἔφη· καὶ γὰρ ἄξιον.", "st": "5.8.7"}, {"sp": "N", "t": "ἀνὴρ κατελείπετο διὰ τὸ μηκέτι δύνασθαι πορεύεσθαι. καὶ ἐγὼ τὸν μὲν ἄνδρα τοσοῦτον ἐγίγνωσκον ὅτι εἷς ἡμῶν εἴη· ἠνάγκασα δὲ σὲ τοῦτον ἄγειν, ὡς μὴ ἀπόλοιτο· καὶ γάρ, ὡς ἐγὼ οἶμαι, πολέμιοι ἡμῖν ἐφείποντο.» συνέφη τοῦτο ὁ ἄνθρωπος.", "st": "5.8.8"}, {"sp": "N", "t": "«οὐκοῦν, ἔφη ὁ Ξενοφῶν, ἐπεὶ προύπεμψά σε, καταλαμβάνω αὖθις σὺν τοῖς ὀπισθοφύλαξι προσιὼν βόθρον ὀρύττοντα ὡς κατορύξοντα τὸν ἄνθρωπον, καὶ ἐπιστὰς ἐπήινουν σε.", "st": "5.8.9"}, {"sp": "N", "t": "ἐπεὶ δὲ παρεστηκότων ἡμῶν συνέκαμψε τὸ σκέλος ἁνήρ, ἀνέκραγον οἱ παρόντες ὅτι ζῆι ἁνήρ, σὺ δ᾽ εἶπας· ‹ὁπόσα γε βούλεται· ὡς ἔγωγε αὐτὸν οὐκ ἄξω.› ἐνταῦθα ἔπαισά σε·» «ἀληθῆ λέγεις·» «ἔδοξας γάρ μοι εἰδότι ἐοικέναι ὅτι ἔζη.»", "st": "5.8.10"}, {"sp": "N", "t": "«τί οὖν; ἔφη, ἧττόν τι ἀπέθανεν, ἐπεὶ ἐγώ σοι ἀπέδειξα αὐτόν;» «καὶ γὰρ ἡμεῖς, ἔφη ὁ Ξενοφῶν, πάντες ἀποθανούμεθα· τούτου οὖν ἕνεκα ζῶντας ἡμᾶς δεῖ κατορυχθῆναι;»", "st": "5.8.11"}, {"sp": "N", "t": "τοῦτον μὲν ἀνέκραγον ὡς ὀλίγας παίσειεν· ἄλλους δ᾽ ἐκέλευε λέγειν διὰ τί ἕκαστος ἐπλήγη.", "st": "5.8.12"}, {"sp": "N", "t": "ἐπεὶ δὲ οὐκ ἀνίσταντο, αὐτὸς ἔλεγεν· «ἐγώ, ὦ ἄνδρες, ὁμολογῶ παῖσαι δὴ ἄνδρας ἕνεκεν ἀταξίας ὅσοις σώιζεσθαι μὲν ἤρκει δι᾽ ὑμῶν ἐν τάξει τε ἰόντων καὶ μαχομένων ὅπου δέοι, αὐτοὶ δὲ λιπόντες τὰς τάξεις προθέοντες ἁρπάζειν ἤθελον καὶ ὑμῶν πλεονεκτεῖν. εἰ δὲ τοῦτο πάντες ἐποιοῦμεν, ἅπαντες ἂν ἀπωλόμεθα.", "st": "5.8.13"}, {"sp": "N", "t": "ἤδη δὲ καὶ μαλακιζόμενόν τινα καὶ οὐκ ἐθέλοντα ἀνίστασθαι ἀλλὰ προϊέμενον αὑτὸν τοῖς πολεμίοις καὶ ἔπαισα καὶ ἐβιασάμην πορεύεσθαι. ἐν γὰρ τῶι ἰσχυρῶι χειμῶνι καὶ αὐτός ποτε ἀναμένων τινὰς συσκευαζομένους καθεζόμενος συχνὸν χρόνον κατέμαθον ἀναστὰς μόλις καὶ τὰ σκέλη ἐκτείνας.", "st": "5.8.14"}, {"sp": "N", "t": "ἐν ἐμαυτῶι οὖν πεῖραν λαβὼν ἐκ τούτου καὶ ἄλλον, ὁπότε ἴδοιμι καθήμενον καὶ βλακεύοντα, ἤλαυνον· τὸ γὰρ κινεῖσθαι καὶ ἀνδρίζεσθαι παρεῖχε θερμασίαν τινὰ καὶ ὑγρότητα, τὸ δὲ καθῆσθαι καὶ ἡσυχίαν ἔχειν ἑώρων ὑπουργὸν ὂν τῶι τε ἀποπήγνυσθαι τὸ αἷμα καὶ τῶι ἀποσήπεσθαι τοὺς τῶν ποδῶν δακτύλους, ἅπερ πολλοὺς καὶ ὑμεῖς ἴστε παθόντας.", "st": "5.8.15"}, {"sp": "N", "t": "ἄλλον δέ γε ἴσως ἀπολειπόμενόν που διὰ ῥαιστώνην καὶ κωλύοντα καὶ ὑμᾶς τοὺς πρόσθεν καὶ ἡμᾶς τοὺς ὄπισθεν πορεύεσθαι ἔπαισα πύξ, ὅπως μὴ λόγχηι ὑπὸ τῶν πολεμίων παίοιτο.", "st": "5.8.16"}, {"sp": "N", "t": "καὶ γὰρ οὖν νῦν ἔξεστιν αὐτοῖς σωθεῖσιν, εἴ τι ὑπ᾽ ἐμοῦ ἔπαθον παρὰ τὸ δίκαιον, δίκην λαβεῖν. εἰ δ᾽ ἐπὶ τοῖς πολεμίοις ἐγένοντο, τί μέγα ἂν οὕτως ἔπαθον ὅτου δίκην ἂν ἠξίουν λαμβάνειν;", "st": "5.8.17"}, {"sp": "N", "t": "ἁπλοῦς μοι, ἔφη, ὁ λόγος· εἰ μὲν ἐπ᾽ ἀγαθῶι ἐκόλασά τινα, ἀξιῶ ὑπέχειν δίκην οἵαν καὶ γονεῖς υἱοῖς καὶ διδάσκαλοι παισί· καὶ γὰρ οἱ ἰατροὶ καίουσι καὶ τέμνουσιν ἐπ᾽ ἀγαθῶι·", "st": "5.8.18"}, {"sp": "N", "t": "εἰ δὲ ὕβρει νομίζετέ με ταῦτα πράττειν, ἐνθυμήθητε ὅτι νῦν ἐγὼ θαρρῶ σὺν τοῖς θεοῖς μᾶλλον ἢ τότε καὶ θρασύτερός εἰμι νῦν ἢ τότε καὶ οἶνον πλείω πίνω, ἀλλ᾽ ὅμως οὐδένα παίω·", "st": "5.8.19"}, {"sp": "N", "t": "ἐν εὐδίαι γὰρ ὁρῶ ὑμᾶς. ὅταν δὲ χειμὼν ἦι καὶ θάλαττα μεγάλη ἐπιφέρηται, οὐχ ὁρᾶτε ὅτι καὶ νεύματος μόνον ἕνεκα χαλεπαίνει μὲν πρωιρεὺς τοῖς ἐν πρώιραι, χαλεπαίνει δὲ κυβερνήτης τοῖς ἐν πρύμνηι; ἱκανὰ γὰρ ἐν τῶι τοιούτωι καὶ μικρὰ ἁμαρτηθέντα πάντα συνεπιτρῖψαι.", "st": "5.8.20"}, {"sp": "N", "t": "ὅτι δὲ δικαίως ἔπαιον αὐτοὺς καὶ ὑμεῖς κατεδικάσατε· ἔχοντες ξίφη, οὐ ψήφους, παρέστατε, καὶ ἐξῆν ὑμῖν ἐπικουρεῖν αὐτοῖς, εἰ ἐβούλεσθε· ἀλλὰ μὰ Δία οὔτε τούτοις ἐπεκουρεῖτε οὔτε σὺν ἐμοὶ τὸν ἀτακτοῦντα ἐπαίετε.", "st": "5.8.21"}, {"sp": "N", "t": "τοιγαροῦν ἐξουσίαν ἐποιήσατε τοῖς κακοῖς αὐτῶν ὑβρίζειν ἐῶντες αὐτούς. οἶμαι γάρ, εἰ ἐθέλετε σκοπεῖν, τοὺς αὐτοὺς εὑρήσετε καὶ τότε κακίστους καὶ νῦν ὑβριστοτάτους.", "st": "5.8.22"}, {"sp": "N", "t": "Βοΐσκος γοῦν ὁ πύκτης ὁ Θετταλὸς τότε μὲν διεμάχετο ὡς κάμνων ἀσπίδα μὴ φέρειν, νῦν δέ, ὡς ἀκούω, Κοτυωριτῶν πολλοὺς ἤδη ἀποδέδυκεν.", "st": "5.8.23"}, {"sp": "N", "t": "ἢν οὖν σωφρονῆτε, τοῦτον τἀναντία ποιήσετε ἢ τοὺς κύνας ποιοῦσι· τοὺς μὲν γὰρ κύνας τοὺς χαλεποὺς τὰς μὲν ἡμέρας διδέασι, τὰς δὲ νύκτας ἀφιᾶσι, τοῦτον δέ, ἢν σωφρονῆτε, τὴν νύκτα μὲν δήσετε, τὴν δὲ ἡμέραν ἀφήσετε.", "st": "5.8.24"}, {"sp": "N", "t": "ἀλλὰ γάρ, ἔφη, θαυμάζω ὅτι εἰ μέν τινι ὑμῶν ἀπηχθόμην, μέμνησθε καὶ οὐ σιωπᾶτε, εἰ δέ τωι ἢ χειμῶνα ἐπεκούρησα ἢ πολέμιον ἀπήρυξα ἢ ἀσθενοῦντι ἢ ἀποροῦντι συνεξεπόρισά τι, τούτων δὲ οὐδεὶς μέμνηται, οὐδ᾽ εἴ τινα καλῶς τι ποιοῦντα ἐπήινεσα οὐδ᾽ εἴ τινα ἄνδρα ὄντα ἀγαθὸν ἐτίμησα ὡς ἐδυνάμην, οὐδὲν τούτων μέμνησθε.", "st": "5.8.25"}, {"sp": "N", "t": "ἀλλὰ μὴν καλόν τε καὶ δίκαιον καὶ ὅσιον καὶ ἥδιον τῶν ἀγαθῶν μᾶλλον ἢ τῶν κακῶν μεμνῆσθαι.» ἐκ τούτου μὲν δὴ ἀνίσταντο καὶ ἀνεμίμνηισκον. καὶ περιεγένετο ὥστε καλῶς ἔχειν.", "st": "5.8.26"}, {"sp": "HDR", "t": "Βιβλίον ςʹ", "st": "6.1.1"}, {"sp": "N", "t": "ἐκ τούτου δὲ ἐν τῆι διατριβῆι οἱ μὲν ἀπὸ τῆς ἀγορᾶς ἔζων, οἱ δὲ καὶ ληιζόμενοι ἐκ τῆς Παφλαγονίας. ἐκλώπευον δὲ καὶ οἱ Παφλαγόνες εὖ μάλα τοὺς ἀποσκεδαννυμένους, καὶ τῆς νυκτὸς τοὺς πρόσω σκηνοῦντας ἐπειρῶντο κακουργεῖν· καὶ πολεμικώτατα πρὸς ἀλλήλους εἶχον ἐκ τούτων.", "st": "6.1.1"}, {"sp": "N", "t": "ὁ δὲ Κορύλας, ὃς ἐτύγχανε τότε Παφλαγονίας ἄρχων, πέμπει παρὰ τοὺς Ἕλληνας πρέσβεις ἔχοντας ἵππους καὶ στολὰς καλάς, λέγοντας ὅτι Κορύλας ἕτοιμος εἴη τοὺς Ἕλληνας μήτε ἀδικεῖν μήτε ἀδικεῖσθαι.", "st": "6.1.2"}, {"sp": "N", "t": "οἱ δὲ στρατηγοὶ ἀπεκρίναντο ὅτι περὶ μὲν τούτων σὺν τῆι στρατιᾶι βουλεύσοιντο, ἐπὶ ξένια δὲ ἐδέχοντο αὐτούς· παρεκάλεσαν δὲ καὶ τῶν ἄλλων ἀνδρῶν οὓς ἐδόκουν δικαιοτάτους εἶναι.", "st": "6.1.3"}, {"sp": "N", "t": "θύσαντες δὲ βοῦς τῶν αἰχμαλώτων καὶ ἄλλα ἱερεῖα εὐωχίαν μὲν ἀρκοῦσαν παρεῖχον, κατακείμενοι δὲ ἐν σκίμποσιν ἐδείπνουν, καὶ ἔπινον ἐκ κερατίνων ποτηρίων, οἷς ἐνετύγχανον ἐν τῆι χώραι.", "st": "6.1.4"}, {"sp": "N", "t": "ἐπεὶ δὲ σπονδαί τε ἐγένοντο καὶ ἐπαιάνισαν, ἀνέστησαν πρῶτον μὲν Θρᾶικες καὶ πρὸς αὐλὸν ὠρχήσαντο σὺν τοῖς ὅπλοις καὶ ἥλλοντο ὑψηλά τε καὶ κούφως καὶ ταῖς μαχαίραις ἐχρῶντο· τέλος δὲ ὁ ἕτερος τὸν ἕτερον παίει, ὡς πᾶσιν ἐδόκει [πεπληγέναι τὸν ἄνδρα]· ὁ δ᾽ ἔπεσε τεχνικῶς πως.", "st": "6.1.5"}, {"sp": "N", "t": "καὶ ἀνέκραγον οἱ Παφλαγόνες. καὶ ὁ μὲν σκυλεύσας τὰ ὅπλα τοῦ ἑτέρου ἐξήιει ἄιδων τὸν Σιτάλκαν· ἄλλοι δὲ τῶν Θραικῶν τὸν ἕτερον ἐξέφερον ὡς τεθνηκότα· ἦν δὲ οὐδὲν πεπονθώς.", "st": "6.1.6"}, {"sp": "N", "t": "μετὰ τοῦτο Αἰνιᾶνες καὶ Μάγνητες ἀνέστησαν, οἳ ὠρχοῦντο τὴν καρπαίαν καλουμένην ἐν τοῖς ὅπλοις.", "st": "6.1.7"}, {"sp": "N", "t": "ὁ δὲ τρόπος τῆς ὀρχήσεως ἦν, ὁ μὲν παραθέμενος τὰ ὅπλα σπείρει καὶ ζευγηλατεῖ, πυκνὰ δὲ στρεφόμενος ὡς φοβούμενος, ληιστὴς δὲ προσέρχεται· ὁ δ᾽ ἐπειδὰν προΐδηται, ἀπαντᾶι ἁρπάσας τὰ ὅπλα καὶ μάχεται πρὸ τοῦ ζεύγους· καὶ οὗτοι ταῦτ᾽ ἐποίουν ἐν ῥυθμῶι πρὸς τὸν αὐλόν· καὶ τέλος ὁ ληιστὴς δήσας τὸν ἄνδρα καὶ τὸ ζεῦγος ἀπάγει·", "st": "6.1.8"}, {"sp": "N", "t": "ἐνίοτε δὲ καὶ ὁ ζευγηλάτης τὸν ληιστήν· εἶτα παρὰ τοὺς βοῦς ζεύξας ὀπίσω τὼ χεῖρε δεδεμένον ἐλαύνει. μετὰ τοῦτο Μυσὸς εἰσῆλθεν ἐν ἑκατέραι τῆι χειρὶ ἔχων πέλτην, καὶ τοτὲ μὲν ὡς δύο ἀντιταττομένων μιμούμενος ὠρχεῖτο, τοτὲ δὲ ὡς πρὸς ἕνα ἐχρῆτο ταῖς πέλταις, τοτὲ δ᾽ ἐδινεῖτο καὶ ἐξεκυβίστα ἔχων τὰς πέλτας, ὥστε ὄψιν καλὴν φαίνεσθαι.", "st": "6.1.9"}, {"sp": "N", "t": "τέλος δὲ τὸ περσικὸν ὠρχεῖτο κρούων τὰς πέλτας καὶ ὤκλαζε καὶ ἐξανίστατο· καὶ ταῦτα πάντα ἐν ῥυθμῶι ἐποίει πρὸς τὸν αὐλόν.", "st": "6.1.10"}, {"sp": "N", "t": "ἐπὶ δὲ τούτωι [ἐπιόντες] οἱ Μαντινεῖς καὶ ἄλλοι τινὲς τῶν Ἀρκάδων ἀναστάντες ἐξοπλισάμενοι ὡς ἐδύναντο κάλλιστα ἦισάν τε ἐν ῥυθμῶι πρὸς τὸν ἐνόπλιον ῥυθμὸν αὐλούμενοι καὶ ἐπαιάνισαν καὶ ὠρχήσαντο ὥσπερ ἐν ταῖς πρὸς τοὺς θεοὺς προσόδοις. ὁρῶντες δὲ οἱ Παφλαγόνες δεινὰ ἐποιοῦντο πάσας τὰς ὀρχήσεις ἐν ὅπλοις εἶναι.", "st": "6.1.11"}, {"sp": "N", "t": "ἐπὶ τούτοις ὁρῶν ὁ Μυσὸς ἐκπεπληγμένους αὐτούς, πείσας τῶν Ἀρκάδων τινὰ πεπαμένον ὀρχηστρίδα εἰσάγει σκευάσας ὡς ἐδύνατο κάλλιστα καὶ ἀσπίδα δοὺς κούφην αὐτῆι. ἡ δὲ ὠρχήσατο πυρρίχην ἐλαφρῶς.", "st": "6.1.12"}, {"sp": "N", "t": "ἐνταῦθα κρότος ἦν πολύς, καὶ οἱ Παφλαγόνες ἤροντο εἰ καὶ γυναῖκες συνεμάχοντο αὐτοῖς. οἱ δ᾽ ἔλεγον ὅτι αὗται καὶ αἱ τρεψάμεναι εἶεν βασιλέα ἐκ τοῦ στρατοπέδου. τῆι μὲν νυκτὶ ταύτηι τοῦτο τὸ τέλος ἐγένετο.", "st": "6.1.13"}, {"sp": "N", "t": "τῆι δὲ ὑστεραίαι προσῆγον αὐτοὺς εἰς τὸ στράτευμα· καὶ ἔδοξε τοῖς στρατιώταις μήτε ἀδικεῖν Παφλαγόνας μήτε ἀδικεῖσθαι. μετὰ τοῦτο οἱ μὲν πρέσβεις ὤιχοντο· οἱ δὲ Ἕλληνες, ἐπειδὴ πλοῖα ἱκανὰ ἐδόκει παρεῖναι, ἀναβάντες ἔπλεον ἡμέραν καὶ νύκτα πνεύματι καλῶι ἐν ἀριστερᾶι ἔχοντες τὴν Παφλαγονίαν.", "st": "6.1.14"}, {"sp": "N", "t": "τῆι δ᾽ ἄλληι ἀφικνοῦνται εἰς Σινώπην καὶ ὡρμίσαντο εἰς Ἁρμήνην τῆς Σινώπης. Σινωπεῖς δὲ οἰκοῦσι μὲν ἐν τῆι Παφλαγονικῆι, Μιλησίων δὲ ἄποικοί εἰσιν. οὗτοι δὲ ξένια πέμπουσι τοῖς Ἕλλησιν ἀλφίτων μεδίμνους τρισχιλίους, οἴνου δὲ κεράμια χίλια καὶ πεντακόσια. καὶ Χειρίσοφος ἐνταῦθα ἦλθε τριήρη ἔχων.", "st": "6.1.15"}, {"sp": "N", "t": "καὶ οἱ μὲν στρατιῶται προσεδόκων ἄγοντά τι σφίσιν ἥκειν· ὁ δ᾽ ἦγε μὲν οὐδέν, ἀπήγγελλε δὲ ὅτι ἐπαινοίη αὐτοὺς καὶ Ἀναξίβιος ὁ ναύαρχος καὶ οἱ ἄλλοι, καὶ ὅτι ὑπισχνεῖτο Ἀναξίβιος, εἰ ἀφίκοιντο ἔξω τοῦ Πόντου, μισθοφορὰν αὐτοῖς ἔσεσθαι.", "st": "6.1.16"}, {"sp": "N", "t": "καὶ ἐν ταύτηι τῆι Ἁρμήνηι ἔμειναν οἱ στρατιῶται ἡμέρας πέντε. ὡς δὲ τῆς Ἑλλάδος ἐδόκουν ἐγγὺς γίγνεσθαι, ἤδη μᾶλλον ἢ πρόσθεν εἰσήιει αὐτοὺς ὅπως ἂν καὶ ἔχοντές τι οἴκαδε ἀφίκωνται.", "st": "6.1.17"}, {"sp": "N", "t": "ἡγήσαντο οὖν, εἰ ἕνα ἕλοιντο ἄρχοντα, μᾶλλον ἂν ἢ πολυαρχίας οὔσης δύνασθαι τὸν ἕνα χρῆσθαι τῶι στρατεύματι καὶ νυκτὸς καὶ ἡμέρας, καὶ εἴ τι δέοι λανθάνειν, μᾶλλον ἂν κρύπτεσθαι, καὶ εἴ τι αὖ δέοι φθάνειν, ἧττον ἂν ὑστερίζειν· οὐ γὰρ ἂν λόγων δεῖν πρὸς ἀλλήλους, ἀλλὰ τὸ δόξαν τῶι ἑνὶ περαίνεσθαι ἄν· τὸν δ᾽ ἔμπροσθεν χρόνον ἐκ τῆς νικώσης ἔπραττον πάντα οἱ στρατηγοί.", "st": "6.1.18"}, {"sp": "N", "t": "ὡς δὲ ταῦτα διενοοῦντο, ἐτράποντο ἐπὶ τὸν Ξενοφῶντα· καὶ οἱ λοχαγοὶ ἔλεγον προσιόντες αὐτῶι ὅτι ἡ στρατιὰ οὕτω γιγνώσκει, καὶ εὔνοιαν ἐνδεικνύμενος ἕκαστος ἔπειθεν αὐτὸν ὑποστῆναι τὴν ἀρχήν.", "st": "6.1.19"}, {"sp": "N", "t": "ὁ δὲ Ξενοφῶν τῆι μὲν ἐβούλετο ταῦτα, νομίζων καὶ τὴν τιμὴν μείζω οὕτως ἑαυτῶι γίγνεσθαι πρὸς τοὺς φίλους καὶ εἰς τὴν πόλιν τοὔνομα μεῖζον ἀφίξεσθαι αὑτοῦ, τυχὸν δὲ καὶ ἀγαθοῦ τινος ἂν αἴτιος τῆι στρατιᾶι γενέσθαι.", "st": "6.1.20"}, {"sp": "N", "t": "τὰ μὲν δὴ τοιαῦτα ἐνθυμήματα ἐπῆιρεν αὐτὸν ἐπιθυμεῖν αὐτοκράτορα γενέσθαι ἄρχοντα. ὁπότε δ᾽ αὖ ἐνθυμοῖτο ὅτι ἄδηλον μὲν παντὶ ἀνθρώπωι ὅπηι τὸ μέλλον ἕξει, διὰ τοῦτο δὲ καὶ κίνδυνος εἴη καὶ τὴν προειργασμένην δόξαν ἀποβαλεῖν, ἠπορεῖτο.", "st": "6.1.21"}, {"sp": "N", "t": "διαπορουμένωι δὲ αὐτῶι διακρῖναι ἔδοξε κράτιστον εἶναι τοῖς θεοῖς ἀνακοινῶσαι· καὶ παραστησάμενος δύο ἱερεῖα ἐθύετο τῶι Διὶ τῶι βασιλεῖ, ὅσπερ αὐτῶι μαντευτὸς ἦν ἐκ Δελφῶν· καὶ τὸ ὄναρ δὴ ἀπὸ τούτου τοῦ θεοῦ ἐνόμιζεν ἑορακέναι ὃ εἶδεν ὅτε ἤρχετο ἐπὶ τὸ συνεπιμελεῖσθαι τῆς στρατιᾶς καθίστασθαι.", "st": "6.1.22"}, {"sp": "N", "t": "καὶ ὅτε ἐξ Ἐφέσου ὡρμᾶτο Κύρωι συσταθησόμενος, αἰετὸν ἀνεμιμνήισκετο ἑαυτῶι δεξιὸν φθεγγόμενον, καθήμενον μέντοι, ὅνπερ ὁ μάντις προπέμπων αὐτὸν ἔλεγεν ὅτι μέγας μὲν οἰωνὸς εἴη καὶ οὐκ ἰδιωτικός, καὶ ἔνδοξος, ἐπίπονος μέντοι· τὰ γὰρ ὄρνεα μάλιστα ἐπιτίθεσθαι τῶι αἰετῶι καθημένωι· οὐ μέντοι χρηματιστικὸν εἶναι τὸν οἰωνόν· τὸν γὰρ αἰετὸν πετόμενον μᾶλλον λαμβάνειν τὰ ἐπιτήδεια.", "st": "6.1.23"}, {"sp": "N", "t": "οὕτω δὴ θυομένωι αὐτῶι διαφανῶς ὁ θεὸς σημαίνει μήτε προσδεῖσθαι τῆς ἀρχῆς μήτε εἰ αἱροῖντο ἀποδέχεσθαι. τοῦτο μὲν δὴ οὕτως ἐγένετο.", "st": "6.1.24"}, {"sp": "N", "t": "ἡ δὲ στρατιὰ συνῆλθε, καὶ πάντες ἔλεγον ἕνα αἱρεῖσθαι· καὶ ἐπεὶ τοῦτο ἔδοξε, προυβάλλοντο αὐτόν. ἐπεὶ δὲ ἐδόκει δῆλον εἶναι ὅτι αἱρήσονται αὐτόν, εἴ τις ἐπιψηφίζοι, ἀνέστη καὶ ἔλεξε τάδε.", "st": "6.1.25"}, {"sp": "N", "t": "«ἐγώ, ὦ ἄνδρες, ἥδομαι μὲν ὑφ᾽ ὑμῶν τιμώμενος, εἴπερ ἄνθρωπός εἰμι, καὶ χάριν ἔχω καὶ εὔχομαι δοῦναί μοι τοὺς θεοὺς αἴτιόν τινος ὑμῖν ἀγαθοῦ γενέσθαι· τὸ μέντοι ἐμὲ προκριθῆναι ὑφ᾽ ὑμῶν ἄρχοντα Λακεδαιμονίου ἀνδρὸς παρόντος οὔτε ὑμῖν μοι δοκεῖ συμφέρον εἶναι, ἀλλ᾽ ἧττον ἂν διὰ τοῦτο τυγχάνειν, εἴ τι δέοισθε παρ᾽ αὐτῶν· ἐμοί τε αὖ οὐ πάνυ τι νομίζω ἀσφαλὲς εἶναι τοῦτο.", "st": "6.1.26"}, {"sp": "N", "t": "ὁρῶ γὰρ ὅτι καὶ τῆι πατρίδι μου οὐ πρόσθεν ἐπαύσαντο πολεμοῦντες πρὶν ἐποίησαν πᾶσαν τὴν πόλιν ὁμολογεῖν Λακεδαιμονίους καὶ αὐτῶν ἡγεμόνας εἶναι.", "st": "6.1.27"}, {"sp": "N", "t": "ἐπεὶ δὲ τοῦτο ὡμολόγησαν, εὐθὺς ἐπαύσαντο πολεμοῦντες καὶ οὐκέτι πέρα ἐπολιόρκησαν τὴν πόλιν. εἰ οὖν ταῦτα ὁρῶν ἐγὼ δοκοίην ὅπου δυναίμην ἐνταῦθ᾽ ἄκυρον ποιεῖν τὸ ἐκείνων ἀξίωμα, ἐκεῖνο ἐννοῶ μὴ λίαν ἂν ταχὺ σωφρονισθείην.", "st": "6.1.28"}, {"sp": "N", "t": "ὃ δὲ ὑμεῖς ἐννοεῖτε, ὅτι ἧττον ἂν στάσις εἴη ἑνὸς ἄρχοντος ἢ πολλῶν, εὖ ἴστε ὅτι ἄλλον μὲν ἑλόμενοι οὐχ εὑρήσετε ἐμὲ στασιάζοντα· νομίζω γὰρ ὅστις ἐν πολέμωι ὢν στασιάζει πρὸς ἄρχοντα, τοῦτον πρὸς τὴν ἑαυτοῦ σωτηρίαν στασιάζειν· ἐὰν δὲ ἐμὲ ἕλησθε, οὐκ ἂν θαυμάσαιμι εἴ τινα εὕροιτε καὶ ὑμῖν καὶ ἐμοὶ ἀχθόμενον.»", "st": "6.1.29"}, {"sp": "N", "t": "ἐπεὶ ταῦτα εἶπε, πολὺ πλείονες ἀνίσταντο λέγοντες ὡς δέοι αὐτὸν ἄρχειν. Ἀγασίας δὲ Στυμφάλιος εἶπεν ὅτι γελοῖον εἴη, εἰ οὕτως ἔχοι· ⟨ἢ⟩ ὀργιοῦνται Λακεδαιμόνιοι καὶ ἐὰν σύνδειπνοι συνελθόντες μὴ Λακεδαιμόνιον συμποσίαρχον αἱρῶνται; ἐπεὶ εἰ οὕτω γε τοῦτο ἔχει, ἔφη, οὐδὲ λοχαγεῖν ἡμῖν ἔξεστιν, ὡς ἔοικεν, ὅτι Ἀρκάδες ἐσμέν. ἐνταῦθα δὴ ὡς εὖ εἰπόντος τοῦ Ἀγασίου ἀνεθορύβησαν.", "st": "6.1.30"}, {"sp": "N", "t": "καὶ ὁ Ξενοφῶν ἐπεὶ ἑώρα πλείονος ἐνδέον, παρελθὼν εἶπεν· «ἀλλ᾽, ὦ ἄνδρες, ἔφη, ὡς πάνυ εἰδῆτε, ὀμνύω ὑμῖν θεοὺς πάντας καὶ πάσας, ἦ μὴν ἐγώ, ἐπεὶ τὴν ὑμετέραν γνώμην ἠισθανόμην, ἐθυόμην εἰ βέλτιον εἴη ὑμῖν τε ἐμοὶ ἐπιτρέψαι ταύτην τὴν ἀρχὴν καὶ ἐμοὶ ὑποστῆναι· καί μοι οἱ θεοὶ οὕτως ἐν τοῖς ἱεροῖς ἐσήμηναν ὥστε καὶ ἰδιώτην ἂν γνῶναι ὅτι τῆς μοναρχίας ἀπέχεσθαί με δεῖ.»", "st": "6.1.31"}, {"sp": "N", "t": "οὕτω δὴ Χειρίσοφον αἱροῦνται. Χειρίσοφος δ᾽ ἐπεὶ ἡιρέθη, παρελθὼν εἶπεν· «ἀλλ᾽, ὦ ἄνδρες, τοῦτο μὲν ἴστε, ὅτι οὐδ᾽ ἂν ἔγωγε ἐστασίαζον, εἰ ἄλλον εἵλεσθε· Ξενοφῶντα μέντοι, ἔφη, ὠνήσατε οὐχ ἑλόμενοι· ὡς καὶ νῦν Δέξιππος ἤδη διέβαλλεν αὐτὸν πρὸς Ἀναξίβιον ὅ τι ἐδύνατο καὶ μάλα ἐμοῦ αὐτὸν σιγάζοντος. ὁ δ᾽ ἔφη νομίζειν αὐτὸν Τιμασίωνι μᾶλλον ἄρχειν συνεθελῆσαι Δαρδανεῖ ὄντι τοῦ Κλεάρχου στρατεύματος ἢ ἑαυτῶι Λάκωνι ὄντι.", "st": "6.1.32"}, {"sp": "N", "t": "ἐπεὶ μέντοι ἐμὲ εἵλεσθε, ἔφη, καὶ ἐγὼ πειράσομαι ὅ τι ἂν δύνωμαι ὑμᾶς ἀγαθὸν ποιεῖν. καὶ ὑμεῖς οὕτω παρασκευάζεσθε ὡς αὔριον, ἐὰν πλοῦς ἦι, ἀναξόμενοι· ὁ δὲ πλοῦς ἔσται εἰς Ἡράκλειαν· ἅπαντας οὖν δεῖ ἐκεῖσε πειρᾶσθαι κατασχεῖν· τὰ δ᾽ ἄλλα, ἐπειδὰν ἐκεῖσε ἔλθωμεν, βουλευσόμεθα.»", "st": "6.1.33"}, {"sp": "N", "t": "ἐντεῦθεν τῆι ὑστεραίαι ἀναγόμενοι πνεύματι ἔπλεον καλῶι ἡμέρας δύο παρὰ γῆν. καὶ παραπλέοντες [ἐθεώρουν τήν τε Ἰασονίαν ἀκτήν, ἔνθα ἡ Ἀργὼ λέγεται ὁρμίσασθαι, καὶ τῶν ποταμῶν τὰ στόματα, πρῶτον μὲν τοῦ Θερμώδοντος, ἔπειτα δὲ τοῦ Ἴριος, ἔπειτα δὲ τοῦ Ἅλυος, μετὰ τοῦτον τοῦ Παρθενίου· τοῦτον δὲ παραπλεύσαντες] ἀφίκοντο εἰς Ἡράκλειαν πόλιν Ἑλληνίδα Μεγαρέων ἄποικον, οὖσαν δ᾽ ἐν τῆι Μαριανδυνῶν χώραι.", "st": "6.2.1"}, {"sp": "N", "t": "καὶ ὡρμίσαντο παρὰ τῆι Ἀχερουσιάδι Χερρονήσωι, ἔνθα λέγεται ὁ Ἡρακλῆς ἐπὶ τὸν Κέρβερον κύνα καταβῆναι ἧι νῦν τὰ σημεῖα δεικνύασι τῆς καταβάσεως τὸ βάθος πλέον ἢ ἐπὶ δύο στάδια.", "st": "6.2.2"}, {"sp": "N", "t": "ἐνταῦθα τοῖς Ἕλλησιν οἱ Ἡρακλεῶται ξένια πέμπουσιν ἀλφίτων μεδίμνους τρισχιλίους καὶ οἴνου κεράμια δισχίλια καὶ βοῦς εἴκοσι καὶ οἶς ἑκατόν. ἐνταῦθα διὰ τοῦ πεδίου ῥεῖ ποταμὸς Λύκος ὄνομα, εὖρος ὡς δύο πλέθρων.", "st": "6.2.3"}, {"sp": "N", "t": "οἱ δὲ στρατιῶται συλλεγέντες ἐβουλεύοντο τὴν λοιπὴν πορείαν πότερον κατὰ γῆν ἢ κατὰ θάλατταν χρὴ πορευθῆναι ἐκ τοῦ Πόντου. ἀναστὰς δὲ Λύκων Ἀχαιὸς εἶπε· «θαυμάζω μέν, ὦ ἄνδρες, τῶν στρατηγῶν ὅτι οὐ πειρῶνται ἡμῖν ἐκπορίζειν σιτηρέσιον· τὺ μὲν γὰρ ξένια οὐ μὴ γένηται τῆι στρατιᾶι τριῶν ἡμερῶν σιτία· ὁπόθεν δ᾽ ἐπισιτισάμενοι πορευσόμεθα οὐκ ἔστιν, ἔφη. ἐμοὶ οὖν δοκεῖ αἰτεῖν τοὺς Ἡρακλεώτας μὴ ἔλαττον ἢ τρισχιλίους κυζικηνούς·»", "st": "6.2.4"}, {"sp": "N", "t": "ἄλλος δ᾽ εἶπε μὴ ἔλαττον ἢ μυρίους· καὶ ἑλομένους πρέσβεις αὐτίκα μάλα ἡμῶν καθημένων πέμπειν πρὸς τὴν πόλιν, καὶ εἰδέναι ὅ τι ἂν ἀπαγγέλλωσι, καὶ πρὸς ταῦτα βουλεύεσθαι.", "st": "6.2.5"}, {"sp": "N", "t": "ἐντεῦθεν προυβάλλοντο πρέσβεις πρῶτον μὲν Χειρίσοφον, ὅτι ἄρχων ἥιρητο· ἔστι δ᾽ οἳ καὶ Ξενοφῶντα. οἱ δὲ ἰσχυρῶς ἀπεμάχοντο· ἀμφοῖν γὰρ ταὐτὰ ἐδόκει μὴ ἀναγκάζειν πόλιν Ἑλληνίδα καὶ φιλίαν ὅ τι μὴ αὐτοὶ ἐθέλοντες διδοῖεν.", "st": "6.2.6"}, {"sp": "N", "t": "ἐπεὶ δ᾽ οὗτοι ἐδόκουν ἀπρόθυμοι εἶναι, πέμπουσι Λύκωνα Ἀχαιὸν καὶ Καλλίμαχον Παρράσιον καὶ Ἀγασίαν Στυμφάλιον. οὗτοι ἐλθόντες ἔλεγον τὰ δεδογμένα· τὸν δὲ Λύκωνα ἔφασαν καὶ ἐπαπειλεῖν, εἰ μὴ ποιήσοιεν ταῦτα.", "st": "6.2.7"}, {"sp": "N", "t": "ἀκούσαντες δ᾽ οἱ Ἡρακλεῶται βουλεύσεσθαι ἔφασαν· καὶ εὐθὺς τά τε χρήματα ἐκ τῶν ἀγρῶν συνῆγον καὶ τὴν ἀγορὰν εἴσω ἀνεσκεύασαν, καὶ αἱ πύλαι ἐκέκλειντο καὶ ἐπὶ τῶν τειχῶν ὅπλα ἐφαίνετο.", "st": "6.2.8"}, {"sp": "N", "t": "ἐκ τούτου οἱ ταράξαντες ταῦτα τοὺς στρατηγοὺς ἠιτιῶντο διαφθείρειν τὴν πρᾶξιν· καὶ συνίσταντο οἱ Ἀρκάδες καὶ οἱ Ἀχαιοί· προειστήκει δὲ μάλιστα αὐτῶν Καλλίμαχός τε ὁ Παρράσιος καὶ Λύκων ὁ Ἀχαιός.", "st": "6.2.9"}, {"sp": "N", "t": "οἱ δὲ λόγοι ἦσαν αὐτοῖς ὡς αἰσχρὸν εἴη ἄρχειν Ἀθηναῖον Πελοποννησίων καὶ Λακεδαιμόνιον, μηδεμίαν δύναμιν παρεχόμενον εἰς τὴν στρατιάν, καὶ τοὺς μὲν πόνους σφᾶς ἔχειν, τὰ δὲ κέρδη ἄλλους, καὶ ταῦτα τὴν σωτηρίαν σφῶν κατειργασμένων· εἶναι γὰρ τοὺς κατειργασμένους Ἀρκάδας καὶ Ἀχαιούς, τὸ δ᾽ ἄλλο στράτευμα οὐδὲν εἶναι (καὶ ἦν δὲ τῆι ἀληθείαι ὑπὲρ ἥμισυ τοῦ στρατεύματος Ἀρκάδες καὶ Ἀχαιοί)·", "st": "6.2.10"}, {"sp": "N", "t": "εἰ οὖν σωφρονοῖεν, αὐτοὶ συστάντες καὶ στρατηγοὺς ἑλόμενοι ἑαυτῶν καθ᾽ ἑαυτοὺς ἂν τὴν πορείαν ποιοῖντο καὶ πειρῶιντο ἀγαθόν τι λαμβάνειν.", "st": "6.2.11"}, {"sp": "N", "t": "ταῦτ᾽ ἔδοξε· καὶ ἀπολιπόντες Χειρίσοφον εἴ τινες ἦσαν παρ᾽ αὐτῶι Ἀρκάδες ἢ Ἀχαιοὶ καὶ Ξενοφῶντα συνέστησαν καὶ στρατηγοὺς αἱροῦνται ἑαυτῶν δέκα· τούτους δὲ ἐψηφίσαντο ἐκ τῆς νικώσης ὅ τι δοκοίη τοῦτο ποιεῖν. ἡ μὲν οὖν τοῦ παντὸς ἀρχὴ Χειρισόφωι ἐνταῦθα κατελύθη ἡμέραι ἕκτηι ἢ ἑβδόμηι ἀφ᾽ ἧς ἡιρέθη.", "st": "6.2.12"}, {"sp": "N", "t": "Ξενοφῶν μέντοι ἐβούλετο κοινῆι μετ᾽ αὐτῶν τὴν πορείαν ποιεῖσθαι, νομίζων οὕτως ἀσφαλεστέραν εἶναι ἢ ἰδίαι ἕκαστον στέλλεσθαι· ἀλλὰ Νέων ἔπειθεν αὐτὸν καθ᾽ αὑτὸν πορεύεσθαι, ἀκούσας τοῦ Χειρισόφου ὅτι Κλέανδρος ὁ ἐν Βυζαντίωι ἁρμοστὴς φαίη τριήρεις ἔχων ἥξειν εἰς Κάλπης λιμένα·", "st": "6.2.13"}, {"sp": "N", "t": "ὅπως οὖν μηδεὶς μετάσχοι, ἀλλ᾽ αὐτοὶ καὶ οἱ αὐτῶν στρατιῶται ἐκπλεύσειαν ἐπὶ τῶν τριήρων, διὰ ταῦτα συνεβούλευε. καὶ Χειρίσοφος, ἅμα μὲν ἀθυμῶν τοῖς γεγενημένοις, ἅμα δὲ μισῶν ἐκ τούτου τὸ στράτευμα, ἐπιτρέπει αὐτῶι ποιεῖν ὅ τι βούλεται.", "st": "6.2.14"}, {"sp": "N", "t": "Ξενοφῶν δὲ ἔτι μὲν ἐπεχείρησεν ἀπαλλαγεὶς τῆς στρατιᾶς ἐκπλεῦσαι· θυομένωι δὲ αὐτῶι τῶι ἡγεμόνι Ἡρακλεῖ καὶ κοινουμένωι, πότερα λῶιον καὶ ἄμεινον εἴη στρατεύεσθαι ἔχοντι τοὺς παραμείναντας τῶν στρατιωτῶν ἢ ἀπαλλάττεσθαι, ἐσήμηνεν ὁ θεὸς τοῖς ἱεροῖς συστρατεύεσθαι.", "st": "6.2.15"}, {"sp": "N", "t": "οὕτω γίγνεται τὸ στράτευμα τρίχα, Ἀρκάδες μὲν καὶ Ἀχαιοὶ πλείους ἢ τετρακισχίλιοι, ὁπλῖται πάντες, Χειρισόφωι δ᾽ ὁπλῖται μὲν εἰς τετρακοσίους καὶ χιλίους, πελτασταὶ δὲ εἰς ἑπτακοσίους, οἱ Κλεάρχου Θρᾶικες, Ξενοφῶντι δὲ ὁπλῖται μὲν εἰς ἑπτακοσίους καὶ χιλίους, πελτασταὶ δὲ εἰς τριακοσίους· ἱππικὸν δὲ μόνος οὗτος εἶχεν, ἀμφὶ τετταράκοντα ἱππέας.", "st": "6.2.16"}, {"sp": "N", "t": "καὶ οἱ μὲν Ἀρκάδες διαπραξάμενοι πλοῖα παρὰ τῶν Ἡρακλεωτῶν πρῶτοι πλέουσιν, ὅπως ἐξαίφνης ἐπιπεσόντες τοῖς Βιθυνοῖς λάβοιεν ὅτι πλεῖστα· καὶ ἀποβαίνουσιν εἰς Κάλπης λιμένα κατὰ μέσον πως τῆς Θράικης.", "st": "6.2.17"}, {"sp": "N", "t": "Χειρίσοφος δ᾽ εὐθὺς ἀπὸ τῆς πόλεως τῶν Ἡρακλεωτῶν ἀρξάμενος πεζῆι ἐπορεύετο διὰ τῆς χώρας· ἐπεὶ δὲ εἰς τὴν Θράικην ἐνέβαλε, παρὰ τὴν θάλατταν ἤιει·", "st": "6.2.18"}, {"sp": "N", "t": "καὶ γὰρ ἠσθένει. Ξενοφῶν δὲ πλοῖα λαβὼν ἀποβαίνει ἐπὶ τὰ ὅρια τῆς Θράικης καὶ τῆς Ἡρακλεώτιδος καὶ διὰ μεσογείας ἐπορεύετο.", "st": "6.2.19"}, {"sp": "N", "t": "[ὃν μὲν οὖν τρόπον ἥ τε Χειρισόφου ἀρχὴ τοῦ παντὸς κατελύθη καὶ τῶν Ἑλλήνων τὸ στράτευμα ἐσχίστη ἐν τοῖς ἐπάνω εἴρηται.]", "st": "6.3.1"}, {"sp": "N", "t": "ἔπραξαν δ᾽ αὐτῶν ἕκαστοι τάδε. οἱ μὲν Ἀρκάδες ὡς ἀπέβησαν νυκτὸς εἰς Κάλπης λιμένα, πορεύονται εἰς τὰς πρώτας κώμας, στάδια ἀπὸ θαλάττης ὡς τριάκοντα. ἐπεὶ δὲ φῶς ἐγένετο, ἦγεν ἕκαστος ὁ στρατηγὸς τὸν αὑτοῦ λόχον ἐπὶ κώμην· ὁποία δὲ μείζων ἐδόκει εἶναι, σύνδυο λόχους ἦγον οἱ στρατηγοί.", "st": "6.3.2"}, {"sp": "N", "t": "συνεβάλλοντο δὲ καὶ λόφον εἰς ὃν δέοι πάντας ἁλίζεσθαι· καὶ ἅτε ἐξαίφνης ἐπιπεσόντες ἀνδράποδά τε πολλὰ ἔλαβον καὶ πρόβατα πολλὰ περιεβάλλοντο.", "st": "6.3.3"}, {"sp": "N", "t": "οἱ δὲ Θρᾶικες ἡθροίζοντο οἱ διαφεύγοντες· πολλοὶ δὲ διέφευγον πελτασταὶ ὄντες ὁπλίτας ἐξ αὐτῶν τῶν χειρῶν. ἐπεὶ δὲ συνελέγησαν, πρῶτον μὲν τῶι Σμίκρητος λόχωι ἑνὸς τῶν Ἀρκάδων στρατηγῶν ἀπιόντι ἤδη εἰς τὸ συγκείμενον καὶ πολλὰ χρήματα ἄγοντι ἐπιτίθενται.", "st": "6.3.4"}, {"sp": "N", "t": "καὶ τέως μὲν ἐμάχοντο ἅμα πορευόμενοι οἱ Ἕλληνες, ἐπὶ δὲ διαβάσει χαράδρας τρέπονται αὐτούς, καὶ αὐτόν τε τὸν Σμίκρητα ἀποκτιννύασι καὶ τοὺς ἄλλους πάντας· ἄλλου δὲ λόχου τῶν δέκα στρατηγῶν τοῦ Ἡγησάνδρου ὀκτὼ μόνους ἔλιπον· καὶ αὐτὸς Ἡγήσανδρος ἐσώθη.", "st": "6.3.5"}, {"sp": "N", "t": "καὶ οἱ ἄλλοι δὲ λόχοι συνῆλθον οἱ μὲν σὺν πράγμασιν οἱ δὲ ἄνευ πραγμάτων· οἱ δὲ Θρᾶικες ἐπεὶ ηὐτύχησαν τοῦτο τὸ εὐτύχημα, συνεβόων τε ἀλλήλους καὶ συνελέγοντο ἐρρωμένως τῆς νυκτός. καὶ ἅμα ἡμέραι κύκλωι περὶ τὸν λόφον ἔνθα οἱ Ἕλληνες ἐστρατοπεδεύοντο ἐτάττοντο καὶ ἱππεῖς πολλοὶ καὶ πελτασταί, καὶ ἀεὶ πλέονες συνέρρεον· καὶ προσέβαλλον πρὸς τοὺς ὁπλίτας ἀσφαλῶς·", "st": "6.3.6"}, {"sp": "N", "t": "οἱ μὲν γὰρ Ἕλληνες οὔτε τοξότην εἶχον οὔτε ἀκοντιστὴν οὔτε ἱππέα· οἱ δὲ προσθέοντες καὶ προσελαύνοντες ἠκόντιζον· ὁπότε δὲ αὐτοῖς ἐπίοιεν, ῥαιδίως ἀπέφευγον· ἄλλοι δὲ ἄλληι ἐπετίθεντο.", "st": "6.3.7"}, {"sp": "N", "t": "καὶ τῶν μὲν πολλοὶ ἐτιτρώσκοντο, τῶν δὲ οὐδείς· ὥστε κινηθῆναι οὐκ ἐδύναντο ἐκ τοῦ χωρίου, ἀλλὰ τελευτῶντες καὶ ἀπὸ τοῦ ὕδατος εἶργον αὐτοὺς οἱ Θρᾶικες.", "st": "6.3.8"}, {"sp": "N", "t": "ἐπεὶ δὲ ἀπορία πολλὴ ἦν, διελέγοντο περὶ σπονδῶν· καὶ τὰ μὲν ἄλλα ὡμολόγητο αὐτοῖς, ὁμήρους δὲ οὐκ ἐδίδοσαν οἱ Θρᾶικες αἰτούντων τῶν Ἑλλήνων, ἀλλ᾽ ἐν τούτωι ἴσχετο. τὰ μὲν δὴ τῶν Ἀρκάδων οὕτως εἶχε.", "st": "6.3.9"}, {"sp": "N", "t": "Χειρίσοφος δὲ ἀσφαλῶς πορευόμενος παρὰ θάλατταν ἀφικνεῖται εἰς Κάλπης λιμένα. Ξενοφῶντι δὲ διὰ τῆς μεσογείας πορευομένωι οἱ ἱππεῖς καταθέοντες ἐντυγχάνουσι πρεσβύταις πορευομένοις ποι. καὶ ἐπεὶ ἤχθησαν παρὰ Ξενοφῶντα, ἐρωτᾶι αὐτοὺς εἴ που ἤισθηνται ἄλλου στρατεύματος ὄντος Ἑλληνικοῦ.", "st": "6.3.10"}, {"sp": "N", "t": "οἱ δὲ ἔλεγον πάντα τὰ γεγενημένα, καὶ νῦν ὅτι πολιορκοῦνται ἐπὶ λόφου, οἱ δὲ Θρᾶικες πάντες περικεκυκλωμένοι εἶεν αὐτούς. ἐνταῦθα τοὺς μὲν ἀνθρώπους τούτους ἐφύλαττεν ἰσχυρῶς, ὅπως ἡγεμόνες εἶεν ὅποι δέοι· σκοποὺς δὲ καταστήσας συνέλεξε τοὺς στρατιώτας καὶ ἔλεξεν·", "st": "6.3.11"}, {"sp": "N", "t": "«ἄνδρες στρατιῶται, τῶν Ἀρκάδων οἱ μὲν τεθνᾶσιν, οἱ δὲ λοιποὶ ἐπὶ λόφου τινὸς πολιορκοῦνται. νομίζω δ᾽ ἔγωγε, εἰ ἐκεῖνοι ἀπολοῦνται, οὐδ᾽ ἡμῖν εἶναι οὐδεμίαν σωτηρίαν, οὕτω μὲν πολλῶν ὄντων ⟨τῶν⟩ πολεμίων, οὕτω δὲ τεθαρρηκότων.", "st": "6.3.12"}, {"sp": "N", "t": "κράτιστον οὖν ἡμῖν ὡς τάχιστα βοηθεῖν τοῖς ἀνδράσιν, ὅπως εἰ ἔτι εἰσὶ σῶιοι, σὺν ἐκείνοις μαχώμεθα καὶ μὴ μόνοι λειφθέντες μόνοι καὶ κινδυνεύωμεν.", "st": "6.3.13"}, {"sp": "N", "t": "ἡμεῖς γὰρ ἀποδραίημεν ἂν οὐδαμοῖ ἐνθένδε· πολλὴ μὲν γάρ, ἔφη, εἰς Ἡράκλειαν πάλιν ἀπιέναι, πολλὴ δὲ εἰς Χρυσόπολιν διελθεῖν· οἱ δὲ πολέμιοι πλησίον· εἰς Κάλπης δὲ λιμένα, ἔνθα Χειρίσοφον εἰκάζομεν εἶναι, εἰ σέσωσται, ἐλαχίστη ὁδός. ἀλλὰ δὴ ἐκεῖ μὲν οὔτε πλοῖά ἐστιν οἷς ἀποπλευσούμεθα, μένουσι δὲ αὐτοῦ οὐδὲ μιᾶς ἡμέρας ἔστι τὰ ἐπιτήδεια.", "st": "6.3.14"}, {"sp": "N", "t": "τῶν δὲ πολιορκουμένων ἀπολομένων σὺν τοῖς Χειρισόφου μόνοις κάκιόν ἐστι διακινδυνεύειν ἢ τῶνδε σωθέντων πάντας εἰς ταὐτὸν ἐλθόντας κοινῆι τῆς σωτηρίας ἔχεσθαι. ἀλλὰ χρὴ παρασκευασαμένους τὴν γνώμην πορεύεσθαι ὡς νῦν ἢ εὐκλεῶς τελευτῆσαι ἔστιν ἢ κάλλιστον ἔργον ἐργάσασθαι Ἕλληνας τοσούτους σώσαντας.", "st": "6.3.15"}, {"sp": "N", "t": "καὶ ὁ θεὸς ἴσως ἄγει οὕτως, ὃς τοὺς μεγαληγορήσαντας ὡς πλέον φρονοῦντας ταπεινῶσαι βούλεται, ἡμᾶς δὲ τοὺς ἀπὸ τῶν θεῶν ἀρχομένους ἐντιμοτέρους ἐκείνων καταστῆσαι. ἀλλ᾽ ἕπεσθαι χρὴ καὶ προσέχειν τὸν νοῦν, ὡς ἂν τὸ παραγγελλόμενον δύνησθε ποιεῖν.", "st": "6.3.16"}, {"sp": "N", "t": "νῦν μὲν οὖν στρατοπεδευσώμεθα προελθόντες ὅσον ἂν δοκῆι καιρὸς εἶναι εἰς τὸ δειπνοποιεῖσθαι· ἕως δ᾽ ἂν πορευώμεθα, Τιμασίων ἔχων τοὺς ἱππέας προελαυνέτω ἐφορῶν ἡμᾶς καὶ σκοπείτω τὰ ἔμπροσθεν, ὡς μηδὲν ἡμᾶς λάθηι.»", "st": "6.3.17"}, {"sp": "N", "t": "ταῦτ᾽ εἰπὼν ἡγεῖτο. παρέπεμψε δὲ καὶ τῶν γυμνήτων ἀνθρώπους εὐζώνους εἰς τὰ πλάγια καὶ εἰς τὰ ἄκρα, ὅπως εἴ πού τί ποθεν καθορῶιεν, σημαίνοιεν· ἐκέλευε δὲ καίειν ἅπαντα ὅτωι ἐντυγχάνοιεν καυσίμωι.", "st": "6.3.18"}, {"sp": "N", "t": "οἱ δὲ ἱππεῖς σπειρόμενοι ἐφ᾽ ὅσον καλῶς εἶχεν ἔκαιον, καὶ οἱ πελτασταὶ ἐπιπαριόντες κατὰ τὰ ἄκρα ἔκαιον πάντα ὅσα καύσιμα ἑώρων, καὶ ἡ στρατιὰ δέ, εἴ τινι παραλειπομένωι ἐντυγχάνοιεν· ὥστε πᾶσα ἡ χώρα αἴθεσθαι ἐδόκει καὶ τὸ στράτευμα πολὺ εἶναι.", "st": "6.3.19"}, {"sp": "N", "t": "ἐπεὶ δὲ ὥρα ἦν, κατεστρατοπεδεύσαντο ἐπὶ λόφον ἐκβάντες, καὶ τά τε τῶν πολεμίων πυρὰ ἑώρων, ἀπεῖχον δὲ ὡς τετταράκοντα σταδίους, καὶ αὐτοὶ ὡς ἐδύναντο πλεῖστα πυρὰ ἔκαιον.", "st": "6.3.20"}, {"sp": "N", "t": "ἐπεὶ δὲ ἐδείπνησαν τάχιστα, παρηγγέλθη τὰ πυρὰ κατασβεννύναι πάντα. καὶ τὴν μὲν νύκτα φυλακὰς ποιησάμενοι ἐκάθευδον· ἅμα δὲ τῆι ἡμέραι προσευξάμενοι τοῖς θεοῖς, συνταξάμενοι ὡς εἰς μάχην ἐπορεύοντο ἧι ἐδύναντο τάχιστα.", "st": "6.3.21"}, {"sp": "N", "t": "Τιμασίων δὲ καὶ οἱ ἱππεῖς ἔχοντες τοὺς ἡγεμόνας καὶ προελαύνοντες ἐλάνθανον αὑτοὺς ἐπὶ τῶι λόφωι γενόμενοι ἔνθα ἐπολιορκοῦντο οἱ Ἕλληνες. καὶ οὐχ ὁρῶσιν οὔτε φίλιον στράτευμα οὔτε πολέμιον (καὶ ταῦτα ἀπαγγέλλουσι πρὸς τὸν Ξενοφῶντα καὶ τὸ στράτευμα), γράιδια δὲ καὶ γερόντια καὶ πρόβατα ὀλίγα καὶ βοῦς καταλελειμμένους.", "st": "6.3.22"}, {"sp": "N", "t": "καὶ τὸ μὲν πρῶτον θαῦμα ἦν τί εἴη τὸ γεγενημένον, ἔπειτα δὲ καὶ τῶν καταλελειμμένων ἐπυνθάνοντο ὅτι οἱ μὲν Θρᾶικες ἀφ᾽ ἑσπέρας ὤιχοντο ἀπιόντες, καὶ τοὺς Ἕλληνας δ᾽ ἔφασαν οἴχεσθαι· ὅποι δέ, οὐκ εἰδέναι.", "st": "6.3.23"}, {"sp": "N", "t": "ταῦτα ἀκούσαντες οἱ ἀμφὶ Ξενοφῶντα, ἐπεὶ ἠρίστησαν, συσκευασάμενοι ἐπορεύοντο, βουλόμενοι ὡς τάχιστα συμμεῖξαι τοῖς ἄλλοις εἰς Κάλπης λιμένα. καὶ πορευόμενοι ἑώρων τὸν στίβον τῶν Ἀρκάδων καὶ Ἀχαιῶν κατὰ τὴν ἐπὶ Κάλπης ὁδόν. ἐπεὶ δὲ ἀφίκοντο εἰς τὸ αὐτό, ἄσμενοί τε εἶδον ἀλλήλους καὶ ἠσπάζοντο ὥσπερ ἀδελφούς.", "st": "6.3.24"}, {"sp": "N", "t": "καὶ ἐπυνθάνοντο οἱ Ἀρκάδες τῶν περὶ Ξενοφῶντα τί τὰ πυρὰ κατασβέσειαν· ἡμεῖς μὲν γάρ, ἔφασαν, ὤιμεθα ὑμᾶς τὸ μὲν πρῶτον, ἐπειδὴ τὰ πυρὰ οὐχ ἑωρῶμεν, τῆς νυκτὸς ἥξειν ἐπὶ τοὺς πολεμίους· καὶ οἱ πολέμιοι δέ, ὥς γε ἡμῖν ἐδόκουν, τοῦτο δείσαντες ἀπῆλθον· σχεδὸν γὰρ ἀμφὶ τοῦτον τὸν χρόνον ἀπῆισαν.", "st": "6.3.25"}, {"sp": "N", "t": "ἐπεὶ δὲ οὐκ ἀφίκεσθε, ὁ δὲ χρόνος ἐξῆκεν, ὠιόμεθα ὑμᾶς πυθομένους τὰ παρ᾽ ἡμῖν φοβηθέντας οἴχεσθαι ἀποδράντας ἐπὶ θάλατταν· καὶ ἐδόκει ἡμῖν μὴ ἀπολείπεσθαι ὑμῶν. οὕτως οὖν καὶ ἡμεῖς δεῦρο ἐπορεύθημεν.", "st": "6.3.26"}, {"sp": "N", "t": "ταύτην μὲν οὖν τὴν ἡμέραν αὐτοῦ ηὐλίζοντο ἐπὶ τοῦ αἰγιαλοῦ πρὸς τῶι λιμένι. τὸ δὲ χωρίον τοῦτο ὃ καλεῖται Κάλπης λιμὴν ἔστι μὲν ἐν τῆι Θράικηι τῆι ἐν τῆι Ἀσίαι· ἀρξαμένη δὲ ἡ Θράικη αὕτη ἐστὶν ἀπὸ τοῦ στόματος τοῦ Πόντου μέχρι Ἡρακλείας ἐπὶ δεξιὰ εἰς τὸν Πόντον εἰσπλέοντι.", "st": "6.4.1"}, {"sp": "N", "t": "καὶ τριήρει μέν ἐστιν εἰς Ἡράκλειαν ἐκ Βυζαντίου κώπαις ἡμέρας μακρᾶς πλοῦς· ἐν δὲ τῶι μέσωι ἄλλη μὲν πόλις οὐδεμία οὔτε φιλία οὔτε Ἑλληνίς, ἀλλὰ Θρᾶικες Βιθυνοί· καὶ οὓς ἂν λάβωσι τῶν Ἑλλήνων ἐκπίπτοντας ἢ ἄλλως πως δεινὰ ὑβρίζειν λέγονται τοὺς Ἕλληνας.", "st": "6.4.2"}, {"sp": "N", "t": "ὁ δὲ Κάλπης λιμὴν ἐν μέσωι μὲν κεῖται ἑκατέρωθεν πλεόντων ἐξ Ἡρακλείας καὶ Βυζαντίου, ἔστι δ᾽ ἐν τῆι θαλάττηι προκείμενον χωρίον, τὸ μὲν εἰς τὴν θάλατταν καθῆκον αὐτοῦ πέτρα ἀπορρώξ, ὕψος ὅπηι ἐλάχιστον οὐ μεῖον εἴκοσιν ὀργυιῶν, ὁ δὲ αὐχὴν ὁ εἰς τὴν γῆν ἀνήκων τοῦ χωρίου μάλιστα τεττάρων πλέθρων τὸ εὖρος· τὸ δ᾽ ἐντὸς τοῦ αὐχένος χωρίον ἱκανὸν μυρίοις ἀνθρώποις οἰκῆσαι.", "st": "6.4.3"}, {"sp": "N", "t": "λιμὴν δ᾽ ὑπ᾽ αὐτῆι τῆι πέτραι τὸ πρὸς ἑσπέραν αἰγιαλὸν ἔχων. κρήνη δὲ ἡδέος ὕδατος καὶ ἄφθονος ῥέουσα ἐπ᾽ αὐτῆι τῆι θαλάττηι ὑπὸ τῆι ἐπικρατείαι τοῦ χωρίου. ξύλα δὲ πολλὰ μὲν καὶ ἄλλα, πάνυ δὲ πολλὰ καὶ καλὰ ναυπηγήσιμα ἐπ᾽ αὐτῆι τῆι θαλάττηι.", "st": "6.4.4"}, {"sp": "N", "t": "τὸ δὲ ὄρος εἰς μεσόγειαν μὲν ἀνήκει ὅσον ἐπὶ εἴκοσι σταδίους, καὶ τοῦτο γεῶδες καὶ ἄλιθον· τὸ δὲ παρὰ θάλατταν πλέον ἢ ἐπὶ εἴκοσι σταδίους δασὺ πολλοῖς καὶ παντοδαποῖς καὶ μεγάλοις ξύλοις.", "st": "6.4.5"}, {"sp": "N", "t": "ἡ δὲ ἄλλη χώρα καλὴ καὶ πολλή, καὶ κῶμαι ἐν αὐτῆι εἰσι πολλαὶ καὶ οἰκούμεναι· φέρει γὰρ ἡ γῆ καὶ κριθὰς καὶ πυροὺς καὶ ὄσπρια πάντα καὶ μελίνας καὶ σήσαμα καὶ σῦκα ἀρκοῦντα καὶ ἀμπέλους πολλὰς καὶ ἡδυοίνους καὶ τἆλλα πάντα πλὴν ἐλαῶν.", "st": "6.4.6"}, {"sp": "N", "t": "ἡ μὲν χώρα ἦν τοιαύτη. ἐσκήνουν δ᾽ ἐν τῶι αἰγιαλῶι πρὸς τῆι θαλάττηι· εἰς δὲ τὸ πόλισμα ἂν γενόμενον οὐκ ἐβούλοντο στρατοπεδεύεσθαι, ἀλλὰ ἐδόκει καὶ τὸ ἐλθεῖν ἐνταῦθα ἐξ ἐπιβουλῆς εἶναι, βουλομένων τινῶν κατοικίσαι πόλιν.", "st": "6.4.7"}, {"sp": "N", "t": "τῶν γὰρ στρατιωτῶν οἱ πλεῖστοι ἦσαν οὐ σπάνει βίου ἐκπεπλευκότες ἐπὶ ταύτην τὴν μισθοφοράν, ἀλλὰ τὴν Κύρου ἀρετὴν ἀκούοντες, οἱ μὲν καὶ ἄνδρας ἄγοντες, οἱ δὲ καὶ προσανηλωκότες χρήματα, καὶ τούτων ἕτεροι ἀποδεδρακότες πατέρας καὶ μητέρας, οἱ δὲ καὶ τέκνα καταλιπόντες ὡς χρήματ᾽ αὐτοῖς κτησάμενοι ἥξοντες πάλιν, ἀκούοντες καὶ τοὺς ἄλλους τοὺς παρὰ Κύρωι πολλὰ καὶ ἀγαθὰ πράττειν. τοιοῦτοι ὄντες ἐπόθουν εἰς τὴν Ἑλλάδα σώιζεσθαι.", "st": "6.4.8"}, {"sp": "N", "t": "ἐπειδὴ δὲ ὑστέρα ἡμέρα ἐγένετο τῆς εἰς ταὐτὸν συνόδου, ἐπ᾽ ἐξόδωι ἐθύετο Ξενοφῶν· ἀνάγκη γὰρ ἦν ἐπὶ τὰ ἐπιτήδεια ἐξάγειν· ἐπενόει δὲ καὶ τοὺς νεκροὺς θάπτειν. ἐπεὶ δὲ τὰ ἱερὰ καλὰ ἐγένετο, εἵποντο καὶ οἱ Ἀρκάδες, καὶ τοὺς μὲν νεκροὺς τοὺς πλείστους ἔνθαπερ ἔπεσον ἑκάστους ἔθαψαν· ἤδη γὰρ ἦσαν πεμπταῖοι καὶ οὐχ οἷόν τε ἀναιρεῖν ἔτι ἦν· ἐνίους δὲ τοὺς ἐκ τῶν ὁδῶν συνενεγκόντες ἔθαψαν ἐκ τῶν ὑπαρχόντων ὡς ἐδύναντο κάλλιστα· οὓς δὲ μὴ ηὕρισκον, κενοτάφιον αὐτοῖς ἐποίησαν μέγα, καὶ στεφάνους ἐπέθεσαν.", "st": "6.4.9"}, {"sp": "N", "t": "ταῦτα δὲ ποιήσαντες ἀνεχώρησαν ἐπὶ τὸ στρατόπεδον. καὶ τότε μὲν δειπνήσαντες ἐκοιμήθησαν. τῆι δὲ ὑστεραίαι συνῆλθον οἱ στρατιῶται πάντες· συνῆγε δὲ μάλιστα Ἀγασίας τε ὁ Στυμφάλιος λοχαγὸς καὶ Ἱερώνυμος Ἠλεῖος λοχαγὸς καὶ ἄλλοι οἱ πρεσβύτατοι τῶν Ἀρκάδων.", "st": "6.4.10"}, {"sp": "N", "t": "καὶ δόγμα ἐποιήσαντο, ἐάν τις τοῦ λοιποῦ μνησθῆι δίχα τὸ στράτευμα ποιεῖν, θανάτωι αὐτὸν ζημιοῦσθαι, καὶ κατὰ χώραν ἀπιέναι ἧιπερ πρόσθεν εἶχε τὸ στράτευμα καὶ ἄρχειν τοὺς πρόσθεν στρατηγούς. καὶ Χειρίσοφος μὲν ἤδη ἐτετελευτήκει φάρμακον πιὼν πυρέττων· τὰ δ᾽ ἐκείνου Νέων Ἀσιναῖος παρέλαβε.", "st": "6.4.11"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα ἀναστὰς εἶπε Ξενοφῶν· «ὦ ἄνδρες στρατιῶται, τὴν μὲν πορείαν, ὡς ἔοικε, [δῆλον ὅτι] πεζῆι ποιητέον· οὐ γὰρ ἔστι πλοῖα· ἀνάγκη δὲ πορεύεσθαι ἤδη· οὐ γὰρ ἔστι μένουσι τὰ ἐπιτήδεια. ἡμεῖς οὖν, ἔφη, θυσόμεθα· ὑμᾶς δὲ δεῖ παρασκευάζεσθαι ὡς μαχουμένους εἴ ποτε καὶ ἄλλοτε· οἱ γὰρ πολέμιοι ἀνατεθαρρήκασιν.»", "st": "6.4.12"}, {"sp": "N", "t": "ἐκ τούτου ἐθύοντο οἱ στρατηγοί, μάντις δὲ παρῆν Ἀρηξίων Ἀρκάς· ὁ δὲ Σιλανὸς ὁ Ἀμπρακιώτης ἤδη ἀπεδεδράκει πλοῖον μισθωσάμενος ἐξ Ἡρακλείας. θυομένοις δὲ ἐπὶ τῆι ἀφόδωι οὐκ ἐγίγνετο τὰ ἱερά.", "st": "6.4.13"}, {"sp": "N", "t": "ταύτην μὲν οὖν τὴν ἡμέραν ἐπαύσαντο. καί τινες ἐτόλμων λέγειν ὡς ὁ Ξενοφῶν βουλόμενος τὸ χωρίον οἰκίσαι πέπεικε τὸν μάντιν λέγειν ὡς τὰ ἱερὰ οὐ γίγνεται ἐπὶ ἀφόδωι.", "st": "6.4.14"}, {"sp": "N", "t": "ἐντεῦθεν κηρύξας τῆι αὔριον παρεῖναι ἐπὶ τὴν θυσίαν τὸν βουλόμενον, καὶ μάντις εἴ τις εἴη, παραγγείλας παρεῖναι ὡς συνθεασόμενον τὰ ἱερά, ἔθυε· καὶ ἐνταῦθα παρῆσαν πολλοί.", "st": "6.4.15"}, {"sp": "N", "t": "θυομένωι δὲ πάλιν εἰς τρὶς ἐπὶ τῆι ἀφόδωι οὐκ ἐγίγνετο τὰ ἱερά. ἐκ τούτου χαλεπῶς εἶχον οἱ στρατιῶται· καὶ γὰρ τὰ ἐπιτήδεια ἐπέλιπεν ἃ ἔχοντες ἦλθον, καὶ ἀγορὰ οὐδεμία πω παρῆν.", "st": "6.4.16"}, {"sp": "N", "t": "ἐκ τούτου ξυνελθόντων εἶπε πάλιν Ξενοφῶν· «ὦ ἄνδρες, ἐπὶ μὲν τῆι πορείαι, ὡς ὁρᾶτε, τὰ ἱερὰ οὔπω γίγνεται· τῶν δ᾽ ἐπιτηδείων ὁρῶ ὑμᾶς δεομένους· ἀνάγκη οὖν μοι δοκεῖ εἶναι θύεσθαι περὶ αὐτοῦ τούτου.»", "st": "6.4.17"}, {"sp": "N", "t": "ἀναστάς τις εἶπε· «καὶ εἰκότως ἄρα ἡμῖν οὐ γίγνεται τὰ ἱερά· ὡς γὰρ ἐγὼ ἀπὸ τοῦ αὐτομάτου χθὲς ἥκοντος πλοίου ἤκουσά τινος [ὅτι] Κλέανδρος ⟨ὁ⟩ ἐκ Βυζαντίου ἁρμοστὴς μέλλει ἥξειν πλοῖα καὶ τριήρεις ἔχων.»", "st": "6.4.18"}, {"sp": "N", "t": "ἐκ τούτου δὲ ἀναμένειν μὲν πᾶσιν ἐδόκει· ἐπὶ δὲ τὰ ἐπιτήδεια ἀνάγκη ἦν ἐξιέναι. καὶ ἐπὶ τούτωι πάλιν ἐθύετο εἰς τρίς, καὶ οὐκ ἐγίγνετο τὰ ἱερά. καὶ ἤδη καὶ ἐπὶ σκηνὴν ἰόντες τὴν Ξενοφῶντος ἔλεγον ὅτι οὐκ ἔχοιεν τὰ ἐπιτήδεια. ὁ δ᾽ οὐκ ἂν ἔφη ἐξαγαγεῖν μὴ γιγνομένων τῶν ἱερῶν.", "st": "6.4.19"}, {"sp": "N", "t": "καὶ πάλιν τῆι ὑστεραίαι ἐθύετο, καὶ σχεδόν τι πᾶσα ἡ στρατιὰ διὰ τὸ μέλειν ἅπασιν ἐκυκλοῦντο περὶ τὰ ἱερά· τὰ δὲ θύματα ἐπελελοίπει. οἱ δὲ στρατηγοὶ ἐξῆγον μὲν οὔ, συνεκάλεσαν δέ.", "st": "6.4.20"}, {"sp": "N", "t": "εἶπεν οὖν Ξενοφῶν· «ἴσως οἱ πολέμιοι συνειλεγμένοι εἰσὶ καὶ ἀνάγκη μάχεσθαι· εἰ οὖν καταλιπόντες ⟨τὰ σκεύη⟩ ἐν τῶι ἐρυμνῶι χωρίωι ὡς εἰς μάχην παρεσκευασμένοι ἴοιμεν, ἴσως ἂν τὰ ἱερὰ προχωροίη ἡμῖν.»", "st": "6.4.21"}, {"sp": "N", "t": "ἀκούσαντες δ᾽ οἱ στρατιῶται ἀνέκραγον, ὡς οὐδὲν δέον εἰς τὸ χωρίον ἄγειν, ἀλλὰ θύεσθαι ὡς τάχιστα. καὶ πρόβατα μὲν οὐκέτι ἦν, βοῦς δὲ ὑπὸ ἁμάξης πριάμενοι ἐθύοντο· καὶ Ξενοφῶν Κλεάνορος ἐδεήθη τοῦ Ἀρκάδος προθυμεῖσθαι, εἴ τι ἐν τούτωι εἴη. ἀλλ᾽ οὐδ᾽ ὣς ἐγένοντο.", "st": "6.4.22"}, {"sp": "N", "t": "Νέων δὲ ἦν μὲν στρατηγὸς κατὰ τὸ Χειρισόφου μέρος, ἐπεὶ δὲ ἑώρα τοὺς ἀνθρώπους ὡς εἶχον δεινῶς τῆι ἐνδείαι, βουλόμενος αὐτοῖς χαρίζεσθαι, εὑρών τινα ἄνθρωπον Ἡρακλεώτην, ὃς ἔφη κώμας ἐγγὺς εἰδέναι ὅθεν εἴη λαβεῖν τὰ ἐπιτήδεια, ἐκήρυξε τὸν βουλόμενον ἰέναι ἐπὶ τὰ ἐπιτήδεια, ὡς ἡγεμόνος ἐσομένου. ἐξέρχονται δὴ σὺν δορατίοις καὶ ἀσκοῖς καὶ θυλάκοις καὶ ἄλλοις ἀγγείοις εἰς δισχιλίους ἀνθρώπους.", "st": "6.4.23"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἦσαν ἐν ταῖς κώμαις καὶ διεσπείροντο ὡς ἐπὶ τὸ λαμβάνειν, ἐπιπίπτουσιν αὐτοῖς οἱ Φαρναβάζου ἱππεῖς πρῶτοι· βεβοηθηκότες γὰρ ἦσαν τοῖς Βιθυνοῖς, βουλόμενοι σὺν τοῖς Βιθυνοῖς, εἰ δύναιντο, ἀποκωλῦσαι τοὺς Ἕλληνας μὴ ἐλθεῖν εἰς τὴν Φρυγίαν· οὗτοι οἱ ἱππεῖς ἀποκτείνουσι τῶν ἀνδρῶν οὐ μεῖον πεντακοσίους· οἱ δὲ λοιποὶ ἐπὶ τὸ ὄρος ἀνέφυγον.", "st": "6.4.24"}, {"sp": "N", "t": "ἐκ τούτου ἀπαγγέλλει τις ταῦτα τῶν ἀποφευγόντων εἰς τὸ στρατόπεδον. καὶ ὁ Ξενοφῶν, ἐπεὶ οὐκ ἐγεγένητο τὰ ἱερὰ ταύτηι τῆι ἡμέραι, λαβὼν βοῦν ὑπὸ ἁμάξης (οὐ γὰρ ἦν ἄλλα ἱερεῖα), σφαγιασάμενος ἐβοήθει καὶ οἱ ἄλλοι οἱ μέχρι τριάκοντα ἐτῶν ἅπαντες.", "st": "6.4.25"}, {"sp": "N", "t": "καὶ ἀναλαβόντες τοὺς λοιποὺς ἄνδρας εἰς τὸ στρατόπεδον ἀφικνοῦνται. καὶ ἤδη μὲν ἀμφὶ ἡλίου δυσμὰς ἦν καὶ οἱ Ἕλληνες μάλ᾽ ἀθύμως ἔχοντες ἐδειπνοποιοῦντο, καὶ ἐξαπίνης διὰ τῶν λασίων τῶν Βιθυνῶν τινες ἐπιγενόμενοι τοῖς προφύλαξι τοὺς μὲν κατέκαινον τοὺς δὲ ἐδίωξαν μέχρι εἰς τὸ στρατόπεδον.", "st": "6.4.26"}, {"sp": "N", "t": "καὶ κραυγῆς γενομένης εἰς τὰ ὅπλα πάντες ἔδραμον οἱ Ἕλληνες· καὶ διώκειν μὲν καὶ κινεῖν τὸ στρατόπεδον νυκτὸς οὐκ ἀσφαλὲς ἐδόκει εἶναι· δασέα γὰρ ἦν τὰ χωρία· ἐν δὲ τοῖς ὅπλοις ἐνυκτέρευον φυλαττόμενοι ἱκανοῖς φύλαξι.", "st": "6.4.27"}, {"sp": "N", "t": "τὴν μὲν νύκτα οὕτω διήγαγον· ἅμα δὲ τῆι ἡμέραι οἱ στρατηγοὶ εἰς τὸ ἐρυμνὸν χωρίον ἡγοῦντο· οἱ δὲ εἵποντο ἀναλαβόντες τὰ ὅπλα καὶ τὰ σκεύη. πρὶν δὲ ἀρίστου ὥραν εἶναι ἀπετάφρευον ἧι ἡ εἴσοδος ἦν εἰς τὸ χωρίον, καὶ ἀπεσταύρωσαν ἅπαν, καταλιπόντες τρεῖς πύλας. καὶ πλοῖον ἐξ Ἡρακλείας ἧκεν ἄλφιτα ἄγον καὶ ἱερεῖα καὶ οἶνον.", "st": "6.5.1"}, {"sp": "N", "t": "πρὼι δ᾽ ἀναστὰς Ξενοφῶν ἐθύετο ἐπ᾽ ἐξόδωι, καὶ γίγνεται τὰ ἱερὰ ἐπὶ τοῦ πρώτου ἱερείου. καὶ ἤδη τέλος ἐχόντων τῶν ἱερῶν ὁρᾶι αἰετὸν αἴσιον ὁ μάντις Ἀρηξίων Παρράσιος, καὶ ἡγεῖσθαι κελεύει τὸν Ξενοφῶντα.", "st": "6.5.2"}, {"sp": "N", "t": "καὶ διαβάντες τὴν τάφρον τὰ ὅπλα τίθενται, καὶ ἐκήρυξαν ἀριστήσαντας ἐξιέναι τοὺς στρατιώτας σὺν τοῖς ὅπλοις, τὸν δὲ ὄχλον καὶ τὰ ἀνδράποδα αὐτοῦ καταλιπεῖν.", "st": "6.5.3"}, {"sp": "N", "t": "οἱ μὲν δὴ ἄλλοι πάντες ἐξῆισαν, Νέων δὲ οὔ· ἐδόκει γὰρ κάλλιστον εἶναι τοῦτον φύλακα καταλιπεῖν τῶν ἐπὶ στρατοπέδου. ἐπεὶ δ᾽ οἱ λοχαγοὶ καὶ οἱ στρατιῶται ἀπέλειπον αὐτόν, αἰσχυνόμενοι μὴ ἐφέπεσθαι τῶν ἄλλων ἐξιόντων, κατέλιπον αὐτοῦ τοὺς ὑπὲρ πέντε καὶ τετταράκοντα ἔτη. καὶ οὗτοι μὲν ἔμενον, οἱ δ᾽ ἄλλοι ἐπορεύοντο.", "st": "6.5.4"}, {"sp": "N", "t": "πρὶν δὲ πεντεκαίδεκα στάδια διεληλυθέναι ἐνέτυχον ἤδη νεκροῖς· καὶ τὴν οὐρὰν τοῦ κέρατος ποιησάμενοι κατὰ τοὺς πρώτους φανέντας νεκροὺς ἔθαπτον πάντας ὁπόσους ἐπελάμβανε τὸ κέρας.", "st": "6.5.5"}, {"sp": "N", "t": "ἐπεὶ δὲ τοὺς πρώτους ἔθαψαν, προαγαγόντες καὶ τὴν οὐρὰν αὖθις ποιησάμενοι κατὰ τοὺς πρώτους τῶν ἀτάφων ἔθαπτον τὸν αὐτὸν τρόπον ὁπόσους ἐπελάμβανεν ἡ στρατιά. ἐπεὶ δὲ εἰς τὴν ὁδὸν ἧκον τὴν ἐκ τῶν κωμῶν, ἔνθα ἔκειντο ἁθρόοι, συνενεγκόντες αὐτοὺς ἔθαψαν.", "st": "6.5.6"}, {"sp": "N", "t": "ἤδη δὲ πέρα μεσούσης τῆς ἡμέρας προάγοντες τὸ στράτευμα ἔξω τῶν κωμῶν ἐλάμβανον τὰ ἐπιτήδεια ὅ τι τις ὁρώιη ἐντὸς τῆς φάλαγγος, καὶ ἐξαίφνης ὁρῶσι τοὺς πολεμίους ὑπερβάλλοντας κατὰ λόφους τινὰς ἐκ τοῦ ἐναντίου, τεταγμένους ἐπὶ φάλαγγος ἱππέας τε πολλοὺς καὶ πεζούς· καὶ γὰρ Σπιθριδάτης καὶ ῾Ραθίνης ἧκον παρὰ Φαρναβάζου ἔχοντες τὴν δύναμιν.", "st": "6.5.7"}, {"sp": "N", "t": "ἐπεὶ δὲ κατεῖδον τοὺς Ἕλληνας οἱ πολέμιοι, ἔστησαν ἀπέχοντες αὐτῶν ὅσον πεντεκαίδεκα σταδίους. ἐκ τούτου εὐθὺς ὁ Ἀρηξίων ὁ μάντις τῶν Ἑλλήνων σφαγιάζεται, καὶ ἐγένετο ἐπὶ τοῦ πρώτου καλὰ τὰ σφάγια.", "st": "6.5.8"}, {"sp": "N", "t": "ἔνθα δὴ Ξενοφῶν λέγει· «δοκεῖ μοι, ὦ ἄνδρες στρατηγοί, ἐπιτάξασθαι τῆι φάλαγγι λόχους φύλακας ἵν᾽ ἄν που δέηι ὦσιν οἱ ἐπιβοηθήσοντες τῆι φάλαγγι καὶ οἱ πολέμιοι τεταραγμένοι ἐμπίπτωσιν εἰς τεταγμένους καὶ ἀκεραίους.» συνεδόκει ταῦτα πᾶσιν.", "st": "6.5.9"}, {"sp": "N", "t": "«ὑμεῖς μὲν τοίνυν, ἔφη, προηγεῖσθε τὴν πρὸς τοὺς ἐναντίους, ὡς μὴ ἑστήκωμεν, ἐπεὶ ὤφθημεν καὶ εἴδομεν τοὺς πολεμίους· ἐγὼ δὲ ἥξω τοὺς τελευταίους λόχους καταχωρίσας ἧιπερ ὑμῖν δοκεῖ.»", "st": "6.5.10"}, {"sp": "N", "t": "ἐκ τούτου οἱ μὲν ἥσυχοι προῆγον, ὁ δὲ τρεῖς ἀφελὼν τὰς τελευταίας τάξεις ἀνὰ διακοσίους ἄνδρας τὴν μὲν ἐπὶ τὸ δεξιὸν ἐπέτρεψεν ἐφέπεσθαι ἀπολιπόντας ὡς πλέθρον· Σαμόλας Ἀχαιὸς ταύτης ἦρχε τῆς τάξεως· τὴν δ᾽ ἐπὶ τῶι μέσωι ἐχώρισεν ἕπεσθαι· Πυρρίας Ἀρκὰς ταύτης ἦρχε· τὴν δὲ μίαν ἐπὶ τῶι εὐωνύμωι· Φρασίας Ἀθηναῖος ταύτηι ἐφειστήκει.", "st": "6.5.11"}, {"sp": "N", "t": "προϊόντες δέ, ἐπεὶ ἐγένοντο οἱ ἡγούμενοι ἐπὶ νάπει μεγάλωι καὶ δυσπόρωι, ἔστησαν ἀγνοοῦντες εἰ διαβατέον εἴη τὸ νάπος. καὶ παρεγγυῶσι στρατηγοὺς καὶ λοχαγοὺς παριέναι ἐπὶ τὸ ἡγούμενον.", "st": "6.5.12"}, {"sp": "N", "t": "καὶ ὁ Ξενοφῶν θαυμάσας ὅ τι τὸ ἴσχον εἴη τὴν πορείαν καὶ ταχὺ ἀκούων τὴν παρεγγύην, ἐλαύνει ἧι τάχιστα. ἐπεὶ δὲ συνῆλθον, λέγει Σοφαίνετος πρεσβύτατος ὢν τῶν στρατηγῶν ὅτι βουλῆς οὐκ ἄξιον εἴη εἰ διαβατέον ἐστὶ τοιοῦτον νάπος.", "st": "6.5.13"}, {"sp": "N", "t": "καὶ ὁ Ξενοφῶν σπουδῆι ὑπολαβὼν ἔλεξεν· ἀλλ᾽ ἴστε μέν με, ὦ ἄνδρες, οὐδένα πω κίνδυνον προξενήσαντα ὑμῖν ἐθελούσιον· οὐ γὰρ δόξης ὁρῶ δεομένους ὑμᾶς εἰς ἀνδρειότητα, ἀλλὰ σωτηρίας.", "st": "6.5.14"}, {"sp": "N", "t": "νῦν δὲ οὕτως ἔχει· ἀμαχεὶ μὲν ἐνθένδε οὐκ ἔστιν ἀπελθεῖν· ἢν γὰρ μὴ ἡμεῖς ἴωμεν ἐπὶ τοὺς πολεμίους, οὗτοι ἡμῖν ὁπόταν ἀπίωμεν ἕψονται καὶ ἐπιπεσοῦνται.", "st": "6.5.15"}, {"sp": "N", "t": "ὁρᾶτε δὴ πότερον κρεῖττον ἰέναι ἐπὶ τοὺς ἄνδρας προβαλλομένους τὰ ὅπλα ἢ μεταβαλλομένους ὄπισθεν ἡμῶν ἐπιόντας τοὺς πολεμίους θεᾶσθαι.", "st": "6.5.16"}, {"sp": "N", "t": "ἴστε μέντοι ὅτι τὸ μὲν ἀπιέναι ἀπὸ πολεμίων οὐδενὶ καλῶι ἔοικε, τὸ δὲ ἐφέπεσθαι καὶ τοῖς κακίοσι θάρρος ἐμποιεῖ. ἐγὼ γοῦν ἥδιον ἂν σὺν ἡμίσεσιν ἐπιοίην ἢ σὺν διπλασίοις ἀποχωροίην. καὶ τούτους οἶδ᾽ ὅτι ἐπιόντων μὲν ἡμῶν οὐδ᾽ ὑμεῖς ἐλπίζετε δέξεσθαι ἡμᾶς, ἀπιόντων δὲ πάντες ἐπιστάμεθα ὅτι τολμήσουσιν ἐφέπεσθαι.", "st": "6.5.17"}, {"sp": "N", "t": "τὸ δὲ διαβάντας ὄπισθεν νάπος χαλεπὸν ποιήσασθαι μέλλοντας μάχεσθαι ἆρ᾽ οὐχὶ καὶ ἁρπάσαι ἄξιον; τοῖς μὲν γὰρ πολεμίοις ἐγὼ βουλοίμην ἂν εὔπορα πάντα φαίνεσθαι ὥστε ἀποχωρεῖν· ἡμᾶς δὲ καὶ ἀπὸ τοῦ χωρίου δεῖ διδάσκεσθαι ὅτι οὐκ ἔστι μὴ νικῶσι σωτηρία.", "st": "6.5.18"}, {"sp": "N", "t": "θαυμάζω δ᾽ ἔγωγε καὶ τὸ νάπος τοῦτο εἴ τις μᾶλλον φοβερὸν νομίζει εἶναι τῶν ἄλλων ὧν διαπεπορεύμεθα χωρίων. πῶς γὰρ διαβατὸν τὸ πεδίον, εἰ μὴ νικήσομεν τοὺς ἱππέας; πῶς δὲ ἃ διεληλύθαμεν ὄρη, ἢν πελτασταὶ τοσοίδε ἐφέπωνται;", "st": "6.5.19"}, {"sp": "N", "t": "ἢν δὲ δὴ καὶ σωθῶμεν ἐπὶ θάλατταν, πόσον τι νάπος ὁ Πόντος; ἔνθα οὔτε πλοῖα ἔστι τὰ ἀπάξοντα οὔτε σῖτος ὧι θρεψόμεθα μένοντες, δεήσει δέ, ἢν θᾶττον ἐκεῖ γενώμεθα, θᾶττον πάλιν ἐξιέναι ἐπὶ τὰ ἐπιτήδεια.", "st": "6.5.20"}, {"sp": "N", "t": "οὐκοῦν νῦν κρεῖττον ἠριστηκότας μάχεσθαι ἢ αὔριον ἀναρίστους. ἄνδρες, τά τε ἱερὰ ἡμῖν καλὰ οἵ τε οἰωνοὶ αἴσιοι τά τε σφάγια κάλλιστα· ἴωμεν ἐπὶ τοὺς ἄνδρας. οὐ δεῖ ἔτι τούτους, ἐπεὶ ἡμᾶς πάντως εἶδον, ἡδέως δειπνῆσαι οὐδ᾽ ὅπου ἂν θέλωσι σκηνῆσαι.", "st": "6.5.21"}, {"sp": "N", "t": "ἐντεῦθεν οἱ λοχαγοὶ ἡγεῖσθαι ἐκέλευον, καὶ οὐδεὶς ἀντέλεγε. καὶ ὃς ἡγεῖτο, παραγγείλας διαβαίνειν ἧι ἕκαστος ἐτύγχανε τοῦ νάπους ὤν· θᾶττον γὰρ ἁθρόον ἐδόκει ἂν οὕτω πέραν γενέσθαι τὸ στράτευμα ἢ εἰ κατὰ τὴν γέφυραν ἣ ἐπὶ τῶι νάπει ἦν ἐξεμηρύοντο.", "st": "6.5.22"}, {"sp": "N", "t": "ἐπεὶ δὲ διέβησαν, παριὼν παρὰ τὴν φάλαγγα ἔλεγεν· «ἄνδρες, ἀναμιμνήισκεσθε ὅσας δὴ μάχας σὺν τοῖς θεοῖς ὁμόσε ἰόντες νενικήκατε καὶ οἷα πάσχουσιν οἱ πολεμίους φεύγοντες, καὶ τοῦτο ἐννοήσατε ὅτι ἐπὶ ταῖς θύραις τῆς Ἑλλάδος ἐσμέν.", "st": "6.5.23"}, {"sp": "N", "t": "ἀλλ᾽ ἕπεσθε ἡγεμόνι τῶι Ἡρακλεῖ καὶ ἀλλήλους παρακαλεῖτε ὀνομαστί. ἡδύ τοι ἀνδρεῖόν τι καὶ καλὸν νῦν εἰπόντα καὶ ποιήσαντα μνήμην ἐν οἷς ἐθέλει παρέχειν ἑαυτοῦ.»", "st": "6.5.24"}, {"sp": "N", "t": "ταῦτα παρελαύνων ἔλεγε καὶ ἅμα ὑφηγεῖτο ἐπὶ φάλαγγος, καὶ τοὺς πελταστὰς ἑκατέρωθεν ποιησάμενοι ἐπορεύοντο ἐπὶ τοὺς πολεμίους. παρήγγελτο δὲ τὰ μὲν δόρατα ἐπὶ τὸν δεξιὸν ὦμον ἔχειν, ἕως σημαίνοι τῆι σάλπιγγι· ἔπειτα δὲ εἰς προσβολὴν καθέντας ἕπεσθαι βάδην καὶ μηδένα δρόμωι διώκειν. ἐκ τούτου σύνθημα παρήιει Ζεὺς σωτήρ, Ἡρακλῆς ἡγεμών. οἱ δὲ πολέμιοι ὑπέμενον, νομίζοντες καλὸν ἔχειν τὸ χωρίον.", "st": "6.5.25"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἐπλησίαζον, ἀλαλάξαντες οἱ Ἕλληνες πελτασταὶ ἔθεον ἐπὶ τοὺς πολεμίους πρίν τινα κελεύειν· οἱ δὲ πολέμιοι ἀντίοι ὥρμησαν, οἵ θ᾽ ἱππεῖς καὶ τὸ στῖφος τῶν Βιθυνῶν· καὶ τρέπονται τοὺς πελταστάς.", "st": "6.5.26"}, {"sp": "N", "t": "ἀλλ᾽ ἐπεὶ ὑπηντίαζεν ἡ φάλαγξ τῶν ὁπλιτῶν ταχὺ πορευομένη καὶ ἅμα ἡ σάλπιγξ ἐφθέγξατο καὶ ἐπαιάνιζον καὶ μετὰ ταῦτα ἠλάλαζον καὶ ἅμα τὰ δόρατα καθίεσαν, ἐνταῦθα οὐκέτι ἐδέξαντο οἱ πολέμιοι, ἀλλὰ ἔφευγον.", "st": "6.5.27"}, {"sp": "N", "t": "καὶ Τιμασίων μὲν ἔχων τοὺς ἱππέας ἐφείπετο, καὶ ἀπεκτίννυσαν ὅσουσπερ ἐδύναντο ὡς ὀλίγοι ὄντες. τῶν δὲ πολεμίων τὸ μὲν εὐώνυμον εὐθὺς διεσπάρη, καθ᾽ ὃ οἱ Ἕλληνες ἱππεῖς ἦσαν, τὸ δὲ δεξιὸν ἅτε οὐ σφόδρα διωκόμενον ἐπὶ λόφου συνέστη.", "st": "6.5.28"}, {"sp": "N", "t": "ἐπεὶ δὲ εἶδον οἱ Ἕλληνες ὑπομένοντας αὐτούς, ἐδόκει ῥᾶιστόν τε καὶ ἀκινδυνότατον εἶναι ἰέναι ἤδη ἐπ᾽ αὐτούς. παιανίσαντες οὖν εὐθὺς ἐπέκειντο· οἱ δ᾽ οὐχ ὑπέμειναν. καὶ ἐνταῦθα οἱ πελτασταὶ ἐδίωκον μέχρι τὸ δεξιὸν διεσπάρη· ἀπέθανον δὲ ὀλίγοι· τὸ γὰρ ἱππικὸν φόβον παρεῖχε τὸ τῶν πολεμίων πολὺ ὄν.", "st": "6.5.29"}, {"sp": "N", "t": "ἐπεὶ δὲ εἶδον οἱ Ἕλληνες τό τε Φαρναβάζου ἱππικὸν ἔτι συνεστηκὸς καὶ τοὺς Βιθυνοὺς ἱππέας πρὸς τοῦτο συναθροιζομένους καὶ ἀπὸ λόφου τινὸς καταθεωμένους τὰ γιγνόμενα, ἀπειρήκεσαν μέν, ὅμως δὲ ἐδόκει καὶ ἐπὶ τούτους ἰτέον εἶναι οὕτως ὅπως δύναιντο, ὡς μὴ τεθαρρηκότες ἀναπαύσαιντο.", "st": "6.5.30"}, {"sp": "N", "t": "συνταξάμενοι δὴ πορεύονται. ἐντεῦθεν οἱ πολέμιοι ἱππεῖς φεύγουσι κατὰ τοῦ πρανοῦς ὁμοίως ὥσπερ ὑπὸ ἱππέων διωκόμενοι· νάπος γὰρ αὐτοὺς ὑπεδέχετο, ὃ οὐκ ἤιδεσαν οἱ Ἕλληνες, ἀλλὰ προαπετράποντο διώκοντες· ὀψὲ γὰρ ἦν.", "st": "6.5.31"}, {"sp": "N", "t": "ἐπανελθόντες δὲ ἔνθα ἡ πρώτη συμβολὴ ἐγένετο, στησάμενοι τρόπαιον ἀπῆισαν ἐπὶ θάλατταν περὶ ἡλίου δυσμάς· στάδιοι δ᾽ ἦσαν ὡς ἑξήκοντα ἐπὶ τὸ στρατόπεδον.", "st": "6.5.32"}, {"sp": "N", "t": "ἐντεῦθεν οἱ μὲν πολέμιοι εἶχον ἀμφὶ τὰ ἑαυτῶν καὶ ἀπήγοντο καὶ τοὺς οἰκέτας καὶ τὰ χρήματα ὅποι ἐδύναντο προσωτάτω· οἱ δὲ Ἕλληνες προσέμενον μὲν Κλέανδρον καὶ τὰς τριήρεις καὶ τὰ πλοῖα ὡς ἥξοντα, ἐξιόντες δ᾽ ἑκάστης ἡμέρας σὺν τοῖς ὑποζυγίοις καὶ τοῖς ἀνδραπόδοις ἐφέροντο ἀδεῶς πυροὺς καὶ κριθάς, οἶνον, ὄσπρια, μελίνας, σῦκα· ἅπαντα γὰρ ἀγαθὰ εἶχεν ἡ χώρα πλὴν ἐλαίου.", "st": "6.6.1"}, {"sp": "N", "t": "καὶ ὁπότε μὲν καταμένοι τὸ στράτευμα ἀναπαυόμενον, ἐξῆν ἐπὶ λείαν ἰέναι, καὶ ἐλάμβανον ⟨οἱ⟩ ἐξιόντες· ὁπότε δὲ ἐξίοι πᾶν τὸ στράτευμα, εἴ τις χωρὶς ἀπελθὼν λάβοι τι, δημόσιον ἔδοξεν εἶναι.", "st": "6.6.2"}, {"sp": "N", "t": "ἤδη δὲ ἦν πάντων ἀφθονία· καὶ γὰρ ἀγοραὶ πάντοθεν ἀφικνοῦντο ἐκ τῶν Ἑλληνίδων πόλεων καὶ οἱ παραπλέοντες ἄσμενοι κατῆγον, ἀκούοντες ὡς οἰκίζοιτο πόλις καὶ λιμὴν εἴη.", "st": "6.6.3"}, {"sp": "N", "t": "ἔπεμπον δὲ καὶ οἱ πολέμιοι ἤδη οἳ πλησίον ὤικουν πρὸς Ξενοφῶντα, ἀκούοντες ὅτι οὗτος πολίζει τὸ χωρίον, ἐρωτῶντες ὅ τι δέοι ποιοῦντας φίλους εἶναι. ὁ δ᾽ ἀπεδείκνυεν αὐτοὺς τοῖς στρατιώταις.", "st": "6.6.4"}, {"sp": "N", "t": "κἀν τούτωι Κλέανδρος ἀφικνεῖται δύο τριήρεις ἔχων, πλοῖον δ᾽ οὐδέν. ἐτύγχανε δὲ τὸ στράτευμα ἔξω ὂν ὅτε ἀφίκετο καὶ ἐπὶ λείαν τινὲς οἰχόμενοι ἄλλοι εἰς τὸ ὄρος εἰλήφεσαν πρόβατα πολλά· ὀκνοῦντες δὲ μὴ ἀφαιρεθεῖεν τῶι Δεξίππωι λέγουσιν, ὃς ἀπέδρα τὴν πεντηκόντορον ἔχων ἐκ Τραπεζοῦντος, καὶ κελεύουσι διασώσαντα αὐτοῖς τὰ πρόβατα τὰ μὲν αὐτὸν λαβεῖν, τὰ δὲ σφίσιν ἀποδοῦναι.", "st": "6.6.5"}, {"sp": "N", "t": "εὐθὺς δ᾽ ἐκεῖνος ἀπελαύνει τοὺς περιεστῶτας τῶν στρατιωτῶν καὶ λέγοντας ὅτι δημόσια εἴη, καὶ τῶι Κλεάνδρωι λέγει ἐλθὼν ὅτι ἁρπάζειν ἐπιχειροῦσιν. ὁ δὲ κελεύει τὸν ἁρπάζοντα ἄγειν πρὸς αὑτόν.", "st": "6.6.6"}, {"sp": "N", "t": "καὶ ὁ μὲν λαβὼν ἦγέ τινα· περιτυχὼν δ᾽ Ἀγασίας ἀφαιρεῖται· καὶ γὰρ ἦν αὐτῶι ὁ ἀγόμενος λοχίτης. οἱ δ᾽ ἄλλοι οἱ παρόντες τῶν στρατιωτῶν ἐπιχειροῦσι βάλλειν τὸν Δέξιππον, ἀνακαλοῦντες τὸν προδότην. ἔδεισαν δὲ καὶ τῶν τριηριτῶν πολλοὶ καὶ ἔφευγον εἰς τὴν θάλατταν, καὶ Κλέανδρος δ᾽ ἔφευγε.", "st": "6.6.7"}, {"sp": "N", "t": "Ξενοφῶν δὲ καὶ οἱ ἄλλοι στρατηγοὶ κατεκώλυόν τε καὶ τῶι Κλεάνδρωι ἔλεγον ὅτι οὐδὲν εἴη πρᾶγμα, ἀλλὰ τὸ δόγμα αἴτιον εἴη τὸ τοῦ στρατεύματος ταῦτα γενέσθαι.", "st": "6.6.8"}, {"sp": "N", "t": "ὁ δὲ Κλέανδρος ὑπὸ τοῦ Δεξίππου τε ἀνερεθιζόμενος καὶ αὐτὸς ἀχθεσθεὶς ὅτι ἐφοβήθη, ἀποπλευσεῖσθαι ἔφη καὶ κηρύξειν μηδεμίαν πόλιν δέχεσθαι αὐτούς, ὡς πολεμίους. ἦρχον δὲ τότε πάντων τῶν Ἑλλήνων οἱ Λακεδαιμόνιοι.", "st": "6.6.9"}, {"sp": "N", "t": "ἐνταῦθα πονηρὸν ἐδόκει τὸ πρᾶγμα εἶναι τοῖς Ἕλλησιν, καὶ ἐδέοντο μὴ ποιεῖν ταῦτα. ὁ δ᾽ οὐκ ἂν ἄλλως ἔφη γενέσθαι, εἰ μή τις ἐκδώσει τὸν ἄρξαντα βάλλειν καὶ τὸν ἀφελόμενον.", "st": "6.6.10"}, {"sp": "N", "t": "ἦν δὲ ὃν ἐξήιτει Ἀγασίας διὰ τέλους φίλος τῶι Ξενοφῶντι· ἐξ οὗ καὶ διέβαλλεν αὐτὸν ὁ Δέξιππος. καὶ ἐντεῦθεν ἐπειδὴ ἀπορία ἦν, συνήγαγον τὸ στράτευμα οἱ ἄρχοντες· καὶ ἔνιοι μὲν αὐτῶν παρ᾽ ὀλίγον ἐποιοῦντο τὸν Κλέανδρον, τῶι δὲ Ξενοφῶντι οὐκ ἐδόκει φαῦλον εἶναι, ἀλλ᾽ ἀναστὰς ἔλεξεν·", "st": "6.6.11"}, {"sp": "N", "t": "«ὦ ἄνδρες στρατιῶται, ἐμοὶ δὲ οὐδὲν φαῦλον δοκεῖ εἶναι τὸ πρᾶγμα, εἰ ἡμῖν οὕτως ἔχων τὴν γνώμην Κλέανδρος ἄπεισιν ὥσπερ λέγει. εἰσὶ μὲν γὰρ ἐγγὺς αἱ Ἑλληνίδες πόλεις· τῆς δὲ Ἑλλάδος Λακεδαιμόνιοι προεστήκασιν· ἱκανοὶ δέ εἰσι καὶ εἷς ἕκαστος Λακεδαιμονίων ἐν ταῖς πόλεσιν ὅ τι βούλονται διαπράττεσθαι.", "st": "6.6.12"}, {"sp": "N", "t": "εἰ οὖν οὗτος πρῶτον μὲν ἡμᾶς Βυζαντίου ἀποκλείσει, ἔπειτα δὲ τοῖς ἄλλοις ἁρμοσταῖς παραγγελεῖ εἰς τὰς πόλεις μὴ δέχεσθαι ὡς ἀπιστοῦντας Λακεδαιμονίοις καὶ ἀνόμους ὄντας, ἔτι δὲ πρὸς Ἀναξίβιον τὸν ναύαρχον οὗτος ὁ λόγος περὶ ἡμῶν ἥξει, χαλεπὸν ἔσται καὶ μένειν καὶ ἀποπλεῖν· καὶ γὰρ ἐν τῆι γῆι ἄρχουσι Λακεδαιμόνιοι καὶ ἐν τῆι θαλάττηι τὸν νῦν χρόνον.", "st": "6.6.13"}, {"sp": "N", "t": "οὔκουν δεῖ οὔτε ἑνὸς ἀνδρὸς ἕνεκα οὔτε δυοῖν ἡμᾶς τοὺς ἄλλους τῆς Ἑλλάδος ἀπέχεσθαι, ἀλλὰ πειστέον ὅ τι ἂν κελεύωσι· καὶ γὰρ αἱ πόλεις ἡμῶν ὅθεν ἐσμὲν πείθονται αὐτοῖς.", "st": "6.6.14"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν (καὶ γὰρ ἀκούω Δέξιππον λέγειν πρὸς Κλέανδρον ὡς οὐκ ἂν ἐποίησεν Ἀγασίας ταῦτα, εἰ μὴ ἐγὼ αὐτὸν ἐκέλευσα), ἐγὼ μὲν οὖν ἀπολύω καὶ ὑμᾶς τῆς αἰτίας καὶ Ἀγασίαν, ἂν αὐτὸς Ἀγασίας φήσηι ἐμέ τι τούτων αἴτιον εἶναι, καὶ καταδικάζω ἐμαυτοῦ, εἰ ἐγὼ πετροβολίας ἢ ἄλλου τινὸς βιαίου ἐξάρχω, τῆς ἐσχάτης δίκης ἄξιος εἶναι, καὶ ὑφέξω τὴν δίκην.", "st": "6.6.15"}, {"sp": "N", "t": "φημὶ δὲ καὶ εἴ τινα ἄλλον αἰτιᾶται, χρῆναι ἑαυτὸν παρασχεῖν Κλεάνδρωι κρῖναι· οὕτω γὰρ ἂν ὑμεῖς ἀπολελυμένοι τῆς αἰτίας εἴητε. ὡς δὲ νῦν ἔχει, χαλεπὸν εἰ οἰόμενοι ἐν τῆι Ἑλλάδι καὶ ἐπαίνου καὶ τιμῆς τεύξεσθαι ἀντὶ δὲ τούτων οὐδ᾽ ὅμοιοι τοῖς ἄλλοις ἐσόμεθα, ἀλλ᾽ εἰρξόμεθα ἐκ τῶν Ἑλληνίδων πόλεων.»", "st": "6.6.16"}, {"sp": "N", "t": "μετὰ ταῦτα ἀναστὰς εἶπεν Ἀγασίας· «ἐγώ, ὦ ἄνδρες, ὄμνυμι θεοὺς καὶ θεὰς ἦ μὴν μήτε με Ξενοφῶντα κελεῦσαι ἀφελέσθαι τὸν ἄνδρα μήτε ἄλλον ὑμῶν μηδένα· ἰδόντι δέ μοι ἄνδρα ἀγαθὸν ἀγόμενον τῶν ἐμῶν λοχιτῶν ὑπὸ Δεξίππου, ὃν ὑμεῖς ἐπίστασθε ὑμᾶς προδόντα, δεινὸν ἔδοξεν εἶναι·", "st": "6.6.17"}, {"sp": "N", "t": "καὶ ἀφειλόμην, ὁμολογῶ. καὶ ὑμεῖς μὲν μὴ ἐκδῶτέ με· ἐγὼ δὲ ἐμαυτόν, ὥσπερ Ξενοφῶν λέγει, παρασχήσω κρίναντι Κλεάνδρωι ὅ τι ἂν βούληται ποιῆσαι· τούτου ἕνεκα μήτε πολεμεῖτε Λακεδαιμονίοις σώιζεσθέ τε ἀσφαλῶς ὅποι θέλει ἕκαστος. συμπέμψατε μέντοι μοι ὑμῶν αὐτῶν ἑλόμενοι πρὸς Κλέανδρον οἵτινες, ἄν τι ἐγὼ παραλίπω, καὶ λέξουσιν ὑπὲρ ἐμοῦ καὶ πράξουσιν.»", "st": "6.6.18"}, {"sp": "N", "t": "ἐκ τούτου ἔδωκεν ἡ στρατιὰ οὕστινας βούλοιτο προελόμενον ἰέναι. ὁ δὲ προείλετο τοὺς στρατηγούς. μετὰ ταῦτα ἐπορεύετο πρὸς Κλέανδρον Ἀγασίας καὶ οἱ στρατηγοὶ καὶ ὁ ἀφαιρεθεὶς ἀνὴρ ὑπὸ Ἀγασίου.", "st": "6.6.19"}, {"sp": "N", "t": "καὶ ἔλεγον οἱ στρατηγοί· «ἔπεμψεν ἡμᾶς ἡ στρατιὰ πρὸς σέ, ὦ Κλέανδρε, καὶ κελεύουσί σε, εἴτε πάντας αἰτιᾶι, κρίναντα σὲ αὐτὸν χρῆσθαι ὅ τι ἂν βούληι, εἴτε ἕνα τινὰ ἢ δύο καὶ πλείους αἰτιᾶι, τούτους ἀξιοῦσι παρασχεῖν σοι ἑαυτοὺς εἰς κρίσιν. εἴ τι οὖν ἡμῶν τινα αἰτιᾶι, πάρεσμέν σοι ἡμεῖς· εἴ τι δὲ ἄλλον τινά, φράσον· οὐδεὶς γὰρ ἀπέσται ὅστις ἂν ἡμῖν ἐθέληι πείθεσθαι.»", "st": "6.6.20"}, {"sp": "N", "t": "μετὰ ταῦτα παρελθὼν ὁ Ἀγασίας εἶπεν· «ἐγώ εἰμι, ὦ Κλέανδρε, ὁ ἀφελόμενος Δεξίππου ἄγοντος τοῦτον τὸν ἄνδρα καὶ παίειν κελεύσας Δέξιππον.", "st": "6.6.21"}, {"sp": "N", "t": "τοῦτον μὲν γὰρ οἶδα ἄνδρα ἀγαθὸν ὄντα, Δέξιππον δὲ οἶδα αἱρεθέντα ὑπὸ τῆς στρατιᾶς ἄρχειν τῆς πεντηκοντόρου ἧς ἠιτησάμεθα παρὰ Τραπεζουντίων ἐφ᾽ ὧιτε πλοῖα συλλέγειν ὡς σωιζοίμεθα, καὶ ἀποδράντα Δέξιππον καὶ προδόντα τοὺς στρατιώτας μεθ᾽ ὧν ἐσώθη.", "st": "6.6.22"}, {"sp": "N", "t": "καὶ τούς τε Τραπεζουντίους ἀπεστερήκαμεν τὴν πεντηκόντορον καὶ κακοὶ δοκοῦμεν εἶναι διὰ τοῦτον, αὐτοί τε τὸ ἐπὶ τούτωι ἀπολώλαμεν. ἤκουε γάρ, ὥσπερ ἡμεῖς, ὡς ἄπορον εἴη πεζῆι ἀπιόντας τοὺς ποταμούς τε διαβῆναι καὶ σωθῆναι εἰς τὴν Ἑλλάδα.", "st": "6.6.23"}, {"sp": "N", "t": "τοῦτον οὖν τοιοῦτον ὄντα ἀφειλόμην. εἰ δὲ σὺ ἦγες ἢ ἄλλος τις τῶν παρὰ σοῦ, καὶ μὴ τῶν παρ᾽ ἡμῶν ἀποδράντων, εὖ ἴσθι ὅτι οὐδὲν ἂν τούτων ἐποίησα. νόμιζε δέ, ἂν ἐμὲ νῦν ἀποκτείνηις, δι᾽ ἄνδρα δειλόν τε καὶ πονηρὸν ἄνδρα ἀγαθὸν ἀποκτείνων.»", "st": "6.6.24"}, {"sp": "N", "t": "ἀκούσας ταῦτα ὁ Κλέανδρος εἶπεν ὅτι Δέξιππον μὲν οὐκ ἐπαινοίη, εἰ ταῦτα πεποιηκὼς εἴη· οὐ μέντοι ἔφη νομίζειν οὐδ᾽ εἰ παμπόνηρος ἦν Δέξιππος βίαι χρῆναι πάσχειν αὐτόν, ἀλλὰ κριθέντα, ὥσπερ καὶ ὑμεῖς νῦν ἀξιοῦτε, τῆς δίκης τυχεῖν.", "st": "6.6.25"}, {"sp": "N", "t": "νῦν οὖν ἄπιτε καταλιπόντες τόνδε τὸν ἄνδρα· ὅταν δ᾽ ἐγὼ κελεύσω, πάρεστε πρὸς τὴν κρίσιν. αἰτιῶμαι δὲ οὔτε τὴν στρατιὰν οὔτε ἄλλον οὐδένα ἔτι, ἐπεὶ οὗτος αὐτὸς ὁμολογεῖ ἀφελέσθαι τὸν ἄνδρα.", "st": "6.6.26"}, {"sp": "N", "t": "ὁ δὲ ἀφαιρεθεὶς εἶπεν· «ἐγώ, ὦ Κλέανδρε, εἰ καὶ οἴει με ἀδικοῦντά τι ἄγεσθαι, οὔτε ἔπαιον οὐδένα οὔτε ἔβαλλον, ἀλλ᾽ εἶπον ὅτι δημόσια εἴη τὰ πρόβατα· ἦν γὰρ τῶν στρατιωτῶν δόγμα, εἴ τις ὁπότε ἡ στρατιὰ ἐξίοι ἰδίαι λήιζοιτο, δημόσια εἶναι τὰ ληφθέντα.", "st": "6.6.27"}, {"sp": "N", "t": "ταῦτα εἶπον· ἐκ τούτου με λαβὼν οὗτος ἦγεν, ἵνα μὴ φθέγγοιτο μηδείς, ἀλλ᾽ αὐτὸς λαβὼν τὸ μέρος διασώσειε τοῖς ληισταῖς παρὰ τὴν ῥήτραν τὰ χρήματα.» πρὸς ταῦτα ὁ Κλέανδρος εἶπεν· «ἐπεὶ τοίνυν ... εἶ, κατάμενε, ἵνα καὶ περὶ σοῦ βουλευσώμεθα.»", "st": "6.6.28"}, {"sp": "N", "t": "ἐκ τούτου οἱ μὲν ἀμφὶ Κλέανδρον ἠρίστων· τὴν δὲ στρατιὰν συνήγαγε Ξενοφῶν καὶ συνεβούλευε πέμψαι ἄνδρας πρὸς Κλέανδρον παραιτησομένους περὶ τῶν ἀνδρῶν.", "st": "6.6.29"}, {"sp": "N", "t": "ἐκ τούτου ἔδοξεν αὐτοῖς πέμψαντας στρατηγοὺς καὶ λοχαγοὺς καὶ Δρακόντιον τὸν Σπαρτιάτην καὶ τῶν ἄλλων οἳ ἐδόκουν ἐπιτήδειοι εἶναι δεῖσθαι Κλεάνδρου κατὰ πάντα τρόπον ἀφεῖναι τὼ ἄνδρε.", "st": "6.6.30"}, {"sp": "N", "t": "ἐλθὼν οὖν ὁ Ξενοφῶν λέγει· «ἔχεις μέν, ὦ Κλέανδρε, τοὺς ἄνδρας, καὶ ἡ στρατιά σοι ὑφεῖτο ὅ τι ἐβούλου ποιῆσαι καὶ περὶ τούτων καὶ περὶ αὑτῶν ἁπάντων. νῦν δέ σε αἰτοῦνται καὶ δέονται δοῦναι σφίσι τὼ ἄνδρε καὶ μὴ κατακαίνειν· πολλὰ γὰρ ἐν τῶι ἔμπροσθεν χρόνωι περὶ τὴν στρατιὰν ἐμοχθησάτην.", "st": "6.6.31"}, {"sp": "N", "t": "ταῦτα δέ σου τυχόντες ὑπισχνοῦνταί σοι ἀντὶ τούτων, ἢν βούληι ἡγεῖσθαι αὐτῶν καὶ ἢν οἱ θεοὶ ἵλεωι ὦσιν, ἐπιδείξειν σοι καὶ ὡς κόσμιοί εἰσι καὶ ὡς ἱκανοὶ τῶι ἄρχοντι πειθόμενοι τοὺς πολεμίους σὺν τοῖς θεοῖς μὴ φοβεῖσθαι.", "st": "6.6.32"}, {"sp": "N", "t": "δέονται δέ σου καὶ τοῦτο, παραγενόμενον καὶ ἄρξαντα ἑαυτῶν πεῖραν λαβεῖν καὶ Δεξίππου καὶ σφῶν τῶν ἄλλων οἷος ἕκαστός ἐστι, καὶ τὴν ἀξίαν ἑκάστοις νεῖμαι.»", "st": "6.6.33"}, {"sp": "N", "t": "ἀκούσας ταῦτα ὁ Κλέανδρος· «ἀλλὰ ναὶ τὼ σιώ, ἔφη, ταχύ τοι ὑμῖν ἀποκρινοῦμαι. καὶ τώ τε ἄνδρε ὑμῖν δίδωμι καὶ αὐτὸς παρέσομαι· καὶ ἢν οἱ θεοὶ παραδιδῶσιν, ἐξηγήσομαι εἰς τὴν Ἑλλάδα. καὶ πολὺ οἱ λόγοι οὗτοι ἀντίοι εἰσὶν ἢ οὓς ἐγὼ περὶ ὑμῶν ἐνίων ἤκουον ὡς τὸ στράτευμα ἀφίστατε ἀπὸ Λακεδαιμονίων.»", "st": "6.6.34"}, {"sp": "N", "t": "ἐκ τούτου οἱ μὲν ἐπαινοῦντες ἀπῆλθον, ἔχοντες τὼ ἄνδρε· Κλέανδρος δὲ ἐθύετο ἐπὶ τῆι πορείαι καὶ ξυνῆν Ξενοφῶντι φιλικῶς καὶ ξενίαν ξυνεβάλλοντο. ἐπεὶ δὲ καὶ ἑώρα αὐτοὺς τὸ παραγγελλόμενον εὐτάκτως ποιοῦντας, καὶ μᾶλλον ἔτι ἐπεθύμει ἡγεμὼν γενέσθαι αὐτῶν.", "st": "6.6.35"}, {"sp": "N", "t": "ἐπεὶ μέντοι θυομένωι αὐτῶι ἐπὶ τρεῖς ἡμέρας οὐκ ἐγίγνετο τὰ ἱερά, συγκαλέσας τοὺς στρατηγοὺς εἶπεν· «ἐμοὶ μὲν οὐ τελέθει τὰ ἱερὰ ἐξάγειν· ὑμεῖς μέντοι μὴ ἀθυμεῖτε τούτου ἕνεκα· ὑμῖν γάρ, ὡς ἔοικε, δέδοται ἐκκομίσαι τοὺς ἄνδρας· ἀλλὰ πορεύεσθε. ἡμεῖς δὲ ὑμᾶς, ἐπειδὰν ἐκεῖσε ἥκητε, δεξόμεθα ὡς ἂν δυνώμεθα κάλλιστα.»", "st": "6.6.36"}, {"sp": "N", "t": "ἐκ τούτου ἔδοξε τοῖς στρατιώταις δοῦναι αὐτῶι τὰ δημόσια πρόβατα· ὁ δὲ δεξάμενος πάλιν αὐτοῖς ἀπέδωκε. καὶ οὗτος μὲν ἀπέπλει. οἱ δὲ στρατιῶται διαθέμενοι τὸν σῖτον ὃν ἦσαν συγκεκομισμένοι καὶ τἆλλα ἃ εἰλήφεσαν ἐξεπορεύοντο διὰ τῶν Βιθυνῶν.", "st": "6.6.37"}, {"sp": "N", "t": "ἐπεὶ δὲ οὐδενὶ ἐνέτυχον πορευόμενοι τὴν ὀρθὴν ὁδόν, ὥστε ἔχοντές τι εἰς τὴν φιλίαν ἐλθεῖν, ἔδοξεν αὐτοῖς τοὔμπαλιν ὑποστρέψαντας ἐλθεῖν μίαν ἡμέραν καὶ νύκτα. τοῦτο δὲ ποιήσαντες ἔλαβον πολλὰ καὶ ἀνδράποδα καὶ πρόβατα· καὶ ἀφίκοντο ἑκταῖοι εἰς Χρυσόπολιν τῆς Καλχηδονίας, καὶ ἐκεῖ ἔμειναν ἡμέρας ἑπτὰ λαφυροπωλοῦντες.", "st": "6.6.38"}, {"sp": "HDR", "t": "Βιβλίον ζʹ", "st": "7.1.1"}, {"sp": "N", "t": "[ Ὅσα μὲν δὴ ἐν τῆι ἀναβάσει τῆι μετὰ Κύρου ἔπραξαν οἱ Ἕλληνες μέχρι τῆς μάχης, καὶ ὅσα ἐπεὶ Κῦρος ἐτελεύτησεν ἐν τῆι πορείαι μέχρι εἰς τὸν Πόντον ἀφίκοντο, καὶ ὅσα ἐκ τοῦ Πόντου πεζῆι ἐξιόντες καὶ ἐκπλέοντες ἐποίουν μέχρι ἔξω τοῦ στόματος ἐγένοντο ἐν Χρυσοπόλει τῆς Ἀσίας, ἐν τῶι πρόσθεν λόγωι δεδήλωται.]", "st": "7.1.1"}, {"sp": "N", "t": "Ἐκ τούτου δὲ Φαρνάβαζος φοβούμενος τὸ στράτευμα μὴ ἐπὶ τὴν αὑτοῦ χώραν στρατεύηται, πέμψας πρὸς Ἀναξίβιον τὸν ναύαρχον (ὁ δ᾽ ἔτυχεν ἐν Βυζαντίωι ὤν), ἐδεῖτο διαβιβάσαι τὸ στράτευμα ἐκ τῆς Ἀσίας, καὶ ὑπισχνεῖτο πάντα ποιήσειν αὐτῶι ὅσα δέοι.", "st": "7.1.2"}, {"sp": "N", "t": "καὶ ὁ Ἀναξίβιος μετεπέμψατο τοὺς στρατηγοὺς καὶ λοχαγοὺς εἰς Βυζάντιον, καὶ ὑπισχνεῖτο, εἰ διαβαῖεν, μισθοφορὰν ἔσεσθαι τοῖς στρατιώταις.", "st": "7.1.3"}, {"sp": "N", "t": "οἱ μὲν δὴ ἄλλοι ἔφασαν βουλευσάμενοι ἀπαγγελεῖν, Ξενοφῶν δὲ εἶπεν αὐτῶι ὅτι ἀπαλλάξοιτο ἤδη ἀπὸ τῆς στρατιᾶς καὶ βούλοιτο ἀποπλεῖν. ὁ δὲ Ἀναξίβιος ἐκέλευσεν αὐτὸν συνδιαβάντα ἔπειτα οὕτως ἀπαλλάττεσθαι. ἔφη οὖν ταῦτα ποιήσειν.", "st": "7.1.4"}, {"sp": "N", "t": "Σεύθης δὲ ὁ Θρᾶιξ πέμπει Μηδοσάδην καὶ κελεύει Ξενοφῶντα συμπροθυμεῖσθαι ὅπως διαβῆι τὸ στράτευμα, καὶ ἔφη αὐτῶι ταῦτα συμπροθυμηθέντι ὅτι οὐ μεταμελήσει.", "st": "7.1.5"}, {"sp": "N", "t": "ὁ δ᾽ εἶπεν· «ἀλλὰ τὸ μὲν στράτευμα διαβήσεται· τούτου ἕνεκα μηδὲν τελείτω μήτε ἐμοὶ μήτε ἄλλωι μηδενί· ἐπειδὰν δὲ διαβῆι, ἐγὼ μὲν ἀπαλλάξομαι, πρὸς δὲ τοὺς διαμένοντας καὶ ἐπικαιρίους ὄντας προσφερέσθω ὡς ἂν αὐτῶι δοκῆι ἀσφαλές.»", "st": "7.1.6"}, {"sp": "N", "t": "ἐκ τούτου διαβαίνουσι πάντες εἰς τὸ Βυζάντιον οἱ στρατιῶται. καὶ μισθὸν μὲν οὐκ ἐδίδου ὁ Ἀναξίβιος, ἐκήρυξε δὲ λαβόντας τὰ ὅπλα καὶ τὰ σκεύη τοὺς στρατιώτας ἐξιέναι, ὡς ἀποπέμψων τε ἅμα καὶ ἀριθμὸν ποιήσων. ἐνταῦθα οἱ στρατιῶται ἤχθοντο, ὅτι οὐκ εἶχον ἀργύριον ἐπισιτίζεσθαι εἰς τὴν πορείαν, καὶ ὀκνηρῶς συνεσκευάζοντο.", "st": "7.1.7"}, {"sp": "N", "t": "καὶ ὁ Ξενοφῶν Κλεάνδρωι τῶι ἁρμοστῆι ξένος γεγενημένος προσελθὼν ἠσπάζετο αὐτὸν ὡς ἀποπλευσούμενος ἤδη. ὁ δὲ αὐτῶι λέγει· «μὴ ποιήσηις ταῦτα· εἰ δὲ μή, ἔφη, αἰτίαν ἕξεις, ἐπεὶ καὶ νῦν τινὲς ἤδη σὲ αἰτιῶνται ὅτι οὐ ταχὺ ἐξέρπει τὸ στράτευμα.»", "st": "7.1.8"}, {"sp": "N", "t": "ὁ δ᾽ εἶπεν· «ἀλλ᾽ αἴτιος μὲν ἔγωγε οὐκ εἰμὶ τούτου, οἱ δὲ στρατιῶται αὐτοὶ ἐπισιτισμοῦ δεόμενοι διὰ τοῦτο ἀθυμοῦσι πρὸς τὴν ἔξοδον.»", "st": "7.1.9"}, {"sp": "N", "t": "«ἀλλ᾽ ὅμως, ἔφη, ἐγώ σοι συμβουλεύω ἐξελθεῖν μὲν ὡς πορευσόμενον, ἐπειδὰν δ᾽ ἔξω γένηται τὸ στράτευμα, τότε ἀπαλλάττεσθαι.» «ταῦτα τοίνυν, ἔφη ὁ Ξενοφῶν, ἐλθόντες πρὸς Ἀναξίβιον διαπραξόμεθα.", "st": "7.1.10"}, {"sp": "N", "t": "οὕτως ἐλθόντες ἔλεγον ταῦτα. ὁ δὲ ἐκέλευεν οὕτω ποιεῖν καὶ ἐξιέναι τὴν ταχίστην συσκευασαμένους, καὶ προσανεῖπεν, ὃς ἂν μὴ παρῆι εἰς τὴν ἐξέτασιν καὶ εἰς τὸν ἀριθμόν, ὅτι αὐτὸς αὑτὸν αἰτιάσεται.", "st": "7.1.11"}, {"sp": "N", "t": "ἐντεῦθεν ἐξῆισαν οἵ τε στρατηγοὶ πρῶτοι καὶ οἱ ἄλλοι. καὶ ἄρδην πάντες πλὴν ὀλίγων ἔξω ἦσαν, καὶ Ἐτεόνικος εἱστήκει παρὰ τὰς πύλας ὡς ὁπότε ἔξω γένοιντο πάντες συγκλείσων τὰς πύλας καὶ τὸν μοχλὸν ἐμβαλῶν.", "st": "7.1.12"}, {"sp": "N", "t": "ὁ δὲ Ἀναξίβιος συγκαλέσας τοὺς στρατηγοὺς καὶ τοὺς λοχαγοὺς ἔλεγεν· «τὰ μὲν ἐπιτήδεια, ἔφη, λαμβάνετε ἐκ τῶν Θραικίων κωμῶν· εἰσὶ δὲ αὐτόθι πολλαὶ κριθαὶ καὶ πυροὶ καὶ τἆλλα ἐπιτήδεια· λαβόντες δὲ πορεύεσθε εἰς Χερρόνησον, ἐκεῖ δὲ Κυνίσκος ὑμῖν μισθοδοτήσει.»", "st": "7.1.13"}, {"sp": "N", "t": "ἐπακούσαντες δέ τινες τῶν στρατιωτῶν ταῦτα, ἢ καὶ τῶν λοχαγῶν τις διαγγέλλει εἰς τὸ στράτευμα. καὶ οἱ μὲν στρατηγοὶ ἐπυνθάνοντο περὶ τοῦ Σεύθου πότερα πολέμιος εἴη ἢ φίλος, καὶ πότερα διὰ τοῦ ἱεροῦ ὄρους δέοι πορεύεσθαι ἢ κύκλωι διὰ μέσης τῆς Θράικης.", "st": "7.1.14"}, {"sp": "N", "t": "ἐν ὧι δὲ ταῦτα διελέγοντο οἱ στρατιῶται ἀναρπάσαντες τὰ ὅπλα θέουσι δρόμωι πρὸς τὰς πύλας, ὡς πάλιν εἰς τὸ τεῖχος εἰσιόντες. ὁ δὲ Ἐτεόνικος καὶ οἱ σὺν αὐτῶι ὡς εἶδον προσθέοντας τοὺς ὁπλίτας, συγκλείουσι τὰς πύλας καὶ τὸν μοχλὸν ἐμβάλλουσιν.", "st": "7.1.15"}, {"sp": "N", "t": "οἱ δὲ στρατιῶται ἔκοπτον τὰς πύλας καὶ ἔλεγον ὅτι ἀδικώτατα πάσχοιεν ἐκβαλλόμενοι εἰς τοὺς πολεμίους· κατασχίσειν τε τὰς πύλας ἔφασαν, εἰ μὴ ἑκόντες ἀνοίξουσιν.", "st": "7.1.16"}, {"sp": "N", "t": "ἄλλοι δὲ ἔθεον ἐπὶ θάλατταν καὶ παρὰ τὴν χηλὴν τοῦ τείχους ὑπερβαίνουσιν εἰς τὴν πόλιν, ἄλλοι δὲ οἳ ἐτύγχανον ἔνδον ὄντες τῶν στρατιωτῶν, ὡς ὁρῶσι τὰ ἐπὶ ταῖς πύλαις πράγματα, διακόπτοντες ταῖς ἀξίναις τὰ κλεῖθρα ἀναπεταννύασι τὰς πύλας, οἱ δ᾽ εἰσπίπτουσιν.", "st": "7.1.17"}, {"sp": "N", "t": "ὁ δὲ Ξενοφῶν ὡς εἶδε τὰ γιγνόμενα, δείσας μὴ ἐφ᾽ ἁρπαγὴν τράποιτο τὸ στράτευμα καὶ ἀνήκεστα κακὰ γένοιτο τῆι πόλει καὶ ἑαυτῶι καὶ τοῖς στρατιώταις, ἔθει καὶ συνεισπίπτει εἴσω τῶν πυλῶν σὺν τῶι ὄχλωι.", "st": "7.1.18"}, {"sp": "N", "t": "οἱ δὲ Βυζάντιοι ὡς εἶδον τὸ στράτευμα βίαι εἰσπῖπτον, φεύγουσιν ἐκ τῆς ἀγορᾶς, οἱ μὲν εἰς τὰ πλοῖα, οἱ δὲ οἴκαδε, ὅσοι δὲ ἔνδον ἐτύγχανον ὄντες, ἔξω, οἱ δὲ καθεῖλκον τὰς τριήρεις, ὡς ἐν ταῖς τριήρεσι σώιζοιντο, πάντες δὲ ὤιοντο ἀπολωλέναι, ὡς ἑαλωκυίας τῆς πόλεως.", "st": "7.1.19"}, {"sp": "N", "t": "ὁ δὲ Ἐτεόνικος εἰς τὴν ἄκραν ἀποφεύγει. ὁ δὲ Ἀναξίβιος καταδραμὼν ἐπὶ θάλατταν ἐν ἁλιευτικῶι πλοίωι περιέπλει εἰς τὴν ἀκρόπολιν, καὶ εὐθὺς μεταπέμπεται ἐκ Καλχηδόνος φρουρούς· οὐ γὰρ ἱκανοὶ ἐδόκουν εἶναι οἱ ἐν τῆι ἀκροπόλει σχεῖν τοὺς ἄνδρας.", "st": "7.1.20"}, {"sp": "N", "t": "οἱ δὲ στρατιῶται ὡς εἶδον Ξενοφῶντα, προσπίπτουσι πολλοὶ αὐτῶι καὶ λέγουσι· «νῦν σοι ἔξεστιν, ὦ Ξενοφῶν, ἀνδρὶ γενέσθαι. ἔχεις πόλιν, ἔχεις τριήρεις, ἔχεις χρήματα, ἔχεις ἄνδρας τοσούτους. νῦν ἄν, εἰ βούλοιο, σύ τε ἡμᾶς ὀνήσαις καὶ ἡμεῖς σὲ μέγαν ποιήσαιμεν.»", "st": "7.1.21"}, {"sp": "N", "t": "ὁ δ᾽ ἀπεκρίνατο· «ἀλλ᾽ εὖ γε λέγετε καὶ ποιήσω ταῦτα· εἰ δὲ τούτων ἐπιθυμεῖτε, θέσθε τὰ ὅπλα ἐν τάξει ὡς τάχιστα·» βουλόμενος αὐτοὺς κατηρεμίσαι· καὶ αὐτός τε παρηγγύα ταῦτα καὶ τοὺς ἄλλους ἐκέλευε παρεγγυᾶν [καὶ] τίθεσθαι τὰ ὅπλα.", "st": "7.1.22"}, {"sp": "N", "t": "οἱ δὲ αὐτοὶ ὑφ᾽ ἑαυτῶν ταττόμενοι οἵ τε ὁπλῖται ἐν ὀλίγωι χρόνωι εἰς ὀκτὼ ἐγένοντο καὶ οἱ πελτασταὶ ἐπὶ τὸ κέρας ἑκάτερον παρεδεδραμήκεσαν.", "st": "7.1.23"}, {"sp": "N", "t": "τὸ δὲ χωρίον οἷον κάλλιστον ἐκτάξασθαί ἐστι τὸ Θράικιον καλούμενον, ἔρημον οἰκιῶν καὶ πεδινόν. ἐπεὶ δὲ ἔκειτο τὰ ὅπλα καὶ κατηρεμίσθησαν, συγκαλεῖ ὁ Ξενοφῶν τὴν στρατιὰν καὶ λέγει τάδε.", "st": "7.1.24"}, {"sp": "N", "t": "«ὅτι μὲν ὀργίζεσθε, ὦ ἄνδρες στρατιῶται, καὶ νομίζετε δεινὰ πάσχειν ἐξαπατώμενοι οὐ θαυμάζω. ἢν δὲ τῶι θυμῶι χαριζώμεθα καὶ Λακεδαιμονίους τε τοὺς παρόντας τῆς ἐξαπάτης τιμωρησώμεθα καὶ τὴν πόλιν τὴν οὐδὲν αἰτίαν διαρπάσωμεν, ἐνθυμεῖσθε ἃ ἔσται ἐντεῦθεν.", "st": "7.1.25"}, {"sp": "N", "t": "πολέμιοι μὲν ἐσόμεθα ἀποδεδειγμένοι Λακεδαιμονίοις καὶ τοῖς συμμάχοις. οἷος δὲ πόλεμος ἂν γένοιτο εἰκάζειν δὴ πάρεστιν, ἑορακότας καὶ ἀναμνησθέντας τὰ νῦν δὴ γεγενημένα.", "st": "7.1.26"}, {"sp": "N", "t": "ἡμεῖς γὰρ οἱ Ἀθηναῖοι ἤλθομεν εἰς τὸν πόλεμον τὸν πρὸς Λακεδαιμονίους καὶ τοὺς συμμάχους ἔχοντες τριήρεις τὰς μὲν ἐν θαλάττηι τὰς δ᾽ ἐν τοῖς νεωρίοις οὐκ ἐλάττους τριακοσίων, ὑπαρχόντων δὲ πολλῶν χρημάτων ἐν τῆι πόλει καὶ προσόδου οὔσης κατ᾽ ἐνιαυτὸν ἀπό τε τῶν ἐνδήμων καὶ τῆς ὑπερορίας οὐ μεῖον χιλίων ταλάντων· ἄρχοντες δὲ τῶν νήσων ἁπασῶν καὶ ἔν τε τῆι Ἀσίαι πολλὰς ἔχοντες πόλεις καὶ ἐν τῆι Εὐρώπηι ἄλλας τε πολλὰς καὶ αὐτὸ τοῦτο τὸ Βυζάντιον, ὅπου νῦν ἐσμεν, ἔχοντες κατεπολεμήθημεν οὕτως ὡς πάντες ὑμεῖς ἐπίστασθε.", "st": "7.1.27"}, {"sp": "N", "t": "νῦν δὲ δὴ τί ἂν οἰόμεθα παθεῖν, Λακεδαιμονίοις μὲν καὶ τῶν ἀρχαίων συμμάχων ὑπαρχόντων, Ἀθηναίων δὲ καὶ οἳ ἐκείνοις τότε ἦσαν σύμμαχοι πάντων προσγεγενημένων, Τισσαφέρνους δὲ καὶ τῶν ἐπὶ θαλάττηι ἄλλων βαρβάρων πάντων πολεμίων ἡμῖν ὄντων, πολεμιωτάτου δὲ αὐτοῦ τοῦ ἄνω βασιλέως, ὃν ἤλθομεν ἀφαιρησόμενοι τὴν ἀρχὴν καὶ ἀποκτενοῦντες, εἰ δυναίμεθα; τούτων δὴ πάντων ὁμοῦ ὄντων ἔστι τις οὕτως ἄφρων ὅστις οἴεται ἂν ἡμᾶς περιγενέσθαι;", "st": "7.1.28"}, {"sp": "N", "t": "μὴ πρὸς θεῶν μαινώμεθα μηδ᾽ αἰσχρῶς ἀπολώμεθα πολέμιοι ὄντες καὶ ταῖς πατρίσι καὶ τοῖς ἡμετέροις αὐτῶν φίλοις τε καὶ οἰκείοις. ἐν γὰρ ταῖς πόλεσίν εἰσι πάντες ταῖς ἐφ᾽ ἡμᾶς στρατευσομέναις, καὶ δικαίως, εἰ βάρβαρον μὲν πόλιν οὐδεμίαν ἠθελήσαμεν κατασχεῖν, καὶ ταῦτα κρατοῦντες, Ἑλληνίδα δὲ εἰς ἣν πρώτην ἤλθομεν πόλιν, ταύτην ἐξαλαπάξομεν.", "st": "7.1.29"}, {"sp": "N", "t": "ἐγὼ μὲν τοίνυν εὔχομαι πρὶν ταῦτα ἐπιδεῖν ὑφ᾽ ὑμῶν γενόμενα μυρίας ἐμέ γε κατὰ τῆς γῆς ὀργυιὰς γενέσθαι. καὶ ὑμῖν δὲ συμβουλεύω Ἕλληνας ὄντας τοῖς τῶν Ἑλλήνων προεστηκόσι πειθομένους πειρᾶσθαι τῶν δικαίων τυγχάνειν. ἐὰν δὲ μὴ δύνησθε ταῦτα, ἡμᾶς δεῖ ἀδικουμένους τῆς γοῦν Ἑλλάδος μὴ στέρεσθαι.", "st": "7.1.30"}, {"sp": "N", "t": "καὶ νῦν μοι δοκεῖ πέμψαντας Ἀναξιβίωι εἰπεῖν ὅτι ἡμεῖς οὐδὲν βίαιον ποιήσοντες παρεληλύθαμεν εἰς τὴν πόλιν, ἀλλ᾽ ἢν μὲν δυνώμεθα παρ᾽ ὑμῶν ἀγαθόν τι εὑρίσκεσθαι, εἰ δὲ μή, ἀλλὰ δηλώσοντες ὅτι οὐκ ἐξαπατώμενοι ἀλλὰ πειθόμενοι ἐξερχόμεθα.»", "st": "7.1.31"}, {"sp": "N", "t": "ταῦτα ἔδοξε, καὶ πέμπουσιν Ἱερώνυμόν τε τὸν Ἠλεῖον ἐροῦντα ταῦτα καὶ Εὐρύλοχον Ἀρκάδα καὶ Φιλήσιον Ἀχαιόν. οἱ μὲν ταῦτα ὤιχοντο ἐροῦντες.", "st": "7.1.32"}, {"sp": "N", "t": "ἔτι δὲ καθημένων τῶν στρατιωτῶν προσέρχεται Κοιρατάδας Θηβαῖος, ὃς οὐ φεύγων τὴν Ἑλλάδα περιήιει ἀλλὰ στρατηγιῶν καὶ ἐπαγγελλόμενος, εἴ τις ἢ πόλις ἢ ἔθνος στρατηγοῦ δέοιτο· καὶ τότε προσελθὼν ἔλεγεν ὅτι ἕτοιμος εἴη ἡγεῖσθαι αὐτοῖς εἰς τὸ Δέλτα καλούμενον τῆς Θράικης, ἔνθα πολλὰ κἀγαθὰ λήψοιντο· ἔστε δ᾽ ἂν μόλωσιν, εἰς ἀφθονίαν παρέξειν ἔφη καὶ σιτία καὶ ποτά.", "st": "7.1.33"}, {"sp": "N", "t": "ἀκούουσι ταῦτα τοῖς στρατιώταις καὶ τὰ παρὰ Ἀναξιβίου ἅμα ἀπαγγελλόμενα (ἀπεκρίνατο γὰρ ὅτι πειθομένοις αὐτοῖς οὐ μεταμελήσει, ἀλλὰ τοῖς τε οἴκοι τέλεσι ταῦτα ἀπαγγελεῖ καὶ αὐτὸς βουλεύσοιτο περὶ αὐτῶν ὅ τι δύναιτο ἀγαθόν),", "st": "7.1.34"}, {"sp": "N", "t": "ἐκ τούτου οἱ στρατιῶται τόν τε Κοιρατάδαν δέχονται στρατηγὸν καὶ ἔξω τοῦ τείχους ἀπῆλθον. ὁ δὲ Κοιρατάδας συντίθεται αὐτοῖς εἰς τὴν ὑστεραίαν παρέσεσθαι ἐπὶ τὸ στράτευμα ἔχων καὶ ἱερεῖα καὶ μάντιν καὶ σιτία καὶ ποτὰ τῆι στρατιᾶι.", "st": "7.1.35"}, {"sp": "N", "t": "ἐπεὶ δὲ ἐξῆλθον, ὁ Ἀναξίβιος ἔκλεισε τὰς πύλας καὶ ἐκήρυξεν ὃς ἂν ἁλῶι ἔνδον ὢν τῶν στρατιωτῶν ὅτι πεπράσεται.", "st": "7.1.36"}, {"sp": "N", "t": "τῆι δ᾽ ὑστεραίαι Κοιρατάδας μὲν ἔχων τὰ ἱερεῖα καὶ τὸν μάντιν ἧκε καὶ ἄλφιτα φέροντες εἵποντο αὐτῶι εἴκοσιν ἄνδρες καὶ οἶνον ἄλλοι εἴκοσι καὶ ἐλαῶν τρεῖς καὶ σκορόδων ἀνὴρ ὅσον ἐδύνατο μέγιστον φορτίον καὶ ἄλλος κρομμύων. ταῦτα δὲ καταθέμενος ὡς ἐπὶ δάσμευσιν ἐθύετο.", "st": "7.1.37"}, {"sp": "N", "t": "Ξενοφῶν δὲ μεταπεμψάμενος Κλέανδρον ἐκέλευε διαπρᾶξαι ὅπως εἰς τὸ τεῖχος εἰσέλθοι καὶ ἀποπλεύσαι ἐκ Βυζαντίου.", "st": "7.1.38"}, {"sp": "N", "t": "ἐλθὼν δ᾽ ὁ Κλέανδρος, «μάλα μόλις, ἔφη, διαπραξάμενος ἥκω·» λέγειν γὰρ Ἀναξίβιον ὅτι οὐκ ἐπιτήδειον εἴη τοὺς μὲν στρατιώτας πλησίον εἶναι τοῦ τείχους, Ξενοφῶντα δὲ ἔνδον· τοὺς Βυζαντίους δὲ στασιάζειν καὶ πονηροὺς εἶναι πρὸς ἀλλήλους· «ὅμως δὲ εἰσιέναι, ἔφη, ἐκέλευεν, εἰ μέλλεις σὺν αὐτῶι ἐκπλεῖν.»", "st": "7.1.39"}, {"sp": "N", "t": "ὁ μὲν δὴ Ξενοφῶν ἀσπασάμενος τοὺς στρατιώτας εἴσω τοῦ τείχους ἀπήιει σὺν Κλεάνδρωι. ὁ δὲ Κοιρατάδας τῆι μὲν πρώτηι ἡμέραι οὐκ ἐκαλλιέρει οὐδὲ διεμέτρησεν οὐδὲν τοῖς στρατιώταις· τῆι δ᾽ ὑστεραίαι τὰ μὲν ἱερεῖα εἱστήκει παρὰ τὸν βωμὸν καὶ Κοιρατάδας ἐστεφανωμένος ὡς θύσων· προσελθὼν δὲ Τιμασίων ὁ Δαρδανεὺς καὶ Νέων ὁ Ἀσιναῖος καὶ Κλεάνωρ ὁ Ὀρχομένιος ἔλεγον Κοιρατάδαι μὴ θύειν, ὡς οὐχ ἡγησόμενον τῆι στρατιᾶι, εἰ μὴ δώσει τὰ ἐπιτήδεια.", "st": "7.1.40"}, {"sp": "N", "t": "ὁ δὲ κελεύει διαμετρεῖσθαι. ἐπεὶ δὲ πολλῶν ἐνέδει αὐτῶι ὥστε ἡμέρας σῖτον ἑκάστωι γενέσθαι τῶν στρατιωτῶν, ἀναλαβὼν τὰ ἱερεῖα ἀπήιει καὶ τὴν στρατηγίαν ἀπειπών.", "st": "7.1.41"}, {"sp": "N", "t": "Νέων δὲ ὁ Ἀσιναῖος καὶ Φρυνίσκος ὁ Ἀχαιὸς καὶ Φιλήσιος ὁ Ἀχαιὸς καὶ Ξανθικλῆς ὁ Ἀχαιὸς καὶ Τιμασίων ὁ Δαρδανεὺς ἐπέμενον ἐπὶ τῆι στρατιᾶι, καὶ εἰς κώμας τῶν Θραικῶν προελθόντες τὰς κατὰ Βυζάντιον ἐστρατοπεδεύοντο.", "st": "7.2.1"}, {"sp": "N", "t": "καὶ οἱ στρατηγοὶ ἐστασίαζον, Κλεάνωρ μὲν καὶ Φρυνίσκος πρὸς Σεύθην βουλόμενοι ἄγειν· ἔπειθε γὰρ αὐτούς, καὶ ἔδωκε τῶι μὲν ἵππον, τῶι δὲ γυναῖκα· Νέων δὲ εἰς Χερρόνησον, οἰόμενος, εἰ ὑπὸ Λακεδαιμονίοις γένοιντο, παντὸς ἂν προεστάναι τοῦ στρατεύματος· Τιμασίων δὲ προυθυμεῖτο πέραν εἰς τὴν Ἀσίαν πάλιν διαβῆναι, οἰόμενος ἂν οἴκαδε κατελθεῖν.", "st": "7.2.2"}, {"sp": "N", "t": "καὶ οἱ στρατιῶται ταὐτὰ ἐβούλοντο. διατριβομένου δὲ τοῦ χρόνου πολλοὶ τῶν στρατιωτῶν, οἱ μὲν τὰ ὅπλα ἀποδιδόμενοι κατὰ τοὺς χώρους ἀπέπλεον ὡς ἐδύναντο, οἱ δὲ καὶ εἰς τὰς πόλεις κατεμίγνυντο.", "st": "7.2.3"}, {"sp": "N", "t": "Ἀναξίβιος δ᾽ ἔχαιρε ταῦτα ἀκούων, διαφθειρόμενον τὸ στράτευμα· τούτων γὰρ γιγνομένων ὤιετο μάλιστα χαρίζεσθαι Φαρναβάζωι.", "st": "7.2.4"}, {"sp": "N", "t": "ἀποπλέοντι δὲ Ἀναξιβίωι ἐκ Βυζαντίου συναντᾶι Ἀρίσταρχος ἐν Κυζίκωι διάδοχος Κλεάνδρωι Βυζαντίου ἁρμοστής· ἐλέγετο δὲ ὅτι καὶ ναύαρχος διάδοχος Πῶλος ὅσον οὐ παρείη ἤδη εἰς Ἑλλήσποντον.", "st": "7.2.5"}, {"sp": "N", "t": "καὶ Ἀναξίβιος τῶι μὲν Ἀριστάρχωι ἐπιστέλλει ὁπόσους ἂν εὕρηι ἐν Βυζαντίωι τῶν Κύρου στρατιωτῶν ὑπολελειμμένους ἀποδόσθαι· ὁ δὲ Κλέανδρος οὐδένα ἐπεπράκει, ἀλλὰ καὶ τοὺς κάμνοντας ἐθεράπευεν οἰκτίρων καὶ ἀναγκάζων οἰκίαι δέχεσθαι· Ἀρίσταρχος δ᾽ ἐπεὶ ἦλθε τάχιστα, οὐκ ἐλάττους τετρακοσίων ἀπέδοτο.", "st": "7.2.6"}, {"sp": "N", "t": "Ἀναξίβιος δὲ παραπλεύσας εἰς Πάριον πέμπει παρὰ Φαρνάβαζον κατὰ τὰ συγκείμενα. ὁ δ᾽ ἐπεὶ ἤισθετο Ἀρίσταρχόν τε ἥκοντα εἰς Βυζάντιον ἁρμοστὴν καὶ Ἀναξίβιον οὐκέτι ναυαρχοῦντα, Ἀναξιβίου μὲν ἠμέλησε, πρὸς Ἀρίσταρχον δὲ διεπράττετο τὰ αὐτὰ περὶ τοῦ Κύρου στρατεύματος ἅπερ πρὸς Ἀναξίβιον.", "st": "7.2.7"}, {"sp": "N", "t": "ἐκ τούτου ὁ Ἀναξίβιος καλέσας Ξενοφῶντα κελεύει πάσηι τέχνηι καὶ μηχανῆι πλεῦσαι ἐπὶ τὸ στράτευμα ὡς τάχιστα, καὶ συνέχειν τε αὐτὸ καὶ συναθροίζειν τῶν διεσπαρμένων ὡς ἂν πλείστους δύνηται, καὶ παραγαγόντα εἰς τὴν Πέρινθον διαβιβάζειν εἰς τὴν Ἀσίαν ὅτι τάχιστα· καὶ δίδωσιν αὐτῶι τριακόντορον καὶ ἐπιστολὴν καὶ ἄνδρα συμπέμπει κελεύσοντα τοὺς Περινθίους ὡς τάχιστα Ξενοφῶντα προπέμψαι τοῖς ἵπποις ἐπὶ τὸ στράτευμα.", "st": "7.2.8"}, {"sp": "N", "t": "καὶ ὁ μὲν Ξενοφῶν διαπλεύσας ἀφικνεῖται ἐπὶ τὸ στράτευμα· οἱ δὲ στρατιῶται ἐδέξαντο ἡδέως καὶ εὐθὺς εἵποντο ἄσμενοι ὡς διαβησόμενοι ἐκ τῆς Θράικης εἰς τὴν Ἀσίαν.", "st": "7.2.9"}, {"sp": "N", "t": "ὁ δὲ Σεύθης ἀκούσας ἥκοντα πάλιν πέμψας πρὸς αὐτὸν κατὰ θάλατταν Μηδοσάδην ἐδεῖτο τὴν στρατιὰν ἄγειν πρὸς ἑαυτόν, ὑπισχνούμενος αὐτῶι ὅ τι ὤιετο λέγων πείσειν. ὁ δ᾽ ἀπεκρίνατο ὅτι οὐδὲν οἷόν τε εἴη τούτων γενέσθαι. καὶ ὁ μὲν ταῦτα ἀκούσας ὤιχετο.", "st": "7.2.10"}, {"sp": "N", "t": "οἱ δὲ Ἕλληνες ἐπεὶ ἀφίκοντο εἰς Πέρινθον, Νέων μὲν ἀποσπάσας ἐστρατοπεδεύσατο χωρὶς ἔχων ὡς ὀκτακοσίους ἀνθρώπους· τὸ δ᾽ ἄλλο στράτευμα πᾶν ἐν τῶι αὐτῶι παρὰ τὸ τεῖχος τὸ Περινθίων ἦν.", "st": "7.2.11"}, {"sp": "N", "t": "μετὰ ταῦτα Ξενοφῶν μὲν ἔπραττε περὶ πλοίων, ὅπως ὅτι τάχιστα διαβαῖεν. ἐν δὲ τούτωι ἀφικόμενος Ἀρίσταρχος ⟨ὁ⟩ ἐκ Βυζαντίου ἁρμοστής, ἔχων δύο τριήρεις, πεπεισμένος ὑπὸ Φαρναβάζου τοῖς τε ναυκλήροις ἀπεῖπε μὴ διάγειν ἐλθών τε ἐπὶ τὸ στράτευμα τοῖς στρατιώταις εἶπε μὴ περαιοῦσθαι εἰς τὴν Ἀσίαν.", "st": "7.2.12"}, {"sp": "N", "t": "ὁ δὲ Ξενοφῶν ἔλεγεν ὅτι Ἀναξίβιος ἐκέλευσε καὶ ἐμὲ πρὸς τοῦτο ἔπεμψεν ἐνθάδε. πάλιν δ᾽ Ἀρίσταρχος ἔλεξεν· Ἀναξίβιος μὲν τοίνυν οὐκέτι ναύαρχος, ἐγὼ δὲ τῆιδε ἁρμοστής· εἰ δέ τινα ὑμῶν λήψομαι ἐν τῆι θαλάττηι, καταδύσω. ταῦτ᾽ εἰπὼν ὤιχετο εἰς τὸ τεῖχος. τῆι δ᾽ ὑστεραίαι μεταπέμπεται τοὺς στρατηγοὺς καὶ λοχαγοὺς τοῦ στρατεύματος.", "st": "7.2.13"}, {"sp": "N", "t": "ἤδη δὲ ὄντων πρὸς τῶι τείχει ἐξαγγέλλει τις τῶι Ξενοφῶντι ὅτι εἰ εἴσεισι, συλληφθήσεται καὶ ἢ αὐτοῦ τι πείσεται ἢ καὶ Φαρναβάζωι παραδοθήσεται. ὁ δὲ ἀκούσας ταῦτα τοὺς μὲν προπέμπεται, αὐτὸς δὲ εἶπεν ὅτι θῦσαί τι βούλοιτο.", "st": "7.2.14"}, {"sp": "N", "t": "καὶ ἀπελθὼν ἐθύετο εἰ παρεῖεν αὐτῶι οἱ θεοὶ πειρᾶσθαι πρὸς Σεύθην ἄγειν τὸ στράτευμα. ἑώρα γὰρ οὔτε διαβαίνειν ἀσφαλὲς ὂν τριήρεις ἔχοντος τοῦ κωλύσοντος, οὔτ᾽ ἐπὶ Χερρόνησον ἐλθὼν κατακλεισθῆναι ἐβούλετο καὶ τὸ στράτευμα ἐν πολλῆι σπάνει πάντων γενέσθαι ἔνθα πείθεσθαι μὲν ἀνάγκη τῶι ἐκεῖ ἁρμοστῆι, τῶν δὲ ἐπιτηδείων οὐδὲν ἔμελλεν ἕξειν τὸ στράτευμα.", "st": "7.2.15"}, {"sp": "N", "t": "καὶ ὁ μὲν ἀμφὶ ταῦτ᾽ εἶχεν· οἱ δὲ στρατηγοὶ καὶ οἱ λοχαγοὶ ἥκοντες παρὰ τοῦ Ἀριστάρχου ἀπήγγελλον ὅτι νῦν μὲν ἀπιέναι σφᾶς κελεύει, τῆς δείλης δὲ ἥκειν· ἔνθα καὶ δήλη μᾶλλον ἐδόκει ἡ ἐπιβουλή.", "st": "7.2.16"}, {"sp": "N", "t": "ὁ οὖν Ξενοφῶν, ἐπεὶ ἐδόκει τὰ ἱερὰ καλὰ εἶναι αὐτῶι καὶ τῶι στρατεύματι ἀσφαλῶς πρὸς Σεύθην ἰέναι, παραλαβὼν Πολυκράτην τὸν Ἀθηναῖον λοχαγὸν καὶ παρὰ τῶν στρατηγῶν ἑκάστου ἄνδρα πλὴν παρὰ Νέωνος ὧι ἕκαστος ἐπίστευεν ὤιχετο τῆς νυκτὸς ἐπὶ τὸ Σεύθου στράτευμα ἑξήκοντα στάδια.", "st": "7.2.17"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἐγγὺς ἦσαν αὐτοῦ, ἐπιτυγχάνει πυροῖς ἐρήμοις. καὶ τὸ μὲν πρῶτον ὤιετο μετακεχωρηκέναι ποι τὸν Σεύθην· ἐπεὶ δὲ θορύβου τε ἤισθετο καὶ σημαινόντων ἀλλήλοις τῶν περὶ Σεύθην, κατέμαθεν ὅτι τούτου ἕνεκα τὰ πυρὰ κεκαυμένα εἴη τῶι Σεύθηι πρὸ τῶν νυκτοφυλάκων, ὅπως οἱ μὲν φύλακες μὴ ὁρῶιντο ἐν τῶι σκότει ὄντες μήτε ὁπόσοι μήτε ὅπου εἶεν, οἱ δὲ προσιόντες μὴ λανθάνοιεν, ἀλλὰ διὰ τὸ φῶς καταφανεῖς εἶεν·", "st": "7.2.18"}, {"sp": "N", "t": "ἐπεὶ δὲ ἤισθετο, προπέμπει τὸν ἑρμηνέα ὃν ἐτύγχανεν ἔχων, καὶ εἰπεῖν κελεύει Σεύθηι ὅτι Ξενοφῶν πάρεστι βουλόμενος συγγενέσθαι αὐτῶι. οἱ δὲ ἤροντο εἰ ὁ Ἀθηναῖος ὁ ἀπὸ τοῦ στρατεύματος.", "st": "7.2.19"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἔφη οὗτος εἶναι, ἀναπηδήσαντες ἐδίωκον· καὶ ὀλίγον ὕστερον παρῆσαν πελτασταὶ ὅσον διακόσιοι, καὶ παραλαβόντες Ξενοφῶντα καὶ τοὺς σὺν αὐτῶι ἦγον πρὸς Σεύθην.", "st": "7.2.20"}, {"sp": "N", "t": "ὁ δ᾽ ἦν ἐν τύρσει μάλα φυλαττόμενος, καὶ ἵπποι περὶ αὐτὴν κύκλωι ἐγκεχαλινωμένοι· διὰ γὰρ τὸν φόβον τὰς μὲν ἡμέρας ἐχίλου τοὺς ἵππους, τὰς δὲ νύκτας ἐγκεχαλινωμένοις ἐφυλάττετο.", "st": "7.2.21"}, {"sp": "N", "t": "ἐλέγετο γὰρ καὶ πρόσθεν Τήρης ὁ τούτου πρόγονος ἐν ταύτηι τῆι χώραι πολὺ ἔχων στράτευμα ὑπὸ τούτων τῶν ἀνδρῶν πολλοὺς ἀπολέσαι καὶ τὰ σκευοφόρα ἀφαιρεθῆναι· ἦσαν δ᾽ οὗτοι Θυνοί, πάντων λεγόμενοι εἶναι μάλιστα νυκτὸς πολεμικώτατοι.", "st": "7.2.22"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἐγγὺς ἦσαν, ἐκέλευσεν εἰσελθεῖν Ξενοφῶντα ἔχοντα δύο οὓς βούλοιτο. ἐπειδὴ δ᾽ ἔνδον ἦσαν, ἠσπάζοντο μὲν πρῶτον ἀλλήλους καὶ κατὰ τὸν Θράικιον νόμον κέρατα οἴνου προύπινον· παρῆν δὲ καὶ Μηδοσάδης τῶι Σεύθηι, ὅσπερ ἐπρέσβευεν αὐτῶι πάντοσε.", "st": "7.2.23"}, {"sp": "N", "t": "ἔπειτα δὲ Ξενοφῶν ἤρχετο λέγειν· «ἔπεμψας πρὸς ἐμέ, ὦ Σεύθη, εἰς Καλχηδόνα πρῶτον Μηδοσάδην τουτονί, δεόμενός μου συμπροθυμηθῆναι διαβῆναι τὸ στράτευμα ἐκ τῆς Ἀσίας, καὶ ὑπισχνούμενός μοι, εἰ ταῦτα πράξαιμι, εὖ ποιήσειν, ὡς ἔφη Μηδοσάδης οὗτος.»", "st": "7.2.24"}, {"sp": "N", "t": "ταῦτα εἰπὼν ἐπήρετο τὸν Μηδοσάδην εἰ ἀληθῆ ταῦτα εἴη. ὁ δ᾽ ἔφη. «αὖθις ἦλθε Μηδοσάδης οὗτος ἐπεὶ ἐγὼ διέβην πάλιν ἐπὶ τὸ στράτευμα ἐκ Παρίου, ὑπισχνούμενος, εἰ ἄγοιμι τὸ στράτευμα πρὸς σέ, τἆλλα τέ σε φίλωι μοι χρήσεσθαι καὶ ἀδελφῶι καὶ τὰ παρὰ θαλάττηι μοι χωρία ὧν σὺ κρατεῖς ἔσεσθαι παρὰ σοῦ.»", "st": "7.2.25"}, {"sp": "N", "t": "ἐπὶ τούτοις πάλιν ἤρετο τὸν Μηδοσάδην εἰ ἔλεγε ταῦτα. ὁ δὲ συνέφη καὶ ταῦτα. «ἴθι νυν, ἔφη, ἀφήγησαι τούτωι τί σοι ἀπεκρινάμην ἐν Καλχηδόνι πρῶτον.»", "st": "7.2.26"}, {"sp": "N", "t": "«ἀπεκρίνω ὅτι τὸ στράτευμα διαβήσοιτο εἰς Βυζάντιον καὶ οὐδὲν τούτου ἕνεκα δέοι τελεῖν οὔτε σοὶ οὔτε ἄλλωι· αὐτὸς δὲ ἐπεὶ διαβαίης, ἀπιέναι ἔφησθα· καὶ ἐγένετο οὕτως ὥσπερ σὺ ἔλεγες.»", "st": "7.2.27"}, {"sp": "N", "t": "«τί γὰρ ἔλεγον, ἔφη, ὅτε κατὰ Σηλυμβρίαν ἀφίκου;» «οὐκ ἔφησθα οἷόν τε εἶναι, ἀλλ᾽ εἰς Πέρινθον ἐλθόντας διαβαίνειν εἰς τὴν Ἀσίαν.»", "st": "7.2.28"}, {"sp": "N", "t": "«νῦν τοίνυν, ἔφη ὁ Ξενοφῶν, πάρειμι καὶ ἐγὼ καὶ οὗτος Φρυνίσκος εἷς τῶν στρατηγῶν καὶ Πολυκράτης οὗτος εἷς τῶν λοχαγῶν, καὶ ἔξω εἰσὶν ἀπὸ τῶν στρατηγῶν ὁ πιστότατος ἑκάστωι πλὴν Νέωνος τοῦ Λακωνικοῦ.", "st": "7.2.29"}, {"sp": "N", "t": "εἰ οὖν βούλει πιστοτέραν εἶναι τὴν πρᾶξιν, καὶ ἐκείνους κάλεσαι. τὰ δὲ ὅπλα σὺ ἐλθὼν εἰπέ, ὦ Πολύκρατες, ὅτι ἐγὼ κελεύω καταλιπεῖν, καὶ αὐτὸς ἐκεῖ καταλιπὼν τὴν μάχαιραν εἴσιθι.»", "st": "7.2.30"}, {"sp": "N", "t": "ἀκούσας ταῦτα ὁ Σεύθης εἶπεν ὅτι οὐδενὶ ἂν ἀπιστήσειεν Ἀθηναίων· καὶ γὰρ ὅτι συγγενεῖς εἶεν εἰδέναι καὶ φίλους εὔνους ἔφη νομίζειν. μετὰ ταῦτα δ᾽ ἐπεὶ εἰσῆλθον οὓς ἔδει, πρῶτον Ξενοφῶν ἐπήρετο Σεύθην ὅ τι δέοιτο χρῆσθαι τῆι στρατιᾶι.", "st": "7.2.31"}, {"sp": "N", "t": "ὁ δὲ εἶπεν ὧδε. Μαισάδης ἦν πατήρ μοι, ἐκείνου δὲ ἦν ἀρχὴ Μελανδῖται καὶ Θυνοὶ καὶ Τρανίψαι. ἐκ ταύτης οὖν τῆς χώρας, ἐπεὶ τὰ Ὀδρυσῶν πράγματα ἐνόσησεν, ἐκπεσὼν ὁ πατὴρ αὐτὸς μὲν ἀποθνήισκει νόσωι, ἐγὼ δ᾽ ἐξετράφην ὀρφανὸς παρὰ Μηδόκωι τῶι νῦν βασιλεῖ.", "st": "7.2.32"}, {"sp": "N", "t": "ἐπεὶ δὲ νεανίσκος ἐγενόμην, οὐκ ἐδυνάμην ζῆν εἰς ἀλλοτρίαν τράπεζαν ἀποβλέπων· καὶ ἐκαθεζόμην ἐνδίφριος αὐτῶι ἱκέτης δοῦναί μοι ὁπόσους δυνατὸς εἴη ἄνδρας, ὅπως καὶ τοὺς ἐκβαλόντας ἡμᾶς εἴ τι δυναίμην κακὸν ποιοίην καὶ ζώιην μὴ εἰς τὴν ἐκείνου τράπεζαν ἀποβλέπων.", "st": "7.2.33"}, {"sp": "N", "t": "ἐκ τούτου μοι δίδωσι τοὺς ἄνδρας καὶ τοὺς ἵππους οὓς ὑμεῖς ὄψεσθε ἐπειδὰν ἡμέρα γένηται. καὶ νῦν ἐγὼ ζῶ τούτους ἔχων, ληιζόμενος τὴν ἐμαυτοῦ πατρώιαν χώραν. εἰ δέ μοι ὑμεῖς παραγένοισθε, οἶμαι ἂν σὺν τοῖς θεοῖς ῥαιδίως ἀπολαβεῖν τὴν ἀρχήν. ταῦτ᾽ ἐστὶν ἃ ἐγὼ δέομαι.", "st": "7.2.34"}, {"sp": "N", "t": "«τί ἂν οὖν, ἔφη ὁ Ξενοφῶν, σὺ δύναιο, εἰ ἔλθοιμεν, τῆι τε στρατιᾶι διδόναι καὶ τοῖς λοχαγοῖς καὶ τοῖς στρατηγοῖς;»", "st": "7.2.35"}, {"sp": "N", "t": "λέξον, ἵνα οὗτοι ἀπαγγέλλωσιν. ὁ δ᾽ ὑπέσχετο τῶι μὲν στρατιώτηι κυζικηνόν, τῶι δὲ λοχαγῶι διμοιρίαν, τῶι δὲ στρατηγῶι τετραμοιρίαν, καὶ γῆν ὁπόσην ἂν βούλωνται καὶ ζεύγη καὶ χωρίον ἐπὶ θαλάττηι τετειχισμένον.", "st": "7.2.36"}, {"sp": "N", "t": "«ἐὰν δέ, ἔφη ὁ Ξενοφῶν, ταῦτα πειρώμενοι μὴ διαπράξωμεν, ἀλλά τις φόβος ἀπὸ Λακεδαιμονίων ἦι, δέξηι εἰς τὴν σεαυτοῦ, ἐάν τις ἀπιέναι βούληται παρὰ σέ;»", "st": "7.2.37"}, {"sp": "N", "t": "ὁ δ᾽ εἶπε· «καὶ ἀδελφούς γε ποιήσομαι καὶ ἐνδιφρίους καὶ κοινωνοὺς ἁπάντων ὧν ἂν δυνώμεθα κτᾶσθαι. σοὶ δέ, ὦ Ξενοφῶν, καὶ θυγατέρα δώσω καὶ εἴ τις σοὶ ἔστι θυγάτηρ, ὠνήσομαι Θραικίωι νόμωι, καὶ Βισάνθην οἴκησιν δώσω, ὅπερ ἐμοὶ κάλλιστον χωρίον ἐστὶ τῶν ἐπὶ θαλάττηι.»", "st": "7.2.38"}, {"sp": "N", "t": "ἀκούσαντες ταῦτα καὶ δεξιὰς δόντες καὶ λαβόντες ἀπήλαυνον· καὶ πρὸ ἡμέρας ἐγένοντο ἐπὶ στρατοπέδωι καὶ ἀπήγγειλαν ἕκαστοι τοῖς πέμψασιν.", "st": "7.3.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ἡμέρα ἐγένετο, ὁ μὲν Ἀρίσταρχος πάλιν ἐκάλει τοὺς στρατηγούς· τοῖς δ᾽ ἔδοξε τὴν μὲν πρὸς Ἀρίσταρχον ὁδὸν ἐᾶσαι, τὸ δὲ στράτευμα συγκαλέσαι. καὶ συνῆλθον πάντες πλὴν οἱ Νέωνος· οὗτοι δὲ ἀπεῖχον ὡς δέκα στάδια.", "st": "7.3.2"}, {"sp": "N", "t": "ἐπεὶ δὲ συνῆλθον, ἀναστὰς Ξενοφῶν εἶπε τάδε. «ἄνδρες, διαπλεῖν μὲν ἔνθα βουλόμεθα Ἀρίσταρχος τριήρεις ἔχων κωλύει· ὥστε εἰς πλοῖα οὐκ ἀσφαλὲς ἐμβαίνειν· οὗτος δὲ αὑτὸς κελεύει εἰς Χερρόνησον βίαι διὰ τοῦ ἱεροῦ ὄρους πορεύεσθαι· ἢν δὲ κρατήσαντες τούτου ἐκεῖσε ἔλθωμεν, οὔτε πωλήσειν ἔτι ὑμᾶς φησιν ὥσπερ ἐν Βυζαντίωι, οὔτε ἐξαπατήσεσθαι ἔτι ὑμᾶς, ἀλλὰ λήψεσθαι μισθόν, οὔτε περιόψεσθαι ἔτι ὥσπερ νυνὶ δεομένους τῶν ἐπιτηδείων.", "st": "7.3.3"}, {"sp": "N", "t": "οὗτος μὲν ταῦτα λέγει· Σεύθης δέ φησιν, ἂν πρὸς ἐκεῖνον ἴητε, εὖ ποιήσειν ὑμᾶς. νῦν οὖν σκέψασθε πότερον ἐνθάδε μένοντες τοῦτο βουλεύσεσθε ἢ εἰς τὰ ἐπιτήδεια ἐπανελθόντες.", "st": "7.3.4"}, {"sp": "N", "t": "ἐμοὶ μὲν οὖν δοκεῖ, ἐπεὶ ἐνθάδε οὔτε ἀργύριον ἔχομεν ὥστε ἀγοράζειν οὔτε ἄνευ ἀργυρίου ἐῶσι λαμβάνειν, ἐπανελθόντας εἰς τὰς κώμας ὅθεν οἱ ἥττους ἐῶσι λαμβάνειν, ἐκεῖ ἔχοντας τὰ ἐπιτήδεια ἀκούοντας ὅ τι τις ἡμῶν δεῖται, αἱρεῖσθαι ὅ τι ἂν ἡμῖν δοκῆι κράτιστον εἶναι.", "st": "7.3.5"}, {"sp": "N", "t": "καὶ ὅτωι γε, ἔφη, ταῦτα δοκεῖ, ἀράτω τὴν χεῖρα.» ἀνέτειναν ἅπαντες. «ἀπιόντες τοίνυν, ἔφη, συσκευάζεσθε, καὶ ἐπειδὰν παραγγέλληι τις, ἕπεσθε τῶι ἡγουμένωι.»", "st": "7.3.6"}, {"sp": "N", "t": "μετὰ ταῦτα Ξενοφῶν μὲν ἡγεῖτο, οἱ δ᾽ εἵποντο. Νέων δὲ καὶ παρ᾽ Ἀριστάρχου ἄλλοι ἔπειθον ἀποτρέπεσθαι· οἱ δ᾽ οὐχ ὑπήκουον. ἐπεὶ δ᾽ ὅσον τριάκοντα στάδια προεληλύθεσαν, ἀπαντᾶι Σεύθης. καὶ ὁ Ξενοφῶν ἰδὼν αὐτὸν προσελάσαι ἐκέλευσεν, ὅπως ὅτι πλείστων ἀκουόντων εἴποι αὐτῶι ἃ ἐδόκει συμφέρειν.", "st": "7.3.7"}, {"sp": "N", "t": "ἐπεὶ δὲ προσῆλθεν, εἶπε Ξενοφῶν· «ἡμεῖς πορευόμεθα ὅπου μέλλει ἕξειν τὸ στράτευμα τροφήν· ἐκεῖ δ᾽ ἀκούοντες καὶ σοῦ καὶ τῶν τοῦ Λακωνικοῦ αἱρησόμεθα ἃ ἂν κράτιστα δοκῆι εἶναι. ἢν οὖν ἡμῖν ἡγήσηι ὅπου πλεῖστά ἐστιν ἐπιτήδεια, ὑπὸ σοῦ νομιοῦμεν ξενίζεσθαι.»", "st": "7.3.8"}, {"sp": "N", "t": "καὶ ὁ Σεύθης ἔφη· «ἀλλὰ οἶδα κώμας πολλὰς ἁθρόας καὶ πάντα ἐχούσας τὰ ἐπιτήδεια ἀπεχούσας ἡμῶν ὅσον διελθόντες ἂν ἡδέως ἀριστώιητε.»", "st": "7.3.9"}, {"sp": "N", "t": "«ἡγοῦ τοίνυν,» ἔφη ὁ Ξενοφῶν. ἐπεὶ δ᾽ ἀφίκοντο εἰς αὐτὰς τῆς δείλης, συνῆλθον οἱ στρατιῶται, καὶ εἶπε Σεύθης τοιάδε. «ἐγώ, ὦ ἄνδρες, δέομαι ὑμῶν στρατεύεσθαι σὺν ἐμοί, καὶ ὑπισχνοῦμαι ὑμῖν δώσειν τοῖς στρατιώταις κυζικηνόν, λοχαγοῖς δὲ καὶ στρατηγοῖς τὰ νομιζόμενα· ἔξω δὲ τούτων τὸν ἄξιον τιμήσω. σῖτα δὲ καὶ ποτὰ ὥσπερ καὶ νῦν ἐκ τῆς χώρας λαμβάνοντες ἕξετε· ὁπόσα δ᾽ ἂν ἁλίσκηται ἀξιώσω αὐτὸς ἔχειν, ἵνα ταῦτα διατιθέμενος ὑμῖν τὸν μισθὸν πορίζω.", "st": "7.3.10"}, {"sp": "N", "t": "καὶ τὰ μὲν φεύγοντα καὶ ἀποδιδράσκοντα ἡμεῖς ἱκανοὶ ἐσόμεθα διώκειν καὶ μαστεύειν· ἂν δέ τις ἀνθιστῆται, σὺν ὑμῖν πειρασόμεθα χειροῦσθαι.»", "st": "7.3.11"}, {"sp": "N", "t": "ἐπήρετο ὁ Ξενοφῶν· «πόσον δὲ ἀπὸ θαλάττης ἀξιώσεις συνέπεσθαί σοι τὸ στράτευμα;» ὁ δ᾽ ἀπεκρίνατο· «οὐδαμῆι πλεῖον ἑπτὰ ἡμερῶν, μεῖον δὲ πολλαχῆι.»", "st": "7.3.12"}, {"sp": "N", "t": "μετὰ ταῦτα ἐδίδοτο λέγειν τῶι βουλομένωι· καὶ ἔλεγον πολλοὶ κατὰ ταὐτὰ ὅτι παντὸς ἄξια λέγει Σεύθης· χειμὼν γὰρ εἴη καὶ οὔτε οἴκαδε ἀποπλεῖν τῶι τοῦτο βουλομένωι δυνατὸν εἴη, διαγενέσθαι τε ἐν φιλίαι οὐχ οἷόν τε, εἰ δέοι ὠνουμένους ζῆν, ἐν δὲ τῆι πολεμίαι διατρίβειν καὶ τρέφεσθαι ἀσφαλέστερον μετὰ Σεύθου ἢ μόνους, ὄντων ἀγαθῶν τοσούτων. εἰ δὲ μισθὸν προσλήψοιντο, εὕρημα ἐδόκει εἶναι.", "st": "7.3.13"}, {"sp": "N", "t": "ἐπὶ τούτοις εἶπεν ὁ Ξενοφῶν· «εἴ τις ἀντιλέγει, λεγέτω· εἰ δὲ μή, ἐπιψηφιῶ ταῦτα.» ἐπεὶ δὲ οὐδεὶς ἀντέλεγεν, ἐπεψήφισε, καὶ ἔδοξε ταῦτα. εὐθὺς δὲ Σεύθηι εἶπεν, ὅτι συστρατεύσοιντο αὐτῶι.", "st": "7.3.14"}, {"sp": "N", "t": "μετὰ τοῦτο οἱ μὲν ἄλλοι κατὰ τάξεις ἐσκήνησαν, στρατηγοὺς δὲ καὶ λοχαγοὺς ἐπὶ δεῖπνον Σεύθης ἐκάλεσε, πλησίον κώμην ἔχων.", "st": "7.3.15"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἐπὶ θύραις ἦσαν ὡς ἐπὶ δεῖπνον παριόντες, ἦν τις Ἡρακλείδης Μαρωνείτης· οὗτος προσιὼν ἑνὶ ἑκάστωι οὕστινας ὤιετο ἔχειν τι δοῦναι Σεύθηι, πρῶτον μὲν πρὸς Παριανούς τινας, οἳ παρῆσαν φιλίαν διαπραξόμενοι πρὸς Μήδοκον τὸν Ὀδρυσῶν βασιλέα καὶ δῶρα ἄγοντες αὐτῶι τε καὶ τῆι γυναικί, ἔλεγεν ὅτι Μήδοκος μὲν ἄνω εἴη δώδεκα ἡμερῶν ἀπὸ θαλάττης ὁδόν, Σεύθης δ᾽ ἐπεὶ τὸ στράτευμα τοῦτο εἴληφεν, ἄρχων ἔσοιτο ἐπὶ θαλάττηι.", "st": "7.3.16"}, {"sp": "N", "t": "γείτων οὖν ὢν ἱκανώτατος ἔσται ὑμᾶς καὶ εὖ καὶ κακῶς ποιεῖν. ἢν οὖν σωφρονῆτε, τούτωι δώσετε ὅ τι ἄγετε· καὶ ἄμεινον ὑμῖν διακείσεται ἢ ἐὰν Μηδόκωι τῶι πρόσω οἰκοῦντι διδῶτε.", "st": "7.3.17"}, {"sp": "N", "t": "τούτους μὲν οὖν οὕτως ἔπειθεν. αὖθις δὲ Τιμασίωνι τῶι Δαρδανεῖ προσελθών, ἐπεὶ ἤκουσεν αὐτῶι εἶναι καὶ ἐκπώματα καὶ τάπιδας βαρβαρικάς, ἔλεγεν ὅτι νομίζοιτο ὁπότε ἐπὶ δεῖπνον καλέσαι Σεύθης δωρεῖσθαι αὐτῶι τοὺς κληθέντας. οὗτος δ᾽ ἢν μέγας ἐνθάδε γένηται, ἱκανὸς ἔσται σε καὶ οἴκαδε καταγαγεῖν καὶ ἐνθάδε πλούσιον ποιῆσαι. τοιαῦτα προυμνᾶτο ἑκάστωι προσιών.", "st": "7.3.18"}, {"sp": "N", "t": "προσελθὼν δὲ καὶ Ξενοφῶντι ἔλεγε· «σὺ καὶ πόλεως μεγίστης εἶ καὶ παρὰ Σεύθηι τὸ σὸν ὄνομα μέγιστόν ἐστι, καὶ ἐν τῆιδε τῆι χώραι ἴσως ἀξιώσεις καὶ τείχη λαμβάνειν, ὥσπερ καὶ ἄλλοι τῶν ὑμετέρων ἔλαβον, καὶ χώραν· ἄξιον οὖν σοι καὶ μεγαλοπρεπέστατα τιμῆσαι Σεύθην.", "st": "7.3.19"}, {"sp": "N", "t": "εὔνους δέ σοι ὢν παραινῶ· εὖ οἶδα γὰρ ὅτι ὅσωι ἂν μείζω τούτωι δωρήσηι, τοσούτωι μείζω ὑπὸ τούτου ἀγαθὰ πείσηι.» ἀκούων ταῦτα Ξενοφῶν ἠπόρει· οὐ γὰρ διεβεβήκει ἔχων ἐκ Παρίου εἰ μὴ παῖδα καὶ ὅσον ἐφόδιον.", "st": "7.3.20"}, {"sp": "N", "t": "ἐπεὶ δὲ εἰσῆλθον ἐπὶ τὸ δεῖπνον τῶν τε Θραικῶν οἱ κράτιστοι τῶν παρόντων καὶ οἱ στρατηγοὶ καὶ οἱ λοχαγοὶ τῶν Ἑλλήνων καὶ εἴ τις πρεσβεία παρῆν ἀπὸ πόλεως, τὸ δεῖπνον μὲν ἦν καθημένοις κύκλωι· ἔπειτα δὲ τρίποδες εἰσηνέχθησαν πᾶσιν· οὗτοι δ᾽ ἦσαν κρεῶν μεστοὶ νενεμημένων, καὶ ἄρτοι ζυμῖται μεγάλοι προσπεπερονημένοι ἦσαν πρὸς τοῖς κρέασι.", "st": "7.3.21"}, {"sp": "N", "t": "μάλιστα δ᾽ αἱ τράπεζαι κατὰ τοὺς ξένους αἰεὶ ἐτίθεντο· νόμος γὰρ ἦν – — καὶ πρῶτος τοῦτο ἐποίει Σεύθης, καὶ ἀνελόμενος τοὺς ἑαυτῶι παρακειμένους ἄρτους διέκλα κατὰ μικρὸν καὶ ἐρρίπτει οἷς αὐτῶι ἐδόκει, καὶ τὰ κρέα ὡσαύτως, ὅσον μόνον γεύσασθαι ἑαυτῶι καταλιπών.", "st": "7.3.22"}, {"sp": "N", "t": "καὶ οἱ ἄλλοι δὲ κατὰ ταὐτὰ ἐποίουν καθ᾽ οὓς αἱ τράπεζαι ἔκειντο. Ἀρκὰς δέ τις Ἀρύστας ὄνομα, φαγεῖν δεινός, τὸ μὲν διαρριπτεῖν εἴα χαίρειν, λαβὼν δὲ εἰς τὴν χεῖρα ὅσον τριχοίνικον ἄρτον καὶ κρέα θέμενος ἐπὶ τὰ γόνατα ἐδείπνει.", "st": "7.3.23"}, {"sp": "N", "t": "κέρατα δὲ οἴνου περιέφερον, καὶ πάντες ἐδέχοντο· ὁ δ᾽ Ἀρύστας, ἐπεὶ παρ᾽ αὐτὸν φέρων τὸ κέρας ὁ οἰνοχόος ἧκεν, εἶπεν ἰδὼν τὸν Ξενοφῶντα οὐκέτι δειπνοῦντα, «ἐκείνωι, ἔφη, δός·", "st": "7.3.24"}, {"sp": "N", "t": "σχολάζει γὰρ ἤδη, ἐγὼ δὲ οὐδέπω.» ἀκούσας Σεύθης τὴν φωνὴν ἠρώτα τὸν οἰνοχόον τί λέγει. ὁ δὲ οἰνοχόος εἶπεν· ἑλληνίζειν γὰρ ἠπίστατο. ἐνταῦθα μὲν δὴ γέλως ἐγένετο.", "st": "7.3.25"}, {"sp": "N", "t": "ἐπειδὴ δὲ προυχώρει ὁ πότος, εἰσῆλθεν ἀνὴρ Θρᾶιξ ἵππον ἔχων λευκόν, καὶ λαβὼν κέρας μεστὸν εἶπε· «προπίνω σοι, ὦ Σεύθη, καὶ τὸν ἵππον τοῦτον δωροῦμαι, ἐφ᾽ οὗ καὶ διώκων ὃν ἂν θέληις αἱρήσεις καὶ ἀποχωρῶν οὐ μὴ δείσηις τὸν πολέμιον.»", "st": "7.3.26"}, {"sp": "N", "t": "ἄλλος παῖδα εἰσάγων οὕτως ἐδωρήσατο προπίνων, καὶ ἄλλος ἱμάτια τῆι γυναικί. καὶ Τιμασίων προπίνων ἐδωρήσατο φιάλην τε ἀργυρᾶν καὶ τάπιδα ἀξίαν δέκα μνῶν.", "st": "7.3.27"}, {"sp": "N", "t": "Γνήσιππος δέ τις Ἀθηναῖος ἀναστὰς εἶπεν ὅτι ἀρχαῖος εἴη νόμος κάλλιστος τοὺς μὲν ἔχοντας διδόναι τῶι βασιλεῖ τιμῆς ἕνεκα, τοῖς δὲ μὴ ἔχουσι διδόναι τὸν βασιλέα, ἵνα καὶ ἐγώ, ἔφη, ἔχω σοι δωρεῖσθαι καὶ τιμᾶν.", "st": "7.3.28"}, {"sp": "N", "t": "ὁ δὲ Ξενοφῶν ἠπορεῖτο τί ποιήσει· καὶ γὰρ ἐτύγχανεν ὡς τιμώμενος ἐν τῶι πλησιαιτάτωι δίφρωι Σεύθηι καθήμενος. ὁ δὲ Ἡρακλείδης ἐκέλευεν αὐτῶι τὸ κέρας ὀρέξαι τὸν οἰνοχόον. ὁ δὲ Ξενοφῶν (ἤδη γὰρ ὑποπεπωκὼς ἐτύγχανεν) ἀνέστη θαρραλέως δεξάμενος τὸ κέρας καὶ εἶπεν·", "st": "7.3.29"}, {"sp": "N", "t": "«ἐγὼ δέ σοι, ὦ Σεύθη, δίδωμι ἐμαυτὸν καὶ τοὺς ἐμοὺς τούτους ἑταίρους φίλους εἶναι πιστούς, καὶ οὐδένα ἄκοντα, ἀλλὰ πάντας μᾶλλον ἔτι ἐμοῦ σοι βουλομένους φίλους εἶναι.", "st": "7.3.30"}, {"sp": "N", "t": "καὶ νῦν πάρεισιν οὐδέν σε προσαιτοῦντες, ἀλλὰ καὶ προϊέμενοι καὶ πονεῖν ὑπὲρ σοῦ καὶ προκινδυνεύειν ἐθέλοντες· μεθ᾽ ὧν, ἂν οἱ θεοὶ θέλωσι, πολλὴν χώραν τὴν μὲν ἀπολήψηι πατρώιαν οὖσαν, τὴν δὲ κτήσηι, πολλοὺς δὲ ἵππους, πολλοὺς δὲ ἄνδρας καὶ γυναῖκας καλὰς κτήσηι, οὓς οὐ λήιζεσθαί σε δεήσει, ἀλλ᾽ αὐτοὶ φέροντες παρέσονται πρὸς σὲ δῶρα.»", "st": "7.3.31"}, {"sp": "N", "t": "ἀναστὰς ὁ Σεύθης συνεξέπιε καὶ συγκατεσκεδάσατο μετ᾽ αὐτοῦ τὸ κέρας. μετὰ ταῦτα εἰσῆλθον κέρασί τε οἵοις σημαίνουσιν αὐλοῦντες καὶ σάλπιγξιν ὠμοβοείαις ῥυθμούς τε καὶ οἷον μαγάδι σαλπίζοντες.", "st": "7.3.32"}, {"sp": "N", "t": "καὶ αὐτὸς Σεύθης ἀναστὰς ἀνέκραγέ τε πολεμικὸν καὶ ἐξήλατο ὥσπερ βέλος φυλαττόμενος μάλα ἐλαφρῶς. εἰσῆισαν δὲ καὶ γελωτοποιοί.", "st": "7.3.33"}, {"sp": "N", "t": "ὡς δ᾽ ἦν ἥλιος ἐπὶ δυσμαῖς, ἀνέστησαν οἱ Ἕλληνες καὶ εἶπον ὅτι ὥρα νυκτοφύλακας καθιστάναι καὶ σύνθημα παραδιδόναι. καὶ Σεύθην ἐκέλευον παραγγεῖλαι ὅπως εἰς τὰ Ἑλληνικὰ στρατόπεδα μηδεὶς τῶν Θραικῶν εἴσεισι νυκτός· οἵ τε γὰρ πολέμιοι Θρᾶικες [ὑμῖν] καὶ ὑμεῖς οἱ φίλοι.", "st": "7.3.34"}, {"sp": "N", "t": "ὡς δ᾽ ἐξῆισαν, συνανέστη ὁ Σεύθης οὐδέν τι μεθύοντι ἐοικώς. ἐξελθὼν δ᾽ εἶπεν αὐτοὺς τοὺς στρατηγοὺς ἀποκαλέσας· «ὦ ἄνδρες, οἱ πολέμιοι ἡμῶν οὐκ ἴσασί πω τὴν ἡμετέραν συμμαχίαν· ἢν οὖν ἔλθωμεν ἐπ᾽ αὐτοὺς πρὶν φυλάξασθαι ὥστε μὴ ληφθῆναι ἢ παρασκευάσασθαι ὥστε ἀμύνασθαι, μάλιστ᾽ ἂν λάβοιμεν καὶ ἀνθρώπους καὶ χρήματα.»", "st": "7.3.35"}, {"sp": "N", "t": "συνεπήινουν ταῦτα οἱ στρατηγοὶ καὶ ἡγεῖσθαι ἐκέλευον. ὁ δ᾽ εἶπε· «παρασκευασάμενοι ἀναμένετε· ἐγὼ δὲ ὁπόταν καιρὸς ἦι ἥξω πρὸς ὑμᾶς, καὶ τοὺς πελταστὰς καὶ ὑμᾶς ἀναλαβὼν ἡγήσομαι σὺν τοῖς θεοῖς.»", "st": "7.3.36"}, {"sp": "N", "t": "καὶ ὁ Ξενοφῶν εἶπε· «σκέψαι τοίνυν, εἴπερ νυκτὸς πορευσόμεθα, εἰ ὁ Ἑλληνικὸς νόμος κάλλιον ἔχει· μεθ᾽ ἡμέραν μὲν γὰρ ἐν ταῖς πορείαις ἡγεῖται τοῦ στρατεύματος ὁποῖον ἂν ἀεὶ πρὸς τὴν χώραν συμφέρηι, ἐάν τε ὁπλιτικὸν ἐάν τε πελταστικὸν ἐάν τε ἱππικόν· νύκτωρ δὲ νόμος τοῖς Ἕλλησιν ἡγεῖσθαί ἐστι τὸ βραδύτατον·", "st": "7.3.37"}, {"sp": "N", "t": "οὕτω γὰρ ἥκιστα διασπᾶται τὰ στρατεύματα καὶ ἥκιστα λανθάνουσιν ἀποδιδράσκοντες ἀλλήλους· οἱ δὲ διασπασθέντες πολλάκις καὶ περιπίπτουσιν ἀλλήλοις καὶ ἀγνοοῦντες κακῶς ποιοῦσι καὶ πάσχουσιν.»", "st": "7.3.38"}, {"sp": "N", "t": "εἶπεν οὖν Σεύθης· «ὀρθῶς λέγετε καὶ ἐγὼ τῶι νόμωι τῶι ὑμετέρωι πείσομαι. καὶ ὑμῖν μὲν ἡγεμόνας δώσω τῶν πρεσβυτάτων τοὺς ἐμπειροτάτους τῆς χώρας, αὐτὸς δ᾽ ἐφέψομαι τελευταῖος τοὺς ἵππους ἔχων· ταχὺ γὰρ πρῶτος, ἂν δέηι, παρέσομαι.» σύνθημα δ᾽ εἶπον Ἀθηναίαν κατὰ τὴν συγγένειαν. ταῦτα εἰπόντες ἀνεπαύοντο.", "st": "7.3.39"}, {"sp": "N", "t": "ἡνίκα δ᾽ ἦν ἀμφὶ μέσας νύκτας, παρῆν Σεύθης ἔχων τοὺς ἱππέας τεθωρακισμένους καὶ τοὺς πελταστὰς σὺν τοῖς ὅπλοις. καὶ ἐπεὶ παρέδωκε τοὺς ἡγεμόνας, οἱ μὲν ὁπλῖται ἡγοῦντο, οἱ δὲ πελτασταὶ εἵποντο, οἱ δ᾽ ἱππεῖς ὠπισθοφυλάκουν·", "st": "7.3.40"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἡμέρα ἦν, ὁ Σεύθης παρήλαυνεν εἰς τὸ πρόσθεν καὶ ἐπήινεσε τὸν Ἑλληνικὸν νόμον. πολλάκις γὰρ ἔφη νύκτωρ αὐτὸς καὶ σὺν ὀλίγοις πορευόμενος ἀποσπασθῆναι σὺν τοῖς ἵπποις ἀπὸ τῶν πεζῶν· νῦν δ᾽ ὥσπερ δεῖ ἁθρόοι πάντες ἅμα τῆι ἡμέραι φαινόμεθα. ἀλλὰ ὑμεῖς μὲν περιμένετε αὐτοῦ καὶ ἀναπαύσασθε, ἐγὼ δὲ σκεψάμενός τι ἥξω.", "st": "7.3.41"}, {"sp": "N", "t": "ταῦτ᾽ εἰπὼν ἤλαυνε δι᾽ ὄρους ὁδόν τινα λαβών. ἐπεὶ δ᾽ ἀφίκετο εἰς χιόνα πολλήν, ἐσκέψατο εἰ εἴη ἴχνη ἀνθρώπων ἢ πρόσω ἡγούμενα ἢ ἐναντία. ἐπεὶ δὲ ἀτριβῆ ἑώρα τὴν ὁδόν, ἧκε ταχὺ πάλιν καὶ ἔλεγεν·", "st": "7.3.42"}, {"sp": "N", "t": "«ἄνδρες, καλῶς ἔσται, ἢν θεὸς θέληι· τοὺς γὰρ ἀνθρώπους λήσομεν ἐπιπεσόντες. ἀλλ᾽ ἐγὼ μὲν ἡγήσομαι τοῖς ἵπποις, ὅπως ἄν τινα ἴδωμεν, μὴ διαφυγὼν σημήνηι τοῖς πολεμίοις· ὑμεῖς δ᾽ ἕπεσθε· κἂν λειφθῆτε, τῶι στίβωι τῶν ἵππων ἕπεσθε. ὑπερβάντες δὲ τὰ ὄρη ἥξομεν εἰς κώμας πολλάς τε καὶ εὐδαίμονας.»", "st": "7.3.43"}, {"sp": "N", "t": "ἡνίκα δ᾽ ἦν μέσον ἡμέρας, ἤδη τε ἦν ἐπὶ τοῖς ἄκροις καὶ κατιδὼν τὰς κώμας ἧκεν ἐλαύνων πρὸς τοὺς ὁπλίτας καὶ ἔλεγεν· «ἀφήσω ἤδη καταθεῖν τοὺς μὲν ἱππέας εἰς τὸ πεδίον, τοὺς δὲ πελταστὰς ἐπὶ τὰς κώμας. ἀλλ᾽ ἕπεσθε ὡς ἂν δύνησθε τάχιστα, ὅπως ἐάν τις ὑφιστῆται, ἀλέξησθε.»", "st": "7.3.44"}, {"sp": "N", "t": "ἀκούσας ταῦτα ὁ Ξενοφῶν κατέβη ἀπὸ τοῦ ἵππου. καὶ ὃς ἤρετο· «τί καταβαίνεις ἐπεὶ σπεύδειν δεῖ;» «οἶδα, ἔφη, ὅτι οὐκ ἐμοῦ μόνου δέηι· οἱ δὲ ὁπλῖται θᾶττον δραμοῦνται καὶ ἥδιον, ἐὰν καὶ ἐγὼ πεζὸς ἡγῶμαι.»", "st": "7.3.45"}, {"sp": "N", "t": "μετὰ ταῦτα ὤιχετο, καὶ Τιμασίων μετ᾽ αὐτοῦ ἔχων ἱππέας ὡς τετταράκοντα τῶν Ἑλλήνων. Ξενοφῶν δὲ παρηγγύησε τοὺς εἰς τριάκοντα ἔτη παριέναι ἀπὸ τῶν λόχων εὐζώνους. καὶ αὐτὸς μὲν ἐτρόχαζε τούτους ἔχων, Κλεάνωρ δ᾽ ἡγεῖτο τῶν ἄλλων.", "st": "7.3.46"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἐν ταῖς κώμαις ἦσαν, Σεύθης ἔχων ὅσον τριάκοντα ἱππέας προσελάσας εἶπε· «τάδε δή, ὦ Ξενοφῶν, ἃ σὺ ἔλεγες· ἔχονται οἱ ἄνθρωποι· ἀλλὰ γὰρ ἔρημοι οἱ ἱππεῖς οἴχονταί μοι ἄλλος ἄλληι διώκων, καὶ δέδοικα μὴ συστάντες ἁθρόοι που κακόν τι ἐργάσωνται οἱ πολέμιοι. δεῖ δὲ καὶ ἐν ταῖς κώμαις καταμένειν τινὰς ἡμῶν· μεσταὶ γάρ εἰσιν ἀνθρώπων.»", "st": "7.3.47"}, {"sp": "N", "t": "«ἀλλ᾽ ἐγὼ μέν, ἔφη ὁ Ξενοφῶν, σὺν οἷς ἔχω τὰ ἄκρα καταλήψομαι· σὺ δὲ Κλεάνορα κέλευε διὰ τοῦ πεδίου παρατεῖναι τὴν φάλαγγα παρὰ τὰς κώμας.» ἐπεὶ ταῦτα ἐποίησαν, συνηλίσθησαν ἀνδράποδα μὲν ὡς χίλια, βόες δὲ δισχίλιοι, πρόβατα ἄλλα μύρια. τότε μὲν δὴ αὐτοῦ ηὐλίσθησαν.", "st": "7.3.48"}, {"sp": "N", "t": "τῆι δ᾽ ὑστεραίαι κατακαύσας ὁ Σεύθης τὰς κώμας παντελῶς καὶ οἰκίαν οὐδεμίαν λιπών, ὅπως φόβον ἐνθείη καὶ τοῖς ἄλλοις οἷα πείσονται, ἂν μὴ πείθωνται, ἀπήιει πάλιν.", "st": "7.4.1"}, {"sp": "N", "t": "καὶ τὴν μὲν λείαν ἀπέπεμψε διατίθεσθαι Ἡρακλείδην εἰς Πέρινθον, ὅπως ἂν μισθὸς γένοιτο τοῖς στρατιώταις· αὐτὸς δὲ καὶ οἱ Ἕλληνες ἐστρατοπεδεύοντο ἀνὰ τὸ Θυνῶν πεδίον.", "st": "7.4.2"}, {"sp": "N", "t": "οἱ δ᾽ ἐκλιπόντες ἔφευγον εἰς τὰ ὄρη. ἦν δὲ χιὼν πολλὴ καὶ ψῦχος οὕτως ὥστε τὸ ὕδωρ ὃ ἐφέροντο ἐπὶ δεῖπνον ἐπήγνυτο καὶ ὁ οἶνος ὁ ἐν τοῖς ἀγγείοις, καὶ τῶν Ἑλλήνων πολλῶν καὶ ῥῖνες ἀπεκαίοντο καὶ ὦτα.", "st": "7.4.3"}, {"sp": "N", "t": "καὶ τότε δῆλον ἐγένετο οὗ ἕνεκα οἱ Θρᾶικες τὰς ἀλωπεκᾶς ἐπὶ ταῖς κεφαλαῖς φοροῦσι καὶ τοῖς ὠσί, καὶ χιτῶνας οὐ μόνον περὶ τοῖς στέρνοις ἀλλὰ καὶ περὶ τοῖς μηροῖς, καὶ ζειρὰς μέχρι τῶν ποδῶν ἐπὶ τῶν ἵππων ἔχουσιν, ἀλλ᾽ οὐ χλαμύδας.", "st": "7.4.4"}, {"sp": "N", "t": "ἀφιεὶς δὲ τῶν αἰχμαλώτων ὁ Σεύθης εἰς τὰ ὄρη ἔλεγεν ὅτι εἰ μὴ καταβήσονται οἰκήσοντες καὶ πείσονται, ὅτι κατακαύσει καὶ τούτων τὰς κώμας καὶ τὸν σῖτον, καὶ ἀπολοῦνται τῶι λιμῶι. ἐκ τούτου κατέβαινον καὶ γυναῖκες καὶ παῖδες καὶ πρεσβύτεροι· οἱ δὲ νεώτεροι ἐν ταῖς ὑπὸ τὸ ὄρος κώμαις ηὐλίζοντο.", "st": "7.4.5"}, {"sp": "N", "t": "καὶ ὁ Σεύθης καταμαθὼν ἐκέλευσε τὸν Ξενοφῶντα τῶν ὁπλιτῶν τοὺς νεωτάτους λαβόντα συνεπισπέσθαι. καὶ ἀναστάντες τῆς νυκτὸς ἅμα τῆι ἡμέραι παρῆσαν εἰς τὰς κώμας. καὶ οἱ μὲν πλεῖστοι ἐξέφυγον· πλησίον γὰρ ἦν τὸ ὄρος· ὅσους δὲ ἔλαβε κατηκόντισεν ἀφειδῶς Σεύθης.", "st": "7.4.6"}, {"sp": "N", "t": "Ἐπισθένης δ᾽ ἦν τις Ὀλύνθιος παιδεραστής, ὃς ἰδὼν παῖδα καλὸν ἡβάσκοντα ἄρτι πέλτην ἔχοντα μέλλοντα ἀποθνήισκειν, προσδραμὼν Ξενοφῶντα ἱκέτευε βοηθῆσαι παιδὶ καλῶι.", "st": "7.4.7"}, {"sp": "N", "t": "καὶ ὃς προσελθὼν τῶι Σεύθηι δεῖται μὴ ἀποκτεῖναι τὸν παῖδα, καὶ τοῦ Ἐπισθένους διηγεῖται τὸν τρόπον, καὶ ὅτι λόχον ποτὲ συνελέξατο σκοπῶν οὐδὲν ἄλλο ἢ εἴ τινες εἶεν καλοί, καὶ μετὰ τούτων ἦν ἀνὴρ ἀγαθός.", "st": "7.4.8"}, {"sp": "N", "t": "ὁ δὲ Σεύθης ἤρετο· «ἦ καὶ θέλοις ἄν, ὦ Ἐπίσθενες, ὑπὲρ τούτου ἀποθανεῖν;» ὁ δ᾽ ὑπερανατείνας τὸν τράχηλον, «παῖε, ἔφη, εἰ κελεύει ὁ παῖς καὶ μέλλει χάριν εἰδέναι.»", "st": "7.4.9"}, {"sp": "N", "t": "ἐπήρετο ὁ Σεύθης τὸν παῖδα εἰ παίσειεν αὐτὸν ἀντ᾽ ἐκείνου. οὐκ εἴα ὁ παῖς, ἀλλ᾽ ἱκέτευε μηδέτερον κατακαίνειν. ἐνταῦθα ὁ Ἐπισθένης περιλαβὼν τὸν παῖδα εἶπεν· «ὥρα σοι, ὦ Σεύθη, περὶ τοῦδέ μοι διαμάχεσθαι· οὐ γὰρ μεθήσω τὸν παῖδα.»", "st": "7.4.10"}, {"sp": "N", "t": "ὁ δὲ Σεύθης γελῶν ταῦτα μὲν εἴα· ἔδοξε δὲ αὐτῶι αὐτοῦ αὐλισθῆναι, ἵνα μηδ᾽ ἐκ τούτων τῶν κωμῶν οἱ ἐπὶ τοῦ ὄρους τρέφοιντο. καὶ αὐτὸς μὲν ἐν τῶι πεδίωι ὑποκαταβὰς ἐσκήνου, ὁ δὲ Ξενοφῶν ἔχων τοὺς ἐπιλέκτους ἐν τῆι ὑπὸ τὸ ὄρος ἀνωτάτω κώμηι, καὶ οἱ ἄλλοι Ἕλληνες ἐν τοῖς ὀρεινοῖς καλουμένοις Θραιξὶ πλησίον κατεσκήνησαν.", "st": "7.4.11"}, {"sp": "N", "t": "ἐκ τούτου ἡμέραι τ᾽ οὐ πολλαὶ διετρίβοντο καὶ οἱ ἐκ τοῦ ὄρους Θρᾶικες καταβαίνοντες πρὸς τὸν Σεύθην περὶ σπονδῶν καὶ ὁμήρων διεπράττοντο. καὶ ὁ Ξενοφῶν ἐλθὼν ἔλεγε τῶι Σεύθηι ὅτι ἐν πονηροῖς σκηνοῖεν καὶ πλησίον εἶεν οἱ πολέμιοι· ἥδιόν τ᾽ ἂν ἔξω αὐλίζεσθαι ἔφη ἐν ἐχυροῖς χωρίοις μᾶλλον ἢ ἐν τοῖς στεγνοῖς, ὥστε ἀπολέσθαι. ὁ δὲ θαρρεῖν ἐκέλευε καὶ ἔδειξεν ὁμήρους παρόντας αὐτῶν.", "st": "7.4.12"}, {"sp": "N", "t": "ἐδέοντο δὲ καὶ αὐτοῦ Ξενοφῶντος καταβαίνοντές τινες τῶν ἐκ τοῦ ὄρους συμπρᾶξαι σφίσι τὰς σπονδάς. ὁ δ᾽ ὡμολόγει καὶ θαρρεῖν ἐκέλευε καὶ ἠγγυᾶτο μηδὲν αὐτοὺς κακὸν πείσεσθαι πειθομένους Σεύθηι. οἱ δ᾽ ἄρα ταῦτ᾽ ἔλεγον κατασκοπῆς ἕνεκα.", "st": "7.4.13"}, {"sp": "N", "t": "ταῦτα μὲν τῆς ἡμέρας ἐγένετο· εἰς δὲ τὴν ἐπιοῦσαν νύκτα ἐπιτίθενται ἐλθόντες ἐκ τοῦ ὄρους οἱ Θυνοί. καὶ ἡγεμὼν μὲν ἦν ὁ δεσπότης ἑκάστης τῆς οἰκίας· χαλεπὸν γὰρ ἦν ἄλλως τὰς οἰκίας σκότους ὄντος ἀνευρίσκειν ἐν ταῖς κώμαις· καὶ γὰρ αἱ οἰκίαι κύκλωι περιεσταύρωντο μεγάλοις σταυροῖς τῶν προβάτων ἕνεκα.", "st": "7.4.14"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἐγένοντο κατὰ τὰς θύρας ἑκάστου τοῦ οἰκήματος, οἱ μὲν εἰσηκόντιζον, οἱ δὲ τοῖς σκυτάλοις ἔβαλλον, ἃ ἔχειν ἔφασαν ὡς ἀποκόψοντες τῶν δοράτων τὰς λόγχας, οἱ δ᾽ ἐνεπίμπρασαν, καὶ Ξενοφῶντα ὀνομαστὶ καλοῦντες ἐξιόντα ἐκέλευον ἀποθνήισκειν, ἢ αὐτοῦ ἔφασαν κατακαυθήσεσθαι αὐτόν.", "st": "7.4.15"}, {"sp": "N", "t": "καὶ ἤδη τε διὰ τοῦ ὀρόφου ἐφαίνετο πῦρ, καὶ ἐντεθωρακισμένοι οἱ περὶ τὸν Ξενοφῶντα ἔνδον ἦσαν ἀσπίδας καὶ μαχαίρας καὶ κράνη ἔχοντες, καὶ Σιλανὸς Μακίστιος ἐτῶν ὡς ὀκτωκαίδεκα σημαίνει τῆι σάλπιγγι· καὶ εὐθὺς ἐκπηδῶσιν ἐσπασμένοι τὰ ξίφη καὶ οἱ ἐκ τῶν ἄλλων σκηνωμάτων.", "st": "7.4.16"}, {"sp": "N", "t": "οἱ δὲ Θρᾶικες φεύγουσιν, ὥσπερ δὴ τρόπος ἦν αὐτοῖς, ὄπισθεν περιβαλλόμενοι τὰς πέλτας· καὶ αὐτῶν ὑπεραλλομένων τοὺς σταυροὺς ἐλήφθησάν τινες κρεμασθέντες ἐνεχομένων τῶν πελτῶν τοῖς σταυροῖς· οἱ δὲ καὶ ἀπέθανον ἁμαρτόντες τῶν ἐξόδων· οἱ δὲ Ἕλληνες ἐδίωκον ἔξω τῆς κώμης.", "st": "7.4.17"}, {"sp": "N", "t": "τῶν δὲ Θυνῶν ὑποστραφέντες τινὲς ἐν τῶι σκότει τοὺς παρατρέχοντας παρ᾽ οἰκίαν καιομένην ἠκόντιζον εἰς τὸ φῶς ἐκ τοῦ σκότους· καὶ ἔτρωσαν Ἱερώνυμόν τε καὶ Εὐοδέα λοχαγὸν καὶ Θεογένην Λοκρὸν λοχαγόν· ἀπέθανε δὲ οὐδείς· κατεκαύθη μέντοι καὶ ἐσθής τινων καὶ σκεύη.", "st": "7.4.18"}, {"sp": "N", "t": "Σεύθης δὲ ἧκε βοηθῶν σὺν ἑπτὰ ἱππεῦσι τοῖς πρώτοις καὶ τὸν σαλπικτὴν ἔχων τὸν Θράικιον. καὶ ἐπείπερ ἤισθετο, ὅσονπερ χρόνον ἐβοήθει, τοσοῦτον καὶ τὸ κέρας ἐφθέγγετο αὐτῶι· ὥστε καὶ τοῦτο φόβον συμπαρέσχε τοῖς πολεμίοις. ἐπεὶ δ᾽ ἦλθεν, ἐδεξιοῦτό τε καὶ ἔλεγεν ὅτι οἴοιτο τεθνεῶτας πολλοὺς εὑρήσειν.", "st": "7.4.19"}, {"sp": "N", "t": "ἐκ τούτου ὁ Ξενοφῶν δεῖται τοὺς ὁμήρους τε αὐτῶι παραδοῦναι καὶ ἐπὶ τὸ ὄρος, εἰ βούλεται, συστρατεύεσθαι· εἰ δὲ μή, αὐτὸν ἐᾶσαι.", "st": "7.4.20"}, {"sp": "N", "t": "τῆι οὖν ὑστεραίαι παραδίδωσιν ὁ Σεύθης τοὺς ὁμήρους, πρεσβυτέρους ἄνδρας ἤδη, τοὺς κρατίστους, ὡς ἔφασαν, τῶν ὀρεινῶν, καὶ αὐτὸς ἔρχεται σὺν τῆι δυνάμει. ἤδη δὲ εἶχε καὶ τριπλασίαν δύναμιν ὁ Σεύθης· ἐκ γὰρ τῶν Ὀδρυσῶν ἀκούοντες ἃ πράττει ὁ Σεύθης πολλοὶ κατέβαινον συστρατευσόμενοι.", "st": "7.4.21"}, {"sp": "N", "t": "οἱ δὲ Θυνοὶ ἐπεὶ εἶδον ἀπὸ τοῦ ὄρους πολλοὺς μὲν ὁπλίτας, πολλοὺς δὲ πελταστάς, πολλοὺς δὲ ἱππέας, καταβάντες ἱκέτευον σπείσασθαι, καὶ πάντα ὡμολόγουν ποιήσειν καὶ πιστὰ λαμβάνειν ἐκέλευον.", "st": "7.4.22"}, {"sp": "N", "t": "ὁ δὲ Σεύθης καλέσας τὸν Ξενοφῶντα ἐπεδείκνυεν ἃ λέγοιεν, καὶ οὐκ ἂν ἔφη σπείσασθαι, εἰ Ξενοφῶν βούλοιτο τιμωρήσασθαι αὐτοὺς τῆς ἐπιθέσεως.", "st": "7.4.23"}, {"sp": "N", "t": "ὁ δ᾽ εἶπεν· «ἀλλ᾽ ἔγωγε ἱκανὴν νομίζω καὶ νῦν δίκην ἔχειν, εἰ οὗτοι δοῦλοι ἔσονται ἀντ᾽ ἐλευθέρων.» συμβουλεύειν μέντοι ἔφη αὐτῶι τὸ λοιπὸν ὁμήρους λαμβάνειν τοὺς δυνατωτάτους κακόν τι ποιεῖν, τοὺς δὲ γέροντας οἴκοι ἐᾶν. οἱ μὲν οὖν ταύτηι πάντες δὴ προσωμολόγουν.", "st": "7.4.24"}, {"sp": "N", "t": "ὑπερβάλλουσι δὲ πρὸς τοὺς ὑπὲρ Βυζαντίου Θρᾶικας εἰς τὸ Δέλτα καλούμενον· αὕτη δ᾽ ἦν οὐκέτι ἀρχὴ Μαισάδου, ἀλλὰ Τήρους τοῦ Ὀδρύσου [ἀρχαίου τινός].", "st": "7.5.1"}, {"sp": "N", "t": "καὶ ὁ Ἡρακλείδης ἐνταῦθα ἔχων τὴν τιμὴν τῆς λείας παρῆν. καὶ Σεύθης ἐξαγαγὼν ζεύγη ἡμιονικὰ τρία (οὐ γὰρ ἦν πλείω), τὰ δ᾽ ἄλλα βοεικά, καλέσας Ξενοφῶντα ἐκέλευε λαβεῖν, τὰ δ᾽ ἄλλα διανεῖμαι τοῖς στρατηγοῖς καὶ λοχαγοῖς.", "st": "7.5.2"}, {"sp": "N", "t": "Ξενοφῶν δὲ εἶπεν· «ἐμοὶ τοίνυν ἀρκεῖ καὶ αὖθις λαβεῖν· τούτοις δὲ τοῖς στρατηγοῖς δωροῦ οἳ σὺν ἐμοὶ ἠκολούθησαν καὶ λοχαγοῖς.»", "st": "7.5.3"}, {"sp": "N", "t": "καὶ τῶν ζευγῶν λαμβάνει ἓν μὲν Τιμασίων ὁ Δαρδανεύς, ἓν δὲ Κλεάνωρ ὁ Ὀρχομένιος, ἓν δὲ Φρυνίσκος ὁ Ἀχαιός· τὰ δὲ βοεικὰ ζεύγη τοῖς λοχαγοῖς κατεμερίσθη. τὸν δὲ μισθὸν ἀποδίδωσιν ἐξεληλυθότος ἤδη τοῦ μηνὸς εἴκοσι μόνον ἡμερῶν· ὁ γὰρ Ἡρακλείδης ἔλεγεν ὅτι οὐ πλέον ἐμπολήσαι.", "st": "7.5.4"}, {"sp": "N", "t": "ὁ οὖν Ξενοφῶν ἀχθεσθεὶς εἶπεν ἐπομόσας· «δοκεῖς μοι, ὦ Ἡρακλείδη, οὐχ ὡς δεῖ κήδεσθαι Σεύθου· εἰ γὰρ ἐκήδου, ἧκες ἂν φέρων πλήρη τὸν μισθὸν καὶ προσδανεισάμενος, εἰ μὴ ἄλλως ἐδύνω, καὶ ἀποδόμενος τὰ σαυτοῦ ἱμάτια.»", "st": "7.5.5"}, {"sp": "N", "t": "ἐντεῦθεν ὁ Ἡρακλείδης ἠχθέσθη τε καὶ ἔδεισε μὴ ἐκ τῆς Σεύθου φιλίας ἐκβληθείη, καὶ ὅ τι ἐδύνατο ἀπὸ ταύτης τῆς ἡμέρας Ξενοφῶντα διέβαλλε πρὸς Σεύθην.", "st": "7.5.6"}, {"sp": "N", "t": "οἱ μὲν δὴ στρατιῶται Ξενοφῶντι ἐνεκάλουν ὅτι οὐκ εἶχον τὸν μισθόν· Σεύθης δὲ ἤχθετο αὐτῶι ὅτι ἐντόνως τοῖς στρατιώταις ἀπήιτει τὸν μισθόν.", "st": "7.5.7"}, {"sp": "N", "t": "καὶ τέως μὲν αἰεὶ ἐμέμνητο ὡς, ἐπειδὰν ἐπὶ θάλατταν ἀπέλθηι, παραδώσει αὐτῶι Βισάνθην καὶ Γάνον καὶ Νέον τεῖχος· ἀπὸ δὲ τούτου τοῦ χρόνου οὐδενὸς ἔτι τούτων ἐμέμνητο. ὁ γὰρ Ἡρακλείδης καὶ τοῦτο διεβεβλήκει ὡς οὐκ ἀσφαλὲς εἴη τείχη παραδιδόναι ἀνδρὶ δύναμιν ἔχοντι.", "st": "7.5.8"}, {"sp": "N", "t": "ἐκ τούτου ὁ μὲν Ξενοφῶν ἐβουλεύετο τί χρὴ ποιεῖν περὶ τοῦ ἔτι ἄνω στρατεύεσθαι· ὁ δ᾽ Ἡρακλείδης εἰσαγαγὼν τοὺς ἄλλους στρατηγοὺς πρὸς Σεύθην λέγειν τε ἐκέλευεν αὐτοὺς ὅτι οὐδὲν ἂν ἧττον σφεῖς ἀγάγοιεν τὴν στρατιὰν ἢ Ξενοφῶν, τόν τε μισθὸν ὑπισχνεῖτο αὐτοῖς ἐντὸς ὀλίγων ἡμερῶν ἔκπλεων παρέσεσθαι δυοῖν μηνοῖν, καὶ συστρατεύεσθαι ἐκέλευε.", "st": "7.5.9"}, {"sp": "N", "t": "καὶ ὁ Τιμασίων εἶπεν· «ἐγὼ μὲν τοίνυν οὐδ᾽ ἂν πέντε μηνῶν μισθὸς μέλληι εἶναι στρατευσαίμην ἂν ἄνευ Ξενοφῶντος.» καὶ ὁ Φρυνίσκος καὶ ὁ Κλεάνωρ συνωμολόγουν τῶι Τιμασίωνι.", "st": "7.5.10"}, {"sp": "N", "t": "ἐντεῦθεν ὁ Σεύθης ἐλοιδόρει τὸν Ἡρακλείδην ὅτι οὐ παρεκάλει καὶ Ξενοφῶντα. ἐκ δὲ τούτου παρακαλοῦσιν αὐτὸν μόνον. ὁ δὲ γνοὺς τοῦ Ἡρακλείδου τὴν πανουργίαν ὅτι βούλοιτο αὐτὸν διαβάλλειν πρὸς τοὺς ἄλλους στρατηγούς, παρέρχεται λαβὼν τούς τε στρατηγοὺς πάντας καὶ τοὺς λοχαγούς.", "st": "7.5.11"}, {"sp": "N", "t": "καὶ ἐπεὶ πάντες ἐπείσθησαν, συνεστρατεύοντο καὶ ἀφικνοῦνται ἐν δεξιᾶι ἔχοντες τὸν Πόντον διὰ τῶν Μελινοφάγων καλουμένων Θραικῶν εἰς τὸν Σαλμυδησσόν. ἔνθα τῶν εἰς τὸν Πόντον πλεουσῶν νεῶν πολλαὶ ὀκέλλουσι καὶ ἐκπίπτουσι· τέναγος γάρ ἐστιν ἐπὶ πάμπολυ τῆς θαλάττης.", "st": "7.5.12"}, {"sp": "N", "t": "καὶ Θρᾶικες οἱ κατὰ ταῦτα οἰκοῦντες στήλας ὁρισάμενοι τὰ καθ᾽ αὑτοὺς ἐκπίπτοντα ἕκαστοι λήιζονται· τέως δὲ ἔλεγον πρὶν ὁρίσασθαι ἁρπάζοντας πολλοὺς ὑπ᾽ ἀλλήλων ἀποθνήισκειν.", "st": "7.5.13"}, {"sp": "N", "t": "ἐνταῦθα ηὑρίσκοντο πολλαὶ μὲν κλῖναι, πολλὰ δὲ κιβώτια, πολλαὶ δὲ βίβλοι γεγραμμέναι, καὶ τἆλλα πολλὰ ὅσα ἐν ξυλίνοις τεύχεσι ναύκληροι ἄγουσιν. ἐντεῦθεν ταῦτα καταστρεψάμενοι ἀπῆισαν πάλιν.", "st": "7.5.14"}, {"sp": "N", "t": "ἔνθα δὴ Σεύθης εἶχε στράτευμα ἤδη πλέον τοῦ Ἑλληνικοῦ· ἔκ τε γὰρ Ὀδρυσῶν πολὺ ἔτι πλείους κατεβεβήκεσαν καὶ οἱ αἰεὶ πειθόμενοι συνεστρατεύοντο. κατηυλίσθησαν δ᾽ ἐν τῶι πεδίωι ὑπὲρ Σηλυμβρίας ὅσον τριάκοντα σταδίους ἀπέχοντες τῆς θαλάττης.", "st": "7.5.15"}, {"sp": "N", "t": "καὶ μισθὸς μὲν οὐδείς πω ἐφαίνετο· πρὸς δὲ τὸν Ξενοφῶντα οἵ τε στρατιῶται παγχαλέπως εἶχον ὅ τε Σεύθης οὐκέτι οἰκείως διέκειτο, ἀλλ᾽ ὁπότε συγγενέσθαι αὐτῶι βουλόμενος ἔλθοι, πολλαὶ ἤδη ἀσχολίαι ἐφαίνοντο.", "st": "7.5.16"}, {"sp": "N", "t": "ἐν τούτωι τῶι χρόνωι σχεδὸν ἤδη δύο μηνῶν ὄντων ἀφικνεῖται Χαρμῖνός τε ὁ Λάκων καὶ Πολύνικος παρὰ Θίβρωνος, καὶ λέγουσιν ὅτι Λακεδαιμονίοις δοκεῖ στρατεύεσθαι ἐπὶ Τισσαφέρνην, καὶ Θίβρων ἐκπέπλευκεν ὡς πολεμήσων, καὶ δεῖται ταύτης τῆς στρατιᾶς καὶ λέγει ὅτι δαρεικὸς ἑκάστωι ἔσται μισθὸς τοῦ μηνός, καὶ τοῖς λοχαγοῖς διμοιρία, τοῖς δὲ στρατηγοῖς τετραμοιρία.", "st": "7.6.1"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἦλθον οἱ Λακεδαιμόνιοι, εὐθὺς ὁ Ἡρακλείδης πυθόμενος ὅτι ἐπὶ τὸ στράτευμα ἥκουσι λέγει τῶι Σεύθηι ὅτι κάλλιστόν τι γεγένηται· οἱ μὲν γὰρ Λακεδαιμόνιοι δέονται τοῦ στρατεύματος, σὺ δὲ οὐκέτι δέηι· ἀποδιδοὺς δὲ τὸ στράτευμα χαριῆι αὐτοῖς, σὲ δὲ οὐκέτι ἀπαιτήσουσι τὸν μισθόν, ἀλλ᾽ ἀπαλλάξονται ἐκ τῆς χώρας.", "st": "7.6.2"}, {"sp": "N", "t": "ἀκούσας ταῦτα ὁ Σεύθης κελεύει παράγειν· καὶ ἐπεὶ εἶπον ὅτι ἐπὶ τὸ στράτευμα ἥκουσιν, ἔλεγεν ὅτι τὸ στράτευμα ἀποδίδωσι, φίλος τε καὶ σύμμαχος εἶναι βούλεται, καλεῖ τε αὐτοὺς ἐπὶ ξένια· καὶ ἐξένιζε μεγαλοπρεπῶς. Ξενοφῶντα δὲ οὐκ ἐκάλει, οὐδὲ τῶν ἄλλων στρατηγῶν οὐδένα.", "st": "7.6.3"}, {"sp": "N", "t": "ἐρωτώντων δὲ τῶν Λακεδαιμονίων τίς ἀνὴρ εἴη Ξενοφῶν ἀπεκρίνατο ὅτι τὰ μὲν ἄλλα εἴη οὐ κακός, φιλοστρατιώτης δέ· καὶ διὰ τοῦτο χεῖρόν ἐστιν αὐτῶι. καὶ οἳ εἶπον· «ἀλλ᾽ ἦ δημαγωγεῖ ὁ ἀνὴρ τοὺς ἄνδρας;» καὶ ὁ Ἡρακλείδης, «πάνυ μὲν οὖν,» ἔφη.", "st": "7.6.4"}, {"sp": "N", "t": "«ἆρ᾽ οὖν, ἔφασαν, μὴ καὶ ἡμῖν ἐναντιώσεται τῆς ἀπαγωγῆς;» «ἀλλ᾽ ἢν ὑμεῖς, ἔφη ὁ Ἡρακλείδης, συλλέξαντες αὐτοὺς ὑπόσχησθε τὸν μισθόν, ὀλίγον ἐκείνωι προσχόντες ἀποδραμοῦνται σὺν ὑμῖν.»", "st": "7.6.5"}, {"sp": "N", "t": "«πῶς οὖν ἄν, ἔφασαν, ἡμῖν συλλεγεῖεν;» «αὔριον ὑμᾶς, ἔφη ὁ Ἡρακλείδης, πρὼι ἄξομεν πρὸς αὐτούς· καὶ οἶδα, ἔφη, ὅτι ἐπειδὰν ὑμᾶς ἴδωσιν, ἄσμενοι συνδραμοῦνται.» αὕτη μὲν ἡ ἡμέρα οὕτως ἔληξεν.", "st": "7.6.6"}, {"sp": "N", "t": "τῆι δ᾽ ὑστεραίαι ἄγουσιν ἐπὶ τὸ στράτευμα τοὺς Λάκωνας Σεύθης τε καὶ Ἡρακλείδης, καὶ συλλέγεται ἡ στρατιά. τὼ δὲ Λάκωνε ἐλεγέτην ὅτι Λακεδαιμονίοις δοκεῖ πολεμεῖν Τισσαφέρνει τῶι ὑμᾶς ἀδικήσαντι· ἢν οὖν ἴητε σὺν ἡμῖν, τόν τε ἐχθρὸν τιμωρήσεσθε καὶ δαρεικὸν ἕκαστος οἴσει τοῦ μηνὸς ὑμῶν, λοχαγὸς δὲ τὸ διπλοῦν, στρατηγὸς δὲ τὸ τετραπλοῦν.", "st": "7.6.7"}, {"sp": "N", "t": "καὶ οἱ στρατιῶται ἄσμενοί τε ἤκουσαν καὶ εὐθὺς ἀνίσταταί τις τῶν Ἀρκάδων τοῦ Ξενοφῶντος κατηγορήσων. παρῆν δὲ καὶ Σεύθης βουλόμενος εἰδέναι τί πραχθήσεται, καὶ ἐν ἐπηκόωι εἱστήκει ἔχων ἑρμηνέα·", "st": "7.6.8"}, {"sp": "N", "t": "ξυνίει δὲ καὶ αὐτὸς Ἑλληνιστὶ τὰ πλεῖστα. ἔνθα δὴ λέγει ὁ Ἀρκάς· «ἀλλ᾽ ἡμεῖς μέν, ὦ Λακεδαιμόνιοι, καὶ πάλαι ἂν ἦμεν παρ᾽ ὑμῖν, εἰ μὴ Ξενοφῶν ἡμᾶς δεῦρο πείσας ἀπήγαγεν, ἔνθα δὴ ἡμεῖς μὲν τὸν δεινὸν χειμῶνα στρατευόμενοι καὶ νύκτα καὶ ἡμέραν οὐδὲν πεπαύμεθα· ὁ δὲ τοὺς ἡμετέρους πόνους ἔχει· καὶ Σεύθης ἐκεῖνον μὲν ἰδίαι πεπλούτικεν, ἡμᾶς δὲ ἀποστερεῖ τὸν μισθόν·", "st": "7.6.9"}, {"sp": "N", "t": "ὥστε [ὅ γε πρῶτος λέγων] ἐγὼ μὲν εἰ τοῦτον ἴδοιμι καταλευσθέντα καὶ δόντα δίκην ὧν ἡμᾶς περιεῖλκε, καὶ τὸν μισθὸν ἄν μοι δοκῶ ἔχειν καὶ οὐδὲν ἐπὶ τοῖς πεπονημένοις ἄχθεσθαι.» μετὰ τοῦτον ἄλλος ἀνέστη ὁμοίως καὶ ἄλλος. ἐκ δὲ τούτου Ξενοφῶν ἔλεξεν ὧδε.", "st": "7.6.10"}, {"sp": "N", "t": "«ἀλλὰ πάντα μὲν ἄρα ἄνθρωπον ὄντα προσδοκᾶν δεῖ, ὁπότε γε καὶ ἐγὼ νῦν ὑφ᾽ ὑμῶν αἰτίας ἔχω ἐν ὧι πλείστην προθυμίαν ἐμαυτῶι γε δοκῶ συνειδέναι περὶ ὑμᾶς παρεσχημένος. ἀπετραπόμην μέν γε ἤδη οἴκαδε ὡρμημένος, οὐ μὰ τὸν Δία οὔτοι πυνθανόμενος ὑμᾶς εὖ πράττειν, ἀλλὰ μᾶλλον ἀκούων ἐν ἀπόροις εἶναι ὡς ὠφελήσων εἴ τι δυναίμην.", "st": "7.6.11"}, {"sp": "N", "t": "ἐπεὶ δὲ ἦλθον, Σεύθου τουτουὶ πολλοὺς ἀγγέλους πρὸς ἐμὲ πέμποντος καὶ πολλὰ ὑπισχνουμένου μοι, εἰ πείσαιμι ὑμᾶς πρὸς αὐτὸν ἐλθεῖν, τοῦτο μὲν οὐκ ἐπεχείρησα ποιεῖν, ὡς αὐτοὶ ὑμεῖς ἐπίστασθε. ἦγον δὲ ὅθεν ὠιόμην τάχιστ᾽ ἂν ὑμᾶς εἰς τὴν Ἀσίαν διαβῆναι. ταῦτα γὰρ καὶ βέλτιστα ἐνόμιζον ὑμῖν εἶναι καὶ ὑμᾶς ἤιδειν βουλομένους.", "st": "7.6.12"}, {"sp": "N", "t": "ἐπεὶ δ᾽ Ἀρίσταρχος ἐλθὼν σὺν τριήρεσιν ἐκώλυε διαπλεῖν ἡμᾶς, ἐκ τούτου, ὅπερ εἰκὸς δήπου ἦν, συνέλεξα ὑμᾶς, ὅπως βουλευσαίμεθα ὅ τι χρὴ ποιεῖν.", "st": "7.6.13"}, {"sp": "N", "t": "οὐκοῦν ὑμεῖς ἀκούοντες μὲν Ἀριστάρχου ἐπιτάττοντος ὑμῖν εἰς Χερρόνησον πορεύεσθαι, ἀκούοντες δὲ Σεύθου πείθοντος ἑαυτῶι συστρατεύεσθαι, πάντες μὲν ἐλέγετε σὺν Σεύθηι ἰέναι, πάντες δ᾽ ἐψηφίσασθε ταῦτα. τί οὖν ἐγὼ ἐνταῦθα ἠδίκησα ἀγαγὼν ὑμᾶς ἔνθα πᾶσιν ὑμῖν ἐδόκει;", "st": "7.6.14"}, {"sp": "N", "t": "ἐπεί γε μὴν ψεύδεσθαι ἤρξατο Σεύθης περὶ τοῦ μισθοῦ, εἰ μὲν ἐπαινῶ αὐτόν, δικαίως ἄν με καὶ αἰτιῶισθε καὶ μισοῖτε· εἰ δὲ πρόσθεν αὐτῶι πάντων μάλιστα φίλος ὢν νῦν πάντων διαφορώτατός εἰμι, πῶς ἂν ἔτι δικαίως ὑμᾶς αἱρούμενος ἀντὶ Σεύθου ὑφ᾽ ὑμῶν αἰτίαν ἔχοιμι περὶ ὧν πρὸς τοῦτον διαφέρομαι;", "st": "7.6.15"}, {"sp": "N", "t": "ἀλλ᾽ εἴποιτ᾽ ἂν ὅτι ἔξεστι καὶ τὰ ὑμέτερα ἔχοντα παρὰ Σεύθου τεχνάζειν. οὐκοῦν δῆλον τοῦτό γέ ἐστιν, εἴπερ ἐμοὶ ἐτέλει τι Σεύθης, οὐχ οὕτως ἐτέλει δήπου ὡς ὧν τε ἐμοὶ δοίη στέροιτο καὶ ἄλλα ὑμῖν ἀποτείσειεν, ἀλλ᾽ οἶμαι, εἰ ἐδίδου, ἐπὶ τούτωι ἂν ἐδίδου ὅπως ἐμοὶ δοὺς μεῖον μὴ ἀποδοίη ὑμῖν τὸ πλέον.", "st": "7.6.16"}, {"sp": "N", "t": "εἰ τοίνυν οὕτως ἔχειν οἴεσθε, ἔξεστιν ὑμῖν αὐτίκα μάλα ματαίαν ταύτην τὴν πρᾶξιν ἀμφοτέροις ἡμῖν ποιῆσαι, ἐὰν πράττητε αὐτὸν τὰ χρήματα. δῆλον γὰρ ὅτι Σεύθης, εἰ ἔχω τι παρ᾽ αὐτοῦ, ἀπαιτήσει με, καὶ ἀπαιτήσει μέντοι δικαίως, ἐὰν μὴ βεβαιῶ τὴν πρᾶξιν αὐτῶι ἐφ᾽ ἧι ἐδωροδόκουν.", "st": "7.6.17"}, {"sp": "N", "t": "ἀλλὰ πολλοῦ μοι δοκῶ δεῖν τὰ ὑμέτερα ἔχειν· ὀμνύω γὰρ ὑμῖν θεοὺς ἅπαντας καὶ πάσας μηδ᾽ ἃ ἐμοὶ ἰδίαι ὑπέσχετο Σεύθης ἔχειν· πάρεστι δὲ καὶ αὐτὸς καὶ ἀκούων σύνοιδέ μοι εἰ ἐπιορκῶ·", "st": "7.6.18"}, {"sp": "N", "t": "ἵνα δὲ μᾶλλον θαυμάσητε, συνεπόμνυμι μηδὲ ἃ οἱ ἄλλοι στρατηγοὶ ἔλαβον εἰληφέναι, μὴ τοίνυν μηδὲ ὅσα τῶν λοχαγῶν ἔνιοι.", "st": "7.6.19"}, {"sp": "N", "t": "καὶ τί δὴ ταῦτ᾽ ἐποίουν; ὤιμην, ἄνδρες, ὅσω, μᾶλλον συμφέροιμι τούτωι τὴν τότε πενίαν, τοσούτωι μᾶλλον αὐτὸν φίλον ποιήσεσθαι, ὁπότε δυνασθείη. ἐγὼ δὲ ἅμα τε αὐτὸν ὁρῶ εὖ πράττοντα καὶ γιγνώσκω δὴ αὐτοῦ τὴν γνώμην.", "st": "7.6.20"}, {"sp": "N", "t": "εἴποι δή τις ἄν, οὔκουν αἰσχύνηι οὕτω μώρως ἐξαπατώμενος; ναὶ μὰ Δία ἠισχυνόμην μέντἄν, εἰ ὑπὸ πολεμίου γε ὄντος ἐξηπατήθην· φίλωι δὲ ὄντι ἐξαπατᾶν αἴσχιόν μοι δοκεῖ εἶναι ἢ ἐξαπατᾶσθαι.", "st": "7.6.21"}, {"sp": "N", "t": "ἐπεὶ εἴ γε πρὸς φίλους ἐστὶ φυλακή, πᾶσαν οἶδα ἡμᾶς φυλαξαμένους ὡς μὴ παρασχεῖν τούτωι πρόφασιν δικαίαν μὴ ἀποδιδόναι ἡμῖν ἃ ὑπέσχετο· οὔτε γὰρ ἠδικήσαμεν τοῦτον οὐδὲν οὔτε κατεβλακεύσαμεν τὰ τούτου οὐδὲ μὴν κατεδειλιάσαμεν οὐδὲν ἐφ᾽ ὅ τι ἡμᾶς οὗτος παρεκάλεσεν.", "st": "7.6.22"}, {"sp": "N", "t": "ἀλλά, φαίητε ἄν, ἔδει τὰ ἐνέχυρα τότε λαβεῖν, ὡς μηδ᾽ εἰ ἐβούλετο ἐδύνατο ἐξαπατᾶν. πρὸς ταῦτα δὴ ἀκούσατε ἃ ἐγὼ οὐκ ἄν ποτε εἶπον τούτου ἐναντίον, εἰ μή μοι παντάπασιν ἀγνώμονες ἐδοκεῖτε εἶναι ἢ λίαν εἰς ἐμὲ ἀχάριστοι.", "st": "7.6.23"}, {"sp": "N", "t": "ἀναμνήσθητε γὰρ ἐν ποίοις τισὶ πράγμασιν ὄντες ἐτυγχάνετε, ἐξ ὧν ὑμᾶς ἐγὼ ἀνήγαγον πρὸς Σεύθην. οὐκ εἰς μὲν Πέρινθον προσῆιτε [πόλιν], Ἀρίσταρχος δ᾽ ὑμᾶς ὁ Λακεδαιμόνιος οὐκ εἴα εἰσιέναι ἀποκλείσας τὰς πύλας; ὑπαίθριοι δ᾽ ἔξω ἐστρατοπεδεύετε, μέσος δὲ χειμὼν ἦν, ἀγορᾶι δὲ ἐχρῆσθε σπάνια μὲν ὁρῶντες τὰ ὤνια, σπάνια δ᾽ ἔχοντες ὅτων ὠνήσεσθε, ἀνάγκη δὲ ἦν μένειν ἐπὶ Θράικης·", "st": "7.6.24"}, {"sp": "N", "t": "τριήρεις γὰρ ἐφορμοῦσαι ἐκώλυον διαπλεῖν· εἰ δὲ μένοι τις, ἐν πολεμίαι εἶναι, ἔνθα πολλοὶ μὲν ἱππεῖς ἦσαν ἐναντίοι,", "st": "7.6.25"}, {"sp": "N", "t": "πολλοὶ δὲ πελτασταί, ἡμῖν δὲ ὁπλιτικὸν μὲν ἦν ὧι ἁθρόοι μὲν ἰόντες ἐπὶ τὰς κώμας ἴσως ἂν ἐδυνάμεθα σῖτον λαμβάνειν οὐδέν τι ἄφθονον, ὅτωι δὲ διώκοντες ἂν ἢ ἀνδράποδα ἢ πρόβατα κατελαμβάνομεν οὐκ ἦν ἡμῖν· οὔτε γὰρ ἱππικὸν οὔτε πελταστικὸν ἔτι ἐγὼ συνεστηκὸς κατέλαβον παρ᾽ ὑμῖν.", "st": "7.6.26"}, {"sp": "N", "t": "εἰ οὖν ἐν τοιαύτηι ἀνάγκηι ὄντων ὑμῶν μηδ᾽ ὁντιναοῦν μισθὸν προσαιτήσας Σεύθην σύμμαχον ὑμῖν προσέλαβον, ἔχοντα καὶ ἱππέας καὶ πελταστὰς ὧν ὑμεῖς προσεδεῖσθε, ἦ κακῶς ἂν ἐδόκουν ὑμῖν βεβουλεῦσθαι πρὸ ὑμῶν;", "st": "7.6.27"}, {"sp": "N", "t": "τούτων γὰρ δήπου κοινωνήσαντες καὶ σῖτον ἀφθονώτερον ἐν ταῖς κώμαις ηὑρίσκετε διὰ τὸ ἀναγκάζεσθαι τοὺς Θρᾶικας κατὰ σπουδὴν μᾶλλον φεύγειν, καὶ προβάτων καὶ ἀνδραπόδων μᾶλλον μετέσχετε.", "st": "7.6.28"}, {"sp": "N", "t": "καὶ πολέμιον οὐκέτι οὐδένα ἑωρῶμεν ἐπειδὴ τὸ ἱππικὸν ἡμῖν προσεγένετο· τέως δὲ θαρραλέως ἡμῖν ἐφείποντο οἱ πολέμιοι καὶ ἱππικῶι καὶ πελταστικῶι κωλύοντες μηδαμῆι κατ᾽ ὀλίγους ἀποσκεδαννυμένους τὰ ἐπιτήδεια ἀφθονώτερα ἡμᾶς πορίζεσθαι.", "st": "7.6.29"}, {"sp": "N", "t": "εἰ δὲ δὴ ὁ συμπαρέχων ὑμῖν ταύτην τὴν ἀσφάλειαν μὴ πάνυ πολὺν μισθὸν προσετέλει τῆς ἀσφαλείας, τοῦτο δὴ τὸ σχέτλιον πάθημα καὶ διὰ τοῦτο οὐδαμῆι οἴεσθε χρῆναι ζῶντα ἐμὲ ἀνεῖναι;", "st": "7.6.30"}, {"sp": "N", "t": "νῦν δὲ δὴ πῶς ἀπέρχεσθε; οὐ διαχειμάσαντες μὲν ἐν ἀφθόνοις τοῖς ἐπιτηδείοις, περιττὸν δ᾽ ἔχοντες τοῦτο εἴ τι ἐλάβετε παρὰ Σεύθου; τὰ γὰρ τῶν πολεμίων ἐδαπανᾶτε. καὶ ταῦτα πράττοντες οὔτε ἄνδρας ἐπείδετε ὑμῶν αὐτῶν ἀποθανόντας οὔτε ζῶντας ἀπεβάλετε.", "st": "7.6.31"}, {"sp": "N", "t": "εἰ δέ τι καλὸν πρὸς τοὺς ἐν τῆι Ἀσίαι βαρβάρους ἐπέπρακτο ὑμῖν, οὐ καὶ ἐκεῖνο σῶν ἔχετε καὶ πρὸς ἐκείνοις νῦν ἄλλην εὔκλειαν προσειλήφατε καὶ τοὺς ἐν τῆι Εὐρώπηι Θρᾶικας ἐφ᾽ οὓς ἐστρατεύσασθε κρατήσαντες; ἐγὼ μὲν ὑμᾶς φημι δικαίως ἂν ὧν ἐμοὶ χαλεπαίνετε τούτων τοῖς θεοῖς χάριν εἰδέναι ὡς ἀγαθῶν.", "st": "7.6.32"}, {"sp": "N", "t": "καὶ τὰ μὲν δὴ ὑμέτερα τοιαῦτα. ἄγετε δὴ πρὸς θεῶν καὶ τὰ ἐμὰ σκέψασθε ὡς ἔχει. ἐγὼ γὰρ ὅτε μὲν πρότερον ἀπῆια οἴκαδε, ἔχων μὲν ἔπαινον πολὺν πρὸς ὑμῶν ἀπεπορευόμην, ἔχων δὲ δι᾽ ὑμᾶς καὶ ὑπὸ τῶν ἄλλων Ἑλλήνων εὔκλειαν. ἐπιστευόμην δὲ ὑπὸ Λακεδαιμονίων· οὐ γὰρ ἄν με ἔπεμπον πάλιν πρὸς ὑμᾶς.", "st": "7.6.33"}, {"sp": "N", "t": "νῦν δὲ ἀπέρχομαι πρὸς μὲν Λακεδαιμονίους ὑφ᾽ ὑμῶν διαβεβλημένος, Σεύθηι δὲ ἀπηχθημένος ὑπὲρ ὑμῶν, ὃν ἤλπιζον εὖ ποιήσας μεθ᾽ ὑμῶν ἀποστροφὴν καὶ ἐμοὶ καλὴν καὶ παισίν, εἰ γένοιντο, καταθήσεσθαι.", "st": "7.6.34"}, {"sp": "N", "t": "ὑμεῖς δ᾽, ὑπὲρ ὧν ἐγὼ ἀπήχθημαί τε πλεῖστα καὶ ταῦτα πολὺ κρείττοσιν ἐμαυτοῦ, πραγματευόμενός τε οὐδὲ νῦν πω πέπαυμαι ὅ τι δύναμαι ἀγαθὸν ὑμῖν, τοιαύτην ἔχετε γνώμην περὶ ἐμοῦ.", "st": "7.6.35"}, {"sp": "N", "t": "ἀλλ᾽ ἔχετε μέν με οὔτε φεύγοντα λαβόντες οὔτε ἀποδιδράσκοντα· ἢν δὲ ποιήσητε ἃ λέγετε, ἴστε ὅτι ἄνδρα κατακεκονότες ἔσεσθε πολλὰ μὲν δὴ πρὸ ὑμῶν ἀγρυπνήσαντα, πολλὰ δὲ σὺν ὑμῖν πονήσαντα καὶ κινδυνεύσαντα καὶ ἐν τῶι μέρει καὶ παρὰ τὸ μέρος, θεῶν δ᾽ ἵλεων ὄντων καὶ τρόπαια βαρβάρων πολλὰ δὴ σὺν ὑμῖν στησάμενον, ὅπως δέ γε μηδενὶ τῶν Ἑλλήνων πολέμιοι γένησθε, πᾶν ὅσον ἐγὼ ἐδυνάμην πρὸς ὑμᾶς διατεινάμενον.", "st": "7.6.36"}, {"sp": "N", "t": "καὶ γὰρ οὖν νῦν ὑμῖν ἔξεστιν ἀνεπιλήπτως πορεύεσθαι ὅπηι ἂν ἕλησθε καὶ κατὰ γῆν καὶ κατὰ θάλατταν. ὑμεῖς δέ, ὅτε πολλὴ ὑμῖν εὐπορία φαίνεται, καὶ πλεῖτε ἔνθα δὴ ἐπεθυμεῖτε πάλαι, δέονταί τε ὑμῶν οἱ μέγιστον δυνάμενοι, μισθὸς δὲ φαίνεται, ἡγεμόνες δὲ ἥκουσι Λακεδαιμόνιοι οἱ κράτιστοι νομιζόμενοι εἶναι, νῦν δὴ καιρὸς ὑμῖν δοκεῖ εἶναι ὡς τάχιστα ἐμὲ κατακαίνειν;", "st": "7.6.37"}, {"sp": "N", "t": "οὐ μὴν ὅτε γε ἐν τοῖς ἀπόροις ἦμεν, ὦ πάντων μνημονικώτατοι, ἀλλὰ καὶ πατέρα ἐμὲ ἐκαλεῖτε καὶ αἰεὶ ὡς εὐεργέτου μεμνήσεσθαι ὑπισχνεῖσθε. οὐ μέντοι ἀγνώμονες οὐδὲ οὗτοί εἰσιν οἱ νῦν ἥκοντες ἐφ᾽ ὑμᾶς· ὥστε, ὡς ἐγὼ οἶμαι, οὐδὲ τούτοις δοκεῖτε βελτίονες εἶναι τοιοῦτοι ὄντες περὶ ἐμέ.» ταῦτ᾽ εἰπὼν ἐπαύσατο.", "st": "7.6.38"}, {"sp": "N", "t": "Χαρμῖνος δὲ ὁ Λακεδαιμόνιος ἀναστὰς εἶπεν· «οὐ τὼ σιώ, ἀλλ᾽ ἐμοὶ μέντοι οὐ δικαίως δοκεῖτε τῶι ἀνδρὶ τούτωι χαλεπαίνειν· ἔχω γὰρ καὶ αὐτὸς αὐτῶι μαρτυρῆσαι. Σεύθης γὰρ ἐρωτῶντος ἐμοῦ καὶ Πολυνίκου περὶ Ξενοφῶντος τίς ἀνὴρ εἴη ἄλλο μὲν οὐδὲν εἶχε μέμψασθαι, ἄγαν δὲ φιλοστρατιώτην ἔφη αὐτὸν εἶναι· διὸ καὶ χεῖρον αὐτῶι εἶναι πρὸς ἡμῶν τε τῶν Λακεδαιμονίων καὶ πρὸς αὐτοῦ.»", "st": "7.6.39"}, {"sp": "N", "t": "ἀναστὰς ἐπὶ τούτωι Εὐρύλοχος Λουσιάτης Ἀρκὰς εἶπεν· «καὶ δοκεῖ γέ μοι, ἄνδρες Λακεδαιμόνιοι, τοῦτο ὑμᾶς πρῶτον ἡμῶν στρατηγῆσαι, παρὰ Σεύθου ἡμῖν τὸν μισθὸν ἀναπρᾶξαι ἢ ἑκόντος ἢ ἄκοντος, καὶ μὴ πρότερον ἡμᾶς ἀπαγαγεῖν.»", "st": "7.6.40"}, {"sp": "N", "t": "Πολυκράτης δὲ Ἀθηναῖος εἶπεν ἐνετὸς ὑπὸ Ξενοφῶντος· «ὁρῶ γε μήν, ἔφη, ὦ ἄνδρες, καὶ Ἡρακλείδην ἐνταῦθα παρόντα, ὃς παραλαβὼν τὰ χρήματα ἃ ἡμεῖς ἐπονήσαμεν, ταῦτα ἀποδόμενος οὔτε Σεύθηι ἀπέδωκεν οὔτε ἡμῖν τὰ γιγνόμενα, ἀλλ᾽ αὐτὸς κλέψας πέπαται. ἢν οὖν σωφρονῶμεν, ἑξόμεθα αὐτοῦ· οὐ γὰρ δὴ οὗτός γε, ἔφη, Θρᾶιξ ἐστιν, ἀλλ᾽ Ἕλλην ὢν Ἕλληνας ἀδικεῖ.»", "st": "7.6.41"}, {"sp": "N", "t": "ταῦτα ἀκούσας ὁ Ἡρακλείδης μάλα ἐξεπλάγη· καὶ προσελθὼν τῶι Σεύθηι λέγει· «ἡμεῖς ἢν σωφρονῶμεν, ἄπιμεν ἐντεῦθεν ἐκ τῆς τούτων ἐπικρατείας.» καὶ ἀναβάντες ἐπὶ τοὺς ἵππους ὤιχοντο ἀπελαύνοντες εἰς τὸ ἑαυτῶν στρατόπεδον.", "st": "7.6.42"}, {"sp": "N", "t": "καὶ ἐντεῦθεν Σεύθης πέμπει Ἀβροζέλμην τὸν ἑαυτοῦ ἑρμηνέα πρὸς Ξενοφῶντα καὶ κελεύει αὐτὸν καταμεῖναι παρ᾽ ἑαυτῶι ἔχοντα χιλίους ὁπλίτας, καὶ ὑπισχνεῖται αὐτῶι ἀποδώσειν τά τε χωρία τὰ ἐπὶ θαλάττηι καὶ τὰ ἄλλα ἃ ὑπέσχετο. καὶ ἐν ἀπορρήτωι ποιησάμενος λέγει ὅτι ἀκήκοε Πολυνίκου ὡς εἰ ὑποχείριος ἔσται Λακεδαιμονίοις, σαφῶς ἀποθανοῖτο ὑπὸ Θίβρωνος.", "st": "7.6.43"}, {"sp": "N", "t": "ἐπέστελλον δὲ ταῦτα καὶ ἄλλοι πολλοὶ τῶι Ξενοφῶντι ὡς διαβεβλημένος εἴη καὶ φυλάττεσθαι δέοι. ὁ δὲ ἀκούων ταῦτα δύο ἱερεῖα λαβὼν ἐθύετο τῶι Διὶ τῶι βασιλεῖ πότερά οἱ λῶιον καὶ ἄμεινον εἴη μένειν παρὰ Σεύθηι ἐφ᾽ οἷς Σεύθης λέγει ἢ ἀπιέναι σὺν τῶι στρατεύματι. ἀναιρεῖ αὐτῶι ἀπιέναι.", "st": "7.6.44"}, {"sp": "N", "t": "ἐντεῦθεν Σεύθης μὲν ἀπεστρατοπεδεύσατο προσωτέρω· οἱ δὲ Ἕλληνες ἐσκήνησαν εἰς κώμας ὅθεν ἔμελλον πλεῖστα ἐπισιτισάμενοι ἐπὶ θάλατταν ἥξειν. αἱ δὲ κῶμαι αὗται ἦσαν δεδομέναι ὑπὸ Σεύθου Μηδοσάδηι.", "st": "7.7.1"}, {"sp": "N", "t": "ὁρῶν οὖν ὁ Μηδοσάδης δαπανώμενα τὰ ἑαυτοῦ ἐν ταῖς κώμαις ὑπὸ τῶν Ἑλλήνων χαλεπῶς ἔφερε· καὶ λαβὼν ἄνδρα Ὀδρύσην δυνατώτατον τῶν ἄνωθεν καταβεβηκότων καὶ ἱππέας ὅσον τριάκοντα ἔρχεται καὶ προκαλεῖται Ξενοφῶντα ἐκ τοῦ Ἑλληνικοῦ στρατεύματος. καὶ ὃς λαβών τινας τῶν λοχαγῶν καὶ ἄλλους τῶν ἐπιτηδείων προσέρχεται.", "st": "7.7.2"}, {"sp": "N", "t": "ἔνθα δὴ λέγει Μηδοσάδης· «ἀδικεῖτε, ὦ Ξενοφῶν, τὰς ἡμετέρας κώμας πορθοῦντες. προλέγομεν οὖν ὑμῖν, ἐγώ τε ὑπὲρ Σεύθου καὶ ὅδε ἁνὴρ παρὰ Μηδόκου ἥκων τοῦ ἄνω βασιλέως, ἀπιέναι ἐκ τῆς χώρας· εἰ δὲ μή, οὐκ ἐπιτρέψομεν ὑμῖν, ἀλλ᾽ ἐὰν ποιῆτε κακῶς τὴν ἡμετέραν χώραν, ὡς πολεμίους ἀλεξόμεθα.»", "st": "7.7.3"}, {"sp": "N", "t": "ὁ δὲ Ξενοφῶν ἀκούσας ταῦτα εἶπεν· «ἀλλὰ σοὶ μὲν τοιαῦτα λέγοντι καὶ ἀποκρίνασθαι χαλεπόν· τούτου δ᾽ ἕνεκα τοῦ νεανίσκου λέξω, ἵν᾽ εἰδῆι οἷοί τε ὑμεῖς ἐστε καὶ οἷοι ἡμεῖς.", "st": "7.7.4"}, {"sp": "N", "t": "ἡμεῖς μὲν γάρ, ἔφη, πρὶν ὑμῖν φίλοι γενέσθαι ἐπορευόμεθα διὰ ταύτης τῆς χώρας ὅποι ἐβουλόμεθα, ἣν μὲν ἐθέλοιμεν πορθοῦντες,", "st": "7.7.5"}, {"sp": "N", "t": "ἣν δὲ θέλοιμεν καίοντες, καὶ σὺ ὁπότε πρὸς ἡμᾶς ἔλθοις πρεσβεύων, ηὐλίζου τότε παρ᾽ ἡμῖν οὐδένα φοβούμενος τῶν πολεμίων· ὑμεῖς δὲ οὐκ ἦιτε εἰς τήνδε τὴν χώραν, ἢ εἴ ποτε ἔλθοιτε, ὡς ἐν κρειττόνων χώραι ηὐλίζεσθε ἐγκεχαλινωμένοις τοῖς ἵπποις.", "st": "7.7.6"}, {"sp": "N", "t": "ἐπεὶ δὲ ἡμῖν φίλοι ἐγένεσθε καὶ δι᾽ ἡμᾶς σὺν θεοῖς ἔχετε τήνδε τὴν χώραν, νῦν δὴ ἐξελαύνετε ἡμᾶς ἐκ τῆσδε τῆς χώρας ἣν παρ᾽ ἡμῶν, ἐχόντων κατὰ κράτος, παρελάβετε· ὡς γὰρ αὐτὸς οἶσθα, οἱ πολέμιοι οὐχ ἱκανοὶ ἦσαν ἡμᾶς ἐξελαύνειν.", "st": "7.7.7"}, {"sp": "N", "t": "καὶ οὐχ ὅπως δῶρα δοὺς καὶ εὖ ποιήσας ἀνθ᾽ ὧν εὖ ἔπαθες ἀξιοῖς ἡμᾶς ἀποπέμψασθαι, ἀλλ᾽ ἀποπορευομένους ἡμᾶς οὐδ᾽ ἐναυλισθῆναι ὅσον δύνασαι ἐπιτρέπεις.", "st": "7.7.8"}, {"sp": "N", "t": "καὶ ταῦτα λέγων οὔτε θεοὺς αἰσχύνηι οὔτε τόνδε τὸν ἄνδρα, ὃς νῦν μέν σε ὁρᾶι πλουτοῦντα, πρὶν δὲ ἡμῖν φίλον γενέσθαι ἀπὸ ληιστείας τὸν βίον ἔχοντα, ὡς αὐτὸς ἔφησθα.", "st": "7.7.9"}, {"sp": "N", "t": "ἀτὰρ τί καὶ πρὸς ἐμὲ λέγεις ταῦτα; ἔφη· οὐ γὰρ ἔγωγ᾽ ἔτι ἄρχω, ἀλλὰ Λακεδαιμόνιοι, οἷς ὑμεῖς παρεδώκατε τὸ στράτευμα ἀπαγαγεῖν οὐδὲν ἐμὲ παρακαλέσαντες, ὦ θαυμαστότατοι, ὅπως ὥσπερ ἀπηχθανόμην αὐτοῖς ὅτε πρὸς ὑμᾶς ἦγον, οὕτω καὶ χαρισαίμην νῦν ἀποδιδούς.»", "st": "7.7.10"}, {"sp": "N", "t": "ἐπεὶ ταῦτα ἤκουσεν ὁ Ὀδρύσης, εἶπεν· «ἐγὼ μέν, ὦ Μηδόσαδες, κατὰ τῆς γῆς καταδύομαι ὑπὸ τῆς αἰσχύνης ἀκούων ταῦτα. καὶ εἰ μὲν πρόσθεν ἠπιστάμην, οὐδ᾽ ἂν συνηκολούθησά σοι· καὶ νῦν ἄπειμι. οὐδὲ γὰρ ἂν Μήδοκός με ὁ βασιλεὺς ἐπαινοίη, εἰ ἐξελαύνοιμι τοὺς εὐεργέτας.»", "st": "7.7.11"}, {"sp": "N", "t": "ταῦτ᾽ εἰπὼν ἀναβὰς ἐπὶ τὸν ἵππον ἀπήλαυνε καὶ σὺν αὐτῶι οἱ ἄλλοι ἱππεῖς πλὴν τεττάρων ἢ πέντε. ὁ δὲ Μηδοσάδης (ἐλύπει γὰρ αὐτὸν ἡ χώρα πορθουμένη), ἐκέλευε τὸν Ξενοφῶντα καλέσαι τὼ Λακεδαιμονίω.", "st": "7.7.12"}, {"sp": "N", "t": "καὶ ὃς λαβὼν τοὺς ἐπιτηδειοτάτους προσῆλθε τῶι Χαρμίνωι καὶ Πολυνίκωι καὶ ἔλεγεν ὅτι καλεῖ αὐτοὺς Μηδοσάδης προερῶν ἅπερ αὐτῶι, ἀπιέναι ἐκ τῆς χώρας.", "st": "7.7.13"}, {"sp": "N", "t": "οἴομαι ἂν οὖν, ἔφη, ὑμᾶς ἀπολαβεῖν τῆι στρατιᾶι τὸν ὀφειλόμενον μισθόν, εἰ εἴποιτε ὅτι δεδέηται ὑμῶν ἡ στρατιὰ συναναπρᾶξαι τὸν μισθὸν ἢ παρ᾽ ἑκόντος ἢ παρ᾽ ἄκοντος Σεύθου, καὶ ὅτι τούτων τυχόντες προθύμως ἂν συνέπεσθαι ὑμῖν φασι· καὶ ὅτι δίκαια ὑμῖν δοκοῦσι λέγειν· καὶ ὅτι ὑπέσχεσθε αὐτοῖς τότε ἀπιέναι ὅταν τὰ δίκαια ἔχωσιν οἱ στρατιῶται.", "st": "7.7.14"}, {"sp": "N", "t": "ἀκούσαντες οἱ Λάκωνες ταῦτα ἔφασαν ἐρεῖν καὶ ἄλλα ὁποῖα ἂν δύνωνται κράτιστα· καὶ εὐθὺς ἐπορεύοντο ἔχοντες πάντας τοὺς ἐπικαιρίους. ἐλθὼν δὲ ἔλεξε Χαρμῖνος· «εἰ μὲν σύ τι ἔχεις, ὦ Μηδόσαδες, πρὸς ἡμᾶς λέγειν, εἰ δὲ μή, ἡμεῖς πρὸς σὲ ἔχομεν.»", "st": "7.7.15"}, {"sp": "N", "t": "ὁ δὲ Μηδοσάδης μάλα δὴ ὑφειμένως· «ἀλλ᾽ ἐγὼ μὲν λέγω, ἔφη, καὶ Σεύθης τὰ αὐτά, ὅτι ἀξιοῦμεν τοὺς φίλους ἡμῖν γεγενημένους μὴ κακῶς πάσχειν ὑφ᾽ ὑμῶν. ὅ τι γὰρ ἂν τούτους κακῶς ποιῆτε ἡμᾶς ἤδη ποιεῖτε· ἡμέτεροι γάρ εἰσιν.»", "st": "7.7.16"}, {"sp": "N", "t": "«ἡμεῖς τοίνυν, ἔφασαν οἱ Λάκωνες, ἀπίοιμεν ἂν ὁπότε τὸν μισθὸν ἔχοιεν οἱ ταῦτα ὑμῖν καταπράξαντες· εἰ δὲ μή, ἐρχόμεθα μὲν καὶ νῦν βοηθήσοντες τούτοις καὶ τιμωρησόμενοι ἄνδρας οἳ τούτους παρὰ τοὺς ὅρκους ἠδίκησαν. ἢν δὲ δὴ καὶ ὑμεῖς τοιοῦτοι ἦτε, ἐνθένδε ἀρξόμεθα τὰ δίκαια λαμβάνειν.»", "st": "7.7.17"}, {"sp": "N", "t": "ὁ δὲ Ξενοφῶν εἶπεν· «ἐθέλοιτε ἂν τούτοις, ὦ Μηδόσαδες, ἐπιτρέψαι, ἐπειδὴ φίλους ἔφατε εἶναι ὑμῖν, ἐν ὧν τῆι χώραι ἐσμέν, ὁπότερ᾽ ἂν ψηφίσωνται, εἴθ᾽ ὑμᾶς προσῆκεν ἐκ τῆς χώρας ἀπιέναι εἴθ᾽ ἡμᾶς;»", "st": "7.7.18"}, {"sp": "N", "t": "ὁ δὲ ταῦτα μὲν οὐκ ἔφη· ἐκέλευε δὲ μάλιστα μὲν αὐτὼ τὼ Λάκωνε ἐλθεῖν παρὰ Σεύθην περὶ τοῦ μισθοῦ, καὶ οἴεσθαι ἂν Σεύθην πεῖσαι· εἰ δὲ μή, Ξενοφῶντα σὺν αὐτῶι πέμπειν, καὶ συμπράξειν ὑπισχνεῖτο. ἐδεῖτο δὲ τὰς κώμας μὴ καίειν.", "st": "7.7.19"}, {"sp": "N", "t": "ἐντεῦθεν πέμπουσι Ξενοφῶντα καὶ σὺν αὐτῶι οἳ ἐδόκουν ἐπιτηδειότατοι εἶναι. ὁ δὲ ἐλθὼν λέγει πρὸς Σεύθην· «οὐδὲν ἀπαιτήσων, ὦ Σεύθη, πάρειμι, ἀλλὰ διδάξων, ἢν δύνωμαι,", "st": "7.7.20"}, {"sp": "N", "t": "ὡς οὐ δικαίως μοι ἠχθέσθης ὅτι ὑπὲρ τῶν στρατιωτῶν ἀπήιτουν σε προθύμως ἃ ὑπέσχου αὐτοῖς· σοὶ γὰρ ἔγωγε οὐχ ἧττον ἐνόμιζον σύμφορον εἶναι ἀποδοῦναι ἢ ἐκείνοις ἀπολαβεῖν.", "st": "7.7.21"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ οἶδα μετὰ τοὺς θεοὺς εἰς τὸ φανερόν σε τούτους καταστήσαντας, ἐπεί γε βασιλέα σε ἐποίησαν πολλῆς χώρας καὶ πολλῶν ἀνθρώπων· ὥστε οὐχ οἷόν τέ σοι λανθάνειν οὔτε ἤν τι καλὸν οὔτε ἤν τι αἰσχρὸν ποιήσηις.", "st": "7.7.22"}, {"sp": "N", "t": "τοιούτωι δὲ ὄντι ἀνδρὶ μέγα μέν μοι ἐδόκει εἶναι μὴ δοκεῖν ἀχαρίστως ἀποπέμψασθαι ἄνδρας εὐεργέτας, μέγα δὲ εὖ ἀκούειν ὑπὸ ἑξακισχιλίων ἀνθρώπων, τὸ δὲ μέγιστον μηδαμῶς ἄπιστον σαυτὸν καταστῆσαι ὅ τι λέγοις.", "st": "7.7.23"}, {"sp": "N", "t": "ὁρῶ γὰρ τῶν μὲν ἀπίστων ματαίους καὶ ἀδυνάτους καὶ ἀτίμους τοὺς λόγους πλανωμένους· οἳ δ᾽ ἂν φανεροὶ ὦσιν ἀλήθειαν ἀσκοῦντες, τούτων οἱ λόγοι, ἤν τι δέωνται, οὐδὲν μεῖον δύνανται ἁνύσασθαι ἢ ἄλλων ἡ βία· ἤν τέ τινας σωφρονίζειν βούλωνται, γιγνώσκω τὰς τούτων ἀπειλὰς οὐχ ἧττον σωφρονιζούσας ἢ ἄλλων τὸ ἤδη κολάζειν· ἤν τέ τώι τι ὑπισχνῶνται οἱ τοιοῦτοι ἄνδρες, οὐδὲν μεῖον διαπράττονται ἢ ἄλλοι παραχρῆμα διδόντες·", "st": "7.7.24"}, {"sp": "N", "t": "ἀναμνήσθητι δὲ καὶ σὺ τί προτελέσας ἡμῖν συμμάχους ἡμᾶς ἔλαβες. οἶσθ᾽ ὅτι οὐδέν· ἀλλὰ πιστευθεὶς ἀληθεύσειν ἃ ἔλεγες ἐπῆρας τοσούτους ἀνθρώπους συστρατεύεσθαί τε καὶ κατεργάσασθαί σοι ἀρχὴν οὐ τριάκοντα μόνον ἀξίαν ταλάντων, ὅσα οἴονται δεῖν οὗτοι νῦν ἀπολαβεῖν, ἀλλὰ πολλαπλασίων.", "st": "7.7.25"}, {"sp": "N", "t": "οὐκοῦν τοῦτο μὲν πρῶτον τὸ πιστεύεσθαι, τὸ καὶ τὴν βασιλείαν σοι κατεργασάμενον, τούτων τῶν χρημάτων πιπράσκεται.", "st": "7.7.26"}, {"sp": "N", "t": "ἴθι δὴ ἀναμνήσθητι πῶς μέγα ἡγοῦ τότε καταπρᾶξαι ἃ νῦν καταστρεψάμενος ἔχεις. ἐγὼ μὲν εὖ οἶδ᾽ ὅτι ηὔξω ἂν τὰ νῦν πεπραγμένα μᾶλλόν σοι καταπραχθῆναι ἢ πολλαπλάσια τούτων τῶν χρημάτων γενέσθαι.", "st": "7.7.27"}, {"sp": "N", "t": "ἐμοὶ τοίνυν μεῖζον βλάβος καὶ αἴσχιον δοκεῖ εἶναι τὸ ταῦτα νῦν μὴ κατασχεῖν ἢ τότε μὴ λαβεῖν, ὅσωιπερ χαλεπώτερον ἐκ πλουσίου πένητα γενέσθαι ἢ ἀρχὴν μὴ πλουτῆσαι, καὶ ὅσωι λυπηρότερον ἐκ βασιλέως ἰδιώτην φανῆναι ἢ ἀρχὴν μὴ βασιλεῦσαι.", "st": "7.7.28"}, {"sp": "N", "t": "οὐκοῦν ἐπίστασαι μὲν ὅτι οἱ νῦν σοι ὑπήκοοι γενόμενοι οὐ φιλίαι τῆι σῆι ἐπείσθησαν ὑπὸ σοῦ ἄρχεσθαι ἀλλ᾽ ἀνάγκηι, καὶ ὅτι ἐπιχειροῖεν ἂν πάλιν ἐλεύθεροι γίγνεσθαι, εἰ μή τις αὐτοὺς φόβος κατέχοι.", "st": "7.7.29"}, {"sp": "N", "t": "ποτέρως οὖν οἴει μᾶλλον ἂν φοβεῖσθαί τε αὐτοὺς καὶ σωφρονεῖν τὰ πρὸς σέ, εἰ ὁρῶιέν σοι τοὺς στρατιώτας οὕτω διακειμένους ὡς νῦν τε μένοντας ἄν, εἰ σὺ κελεύοις, αὖθίς τ᾽ ἂν ταχὺ ἐλθόντας, εἰ δέοι, ἄλλους τε τούτων περὶ σοῦ ἀκούοντας πολλὰ ἀγαθὰ ταχὺ ἄν σοι ὁπότε βούλοιο παραγενέσθαι, ἢ εἰ καταδοξάσειαν μήτ᾽ ἂν ἄλλους σοι ἐλθεῖν δι᾽ ἀπιστίαν ἐκ τῶν νῦν γεγενημένων τούτους τε αὐτοῖς εὐνουστέρους εἶναι ἢ σοί;", "st": "7.7.30"}, {"sp": "N", "t": "ἀλλὰ μὴν οὐδὲ πλήθει γε ἡμῶν λειφθέντες ὑπεῖξάν σοι, ἀλλὰ προστατῶν ἀπορίαι. οὐκοῦν νῦν καὶ τοῦτο κίνδυνος μὴ λάβωσι προστάτας αὑτῶν τινας τούτων οἳ νομίζουσιν ὑπὸ σοῦ ἀδικεῖσθαι, ἢ καὶ τούτων κρείττονας τοὺς Λακεδαιμονίους, ἐὰν μὲν οἱ στρατιῶται ὑπισχνῶνται προθυμότερον αὐτοῖς συστρατεύσεσθαι, ἂν τὰ παρὰ σοῦ νῦν ἀναπράξωσιν, οἱ δὲ Λακεδαιμόνιοι διὰ τὸ δεῖσθαι τῆς στρατιᾶς συναινέσωσιν αὐτοῖς ταῦτα.", "st": "7.7.31"}, {"sp": "N", "t": "ὅτι γε μὴν οἱ νῦν ὑπὸ σοὶ Θρᾶικες γενόμενοι πολὺ ἂν προθυμότερον ἴοιεν ἐπί σε ἢ σύν σοι οὐκ ἄδηλον· σοῦ μὲν γὰρ κρατοῦντος δουλεία ὑπάρχει αὐτοῖς, κρατουμένου δέ σου ἐλευθερία.", "st": "7.7.32"}, {"sp": "N", "t": "εἰ δὲ καὶ τῆς χώρας προνοεῖσθαι ἤδη τι δεῖ ὡς σῆς οὔσης, ποτέρως ἂν οἴει ἀπαθῆ κακῶν μᾶλλον αὐτὴν εἶναι, εἰ οὗτοι οἱ στρατιῶται ἀπολαβόντες ἃ ἐγκαλοῦσιν εἰρήνην καταλιπόντες οἴχοιντο, ἢ εἰ οὗτοί τε μένοιεν ὡς ἐν πολεμίαι σύ τε ἄλλους πειρῶιο πλέονας τούτων ἔχων ἀντιστρατοπεδεύεσθαι δεομένους τῶν ἐπιτηδείων;", "st": "7.7.33"}, {"sp": "N", "t": "ἀργύριον δὲ ποτέρως ἂν πλέον ἀναλωθείη, εἰ τούτοις τὸ ὀφειλόμενον ἀποδοθείη, ἢ εἰ ταῦτά τε ὀφείλοιντο ἄλλους τε κρείττονας δέοι σε μισθοῦσθαι;", "st": "7.7.34"}, {"sp": "N", "t": "ἀλλὰ γὰρ Ἡρακλείδηι, ὡς πρὸς ἐμὲ ἐδήλου, πάμπολυ δοκεῖ τοῦτο τὸ ἀργύριον εἶναι. ἦ μὴν πολύ γέ ἐστιν ἔλαττον νῦν σοι καὶ λαβεῖν τοῦτο καὶ ἀποδοῦναι ἢ πρὶν ἡμᾶς ἐλθεῖν πρὸς σὲ δέκατον τούτου μέρος.", "st": "7.7.35"}, {"sp": "N", "t": "οὐ γὰρ ἀριθμός ἐστιν ὁ ὁρίζων τὸ πολὺ καὶ τὸ ὀλίγον, ἀλλ᾽ ἡ δύναμις τοῦ τε ἀποδιδόντος καὶ λαμβάνοντος. σοὶ δὲ νῦν ἡ κατ᾽ ἐνιαυτὸν πρόσοδος πλείων ἔσται ἢ ἔμπροσθεν τὰ παρόντα πάντα ἃ ἐκέκτησο.", "st": "7.7.36"}, {"sp": "N", "t": "ἐγὼ μέν, ὦ Σεύθη, ταῦτα ὡς φίλου ὄντος σου προυνοούμην, ὅπως σύ τε ἄξιος δοκοίης εἶναι ὧν οἱ θεοί σοι ἔδωκαν ἀγαθῶν ἐγώ τε μὴ διαφθαρείην ἐν τῆι στρατιᾶι.", "st": "7.7.37"}, {"sp": "N", "t": "εὖ γὰρ ἴσθι ὅτι νῦν ἐγὼ οὔτ᾽ ἂν ἐχθρὸν βουλόμενος κακῶς ποιῆσαι δυνηθείην σὺν ταύτηι τῆι στρατιᾶι οὔτ᾽ ἂν εἴ σοι πάλιν βουλοίμην βοηθῆσαι, ἱκανὸς ἂν γενοίμην. οὕτω γὰρ πρός με ἡ στρατιὰ διάκειται.", "st": "7.7.38"}, {"sp": "N", "t": "καίτοι αὐτόν σε μάρτυρα σὺν θεοῖς εἰδόσι ποιοῦμαι ὅτι οὔτε ἔχω παρὰ σοῦ ἐπὶ τοῖς στρατιώταις οὐδὲν οὔτε ἤιτησα πώποτε εἰς τὸ ἴδιον τὰ ἐκείνων οὔτε ἃ ὑπέσχου μοι ἀπήιτησα·", "st": "7.7.39"}, {"sp": "N", "t": "ὄμνυμι δέ σοι μηδὲ ἀποδιδόντος δέξασθαι ἄν, εἰ μὴ καὶ οἱ στρατιῶται ἔμελλον τὰ ἑαυτῶν συναπολαμβάνειν. αἰσχρὸν γὰρ ἦν τὰ μὲν ἐμὰ διαπεπρᾶχθαι, τὰ δ᾽ ἐκείνων περιιδεῖν κακῶς ἔχοντα ἄλλως τε καὶ τιμώμενον ὑπ᾽ ἐκείνων.", "st": "7.7.40"}, {"sp": "N", "t": "καίτοι Ἡρακλείδηι γε λῆρος πάντα δοκεῖ εἶναι πρὸς τὸ ἀργύριον ἔχειν ἐκ παντὸς τρόπου· ἐγὼ δέ, ὦ Σεύθη, οὐδὲν νομίζω ἀνδρὶ ἄλλως τε καὶ ἄρχοντι κάλλιον εἶναι κτῆμα οὐδὲ λαμπρότερον ἀρετῆς καὶ δικαιοσύνης καὶ γενναιότητος.", "st": "7.7.41"}, {"sp": "N", "t": "ὁ γὰρ ταῦτα ἔχων πλουτεῖ μὲν ὄντων φίλων πολλῶν, πλουτεῖ δὲ ἄλλων βουλομένων γενέσθαι, καὶ εὖ μὲν πράττων ἔχει τοὺς συνησθησομένους, ἐὰν δέ τι σφαλῆι, οὐ σπανίζει τῶν βοηθησόντων.", "st": "7.7.42"}, {"sp": "N", "t": "ἀλλὰ γὰρ εἰ μήτε ἐκ τῶν ἔργων κατέμαθες ὅτι σοι ἐκ τῆς ψυχῆς φίλος ἦν, μήτε ἐκ τῶν ἐμῶν λόγων δύνασαι τοῦτο γνῶναι, ἀλλὰ τοὺς τῶν στρατιωτῶν λόγους πάντας κατανόησον· παρῆσθα γὰρ καὶ ἤκουες ἃ ἔλεγον οἱ ψέγειν ἐμὲ βουλόμενοι.", "st": "7.7.43"}, {"sp": "N", "t": "κατηγόρουν γάρ μου πρὸς Λακεδαιμονίους ὡς σὲ περὶ πλείονος ποιοίμην ἢ Λακεδαιμονίους, αὐτοὶ δ᾽ ἐνεκάλουν ἐμοὶ ὡς μᾶλλον μέλει μοι ὅπως τὰ σὰ καλῶς ἔχοι ἢ ὅπως τὰ ἑαυτῶν· ἔφασαν δέ με καὶ δῶρα ἔχειν παρὰ σοῦ.", "st": "7.7.44"}, {"sp": "N", "t": "καίτοι τὰ δῶρα ταῦτα πότερον οἴει αὐτοὺς κακόνοιάν τινα ἐνιδόντας μοι πρὸς σὲ αἰτιᾶσθαί με ἔχειν παρὰ σοῦ ἢ προθυμίαν πολλὴν περὶ σὲ κατανοήσαντας;", "st": "7.7.45"}, {"sp": "N", "t": "ἐγὼ μὲν οἶμαι πάντας ἀνθρώπους νομίζειν εὔνοιαν δεῖν ἀποδείκνυσθαι τούτωι παρ᾽ οὗ ἂν δῶρά τις λαμβάνηι. σὺ δὲ πρὶν μὲν ὑπηρετῆσαί τί σοι ἐμὲ ἐδέξω ἡδέως καὶ ὄμμασι καὶ φωνῆι καὶ ξενίοις καὶ ὅσα ἔσοιτο ὑπισχνούμενος οὐκ ἐνεπίμπλασο· ἐπεὶ δὲ κατέπραξας ἃ ἐβούλου καὶ γεγένησαι ὅσον ἐγὼ ἐδυνάμην μέγιστος, νῦν οὕτω με ἄτιμον ὄντα ἐν τοῖς στρατιώταις τολμᾶις περιορᾶν;", "st": "7.7.46"}, {"sp": "N", "t": "ἀλλὰ μὴν ὅτι σοι δόξει ἀποδοῦναι πιστεύω καὶ τὸν χρόνον διδάξειν σε καὶ αὐτόν γέ σε οὐχὶ ἀνέξεσθαι τοὺς σοὶ προεμένους εὐεργεσίαν ὁρῶντά σοι ἐγκαλοῦντας. δέομαι οὖν σου, ὅταν ἀποδιδῶις, προθυμεῖσθαι ἐμὲ παρὰ τοῖς στρατιώταις τοιοῦτον ποιῆσαι οἷόνπερ καὶ παρέλαβες.»", "st": "7.7.47"}, {"sp": "N", "t": "ἀκούσας ταῦτα ὁ Σεύθης κατηράσατο τῶι αἰτίωι τοῦ μὴ πάλαι ἀποδεδόσθαι τὸν μισθόν· καὶ πάντες Ἡρακλείδην τοῦτον ὑπώπτευσαν εἶναι· «ἐγὼ γάρ, ἔφη, οὔτε διενοήθην πώποτε ἀποστερῆσαι ἀποδώσω τε.»", "st": "7.7.48"}, {"sp": "N", "t": "ἐντεῦθεν πάλιν εἶπεν ὁ Ξενοφῶν· «ἐπεὶ τοίνυν διανοῆι ἀποδιδόναι, νῦν ἐγώ σου δέομαι δι᾽ ἐμοῦ ἀποδοῦναι, καὶ μὴ περιιδεῖν με διὰ σὲ ἀνομοίως ἔχοντα ἐν τῆι στρατιᾶι νῦν τε καὶ ὅτε πρὸς σὲ ἀφικόμεθα.»", "st": "7.7.49"}, {"sp": "N", "t": "ὁ δ᾽ εἶπεν· «ἀλλ᾽ οὔτ᾽ ἐν τοῖς στρατιώταις ἔσει δι᾽ ἐμὲ ἀτιμότερος ἄν τε μένηις παρ᾽ ἐμοὶ χιλίους μόνους ὁπλίτας ἔχων, ἐγώ σοι τά τε χωρία ἀποδώσω καὶ τἆλλα ἃ ὑπεσχόμην.»", "st": "7.7.50"}, {"sp": "N", "t": "ὁ δὲ πάλιν εἶπε· «ταῦτα μὲν ἔχειν οὕτως οὐχ οἷόν τε· ἀπόπεμπε δὲ ἡμᾶς.» «καὶ μήν, ἔφη ὁ Σεύθης, καὶ ἀσφαλέστερόν γέ σοι οἶδα ὂν παρ᾽ ἐμοὶ μένειν ἢ ἀπιέναι.»", "st": "7.7.51"}, {"sp": "N", "t": "ὁ δὲ πάλιν εἶπεν· «ἀλλὰ τὴν μὲν σὴν πρόνοιαν ἐπαινῶ· ἐμοὶ δὲ μένειν οὐχ οἷόν τε· ὅπου δ᾽ ἂν ἐγὼ ἐντιμότερος ὦ, νόμιζε καὶ σοὶ τοῦτο ἀγαθὸν ἔσεσθαι.»", "st": "7.7.52"}, {"sp": "N", "t": "ἐντεῦθεν λέγει Σεύθης· «ἀργύριον μὲν οὐκ ἔχω ἀλλ᾽ ἢ μικρόν τι, καὶ τοῦτό σοι δίδωμι, τάλαντον· βοῦς δὲ ἑξακοσίους καὶ πρόβατα εἰς τετρακισχίλια καὶ ἀνδράποδα εἰς εἴκοσι καὶ ἑκατόν. ταῦτα λαβὼν καὶ τοὺς τῶν ἀδικησάντων σε ὁμήρους προσλαβὼν ἄπιθι.»", "st": "7.7.53"}, {"sp": "N", "t": "γελάσας ὁ Ξενοφῶν εἶπεν· «ἢν οὖν μὴ ἐξικνῆται ταῦτ᾽ εἰς τὸν μισθόν, τίνος τάλαντον φήσω ἔχειν; ἆρ᾽ οὐκ, ἐπειδὴ καὶ ἐπικίνδυνόν μοί ἐστιν, ἀπιόντα γε ἄμεινον φυλάττεσθαι πέτρους; ἤκουες δὲ τὰς ἀπειλάς.» τότε μὲν δὴ αὐτοῦ ἔμεινε.", "st": "7.7.54"}, {"sp": "N", "t": "τῆι δ᾽ ὑστεραίαι ἀπέδωκέ τε αὐτοῖς ἃ ὑπέσχετο καὶ τοὺς ἐλῶντας συνέπεμψεν. οἱ δὲ στρατιῶται τέως μὲν ἔλεγον ὡς ὁ Ξενοφῶν οἴχοιτο ὡς Σεύθην οἰκήσων καὶ ἃ ὑπέσχετο αὐτῶι ληψόμενος· ἐπεὶ δὲ εἶδον, ἥσθησαν καὶ προσέθεον.", "st": "7.7.55"}, {"sp": "N", "t": "Ξενοφῶν δ᾽ ἐπεὶ εἶδε Χαρμῖνόν τε καὶ Πολύνικον· «ταῦτα, ἔφη, σέσωσται δι᾽ ὑμᾶς τῆι στρατιᾶι καὶ παραδίδωμι αὐτὰ ἐγὼ ὑμῖν· ὑμεῖς δὲ διαθέμενοι διάδοτε τῆι στρατιᾶι.» οἱ μὲν οὖν παραλαβόντες καὶ λαφυροπώλας καταστήσαντες ἐπώλουν, καὶ πολλὴν εἶχον αἰτίαν.", "st": "7.7.56"}, {"sp": "N", "t": "Ξενοφῶν δὲ οὐ προσήιει, ἀλλὰ φανερὸς ἦν οἴκαδε παρασκευαζόμενος· οὐ γάρ πω ψῆφος αὐτῶι ἐπῆκτο Ἀθήνησι περὶ φυγῆς. προσελθόντες δὲ αὐτῶι οἱ ἐπιτήδειοι ἐν τῶι στρατοπέδωι ἐδέοντο μὴ ἀπελθεῖν πρὶν ἀπαγάγοι τὸ στράτευμα καὶ Θίβρωνι παραδοίη.", "st": "7.7.57"}, {"sp": "N", "t": "ἐντεῦθεν διέπλευσαν εἰς Λάμψακον, καὶ ἀπαντᾶι τῶι Ξενοφῶντι Εὐκλείδης μάντις Φλειάσιος ὁ Κλεαγόρου υἱὸς τοῦ τὰ ἐντοίχια ἐν Λυκείωι γεγραφότος. οὗτος συνήδετο τῶι Ξενοφῶντι ὅτι ἐσέσωστο, καὶ ἠρώτα αὐτὸν πόσον χρυσίον ἔχοι.", "st": "7.8.1"}, {"sp": "N", "t": "ὁ δ᾽ αὐτῶι ἐπομόσας εἶπεν ἦ μὴν ἔσεσθαι μηδὲ ἐφόδιον ἱκανὸν οἴκαδε ἀπιόντι, εἰ μὴ ἀπόδοιτο τὸν ἵππον καὶ ἃ ἀμφ᾽ αὑτὸν εἶχεν.", "st": "7.8.2"}, {"sp": "N", "t": "ὁ δ᾽ αὐτῶι οὐκ ἐπίστευεν. ἐπεὶ δ᾽ ἔπεμψαν Λαμψακηνοὶ ξένια τῶι Ξενοφῶντι καὶ ἔθυε τῶι Ἀπόλλωνι, παρεστήσατο τὸν Εὐκλείδην· ἰδὼν δὲ τὰ ἱερὰ ὁ Εὐκλείδης εἶπεν ὅτι πείθοιτο αὐτῶι μὴ εἶναι χρήματα. «ἀλλ᾽ οἶδα, ἔφη, ὅτι κἂν μέλληι ποτὲ ἔσεσθαι, φαίνεταί τι ἐμπόδιον, ἂν μηδὲν ἄλλο, σὺ σαυτῶι.» συνωμολόγει ταῦτα ὁ Ξενοφῶν.", "st": "7.8.3"}, {"sp": "N", "t": "ὁ δὲ εἶπεν· «ἐμπόδιος γάρ σοι ὁ Ζεὺς ὁ μειλίχιός ἐστι», καὶ ἐπήρετο εἰ ἤδη θύσειεν, «ὥσπερ οἴκοι, ἔφη, εἰώθειν ἐγὼ ὑμῖν θύεσθαι καὶ ὁλοκαυτεῖν.» ὁ δ᾽ οὐκ ἔφη ἐξ ὅτου ἀπεδήμησε τεθυκέναι τούτωι τῶι θεῶι. συνεβούλευσεν οὖν αὐτῶι θύεσθαι καθὰ εἰώθει, καὶ ἔφη συνοίσειν ἐπὶ τὸ βέλτιον.", "st": "7.8.4"}, {"sp": "N", "t": "τῆι δὲ ὑστεραίαι Ξενοφῶν προσελθὼν εἰς Ὀφρύνιον ἐθύετο καὶ ὡλοκαύτει χοίρους τῶι πατρίωι νόμωι, καὶ ἐκαλλιέρει.", "st": "7.8.5"}, {"sp": "N", "t": "καὶ ταύτηι τῆι ἡμέραι ἀφικνεῖται Βίων καὶ Ναυσικλείδης χρήματα δώσοντες τῶι στρατεύματι, καὶ ξενοῦνται τῶι Ξενοφῶντι καὶ ἵππον ὃν ἐν Λαμψάκωι ἀπέδοτο πεντήκοντα δαρεικῶν, ὑποπτεύοντες αὐτὸν δι᾽ ἔνδειαν πεπρακέναι, ὅτι ἤκουον αὐτὸν ἥδεσθαι τῶι ἵππωι, λυσάμενοι ἀπέδοσαν καὶ τὴν τιμὴν οὐκ ἤθελον ἀπολαβεῖν.", "st": "7.8.6"}, {"sp": "N", "t": "ἐντεῦθεν ἐπορεύοντο διὰ τῆς Τρωιάδος, καὶ ὑπερβάντες τὴν Ἴδην εἰς Ἄντανδρον ἀφικνοῦνται πρῶτον, εἶτα παρὰ θάλατταν πορευόμενοι [τῆς Ἀσίας] εἰς Θήβης πεδίον.", "st": "7.8.7"}, {"sp": "N", "t": "ἐντεῦθεν δι᾽ Ἀδραμυττίου καὶ Κερτωνοῦ ὁδεύσαντες εἰς Καΐκου πεδίον ἐλθόντες Πέργαμον καταλαμβάνουσι τῆς Μυσίας. ἐνταῦθα δὴ ξενοῦται Ξενοφῶν Ἑλλάδι τῆι Γογγύλου τοῦ Ἐρετριέως γυναικὶ καὶ Γοργίωνος καὶ Γογγύλου μητρί.", "st": "7.8.8"}, {"sp": "N", "t": "αὕτη δ᾽ αὐτῶι φράζει ὅτι Ἀσιδάτης ἐστὶν ἐν τῶι πεδίωι ἀνὴρ Πέρσης· τοῦτον ἔφη αὐτόν, εἰ ἔλθοι τῆς νυκτὸς σὺν τριακοσίοις ἀνδράσι, λαβεῖν ἂν καὶ αὐτὸν καὶ γυναῖκα καὶ παῖδας καὶ τὰ χρήματα· εἶναι δὲ πολλά. ταῦτα δὲ καθηγησομένους ἔπεμψε τόν τε αὑτῆς ἀνεψιὸν καὶ Δαφναγόραν, ὃν περὶ πλείστου ἐποιεῖτο.", "st": "7.8.9"}, {"sp": "N", "t": "ἔχων οὖν ὁ Ξενοφῶν τούτους παρ᾽ ἑαυτῶι ἐθύετο. καὶ Βασίας ὁ Ἠλεῖος μάντις παρὼν εἶπεν ὅτι κάλλιστα εἴη τὰ ἱερὰ αὐτῶι καὶ ὁ ἀνὴρ ἁλώσιμος εἴη.", "st": "7.8.10"}, {"sp": "N", "t": "δειπνήσας οὖν ἐπορεύετο τούς τε λοχαγοὺς τοὺς μάλιστα φίλους λαβὼν καὶ .. πιστοὺς γεγενημένους διὰ παντός, ὅπως εὖ ποιήσαι αὐτούς. συνεξέρχονται δὲ αὐτῶι καὶ ἄλλοι βιασάμενοι εἰς ἑξακοσίους· οἱ δὲ λοχαγοὶ ἀπήλαυνον, ἵνα μὴ μεταδοῖεν τὸ μέρος, ὡς ἑτοίμων δὴ χρημάτων.", "st": "7.8.11"}, {"sp": "N", "t": "ἐπεὶ δὲ ἀφίκοντο περὶ μέσας νύκτας, τὰ μὲν πέριξ ὄντα ἀνδράποδα τῆς τύρσιος καὶ χρήματα τὰ πλεῖστα ἀπέδρα αὐτοὺς παραμελοῦντας, ὡς τὸν Ἀσιδάτην αὐτὸν λάβοιεν καὶ τὰ ἐκείνου.", "st": "7.8.12"}, {"sp": "N", "t": "πυργομαχοῦντες δὲ ἐπεὶ οὐκ ἐδύναντο λαβεῖν τὴν τύρσιν (ὑψηλὴ γὰρ ἦν καὶ μεγάλη καὶ προμαχεῶνας καὶ ἄνδρας πολλοὺς καὶ μαχίμους ἔχουσα), διορύττειν ἐπεχείρησαν τὸν πύργον.", "st": "7.8.13"}, {"sp": "N", "t": "ὁ δὲ τοῖχος ἦν ἐπ᾽ ὀκτὼ πλίνθων γηίνων τὸ εὖρος. ἅμα δὲ τῆι ἡμέραι διωρώρυκτο· καὶ ὡς τὸ πρῶτον διεφάνη, ἐπάταξεν ἔνδοθεν βουπόρωι τις ὀβελίσκωι διαμπερὲς τὸν μηρὸν τοῦ ἐγγυτάτω· τὸ δὲ λοιπὸν ἐκτοξεύοντες ἐποίουν μηδὲ παριέναι ἔτι ἀσφαλὲς εἶναι.", "st": "7.8.14"}, {"sp": "N", "t": "κεκραγότων δὲ αὐτῶν καὶ πυρσευόντων ἐκβοηθοῦσιν Ἰταμένης μὲν ἔχων τὴν ἑαυτοῦ δύναμιν, ἐκ Κομανίας δὲ ὁπλῖται Ἀσσύριοι καὶ Ὑρκάνιοι ἱππεῖς καὶ οὗτοι βασιλέως μισθοφόροι ὡς ὀγδοήκοντα, καὶ ἄλλοι πελτασταὶ εἰς ὀκτακοσίους, ἄλλοι δ᾽ ἐκ Παρθενίου, ἄλλοι δ᾽ ἐξ Ἀπολλωνίας καὶ ἐκ τῶν πλησίον χωρίων καὶ ἱππεῖς.", "st": "7.8.15"}, {"sp": "N", "t": "ἐνταῦθα δὴ ὥρα ἦν σκοπεῖν πῶς ἔσται ἡ ἄφοδος· καὶ λαβόντες ὅσοι ἦσαν βόες καὶ πρόβατα ἤλαυνον καὶ ἀνδράποδα ἐντὸς πλαισίου ποιησάμενοι, οὐ τοῖς χρήμασιν ἔτι προσέχοντες τὸν νοῦν, ἀλλὰ μὴ φυγὴ εἴη ἡ ἄφοδος, εἰ καταλιπόντες τὰ χρήματα ἀπίοιεν, καὶ οἵ τε πολέμιοι θρασύτεροι εἶεν καὶ οἱ στρατιῶται ἀθυμότεροι· νῦν δὲ ἀπῆισαν ὡς περὶ τῶν χρημάτων μαχούμενοι.", "st": "7.8.16"}, {"sp": "N", "t": "ἐπεὶ δὲ ἑώρα Γογγύλος ὀλίγους μὲν τοὺς Ἕλληνας, πολλοὺς δὲ τοὺς ἐπικειμένους, ἐξέρχεται καὶ αὐτὸς βίαι τῆς μητρὸς ἔχων τὴν ἑαυτοῦ δύναμιν, βουλόμενος μετασχεῖν τοῦ ἔργου· συνεβοήθει δὲ καὶ Προκλῆς ἐξ Ἁλισάρνης καὶ Τευθρανίας ὁ ἀπὸ Δαμαράτου.", "st": "7.8.17"}, {"sp": "N", "t": "οἱ δὲ περὶ Ξενοφῶντα ἐπεὶ πάνυ ἤδη ἐπιέζοντο ὑπὸ τῶν τοξευμάτων καὶ σφενδονῶν, πορευόμενοι κύκλωι, ὅπως τὰ ὅπλα ἔχοιεν πρὸ τῶν τοξευμάτων, μόλις διαβαίνουσι τὸν Κάρκασον ποταμόν, τετρωμένοι ἐγγὺς οἱ ἡμίσεις.", "st": "7.8.18"}, {"sp": "N", "t": "ἐνταῦθα δὲ Ἀγασίας ὁ Στυμφάλιος λοχαγὸς τιτρώσκεται, τὸν πάντα χρόνον μαχόμενος πρὸς τοὺς πολεμίους. καὶ διασώιζονται ἀνδράποδα ὡς διακόσια ἔχοντες καὶ πρόβατα ὅσον θύματα.", "st": "7.8.19"}, {"sp": "N", "t": "τῆι δὲ ὑστεραίαι θυσάμενος ὁ Ξενοφῶν ἐξάγει νύκτωρ πᾶν τὸ στράτευμα, ὅπως ὅτι μακροτάτην ἔλθοι τῆς Λυδίας, εἰς τὸ μὴ διὰ τὸ ἐγγὺς εἶναι φοβεῖσθαι, ἀλλ᾽ ἀφυλακτεῖν.", "st": "7.8.20"}, {"sp": "N", "t": "ὁ δὲ Ἀσιδάτης ἀκούσας ὅτι πάλιν ἐπ᾽ αὐτὸν τεθυμένος εἴη ὁ Ξενοφῶν καὶ παντὶ τῶι στρατεύματι ἥξοι, ἐξαυλίζεται εἰς κώμας ὑπὸ τὸ Παρθένιον πόλισμα ἐχούσας.", "st": "7.8.21"}, {"sp": "N", "t": "ἐνταῦθα οἱ περὶ Ξενοφῶντα συντυγχάνουσιν αὐτῶι καὶ λαμβάνουσιν αὐτὸν καὶ γυναῖκα καὶ παῖδας καὶ τοὺς ἵππους καὶ πάντα τὰ ὄντα· καὶ οὕτω τὰ πρότερα ἱερὰ ἀπέβη.", "st": "7.8.22"}, {"sp": "N", "t": "ἔπειτα πάλιν ἀφικνοῦνται εἰς Πέργαμον. ἐνταῦθα τὸν θεὸν ἠσπάσατο Ξενοφῶν· συνέπραττον γὰρ καὶ οἱ Λάκωνες καὶ οἱ λοχαγοὶ καὶ οἱ ἄλλοι στρατηγοὶ καὶ οἱ στρατιῶται ὥστ᾽ ἐξαίρετα λαβεῖν καὶ ἵππους καὶ ζεύγη καὶ τἆλλα· ὥστε ἱκανὸν εἶναι καὶ ἄλλον ἤδη εὖ ποιεῖν.", "st": "7.8.23"}, {"sp": "N", "t": "ἐν τούτωι Θίβρων παραγενόμενος παρέλαβε τὸ στράτευμα καὶ συμμείξας τῶι ἄλλωι Ἑλληνικῶι ἐπολέμει πρὸς Τισσαφέρνην καὶ Φαρνάβαζον.", "st": "7.8.24"}, {"sp": "N", "t": "[ἄρχοντες δὲ οἵδε τῆς βασιλέως χώρας ὅσην ἐπήλθομεν. Λυδίας Ἀρτίμας, Φρυγίας Ἀρτακάμας, Λυκαονίας καὶ Καππαδοκίας Μιθραδάτης, Κιλικίας Συέννεσις, Φοινίκης καὶ Ἀραβίας Δέρνης, Συρίας καὶ Ἀσσυρίας Βέλεσυς, Βαβυλῶνος ῾Ρωπάρας, Μηδίας Ἀρβάκας, Φασιανῶν καὶ Ἑσπεριτῶν Τιρίβαζος· Καρδοῦχοι δὲ καὶ Χάλυβες καὶ Χαλδαῖοι καὶ Μάκρωνες καὶ Κόλχοι καὶ Μοσσύνοικοι καὶ Κοῖτοι καὶ Τιβαρηνοὶ αὐτόνομοι· Παφλαγονίας Κορύλας, Βιθυνῶν Φαρνάβαζος, τῶν ἐν Εὐρώπηι Θραικῶν Σεύθης.", "st": "7.8.25"}, {"sp": "N", "t": "ἀριθμὸς συμπάσης τῆς ὁδοῦ τῆς ἀναβάσεως καὶ καταβάσεως σταθμοὶ διακόσιοι δεκαπέντε, παρασάγγαι χίλιοι ἑκατὸν πεντήκοντα, στάδια τρισμύρια τετρακισχίλια διακόσια πεντήκοντα πέντε. χρόνου πλῆθος τῆς ἀναβάσεως καὶ καταβάσεως ἐνιαυτὸς καὶ τρεῖς μῆνες.]", "st": "7.8.26"}],[]);})();
